\begin{lemma}
\label{lemmarestriction}
For every pair of directed sets $P \subseteq P' \subseteq {}^{\omega_n} \omega$ and domains $E \subseteq E' \subseteq \omega_n \times \omega$, if $\Psi = \{ \psi_{\vec{f}} : E' \to \mathbb{Z} \mid \vec{f} \in P'^{(k)} \} $ trivializes $\Phi$, then $(\Psi \restriction P^{(k)}) \restriction \restriction E$ trivializes $(\Phi \restriction P^{(k)}) \restriction \restriction E$.
\end{lemma}


