\paragraph{\bf Notations.} 
Throughout the paper we will adopt the following notational convention. First, $p$ will denote a fixed prime. To make the notations transparent, we will always denote free groups by capital Latin letters in a Roman font  and free pro-$p$ groups by capital Latin letters in a boldface font, with $F$ and $\propF{p}$ being the default choices. Occasionally we will make statements which covers both free pro-$p$ and free groups, and in that case we will use letters in a calligraphic font (usually $\apf{F}$). 


\section{Basic results on commensurators} \label{sec-prelim-general}

\subsection{The commensurator of a topological group}\label{subsec-profinite-commens}

We start by defining the commensurator $\Comm(G)$ for a topological group $G$. 

\begin{Definition} \label{defin-local-iso}
Let $G$ be a topological group.
	\begin{itemize}
		\item A {\it virtual isomorphism of $G$} is a topological group isomorphism $f : U \to V $ where $U,V$ are both finite index open subgroups of $G$. We also say that the triple $(f,U,V)$ is a virtual isomorphism.
		\item Given two virtual isomorphisms $f_i : U_i \to V_i $, $i=1,2$, their composition is the virtual isomorphism
		\[
		f_1 \circ f_2: f^{-1}_2(V_2 \cap U_1) \to f_1(V_2 \cap U_1 )\mbox{ defined by } x \mapsto f_1(f_2(x)).
		\]
		\item Two virtual isomorphisms are declared equivalent if they coincide on some finite index open subgroup. 
		\item The equivalence class of a virtual isomorphism $f$ will be denoted by $[f]$.
	\end{itemize}
\end{Definition}

Virtual isomorphisms modulo this equivalence form a group with operation defined by $[f_1][f_2] = [f_1 \circ f_2]$. This group is called
the {\it commensurator of $G$} and will be denoted by $\Lg(G)$.  

If $H$ is a finite index open subgroup of $G$, then every virtual isomorphism of $H$ is a virtual isomorphism of $G$, and the induced homomorphism $\Lg(H) \to \Lg(G)$ is an isomorphism, so we can identify $\Lg(H)$ with $\Lg(G)$. More generally, if two topological groups $G_1$ and $G_2$ are \emph{virtually isomorphic}\footnote{We warn the reader that what we call 'virtually isomorphic' is sometimes called 'abstractly commensurable' or just 'commensurable'. Here we will use the word `commensurable' only in the situations when both groups are subgroups of the same group -- see Definition~\ref{def-commensurated}.}, 
meaning that they admit topologically isomorphic finite index open subgroups, then $\Lg(G_1)$ and $\Lg(G_2)$ are isomorphic. 


\begin{Remark} \label{rem:openfiniteindex}
In this paper we will only consider the groups $\Comm(G)$ in the case where all open subgroups of $G$ are of finite index.
\end{Remark}

We will use the following terminology. 

\begin{Definition}\label{def:quasivirtualcenter}
$\empty$

\begin{itemize}
\item[(a)] Let $\Gama$ be an abstract group. The {\it virtual center} $\VZ(\Gama)$ is the set of elements $g\in \Gama$ which centralize a finite index subgroup of $G$ \footnote{Also called FC-center. Here we adopt the terminology `virtual center' as we think of this set as the elements that act trivially by conjugation on a finite index subgroup, rather than the elements whose conjugacy class is finite.
}. 
\item[(b)] Now let $G$ be a topological group. The {\it quasi-center} $\QZ(G)$ is the set of elements $g \in G$ which centralize an open subgroup of $G$.
\end{itemize}
\end{Definition}
Clearly, $\VZ(\Gama)$ is a characteristic subgroup of an abstract group $\Gama$. Likewise $\QZ(G)$ is a topologically characteristic subgroup of a topological group $G$ (which need not be closed). For a general topological group $G$ neither of the subgroups $\VZ(G)$ and $\QZ(G)$ must contain the other, but for instance $\QZ(G)=\VZ(G)$ if either $G$ is an abstract group with profinite topology or a profinite group. 

\skv
Let $G$ be a topological group. Given $g \in G$, we denote by $\iotta_g: G \rightarrow G$ the left conjugation by $g$, that is,
$\iotta_g(x)=gxg^{-1}$. The map $\iotta: G \to \Lg(G)$ given by $\iotta(g)= [\iotta_g]$ is a group homomorphism. In general, the kernel
of $\iotta$ is $\VZ(G)\cap \QZ(G)$, the intersection of the virtual center and the quasi-center. However, we will only consider
$\Lg(G)$ when every open subgroup of $G$ has finite index in $G$, in which case $\QZ(G)\subseteq \VZ(G)$ and therefore
$$\Ker(\iotta)=\QZ(G).$$
For the rest of the paper we make the standing assumption that when $\QZ(G)$ is trivial, we will 
usually identify $G$ with $\iotta(G)$ and thus view $G$ as a subgroup of its commensurator $\Lg(G)$. 

\begin{Definition} \label{def-commensurated}
		Two subgroups $H,K$ of a group $G$ will be called  \textit{commensurable} if their intersection $H \cap K$ has finite index in both $H$ and $K$. A subgroup $H$ of $G$ is  \textit{commensurated} in $G$ if any two $G$-conjugates of $H$ are commensurable. 
\end{Definition}

We will be frequently using this terminology when the group $G$ is equipped with a topology. We stress that in such situations we are not requiring any extra hypotheses on $H,K$ and $H \cap K$ with respect to the ambient topology on $G$.

\begin{Lemma} \label{lem-G-commens-CommG}
Let $G$ be a topological group and $f: U \to V$ a virtual isomorphism of $G$. 
Then for any $[f]\in\Lg(G)$ we have $[f] \iotta(U) [f]^{-1} = \iotta(V)$. In particular, $i(G)$ is commensurated in $\Lg(G)$.
\end{Lemma}

\begin{proof}
The equality $[f] \iotta(U) [f]^{-1} = \iotta(V)$ is a consequence of the definitions. 
That $\iotta(G)$ is commensurated follows because $\iotta(U)$ and $\iotta(V)$ both have finite index in $\iotta(G)$. 
\end{proof}

There is a natural way to equip $\Lg(G)$ with a group topology, which relies on the following classical principle (see e.g. \cite[III.2 Proposition 1]{Bourbaki_III_1-4}):


\begin{Proposition}
	\label{prop:topbase}
	Let $\Gama$ be a group and  $\mathcal{O}$ a collection of subgroups of $\Gama$ such that
	\begin{enumerate}
		\item any finite intersection of elements of $\mathcal{O}$ contains an element of $\mathcal{O}$;
		\item for every $g\in \Gama$ and $O_1\in \mathcal{O}$, there is $O_2\in \mathcal{O}$ such that $O_2 \subseteq gO_1g^{-1}$. 
	\end{enumerate}
	Then there is a unique group topology $\tau$ on $\Gama$ such that $\mathcal{O}$ is a base of neighborhoods of the identity for $\tau$. Moreover, $\tau$ is Hausdorff if and only if the intersection of all subgroups in $\mathcal O$ is trivial.
\end{Proposition}

\begin{Proposition}\label{prop-topo-germs}
	Let $G$ be a topological group.  Then $\Lg(G)$ admits a unique group topology $\tau$ such that there is a base $\mathcal{O}$ of neighborhoods of the identity formed by subgroups of the form $\iotta(U)$, for $U$ a finite index open subgroup of $G$.  With respect to $\tau$, the homomorphism $\iotta: G \to \Lg(G)$ is continuous and open.
\end{Proposition}


\begin{proof}
To establish the existence and uniqueness of $\tau$ it is enough to check that $\mathcal{O}$ has property (2) from Proposition~\ref{prop:topbase}. Given $g \in \Lg(G)$ and an open subgroup $W$ in $G$, we want to show that $g\iotta(W)g^{-1}$ contains some element of $\mathcal{O}$. Choose a virtual isomorphism $f: U \to V$ of $G$ such that $g = [f]$ and $U \subseteq W$. 
Then $g\,\iotta(W)g^{-1} \supseteq g\,\iotta(U)g^{-1} = \iotta(V)$ where the equality holds by Lemma \ref{lem-G-commens-CommG}.  
\end{proof}


 For the rest of the paper we always consider $\Lg(G)$  being equipped with the topology from Proposition~\ref{prop-topo-germs}, unless explicitly mentioned otherwise.\footnote{This topology is called the strong topology in \cite{BEW}, but we will not be using that terminology.}
\skv

The commensurator $\Lg(G)$ satisfies the following universal property. For simplicity, we state it in the special case where $G$ has trivial quasi-center:


\begin{Proposition}[Universal property of $\Lg(G)$] \label{prop-univ-Comm}
Let $G$ be a topological group with trivial quasi-center. Then $G$ is an open commensurated subgroup of $\Lg(G)$. Conversely, if $L$ is a topological group into which $G$ embeds as an open commensurated subgroup, then there is a  homomorphism $\psi: L \to \Lg(G)$. Moreover, $\psi$ is  continuous, $\psi$ has open image, and $\ker(\psi) = \QZ(L)$, which is a discrete normal subgroup of $L$. 
\end{Proposition}

\begin{proof}
The first statement follows from the previous discussion. Now suppose $L$ is a topological group into which $G$  embeds as an open commensurated subgroup. For  every $h \in L$, the subgroups $h^{-1}Gh \cap G$ and $G \cap hGh^{-1}$ are finite index open subgroups of $G$, and the conjugation by $h$ induces a virtual isomorphism $h^{-1}Gh \cap G \to G \cap hGh^{-1}$ of $G$. This defines a homomorphism $\psi : L \to \Lg(G)$, whose restriction to $G$ is equal to $\iotta: G \to \Lg(G)$. Since $G$ is open in $L$, $\psi $ is continuous, and  $\psi(L)$ is open since it contains $i(G)$. An element of $h \in L$ belongs to $\ker(\psi)$ if and only if there exists an open subgroup of $G$ with which $h$ commutes, which precisely means that $h \in \QZ(L)$. Since $\QZ(L) \cap G = \QZ(G) = 1$, the group $\QZ(L) $ is necessarily discrete. 
\end{proof}



Given a finite index open subgroup $U$ of a topological group $G$, any automorphism of $U$ can be viewed as a virtual isomorphism of $G$.  Thus we have a natural homomorphism $\iota_U: \Aut(U) \rightarrow \Lg(G)$; we denote its image by $\uAut(U)$.

\begin{Definition}
We will say that $G$ is {\it $\Aut$-$\Comm$ injective} if the map $\iota_U$ is injective for every open subgroup $U$ of $G$.
\end{Definition}

If $G$ is $\Aut$-$\Comm$ injective, we will simplify notation again and write $\Aut(U)$ instead of $\uAut(U)$, thereby
identifying $\Aut(U)$ with a subgroup of $\Lg(G)$.
The following two simple observations provide two natural conditions on $G$, either of which implies that $G$ is $\Aut$-$\Comm$ injective
and in fact has a slightly stronger property.


\begin{Lemma}
	\label{lem-BEW}
	Let $G$ be a topological group with  trivial quasi-center. Suppose $f: U \to V$ is an isomorphism between two open subgroups of $G$ such that $f$ is the identity on some open subgroup of $G$. Then $U=V$ and $f$ is the identity map. In particular, $G$ is $\Aut$-$\Comm$ injective.
\end{Lemma}

\begin{proof}
When $G$ is profinite, this was proved in  \cite[Proposition~2.6]{BEW}. The proof for general topological groups is identical.
\end{proof}

\begin{Lemma} \label{lem-unique-root}
	Let $G$ be a topological group with the unique root property (if $g^n=h^n$ for some $g,h\in G$ and $n \geq 1$, then $g=h$). Suppose $f: U \to V$ is an isomorphism between two finite index open subgroups of $G$ such that $f$ is the identity on some open subgroup of $G$. Then $U=V$ and $f$ is the identity map. In particular, $G$ is $\Aut$-$\Comm$ injective.
\end{Lemma}

\begin{proof}
This was proved for abstract groups in  \cite{Barth-Bogo}. The same proof applies to topological groups without any changes.
\end{proof}


\begin{Remark}\label{rem:valueofvirtulauto}
If $G$ satisfies the conclusion of Lemma~\ref{lem-BEW}, the following more general property automatically holds: if $f: U \to V$ is a virtual isomorphism of $G$ and $f': U' \to V'$ is a virtual isomorphism of $G$ that is equivalent to $f$, then the value of $f'$ at any point is determined by $f$; in particular, $f(g) = f'(g)$ for all $g \in U \cap U'$.
\end{Remark}

Our next lemma provides some useful information on the subgroup structure of $\Lg(G)$ in the case where $G$ has trivial quasi-center. Of particular importance to us is part (\ref{item-Comm-local-normal}) which will be the starting observation of many of our simplicity theorems.


\begin{Lemma} \label{lem-Comm-trivialQZ}
	Let $G$ be a topological group with trivial quasi-center. The following hold: 
\begin{enumerate}
		\item  \label{item-Comm-trivial-QZ} Any open subgroup of $\Lg(G)$ has trivial  quasi-center.
		\item \label{item-Comm-local-normal} Let $N$ be a non-trivial subgroup  of $\Lg(G)$ whose normalizer in $\Lg(G)$ is open. 
Then $N \cap G$ is non-trivial. 
	\end{enumerate} 
\end{Lemma}


\begin{proof}
(\ref{item-Comm-trivial-QZ}) The entire $\Lg(G)$ has trivial quasi-center by \cite[Proposition 3.2(c)]{BEW}. On the other hand,
if $U$ is an open subgroup of a topological group $L$, then $\QZ(U)=\QZ(L)\cap U$, so (\ref{item-Comm-trivial-QZ}) follows.
\skv

 (\ref{item-Comm-local-normal}) In this proof, to avoid confusion, we will not identify $G$ with $\iotta(G)$, so our goal is to show
 that $N\cap \iotta(G)$ is non-trivial. Let $[\psi]$ be a non-trivial element of $N$. By our hypotheses there exists an open subgroup $U$ of $G$ such that
$\psi$ is defined on $U$ and $\iotta(U)$ normalizes $N$. Since $\QZ(G)=\{1\}$, the restriction of $\psi$ to $U$ is non-trivial
by Lemma~\ref{lem-BEW}, so we can find $g\in U$ such that $\psi(g)\neq g$.
 Then $\iotta_{\psi(g)g^{-1}}=\iotta_{\psi(g)}\iotta_g^{-1}=\psi \iotta_g \psi^{-1}\iotta_g^{-1}=\psi\cdot (\iotta_g \psi^{-1}\iotta_g^{-1})$ is a non-trivial element which lies in both $N$ and $\iotta(G)$.
\end{proof}

Now suppose that $\tau_1$ and $\tau_2$ are two group topologies on $G$ such that $\tau_1 \subseteq \tau_2$. Every virtual isomorphism $f$ of
the topological group $(G,\tau_1)$ is also a virtual isomorphism of $(G,\tau_2)$, and $f_1 \sim f_2$ for $\tau_1$ 
implies $f_1 \sim f_2$ for $\tau_2$. Thus there is an induced map $\Lg((G,\tau_1)) \to \Lg((G,\tau_2))$, which is clearly a  homomorphism.

\begin{Lemma} \label{lem-germ-compare-topologies}
Suppose that $(G,\tau_2)$ has trivial quasi-center. Then the homomorphism $\Lg((G,\tau_1)) \to \Lg((G,\tau_2))$ is injective.
\end{Lemma}

\begin{proof}
	If $f : U  \to V$ is a virtual isomorphism of $(G,\tau_1)$ whose image in $\Lg((G,\tau_2))$ is trivial, then Lemma \ref{lem-BEW} asserts 
that $U=V$ and $f$ is the identity map, so $f$ has trivial image in $\Lg((G,\tau_1))$ as well. 
\end{proof}

\subsection{The commensurator and the $p$-commensurator of an abstract group}
Let $\Gama$ be an abstract group. We start by recalling the definitions of the profinite and pro-$p$ topologies on $\Gama$. 
Each of these turns $\Gama$ into a topological group. 

\begin{itemize}
\item The profinite topology $\tau_{\prof}$ on $\Gama$  is defined by declaring that the finite index normal subgroups of $\Gama$ form a base of neighborhoods of the identity. Since every finite index subgroup contains a finite index normal subgroup, the open subgroups
in the profinite topology are precisely the finite index subgroups.

\item If $p$  is a prime number, the  pro-$p$ topology $\tau_p$ on $\Gama$ is defined by declaring that the normal subgroups of $\Gama$ of finite $p$-power index form a base of neighborhoods of the identity. We say that a subgroup of $\Gama$ is {\it $p$-open} or {\it $p$-closed} if it is open or closed in the pro-$p$ topology, respectively. It is well known that $p$-open subgroups are precisely subnormal subgroups of $p$-power index.
\end{itemize}	



\begin{Definition}  \label{def-Comm-Commp}
	Let $\Gama$ be an abstract group.
\begin{itemize}
\item The {\it commensurator} of $\Gama$ denoted by $\Comm(\Gama)$ is the commensurator of the topological group $(\Gama, \tau_{prof})$, that is, $\Comm(\Gama)= \Lg((\Gama,\tau_{\prof}))$. 
\item The {\it $p$-commensurator} of $\Gama$ denoted by $\Comm_p(\Gama)$ is the commensurator of the topological group $(\Gama, \tau_{p})$, that is,  $\Comm_p(\Gama)= \Lg((\Gama,\tau_p))$.
\end{itemize}
\end{Definition}


	More explicitly, \begin{itemize}
		\item 	elements of $\Comm(\Gama)$ are  isomorphisms between finite index subgroups of $\Gama$,  modulo being equal on a finite index subgroup. The kernel of $i: \Gama \to \Comm(\Gama)$ is $\QZ((\Gama,\tau_{prof}))=\VZ(\Gama)$, the virtual center of $\Gama$. 

		\item elements of $\Comm_p(\Gama)$ are isomorphisms between $p$-open subgroups of $\Gama$,  modulo being equal on a $p$-open subgroup. The kernel of $i: \Gama \to \Comm_p(\Gama)$ is the set of elements which centralize a $p$-open subgroup of $\Gama$. 
	\end{itemize}

In what follows we always endow the groups $\Comm(\Gama)$ and $\Comm_p(\Gama)$ with the topology from Proposition \ref{prop-topo-germs}.  By definition the pro-$p$ topology is coarser than the profinite topology, so applying Lemma \ref{lem-germ-compare-topologies} 
to the topological group $(\Gama,\tau_{prof})$ we obtain the following:

\begin{Lemma}
	Suppose that an abstract group $\Gama$ has trivial virtual center. Then the natural homomorphism $\Comm_p(\Gama) \to \Comm(\Gama)$ is injective. 
\end{Lemma}


Again let  $\Gama$ be an abstract group and $p$ a prime number. We denote by $\widehat{\Gama}_p$  the pro-$p$ completion of $\Gama$; thus we have a  completion map $\Gama \rightarrow \widehat{\Gama}_p$, which is injective precisely when $\Gama$ is residually-$p$ 
(by definition this holds if elements of $\Gama$ can be separated by homomorphisms to finite $p$-groups).


 Part (3) of the following lemma establishes a natural map from the $p$-commensurator of an abstract group to the commensurator of its pro-$p$ completion, {which will be used repeatedly in the paper.} 

\begin{Lemma} \label{lem-localiso-extends-completion}
Let $\Gama$ be an abstract group.
\begin{enumerate}
\item  If $H$ is a $p$-open subgroup of $\Gama$, then the restriction to $H$ of the pro-$p$ topology on $\Gama$ is equal to the pro-$p$ topology on $H$. 
\item Given an injective  homomorphism $\theta: H \to \Gama$ with $p$-open image,  $\theta$ extends to a continuous injective open homomorphism $\widehat{\theta}_p:  \widehat{H}_p \to  \widehat{\Gama}_p$.
\item  There is a continuous  homomorphism $\phi: \Comm_p(\Gama) \to \Comm(\widehat{\Gama}_p)$ given by $\phi([f]) = [\widehat{f}_p]$.
\end{enumerate}
\end{Lemma}

\begin{proof}
For (1) see \cite[Lemma 3.1.4(a)]{RZ-book}. Part (2) is a standard construction, see \cite[\S~3.2]{RZ-book}. The fact that $\widehat{\theta}_p$ is injective follows from part (1) -- see \cite[Lemma 3.2.6]{RZ-book}.  In particular, if $H$ is a $p$-open subgroup of $\Gama$ and $\theta: H \to \Gama$ is the inclusion map, then we may regard $\widehat{H}_p$ as an open subgroup of $\widehat{\Gama}_p$ via the map $\widehat{\theta}_p$.
\skv

(3) First let us explain why the map $\phi$ given by $\phi([f]) = [\widehat{f}_p]$ is well defined. For this,
it is enough to note that when $f: H \rightarrow K$ is a virtual isomorphism of $\Gama$ in the pro-$p$ topology and $g$ is the restriction of $f$ to some $p$-open subgroup $L$ of $H$, then $\widehat{g}_p$ is given by the restriction of $\widehat{f}_p$ to $\widehat{L}_p$ (regarding $\widehat{L}_p$ as an open subgroup of $\widehat{H}_p$ as in the previous paragraph).  

Next we show that $\phi$ is a  homomorphism.
Given $f,g \in \Comm_p(\Gama)$, there is an identity neighborhood $\propU{p}$ in $\widehat{\Gama}_p$ on which the composition $\widehat{f}_p\widehat{g}^{-1}_p$ is defined, and for all $x \in \Gama \cap \propU{p}$ we have $\widehat{f}_p\widehat{g}^{-1}_p(x) = \widehat{(fg^{-1})}_p(x)$; by continuity, the same equation holds for all $x \in U$, and hence $[\widehat{f}_p][\widehat{g}_p]^{-1} = [\widehat{(fg^{-1})}_p]$, showing that $\phi$ is a  homomorphism.  

Finally, note that $\{ \widehat{H}_p : H \text{ is a $p$-open subgroup of }G\}$ is a base of neighborhoods of the identity in $\Comm(\widehat{\Gama}_p)$, and for each $p$-open subgroup $H$ of $\Gama$, the preimage $\phi^{-1}(\widehat{H}_p)$ is an open subgroup of $\Comm_p(\Gama)$ since it contains $H$. It follows that $\phi$ is continuous.
\end{proof}

In particular, Lemma~\ref{lem-localiso-extends-completion}(1) ensures that for a $p$-open subgroup $H$ of $\Gama$, we have $\Comm_p(H) = \Comm_p(\Gama)$. The same is of course true for the profinite topology: if $H$ is a finite index subgroup of $\Gama$, then the profinite topology on $H$ agrees with the restriction to $H$ of the profinite topology on $\Gama$.  We will use these facts frequently without further mention.

 We remark that an equivalent way to say that two subgroups $H, K$ of a group $\Gama$ are commensurable (Definition \ref{def-commensurated}) is that $H \cap K$ is open in the profinite topology on $H$ and on $K$. Note that this reformulation involves the profinite topologies on $H$ and $K$, and not the profinite topology on $G$. We make an analogous definition for the pro-$p$ topology. 

 \begin{Definition}
	Two subgroups $H, K$ of a group $\Gama$ are {\it $p$-commensurable} if $H \cap K$ is a $p$-open subgroup in  $H$ and $K$. This is an equivalence relation. A subgroup $L$ of $\Gama$ is {\it $p$-commensurated} if all the $\Gama$-conjugates of $L$ are $p$-commensurable with each other. 
\end{Definition}

\begin{Lemma} \label{lem-im-p-commens}
The image $i(\Gama)$ of $\Gama$ in $\Comm_p(\Gama)$ is a $p$-commensurated subgroup of $\Comm_p(\Gama)$. 
\end{Lemma}

\begin{proof}
Let $f: U \to V$ be an isomorphism between two $p$-open subgroups of $G$. By Lemma \ref{lem-G-commens-CommG} we have $[f] \iotta(U) [f]^{-1} = \iotta(V)$, and the subgroups $\iotta(U)$ are $\iotta(V)$ are $p$-commensurable since they are both $p$-open in $i(\Gama)$. 
\end{proof}


\subsection{Subgroups of the commensurator generated by automorphisms} \label{subsec-def-AComm}

Let $G$ be a topological group. Recall that for any finite index open subgroup $U$ of $G$ we denote by $\uAut(U)$
the canonical image of $\Aut(U)$ in $\Lg(G)$. We define $\AComm(G)$ to be the subgroup of $\Comm(G)$ generated
by all subgroups $\uAut(U)$.

If $\Gama$ is an abstract group,  we define 
$$\AComm(\Gama)=\AComm((\Gama,\tau_{prof})) \mbox{ and }\AComm_p(\Gama)=\AComm((\Gama,\tau_p)).$$
More explicitly, 
\begin{itemize}
\item $\AComm(\Gama)$ is the subgroup of $\Comm(\Gama)$ generated by $\uAut(H)$ where $H$ ranges over all finite index subgroups of $\Gama$;
\item $\AComm_p(\Gama)$ is the subgroup of $\Comm_p(\Gama)$ generated by $\uAut(H)$ where $H$ ranges over all $p$-open subgroups of $\Gama$.
\end{itemize}

As we will show shortly (see Lemma~\ref{lemma:Aut_1} below and the remark after it), under mild additional assumptions on $G$, the group $\AComm(G)$ is normal in $\Comm(G)$ and only depends on the commensurability class of $G$.

\begin{Definition}
	A topological group $G$ is {\it characteristically based} if every finite index open subgroup of $G$ contains a finite index open (topologically) characteristic subgroup.  We say that $G$ is {\it hereditarily  characteristically based} (h.c.b.) if every finite index open subgroup of $G$ is  characteristically based.
\end{Definition}


\begin{Lemma}
\label{lem:hcb}
Any topological group that is topologically finitely generated is h.c.b.. In particular, the following groups are h.c.b.:
	\begin{enumerate}
		\item A finitely generated abstract group equipped with the profinite topology or pro-$p$ topology.
		\item A finitely generated profinite group.\footnote{As we will explain in section~\ref{sec-prelim-freegroups},
by a finitely generated profinite group, we mean a profinite group which is
topologically finitely generated.}
	\end{enumerate}
\end{Lemma}

\begin{proof}
Let $G$ be a topologically finitely generated group. By a standard argument $G$ contains only finitely many open subgroups of any given finite index. The intersection $G_n$ of all open subgroups of index $n$ is then a characteristic open subgroup, and by definition every finite index open subgroup contains $G_n$ for some $n$. Thus $G$ is characteristically based.
Further, by Schreier's subgroup lemma every finite index open subgroup of $G$ satisfies the same hypothesis, so in fact $G$ is h.c.b.
\end{proof}

\begin{Lemma}
	\label{lemma:Aut_1}
Let $G$ be a h.c.b. topological group. The following hold:
	\begin{itemize}
		\item[(a)] Let $U$ be any finite index open subgroup of $G$. Then $\AComm(U)=\AComm(G)$.
		\item[(b)] For any finite index open subgroup $U$ of $G$ and any $f\in \Comm(G)$ there exists a finite index open subgroup $Z$ of $G$ such that $$f\uAut(U)f^{-1}\subseteq \uAut(Z).$$ In particular, 
		$\AComm(G)$ is normal in $\Comm(G)$. 
	\end{itemize}

In particular, these conditions hold when $G$ is a finitely generated abstract group equipped with the profinite topology or pro-$p$ topology or when $G$ is a finitely generated profinite group.
\end{Lemma}


\begin{proof} 
(a) The inclusion $\AComm(U)\subseteq \AComm(G)$ holds simply because every finite index open subgroup of $U$ is also a finite index open subgroup of $G$. To prove the reverse inclusion we need to show that for every finite index open subgroup $V$ of $G$, the group
$\uAut(V)$ lies in $\AComm(U)$. Since $G$ is h.c.b., it has a finite index open subgroup $W$ such that $W\subseteq U\cap V$ and
$W$ is characteristic in $V$. The latter implies that $\uAut(V)\subseteq \uAut(W)$, and since $W\subseteq U$, we have 
$\uAut(W)\subseteq \AComm(U)$, so $\uAut(V)\subseteq \AComm(U)$, as desired.
\skv

(b) Take any finite index open subgroup $U$ of $G$ and $[\phi]\in \Comm(G)$. Since $G$ is h.c.b., it has a finite index open subgroup $W$ 
which is characteristic in $U$ and such that $\phi$ is defined on $W$. Let $Z=\phi(W)$. Then for any $\psi\in \Aut(U)$ we have
$$\phi\,\psi\phi^{-1}(Z)=(\phi\,\psi)(W)=\phi(W)=Z,$$
so $[\phi]\,\uAut(U)[\phi]^{-1}\subseteq \uAut(Z)$, as desired.
\end{proof}


\section{Preliminaries on free groups and their automorphisms.} \label{sec-prelim-freegroups}

This section is organized as follows. We will start with some basic properties of the automorphism groups
of free groups in subsection~\ref{subsec-free-groups-gen-aut}, followed by the discussion of some results on finite index subgroups
in free groups and their generating sets in subsection~\ref{subsect-free-abstract-subgroups}. After reviewing a few general facts about generation in profinite groups in 
subsection~\ref{subsec-prelim-pro-p}, in subsection~\ref{subsec-prelim-freeprop} we will state the analogues of some of the results from 
subsection~\ref{subsect-free-abstract-subgroups} for free pro-$p$ groups.  Finally, in subsection~\ref{subsec-prelim-auto} we will introduce a natural topology on the automorphism groups of profinite groups.
The discussion of the automorphism groups of free pro-$p$ groups will be deferred till subsection~\ref{subsec-generation-commfreeprop}. 



\subsection{The subgroup $\SAut(F)$ and Nielsen generators} \label{subsec-free-groups-gen-aut}

Let $\absF{}$ be a free group of rank $d>1$. The abelianization map $\absF{}\to \absF{}/[\absF{},\absF{}]\cong \dbZ^d$ induces a homomorphism $\pi:\Aut(\absF{})\to \Aut(\dbZ^d)\cong\GL_d(\dbZ)$, which is known to be surjective \cite[Proposition 4.4]{LS}. The special automorphism group $\SAut(\absF{})$ is defined by $$\SAut(\absF{})=\pi^{-1}(\SL_d(\dbZ)).$$
Since $\pi$ is surjective, we have $[\Aut(\absF{}):\SAut(\absF{})]=[\GL_d(\dbZ)):\SL_d(\dbZ))]=2$. 


It is well known that a subset $X$ of $F$ is a free generating set if and only
if $X$ generates $F$ and $|X|=d$. For brevity, we will refer to free generating sets as {\it bases} of $F$. Let $X = \left\lbrace x_1,\ldots,x_d \right\rbrace $ be a fixed basis of $\absF{}$. For $1\leq i\neq j\leq d$ define
$R_{ij},L_{ij}\in \Aut(F)$ by $R_{ij}(x_i)=x_i x_j$ and $R_{ij}(x_k)=x_k$ for $k \neq i$; and $L_{ij}(x_i)=x_j x_i$ and $L_{ij}(x_k)=x_k$ for $k \neq i$. The maps $R_{ij}$ and $L_{ij}$ are called {\it Nielsen transformations}. Clearly, $R_{ij},L_{ij}\in \SAut(F)$, and
it is a classical theorem of Nielsen~\cite{Ni} (see also \cite[\S~I.4]{LS})  that $\SAut(\absF{})$ is generated by the maps $R_{ij}$ and $L_{ij}$. 


Every permutation of $X$ defines an element of $\Aut(F)$. We denote by $\Sym(X)$ the corresponding subgroup of $\Aut(F)$ and by 
$\Alt(X) \subseteq \Sym(X)$ the subgroup consisting of even permutations. 

The following lemma collects some basic properties of $\SAut(\absF{})$.

\begin{Lemma} 
	\label{lem:absperfect}
	The following hold:	
	\begin{itemize}
		\item[(a)] $\Sym(X) \cap \SAut(\absF{}) = \Alt(X)$ . 
		\item[(b)] Assume that $\rk(F)\geq 3$. Then $\SAut(\absF{})$ is perfect and $[\Aut(\absF{}),\Aut(\absF{})]=\SAut(\absF{})$. 
	\end{itemize}
\end{Lemma}
\begin{proof} 
	(a) holds since the image
	of an element $\sigma$ of $ \Sym(X)$ in $\Aut(\absF{}/[\absF{},\absF{}])\cong \GL_d(\dbZ)$ is the permutation matrix $P_{\sigma}$ and
	$\det(P_{\sigma})=\mathrm{sgn}(\sigma)$.
	\skv
	(b) Let $d=\rk(\absF{})$. Since $d\geq 3$, for any indices $1\leq i\neq j\leq d$ there exists $1\leq m\leq d$ with $m\neq i,j$,
	and by direct computation $R_{ij}=[R_{mj},R_{im}]$ and $L_{ij}=[L_{mj},L_{im}]$. Since $\SAut(F)$ is generated by $R_{ij}$ and $L_{ij}$,
	it follows that $\SAut(F)$ is perfect.
	Finally, $[\Aut(\absF{}),\Aut(\absF{})]\subseteq \SAut(\absF{})$ simply because $[\GL_d(\dbZ),\GL_d(\dbZ)]\subseteq \SL_d(\dbZ)$.
\end{proof}

\subsection{On the subgroup structure of free groups}\label{subsect-free-abstract-subgroups}

Let $F$ be a non-abelian free group of finite rank. 

\skv
\paragraph{\bf Normal subgroups with finite cyclic quotients.} Throughout the paper we will frequently deal with automorphisms of finite index subgroups of $F$. The following situation  will play a {special} role. 

\begin{Definition}
Let  $m \geq 2$. We denote by $SCQ(F,m)$ the set of normal subgroups of $F$ such that $F/H$ is cyclic of order $m$.
\end{Definition}

For a general $m$, among the normal subgroups of index $m$, the ones in $SCQ(F,m)$ are very special. However when $m=p$ is prime, every normal subgroup of index $p$ is in $SCQ(F,p)$.

	\begin{Definition}
	Let  $m \geq 2$. Let $X$ be a basis of $F$ and let $x \in X$. We denote by $ F(X,x,m) $ the subgroup of $\absF{}$ normally generated by $x^m$ and $X \setminus \left\lbrace  x\right\rbrace $. Equivalently, $F(X,x,m)$ is the unique normal subgroup of index $m$ in $F$	
which contains $X\setminus\{x\}$.
	\end{Definition}

The following fact is well known, but we are not aware of an explicit reference in the literature, so we will provide a proof.

\begin{Lemma} \label{lem-description-SCQ}
Fix $m \geq 2$. Then  any subgroup in $SCQ(F,m)$ is equal
to $F(X,x,m)$ for some basis $X$ of $F$ and $x\in X$. Moreover, $\SAut(F)$ acts transitively on $SCQ(F,m)$.
\end{Lemma}


\begin{proof}
Let $H$ be any subgroup in $SCQ(F,m)$ and choose an epimorphism $\phi:F\to \dbZ/m\dbZ$ with $\Ker(\phi)=H$.
Given an ordered basis $X=(x_1,\ldots, x_d)$, let $t(X)\in (\dbZ/m\dbZ)^d$ be the vector
$(\phi(x_1),\ldots, \phi(x_d))$. Then for any indices $i\neq j$, the vector $t(R_{ij}^{\pm 1}X)$ is obtained
from $t(X)$ by adding (resp. subtracting) the $j^{\rm th}$ coordinate to (resp. from) the $i^{\rm th}$ coordinate.

Using such operations, any nonzero vector in $(\dbZ/m\dbZ)^d$ can be reduced to a vector with only one nonzero coordinate
(equal to the greatest common divisor of the coordinates of the original vector).
Therefore, starting with any basis $X_0$ and applying suitable Nielsen maps to it, we obtain a basis
$X$ such that $t(X)$ has at most one (in fact, exactly one) nonzero coordinate; equivalently,
$H=\Ker(\phi)$ contains $X\setminus\{x\}$. Since $H$ is normal of index $m$, it follows that $H=F(X,x,m)$, so we proved
the first assertion of Lemma~\ref{lem-description-SCQ}.
\skv

To deduce the second assertion from the first one, note that $\Aut(F)$ acts transitively on the set of ordered bases, so
for any bases $X,X'$ of $F$ and elements $x\in X$ and $x'\in X'$ there exists $\phi\in \Aut(F)$ which sends
$F(X,x,m)$ to $F(X',x',m)$. Moreover, if $\eps$ is the automorphism of $F$ which sends $x$ to $x^{-1}$ and
fixes other elements of $X$, then $\phi\, \eps$ also sends $F(X,x,m)$ to $F(X',x',m)$, and one of the maps $\phi$ and $\phi\,\eps$
lies in $\SAut(F)$.
\end{proof}

\skv
\paragraph{\bf The Schreier index formula.}
\skv

Any subgroup of $\absF{}$ is free, and the rank of a finite index subgroup $H$
of $\absF{}$ can be computed by the Schreier index formula:
$$\rk(H)=1+[\absF{}:H]\cdot\rk(\absF{}).$$
Moreover, suppose we are given a basis $X$ for $\absF{}$ and 
a right Schreier transversal $T$ for $H$ and $\absF{}$ with respect to $X$
(that is, a set of right coset representatives closed under taking suffixes,
where elements of $\absF{}$ are viewed as reduced words in $X\sqcup X^{-1}$).
Then $H$ has a basis consisting of non-identity elements of the form
$$\{tx{\overline{tx}\,}^{-1}: t\in T, x\in X\}\eqno (***)$$ where $\overline g$ is the unique
element of $T$ with $H\overline{g}=Hg$. 

\begin{Definition}
We adopt the following convention for commutators: $[x,y] = xyx^{-1}y^{-1}$, and a commutator of length more than two should be read as a {\it left-normed commutator}:
$[x_1,\dots,x_{n+1}] = [[x_1,\dots,x_n],x_{n+1}]$.
\end{Definition}

The following will be used repeatedly, sometimes without further mention, later in the paper.

\begin{Lemma}
	\label{lem:Schreier}
	 Let $X$ be a basis of $\absF{}$, let $x \in X$, and let $m \geq 2$. Then each of the following sets is a free generating set for $ F(X,x,m)$:
	\begin{itemize}
		\item[(a)] $Y=\{x^m\}\cup\{ x^j y x^{-j}: y\in X\setminus\{x\}, 0\leq j\leq m-1\}.$
		\item[(b)] $Z=\{x^m\}\cup\{[y,{}_j x]: y\in X\setminus\{x\}, 0\leq j\leq m-1\}$
		where $[y,{}_j x]$ is the left-normed commutator 
		$[y,\underbrace{x,\ldots,x}_{j\mbox{ times} }]$.
	\end{itemize}
\end{Lemma}

\begin{proof} (a) $Y$ is precisely the generating set given by (***) if we set
	$T=\{1,x,\ldots, x^{m-1}\}$. 

	(b) Since $|Z|=|Y|$, it suffices to show that $Z$ is a generating set for $ F(X,x,m)$.
	To deduce this from (a) it suffices to show that 
	$\la y,x y x^{-1},\ldots, x^k y x^{-k} \ra=\la y,[y,x],\ldots, [y,{}_k x]\ra$ for all
	$y\in \absF{}$ and $k\in \dbN$. The latter can be proved by routine induction
	using the observation that $[y,{}_k x]=[y,{}_{k-1} x](x[y,{}_{k-1} x]x^{-1})^{-1}$.
\end{proof}
\skv
\paragraph{\bf Primitive elements and free factors.} An element $g\in F$ is called primitive (for $F$) if $g$ belongs to some basis of $F$.
Every non-trivial element of $F$ is primitive for some finite index subgroup. This is a special case of the famous free factor theorem of M. Hall (see \cite[Theorem~5.1]{Ha}~and~\cite[Theorem~1]{Bu}\footnote{This result does not follow from the statement of Theorem~5.1 in 
\cite{Ha}, but it follows from its proof as explained in \cite{Bu}.}):

\begin{Theorem}\label{thm:Hallfreefactor}
Let $H$ a finitely generated subgroup of $F$. Then $H$ is a free factor for some finite index subgroup of $F$. 
\end{Theorem}

We will revisit Theorem~\ref{thm:Hallfreefactor} and discuss further generalizations in section~\ref{sec-conjugacy}.

\subsection{Generation in profinite groups and the Frattini subgroup} \label{subsec-prelim-pro-p}

Before turning to free pro-$p$ groups, we make a short digression and discuss some basic facts about generation in arbitrary profinite groups, with emphasis on pro-$p$ groups. Following a standard convention, by a generating set of a profinite group we will mean a topological
generating set unless explicitly mentioned otherwise. In particular, we will say that a profinite group is {\it finitely generated} if it has a finite topological generating set. However, we will not follow this convention whenever discussing generation of abstract and profinite groups in the same setting, most notably in section~\ref{sec-conjugacy}.

\begin{Definition}
	Let $G$ be a profinite group. The {\it Frattini subgroup} $\Phi (G)$ is the intersection of all maximal proper open subgroups of $G$. 
\end{Definition}


The  Frattini subgroup $\Phi(G)$ has the following key properties (see \cite[2.8.5]{RZ-book}):

\begin{Lemma}
	\label{lem:Frattinibasic}
	Let $G$ be a profinite group.  The following hold:
	\begin{itemize}
		\item[(i)] A subset $S$ of $G$ is a generating set if and of only if
		$G/\Phi(G)$ is generated by the image of $S$.
		\item[(ii)] An element $g\in G$ lies in $\Phi(G)$ if and only if $g$ is a non-generator,
		that is, for any generating set $S$ of $G$, the set $S\setminus\{g\}$ also generates $G$.
	\end{itemize}
\end{Lemma}

If $G$ is pro-$p$, there is a simple explicit formula for the Frattini subgroup:
$\Phi(G)=\overline{[G,G]G^p}$, where $G^p = \la x^p : x \in G\ra $ is the subgroup generated by the $p^{\rm th}$ powers
(see \cite[2.8.7]{RZ-book}). Thus the Frattini quotient $G/\Phi(G)$ is an elementary abelian $p$-group. Things become even nicer if in addition $G$ is finitely
generated \cite[2.8.10-2.8.13]{RZ-book}:

\begin{Proposition}
	\label{prop:Frattini}
	Let $G$ be a finitely generated pro-$p$ group. The following hold:
	\begin{enumerate}[resume]
		\item[(a)] $\Phi(G)=[G,G]G^p$ and $\Phi(G)$ is open in $G$.
		\item[(b)] Define the Frattini series $(\Phi^{\ell} (G))_{\ell\geq 0}$
inductively by $\Phi^0(G) =G$ and $\Phi^{\ell + 1} (G) = \Phi (\Phi^{\ell}(G))$ for every $\ell \geq 0$. Then 
$(\Phi^{\ell} (G))_{\ell\geq 0}$ is a base of neighborhoods of $1$ in $G$.
	\end{enumerate}
\end{Proposition}


\subsection{Free pro-$p$ groups}\label{subsec-prelim-freeprop}

Let $X$ be a finite set and $F=F(X)$, the free group on $X$.
The pro-$p$ completion $\propF{p}=\widehat{F}_p$ is called a free pro-$p$ group on $X$, and $X$ will be referred to as a basis of 
$\propF{p}$. We will also say that $\propF{p}$ is free pro-$p$ of finite rank, and the number $d=|X|$ (which is determined
by the isomorphism class of $\propF{p}$) will be called the rank of $\propF{p}$.

More generally, a subset $Y$ of $\propF{p}$ will be called a {\it basis} if the inclusion map $Y\to\propF{p}$ induces an isomorphism
from $\widehat{F(Y)}_p$ to $\propF{p}$. In complete analogy with free groups, bases of $\propF{p}$ are precisely the (topological) generating sets of the smallest cardinality~\cite[Lemma 3.3.5.b]{RZ-book}.

The Schreier index formula remains valid in pro-$p$ groups. Indeed, if $F$ is a free group of finite rank $d$
and $\propF{p} = \widehat{F}_p$ is its pro-$p$ completion, then the map $\propU{p} \to \propU{p}\cap F$ establishes an index-preserving
bijection between open subgroups of $\propF{p}$ and $p$-open subgroups of $F$, and any such $\propU{p}$ is isomorphic to the pro-$p$ completion
of $\propU{p}\cap F$.

The category of pro-$p$ groups admits free products; see \cite[\S~9.1]{RZ-book} for basic features of free pro-$\mathcal{C}$ products of finitely many groups, which is the only case we will need.  When discussing pro-$p$ groups, $A * B$ will denote the free pro-$p$ product, rather than the abstract free product.  Free pro-$p$ factors of a pro-$p$ group are always closed. We will need the following pro-$p$ analogue of Hall's free factor theorem:

\begin{Theorem}[See {\cite[Theorem~3.2]{Lubotzky}} or {\cite[Theorem~9.1.19]{RZ-book}}]\label{thm-free-factor}
Let $\propF{p}$ be a free pro-$p$ group of finite rank and let $H$ be a closed subgroup of $\propF{p}$ that is topologically finitely generated.  Then there is an open subgroup $K$ of $\propF{p}$ such that $H$ is a free pro-$p$ factor of $K$.
\end{Theorem}


\subsection{The $A$-topology on the automorphism group of a profinite group}\label{subsec-prelim-auto}
\label{subsec-prelim-auto-general}
A detailed discussion of the automorphism groups of free pro-$p$ groups will be deferred till subsection~\ref{subsec-generation-commfreeprop}. We finish this section by introducing a natural topology on $\Aut(G)$ for a profinite group $G$, which we will call the $A$-topology. We warn the reader that the canonical
map $\Aut(G)\to\Comm(G)$ is not continuous with respect to the $A$-topology unless $\Aut(G)$ is a finite extension of $\Inn(G)$,
the subgroup of inner automorphisms.

Let $G$ be a profinite group.  For every open subgroup $U$ of $G$ define $\Aut(G;U)\subseteq \Aut(G)$ by $$\Aut(G;U)=\{\phi\in\Aut(G): \phi(g)\equiv g\mod U\mbox{ for all }g\in G\}.$$ 
Each $\Aut(G;U)$ is a subgroup of $\Aut(G)$, and the family of all subgroups $\Aut(G;U)$
 satisfies the hypotheses of Proposition~\ref{prop:topbase} and has trivial intersection, so
$\Aut(G)$ has the structure of a Hausdorff topological group where the subgroups
$\Aut(G;U)$ form a base of neighborhoods of the identity.  We will call this the {\it $A$-topology} on $\Aut(G)$.

When $G$ is a finitely generated profinite group, $\Aut(G)$ with the $A$-topology is also compact and hence profinite \cite[Corollary 4.4.4]{RZ-book}. More is true in the case {where} $G$ is a finitely generated pro-$p$ group \cite[Lemma 4.5.5]{RZ-book}:

\begin{Proposition}
	\label{Aut:virtprop}
	Let $G$ be a finitely generated pro-$p$ group. Then the subgroup
	$$\Aut(G;\Phi(G))=\Ker(\Aut(G)\to\Aut(G/\Phi(G)))$$ 
	(which is open by Proposition~\ref{prop:Frattini}(a)) is pro-$p$.  Thus $\Aut(G)$ is virtually pro-$p$.
\end{Proposition}

Later in the paper, we will apply Proposition~\ref{Aut:virtprop} in two separate proofs, both times in the case where $G$ is free pro-$p$.
In one of the instances the specific topology on $\Aut(G)$ will not play a role; we will just need to know that
$\Aut(G;\Phi(G))$ is pro-$p$ with respect to some topology.


\section{Some precursors to the simplicity theorems} \label{sec-prelim-simpl}

Recall that throughout the paper $F$ denotes a {non-abelian} free group {of finite rank}.

\subsection{Stability and instability of $\det$ under passing to invariant subgroups}



In this subsection we  establish  basic results relating the groups $\SAut(F)$ and $\SAut(H)$
where $H$ is a suitable finite index subgroup of $F$. The first result of this kind follows immediately 
from Lemma~\ref{lem:absperfect}(b):


\begin{Corollary}
\label{cor:SAut_char}
Suppose that $\rk(\absF{})\geq 3$. Let $H$ be a finite index characteristic subgroup of $\absF{}$, so that 
$\Aut(\absF{}) \subseteq \Aut(H)$ if we view both $\Aut(F)$ and $\Aut(H)$ as subgroups of $\Comm(F)$. Then $\SAut(\absF{}) \subseteq \SAut(H)$.
\end{Corollary}

\begin{proof} Note that $\rk(H)\geq \rk(\absF{})\geq 3$.
Hence by Lemma~\ref{lem:absperfect}(b) we have 
$$\SAut(\absF{})=[\Aut(\absF{}),\Aut(\absF{})] \subseteq [\Aut(H),\Aut(H)]=\SAut(H).\qedhere$$
\end{proof}

\begin{Notation}
If $H$ is a finite index subgroup of $F$, we denote by  $\Aut(F)_H$  the stabilizer of $H$ in $\Aut(F)$. Hence inside the ambient group $\Comm(\absF{})$ we have $\Aut(F)_H \subseteq \Aut(H)$. 
\end{Notation}

Given $\alpha\in \Aut(F)$, we set $\det(\alpha)=\det(\pi(\alpha))$ where $\pi:\Aut(\absF{})\to \GL_d(\dbZ)$ is the canonical map.
Thus, $\alpha\in \SAut(F)$ if and only if $\det(\alpha)=1$. If $H$ is a finite index subgroup of $F$ such that $\alpha \in \Aut(F)_H$, we set $\det_H(\alpha)=\det(\alpha_{|H})$ where $\alpha_{|H}$ is the automorphism of $H$ induced by $\alpha$. 
Corollary~\ref{cor:SAut_char} can be rephrased by saying that if $\rk(F)\geq 3$, $\det_F(\alpha)=1$ and $H$ is characteristic in $F$,
then $\det_H(\alpha)=1$ as well. As we will see shortly, such implication does not hold if we only assume that $H$ is $\alpha$-invariant.
\skv


\begin{Lemma} \label{lem-stab-not-contained-special-aut}
Let $m \geq 2$ and $H \in SCQ(F,m)$. The following hold:
\begin{itemize}
\item[(a)] There exists $\alpha\in\Aut(F)_H$ such that  $\alpha_{|H} \not\in \SAut(H)$. Hence if we view $\Aut(F)$ and $\Aut(H)$
as subgroups of $\Comm(F)$, then $\Aut(H)\subseteq \la\SAut(H),\Aut(F)\ra$.
\item[(b)] If $m=2$, or if $m \equiv 3 \mod 4$ and $\rk(F)$ is even, then there exists $\alpha\in\Aut(F)_H$ such that
$\alpha\not\in \SAut(F)$, but $\alpha_{|H}\in \SAut(H)$. Hence inside $\Comm(F)$ we have $\Aut(F)\subseteq \la\SAut(F),\SAut(H)\ra$.
\end{itemize}
\end{Lemma}

\begin{proof} Let $d=\rk(F)$. By Lemma \ref{lem-description-SCQ} we have $H=F(X,x_1,m)$ for some basis $X = \left\lbrace x_1,\ldots,x_d \right\rbrace $ of $\absF{}$, 
and then by Lemma~\ref{lem:Schreier}(a) $H$ has a basis $$Y=\left\{x_1^p,   x_1^k x_i x_1^{-k}: 2\leq i\leq d, 0\leq k\leq m-1\right\}.$$
\skv

(a) Let $\alpha$ be the automorphism of $\absF{}$ given by $\alpha(x_2)=x_2^{-1}$ and $\alpha(x_i)=x_i$ for $i\neq 2$.
Then $\alpha$ preserves $H$; in fact, it inverts $m$ generators from $Y$, namely the elements $x_1^k x_2 x_1^{-k}$,
and fixes the remaining generators. Hence the matrix of the induced automorphism of $H/[H,H]$ is diagonal, with
all diagonal entries equal to $\pm 1$ and exactly $m$ entries equal to $-1$. Thus $\det_H(\alpha)=(-1)^m$, so $\alpha_{|H} \not\in \SAut(H)$ if $m$ is odd.

For $m$ even, we consider the automorphism $\gamma$ of $\absF{}$ that maps $x_2$ to $x_1  x_2 x_1^{-1}$ and fixes all other elements of $X$. 
In this case the matrix of the induced automorphism of $H/[H,H]$ is a permutation matrix associated to a cycle of length $m$,
so $\det_H(\gamma)=-1$. This finishes the proof of the first assertion of (a).

The second assertion of (a) follows from
the first one and the fact that $\SAut(H)$ has index $2$ in $\Aut(H)$, so there are no subgroups strictly between
$\Aut(H)$ and $\SAut(H)$.
\skv

(b) As in (a), it suffices to prove the first assertion.
First suppose that $m=2$ and consider the automorphism $\alpha$ used in the proof of (a).
Clearly $\det_{F}(\alpha)= -1$, and $\det_{H}(\alpha)=(-1)^2=1$ by the computation in (a), so $\alpha\not\in \SAut(F)$
while $\alpha_{|H} \in \SAut(H)$, as desired.
\skv

Now suppose that $m \geq 3$ and $d=\rk(F)$ is even. Define $\beta\in \Aut(F)$ by $\beta(x_1)=x_1^{-1}$ and $\beta(x_i)=x_i$ for $i\neq 1$,
so that $\det_{F}(\beta) = -1$. To show that $\beta$ preserves $H$ and compute $\det_{H}(\beta)$, it is more convenient
to use a slightly different basis $Z$ for $H$: $$Z=\left\{x_1^m, x_1^k x_i x_1^{-k}: 2\leq i\leq d, |k|\leq \frac{m-1}{2}\right\}.$$
Note that $\beta$ inverts one element of $Z$, namely $x_1^m$, fixes $d-1$ elements, namely $x_i$ for $2\leq i\leq d$, and
performs $(d-1)(m-1)/2$ transpositions on the remaining generators
(it swaps $x_1^k x_i x_1^{-k}$ with $x_1^{-k} x_i x_1^{k}$ whenever $k\neq 0$). Hence $\det_{H}(\alpha) = (-1)^{\frac{(d-1)(m-1)}{2}+1}=1$
since $m\equiv 3 \mod 4$ and $d$ is even. 
\end{proof}

\subsection{Preliminary results on the subgroups of $\Comm(F)$}

In this subsection we will establish two technical results on the subgroup structure of $\Comm(F)$. In both cases our goal is to show
that the subgroup of $\Comm(F)$ generated by a certain set contains $\SAut(H)$ where $H=F$ or $H\in SCQ(F,m)$.

\skv

We will need the following lemma, which can be extracted from the proof of \cite[Proposition~1]{Bri-Vog-hom}.  The proposition is originally stated for normal subgroups of $\Aut(F)$, but the argument works just as well for subgroups normalized by $\SAut(F)$.

\begin{Lemma} 
	\label{lem-alt-normally-generates}
	Suppose that $\rk(F)\geq 3$, and let $N$ be a subgroup of $\Aut(F)$ normalized by $\SAut(F)$.  Suppose that some element of $N$ acts as a non-trivial permutation of a basis for $F$.  Then $N$ contains $\SAut(F)$. 
\end{Lemma}

As in subsection~\ref{subsec-free-groups-gen-aut}, for any basis $X$ of $F$, we will view the symmetric group $\Sym(X)$
and the alternating group $\Alt(X)$ as subgroups of $\Aut(F)$. 

\begin{Proposition} 
	\label{prop-int-implies-saut}
Let $d=\rk(F)$ and  $X = \left\lbrace x_1,\ldots,x_d \right\rbrace $ a basis of $F$. Let $m \geq 2$, let  $H = F(X,x_1,m)$, and let $s \geq 1$ be such that $m$ does not divide $s$. Assume that $(d,m) \neq (2,2)$. Then the group generated by the $\SAut(H)$-conjugates of $x_1^s$ contains $\SAut(H)$. In particular, the  group generated by the $\SAut(H)$-conjugates of $F$ contains $\SAut(H)$.
\end{Proposition}

