\title{Group schemes and their Lie algebras over a symmetric tensor category}
\begin{document}


\begin{abstract}
We investigate the theory of affine group schemes over a symmetric tensor
category, with particular attention to the tangent space at the
identity.  We show that this carries the structure of a restricted Lie
algebra, and can be viewed as the degree one distributions on the
group scheme, or as the right invariant derivations on the coordinate
ring. In the second half of the paper, we illustrate the theory in the
particular case of the symmetric tensor category $\mathsf{Ver}_4^+$ in
characteristic two.
\end{abstract}

\keywords{Canonical algebra, distribution algebra, group scheme,
operads, restricted Lie algebras, symmetric tensor categories, 
Verlinde categories}

