\part{\texorpdfstring{\centering The case $\mcC=\CV$}
{The case C=Ver₄⁺}}

We now make explicit the abstract theory presented above in the case
of the symmetric tensor category $\CV$. We write $\CVi$ for
the ind-completion of $\CV$.



Let $k$ be a field of characteristic two.
An object in $\CVi=\CVi(k)$ consists of a vector space $V$ together with a 
map $d\colon V \to V$ satisfying $d^2=0$. The tensor product of two
such, $(V,d)$ and $(V',d')$, is $(V\otimes V',d\otimes 1 + 1 \otimes d')$.
The symmetric braiding
\[ s\colon V \otimes V' \to V'\otimes V \]
is given by 
\[ s(v\otimes v') = v'\otimes v + dv' \otimes dv. \]

The category $\CV$ has just one simple object, which is the field
$k$. This is the tensor identity $\one$ in $\CV$.
There are two isomorphism classes of indecomposable objects in $\CV$,
namely the simple $k$ and its projective cover $P$. There is a short
exact sequence
\[ 0 \to k \to P \to k \to 0. \]

\section{Algebras}

This section expands on Section~\ref{se:CA} in the context of $\CV$.
An algebra in $\CVi$ is an object $A$ in $\CVi$ together
with a morphism $\mu\colon A \otimes A \to A$ satisfying the usual associativity
and unit conditions; namely a differential algebra over $k$. This consists of an 
associative algebra $A$ in the usual sense, with a linear map $d\colon A\to A$ satisfying
$d^2=0$ and $d(xy)=dx.y+x.dy$ for all $x$, $y\in A$. In particular, this implies
that $d(1)=0$.

The tensor product $A\otimes A'$ of two algebras $A$, $A'$ in $\CVi$
is given by taking the tensor product of the vector spaces $A \otimes_k A'$
with differential $d(x\otimes y) = dx \otimes y + x \otimes dy$
and multiplication 
\[ (x \otimes y)(x' \otimes y') = xx' \otimes yy' + x.dx' \otimes dy.y'. \]

The definition of commutative algebra given in Section~\ref{se:CA}
takes the following form in $\CVi$.

\begin{defn}\label{def:ep}
A \emph{commutative algebra} over $\CVi$ consists of a differential algebra $A$ satisfying
the identity
\begin{equation}\label{eq:comm}
xy + yx = dx.dy
\end{equation}
for all $x$, $y\in A$. 

The commutative algebras over $\CVi$ form a category over $\CVi$
which we denote $\CVAlg$. If $A$ and $B$ are commutative algebras
over $\CVi$ then so is $A\otimes B$, with multiplication
\[ (x\otimes y) (x'\otimes y')=xx'\otimes yy' + x.dx' \otimes dy.y'. \]
There is a full embedding of the category $\CAlg=\CAlg_{\VV(k)}$ 
into $\CVAlg$. It has a left adjoint $u\colon \CVAlg \to \CAlg$
which takes a commutative algebra $A$ over $\CVi$ to
the quotient $A_u$ of $A$ by the linear span of elements of the form $x.dy$. 
This is an ideal, so the quotient is an object in $\CAlg$.
\end{defn}

\begin{eg}\label{eg:K}
Mod two topological K-theory is a contravariant functor from the
homotopy category of CW-complexes to the category
$\CVAlg$, with the Bockstein map as the differential. 
Actually it admits two different multiplications,
but one is the reverse of the other, so we make a choice.
The two choices are related by an automorphism of $\CV$,
so it does not matter which choice we make. This is investigated in
papers of Araki and coauthors~\cite{Araki:1967a,Araki/Toda:1965a, 
Araki/Toda:1966a,Araki/Yosimura:1970a,Araki/Yosimura:1971a}.

Morava K-theory $K(n)$ in characteristic two, as well as the $BP$-module
spectrum $P(n)$ have similar properties. See 
W\"urgler~\cite[Remark~7.3]{Wurgler:1977a}, \cite[Proposition~2.4]{Wurgler:1986a},
Mironov~\cite{Mironov:1979a},
Kultze and W\"urgler~\cite{Kultze/Wurgler:1987a,Kultze/Wurgler:1988a},
Kane~\cite[\S14]{Kane:1988a},
Nassau~\cite{Nassau:2002a}, 
Strickland~\cite[Theorem~2.13]{Strickland:1999a}.
\end{eg}

\begin{lemma}\label{le:dx2}
If $x$, $y$ are elements of a commutative algebra over $\CV$ then
$(dx)^2=0$ and $x.dy=dy.x$.
\end{lemma}
\begin{proof}
This follows from \eqref{eq:comm} by replacing $y$ by $x$, respectively $dy$.
\end{proof}


An object in $\CV$ can be written as a direct sum of $m$ copies of $k$
and $n$ copies of $P$. This has a $k$-basis of the form
\begin{equation}\label{eq:basis}
x_1,\dots,x_{m+n},w_1,\dots,w_n 
\end{equation}
with 
\[ d(x_i)=\begin{cases} w_i & 1\le i \le n \\ 0 & n+1\le i \le
  m \end{cases}\qquad
d(w_i) = 0. \] 
We write $V_{m+n|n}$ for this object. These form a complete set of
representatives for the isomorphism classes of 
objects in $\CV$, with $m,n\ge 0$.


\begin{lemma}\label{le:free}
The \emph{free commutative algebra} in $\CVi$ on $V_{m+n|n}$
has generators as an algebra 
\[ x_1,\dots,x_{n+m},w_1,\dots,w_n,\] 
with 
\[
d(x_i)=\begin{cases} w_i & 1\le i \le n \\ 0 & n+1\le i \le
  m \end{cases},\qquad
d(w_i) = 0 \]
and relations
\[ w_i^2=0,\qquad 
x_iw_j=w_jx_i,\qquad
x_ix_j+x_jx_i=w_iw_j=w_jw_i. \] 
\end{lemma}
\begin{proof}
Given these generators, defining $w_i$ to be $d(x_i)$, the given 
relations follow from Lemma~\ref{le:dx2}. Conversely, the differential algebra
defined by these generators and relations satisfies the commutativity
condition \eqref{eq:comm}.
\end{proof}

\begin{defn}
For notation, we shall write $k\lb x_1,\dots,x_n\rb$ for the free commutative
algebra in $\CV$ on $x_1,\dots,x_n$, as described in Lemma~\ref{le:free}.
\end{defn}

\begin{eg}\label{eg:xx^-1}
Let's examine $k\lb x,y\rb/(xy+1)$. We have $d(xy)=d(1)=0$, 
so $dx.y+x.dy=0$. Multiplying by $y$, we see that $dy=y^2dx$.
Writing $y$ as $x^{-1}$, we have $d(x^{-1})=x^{-2}dx$. Thus
as an ordinary algebra we have $k\lb x,y\rb/(xy)=k[x,x^{-1},w]/(w^2)$
with $dx=w$, $d(x^{-1})=x^{-2}w$, $dw=0$. We shall write $k\lb x,x^{-1}\rb$ 
for this object in $\CVAlg$.
\end{eg}

\begin{lemma}\label{le:inverse}
Let $A$ be a commutative algebra in $\CVi$, and let $u$ and
$v$ be elements of $A$ satisfying $uv=1$. Then also $vu=1$.
\end{lemma}
\begin{proof}
Let $I$ be the ideal in $A$ generated by the elements $dx$ for $x \in A$.
Then $I^2=0$, and $A/I$ is commutative in the ordinary sense. These are
the hypotheses we use to prove the lemma. If $uv=1$ then $vu$ and $1$
have the same image in $A/I$ and so $vu-1\in I$. Thus $(1-vu)^2=0$.
Expanding this out, we have $1-2vu+vuvu=0$. Using $uv=1$, this becomes
$1-vu=0$ and so $vu=1$.
\end{proof}

\begin{rk}
Essentially the same 
proof shows more generally that if $I$ is a nilpotent ideal in a
ring $A$ with $A/I$ commutative (in the ordinary sense) and
$u$ and $v$ are elements with $uv=1$ then also $vu=1$.
The proof is that $vu$ is idempotent, so $1-vu$ is also
idempotent. But it is also nilpotent, and hence it is zero.
\end{rk}

\section{Affine schemes}

This section expands on Section~\ref{se:tangent} in the context of $\CV$.
An affine scheme $S$ in $\CVi$ is a representable functor
\[ S\colon \CVAlg\to \Set \]
with representing object the coordinate ring $\mcO(S)$. 

The canonical algebra $E$ for $\CV$ is a two dimensional
space with basis $\ep, d\ep$. So the ring of dual numbers over $\CV$
(Definition~\ref{def:dual-numbers}) is 
\[ \mcE = k[\ep,d\ep]/(\ep^2,\ep\,d\ep,d\ep^2). \]
The differential $d$ takes $1$ and $d\ep$ to zero, and $\ep$ to $d\ep$.
The ring $\mcE$ comes with an augmentation map $\eta\colon\mcE\to k$ which
takes $1$ to $1$ and takes $\ep$ and $d\ep$ to zero.

Let $x\colon\mcO(S) \to k$ have kernel $\mfm_x$.
The tangent space to $S$ at $x$ is 
\[ \Tan_{S,x}=(\mfm_x/\mfm_x^2)^* \cong 
\Hom_\CV(\mfm/\mfm_x^2,E)\cong \Hom_{\CVAlg}(\mcO(S),\mcE)_x, \]
where $\Hom_{\CVAlg}(\mcO(S),\mcE)_x$ is the
subspace of $\Hom_{\CVAlg}(\mcO(S),\mcE)$ consisting
of those morphisms whose composite with $\eta$ is
equal to $x$. The isomorphism between $(\mfm_x/\mfm_x^2)^*$ 
and $\Hom_{\CVAlg}(\mcO(S),\mcE)_x$ is described explicitly 
in the following lemma, which shows that tangent vectors can
be thought of as $x$-derivations from $\mcO(S)$ to $k$ in
the ordinary sense of derivation.

\begin{lemma}\label{le:f:k[S]to-k-ep}
If $f\in\Hom_{\CVAlg}(\mcO(S),\mcE)_x$, then
$f$ takes the form 
\begin{equation}\label{eq:f(a)} 
f(a)=x(a)+f'(da)\ep +f'(a)d\ep 
\end{equation}
where $f'\colon \mcO(S)\to k$ is a linear map which takes value
zero on $1$ and on $\mfm_x^2$, and satisfies
\begin{equation}\label{eq:f'(ab)} 
f'(ab)=f'(a)x(b)+x(a)f'(b). 
\end{equation}
Conversely, if $f'$ is given, satisfying these conditions, then
the map $f$ defined by~\eqref{eq:f(a)} is an element of
$\Hom_{\CVAlg}(\mcO(S),\mcE)_x$.
\end{lemma}
\begin{proof}
If the composite of $f$ with $\eta$ is $x$, then $f$ takes
the form
\[ f(a) = x(a) + g(a)\ep + h(a)d\ep \]
for suitable linear maps $g$, $h$ from $\mcO(S)$ to $k$.
Applying $d$ to this equation, we obtain
\[ d(f(a))=g(a)d\ep. \]
On the other hand, since $x(da)=0$, we have
\[ f(da) = g(da)\ep + h(da)d\ep. \]
Since $f$ is a morphism in $\CVi$, it commutes with the action of $d$,
so these expressions have to be equal. Hence we have
\[ g(da)=0, \qquad h(da)=g(a). \]
The second of these says that $h$ determines $g$, and the first
is then automatic. So we write $f'(a)$ for $h(a)$
and $f'(da)$ for $g(a)$.

The statement that $f$ is an algebra homomorphism
translates as
\[ x(ab) + f'(d(ab))\ep + f'(ab)d\ep = (x(a)+f'(da)\ep+f'(a)d\ep)(x(b)+f'(db)\ep+f'(b)d\ep). \]
Multiplying this out, and using the fact that $x(ab)=x(a)x(b)$, this is equivalent to
\[ (f'(da.b)+f'(a.db))\ep + f'(ab)d\ep = (x(a)f'(db)+f'(da)x(b))\ep + (x(a)f'(b)+f'(a)x(b))d\ep. \]
Comparing coefficients of $\ep$ and $d\ep$, this is equivalent to two equations:
\begin{align*}
f'(da.b)+f'(a.db) &= x(a)f'(db)+f'(da)x(b), \\
f'(ab)&=x(a)f'(b) + f'(a)x(b).
\end{align*}
The second of these implies the first, and so $f$ is an algebra homomorphism
if and only if $f'$ satisfies~\eqref{eq:f'(ab)}. If this holds, then $f'$ vanishes on
$1$ and on $\mfm_x^2$.
\end{proof}


\section{Group schemes}

This section expands on Section~\ref{se:group-schemes} in the context
of $\CV$.
An affine group scheme $G$ over $\CVi$ is a functor
\[ G\colon \CVAlg \to \Grp \]
such that composing with the forgetful functor $\Grp\to\Set$
gives a representable functor.
If $G$ is an affine group scheme over $\CVi$ then the
coordinate ring $\mcO(G)$ is a Hopf algebra over $\CVi$.


\begin{warning}
Just as in the case of Hopf superalgebras, 
a Hopf algebra over $\CVi$ is not a Hopf algebra in the
ordinary sense, because the comultiplication is not a map of algebras 
when the tensor product is given the usual algebra structure.
Hopf algebras in $\CVi$ are given the cumbersome name 
\emph{differential near Hopf algebras} in~\cite{Araki:1967a}.
\end{warning}

\begin{eg}
Continuing with Example~\ref{eg:K},
the mod two K-theory of a compact Lie group is
a commutative Hopf algebra over $\CVi$, and hence
gives rise to an affine group scheme.
This example is discussed at length by Araki and his
coauthors in \cite{Araki:1967a,Araki/Toda:1965a,Araki/Toda:1966a,
Araki/Yosimura:1970a,Araki/Yosimura:1971a}.
\end{eg}

\begin{eg}\label{eg:Ga}
The \emph{additive group scheme} $\widetilde\bbG_a$ is the functor
assigning to each object in $\CVAlg$ its additive group. It
has $\mcO(\widetilde\bbG_a)=k\lb x\rb =k[x,dx]/((dx)^2)$
with coproduct $\Delta(x)=x\otimes 1 + 1 \otimes x$,
$\Delta(dx)=dx\otimes 1 + 1 \otimes dx$, counit
$\eta(x)=0$, $\eta(dx)=0$, antipode $\tau(x)=x$, $\tau(dx)=dx$.
\end{eg}

\begin{eg}\label{eg:Gm}
The \emph{multiplicative group scheme} $\widetilde\bbG_m$ is the
functor assigning to each object in $\CVAlg$ its multiplicative
group of invertible elements. Note that an element of such
an object is invertible if and only if it is invertible modulo
the image of $d$. We have
\[ k[\widetilde\bbG_m]=k\lb x,x^{-1}\rb=k[x,x^{-1},dx]/((dx)^2) \]
(see Example~\ref{eg:xx^-1}) with coproduct
\[ \Delta(x) = x \otimes x,\qquad
\Delta(x^{-1}) = x^{-1}\otimes x^{-1},\qquad 
\Delta(dx)=dx\otimes x + x \otimes dx, \]
counit $\eta(x)=1$, $\eta(x^{-1})=1$, $\eta(dx)=0$, antipode
$\tau(x)=x^{-1}$, $\tau(x^{-1})=x$, $\tau(dx)=x^{-2}dx$.
\end{eg}

\begin{rk}
Our notation $\widetilde\bbG_a$ and $\widetilde\bbG_m$ corresponds to the
notation $\bbG'_a$ and $\bbG'_m$ in Hu~\cite{Hu:GLVer4+}.
\end{rk}

\begin{eg}\label{eg:GL}
Let $V_{m+n|n}$ be a direct sum of $m$ copies of $k$ and $n$ copies of $P$ in
$\CV$. Then
the \emph{general linear group scheme} $\GL(V_{m+n|n})=\GL(m+n|n)$ is the functor
assigning to each object $A$ in $\CVAlg$ the multiplicative group
of automorphisms of the $A$-module $V_{m+n|n}\otimes A$. 
Again note that
a matrix is invertible if and only if it is invertible modulo the
image of $d$. We have
\begin{multline*} 
k[\GL(m+n|n)]=k[ x_{i,j}\ (1\le i,j\le m+n), dx_{i,j}\ (1\le i,j\le
  n),u,du]\\
/((dx_{i,j})^2, (du)^2, u.\det(x_{i,j})+1). 
\end{multline*}
(where $dx_{i,j}=0$ if either $i$ or $j$ is larger than $n$).
Note that by Lemma~\ref{le:inverse}, in $k[\GL(m+n|n)]$ we have
\[ \det(x_{i,j}).u=u.\det(x_{i,j})=1. \]
Note also that we may take any order for the variables $x_{i,j}$ for the 
definition of a determinant here, but changing the order changes
what $u$ is.
For example, if $n=2$, $m=0$, and
\[ u(x_{1,1}.x_{2,2}+x_{1,2}.x_{2,1}) = 1 \]
then 
\[ (u+u^2dx_{1,1}.dx_{2,2})(x_{2,2}.x_{1,1}+x_{1,2}.x_{2,1}) = 1. \]
In general, the determinant is well defined modulo the
ideal generated by the image of $d$, but adding an element
of this ideal does not affect the effect of adjoining the inverse 
of the determinant.
For definiteness we use the lexicographic order
on the $x_{i,j}$. 
Using the same lexicographic order to define the adjoint of a matrix $X$
of elements of an object in $\CVAlg$,
we don't have $X.\Adj(X)=\det(X).I$, but the difference squares
to zero, so we have 
\[ X. \Adj(X).u.X.\Adj(X).u=I. \]
So the inverse of $X$ is $\Adj(X).u.X.\Adj(X).u$.

The coproduct on $k[\GL(n+m|m)]$ is given by
\[ \Delta(x_{i,j})=\sum_{\ell}x_{i,\ell}\otimes
  x_{\ell,j},\quad \Delta(u)=u\otimes u. \]
The counit is $\ep(x_{i,j})=\delta_{i,j}$ (Kronecker's delta),
$\ep(dx_{i,j})=0$, $\ep(u)=1$.
The antipode $\tau(x_{i,j})$ is given by the matrix entries in
$\Adj(X).u.X.\Adj(X).u$, which is equivalent to $\Adj(x_{i,j})$ modulo the
ideal generated by the image of $d$, and $\tau(dx_{i,j})=d\tau(x_{i,j})$
then simplifies to $d(\Adj(x_{i,j}))$.
\end{eg}

\begin{lemma}
If $G$ is an affine group scheme over $\CVi$ then $\mcO(G)_u$
(see Definition~\ref{def:ep}) is a
commutative Hopf algebra over $\VV$, defining an affine group
scheme over $\VV$ denoted $G_u$.
\end{lemma}
\begin{proof}
We have
\begin{align*}
\Delta(x.dy)&=\Delta(x).d(\Delta(y)) \\
&=\sum(x' \otimes x'').\sum(dy'\otimes y''+y'\otimes dy'') \\
&=\sum(x'.dy' \otimes x''y'' + x'y' \otimes x''.dy'').
\qedhere
\end{align*}
\end{proof}

Applying this functor to the group schemes $\widetilde\bbG_a$ and
$\widetilde\bbG_m$  above gives the corresponding more familiar group schemes
$\bbG_a$ and $\bbG_m$ over $\VV$.

\begin{defn}
A \emph{finite group scheme} $G$ in $\CV$ is an affine group scheme 
in $\CVi$ whose coordinate ring $\mcO(G)$ is in $\CV$, which is to say
that it is finite dimensional over $k$.
\end{defn}

If $G$ is a finite group scheme in $\CV$ then the dual Hopf algebra
\[ kG = \Hom_k(\mcO(G),k) \]
is a cocommutative Hopf algebra in $\CV$. This sets up a covariant
equivalence of categories between finite group schemes in $\CV$ and
cocommutative Hopf algebras in $\CV$.


\section{Derivations}

This section expands on Section~\ref{se:derivations} in the context of $\CV$.

\begin{defn}
[Derivations in $\CVi$] 
Let $A$ be an algebra in $\CVi$ and $M$ an $A$-$A$-bimodule in $\CVi$.
A map $f\colon A \to M$ in $\CVi$ is a 
\emph{derivation} if 
\[ f(xy)=f(x)y+xf(y)+dx.(df)(y) \] 
where $df$ is defined by 
\[ (df)(x)=d(f(x))+f(dx). \] 
We write $\Der(A,M)$ for the $k$-vector space of 
derivations from $A$ to $M$, and $\Der(A)$ for $\Der(A,A)$.
\end{defn}

\begin{lemma}\label{le:dfxy}
If $f\colon A\to M$ is a derivation in $\CVi$ 
then for $x$,
$y\in A$ we have
\begin{enumerate} 
\item $(df)(xy) = d(f(x)).y+x.d(f(y))+f(dx).y+x.f(dy)$
\item $d(f'\circ f)=df'\circ f + f' \circ df$
\item $d(df)=0$.\smallskip

If $f,f'\colon A \to A$ are derivations then for $x\in A$ we have
\item $(df'\circ df)(x)=d(f'(d(f(x)))+d(f'(f(dx)))+f'(d(f(dx))).$
\end{enumerate}
\end{lemma}
\begin{proof}
For (i), we have
\begin{align*}
(df)(xy) & = d(f(xy))+f(d(xy)) \\
&= d(f(x).y+x.f(y)+dx.(df)(y))+f(dx.y+x.dy) \\
&=d(f(x)).y+f(x).dy+dx.f(y)+x.d(f(y)) \\
&\qquad +f(dx).y+dx.f(y)+f(x).dy+x.f(dy)\\
&=d(f(x)).y+x.d(f(y))+f(dx).y+x.f(dy).
\end{align*}
Parts (ii)--(iv) are similar but easier computations.
\end{proof}

\begin{defn}
If $f,f'\colon A\to A$ are derivations of an algebra in $\CVi$
we define
\[ [f,f']=f\circ f' + f' \circ f + df' \circ df. \]
\end{defn}

\begin{lemma}\label{le:[f,f']}
If $f,f'\colon A\to A$ are derivations of an algebra in $\CVi$ then so is
$[f,f']$.
\end{lemma}
\begin{proof}
This follows from 
Theorem~\ref{th:derivations}, but one can also give
a long and stupid proof with elements using Lemma~\ref{le:dfxy}.
\end{proof}


\section{Lie algebras}

Translating Definition~\ref{def:Lie}, 
we find that the definition in $\CVi$ is as follows.

\begin{defn}\label{def:Lie-algebra}
A \emph{Lie algebra} in $\CVi$ consists of an object $(L,d)$ in 
$\CVi$ together with a bilinear map of vector spaces, called the \emph{Lie bracket}:
\[ [\ ,\ ] \colon L \otimes L \to L \]
satisfying the following axioms:\smallskip
\begin{enumerate}
\item $d[x,y] =[dx,y]+[x,dy]$, \smallskip
\item $[y,x]=[x,y]+[dx,dy]$, \smallskip
\item $[x,[y,z]]+[y,[z,x]]+[z,[x,y]] =
  [dx,[y,dz]]+[dy,[z,dx]]+[dz,[x,dy]]$. 
\item If $dx=0$ then $[x,x]=0$.
\end{enumerate}
\end{defn}

\begin{rk}
Conditions (i)--(iii) of this definition come from
Definition~\ref{def:Lie} of an operadic Lie algebra. Condition~(iv)
comes from the following lemma. See also Remark~\ref{rk:res-Lie-algebra}.
\end{rk}

\begin{lemma}\label{le:[dx,dx]}
We have $[dx,dx]=0$ and $[x,dy]=[dy,x]$.
\end{lemma}
\begin{proof}
This follows from (ii) by replacing $y$ by $x$, respectively $dy$.
\end{proof}

\begin{rk}
In the presence of the other axioms, (iii) is symmetric, in
the sense that it is equivalent to
\[ [[x,y],z]+[[y,z],x]+[[z,x],y]=[[dx,y],dz]
+[[dy,z],dx]+[[dz,x],dy]. \]
\end{rk}

\begin{lemma}
We have $d[x,x]=0$.
\end{lemma}
\begin{proof}
Replace $y$ by $x$ in (i) and use Lemma~\ref{le:[dx,dx]}.
\end{proof}

\begin{lemma}\label{le:[x,y]}
If $A$ is an algebra in $\CVi$ then defining a bracket $[\ ,\ ]$
on $A$ via 
\[ [x,y] = xy + yx + dy.dx \]
we give $A$ the structure of a Lie algebra in $\CVi$.
\end{lemma}
\begin{proof}
We verify the four axioms in Definition~\ref{def:Lie-algebra}:

(i) $d[x,y]=d(xy+yx+dy.dx)=dx.y+x.dy+dy.x+y.dx=[dx,y]+[x,dy]$.

(ii) $[x,y]+[dx,dy]=xy+yx+dy.dx+dx.dy+dy.dx=xy+yx+dx.dy=[y,x]$.

(iii) We expand $[x,[y,z]]+[dx,[y,dz]]$ to get
\begin{gather*} 
x(yz+zy+dz.dy)+(yz+zy+dz.dy)x +(dy.z+y.dz+dz.y+z.dy)dx \\
{}+dx(y.dz+dz.y) +(y.dz+dz.y)dx 
\end{gather*}
The terms $y.dz.dx$ and $dz.y.dx$ occur twice and cancel.
We need to check that rotating $x$, $y$ and $z$ and adding the three
resulting expressions, we get zero. By symmetry, we only need check
the terms beginning with $x$ and with $dx$. Rotating the remaining
ten terms this way gives
\begin{equation*}
xyz+xzy+x.dz.dy+xyz+xzy+dx.dz.y+dx.y.dz+x.dz.dy+dx.y.dz+dx.dz.y
\end{equation*}
which adds up to zero.

(iv) If $dx=0$ then $xx + xx + dx.dx = 0$.
\end{proof}

\begin{rk}
Lemma~\ref{le:[x,y]} is the construction of the object $\Lie(A)$
described in~\eqref{eq:functors}.
\end{rk}

\begin{eg}\label{eg:End}
If $V$ is an object in $\CVi$ then $\End(V)$ is an algebra
in $\CVi$. Using Lemma~\ref{le:[x,y]}, we make $\End(V)$
into a Lie algebra.
\end{eg}

\begin{eg}
If $A$ be an algebra in $\CVi$ then by Lemmas~\ref{le:[f,f']} 
and~\ref{le:[x,y]}, $\Der(A)$ is a Lie subalgebra of $\End(V)$ in $\CVi$.
\end{eg}

\begin{rk}
Note the asymmetry in the lemma: we don't have $dx.dy=dy.dx$. 
It is possible to set everything up in such a way that
$[x,y]=xy+yx+dx.dy$. The effect of this would be to work with left
invariant derivations instead of right invariant ones in what follows.
\end{rk}

\begin{lemma}\label{le:Ad}
In the presence of Axioms {\rm\ref{def:Lie-algebra}\,(i)} and {\rm (ii)}, 
axiom {\rm (iii)} is equivalent to 
\[ [[x,y],z]=[x,[y,z]]+[y,[x,z]]+[dy,[dx,z]]. \]
which may be interpreted as saying that $\ad([x,y])(z)=[\ad(x),\ad(y)](z)$.
\end{lemma}
\begin{proof}
This is a long but straightforward exercise, using the definitions.
\end{proof}

\begin{defn}
The \emph{adjoint representation} of a Lie algebra $L$ in $\CVi$ is
the map from $L$ to $\End(L)$ sending $x$ to $\ad(x)$. Regarding $\End(L)$
as a Lie algebra as in Example~\ref{eg:End}, Lemma~\ref{le:Ad} shows
that the adjoint
representation is a homomorphism of Lie algebras in $\CVi$.
\end{defn}

\begin{defn}
Let $G$ be a group scheme in $\CVi$. A map $f\colon\mcO(G)\to
\mcO(G)$ is said to be 
\emph{right invariant} if the following diagram commutes:
\[ \xymatrix{\mcO(G) \ar[r]^f\ar[d]_\Delta & \mcO(G) \ar[d]^\Delta \\
\mcO(G) \otimes \mcO(G) \ar[r]_{f\otimes\Id} & \mcO(G)\otimes \mcO(G).} \]

It is easy to check that if $f$ and $f'$ are 
right invariant then so are $df$ and $f\circ f'$.
\end{defn}

\begin{lemma}
If $f$ and $f'$ are right invariant derivations of $\mcO(G)$ then so
is 
\[ [f,f']=f\circ f' + f'\circ f + df' \circ df. \]
This gives the set of right invariant derivations of $\mcO(G)$ the
structure of a Lie algebra.
\end{lemma}
\begin{proof}
The fact that $[f,f']$ is a derivation is proved in
Lemma~\ref{le:[f,f']}. The fact that it is right invariant follows from
the fact that each of $f\circ f'$, $f'\circ f$ and $df'\circ df$ are
separately right invariant. The fact that the right invariant
derivations form a Lie algebra now follows from Lemma~\ref{le:[x,y]}.
\end{proof}


\begin{defn}
For a group scheme $G$ in $\CVi$ we define $\Lie(G)$ to be
the Lie algebra in $\CVi$ of right invariant derivations $\mcO(G)\to
\mcO(G)$.
\end{defn}

The following verifies Theorem~\ref{th:main} independently in the case
of $\CVi$.

\begin{prop}
Let $G$ be a group scheme in $\CVi$.
There is a one to one correspondence between right invariant
derivations $\mcO(G)\to \mcO(G)$, elements of the tangent space 
$\Tan_{G,e}=(\mfm/\mfm^2)^*$, and elements of
$\Hom_{\CVAlg}(\mcO(G),\mcE)_e$ in $\CVi$.
\end{prop}
\begin{proof}
Lemma~\ref{le:f:k[S]to-k-ep} shows that if
$f\in\Hom_{\CVAlg}(\mcO(G),\mcE)_e$ then $f$ takes the
form
\[ f(a)= \eta(a)+f'(da)\ep + f'(a)d\ep \]
where $f'\colon \mcO(G)\to k$ is a linear map which takes value zero on
$1$ and on $\mfm_1^2$, and is an $\eta$-derivation in the sense
that it satisfies $f'(ab)=f'(a)\eta(b)+\eta(a)f'(b)$. In particular,
$f'$ can be regarded as a linear map $\mfm/\mfm^2\to k$.
Conversely, given $f'$, the map $f$ defined by $f'$ is an
element of $\Hom_{\CVAlg}(\mcO(G),\mcE)_e$.

Given an $\eta$-derivation $f'\colon \mcO(G)\to k$, we define a
map $F\colon \mcO(G)\to \mcO(G)$ via $F=(f'\otimes 1)\circ\Delta$
\[ \xymatrix{\mcO(G) \ar[r]^(.4)\Delta \ar[d]_F & \mcO(G) \otimes \mcO(G) 
\ar[d]^{f'\otimes\Id} \\ \mcO(G)\ar[r]^(.4)\cong&k\otimes\mcO(G).} \]
First we check right invariance:
\[ \xymatrix{\mcO(G) \ar[r]^(.4)\Delta\ar[d]_\Delta & 
\mcO(G) \otimes \mcO(G) \ar[d]^{\Delta\otimes\Id} \\
\mcO(G) \otimes \mcO(G) \ar[r]^(.4){\Id\otimes\Delta} \ar[d]_{f'\otimes \Id} & 
\mcO(G) \otimes \mcO(G)\otimes \mcO(G)\ar[d]^{f'\otimes \Id\otimes \Id} \\
k\otimes \mcO(G) \ar[r]^(.4){\Id \otimes \Delta} & k \otimes \mcO(G)\otimes \mcO(G)} \]
The upper square commutes by coassociativity of $\Delta$,
and the lower square obviously commutes. Therefore the outer rectangle
commutes, which is the definition of right invariance.

Next, we check that $F\colon \mcO(G)\to \mcO(G)$ is a derivation. Using
Sweedler's notation, we have
\begin{align*}
F(x)&=(f'\otimes \Id)\Delta(x)=f'(x_1)x_2, \\
(dF)(x)&=F(dx)+d(F(x)) \\
&=f'(x_1)dx_2+f'(dx_1)x_2+f'(x_1)dx_2\\
&=f'(dx_1)x_2.
\end{align*}
So
\begin{align*}
F(xy) &=(f'\otimes \Id)\Delta(xy) \\
&=(f'\otimes \Id)\Delta(x)\Delta(y) \\
&=(f'\otimes \Id)(x_1\otimes x_2)(y_1\otimes y_2) \\
&=(f'\otimes \Id)(x_1y_1\otimes x_2y_2+x_1\,dy_1\otimes dx_2\,y_2) \\
&=f'(x_1y_1)x_2y_2+f'(x_1\,dy_1)dx_2\,y_2\\
&=\eta(x_1)f'(y_1)x_2y_2+f'(x_1)\eta(y_1)x_2y_2
+\eta(x_1)f'(dy_1)dx_2\,y_2 \\
&= xF(y)+F(x)y+dx\,(dF)(y).
\end{align*}
This proves that $F$ is a derivation.

Conversely, given a right invariant derivation $F\colon \mcO(G)\to \mcO(G)$,
we define $f'\colon \mcO(G) \to k$ to be the composite $\eta\circ F$.
We check that $f'$ satisfies the properties above, and that 
these are inverse processes.
\end{proof}


\section{Restricted Lie algebras}

This section makes explicit the definitions of
Section~\ref{se:restricted} in the context of $\CVi$.

\begin{defn}\label{def:res-Lie-algebra}
A \emph{restricted Lie algebra} over $\CVi$ is defined
to be  a Lie algebra $L$ over $\CVi$ together with an operation
$x\mapsto x^{[2]}$ defined only on the kernel of $d$, and satisfying
the following identities:
\begin{enumerate}
\item[(i)] If $dx=dy=0$ then $(x+y)^{[2]}=x^{[2]}+y^{[2]}+[x,y]$,
\item[(ii)] If $\lambda\in k$ and $dx=0$, $(\lambda x)^{[2]}=\lambda^2x^{[2]}$
\item[(iii)] If $dx=0$ then $d(x^{[2]})=0$,
\item[(iv)] $[x,x]=(dx)^{[2]}$,
\item[(v)] If $dx=0$ then $[x,[x,y]]=[x^{[2]},y]$.
\end{enumerate}
\end{defn}

\begin{rk}\label{rk:res-Lie-algebra}
This is the translation of Definition~\ref{def:Fresse} into
$\CVi$. The operations $[x,y]$ and $x^{[2]}$ come from the fact that the
space $\Gamma^2L$ is spanned by the elements $x\otimes y + y\otimes x
+ dy\otimes dx$ and the elements $x\otimes x$ with $dx=0$.

Note that condition (iv) of Definition~\ref{def:Lie-algebra} follows
from condition (iv) of Definition~\ref{def:res-Lie-algebra}. This 
should be the case, since by Proposition~\ref{pr:forget}, the
functor of~\eqref{eq:functors} from restricted Lie algebras to operadic Lie
algebras factors through Lie algebras.
\end{rk}

\begin{theorem}\label{th:Ver-reslie}
If $G$ is a group scheme over $\CVi$ then 
$\Lie(G)$ is a restricted Lie algebra over $\CVi$
with $[x,y]=x\circ y+y\circ x+dy\circ dx$ 
and if $dx=0$ then $x^{[2]}=x \circ x$.
\end{theorem}
\begin{proof}
Let $x$ and $y$ be right invariant derivations of $\mcO(G)$.
\newline
(i) If $dx=dy=0$ then $(x+y)\circ(x+y)=x\circ x+y\circ y+[x,y]$.
\newline
(ii) If $dx=0$ then $(\lambda x)^{[2]}=(\lambda x)\circ(\lambda x)=\lambda^2(x\circ x)$.
\newline
(iii) If $dx=0$ then $d(x^{[2]})=d(x\circ x)= dx\circ x + x \circ dx = 0$.
\newline
(iv) $[x,x] = x\circ x + x\circ x + dx\circ dx = dx\circ dx = (dx)^{[2]}$.
\newline
(v) If $dx=0$ then 
\begin{align*}
[x,[x,y]] &= x\circ(x\circ y+y\circ x+dy\circ dx)+(x\circ y+y\circ
x+dy\circ dx)\circ x \\
&\qquad + (dx\circ y+x\circ dy+dy\circ x+y\circ dx)\circ dx \\
&= x\circ x\circ y+y\circ x\circ x =x^{[2]}\circ y + y\circ x^{[2]}= [x^{[2]},y].
\end{align*}
Note that if $dx\ne 0$ then bracketing with $x\circ x$ is not necessarily a
derivation.
\end{proof}

\begin{rk}
Exactly the same computations as in Theorem~\ref{th:Ver-reslie} show
that if $A$ is an associative algebra in 
$\CVi$ then we may define a restricted Lie algebra structure on $A$ by
setting $[x,y]=x.y+y.x+dy.dx$, and if $dx=0$ then $x^{[2]}=x.x$. This
is the dashed functor in Diagram~\eqref{eq:functors}.
\end{rk}

\begin{eg}
Let $\widetilde\bbG_a$ be the additive group scheme in $\CVi$, 
see Example~\ref{eg:Ga}. Then $\Lie(\bbG_a)$
has two basis elements, $e$ dual to $x$ and $f$ dual to $dx$. We have
$df=e$, $de=0$, all brackets are zero, and $e^{[2]}=0$. Since $df\ne
0$, $f^{[2]}$ is not defined. 
\end{eg}

\begin{eg} 
Let $\widetilde\bbG_m$ be the multiplicative group scheme in $\CVi$, see
Example~\ref{eg:Gm}. Then 
$\Lie(\bbG_m)$ has two basis elements, $e$ dual to $x-1$ and $f$ dual to
$dx$. We have $df=e$, $de=0$, all brackets are zero, 
$e^{[2]}=e$, and $f^{[2]}$ is not defined.
\end{eg}

\begin{eg}
Let $\GL(m+n|n)$ be the general linear group scheme in $\CVi$, see
Example~\ref{eg:GL}. Then $\Lie(\GL(m+n|n))$ has a basis consisting of
elements $e_{i,j}$ for $1\le i,j\le m+n$ dual to
$x_{i,j}-\delta_{i,j}$, and elements $f_{i,j}$ for $1\le i,j\le n$
dual to $dx_{i,j}$. We have $df_{i,j}=e_{i,j}$ if $1\le i,j\le n$,
and $de_{i,j}=0$. The brackets are given by
\begin{align*}
[e_{i,j},e_{k,\ell}]&=\delta_{j,k}e_{i,\ell}+\delta_{i,\ell}e_{j,k}\\
[e_{i,j},f_{k,\ell}]&=\delta_{j,k}f_{i,\ell}+\delta_{i,\ell}f_{k,j}\\
[f_{i,j},f_{k,\ell}]&=\begin{cases}
e_{i,j}& \text{if } (i,j)=(k,\ell) \\
\delta_{j,k}e_{i,\ell}+\delta_{i,\ell}e_{k,j}&\text{otherwise.}
\end{cases}
\end{align*}
The square map is given by $e_{i,j}^{[2]}=\delta_{i,j}e_{i,j}$, while
$f_{i,j}^{[2]}$ is not defined.
\end{eg}

\begin{rk}
Let $f\colon k \to k$ be the Frobenius map, given by $f(x) = x^2$.
For an object $A$ in $\CVAlg(k)$ the $r$th
\emph{Frobenius twist} $A^{(r)}$ is defined as the base change 
of $A$ over the Frobenius map: $A^{(r)} = k \otimes_{f^r} A$. 
Note that the $k$-linear map $A^{(r)} \to A$ given by $x\mapsto x^{2^r}$ 
is an algebra homomorphism for $r \ge 2$ but not for
$r=1$, because $(x+y)^2$ is not always equal to $x^2+y^2$. 
See the discussion of the Frobenius twist and the Frobenius kernels in Coulembier and
Sherman~\cite{Coulembier/Sherman:hstc}, and see also Section~6 of
Venkatesh~\cite{Venkatesh:2016a}.  
\end{rk}


