\title{Homogenization of an indefinite spectral problem arising in population genetics}
\author[ad1]{Srinivasan Aiyappan}
\author[ad1]{Aditi Chattaraj}
\author[ad2]{Irina Pettersson\corref{mycorrespondingauthor}}
\cortext[mycorrespondingauthor]{Corresponding author}
