{Under the coercivity and boundedness conditions on the coefficient $a(x_1,y)$, the bilinear forms $a_{x_1}(v,v)=(\mathcal A_y v, v)_{L^2(Y)}$ and $b_{x_1}(v,\varphi)=(\rho(x_1,\cdot)v, \varphi)_{L^2(Y)}$ are Fr\'{e}chet differentiable with respect to $x_1$} (see Theorem 2.4.1 in \cite{komkov1986design}), and the corresponding differentials are
\begin{align*}
a_{\delta x_1}'(v, \varphi)&= \delta x_1 \int_Y \partial_{x_1}a(x_1, y)\nabla v\cdot \nabla \varphi\, dy,\\
b_{\delta x_1}'(v,\varphi)&= \delta x_1 \int_Y \partial_{x_1}\rho(x_1, y)\, v\, \varphi\, dy.
\end{align*}

From the coercivity and differentiability of the bilinear forms it follows that the operator $\mathcal A_y$ (given by its bilinear form) {with the domain $D(\mathcal A_y)$, which is dense in $L^2(Y)$, possesses an inverse $\mathcal A_y^{-1}$ }that is Fr\'echet differentiable (Theorem 2.4.2 in \cite{komkov1986design}). In addition, the operator $B_{x_1}$ defined by the bilinear form $(B_{x_1} v, \varphi)_{L^2(Y)}=(\rho(x_1,\cdot)v, \varphi)_{L^2(Y)}$ is bounded from $L^2(Y)$ into itself, and, thus, is Fr\'echet differentiable with respect to $x_1$. Thus, $\mathcal A_y^{-1} B_{x_1}$ is also Fr\'echet differentiable. The eigenvalue problem \eqref{eq:cell-problem} can be equivalently rewritten as
\begin{align}
\label{eq:equiv-eigenvalue}
\mathcal A_y^{-1} B_{x_1} \Psi = \frac{1}{\mu(x_1)}\Psi.
\end{align}
Then $1/\mu(x_1)$ is continuous with respect to $x_1$, and, furthermore, by Theorem 2.5.2 in \cite{komkov1986design}, since the principal eigenvalue is simple, it is differentiable, and the derivative is given by
\begin{align}
\label{eq:m'}
\mu'(x_1)&= \int_Y \partial_{x_1} a(x_1,y)\nabla_y \Psi(x_1,y)\cdot \nabla_y \Psi(x_1,y)\, dy\\
&-\mu(x_1)\int_Y \partial_{x_1}\rho(x_1,y) \Psi(x_1,y)^2\, dy,\nonumber
\end{align}
where $\Psi$ is the corresponding eigenfunction normalized by $\int_Y \rho \Psi^2\,dy=1$.

Having proved that the eigenvalue $\mu(x_1)$ is differentiable with respect to $x_1$, we conclude that the corresponding eigenfunction is differentiable in $x_1$, as a solution to a boundary value problem with a given $\mu(x_1)$ (see Theorem 2.4.3 in \cite{komkov1986design}). 

% \noindent
% \textbf{Step 4: Lipschitz regularity of $\mu(x_1)$.}\\
Next, we prove the Lipschitz regularity of $\mu(x_1)$. Let us estimate $|\mu(\xi)-\mu(\eta)|$. 
For brevity, for two values $\xi, \eta \in [-1,1]$, we write
\begin{align}
\label{eq:L_xi}
L_{\xi}\Psi_{\xi} &:= -{\rm div}_y(a(\xi, y)\nabla_y \Psi(\xi, y))= \mu(\xi)\rho(\xi,y)\Psi(\xi, y)=:\mu_{\xi} \rho_{\xi} \Psi_{\xi},\\
\nonumber
L_{\eta}\Psi_{\eta} &:= -{\rm div}_y(a(\eta, y)\nabla_y \Psi(\eta, y))
= \mu(\eta)\rho(\eta,y)\Psi(\eta,y)
=:\mu_{\eta} \rho_{\eta} \Psi_{\eta}.
\end{align}
Then
\begin{align}
\label{eq:L_xi_Psi_eta}
L_\xi \Psi_\eta = (L_\xi-L_\eta) \Psi_\eta  + \mu_\eta \rho_\eta \Psi_\eta.
\end{align}
Taking the scalar product of \eqref{eq:L_xi_Psi_eta} with $\Psi_\xi$ in $L^2(Y)$, integrating by parts and using \eqref{eq:L_xi}, we obtain
\begin{align}
\label{eq:aux-1}
\mu_\xi(\rho_\eta \Psi_\eta, \Psi_\xi)_{L^2(Y)}
- \mu_\eta (\rho_\xi \Psi_\eta, \Psi_\xi)_{L^2(Y)}
=
((L_\xi-L_\eta) \Psi_\eta, \Psi_\xi )_{L^2(Y)}.
\end{align}
Using the linear approximations for $a_\eta, \rho_\eta$ and integrating by parts in \eqref{eq:aux-1}, we get
\begin{align}
\label{m_Holder-continuity}
(\mu_\xi-\mu_\eta) (\rho_\xi \Psi_\eta, \Psi_\xi)_{L^2(Y)}
&= 
(\partial_{x_1}a(\zeta, \cdot)(\eta - \xi) \nabla \Psi_\eta, \nabla \Psi_\xi)_{L^2(Y)} \\ 
& + (\partial_{x_1}a(\zeta, \cdot)(\eta - \xi) \nabla \Psi_\eta\cdot n, \Psi_\xi)_{L^2(\Sigma)} \nonumber\\
&- \mu_\eta(\partial_{x_1}\rho(\zeta, \cdot)(\eta - \xi) \Psi_\eta, \Psi_\xi)_{L^2(Y)}.\nonumber
\end{align}
Since $a_{ij}, \rho\in C^{1, \alpha}([-1,1]; C^{0,\alpha}(\overline Y))$, the partial derivatives $\partial_{x_1} a_{ij}, \partial_{x_1}\rho(x_1, y)$ are H\"older continuous on $[-1,1]$ and, thus, uniformly bounded. Moreover, {by the differentiability of $\mu(x_1)$ and $\Psi(x_1, y)$ in $x_1$, the normalization condition $\int_Y \rho \Psi^2\, dy=1$ implies then that for $|\xi-\eta|$ small enough, $\int_Y \rho_\xi \Psi_\xi \Psi_\eta\, dy \ge 1/2$.}
Thus, $\mu$ is Lipschitz continuous:
\begin{align}
\label{eq:est-mu-1}
|\mu(\xi)-\mu(\eta)|\le C |\xi-\eta|.
\end{align}
Differentiating \eqref{eq:cell-problem} with respect to $x_1$, we obtain:
\begin{align}
-&{\rm div}_y(a(x_1,y)\nabla_y (\partial_{x_1}\Psi(x_1, y))) - \mu(x_1) \rho(x_1,y) (\partial_{x_1}\Psi(x_1, y)) \nonumber\\
&\quad= {\rm div}_y (\partial_{x_1}a(x_1,y) \nabla_y \Psi(x_1,y))
+ \mu'(x_1) \rho(x_1, y) \Psi(x_1,y) \nonumber\\
&\qquad+\mu(x_1)\partial_{x_1} \rho(x_1,y) \Psi(x_1,y), \quad &y\in Y, \label{eq:aux-2}\\
&a(x_1, y)\nabla_y (\partial_{x_1}\Psi(x_1, y))\cdot n 
= -\partial_{x_1}a(x_1,y)\nabla \Psi(x_1,y)\cdot n, \quad &y\in \Sigma,\nonumber\\
&y_1 \mapsto \Psi(x_1, y_1, y') \,\mbox{is 1-periodic}.\nonumber
\end{align}
The eigenfunction $\Psi$ is normalized by $\int_Y \rho \Psi^2\, dy =1$ which implies 
\begin{align*}
&\partial_{x_1}\int_Y \rho(x_1,y) \Psi(x_1,y)^2\, dy\\
&= \int_Y \partial_{x_1}\rho(x_1,y) \Psi(x_1,y)^2\, dy
+ 2 \int_Y \rho(x_1,y) \partial_{x_1}\Psi(x_1,y) \Psi(x_1,y)\, dy=0.
\end{align*}
{Further, the compatibility condition for \eqref{eq:aux-2} is satisfied thanks to \eqref{eq:m'}.}
{Due to the elliptic regularity, $\partial_{x_1} \Psi(x_1, \cdot) \in C^{0,\alpha}(\bar Y)\cap H^1(Y)$.}
To prove the H\"older continuity in $x_1$, we estimate the $H^1$-norm of the difference $\Psi(\xi,\cdot)-\Psi(\eta,\cdot)$.
\begin{align*}
L_\xi(\Psi_\xi-\Psi_\eta) &= (L_\eta-L_\xi)\Psi_\eta + \mu_\xi \rho_\xi \Psi_\xi - \mu_\eta\rho_\eta\Psi_\eta,\\
(L_\xi(\Psi_\xi-\Psi_\eta), (\Psi_\xi-\Psi_\eta))_{L^2(Y)} &= ((L_\eta-L_\xi)\Psi_\eta, (\Psi_\xi-\Psi_\eta))_{L^2(Y)}\\
&+ \mu_\xi(\rho_\xi \Psi_\xi, (\Psi_\xi-\Psi_\eta))_{L^2(Y)}\\
&- \mu_\eta(\rho_\eta \Psi_\eta, (\Psi_\xi-\Psi_\eta))_{L^2(Y)}.
\end{align*}
{By the hypotheses (H1)--(H3), the differentiability of the eigenpair proved above, and Lemma \ref{lm:estimate}, we obtain
\begin{align}
\|\Psi_\xi-\Psi_\eta\|_{H^1(Y)}\le C|\xi-\eta|^\alpha.
\end{align}
Combining \eqref{eq:m'} and the above estimate yields that $\mu'(x_1)$ is H\"older continuous. For a given $\mu(x_1)$, $\partial_{x_1} \Psi(x_1,y)$ solves \eqref{eq:aux-2} and thus, by elliptic regularity, belongs to $H^1(Y)\cup C^{0,\alpha}(\bar Y)$. We conclude that $\Psi \in C^{1,\alpha}([-1,1]; C^{0,\alpha}(\bar Y)\cap H^1(Y))$.}


\end{proof}


\section{Proof of Theorem \ref{th:main}}
\label{sec: proof main theorem}
In this section we prove the main result of the paper Theorem \ref{th:main}. First, we perform the factorization of \eqref{orig-prob} with the positive eigenfunction defined in Lemma \ref{lm:existence-mu}. After that we rescale the obtained problem in order to elliminate the singularity. Then the two-scale convergence technique in spaces with singular measure is used to derive the limit problem \eqref{eq:eff-prob}.  
