\subsection{Rescaling}
\label{sec rescaling and apriori estimate}
We change the variables in \eqref{eq:v-eps} setting
$\displaystyle z= \frac{x}{\sqrt{\ve}}$.
With $v^{\ve}(\sqrt{\ve}z) = w^{\ve}(z)$, \eqref{eq:v-eps} becomes
\begin{align}
  \label{eq:rescle-final}
\begin{split}
\begin{cases}
     &\displaystyle 
     -\mathrm{div}(a_{\Psi}^{\ve}(\sqrt{\ve} z)\nabla w^{\ve}(z)) + C_\Psi^{\ve}w^{\ve}(z)\\[2mm]
     \displaystyle
     &\displaystyle+ \frac{\mu(\sqrt{\ve} z_{1}) - \mu(0)}{\ve} \rho_{\Psi}^{\ve}(\sqrt{\ve} z) w^{\ve}(z)
     = \ve \nu^{\ve} \rho_{\Psi}^{\ve}(\sqrt{\ve} z) w^{\ve}(z), \quad z\in \ve^{-\frac{1}{2}}\Omega_\ve,\\[2mm]
  &a_\Psi^\ve(\sqrt{\ve}z)\nabla w^\ve(z) \cdot \nu 
  + w^\ve(z) a^\ve \Psi^\ve \nabla_z \Psi(\sqrt{\ve}z_{1}, y)\big|_{y=z/\sqrt{\ve}} \cdot n =0, \quad \ve^{-\frac{1}{2}}\Sigma_\ve,\\[2mm]
      &w^{\ve}(-\ve^{-1/2},z')=w^{\ve}(\ve^{-1/2},z')=0, \quad z'\in \sqrt{\ve} Q,
      \end{cases}
    \end{split}
\end{align}
where 
\begin{align*}
    &a_{\Psi}^{\ve} (\sqrt{\ve}z) = a_{\Psi} \left( \sqrt{\ve}z_{1}, \frac{z}{\sqrt{\ve}} \right), \quad \rho_{\Psi}^{\ve}(\sqrt{\ve}z) = \rho_{\Psi} \left( \sqrt{\ve}z_{1}, \frac{z}{\sqrt{\ve}} \right),\\
    & 
    C_\Psi^{\ve}(\sqrt \ve z) = \left(- \Psi^{\ve} \mathrm{div}(a  \nabla_{z} \Psi) - \frac{1}{\sqrt{\ve}}\Psi^{\ve} \mathrm{div}_{z}(a \nabla_{\zeta} \Psi)\right)\left( \sqrt{\ve}z_{1}, \frac{z}{\sqrt{\ve}} \right).
\end{align*}
We will derive a priori estimates for the eigenfunctions of \eqref{eq:rescle-final} in terms of a singular measure $d\mu_\ve$ charging the rescaled domain $\ve^{-1/2}\Omega_\ve$.
Let us define a Radon measure on $\mathbb{R}^{d}$ by
\begin{align}
\label{def:mu_eps}
    \mu_{\ve}(B) = \displaystyle \frac{\ve^{-(d-1)/2}}{|Q|}\int_{B} \chi_{\ve^{-\frac{1}{2}} \Omega_{\ve}} \, dx,
\end{align}
for all Borel sets $B$, where $\chi_{\ve^{-\frac{1}{2}} \Omega_{\ve}}$ is the characteristic function on the rescaled domain $\ve^{-\frac{1}{2}} \Omega_{\ve}$. 

Let us choose the normalization in the original domain $\Omega_{\ve}$:
$\int_{\Omega_{\ve}} v_{i}^{\ve} v_{j}^{\ve} \, dx = \ve^{1/2} \ve^{d-1} |Q| \delta_{ij}$.
Then in the rescaled domain, the normalization condition becomes
\begin{align}
\label{eq:norm-cond-rescaled}
    \int_{\ve^{-1/2}\Omega_{\ve}} v_{i}^{\ve}(\sqrt{\ve} z) v_{j}^{\ve}(\sqrt{\ve}z) \, dz = \ve^{(d-1)/2} |Q| \delta_{ij},
\end{align}
and in terms of the singular measure:
\begin{align}
\label{eq:norm-cond-rescaled}
    \int_{\mathbb{R}^{d}} v_{i}^{\ve} v_{j}^{\ve} \, d\mu_{\ve} = \delta_{ij}.
\end{align}

