&+\sqrt{\ve}\int_{\mathbb{R}^{d}} a(x_1,\zeta)\nabla_x\Psi(x_{1}, \zeta)\big|_{x_{1} = \sqrt{\ve}z_{1}, \, \zeta = z/\sqrt{\ve}} \cdot \nabla w^\ve\, w^\ve \Psi(\sqrt{\ve}z) \, d\mu_\ve \nonumber\\
&+\sqrt{\ve}\int_{\mathbb{R}^{d}} a(x_1,\zeta)\nabla_x\Psi(x_{1}, \zeta)\big|_{x_{1} = \sqrt{\ve}z_{1}, \, \zeta = z/\sqrt{\ve}} \cdot w^\ve(z) \nabla w^\ve \Psi(\sqrt{\ve}z) \, d\mu_\ve \nonumber\\
&- \int_{\mathbb{R}^{d}} {\rm div}_x(a(x_1,\zeta) \nabla_\zeta \Psi(x_1,\zeta)) \Psi(x_1, \zeta)\big|_{x_{1}=\sqrt{\ve}z_{1}, \, \zeta = z/\sqrt{\ve}}\, (w^\ve)^2\, d\mu_\ve\\
&+ \int_{\mathbb{R}^{d}}\frac{\mu(\sqrt{\ve}z_1)-\mu(0)}{\ve} \rho_\Psi^\ve(\sqrt{\ve}z) (w^\ve)^2 d\mu_\ve\\
&= 
\ve \nu^\ve \int_{\ve^{-1/2}\Omega_\ve} \rho_\Psi^\ve(\sqrt{\ve}z) (w^\ve)^2\, d\mu_\ve.\nonumber
\end{align}
The right-hand side of the above identity is estimated using Lemma \ref{lm:oscillating-integrals}, the normalization in Lemma \ref{lm:existence-mu}, the estimate for the eigenvalues \eqref{eq:est-nu^eps}, and the normalization condition for $w_i^\ve$:
\begin{align}
    \label{eq:est:RHS}
    \ve \nu^\ve \left|\int_{\ve^{-1/2}\Omega_\ve} \rho_\Psi^\ve(\sqrt{\ve}z) |w^\ve|^2\, dz \right|
    \le C.
\end{align}
Let us estimate the second term in the equality above separately, using the regularity properties of the coefficients and $\Psi(x_1, y)$:
\begin{align*}
& \left|\sqrt{\ve}\int_{\ve^{-1/2}\Omega_\ve} a(x_1,\zeta)\nabla_x\Psi(x_1,\zeta)\big|_{x_{1}=\sqrt{\ve}z_{1}, \, \zeta =z/\sqrt{\ve}} \cdot \nabla(\Psi^\ve(\sqrt{\ve}z))\, (w^\ve(z))^2\, dz \right|\\
&\le
\sqrt{\ve} \left|\int_{\ve^{-1/2}\Omega_\ve} a(x_1,\zeta)\nabla_x\Psi(x_1,\zeta)\big|_{x_{1}=\sqrt{\ve}z_{1}, \, \zeta =z/\sqrt{\ve}} \cdot \nabla_z(\Psi^\ve(\sqrt{\ve}z))\, (w^\ve(z))^2\, dz \right| \\
&+ \left|\int_{\ve^{-1/2}\Omega_\ve} a(x_1,\zeta)\nabla_x\Psi(x_1,\zeta)\big|_{x_{1}=\sqrt{\ve}z_{1}, \, \zeta
 =z/\sqrt{\ve}} \cdot \nabla_\zeta \Psi^\ve(\sqrt{\ve}z)\, (w^\ve(z))^2\, dz \right|\\
&\le 
C_1\ve \int_{\ve^{-1/2}\Omega_\ve} |w^\ve|^2\, dz
+ C_2\int_{\ve^{-1/2}\Omega_\ve}|w^\ve|^2\, dz\le C_0 \int_{\ve^{-1/2}\Omega_\ve}|w^\ve|^2\, dz.
\end{align*}
This shows that this term does not vanish, as $\ve \to 0$, and, thus, we shift the spectrum by adding $C_0 \|w^\ve\|_{L^2(\ve^{-1/2}\Omega_\ve)}^2$ to both sides of the weak formulation for the rescaled equation. 

As $\rho_{\Psi}^{\ve}(\sqrt{\ve}z)$ is sign-changing, we cannot estimate the term containing $(\mu(\sqrt{\ve} z_1) - \mu(0))$ directly from below. Then we will use the following mean-value theorem to estimate this term, using Corollary \eqref{corollary_two scale_average}
{\begin{align*}
    &\int_{\mathbb{R}^{d}} %\chi_{\ve^{-\frac{1}{2}} \Omega_{\ve}}
    \frac{(\mu(\sqrt{\ve}z_{1}) - \mu(0))}{\ve} \rho_{\Psi}^{\ve}(\sqrt{\ve}z) (w^{\ve}(z))^{2} \, d \mu_{\ve}\\
    &~~~~~ -\int_{\mathbb{R}^{d}} \frac{(\mu(\sqrt{\ve}z_{1}) - \mu(0))}{\ve} \Big( \int_{Y} \rho_{\Psi}^{\ve}(\sqrt{\ve}z_{1},\zeta) \, d\zeta \Big) (w^{\ve}(z))^{2} \, d \mu_{\ve}\\
    &= O(\sqrt{\ve} \|w^{\ve}\|_{L^{2}(\mathbb{R}^{d}, \mu_{\ve})} \| \nabla w^{\ve}\|_{L^{2}(\mathbb{R}^{d}, \mu_{\ve})}).
\end{align*}}
By \textbf{(H5)},
\begin{align*}
    \mu(\sqrt{\ve}z_{1}) - \mu(0) = \frac{1}{2} \mu''(0)(\sqrt{\ve}|z_{1}|)^{2} + o(|\sqrt{\ve}z_{1}|^{2}).
\end{align*}
Since we do not know yet that $w^{\ve}$ is localized, Taylor's expansion cannot be used to obtain an estimate for the remainder. Instead, we will use a quadratic equivalence, a forward consequence to Taylor's theorem. 
We substitute $(\mu(\sqrt{\ve}z_{1}) - \mu(0)) \Big( \int_{Y} \rho_{\Psi}^{\ve}(\sqrt{\ve}z_{1},\zeta) \, d\zeta \Big)$ with the equivalent quadratic function $\frac{\mu''(0)}{2} (\sqrt{\ve} |z_{1}|)^{2}$ in the weak formulation \eqref{eq:weak-w_eps-measure}.

Finally, by the coercivity of $a$ and the regularity properties of $\Psi$, we derive \eqref{eq:estimate}. Note that the estimate {$\|z_{1} w_{\ve}\|_{L^{2}(\mathbb{R}^{d}, \mu_{\ve})} \leq C$ implies $\|w_{\ve}\|_{L^{2}(\mathbb{R}^{d}, \mu_{\ve})} \leq C$ because of the growing weight $|z_{1}|$.} }
\end{proof}
The proof of the following lemma can be found in \cite{pettersson2017two}, \cite{PaPe-ApplicAnal-2014}.
\begin{lemma} 
Under conditions in Lemma \ref{lm:a priori est w_eps}, there exists $w \in H^{1}(\mathbb{R}^{d},\mu^{*})$ such that
\begin{align*}
&w^{\ve}\overset{2}{\rightharpoonup} w(z_{1},0) \quad \text{in } L^{2}(\mathbb{R}^{d}, \mu_{\ve}),\\
&\nabla w^{\ve} \overset{2}{\rightharpoonup}
\nabla^{\mu^{*}}w(z_{1},0) + \nabla_{\zeta} w^{1}(z_{1},\zeta) \quad \text{in } L^{2}(\mathbb{R}^{d},\mu_{\ve}),
\end{align*}
where $w^{1}(z_{1},\zeta) \in L^{2}(\mathbb{R}; H^{1}(Y))$ is $1$-periodic in $\zeta_{1}$.
\end{lemma}

\subsection{Passage to the limit in \eqref{eq:weak-w_eps}}
\label{sec passage of limit}

Recall the weak formulation of the rescaled problem \eqref{eq:rescle-final}:
\begin{align}
\label{eq:weak-w_eps-measure-1}
&\int_{\mathbb{R}^{d}} a_\Psi^\ve(\sqrt{\ve}z) \nabla w^\ve(z) \cdot \nabla \varphi(z)\, d\mu_\ve \nonumber\\
&+\sqrt{\ve}\int_{\mathbb{R}^{d}} a(x_1,\zeta)\nabla_x\Psi(x_1, \zeta )\big|_{x_{1}=\sqrt{\ve}z_{1}, \, \zeta =z/\sqrt{\ve}} \cdot \nabla\Psi^\ve(\sqrt{\ve}z)\, w^\ve(z) \varphi(z)\, d\mu_\ve \nonumber\\
&+\sqrt{\ve}\int_{\mathbb{R}^{d}} a(x_1,\zeta)\nabla_x\Psi(x_1,\zeta)\big|_{x_{1}=\sqrt{\ve}z_{1}, \, \zeta =z/\sqrt{\ve}} \cdot \nabla w^\ve(z) \varphi(z) \Psi^\ve(\sqrt{\ve}z) \, d\mu_\ve \nonumber\\
&+\sqrt{\ve}\int_{\mathbb{R}^{d}} a(x_1,\zeta)\nabla_x\Psi(x_1,\zeta)\big|_{x_{1}=\sqrt{\ve}z_{1}, \, \zeta =z/\sqrt{\ve}} \cdot w^\ve(z) \nabla \varphi(z)\Psi^\ve(\sqrt{\ve}z) \, d\mu_\ve \nonumber\\
&- \int_{\mathbb{R}^{d}} {\rm div}_x(a(x_1,\zeta) \nabla_\zeta
\Psi(x_1,\zeta)) \Psi(x_1, \zeta)\big|_{x_{1}=\sqrt{\ve}z_{1}, \, \zeta =z/\sqrt{\ve}}\, w^\ve(z)\, \varphi(z)\, d\mu_\ve\\
&+ \int_{\mathbb{R}^{d}}\frac{\mu(\sqrt{\ve}z_1)-\mu(0)}{\ve} \rho_\Psi^\ve(\sqrt{\ve}z) w^\ve(z)\,\varphi(z) d\mu_\ve \nonumber\\
&= 
\ve \nu^\ve \int_{\mathbb{R}^{d}} \rho_\Psi^\ve(\sqrt{\ve}z) w^\ve(z) \varphi(z)\, d\mu_\ve,\nonumber
\end{align}
\noindent
for all $\phi \in H^{1}(\ve^{-1/2}\Omega_\ve)$ such that $\phi(-1/\sqrt \ve, z')=\phi(1/\sqrt \ve, z')=0$.

\noindent
\textbf{Step 1.}\\
Choose a test function $\Phi_{\ve} = \ve^{1/2} \phi(z) \psi(\frac{z}{\ve^{1/2}})$ in \eqref{eq:weak-w_eps-measure-1}, where $\phi \in C_{0}^{\infty}(\mathbb{R}^{d})$, $\psi \in C^{\infty}(\overline{Y})$.
The gradient of the test function is
\begin{align*}
    \nabla \Phi_{\ve} = \ve^{1/2} \psi(\frac{z}{\ve^{1/2}}) \nabla \phi(z) + \phi(z) \nabla_{\zeta} \psi(\zeta)\Big|_{\zeta = z/\ve^{1/2}}.
\end{align*}
The limit of the first term in \eqref{eq:weak-w_eps} is
\begin{align*}
    &\lim_{\ve \rightarrow 0} \int_{\mathbb{R}^{d}} a_{\Psi}^{\ve}(\sqrt{\ve}z) \nabla w^{\ve}(z) \cdot \nabla \Phi^{\ve}(z) \, d\mu_{\ve}\\
    &= \frac{1}{|Y|} \int_{\mathbb{R}^{d}} \left( \int_{Y} a_{\Psi}(0,\zeta)\left (\nabla^{\mu^{*}}w(z_{1},0) + \nabla_{\zeta} w^{1}(z_{1},\zeta) \right) \cdot \nabla_{\zeta} \psi(\zeta) \, d\zeta\right) \phi(z_{1},0) \, d\mu^{*}.
\end{align*}
{The limit of the next four terms is zero} due to the regularity properties of $\Psi$ and the small factor $\sqrt \ve$ in the test function.
The sixth term can be proved to go to zero by using Corollary 1 in \cite{PaPe-ApplicAnal-2014}. Indeed,
\begin{align*}
    &\int_{\mathbb{R}^{d}} \frac{\mu(\sqrt{\ve}z_{1}) - \mu(0)}{\ve} \rho_{\Psi}^{\ve}(\sqrt{\ve}z) w^{\ve} \Phi^{\ve}(z) \, d\mu_{\ve}\\
    &\\
    &= \displaystyle  \frac{\sqrt{\ve}}{|Y|}\int_{\mathbb{R}^{d}} \frac{\mu(\sqrt{\ve}z_{1}) - \mu(0)}{\ve} \left( \int_{Y} \rho_{\Psi}(\sqrt{\ve} z_{1}, \zeta) \psi(\zeta) \, d\zeta \right) w^{\ve} \phi(z) \, d\mu_{\ve} + O(\sqrt{\ve})\\
    &\\
    &= \displaystyle \frac{\sqrt{\ve} \mu''(0)}{2|Y|} \int_{\mathbb{R}^{d}} |z_{1}|^{2} \left( \int_{Y} \rho_{\Psi}(\sqrt{\ve} z_{1}, \zeta) \psi(\zeta) \, d\zeta \right) w^{\ve} \phi(z) \, d\mu_{\ve} \\[2mm]
    &~~~~~~~~~~~~~~~+  \frac{\sqrt{\ve}}{|Y|} \int_{\mathbb{R}^{d}} \frac{o(\ve |z_{1}|^{2})}{2\ve} \left( \int_{Y} \rho_{\Psi}(\sqrt{\ve} z_{1}, \zeta) \psi(\zeta) \, d\zeta \right) w^{\ve} \phi(z) \, d\mu_{\ve} + O(\sqrt{\ve}).
\end{align*}
Since $\phi$ has a compact support in $z_1$, $o(\ve |z_1|^2)=o(\ve)$ as $\ve \to 0$. Therefore
\begin{align*}
    &\left| \int_{\mathbb{R}^{d}} \frac{\mu(\sqrt{\ve}z_{1}) - \mu(0)}{\ve} \rho_{\Psi}^{\ve}(\sqrt{\ve}z) w^{\ve} \Phi^{\ve}(z) \, d\mu_{\ve} \right|\\
    &\leq \left| \frac{\sqrt{\ve} \mu''(0)}{2 |Y|}\int_{\mathbb{R}^{d}} |z_{1}|^{2} \left( \int_{Y} \rho_{\Psi}(\sqrt{\ve} z_{1}, \zeta) \psi(\zeta) \, d\zeta \right) w^{\ve} \phi(z) \, d\mu_{\ve}  + O(\sqrt{\ve}) \right| \le C \sqrt{\ve}.
\end{align*}
As for the right-hand side of the weak formulation \eqref{eq:weak-w_eps-measure-1}, it is estimated by using the bound for the eigenvalues \eqref{eq:est-nu^eps}:
\begin{align*}
    &\left| \ve \nu^{\ve} \int_{\mathbb{R}^{d}} \rho_{\Psi}^{\ve}(\sqrt{\ve}z) w^{\ve} \Phi^{\ve}(z) \, d\mu_{\ve} \right|
    \le C \sqrt{\ve}.
\end{align*}
Passing limit as $\ve \rightarrow 0$ in \eqref{eq:weak-w_eps-measure-1}, we obtain a problem for $w^1$:
\begin{align}
\label{limit_rescle_Phi^(ve)}
    \int_{\mathbb{R}^{d}} \left( \int_{Y} a_{\Psi}(0,\zeta)\left (\nabla^{\mu^{*}}w(z_{1},0) + \nabla_{\zeta} w^{1}(z_{1},\zeta) \right) \cdot \nabla_{\zeta} \psi(\zeta) \, d\zeta\right) \phi(z_{1},0) \, d\mu^{*} = 0.
\end{align}
We are looking for the solution in the form $w^{1}(z_{1}, \zeta) = N(\zeta) \cdot \nabla^{\mu^{*}} w(z_{1},0)$, where $N: Y \to \mathbb{R}^d$ are periodic in $\zeta_1$ solving
\begin{align*}
    &\int_{Y} a_{\Psi}(0,\zeta) \nabla_{\zeta} N_{j}(\zeta) \cdot \nabla_{\zeta} \psi(\zeta) \, d\zeta = - \int_{Y} (a_{\Psi})_{kj} \partial_{\zeta_{k}} \psi(\zeta)) d\zeta.
\end{align*}
The last integral identity yields the problem for $N_j$ in its strong form:
\begin{align}
\label{rescle_cell_problem}
    \begin{cases}
        &-\displaystyle \mathrm{div}(a_{\Psi}(0,\zeta) \nabla_{\zeta} N_{j}(\zeta)) = \partial_{\zeta_{k}} (a_{\Psi})_{kj} (0,\zeta) \quad \text{in } Y\\
        &a_{\Psi}(0,\zeta) \nabla_{\zeta} N_{j}(\zeta) \cdot n = - (a_{\Psi})_{kj} (0, \zeta) n_{k} \quad \text{on } \Sigma, \\
        & N_{j}(\cdot, \zeta')\,\, \mbox{is}\,\, 1-\mbox{periodic}, \quad j=1,2,\ldots, d.
    \end{cases}
\end{align}
In this way, we have the following convergence
\begin{align*}
    &\nabla w^{\ve}(z) \overset{2}{\rightharpoonup} \left( I + \nabla N(\zeta) \right) \nabla^{\mu^{*}} w(z_{1},0) ~~ \text{as } \ve \rightarrow 0.
    \end{align*}
 We proceed with deriving the effective problem for the limit function $w$.\\

\noindent
\textbf{Step 2:}
\noindent 
Let us take a test function $\varphi\in C_{0}^{\infty}(\mathbb{R}; C^{\infty}(\ve^{1/2}Q))$ in \eqref{eq:weak-w_eps-measure-1}
\begin{align}
\label{eq:weak-pass-limit}
\begin{split}
      &\int_{\mathbb{R}^{d}} a_{\Psi}^{\ve}(\sqrt{\ve}z) \nabla w^{\ve} \cdot \nabla \varphi \, d\mu_{\ve}  + \int_{\mathbb{R}^{d}}  (a^{\ve} \nabla_{z} \Psi^{\ve} \cdot \nabla(\Psi^{\ve} w^{\ve} \varphi) \, d\mu_{\ve}\\
      &- \int_{\mathbb{R}^{d}} \Psi^{\ve} \mathrm{div}_{z} (a^{\ve} \nabla_{\zeta} \Psi^{\ve} ) w^{\ve} \varphi(z) \, d\mu_{\ve}\\
    &+ \int_{\mathbb{R}^{d}} \frac{\mu(\sqrt{\ve}z_{1}) - \mu(0)}{\ve} \rho_{\Psi}^{\ve}(\sqrt{\ve}z) w^{\ve} \varphi(z) \, d\mu_{\ve}\\
    &~= \ve \nu^{\ve} \int_{\mathbb{R}^{d}} \rho_{\Psi}^{\ve}(\sqrt{\ve}z) w^{\ve} \varphi(z) \, d\mu_{\ve}.
\end{split}
\end{align}
The first term in \eqref{eq:weak-pass-limit}, as $\ve \to 0$,  yields
 \begin{align*}
     &\lim_{\ve \rightarrow 0} \int_{\mathbb{R}^{d}} a_{\Psi}^{\ve}(\sqrt{\ve}z) \nabla w^{\ve}(z) \cdot \nabla \varphi(z) \, d\mu_{\ve}\\
     &~~~= \frac{1}{|Y|} \int_{\mathbb{R}^{d}} \left( \int_{Y} a_{\Psi}(0,\zeta) \left( I + \nabla N(\zeta) \right) \, d\zeta\right) \nabla^{\mu^{*}} w(z_{1},0) \cdot \nabla \varphi(z_{1},0) \, d\mu^{*}\\
     &~~~= \int_{\mathbb{R}^{d}} A^{\text{eff}} \nabla^{\mu^{*}} w(z_{1},0) \cdot \nabla \varphi(z_{1},0) \, d\mu^{*},
 \end{align*}
where we denote
 \begin{align*}
     % &A^{\text{eff}} = \frac{1}{|Y|} \int_{Y} a_{\Psi}(0,\zeta) \left( I + \nabla N(\zeta) \right) \, d\zeta. \\
     &A_{ij}^{\text{eff}} = \frac{1}{|Y|} \int_{Y}(a_{\Psi})_{ik}(0,\zeta) \left(  \delta_{kj} + \partial_{\zeta_{k}} N_{j}(\zeta) \right) \, d \zeta.
 \end{align*}
The fourth term in  \eqref{eq:weak-pass-limit}:
 \begin{align*}
     &\int_{\mathbb{R}^{d}} \frac{\mu(\sqrt{\ve}z_{1}) - \mu(0)}{\ve} \rho_{\Psi}^{\ve}(\sqrt{\ve}z) w^{\ve} \varphi(z) \, d\mu_{\ve}\\
     &= \frac{1}{|Y|} \int_{\mathbb{R}^{d}} \frac{\mu(\sqrt{\ve}z_{1}) - \mu(0)}{\ve} \left(\int_{Y} \rho_{\Psi}(0,\zeta) \, d\zeta\right) w^{\ve} \varphi(z) \, d\mu_{\ve}\\
     &+ O(\sqrt{\ve} \|w^{\ve}\|_{L^{2}(\mathbb{R}^{d},\mu_{\ve})} \|\nabla w^{\ve}\|_{L^{2}(\mathbb{R}^{d},\mu_{\ve})} )\\
     &= \frac{1}{|Y|} \int_{\mathbb{R}^{d}} \frac{\mu(\sqrt{\ve}z_{1}) - \mu(0)}{\ve} \left(\int_{Y} \rho_{\Psi}(\sqrt{\ve}z_{1},\zeta) \, d\zeta\right) w^{\ve} \varphi(z) \, d\mu_{\ve}+ O(\sqrt{\ve}).
 \end{align*}
  Writing the Taylor expansions for $\mu(\sqrt{\ve}z_{1})$ and $\langle \rho_{\Psi}(\sqrt{\ve}z_{1} , \cdot) \rangle$ we obtain, as $\ve|z_1|^2 \to 0$:
  \begin{align*}
      &\mu(\sqrt{\ve}z_{1}) = \mu(0) + \ve z_{1}^{2} \mu''(0) + o(\ve |z_{1}|^{2}),\\
      &\langle \rho_{\Psi}(\sqrt{\ve}z_{1}, \cdot) \rangle = \langle \rho_{\Psi}(0, \cdot) \rangle + \sqrt{\ve}z_{1} \langle \partial_{z_{1}} \rho_{\Psi}(0, \cdot) \rangle + \frac{\ve |z_{1}|^{2}}{2} \langle \partial_{z_{1}}^{2} \rho_{\Psi}(0, \cdot) \rangle + o(\ve |z_{1}|^{2}).
  \end{align*}
  By the Lebesgue dominated convergence theorem, since the test function has compact support,
  \begin{align*}
      &\lim_{\ve \rightarrow 0} \int_{\mathbb{R}^{d}} \frac{\mu(\sqrt{\ve}z_{1}) - \mu(0)}{\ve} \rho_{\Psi}^{\ve}(\sqrt{\ve}z) w^{\ve} \varphi(z) \, d\mu_{\ve}\\
      &= \frac{\mu''(0)}{2} \langle \rho_{\Psi}(0, \cdot) \rangle \int_{\mathbb{R}^{d}} |z_{1}|^{2} w(z_{1},0) \varphi(z_{1},0) \, d\mu^{*}.
   \end{align*}
As for the terms 2-4 in \eqref{eq:weak-w_eps-measure-1} coming from $C^\ve$, we see that the only one that contributes to the limit is the one containing $\nabla_\zeta \Psi$ (in the second term). 
\begin{align*}
    &\lim_{\ve \rightarrow 0} \sqrt{\ve} \int_{\mathbb{R}^{d}}  a(x_{1}, \zeta) \nabla_{x} \Psi(x_{1}, \zeta)\big|_{x_{1} = \sqrt{\ve}z_{1}, \, \zeta = z/\sqrt{\ve}} \cdot \frac{1}{\sqrt{\ve}} (\nabla_{\zeta} \Psi)(\sqrt{\ve}z)  \, w^{\ve}(z) \varphi(z)   \, d\mu_{\ve}\\
    &= \frac{1}{|Y|}\int_{\mathbb{R}^{d} \times Y} (a\nabla_{x} \Psi) (0, \zeta) \cdot \nabla_{\zeta} \Psi(0, \zeta)\, w(z_{1}) \varphi(z_{1},0) \, d\zeta\, d\mu^{*};\\
    &\\
    &\lim_{\ve \rightarrow 0} \int_{\mathbb{R}^{d}} \Psi(x_{1}, \zeta)\,  \mathrm{div}_{x} (a(x_{1}, \zeta) \nabla_{\zeta} \Psi(x_{1}, \zeta))\big|_{x_{1} = \sqrt{\ve}z_{1}, \, \zeta = z/\sqrt{\ve} }  \, w^{\ve}(z) \varphi(z) \, d\mu_{\ve} \\
    &= \frac{1}{|Y|}\int_{\mathbb{R}^{d} \times Y} \Psi (0, \zeta) \mathrm{div}_{x}(a \nabla_{\zeta} \Psi)(0, \zeta) \, w(z_{1}) \varphi(z_{1},0) \, d\zeta\, d\mu^{*}.
     \end{align*}
Denote    
\begin{align*}
        c^{\text{eff}} = \frac{1}{|Y|}\int_{Y}\Big( (a \nabla_{x} \Psi)(0,\zeta) \cdot \nabla_{\zeta}\Psi(0, \zeta) - \mathrm{div}_{x}(a \nabla_{\zeta} \Psi)(0, \zeta) \Psi(0, \zeta) \Big)\, d\zeta.
\end{align*}
The limit of the right-hand side of the weak formulation \eqref{eq:weak-w_eps-measure-1} is
    \begin{align*}
        &\displaystyle \lim_{\ve \rightarrow 0} \ve \nu^{\ve} \int_{\mathbb{R}^{d}} \rho_{\Psi}^{\ve} (\sqrt{\ve}z ) w^{\ve}(z) \varphi(z) \, d\mu_{\ve}
        = \nu \langle \rho_{\Psi}(0, \cdot) \rangle \int_{\mathbb{R}^{d}} w(z_{1},0) \varphi(z_{1}, 0) \, d\mu^{*}.
    \end{align*}
Finally, passing to the limit of the weak formulation \eqref{eq:weak-w_eps-measure-1} we have
\begin{equation}
\label{limit_rescaled_weak form}
\begin{aligned}
&\int_{\mathbb{R}^{d}} A^{\text{eff}} \nabla^{\mu^{*}} w(z_{1},0) \cdot \nabla \phi(z_{1},0) \, d\mu^{*}\\
&+ \frac{\mu''(0)}{2} \langle \rho_{\Psi}(0, \cdot) \rangle \int_{\mathbb{R}^{d}} |z_{1}|^{2} w(z_{1},0) \varphi(z_{1},0) \, d\mu^{*}\\
&+ \int_{\mathbb{R}^{d}} c^{\text{eff}} w(z_{1},0) \phi(z_{1},0) \, d\mu^{*} = \nu \langle \rho_{\Psi}(0, \cdot) \rangle \int_{\mathbb{R}^{d}} w(z_{1},0) \varphi(z_{1}, 0) \, d\mu^{*}.
\end{aligned}
\end{equation}
Take any test function with zero trace $\varphi(z_{1},0, \ldots, 0) = 0$ and a non-zero $\mu^{*}$-gradient, \textit{e.g.} $\varphi(z) = \displaystyle \sum_{j \neq 1} z_{j} \psi(z_{1})$, with arbitrary $\psi \in C_{c}^{\infty}(\mathbb{R})\setminus\{0\}$. Then
\begin{align*}
&\varphi(z) = z \cdot \Big(0, \psi_{2}(z_{1}), \ldots, \psi_{d}(z_{1}) \Big), ~~\varphi(z_{1}, 0, \ldots,0) = 0,\\ &\nabla\varphi(z) = \displaystyle \Big(\sum_{j \neq 1} z_{j}\psi_{j}'(z_{1}), \psi_{2}(z_{1}), \ldots, \psi_{d}(z_{1}) \Big),\\ 
&\nabla^{\mu^{*}} \varphi(z) = \nabla\varphi(z_{1}, 0, \ldots, 0) = \Big(0, \psi_{2}(z_{1}), \ldots, \psi_{d}(z_{1}) \Big).
\end{align*}
By the density of $C_{c}^{\infty}(\mathbb{R}^{d})$ in $L^{2}(\mathbb{R}^{d})$, we can take $\psi_{j} \in L^{2}(\mathbb{R}^{d})$. Taking this test function in \eqref{limit_rescaled_weak form} gives
\begin{align*}
    \int_{\mathbb{R}^{d}} A^{\text{eff}} \nabla^{\mu^{*}} w(z_{1},0) \cdot \Big(0, \psi_{2}(z_{1}), \ldots, \psi_{d}(z_{1}) \Big) \, d\mu^{*} = 0
\end{align*}
which implies
\begin{align*}
&A^{\text{eff}} \nabla^{\mu^{*}} w(z_{1},0) = \Big( \displaystyle \sum_{j=1}^{d} A_{1j}^{\text{eff}} \partial_{z_{j}}^{\mu^{*}} w(z_{1},0), 0, \ldots, 0 \Big).
\end{align*}
\noindent
Let us reformulate the equation for $N_{k}$ in the following form:
\begin{equation}
\label{rescaled_cell_problem}
\begin{aligned}
    -&\mathrm{div}(a_{\Psi}(0, \zeta) \nabla (N_{k}(\zeta) + \zeta_{k})) = 0, \quad y\in Y\\
    &a_{\Psi}(0, \zeta) \nabla (N_{k} + \zeta_{k}) = 0, \quad y\in \Sigma,\\
    &N_k(\cdot, \zeta') \,\, \mbox{is} \,\, 1-\mbox{periodic}.
\end{aligned}
\end{equation}
Multiplying \eqref{rescaled_cell_problem} by $\zeta_{m}$ for $m\neq 1$ ($\zeta_{m}$  is then $1$-periodic in $\zeta_{1}$ and thus it can be used as a test function), and integrating by parts over $Y$, we obtain
\begin{align*}
    \int_{Y} a_{\Psi}(0, \zeta) \nabla (N_{k}(\zeta) + \zeta_{k}) \cdot \nabla \zeta_{m} \, d\zeta = 0,
\end{align*}
which yields
\begin{align*}
&0= \int_{Y} \displaystyle \sum_{j = 1}^{d} (a_{\Psi})_{mj}(0, \zeta) (\partial_{\zeta_{j}}N_{k} + \delta_{jk}) \, d\zeta = A_{mk}^{\text{eff}}, \quad m \neq 1.
\end{align*}
Then the weak formulation of the limit problem \eqref{limit_rescaled_weak form} becomes
 \begin{align*}
&\int_{\mathbb{R}^{d}} A_{11}^{\text{eff}} \partial_{z_{1}}^{\mu^{*}} w(z_{1},0) \partial_{z_1} \phi(z_{1},0) \, d\mu^{*} + \frac{\mu''(0)}{2} \langle \rho_{\Psi}(0, \cdot) \rangle \int_{\mathbb{R}^{d}} |z_{1}|^{2} w(z_{1},0) \phi(z_{1},0) \, d\mu^{*} \nonumber\\
&~~~+ \int_{\mathbb{R}^{d}} c^{\text{eff}} w(z_{1},0) \phi(z_{1},0) \, d\mu^{*} = \nu \langle \rho_{\Psi}(0, \cdot) \rangle \int_{\mathbb{R}^{d}} w(z_{1},0) \phi(z_{1}, 0) \, d\mu^{*}.
 \end{align*}
Choosing $N_{i}$ as a test function in the cell problem of $N_{k}$ we have
\begin{align*}
    &\int_{Y} a_{\Psi}(0,\zeta) \nabla_{\zeta} ( N_{k} + \zeta_{k}) \cdot \nabla_{\zeta} N_{i} \, d\zeta = 0,
\end{align*}
then $A_{ik}^{\text{eff}}$ can be written as 
\begin{align*}
    A_{ik}^{\text{eff}} = \int_{Y} a_{\Psi}(0, \zeta) \nabla_{\zeta}(N_{k} + \zeta_{k}) \cdot \nabla_{\zeta}(N_{i} + \zeta_{i}) \, d\zeta
\end{align*}
which gives
\begin{align*}
A_{11}^{\text{eff}} = A^{\text{eff}} e_{1} \cdot e_{1}
& = \frac{1}{|Y|} \int_{Y} a(0, \zeta) \nabla(\zeta_{1} + N_{1}(\zeta)) \cdot \nabla(\zeta_{1} + N_{1}(\zeta)) \, d\zeta\\ 
&\ge \frac{\Lambda}{|Y|} \int_{Y} | \nabla(\zeta_{1} + N_{1}(\zeta)) |^{2} \, d\zeta.
\end{align*}
Assuming that $\partial_{\zeta_{i}}(\zeta_{1} + N_{1}(\zeta)) = 0$, for all $i$ leads to the contradiction since $N_{1}$ is periodic in $\zeta_{1}$. Thus, the effective coefficient is strictly positive.

Denoting $a^{\text{eff}} := A_{11}^{\text{eff}}$, $w(z_{1}) := w(z_{1}, 0)$, the last integral identity is  the weak formulation of the harmonic oscillator equation on $\mathbb R$:
\begin{align}
\label{limit_rescled_prob}
    &-a^{\text{eff}} w'' + \left( \frac{\mu''(0)}{2} \langle \rho_{\Psi}(0, \cdot) \rangle |z_{1}|^{2} + c^{\text{eff}} \right) w
    = \nu \langle \rho_{\Psi}(0, \cdot) \rangle w
,\quad w \in L^{2}(\mathbb{R}).
\end{align}
Due to the normalization condition and the strong convergence of $w^{\ve}$ in $L^{2}(\mathbb{R}^{d}, \mu_{\ve})$ (see Lemma \ref{lm:compactness}), the limit function $w(z_{1}) \neq 0$. Thus, $(\nu, w(z_{1}))$ is an eigenpair of the effective spectral problem \eqref{limit_rescled_prob}.
\begin{remark}
    The eigenpairs $(\nu_{j}, w_{j})$ of the Sturm-Liouville problem
    \begin{align*}
        -a^{\text{eff}} w'' + \left( \frac{\mu''(0)}{2} \langle \rho
        _{\Psi}(0, \cdot)\rangle |z_{1}|^{2} + c^{\text{eff}} \right) w = \nu \langle \rho_{\Psi}(0, \cdot) \rangle w, \quad w \in L^{2}(\mathbb{R})
    \end{align*}
    admit explicit representation: 
    \begin{align*}
    &\nu_{j}  = \big(c^{\text{eff}} + (2j - 1) \sqrt{\frac{a^{\text{eff}} \mu''(0)}{2}}\big)/\langle \rho_{\Psi}(0, \cdot) \rangle,\\
    &
    w_{j}(z_{1}) = {H_{j}(\theta^{1/4} z_{1})} e^{-\sqrt{\theta}z_{1}^{2}/2}, \,\, j = 1,2, \ldots,
    \end{align*}
    where $\displaystyle\theta = \frac{\mu''(0)}{2a^{\text{eff}}}$ and $\displaystyle H_{j}(x) = e^{x^{2}} \frac{d^{j-1}}{dx^{j-1}} e^{-x^{2}}$ are the Hermite polynomials. Note that the eigenvalues $\nu_j$ are simple \cite{Bohm1986}.
\end{remark}
\section{Convergence of spectra}
\label{sec convergence of spectra}

In this section we will show that the $j$th eigenvalue of the rescaled problem \eqref{eq:rescle-final} converges to the $j$th eigenvalue of the homogenized problem \eqref{limit_rescled_prob}, as well as the convergence of the corresponding eigenfunctions. 
\begin{lemma}
    For sufficiently small $\ve$, along a subsequence, the eigenvalues $\ve \nu_j^\ve$ of problem \eqref{eq:rescle-final} are simple.
\end{lemma}
\begin{proof}
{Suppose that some eigenvalue $\ve \nu^{\ve}$ of \eqref{eq:rescle-final} has multiplicity at least two for all $\ve>0$, i.e. there exist two linearly independent eigenfunctions $v_{1}^{\ve}$, $v_{2}^{\ve}$ corresponding to $\ve \nu^{\ve}$. Let us normalize the eigenfunctions by $\int_{\mathbb R^d} v_1^\ve v_2^\ve\, d\mu_\ve = \delta_{ij}$. By the strong $L^2$-compactness, $v_{1}^{\ve}$ and $v_{2}^{\ve}$, extended by zero to $\mathbb R \times \ve^{1/2} Q$, converge strongly in $L^{2}(\mathbb{R}^{d}, \mu_\ve)$ to the eigenfunctions $v_1, v_2$ of the limit problem corresponding to some eigenvalue $\nu^{*}$. Passing to the limit in the normalization condition yields $\int_{\mathbb R} v_1\, v_2\, dx =0$.
Since the eigenvalues of the one-dimensional limit problem are simple, $v_{1}$, $v_{2}$ should be linearly dependent, which leads to a contradiction.
}
\end{proof}

The next lemma shows that the convergence of eigenvalues, as $\ve \to 0$, preserves the order.
\begin{lemma}
   For any $j$, the $j$th eigenvalue $\nu_{j}^{\ve}$ of problem \eqref{eq:rescle-final} converges to the $j$th eigenvalue $\nu_{j}$ of \eqref{limit_rescled_prob}, and the corresponding eigenfunction $w_j^\ve$ converges, along a subsequence, to the eigenfunction $w_j$ of \eqref{limit_rescled_prob}.  
\end{lemma}
\begin{proof}
    By the a priori estimates and the compactness, we have proved that all the eigenvalues of \eqref{eq:rescle-final} converge to some eigenvalues of \eqref{limit_rescled_prob}. It is left to prove that all eigenvalues of the effective problem \eqref{limit_rescled_prob} are limits of some eigenvalues of \eqref{eq:rescle-final}. 
    \noindent
    We follow the ideas of the proof of Lemma 3.12 in \cite{PaPe-ApplicAnal-2014}  and will prove this by contradiction. Assume that the first eigenvalue $\nu_{1}^{\ve}$ of \eqref{eq:rescle-final}, converge to the second eigenvalue $\nu_{2}$ of \eqref{limit_rescled_prob}, and not to $\nu_1$. The first eigenvalue $\nu_{1}^{\ve}$ is simple and the corresponding eigenfunction $v_{1}^{\ve}$ converge to the eigenfunction $v_{2}$.
    By the variational principle,
    \begin{align*}
        \nu_{1}^{\ve} = \inf_{w} \frac{\mathcal{F}_{\ve}(w)}{\int_{\mathbb{R}^{d}} \rho_{\Psi}^{\ve} w^{2}\, d\mu_{\ve}},
    \end{align*}
    where the infimum is taken over $H^{1}(\mathbb{R}^{d}, \mu_{\ve}) \setminus \{0\}$ such that $w\Big|_{z_{1} = \ve^{-1/2} \Gamma_{\ve}^{\pm}} = 0$, and
    \begin{align*}
        \mathcal{F}_{\ve}(w) :=
      &\int_{\mathbb{R}^{d}} a_{\Psi}^{\ve}(\sqrt{\ve}z) \nabla w \cdot \nabla w \, d\mu_{\ve}  + \int_{\mathbb{R}^{d}}  (a^{\ve} \nabla_{z} \Psi^{\ve} \cdot \nabla(\Psi^{\ve} w^{2} ) \, d\mu_{\ve}\\
      &- \int_{\mathbb{R}^{d}} \Psi^{\ve} \mathrm{div}_{z} (a^{\ve} \nabla_{\zeta} \Psi^{\ve} ) w^{2} \, d\mu_{\ve}\\
    &+ \int_{\mathbb{R}^{d}} \frac{\mu(\sqrt{\ve}z_{1}) - \mu(0)}{\ve} \rho_{\Psi}^{\ve}(\sqrt{\ve}z) w^{2} \, d\mu_{\ve}.
  \end{align*}
    The minimum is attained on the first eigenfunction $w_{1}^{\ve}$. Since $\nu_{1}^{\ve} \rightarrow \nu_{2}$, as $\ve \rightarrow 0$, we can write $\nu_{1}^{\ve} = \nu_{2} + o(1)$, as $\ve \rightarrow 0$.

    Let $w_{1}(z_{1})$ be the first eigenfunction of \eqref{limit_rescled_prob} and $N$ be the normalized solution of the auxiliary cell problem {satisfied by $N_{1}$}. Denote
    \begin{align*}
        W_{\ve} = \left( w_{1}(z_{1}) + \ve^{1/2} N \left( \frac{z}{\sqrt{\ve}} \right) w_{1}'(z_{1}) \right) \phi_{\ve}(z_{1}),
    \end{align*}
    where
    \begin{align*}
        \phi_{\ve}(z_{1}) = \begin{cases}
            &1, ~~ z_{1} \in [-\frac{\ve^{-1/2}}{6} , \frac{\ve^{-1/2}}{6}]\\
            &0, ~~ z_{1} \in \mathbb{R} \setminus [-\frac{\ve^{-1/2}}{3} , \frac{\ve^{-1/2}}{3}]
        \end{cases}
    \end{align*}
    and such that $0 \le \phi_{\ve} \le 1$, $| \phi_{\ve}'(z_{1}) | \le C \ve^{1/2}$.\\
The cut-off function is introduced in order to make the test function $W_{\ve}$ satisfy the Dirichlet boundary condition at the ends of the rod. Using Corollary \eqref{corollary_two scale_average} and taking into account the exponential decay of $w_{1}(z_{1})$, we estimate the norm of $W_\ve$:
    \begin{align*}
        \|W_{\ve}\|^{2}_{L^{2}(\mathbb{R}^{d}, \mu_{\ve})} &= \int_{\mathbb{R}^{d}} \Big( w_{1}(z_{1}) + \ve^{1/2} N \Big( \frac{z}{\sqrt{\ve}} \Big) w_{1}'(z_{1}) \Big)^{2} |\phi_{\ve}(z_{1})|^{2} \, d\mu_{\ve}\\
        &= \int_{\mathbb{R}^{d}} |w_{1}(z_{1})|^{2} |\phi_{\ve}(z_{1})|^{2} \, d\mu_{\ve} + \ve \int_{\mathbb{R}^{d}} \left|N \left(\frac{z}{\sqrt{\ve}} \right) w_{1}'(z_{1}) \right|^{2} |\phi_{\ve}(z_{1})|^{2} \, d\mu_{\ve}\\
        &~~~~+ 2\sqrt{\ve} \int_{\mathbb{R}^{d}} w_{1}(z_{1}) N \left(\frac{z}{\sqrt{\ve}} \right) w_{1}'(z_{1}) |\phi_{\ve}(z_{1})|^{2} \, d\mu_{\ve} \\
        &= \int_{\mathbb{R}^{d}} |w_{1}(z_{1})|^{2} |\phi_{\ve}(z_{1})|^{2} \, d\mu_{\ve} + o(\ve)\\
        &= \int_{\mathbb{R}} |w_{1}(z_{1})|^{2} \, dz_{1} + o(\sqrt{\ve}), ~\text{as}~ \ve \rightarrow 0.
    \end{align*}
    \noindent
    Let us compute the derivatives of $W_\ve$:
    \begin{align*}
        &\partial_{z_{i}} W_{\ve} = \left( \delta_{1i} + \partial_{\zeta_{i}} N(\zeta)\Big|_{\zeta = z/\sqrt{\ve}} \right) w_{1}'(z_{1}) \phi_{\ve}(z_{1}), ~~i \neq 1,\\
        &\partial_{z_{1}} W_{\ve} = \left( \delta_{11} + \partial_{\zeta_{1}} N(\zeta)\Big|_{\zeta = z/\sqrt{\ve}} \right) w_{1}'(z_{1}) \phi_{\ve}(z_{1}) + \ve^{1/2} N \left(\frac{z}{\sqrt{\ve}} \right) w_{1}''(z_{1}) \phi_{\ve}(z_{1}) \\
        &~~~~~~~~~+ \left( w_{1}(z_{1}) + \ve^{1/2} N \left(\frac{z}{\ve} \right) w_{1}'(z_{1}) \right) \phi_{\ve}'(z_{1}).
    \end{align*}
    Sustituting $W_{\ve}$ into the functional $\mathcal{F}_{\ve}$, we obtain
    \begin{align*}
        \mathcal{F}_{\ve}(W_{\ve}) &= \int_{\mathbb{R}^{d}} (a_{\Psi}^{\ve})_{ij} \left( \delta_{1j} + \partial_{\zeta_{j}} N \left(\frac{z}{\sqrt{\ve}} \right) \right) \left( \delta_{1i} + \partial_{\zeta_{i}} N \left(\frac{z}{\sqrt{\ve}} \right) \right) \phi_{\ve}^{2}(z_{1}) (w_{1}'(z_{1}))^{2} \, d\mu_{\ve}\\
        &~~+ \int_{\mathbb{R}^{d}} (a^{\ve} \nabla_{z} \Psi^{\ve}) \cdot \nabla(\Psi^{\ve} W_{\ve}^{2}) \, d\mu_{\ve} + \frac{1}{\sqrt{\ve}} \int_{\mathbb{R}^{d}} \Psi^{\ve} \mathrm{div}_{z} (a^{\ve} \nabla_{\zeta} \Psi^{\ve}) W_{\ve}^{2} \, d\mu_{\ve}\\
        &~~+ \int_{\mathbb{R}^{d}} \frac{\mu(\sqrt{\ve}z_{1}) - \mu(0)}{\ve} \rho_{\Psi}^{\ve} W_{\ve}^{2} \, d\mu
        _{\ve} + o(1), ~~\ve \rightarrow 0.
    \end{align*}
    Taking the limit as $\ve \rightarrow 0$
    \begin{align*}
        \mathcal{F}_{\ve}(W_{\ve}) &= \int_{\mathbb{R} \times Y} (a_{\Psi}(0, \zeta))_{ij} ( \delta_{1j} + \partial_{\zeta_{j}} N(\zeta)) ( \delta_{1i} + \partial_{\zeta_{i}} N(\zeta ) (w_{1}'(z_{1}))^{2} \, d\zeta dz_{1}\\
        &+ \int_{\mathbb{R} \times Y} (a \nabla_{x} \Psi)(0, \zeta) \cdot \nabla_{\zeta} (\Psi(0, \zeta)) (w_{1}(z_{1}))^{2} \, d\zeta dz_{1}\\
        &- \int_{\mathbb{R} \times Y} \Psi(0, \zeta) \mathrm{div}(a \nabla_{\zeta} \Psi)(0, \zeta) (w_{1}(z_{1}))^{2} \, d\zeta dz_{1}\\
        &+ \frac{\mu''(0)}{2} \langle \rho_{\Psi}(0, \cdot) \rangle \int_{\mathbb{R}} |z_{1}|^{2}( w_{1}(z_{1}))^{2} \, dz_{1} + o(1)\\
        &= \int_{\mathbb{R}} a^{\text{eff}} (w_{1}(z_{1}))^{2} \, dz_{1} + \int_{\mathbb{R}} c^{\text{eff}} (w_{1}(z_{1}))^{2} \, dz_{1}\\
        &+ \frac{\mu''(0)}{2} \langle \rho_{\Psi}(0, \cdot) \rangle \int_{\mathbb{R}} |z_{1}|^{2}( w_{1}(z_{1}))^{2} \, dz_{1} + o(1), ~\ve \to 0.
    \end{align*}
    Therefore,
    \begin{align*}
       &\frac{ \mathcal{F}(W_{\ve})}{\int_{\mathbb{R}^{d}}\rho_{\Psi}^\ve W_{\ve}^{2} \, d\mu_{\ve}}\\
       &= \frac{\int_{\mathbb{R}} a^{\text{eff}} (w_{1}')^{2} \, dz_{1} + \int_{\mathbb{R}} c^{\text{eff}} (w_{1})^{2} \, dz_{1} + \frac{\mu''(0)}{2} \langle \rho_{\Psi}(0, \cdot) \rangle \int_{\mathbb{R}} |z_{1}|^{2}( w_{1})^{2} \, dz_{1}} { \langle 
\rho_{\Psi}(0, \cdot) \rangle \int_{\mathbb{R}} (w_{1})^{2} \, dz_{1}}+ o(1)\\
&= \nu_{1} + o(1), ~\ve \to 0.
    \end{align*}
Since $\nu_{1}<\nu_2$, we have constructed a test function giving a smaller eigenvalue than $\nu_{1}^{\ve} = \nu_{2} + o(1)$, which is a contradiction.
\end{proof}

\appendix
\section{Two-scale convergence in spaces with measure}
\label{Appendix A}
\begin{definition}
Let $\mu_\ve$ be the measure defined by \eqref{def:mu_eps}.
A sequence $g^\ve(x) \in L^{2}(\mathbb{R}^{d}, \mu_{\ve})$ is said to converge weakly in $L^{2}(\mathbb{R}^{d}, \mu_{\ve})$ to a function $g(x_{1}) \in L^{2}(\mathbb{R}^{d}, \mu^{*})$, as $\ve \rightarrow 0$, if
\begin{itemize}
\item[(i)] 
$\|g^{\ve}\|_{L^{2}(\mathbb{R}^{d}, \mu_{\ve})} \le C$,

\item[(ii)] for any $\phi \in C_{c}^{\infty}(\mathbb{R}^{d})$ the following relation holds:
\begin{align*}
    \lim_{\ve \rightarrow 0} \int_{\mathbb{R}^{d}} g^{\ve}(x) \phi(x) \, d\mu_{\ve} = \int_{\mathbb{R}^{d}} g(x_{1}) \phi(x) \, d\mu^{*}.
\end{align*}
\end{itemize}
A sequence $g^{\ve}$ is said to converge strongly to $g(x_{1})$ in $L^{2}(\mathbb{R}^{d}, \mu_{\ve})$, as $\ve \rightarrow 0$, if it converges weakly and 
\begin{align*}
    \lim_{\ve \rightarrow 0} \int_{\mathbb{R}^{d}} g^{\ve}(x) \psi^{\ve}(x) \, d\mu_{\ve} = \int_{\mathbb{R}^{d}} g(x_{1}) \psi(x_{1}) \, d\mu^{*}
\end{align*}
for any sequence $\{\psi^{\ve}(x)\}$ weakly converging to $\psi(x_{1})$ in $L^{2}(\mathbb{R}^{d}, \mu_{\ve})$.
\end{definition}
The weak compactness results are valid in spaces with measure, we refer to \cite{ZikovTwoscale}.\\

In the present context, two-scale convergence is described as follows.

\begin{definition}
    We say $g^{\ve} \in L^{2}(\mathbb{R}^{d}, \mu_{\ve})$ converges two-scale weakly, as $\ve \rightarrow 0$, in $L^{2}(\mathbb{R}^{d}, \mu_{\ve})$ if
    \begin{itemize}
    \item[(i)]
    $\|g^{\ve}\|_{L^{2}(\mathbb{R}^{d}, \mu_{\ve})} \le C, ~~~ \ve >0$,

    \item[(ii)] there exists a function $g(x_{1},y) \in L^{2}(\mathbb{R}^{d} \times Y, \mu^{*} \times d\zeta)$ such the following limit relation holds:
    \begin{align*}
        \lim_{\ve \rightarrow 0} \int_{\mathbb{R}^{d}} g^{\ve}(x) \phi(x) \psi(\frac{x}{\sqrt{\ve}}) \, d\mu_{\ve} = \frac{1}{|Y|} \int_{\mathbb{R}^{d}} \int_{Y} g(x_{1},y) \phi(x_{1}, 0) \psi(\zeta) \, d\zeta \, d\mu^{*},
    \end{align*}
    for any $\phi \in C_{c}^{\infty}(\mathbb{R}^{d})$ and $\psi(\zeta) \in C^{\infty}(\Bar{Y})$ periodic in $\zeta_{1}$.
    \end{itemize}
\end{definition}
We write $g^{\ve} \overset{2}{\rightharpoonup} g(x_{1},y)$
if $g^{\ve}$ converges two-scale weakly to $g(x_{1},y)$ in $L^{2}(\mathbb{R}^{d}, \mu_{\ve})$.\\

Note that the last definition holds for more general classes of test functions, e.g. $\Phi(x,y) \in C(\mathbb{R}^{d}; L^{\infty}(Y))$ or $\Phi(x,y) = \phi(x) \psi(y)$ with $\phi \in C(\mathbb{R}^{d})$, $\psi \in L^{2}(Y)$, \cite{ZikovTwoscale}.\\
\begin{lemma}
   Suppose that $g^{\ve}$ satisfies the following estimate
   $$\|g^{\ve}\|_{L^{2}(\mathbb{R}^{d}, \mu_{\ve})} \le C.$$
Then $g^{\ve}$, up to a subsequence, converges two-scale weakly in $L^{2}(\mathbb{R}^{d}, \mu_{\ve})$ to some function $g(x_{1},y) \in L^{2}(\mathbb{R}^{d} \times Y, \mu^{*} \times d\zeta)$.   
\end{lemma}

\begin{definition}
A sequence $g^{\ve}$ is said to converge two-scale strongly to a function $g(x_{1},y) \in L^{2}(\mathbb{R}^{d} \times Y, \mu^{*} \times d\zeta)$ if
\begin{itemize}
\item[(i)] $g^{\ve} \overset{2}{\rightharpoonup} g(x_{1},y)$.
\item[(ii)] The following limit relation holds
\begin{align*}
    \lim_{\ve \rightarrow 0} \int_{\mathbb{R}^{d}} (g^{\ve}(x))^{2} \, d\mu_{\ve} = \frac{1}{|Y|} \int_{\mathbb{R}^{d}} \int_{Y} (g(x_{1},y))^{2} \, d\zeta \, d\mu^{*}
\end{align*}
\end{itemize}
\end{definition}
We write $g^{\ve} \overset{2}{\rightarrow} g(x_{1},y)$
if $g^{\ve}$ converges two-scale strongly to the function $g(x_{1},y)$ in $L^{2}(\mathbb{R}^{d}, \mu_{\ve})$.

\begin{lemma}
\label{lm:compactness}
    Assume that $v_\ve$ is such that
    \begin{align*}
        \int_{\mathbb R^d} |\nabla v|^2\, d\mu_\ve
        + \int_{\mathbb R^d} |x_1 v|^2\, d\mu_\ve \le C.
    \end{align*}
    Then $v_\ve$ converges strongly in $L^2(\mathbb R^d, \mu_\ve)$ to $v\in L^2(\mathbb R)$.
\end{lemma}
{The proof of Lemma \ref{lm:compactness} follows the lines of Lemma 4.4 in \cite{piat2013localization}.}

\section{Integral estimates for oscillating functions}
\label{Appendix B}
The proof of the following integral estimate for oscillating functions can be found in \cite{PaPe-ApplicAnal-2014}.
\begin{lemma}
\label{lm:oscillating-integrals}
    Let $v_{\ve} \in H^{1}_{0}(\Omega_{\ve})$, $v_{\ve}(\pm 1, x') = 0$, and $w(x_{1},y) \in C^{1}(\bar{I}, L^{\infty}(Y))$. Then as $\ve \rightarrow 0$,
    \begin{align*}
        &\int_{\Omega_{\ve}} w(x_{1}, \frac{x}{\ve}) v_{\ve}^{2}(x) \, dx - \frac{1}{|Y|}\int_{\Omega_{\ve}} (\int_{Y} w(x_{1},y) \, dy)\, v_{\ve}^{2}(x) \, dx\\ \vspace{1mm}
        &~~= O(\ve\|v_{\ve}\|_{L^{2}(\Omega_{\ve})} \|\nabla v_{\ve}\|_{L^{2}(\Omega_{\ve})}).
    \end{align*}
\end{lemma}

\begin{corollary}
\label{corollary_two scale_average}
    Let $w_{\ve} \in H^{1}(\mathbb{R}^{d}, \mu_{\ve})$ be such that $w_{\ve} = 0$ on $\ve^{-1/2} \Gamma_{\ve}^{\pm}$, and $c(x_{1},y) \in C^{1}(\mathbb{R}; L^{\infty}(Y)$. Then as $\ve \rightarrow 0$, 
    \begin{align*}
     &\int_{\mathbb{R}^{d}} c(\sqrt{\ve} z_{1}, \frac{z}{\sqrt{\ve}}) w_{\ve}^{2}(z) \, d\mu_{\ve} - \int_{\mathbb{R}^{d}} \left( \int_{Y} c(\sqrt{\ve}z_{1}, \zeta) \, d\zeta \right) w_{\ve}^{2}(z) \, d\mu_{\ve}\\
     &~~~= O\left( \sqrt{\ve} \|w_{\ve}\|_{L^{2}(\mathbb{R}^{d}, \mu_{\ve})} \| \nabla w_{\ve} \|_{L^{2}(\mathbb{R}^{d}, \mu_{\ve})} \right).
    \end{align*}
\end{corollary}


