\end{defn}

\begin{defn} We say a morphism of stacks $f: X \to Y$, has property $P$ if for all affines $S \to Y$, the map $S \times_Y X \to S$ has propery $P.$ \end{defn} 


\begin{example} 
We will consider the following sites for a base scheme $S\in\mr{Sch}$:
\begin{itemize} 
\item The (small) \'etale site $S_{et}$ is the full subcategory of $\mr{Sch}_{/S}$ on \'etale morphisms of schemes $f:X\to S$ with covering families given by jointly surjective families $\{f_i:X_i\to S\}_{i\in I}$ of \'etale morphisms.
\item The (small) pro-\'etale site $S_{proet}$ is the full subcategory $\mr{Sch}_{/S}$ on pro-\'etale (or weakly \'etale) morphisms of schemes $f:X\to S$ with topology induced by the fpqc topology.
\item The (big) fppf site $\mr{Sch}_{fppf}/S=(\mr{Sch}/S)_{fppf}$ with covering families given by jointly surjective families $\{f_i:X_i\to S\}_{i\in I}$ of morphisms which are flat and locally of finite presentation (see \cite[Section 021L]{stacks-project}).
\item The (big) fpqc site $\mr{Sch}_{fpqc}/S=(\mr{Sch}/S)_{fpqc}$ with covering families given by jointly surjective families $\{f_i:X_i\to S\}_{i\in I}$ of morphisms which are faithfully flat and quasicompact (see \cite[Section 03NV]{stacks-project}). 
\end{itemize}
\end{example}

\begin{defn} (1) An affine formal algebraic space over $S$ is a sheaf $\mc{X}$ on the fppf site of $S$ which admits a description as an Ind-scheme $X \simeq \lim_i X_i$, where the $X_i$ are affine schemes and the transition morphisms are thickenings.

\noindent (2) A formal algebraic space over $S$ is a sheaf $\mc{X}$ on the fppf site of $S$ which receives a morphism $\amalg U_i \to \mc{X}$ which is representable, \'etale, and surjective, and whose source is a disjoint union of affine formal algebraic spaces $U_i$. 
\end{defn}

\begin{defn} Let $\mc{X}$ be a stack in groupoids on the fppf site of a scheme $S$. We say that $\mc{X}$ is a formal algebraic stack if it admits a pro-etale surjection $\mc{U} \to \mc{X}$ from a formal algebraic space $\mc{U}$.

%if there is a morphism $\mc{U} \to \mc{X}$ whose domain $U$ is a formal algebraic space, and which is representable by algebraic spaces, etale and surjective. %smooth
\end{defn}

\begin{remark}
A formal algebraic space is ind-\'etale, and an \'etale map from it is ind-\'etale. 
\end{remark}

\begin{remark} Emerton \cite{emerton2020formal} uses a stronger definition which is representable by algebraic spaces, smooth and surjective. In other words, he works with the analog of Artin stacks, whereas we are working with the proetale topology. This lets us work with profinite stacks (locally quotients by a profinite group), which lay in between Artin stacks and DM stacks (quotients by a finite group).
\end{remark}


