\begin{defn} 
Let $\mc{X}$ be a stack. We define $\mr{QCoh}: \mr{Stk}^{op} \to \mr{Cat}$ as the right Kan extension of the presheaf $\mr{Spec}(R) \mapsto \mr{Mod}_R$ along the inclusion $\mr{Aff} \hookrightarrow \mr{Stk}$, where $\mr{Stk}$ is the $\infty$-category of stacks. In other words: 
\begin{align*} 
\QCoh(\mc{X}) &\simeq \QCoh(\underset{\Spec A \to \mc{X}}\colim \Spec A) \\
& \simeq \lim_{\Spec A \to \mc{X}} \QCoh(\Spec A) \\
& \simeq \lim_{\Spec A \to \mc{X}} \Mod_A \\
\end{align*}

%We define the category $\mr{QCoh}(\mc{X}) := \lim_{(R, x)} \mr{Mod}_{R}$ over the 
\end{defn}

By definition, a quasi-coherent sheaf $\mc{F}$ on a stack $\mc{X}$ amounts to the following data: 
\begin{itemize} 
\item For every $\Spec A \xrightarrow{x} \mc{X}$, the datum of an $A$-module $x^*(\mc{F})$, 
\item For every ring homomorphism $A \to B$, where the image of $x$ to the image of $y$ in $\mc{X}$, 
\[
\begin{tikzcd}
\Spec B \arrow[r] \arrow[rr, "y"', bend right] & \Spec A \arrow[r, "x"] & \mc{X}
\end{tikzcd}
\]

then the datum of a $B$-module $y^*(\mc{F})$ with a prescribed isomorphism of $B$-modules $x^*(\mc{F}) \otimes_A B \simeq y^*(\mc{F}).$
\end{itemize}

\begin{example} For $\pt = \Spec k$, then we have $$\QCoh(\pt) = \Mod_k.$$ \noindent Our beloved global sections thus follow from a pushforward.

\begin{align*} 
p_*: \QCoh(X) &\to \QCoh(pt)\\
\mc{F} &\mapsto \Gamma(X, \mc{F}) = p_*(\mc{F}) 
\end{align*}
\end{example}

\begin{defn}
We define the functor $$\OO: \rm{Stk}^{op} \to \mr{CRing}$$ as the right Kan extension of $\OO(\Spec A) = A$, such that it preserves limits. 
\end{defn} 

\begin{remark} This is the decategorification of $\QCoh$. \end{remark}

\begin{example} Given $X \xrightarrow{p} \pt$, $\OO_X := p^*\OO_{\pt}.$ Also, $p_*\OO_X := \OO(X) := \Gamma(X, \OO_X).$
\end{example}


