This section is devoted to the consideration of formal groups in characteristic $p$.

\begin{lemma}The category of formal groups is equivalent to the category of connected $p$-divisible groups. \end{lemma} 


\begin{defn} Given $R$ a commutative ring in characteristic $p$, there is a map $\varphi_R: R \to R$ such that $\varphi_R(x) = x^p.$ For a commutative $R$-algebra $A,$ with structure map $R \xrightarrow{f} A,$ we denote $A^{1/p^h}$ as the corresponding $R$-algebra defined via the structure map $$R \xrightarrow{(\varphi_{X})^h} R \xrightarrow{f} A.$$ Given a functor $X$ with source category $\mr{CAlg}_R$, we define $X^{(p^h)}(A) := X(A^{1/p^h}).$
There is a natural map $\varphi_{X/R}^h: X \to X^{(p^h)}$ called the \textbf{relative Frobenius map}.
\end{defn}

We now introduce a key property of formal groups over characteristic $p$ fields. 

\begin{lemma} \cite{ell2} (Prop 4.4.5) Given a map $f: G \to G'$ in $\mc{M}_{\mr{fg}}(R)$, the following conditions are equivalent: 
\begin{itemize}
\item The pullback map $f^* \colon \omega_G \to \omega_{G'}$ vanishes.
\item The morphism $f$ factors as a composition $G \xrightarrow{\phi_G} G^{(p)} \xrightarrow{g} G'$.
\end{itemize}
If these conditions are satisfied, the map $g$ is uniquely determined.
\end{lemma}



%\bonus{ define height this way and then state that it must be of height exactly $h$ or infinite...}



\begin{defn}
A formal group $F$ over an $\F_p$-algebra is of height at least $h$ if the multiplication by $p$ map factors through the $h$-th relative Frobenius, as in 

\[\begin{tikzcd}
	F & {F^{(p^h)}} \\
	& F
	\arrow["{\varphi^h_{F/R}}", from=1-1, to=1-2]
	\arrow["{[p]_F}"', from=1-1, to=2-2]
	\arrow[dashed, from=1-2, to=2-2]
\end{tikzcd}\]

\noindent A formal group $F$ is of height exactly $h$ if the map factoring Frobenius is an isomorphism.

\[\begin{tikzcd}
	F & {F^{(p^h)}} \\
	& F
	\arrow["{{\varphi^h_{F/R}}}", from=1-1, to=1-2]
	\arrow["{[p]_F}"', from=1-1, to=2-2]
	\arrow["\simeq", from=1-2, to=2-2]
\end{tikzcd}\] 
\end{defn}

\begin{remark} An equivalent definition of the \textbf{height} of a (one-dimensional) formal group $F$ over characteristic $p$ field $k$ as the rank of connected component of the kernel of the multiplication by $p$ map as a $k$-vector space, i.e., 
$\text{height}(F) := \text{rank}_kF^\circ[p].$
\end{remark}

