\subsection{Isomorphism Scheme is Ind-Etale and Height Classifies}
\begin{defn}% A $k$-algebra is ind-\'etale if as a $k$-algebra, it is isomorphic to a filtered colimit of \'etale algebras.
An ind-\'etale cover over $R$ is a filtered colimit of finite etale extensions over $\Spec R.$ An equivalent definition is that a cover $\Spec S \to \Spec R$ is ind-etale if for every diagram there is a unique lift of $q$
\[\begin{tikzcd}
	{\Spec k} & {\Spec S} \\
	{\Spec A} & {\Spec R}
	\arrow[from=1-1, to=1-2]
	\arrow[from=1-1, to=2-1]
	\arrow["\begin{array}{c} \text{ind-}\\ \text{etale} \end{array}", from=1-2, to=2-2]
	\arrow["{{\exists !}}"{description}, dashed, from=2-1, to=1-2]
	\arrow["q", from=2-1, to=2-2]
\end{tikzcd}\]
where $\Spec k \to \Spec A$ is a nil-thickening.
\end{defn}

\begin{remark} A cover is \'etale if it has this property and is also finite. \end{remark}

