If the formal groups come from formal group laws $F_0, F_1$, the resulting scheme is affine, $\mathrm{Iso}(G_0, G_1) \simeq \Spec(A_{F_0, F_1}).$ This is the $R_0 \otimes_\Z R_1$ algebra generated by symbols $b_i$ for $i \geq 0$ subject to the relations which state that the power series $\phi(x) = \sum_i b_ix^{i+1}$ is an isomorphism from $F_0$ to $F_1$.  We introduce the notation of $A_{F_0, F_1}(m)$ to mean the $R_0 \otimes R_1$-subalgebra of $A_{F_0, F_1}$ generated by $b_i$ for $i < m.$


\begin{lemma} \label{indetale} \cite{finiteheight} (15.2) Let $F_0$ and $F_1$ be formal groups of dimension 1 which are both of height $h > 0$ , then 
\begin{enumerate} 
\item $A_{F_0, F_1}(0) \simeq R_0 \otimes_{\Z} R_1$
\item each of the maps $A_{F_0, F_1}(m) \hookrightarrow A_{F_0, F_1}(m+1)$ is finite etale.
\end{enumerate} 
In particular $A_{F_0, F_1}$ is ind-etale over $R_0 \otimes R_1$.
\end{lemma}

\begin{lemma} \cite{finiteheight} (15.6)
Let $F_0, F_0', F_1$ be formal group laws over $R,$ then any choice of isomorphism $\phi(F_0, F')$ induces an isomorphism of $R$ algebras $A_{F_0, F_1} \simeq A_{F_0', F_1}$ compatible with the filtration. 
\end{lemma}

\begin{remark} This filtration by $m$ induces a topology on $A_{F_0, F_1}$, giving it the structure of a pro-finite group. \end{remark}

\begin{theorem}  \cite{finiteheight} (15.4)(Lazard)  Let $K$ be an algebraically closed field of characteristic $p$. Then any two formal groups $F_0, F_1$ of dimension 1 over $K$ of the same height are isomorphic. \end{theorem}
