    \centering 
    \includegraphics[width=\linewidth]{figures/facility_labelled.pdf}
    \caption{Rendering of the COSINUS setup in hall B of LNGS with the cryostat in the center of the cylindrical water tank. Depicted is the Cherenkov light emitted by a particle traversing the water tank, which is picked up by 30 PMTs. A clean room is installed above the water tank to allow the handling of the cryostat (and detectors) in a clean environment.}
    \label{fig:facility}
