	The points on the horizontal lines are the exceptional vertices. Both graphs have the feature that there is one vertex with exactly one incoming 
	and exactly one outgoing arrow and due to \cite[Section 7.3.3.1]{kontsevich:2003a} the weights of these graphs vanish. This means in particular 

\begin{corollary}
		\label{Cor: SkewKon}
	Let $\hbar\pi=\sum_{k=1}^\infty\hbar^k\pi_k\in  \hbar\Secinfty(\Anti^2 TM)\formal{\hbar}$ be a formal Poisson structure. The skew symmetrization of 
	the second order of the Kontsevich-Dolgushev star product corresponding to $\hbar\pi$ is given by $F_1(\pi_2)$.   
\end{corollary}

\section{Representable HKR Theorem}
\label{sec:RepresentableHKR}

Following \cite[]{dippell.esposito.schnitzer.waldmann:2024a:pre}
we collect some results.
Let $E_\Total \to M$ be a vector bundle together with a linear submanifold
$I \colon E_\Normal \hookrightarrow E_\Total$ over a submanifold
$i \colon C \hookrightarrow M$,
and denote the normal bundle of $E_\Normal$ in $i^\#E_\Total$ by
$\nu(E_\Total,E_\Normal)$.
Consider the differential operators $\Diffop(E_\Normal)$ on the total space of the
vector bundle $E_\Normal$ as a $\Cinfty(E_\Total)$-bimodule with bimodule
structure given by
\begin{equation}
	(F \acts D)(G) \coloneqq I^*F \cdot D(G)
	\qquad\text{and}\qquad
	(D \racts F)(G) \coloneqq D(I^*F \cdot G),
\end{equation}
for $F \in \Cinfty(E_\Total)$ and $G \in \Cinfty(E_\Normal)$.
With this we obtain the Hochschild complex
$\HCdiff^\bullet\bigl(E_\Total,\Diffop(E_\Normal)\bigr)$
with differential given by
\begin{equation}
	\label{eq:RepresentableDifferential}
\begin{split}
	(\del D)(F_0, \dotsc, F_n)(G)
	&= 
	I^*F_0 \cdot D(F_1,\dotsc,F_n)(G)
	\\
	&\phantom{=}+ \sum_{i=0}^{n} (-1)^{i+1}
		D(F_0,\dotsc,F_i \cdot F_{i+1}, \dotsc, F_n)(G)
	\\
	&\phantom{=}+ (-1)^{n+1} D(F_0,\dotsc,F_{n-1})(I^*F_n \cdot G)
\end{split}
\end{equation}
for $F_0, \dotsc, F_n \in \Cinfty(E_\Total)$
and $G \in \Cinfty(E_\Normal)$.

\begin{theorem}[Representable HKR Theorem]
    \label{thm:RepresentableHKR}%
    Let $\nabla$ be a torsion-free homogeneous covariant
    de\-ri\-vative on $E_\Total$.
	Then there exist
	\begin{equation}
		\hkrHomo
			\colon
		\HCdiff^\bullet\bigl(E_\Total,\Diffop(E_\Normal)\bigr)
			\to
		\HCdiff^{\bullet-1}\bigl(E_\Total,\Diffop(E_\Normal)\bigr)
	\end{equation}
	and
	\begin{equation}
		\hkrInv
			\colon
		\HCdiff^\bullet\bigl(E_\Total,\Diffop(E_\Normal)\bigr)
			\to
		\Anti^{\bullet} \Secinfty\bigl(\nu(E_\Total,E_\Normal)\bigr)
	\end{equation}
	such that
    \begin{equation}
        \label{eq:representableHKRDeformationRetract}
        \begin{tikzcd}[column sep = large]
            \Anti^{\bullet} \Secinfty\bigl(\nu(E_\Total,E_\Normal)\bigr)
            	\arrow[r,"\hkr", shift left = 3pt]
            & \bigl( \HCdiff^\bullet\bigl(E_\Total,\Diffop(E_\Normal)\bigr),\del \bigr)
            	\arrow[l,"\hkrInv", shift left = 3pt]
            	\arrow[loop,
				out = -30,
				in = 30,
				distance = 30pt,
				start anchor = {[yshift = -7pt]east},
				end anchor = {[yshift = 7pt]east},
				"\hkrHomo"{swap}
				]
        \end{tikzcd}
    \end{equation}
    is a deformation retract, i.e. the following holds:
    \begin{theoremlist}
		\item \label{thm:representableHKR_1}
			We have $\hkrInv \circ \hkr = \id$.
		\item \label{thm:representableHKR_2}
			We have
			$\del \hkrHomo + \hkrHomo \del
			= \id - \hkr \circ \hkrInv$.
    \end{theoremlist}
	Moreover, the maps $\hkr$, $\hkrInv$ and $\hkrHomo$
	preserve the degrees of homogeneity.
\end{theorem}

In particular, for $D \in \HCdiff^2\bigl(E_\Total, \Diffop(E_\Normal)\bigr)$
we know that $\hkrInv(D) \in \Anti^2\Secinfty(\nu(E_\Total,E_\Normal))$,
and hence $\hkrInv(D)$ is determined by evaluating at elements in 
the annihilator of $E_\Normal$. Let us assume that $D$ is closed, then we get by
using the homotopy equation we get 
\begin{align}
	D(F,G)(1)=(\partial\hkrHomo D)(F,G)(1)+ \hkr\hkrInv(D)(F,G)(1)
\end{align}
for all $F,G\in \Cinfty(E_\Total)$. If we now assume that $F,G\in\vanishing_{E_\Normal}$, then we get 
by anti-symmetrizing
\begin{align}
	\hkr\hkrInv(D)(F,G)(1)= \frac{1}{2}\bigl(D(F,G)(1)-D(G,F)(1)\bigr),
\end{align}
since $(\partial\hkrHomo D)(F,G)(1)$ is symmetric evaluated on functions contained in 
the vanishing ideal. 
Moreover, using the explicit form of the map $\hkr$ on $F$ and $G$, this yields 
\begin{equation}
	\hkrInv(D)\left(\D F\at{C} , \D G\at{C}\right)
	= D(F,G)(1) - D(G,F)(1).
\end{equation}



