\section{Preliminaries}
We start by introducing some relevant notation. For every $N>1$ and $p\in(1,\infty)$ we denote
\begin{equation}
  S_{N,p} \coloneqq \frac 1N\left(\frac{N(p-1)}{N-p}\right)^{\frac{p-1}p}\left(\frac{\Gamma(N+1)}{N\omega_N\Gamma(N/p)\Gamma (N+1-d/p)}\right)^{\frac 1N}, \label{eq:Sobolev constant}  
\end{equation}
where $\omega_N \coloneqq \pi^{N/2} / \Gamma(N/2+1)$ and $\Gamma(\cdot)$ is the Gamma function.

A metric measure space is a triple  $(\X,\sfd,\mm)$ where $(\X,\sfd)$ is a complete and separable metric space and $\mm$ is a non-negative, non-zero and boundedly finite Borel measure. By $C(\X),C_b(\X),C_{bs}(\X)$ we denote respectively the space of continuous functions, continuous and bounded functions and continuous and boundedly supported functions on $\X$. By $\Lip(\X),\Lip_{bs}(\X)$, we denote respectively the collection of Lipschitz functions and boundedly supported Lipschitz functions and by $\lip(u)$ the local Lipschitz constant of $u\colon \X\to \R$. For all $p \in (1,\infty)$, we denote by $L^p(\mm),L^p_{loc}(\mm)$ respectively the space of $p$-integrable functions and $p$-integrable functions on a neighborhood of every point (up to $\mm$-a.e.\ equality relation) on $\X$. 


\subsection{Calculus on ${\sf RCD}$ spaces}\label{sec:RCD}
We define the $p$-\emph{Cheeger} energy by
\[
\rmCh_p(u)\coloneqq \inf\left\{ \int \lip(u_n)^p\,\d \mm \colon (u_n)\subseteq \Lip(\X), \, u_n \to u \text{ in }L^p(\mm)\right\},
\]
where we set the infimum to be equal to $+\infty$ when no such sequence $(u_n)$ exists. Then, the Sobolev space $W^{1,p}(\X)$ is defined as the collection of $u \in L^p(\mm)$ so that $\rmCh_p(u)<\infty$ equipped with the usual norm $\|u\|_{W^{1,p(\X)}}^p \coloneqq \|u\|_{L^p(\mm)}^p + \rmCh_p(u)$. We refer to \cite{Cheeger00,Shan00} for a general introduction while here we follow the equivalent axiomatization given by \cite{AmbrosioGigliSavare11-3}. Recall that we have the representation
\[
\rmCh_p(u) = \int |\nabla u|^p\,\d \mm,
\]
for a suitable function $|\nabla u| \in L^p(\mm)$ called minimal $p$-weak upper gradient. Thanks to locality \cite{AmbrosioGigliSavare11-3} of minimal $p$-weak upper gradients, we recall the space $W^{1,p}_{loc}(\X)$ as the subset of $u \in L^p_{loc}(\mm)$ so that $\eta u \in W^{1,p}(\X)$ for all $\eta \in \Lip_{bs}(\X)$. By slight abuse of notation, we shall write $\|\nabla u\|_{L^p(\mm)}$ in place of $\| |\nabla u|\|_{L^p(\mm)}$. We also do not insist on the dependence of $|\nabla u|$ on the exponent $p$ (see, e.g., \cite{DiMarinoSpeight13}), as we shall only deal with settings where this does not occur, see \cite{Cheeger00,GigliHan14,GigliNobili21}.

We also recall the notion of functions of locally bounded variation following \cite{Miranda03,AmbrosioDiMarino14}. If $\varnothing \neq U\subset\X$ is open and $u\in L^1_{loc}(\mm)$, we define
\[
    |D u|(U) \coloneqq \inf \Big\{\liminf_{n\uparrow\infty} \int \lip\, u_n\, \d \mm \colon (u_n)\subset \Lip_{loc}(U),\, u_n \to u \text{ in }L^1_{loc}(U)\Big\}.
\]
It can be shown that the above extends to a nonnegative Borel measure to the whole sigma-algebra of Borel sets (\cite{AmbrosioDiMarino14}). We then say that $u \in BV_{loc}(\X)$ provided $|Du|$ is finite on a neighborhood of every point. We simply say that $u$ is a function of bounded variation, writing $u \in BV(\X)$, provided $u\in L^1(\mm)$ and $|Du|(\X)<\infty$. We also refer to \cite{DiMarinoPhD,Martio16-2,NobiliPasqualettoSchultz21,BrenaNobiliPasqualetto22} for other equivalent approaches.
%
%
%


In this note we are interested in Sobolev inequalities on spaces with synthetic Ricci curvature lower bounds. We assume the reader to be familiar with the theory and concepts of ${\sf RCD}$-spaces. In the following parts, we shall limit ourselves to recalling only the relevant properties. We refer, for general introductions and the relevant references to the surveys \cite{Villani2016,AmbICM,Gigli23_working,Sturm24_Survey}.

If $\Xdm$ is an ${\sf RCD}(0,N)$ space  for some  $N>1$ we will use several times the following Bishop-Gromov monotonicity (see \cite{Sturm06I,Sturm06II}): for all $x\in\X$ we have that\[
r\mapsto \frac{\mm(B_r(x))}{\omega_Nr^N},\qquad\text{is non-increasing}.
\]
In particular, the following limit is well-defined and independent on $x$
\[
{\sf AVR}(\X) \coloneqq \lim_{R\to \infty} \frac{\mm(B_r(x))}{\omega_Nr^N} \in [0,\infty).
\]
%
%
We next state a useful principle for Sobolev functions and functions of bounded variations.
\begin{proposition}\label{prop:sob small support}
    For all constants $\eps>0,K\in\R,N\in(1,\infty),p\in[1,N)$ and $R_0>0$ there exists $\delta \coloneqq \delta(\eps,K,N,p,R_0)>0$ so that the following holds: let $\Xdm$ be an ${\sf RCD}(K,N)$ space, $x \in \X$ and suppose that $u \in W^{1,p}(\X)$ if $p\neq 1$ or $u \in BV(\X)$ if $p=1$ satisfies for some $0<R\le R_0$
    \begin{equation}
    \supp(u)\subset B_R(x),\qquad \frac{\mm(\supp(u))}{\mm(B_R(x))} \le \delta.
    \label{eq:delta support}
    \end{equation}
    Then, it holds
    \[
        \int |u|^p\,\d \mm \le  \eps\cdot \begin{cases}
        \, \int |\nabla u|^p\,\d \mm,&\text{if }p\in(1,N),\\
        \, |Du|(\X),            &\text{if }p=1.
        \end{cases}
    \]
\end{proposition}
\begin{proof}
    We only prove the case $p>1$, the case $p=1$ being the same. Denote by $p^*=pN/(N-p)>p$ and, for all $\eps>0$, notice by interpolation and Young inequality that
    \[
    \left(\fint_{B_R(x)}|u|^p\,\d\mm\right)^\frac1p \le \eps\left( \fint_{B_R(x)}|u|^{p^*}\,\d\mm\right)^{\frac{1}{p^*}} + \eps^{-\frac{N(p-1)}{p}}\fint_{B_r(x)}|u|\,\d\mm. 
    \]
    Thus, provided $\delta^{1-1/p} \le \frac 12 \eps^{\frac{N(p-1)}{p}}$, by H\"older inequality and the assumptions \eqref{eq:delta support} we get
    \[
     \left(\fint_{B_R(x)}|u|^p\,\d\mm\right)^\frac1p  \le 2\eps \left( \fint_{B_R(x)}|u|^{p^*}\,\d\mm\right)^{\frac{1}{p^*}}.
    \]
    In particular, by the triangular inequality and the local $(p^*,p)$-Sobolev inequality in this setting (see, e.g.\ \cite[Theorem 5.1]{HajlaszKoskela00}), we deduce
    \[
    \left( \fint_{B_R(x)}|u|^{p^*}\,\d\mm\right)^{\frac{1}{p^*}} - \fint_{B_R(x)}|u|\,\d\mm \le  \left( \fint_{B_R(x)}\Big|u - \fint_{B_R(x)}u\,\d \mm\Big|^{p^*} \,\d\mm\right)^{\frac{1}{p^*}} \le C \left(\fint_{B_R(x)}|\nabla u|^p\,\d \mm\right)^\frac 1p,
    \]
    for some constant $C\coloneqq C(K,N,R_0)>0$. Combining everything and using again H\"older inequality on the term $\fint_{B_R(x)}|u|\,\d\mm $, the proof is concluded.
\end{proof}


We isolate here the following technical density bound that will be needed in the proof of Theorem \ref{thm:CC extremal} in the collapsed case. The proof is identical to \cite[Lemma 6.1]{NobiliViolo24}, there for $p=2$, and it is omitted.
\begin{lemma}[Density bound from reverse Sobolev inequality]\label{lem:density bound}
For every $N\in(1,\infty),p\in(1,N)$ and $K \in \R$ there are constants $\lambda_{N,{K},p}\in(0,1),\, r_{{K^-},N,p}>0$  (with $r_{0,N,p}=+\infty$), $C_{N,K,p}>0$  such that the following holds. Set $p^*=pN/(N-p)$ and let $\Xdm$ be an $\RCD(K,N)$ space and let $u \in W^{1,p}_{loc}(\X)\cap L^{p^*}(\mm)$ be non-constant satisfying 
    \begin{equation}\label{eq:reverse sobolev lemma}
           \|u\|_{L^{p^*}(\mm)}^p\ge A\|\nabla u\|_{L^p(\mm)}^p,
    \end{equation}
    for some $A>0.$ Assume also that for some $\eta \in(0,\lambda_{N,K,p})$, $\rho \in (0,r_{{K^-},N,p}\wedge \frac{\lambda_{N,K,p}}8 \diam(\X))$ and $x\in\X$ it holds
    $$\|u\|^{p^*}_{L^{p^*}(B_{\rho}(x))}\ge (1-\eta) \|u\|_{L^{p^*}(\mm)}^{p^*}.$$
    Then
        \begin{equation}\label{eq:density bound}
        \frac{\mm(B_\rho(x))}{\rho ^N}\le \frac{C_{N,K,p}}{A^{N/p}}.
    \end{equation}
\end{lemma}
