\subsection{Convergence and stability properties}
In this part, we recall compactness and stability properties of the ${\sf RCD}$-class and discuss notions of convergence of functions on varying base space.




 We recall first the notion of pointed measured Gromov Hausdorff convergence of metric measure spaces. This concept goes back to Gromov \cite{Gromov07}, while the following definition is not standard and is taken from  \cite{GigliMondinoSavare13}. However, in the case of finite dimensional ${\sf RCD}$-spaces, this notion coincides with previous ones considered in the literature (see again \cite{GigliMondinoSavare13}). 

 Set $\bar \N \coloneqq \N \cup\{\infty\}$. A \emph{pointed} metric measure space is a quadruple $(\X,\sfd,\mm,x)$ where $\Xdm$ is a metric measure space and $x \in \X$.
\begin{definition}
Let $(\X_n,\sfd_n,\mm_n,x_n)$ be pointed metric measure spaces for $n \in \bar \N$. We say that $(\X_n,\sfd_n,\mm_n,x_n)$ converges to $(\X_\infty,\sfd_\infty,\mm_\infty,x_\infty)$ in the pointed measured Gromov Hausdorff topology, provided there are a metric space $(\Z,\sfd)$ and isometric embeddings $\iota_n \colon \X_n \to \Z$ for all $n \in \bar \N$ satisfying
\[
    (\iota_n)_\sharp \mm_n \weakto (\iota_\infty)_\sharp\mm_\infty,\qquad \text{in duality with }C_{bs}(\Z),
\]
and $\iota_n(x_n)\to \iota_\infty(x_\infty)$ as $n\uparrow\infty$. The metric space $(\Z,\sfd)$ is called the \emph{realization of the convergence}. In this case, we shortly say that $\X_n$ pmGH-converges to $\X_\infty$ and write $\X_n \overset{pmGH}{\to}\X_\infty$. 
\end{definition}
%Even if it is not strictly needed, we remark that this convergence is actually metrizable by a suitable distance of pointed metric measure spaces that we denote by $\sfd_{pmGH}$, see \cite{GigliMondinoSavare13}.


The key results are then the pre-compactness and the stability properties of the ${\sf RCD}$-condition, referring to \cite{Gigli10,AmbrosioGigliSavare11-2,GigliMondinoSavare13} (also recall \cite{Sturm06I,Sturm06II,LV09}) and thanks to Gromov's precompactness \cite{Gromov07}). 
\begin{theorem}\label{thm:gromov}
    Let $(\X_n,\sfd_n,\mm_n,x_n)$ be pointed ${\sf RCD}(K_n,N_n)$ spaces for $n\in\N$ and for some $K_n \in \R,N_n \in [1,\infty)$ with $K_n \to K \in \R, N_n \to N \in [1,\infty)$. Suppose that $\mm_n(B_1(x_n)) \in (v,v^{-1})$ for some $v>0$ independent on $n$. Then, there exist a pointed ${\sf RCD}(K,N)$ space $(\X_\infty,\sfd_\infty,\mm_\infty,x_\infty)$ and a subsequence $(n_k)$ such that $\X_{n_k} \overset{pmGH}{\to}\X_\infty$ as $k\uparrow\infty$.
\end{theorem}
%
%
It is well known that, as a by-product of the above result, we have the existence of blow downs (or asymptotic cones) of a pointed ${\sf RCD}(0,N)$ metric measure space $(\X,\sfd,\mm,x)$ with ${\sf AVR}(\X)>0$. A blowdown is any pointed metric measure space $(Y,\rho,\mu,y)$  arising as a pmGH-limit of $(\X,\sigma\cdot\sfd, \sigma^N\mm,x)$ along a suitable subsequence $\sigma_n\down 0$, possibly depending on $x\in \X$. 



Next, we recall some notions of convergence of functions along a pmGH-converging sequence, following \cite{Honda15,GigliMondinoSavare13,AmbrosioHonda17}and adopting the so-called \emph{extrinsic approach}, see \cite{GigliMondinoSavare13}.
\begin{definition}\label{def:lpconv}
 Let $(\X_n,\sfd_n,\mm_n,x_n)$ be pointed metric measure spaces for $n \in \bar \N$ and suppose that $\X_n \overset{pmGH}{\to}\X_\infty$ as $n\uparrow\infty$. Let $p \in (1,\infty)$ and fix a realization  of the convergence in $(\Z,\sfd)$. We say:
\begin{itemize}
\item[{\rm i)}] $f_n\in L^p(\mm_n)$ \emph{converges $L^p$-weak} to $f_\infty\in L^p(\mm_\infty)$, provided $\sup_{n \in \N}\|f_n\|_{L^p(\mm_n)}<\infty$ and $f_n\mm_n \weakto f_\infty\mm_\infty$ in duality with $C_{bs}(\Z)$;
\item[{\rm ii)}] $f_n\in L^p(\mm_n)$ \emph{converges $L^p$-strong} to $f_\infty\in L^p(\mm_\infty)$, provided it converges $L^p$-weak and $\limsup_n \|f_n\|_{L^p(\mm_n)} \le  \|f_\infty\|_{L^p(\mm_\infty)}$;
\item[{\rm iii)}] $f_n \in W^{1,p}(\X_n)$ \emph{converges $W^{1,p}$-weak} to $f_\infty \in L^p(\mm_\infty)$ provided it converges $L^p$-weak and $\sup_{n \in \N} \| \nabla f_n \|_{L^p(\mm_n)}<\infty$;
\item[{\rm iv)}] $f_n \in W^{1,p}(\X_n)$ \emph{converges $W^{1,p}$-strong} to $f_\infty \in W^{1,p}(\X_\infty)$ provided it converges $L^p$-strong and $\| \nabla f_n \|_{L^p(\mm_n)} \to \|\nabla f_\infty \|_{L^p(\mm_\infty)}$;
\item[{\rm v)}] $f_n\in L^p(\mm_n)$ \emph{converges $L^p_{loc}$-strong} to $f_\infty\in L^p(\mm_\infty)$, provided $\eta f_n$ converges $L^p$-strong to $\eta f_\infty$ for every $\eta \in C_{bs}(\Z)$.
%\item[$(v)$] We say that $f_n \in L^1(\mm_n)$ \emph{converges $L^1$-strong} to $f_\infty \in L^1(\mm_\infty)$, provided $\sigma \circ f_n \mm_n\weakto \sigma \circ f_\infty \mm_\infty$ in $C_{bs}(\Z)$ and $\lim_n \|f_n\|_{L^1(\mm_n)} = \|f_\infty \|_{L^1(\mm_\infty)}$, where $\sigma(z)=\emph{sgn}(z)\sqrt{z}$.
\end{itemize}
\end{definition}
We point out (see \cite{Honda15,GigliMondinoSavare13,AmbrosioHonda17}) that the strong notions of convergence are also metrizable. 
