\subsection{Technical results for locally Sobolev functions}
We extend some technical convergence results to the case of locally Sobolev functions. This is necessary for the goal of this note, as a Sobolev inequality of Euclidean type implies global integrability for a different exponent from that of the gradient.

We shall need the following lower semicontinuity result of gradient norms of locally Sobolev functions, using Theorem \ref{thm:Mosco Chp} that is now available.
\begin{proposition}\label{prop:Ch is Lp-lsc}
Let $p \in (1,\infty)$ and suppose $u_n\in W^{1,p}_{loc}(\X_n)$ converges $L^p_{loc}$-strong to $u_\infty$. Then 
\begin{equation}
      \|\nabla u_\infty \|^p_{L^p(\mm_\infty)} \le \liminf_{n\uparrow\infty} \| \nabla u_n \|^p_{L^p(\mm_n)},
\label{eq:Ch is Lp-lsc}  
\end{equation}
meaning that, if the right hand side is finite, then $u_\infty\in W^{1,p}_{loc}(\X_\infty)$ and \eqref{eq:Ch is Lp-lsc} holds. 
\end{proposition}
\begin{proof}
If the right hand side in \eqref{eq:Ch is Lp-lsc} is infinite then there is nothing to prove, so let us assume it to be finite. Fix any ball $B\subset Z$  and take $\eta \in \Lip_{bs}(\Z)$ constantly equal to $1$ on $B$. Since $\eta u_n$ converges $L^p$-strong to $\eta u_\infty$, Proposition \ref{prop:lsc on open} yields
\[
    \int_B  |\nabla u_\infty |^p \, \d \mm_\infty = \int_B |\nabla (\eta u_\infty) |^p \, \d \mm_\infty  \le \liminf_n \int_B  |\nabla (\eta u_n)|^p \, \d \mm_n \le \liminf_n\|\nabla u_n\|^p_{L^p(\mm_n)}<\infty,
\]
where in the first and last step we used the locality of weak upper gradients. By the arbitrariness of $B$, the proof follows.
\end{proof}
%
%
%
A direct corollary of the compactness results in Proposition \ref{prop:rellich W1p} and the above lower semicontinuity property is the following local compactness that we single out for later use.
\begin{lemma}\label{lem:pmGHW1ploc}
Let $p,q\in(1,\infty)$ with $q\ge p$ and suppose $u_n \in W^{1,p}_{loc}(\X_n)$ converges $L^q$-weak to $u_\infty \in L^q(\mm_\infty)$ and $\sup_n \|\nabla u_n\|_{L^p(\mm_n)} <\infty$. Then, up to  a subsequence $u_n$ converges $L^p_{loc}$-strong to $u_\infty \in W^{1,p}_{loc}(\X_\infty)$ with $|\nabla u_\infty|\in L^p(\mm_\infty)$. Finally, if also $\|\nabla u_n\|_{L^p(\mm_n)} \to \|\nabla u_\infty\|_{L^p(\mm_\infty)}$, then also $|\nabla u_n|$ converges $L^p$-strong to $|\nabla u_\infty|$.
\end{lemma}
\begin{proof}
We first prove the $L^p_{loc}$-strong convergence. Consider $\eta \in \Lip_{bs}(\Z)$ (recall that $(\Z,\sfd)$ is a space realizing the convergence). Notice that the sequence $\eta u_n$ satisfies $\supp(\eta u_n)\subset B_R(x_n)$ for some fixed $R>0$ independent on $n\in\N$. Since $q\ge p$, by H\"older inequality and the Leibniz rule we have  $\sup_n \| \eta u_n\|_{W^{1,p}(\mm_n)} <+\infty$. Thus by Proposition \ref{prop:rellich W1p}, there exists a subsequence $(n_k)$ such that  $\eta u_{n_k}$ converges $L^p$-strong to some $v \in W^{1,p}(\X_\infty)$, which must be equal to $\eta u_\infty$ by uniqueness of weak limits. In particular, Proposition \ref{prop:Ch is Lp-lsc} guarantees that $u_\infty \in W^{1,p}_{loc}(\X_\infty)$ with $|\nabla u_\infty|\in L^p(\mm_\infty)$. This shows the first part of the statement. For the second part we assume that $\|\nabla u_n\|_{L^p(\mm_n)} \to \|\nabla u_\infty\|_{L^p(\mm_\infty)}$.  By considering any ball $B\subset\X_\infty\subset \Z$ and $\eta \in \Lip_{bs}(\Z)$ with $\eta\equiv 1$ on $B$, we can argue as in  the proof of Lemma \ref{lem:Lpstrong gradient}:
\begin{align*}
     \int_B G\,\d \mm_\infty &= \int_{\overline{B}} G \,\d \mm_\infty \ge \limsup_{n\uparrow\infty}  \int_{\overline{B}} |\nabla u_n|^p\,\d \mm_n \ge \limsup_{n\uparrow\infty}  \int_B |\nabla (\eta u_n)|^p\,\d \mm_n \\
     &\overset{\eqref{eq:lsc chp on open}}{\ge} \int_B|\nabla (\eta u_\infty)|^p\,\d\mm_\infty = \int_B|\nabla  u_\infty|^p\,\d\mm_\infty,
\end{align*}
where $G$ is any $L^p$-weak limit of $|\nabla u_n|$, which exists up to further passing to a subsequence. Notice that, in the application of \eqref{eq:lsc chp on open}, we are using that $\eta u_n$ converges $L^p$-weak to $\eta u_\infty$ (actually, also $L^p$-strong, under the current assumptions) and $\sup_n \|\eta u_n\|_{W^{1,p}(\X_n)}<\infty$ by the Leibniz rule. This concludes the proof, by arbitrariness of $B$, by the same reasoning as at the end of Lemma \ref{lem:Lpstrong gradient}.
\end{proof}
%
Next, we show the existence of certain recovery sequences.
\begin{lemma}\label{lem:strongrecov}
Let $p,q \in (1,\infty)$ with $q\ge p$ and  $u_\infty \in W^{1,p}_{loc}(\X_\infty)\cap L^{q}(\mm_\infty)$ with  $|\nabla u_\infty|\in L^p(\mm_\infty)$. Then, there exists $u_n \in W^{1,p}_{loc}(\X_n)\cap L^{q}(\mm_n)$ that converges $L^{q}$-strong and $L^p_{loc}$-strong to $u_\infty$ and so that $|\nabla u_n|$ converges $L^p$-strong to $|\nabla u_\infty|$.
\end{lemma}
\begin{proof}
By \cite[Lemma 3.2]{NobiliViolo24} (holding also for $p\neq 2$) we can find a sequence $u_n \in W^{1,p}(\X_\infty)\cap L^q(\mm_\infty)$ such that $u_n \to u_\infty$ and $|\nabla u_n|\to |\nabla u_\infty|$ strongly in $L^p(\mm_\infty).$ From \cite[Lemma 6.4]{NobiliViolo21}  (there written for compact spaces and for $p=2$, but the same proof works in the present setting)  there exists a sequence $u_n^k \in W^{1,p}(\X_n)$ that converges $L^q$-strong and $W^{1,p}$-strong to $u_n$ as $k\uparrow \infty$. Then, the sought $L^q$-strong convergence follows by a diagonal argument, while the $L^p_{loc}$-strong convergence follows from Lemma \ref{lem:pmGHW1ploc}. Finally, the $L^p$-strong convergence of $|\nabla u_n|$ follows by the last conclusion in Lemma \ref{lem:pmGHW1ploc}.
\end{proof}
%
%
We conclude this part by showing that there is a linear convergence of gradients of locally Sobolev functions. 
\begin{proposition}[Linearity]\label{prop:linearity W1ploc convergence}
    Let $p \in (1,\infty)$ and suppose that $u_n,v_n \in W^{1,p}_{loc}(\X_n)$ both converges  $L^p_{loc}$-strong to $u_\infty \in W^{1,p}_{loc}(\X_\infty)$. If $\|\nabla u_n\|_{L^p(\mm_n)}\to \|\nabla u_\infty\|_{L^p(\mm_\infty)}$ and $\|\nabla v_n\|_{L^p(\mm_n)}\to \|\nabla u_\infty\|_{L^p(\mm_\infty)}$ as $n\uparrow\infty$, then we have
    \[
        \lim_{n\uparrow\infty}\|\nabla (u_n -v_n)\|_{L^p(\mm_n)} = 0.
    \]
\end{proposition}
\begin{proof}
The statement is known if $p=2$ when $u_n,v_n$ converges $L^2$-strong, i.e.\ the $W^{1,2}$-strong convergence is linear. This simply follows by cosine law for the $2$-weak upper gradients (having assumed infinitesimal Hilbertianity) and the convergence of the couplings \cite[Eq. 5.3]{AmbrosioHonda17}. We handle here the arbitrary exponent case. 


First, since $\X_n$ are assumed ${\sf RCD}$ spaces, we can appeal to the Clarkson inequalities (see \cite[Eq. (4.3)]{GigliNobili21} to write for all $n\in\N$: if $p\ge 2$ then
\[
    \left\|\nabla \left(\frac{u_n -v_n}{2}\right)\right\|^p_{L^p(\mm_n)}+  \left\|\nabla \left(\frac{u_n +v_n}{2}\right)\right \|^p_{L^p(\mm_n)} \le \frac{1}{2}\|\nabla u_n\|_{L^p(\mm_n)}^p +  \frac{1}{2}\|\nabla v_n\|_{L^p(\mm_n)}^p,
\]
while, if $p\in (1,2)$, denoting by $q$ the H\"older conjugate, we have
\[
    \left\|\nabla \left(\frac{u_n -v_n}{2}\right)\right\|^q_{L^p(\mm_n)}+  \left\|\nabla \left(\frac{u_n +v_n}{2}\right)\right \|^q_{L^p(\mm_n)} \le \left(\frac{1}{2}\|\nabla u_n\|^p_{L^p(\mm_n)} +  \frac{1}{2}\|\nabla v_n\|^p_{L^p(\mm_n)}\right)^{\frac qp}.
\]
For the validity of the above, the relevant fact is that $\X_n$ are infinitesimal Hilbertian spaces and that weak upper gradients do not depend on the integrability exponent in a weak sense (see \cite{GigliNobili21}). 
% In particular, rewriting the above with $u_n' \coloneqq \frac{u_n -v_n}{2}$ and $v_n' \coloneqq \frac{u_n +v_n}{2}$ we deduce: if $p\ge 2$
% \[
%     \left\|\nabla v_n \right\|^p_{L^p(\mm_n)}+  \left\|\nabla u_n\right \|^p_{L^p(\mm_n)} \le \frac{1}{2}\left\|\nabla \left(\frac{u_n -v_n}{2}\right)\right\|_{L^p(\mm_n)}^p +  \frac{1}{2}\left\|\nabla\left(\frac{u_n +v_n}{2}\right)\right\|_{L^p(\mm_n)}^p,
% \]
% while, if $p\in (1,2)$
% \[
%     \left\|\nabla v_n \right\|^q_{L^p(\mm_n)}+  \left\|\nabla u_n \right \|^q_{L^p(\mm_n)} \le \left(\frac{1}{2}\left\|\nabla \left(\frac{u_n -v_n}{2}\right)\right\|^p_{L^p(\mm_n)} +  \frac{1}{2}\left\|\nabla\left(\frac{u_n +v_n}{2}\right)\right\|^p_{L^p(\mm_n)}\right)^{\frac qp},
% \]
% for all $n\in\N$. 
By these  inequalities, in the whole range $p \in (1,\infty)$, the conclusion of the proof will be achieved provided we can show that
\[
    \lim_{n\uparrow\infty}\|\nabla (u_n +v_n)\|_{L^p(\mm_n)}= 2\|\nabla u_\infty\|_{L^p(\mm_\infty)}.
\]
The above will directly follow from the chain of inequalities
\begin{align*}
    2\|\nabla u_\infty\|_{L^p(\mm_\infty)} &\overset{(\ast)}{\le}\liminf_{n\uparrow\infty}\|\nabla (u_n +v_n)\|_{L^p(\mm_n)} \\
    &\le \lim_{n\uparrow\infty}\|\nabla u_n\|_{L^p(\mm_n)}  + \lim_{n\uparrow\infty}\|\nabla v_n\|_{L^p(\mm_n)} =2\|\nabla u_\infty\|_{L^p(\mm_\infty)},
\end{align*}
provided $(\ast)$ is true. However, $(\ast)$ follows by Proposition \ref{prop:Ch is Lp-lsc} and noticing that the $L^p_{loc}$-strong convergence is linear (simply notice that $\eta(u_n+v_n)$ converges to $2\eta u_\infty$ for every $\eta \in \Lip_{bs}(\Z)$, whence $u_n+v_n$ converges $L^p_{loc}$-strong to $2u_\infty$).
\end{proof}
