\section{Concentration compactness principles}
In this part, we extend for an exponent $p\neq 2$ the concentration compactness principles studied in \cite{NobiliViolo21,NobiliViolo24}. We state the main result and provide the proof at the end of this section.
\begin{theorem}\label{thm:CC extremal}
    For every $N\in (1,\infty)$ and $p \in (1,N)$, there   exists $\eta_{p,N}\in(0,1/2)$ such that the following holds. Let $(Y_n,\rho_n,\mu_n,y_n)$ be pointed ${\sf RCD}(0,N)$ spaces. Set $p^*=pN/(N-p)$. Suppose that for some $A_n\to A \in(0,\infty)$ it holds
   \begin{equation}
   \|u\|_{L^{p^*}(Y_n)} \le A_n\|\nabla u\|_{L^p(Y_n)},\qquad \forall u \in W^{1,p}(Y_n).\label{eq:convention}
   \end{equation}
Furthermore, suppose there are non-constant functions $u_n \in W^{1,p}(Y_n)$ with $\| u_n\|_{L^{p^*}(\mu_n)} =1$  and
\begin{align}
&\sup_{y \in Y_n} \int_{B_1(y)}|u_n|^{p^*}\,\d\mu_n=\int_{B_1(y_n)}|u_n|^{p^*}\,\d\mu_n = 1-\eta,\label{eq:Levyscalings} \\
 &\| u_n\|_{L^{p^*}(\mu_n)} \ge  \tilde A_n \|\nabla u_n\|_{L^p(\mu_n)},\label{eq:extremals}
\end{align}
for  some $\tilde A_n \to A$  and  $\eta \in(0,\eta_{p,N}).$ Then, up to a subsequence, we have:
    \begin{itemize}
    \item[ \rm i)]
    there is a pointed $\RCD(0,N)$-space $(Y,\rho,\mu,y)$ so that 
    \[
    Y_n\overset{pmGH}{\to} Y,
    \]
    and it holds
    \begin{equation}
       \|u\|_{L^{p^*}(Y)} \le A\|\nabla u\|_{L^p(Y)},\qquad \forall u \in W^{1,p}(Y);\label{eq:sob limit Y}
       \end{equation}
    \item[ \rm ii)]  $u_n$ converges  $L^{p^*}$-strong to some $0\neq u_\infty \in W^{1,p}_{loc}(Y)$ with $|\nabla u_\infty| \in L^p(\mu)$ and
    \[
       \int |\nabla u_n|^p\, \d \mu_n \to  \int |\nabla u_\infty|^p\,\d\mu, \qquad  \text{as }n\uparrow\infty;
    \]
    \item[ \rm iii)] it holds
    \[
        \| u_\infty\|_{L^{p^*}(\mu)} =  A \|\nabla u_\infty\|_{L^p(\mu)}.
    \]
\end{itemize}
\end{theorem}
Compare the above to \cite[Theorem 6.2]{NobiliViolo24} and notice that here we drop the $B$-term in the Sobolev inequality, as this is not needed in this note. This will slightly simplify some arguments. 
%
%
%


\subsection{Decomposition principle}
We study here a decomposition principle describing concentration phenomena of sequences of functions and measures arising from Sobolev inequalities. This extends \cite[Lemma A.7]{NobiliViolo24} (in turn relying on \cite[Lemma 6.6]{NobiliViolo21}) for $p\neq 2$, but in the absence of the $B$-term in the Sobolev inequality that we shall never need this in this note. The proof is similar, but we include all the details to handle the general exponent and to explicitly highlight where the technical machinery of Section \ref{sec:Mosco} will be needed.
\begin{lemma}\label{lem:conccomp 2}
Let $(\X_n,\sfd_n,\mm_n,x_n)$ be  pointed $\RCD(K,N)$ spaces, $n \in\N\cup\{\infty\}$, for some $K \in \R$, $N \in(1,\infty)$  with $\X_n\overset{pmGH}{\to}\X_\infty$ and assume that \eqref{eq:convention} holds for some $A_n>0$ uniformly bounded and $p\in (1,N)$.


Suppose further that $u_n \in W_{loc}^{1,p}(\X_n) \cap  L^{p^*}(\mm_n)$ with $\sup_n \|\nabla u_n\|_{L^p(\mm_n)}<\infty $ is $L^p_{loc}$-strong converging to $u_\infty \in L^{p^*}(\mm_\infty)$ and suppose that $|\nabla u_n|^p \mm_n \weakto \omega,$ $|u_n|^{p^*}\mm_n\weakto \nu$ in duality with $C_{bs}(\Z)$ and $C_b(\Z)$, respectively (where $(\Z,\sfd)$ is a fixed realization of the convergence). 

Then, $u_\infty \in W^{1,p}_{loc}(\X_\infty)$ with $|\nabla u_\infty|\in L^p(\mm_\infty)$ and
\begin{itemize}
    \item[{\rm i)}] there are a countable set $J$, points $(x_j)_{j\in J}\subset \X_\infty$ and  $(\nu_j)_{j\in J}\subset\R^+$ so that
    \[ \nu =|u_\infty|^{p^*}\mm_\infty +\sum_{j\in J}\nu_j\delta_{x_j};\]
    \item[{\rm ii)}] there is $(\omega_j)_{j\in J} \subset \R^+$ satisfying $\nu_j^{p/p^*} \le (\limsup_{n}A_n)\omega_j$ for every $j\in J$ and such that
    \[\omega \ge |\nabla u_\infty|^p\mm_\infty +\sum_{j\in J}\omega_j\delta_{x_j}.\]
    In particular, we have $\sum_j \nu_j^{p/p^*}<\infty$.
    \end{itemize}
\end{lemma}
\begin{proof}
By assumptions, we can also assume that $u_n$ is $L^{p^*}$-weak converging to $u_\infty$ (by uniqueness of limits), simply by plugging $u_n$ in \eqref{eq:convention} to deduce a uniform $L^{p^*}$-bound. We subdivide the proof into two steps.


\noindent{\sc Step 1}. Suppose first that $u_\infty=0$. Let $\varphi \in \LIP_{bs}(\Z)$ and plugging $\varphi u_n\in W^{1,p}(\X_n)$ in \eqref{eq:convention} yields
\[ \left( \int |\varphi|^{p^*}|u_n|^{p^*}\, \d \mm_n \right)^{\frac{1}{p^*}} \le A_n\left(\int |\nabla(\varphi u_n)|^p\, \d \mm_n\right)^{\frac 1p}, \qquad \forall n\in \N.\]
Thanks to the weak convergence, the left hand side of the inequality tends to $(\int |\varphi|^{p^*}\,\d \nu )^{1/p^*}$. Instead, estimating by the Leibniz-rule  $\int |\nabla(\varphi u_n)|\, \d \mm_n \le \int |\nabla \varphi||u_n| + |\phi||\nabla u_n|\, \d \mm_n$ and using the $L^p_{loc}$-strong convergence to deduce $\int |\nabla \varphi|^p|u_n|^p\d \mm_n\to0$, we get
\[
\left( \int |\varphi|^{p^*} \d \nu \right)^{1/p^*} \le \limsup_n A_n \left(\int |\varphi|^p\, \d \mu\right)^{1/p}, \qquad \forall \varphi \in \LIP_{bs}(\Z).
\]
The application of \cite[Lemma 6.5]{NobiliViolo21} in $\Z$ gives conclusions i),ii) for the case $u_\infty=0$. Notice that the points $(x_j)_{j\in J}$ (which are a-priori in $\Z$) can be proved to belong actually to $\X_\infty$ noticing, for any $j \in J$ that the  weak convergence $|u_n|^{p^*}\mm_n \rightharpoonup\nu$ implies the existence of a sequence $y_n \in \supp(\mm_n)=\X_n$ such that $\sfd_\Z(y_n,x_j)\to0.$ Then the pmGH-convergence of $\X_n$ to $\X_\infty$ ensures that $x_j \in \X_\infty$.


\noindent \textsc{Step 2}. Here $u_\infty$ is possibly nonzero. By stability of Sobolev inequalities (c.f.\ \cite[Lemma 4.1]{NobiliViolo21}), we know that \eqref{eq:convention} holds in $\X_\infty$ with $A\coloneqq \limsup_n A_n$. From Lemma \ref{lem:strongrecov} there exists a sequence $\tilde u_n \in W^{1,p}_{loc}(\X_n)$ such that $\tilde u_n$ converges in $L^{p^*}$-strong and $L^{p}_{loc}$-strong to $u_\infty$ and $|\nabla u_n|$ converges $L^p$-strong to $|\nabla u_\infty|$. For every $\varphi \in \Lip_{bs}(\Z)$ nonnegative, by the Brezis-Lieb lemma \cite[Lemma A.1]{NobiliViolo24} we deduce
\begin{equation}
\lim_{n\uparrow\infty}\int |\varphi|^{p^*}|u_n|^{p^*}\,\d\mm_n - \int |\varphi|^{p^*}|u_n-\tilde u_n|^{p^*}\,\d\mm_n = \int |\varphi|^{p^*}|u_\infty|^{p^*}\,\d\mm_\infty.
\label{eq:step BL}
\end{equation}
Consider now the sequence $v_n := u_n-\tilde u_n$. Clearly $v_n$ converge $L^{p}_{loc}$-strong and $L^{p^*}$-weak to zero. Moreover, by tightness using the estimates $ |v_n|^{p^*} \le 2^{p^*}(|u_n|^{p^*}+|\tilde u_n|^{p^*})$ and $|\nabla v_n|^p\le 2^p(|\nabla u_n|^p+|\nabla \tilde u_n|^p) $ we deduce, up to a subsequence, that $|\tilde u_n|^{p^*}\mm_n$ weakly converges in duality with $C_b(\Z)$ to some probability measure $\tilde \nu$ and $|\nabla v_n|^p\mm_n$ weakly converges in duality with $C_{bs}(\Z)$ to some finite Borel measure $\tilde w$. Thus, Step 1 applies for the sequence $v_n$ and the conclusions i),ii) holds for the measures $\tilde \nu,\tilde \omega$, for suitable countable set $J$, points $(x_j)\subset \X_\infty$ and weights $(w_j)\subset \R^+$. Then, conclusion i) for $\nu $ is immediate recalling \eqref{eq:step BL} with the underlying weak convergence. 

We are left to show ii) for $\omega$. We claim that
\begin{align*}
    &\omega(\{x_j\}) = \tilde \omega(\{ x_j\})\ge \omega_j,\qquad \forall j \in J,\\
    &\omega \ge |\nabla u_\infty|\mm_\infty.
\end{align*}
Clearly, by mutual singularity the combination of the two would conclude the proof. Fix $j \in J$ and $\eps >0$, consider $\nchi_\eps \in \LIP_{bs}(\Z)$, $0\le \nchi_\eps \le 1, \nchi_\eps(x_j)=1$ and supported in $B_\eps(x_j)$ and let us estimate
\begin{equation*}
    \begin{split}
       \Big| \int \nchi_\eps|\nabla u_n|^p\, \d \mm_n -\int \nchi_\eps|\nabla v_n|^p\,\d\mm_n\Big| &\le  p \int\nchi_\eps  \big||\nabla u_n|-|\nabla v_n|\big|\big(|\nabla u_n|^{p-1}+|\nabla v_n|^{p-1}\big)\, \d \mm_n \\
        &\le p \int \nchi_\eps|\nabla \tilde u_n|\big(|\nabla u_n|^{p-1}+|\nabla v_n|^{p-1}\big)\, \d \mm_n \\
       &\le p \left(\int\nchi_\eps^p|\nabla \tilde u_n|^p\, \d \mm_n\right)^{1/p}\left(\| \nabla u_n\|_{L^p(\mm_n)}^{\frac{p-1}{p}} +\| \nabla v_n\|_{L^p(\mm_n)}^{\frac{p-1}{p}}\right).
    \end{split}
\end{equation*}
Recalling that $|\nabla \tilde u_n|\to |\nabla u_\infty|$ $L^p$-strong by Lemma \ref{lem:strongrecov},  we deduce that $\int\nchi_\eps^p|\nabla\tilde u_n|^p\, \d \mm_n\to \int\nchi_\eps^p|\nabla u_\infty|^p\, \d \mm_\infty$. Moreover $\int\nchi_\eps^p|\nabla u_\infty|^p\, \d \mm_\infty\to0$ as $\eps\to 0^+$ and $|\nabla u_n|,|\nabla v_n|$ are uniformly bounded in $L^p(\mm_n)$. Therefore taking first $n \to +\infty$ and afterwards $\eps\to 0^+$ we get $\omega(\{x_j\}) = \tilde \omega(\{ x_j\})$. Now, since $\omega$ is non-negative and $\tilde \omega \ge \sum_{j \in J}\omega_j\delta_{x_j}$ the first claim follows. 


We next prove the second claim. We fix $\phi \in \Lip_{bs}(\Z)$, $\phi \ge 0$, and $\nchi \in \LIP_{bs}(\Z)$ be such that $\nchi=1$ in $\supp (\phi)$. It is easy to check that $\nchi u_n$ is $W^{1,p}$-weak converging to $\nchi u_\infty$ (recall that $u_n\to u_\infty$ in $L^p_{loc}$). Then, by Proposition \ref{prop:lsc on open} (see \eqref{eq:lsc chp glsc}) and locality we get 
\[
     \int \phi |\nabla u_\infty|^p\, \d \mm_\infty=\int \phi |\nabla (\nchi u_\infty)|^p\, \d \mm_\infty \le \liminf_{n\uparrow\infty}\int \phi |\nabla (\nchi u_n)|^p\, \d \mm_n= \int \phi \,\d\omega.
\]
By arbitrariness of $\varphi$, the  second claim is proved and, as discussed, the proof is  concluded.
\end{proof} 
