\subsection{Proof of concentration compactness} Here we finally combine the previous technical results and prove the main concentration compactness principle.
\begin{proof}[Proof of Theorem \ref{thm:CC extremal}]  We subdivide the proof into different steps.

\noindent{{\sc Step 1}}. We take $\eta_{N,p}\coloneqq \frac{\lambda_{0,N,p}}8\wedge  \frac13$, with $\lambda_{0,N,p}$ as in Lemma \ref{lem:density bound}. To show i), we first need to check the assumptions of the Gromov pre-compactness result in this setting (c.f.\ Theorem \ref{thm:gromov}), i.e.\ we check that $\mu_n(B_1(y_n)) \in (v^{-1},v) $ for some $v>1.$  If we can prove that $\diam(Y_n)> \eta_{N,p}^{-1}\ge 8\lambda_{0,N,p}^{-1}$, then the assumptions \eqref{eq:Levyscalings} and \eqref{eq:extremals} make it possible to invoke Lemma \ref{lem:density bound} (for $C_{0,N,p}>0$ as in this Lemma) to obtain
\[
\limsup_n \mu_n(B_1(y_n))\le \limsup_n \frac{C_{0,N,p}}{ (\tilde A_n)^{N/p}}= \frac{C_{0,N,p} }{ A^{N/p}}<+\infty.
\]
However, this is actually trivially true since the validity of \eqref{eq:convention} implies that $\diam(Y_n)=+\infty$, see \cite[Theorem 4.6]{NobiliViolo21}. On the other hand, plugging in \eqref{eq:convention} the functions $\phi_n\in \LIP(Y_n)$ such that $\phi_n=1$ in $B_1(y_n)$ with $\supp \varphi_n \subset B_2(y_n)$, $0\le \phi_n\le 1$ and $\Lip(\phi_n)\le 1$, we get
\[
\mu_n(B_1(y_n))^{p/p^*}\le A^p\mu_n(B_2(y_n))\le 2^NA^p\mu_n(B_1(y_n)),
\]
where we used the doubling property of $\mu_n$ (see \cite[Corollary 2.4]{Sturm06II}). Since $A_n \to A>0$ we also obtain $\liminf_n \mu_n(B_1(y_n))>0.$ Therefore up to a not relabeled subsequence, we deduce that $Y_n$ pmGH converge to some pointed $\RCD(0,N)$ space $(Y,\rho,\mu,y)$. Moreover, the stability of the Sobolev inequalities \cite[Lemma 4.1]{NobiliViolo21} guarantees that \eqref{eq:sob limit Y} holds. This settles point i).  


\noindent{{\sc Step 2}}. From now on we assume to have fixed a realization of the convergence in a proper metric space $(\Z,\sfd)$. Set $\nu_n \coloneqq  |u_n|^{p^*}\mu_n$. Up to a subsequence, (exactly) one of cases i),ii),iii) in \cite[Lemma A.6]{NobiliViolo24} holds. We claim i) (i.e.\ compactness) occurs. First, notice that vanishing as in case ii) cannot occur:
\[ \limsup_{n\uparrow\infty} \sup_{y \in Y_n }\nu_n(B_R(y)) \ge \limsup_{n\uparrow\infty} \nu_n(B_1(y_n)) \stackrel{\eqref{eq:Levyscalings}}=1-\eta,\qquad  \forall R\ge 1.
\]
Thus, it remains to exclude the dichotomy case iii). Suppose by contradiction that  this occurs for some $\lambda \in (0,1)$ (with $\lambda \ge \limsup_{n}\sup_z \nu_n(B_R(z))$ for all $R>0$), sequences $R_n\uparrow \infty$, $(z_n)\subset \Z$ and measures $\nu_n^1,\nu_n^2$ so that
\[
    \begin{split}
        &0 \le \nu_n^1+\nu_n^2 \le \nu_n, \\
        &\supp( \nu_n^1) \subset B_{R_n}(z_n), \quad \supp( \nu_n^2) \subset \Z \setminus B_{10R_n}(z_n), \\
        & \limsup_{n\uparrow\infty}   \ \big| \lambda -  \nu_n^1( \Z) \big|+ \big| (1-\lambda ) -  \nu_n^2( \Z) \big|  =0 .
    \end{split}
\]
We claim first that $\supp (\nu_n^1) \subset B_{3R_n}(y_n)$ and $\supp (\nu_n^2) \subset \Z\setminus B_{4R_n}(y_n)$. Indeed $\lambda \ge \limsup_{n\uparrow\infty} \nu_n(B_1(y_n)) = 1-\eta$ and 
$$\liminf_{n\uparrow\infty} \nu_n(B_{R_n}(z_n)) \ge\liminf_{n\uparrow\infty}  \nu_n^1(B_{R_n}(z_n))=\lim_{n\uparrow\infty} \nu_n^1(\Z) = \lambda\ge 1-\eta.$$  Since $\nu_n(B_1(y_n))=1-\eta$ and $\eta<1/2$, this implies that for $n$ large enough $B_{R_n}(z_n) \cap B_1(y_n) \neq 0$, which implies the claim, provided $R_n\ge 1.$


Let $\varphi_n$ be a Lipschitz cut-off so that $0\le  \varphi_n \le 1, \varphi_n \equiv 1$ on $B_{3R_n}(y_n)$, $\supp (\varphi_n)\subset B_{4R_n}(y_n)$  and $\Lip(\varphi_n)\le R_n^{-1}$, for every $n \in \N$. Since 
\begin{equation}
1\ge |\varphi_n|^p + |(1-\varphi_n)|^p,\qquad\text{in $\Z$},\label{eq:phi one minus phi}
\end{equation} 
we can estimate by triangular inequality, the Leibniz rule and  Young inequality
\begin{equation}
\begin{split}
      \|\nabla u_n\|^p_{L^p(\mu_n)}  &\ge \| \varphi_n|\nabla u_n| \|^p_{L^p(\mu_n)} +  \| (1-\varphi_n) |\nabla u_n|  \|^p_{L^p(\mu_n)} \\
       &\ge \| \nabla (u_n\varphi_n)\|_{L^p(\mu_n)}^p+ \|\nabla (u_n(1-\varphi_n)) \|_{L^p(\mu_n)}^p - R_n(\delta)
\end{split}
  \label{eq:estim 1}
\end{equation}
for every $\delta>0$ and every $n$, where the reminder $R_n(\delta)$ can be estimated, for a suitable constant $C_p>0$, as follows
\[
R_n(\delta) \le \frac{ C_p +1}{\delta^p}\|u_n|\nabla \varphi_n|\|^p_{L^p(\mm_n)} + C_p \delta^{\frac{p}{p-1}} \|\nabla u_n\|^p_{L^p(\mm_n)}.
\]
Setting $O_n\coloneqq  B_{4R_n}(y_n)\setminus B_{3R_n}(y_n)$, we have by the H\"older inequality
\[ \| u_n |\nabla \varphi_n| \|^p_{L^p(\mu_n)} \le {R_n}^{-p}\| u_n\|^p_{L^{p^*}(O_n)} \mu_n(O_n)^{p/N} \le   4^p v^{p/N}\| u_n\|^p_{L^{p^*}(O_n)},   \]
having used that $\mu_n(O_n) \le \mu_n(B_{4R_n}(y_n))\le (4R_n)^N\mu_n(B_1(y_n))\le    (4R_n)^Nv$, by the Bishop-Gromov inequality, for suitable $v>0$ as found in Step 1. Notice that we also have
\[ \limsup_{n\uparrow\infty} \| u_n\|_{L^{p^*}(O_n)} \le  \limsup_{n\uparrow\infty}\Big| 1 -  \nu^1_n(\Z)  - \nu^2_n(\Z)  \Big|^{1/p^*}  =0,\]
from which we get $ \lim_n \| u_n |\nabla \varphi_n| \|^p_{L^p(\mu_n)} =0$. Therefore, recalling that $\|\nabla u_n\|^p_{L^p(\mu_n)}$ is uniformly bounded by \eqref{eq:extremals}, choosing appropriately $\delta_n\to 0$,  we get
\begin{equation}\label{eq:zero reminder}
    R_n(\delta_n)\to 0.
\end{equation}
Thus, recalling that $\lim_n A_n = \lim_n \tilde A_n$, we get
\begin{align*}
       1 = \|u_n\|_{L^{p^*}(\mm_n)}^p &\overset{\eqref{eq:extremals},\eqref{eq:estim 1},\eqref{eq:zero reminder}}{\ge}  \limsup_{n\uparrow\infty}   A^p_n  \| \nabla (u_n\varphi_n) \|^p_{L^p(\mu_n)}   +  A^p_n\| \nabla (u_n(1-\varphi_n)) \|^p_{L^p(\mu_n)}    \\
      &\overset{\eqref{eq:convention}}{\ge}  \limsup_{n\uparrow\infty}    \| u_n\varphi_n\|^p_{L^{p^*}(\mu_n)} +  \| u_n(1-\varphi_n)\|^p_{L^{p^*}(\mu_n)}  \\
       &\ge \limsup_{n\uparrow\infty} \big( \nu^1_n(\Z)\big)^{p/p^*} +\big( \nu^2_n(\Z)\big)^{p/p^*} \\
      &\ge \lambda ^{p/p^*} +(1-\lambda)^{p/p^*} >1,
\end{align*}
having used the strict concavity of $t \mapsto t^{p/p^*}$ and the fact that $\lambda \in (0,1)$. This gives a contradiction, hence the dichotomy case cannot occur. 


\noindent{\sc Step 3}. In the previous step, we proved thus that i) in \cite[Lemma A.6]{NobiliViolo24} occurs, i.e.\  there a $(z_n) \subset \Z$ so that for every $\eps>0$ there exists $R\coloneqq R(\eps)$ so that $\int_{B_R(z_n)} |u_n|^{p^*}\,\d\mu_n \ge 1-\eps$ for all $ n \in \N$. If $\eps <1/2$, we have $B_R(z_n) \cap B_1(y_n) \neq \emptyset$ and
\begin{equation}
    \int_{B_{2R+1}(y_n)} |u_n|^{p^*}\,\d\mu_n \ge 1-\eps\qquad \forall n \in \N.\label{eq:usigmaCompactness}
\end{equation}
Moreover $y_n\to y$ in $\Z$, hence $|u_n|^{p^*}\mu_n$ is tight as a sequence of probabilities (recall $\Z$ is chosen proper). Thus, along a not relabeled subsequence, it converges in duality with $C_{b}(\Z)$ to some probability measure $\nu$. Additionally, up to a further subsequence, we have that $u_n$ is $L^{p^*}$-weak convergent to some $u \in L^{p^*}(\mu)$ with $\sup_n \|\nabla u_n\|_{L^p(\mu_n)}<\infty$ and also that $|\nabla u_n|^p\,\d\mu_n \weakto \omega$ in duality with $C_{bs}(\Z)$ for some bounded Borel measure $\omega.$ We can invoke Lemma \ref{lem:pmGHW1ploc} and, up to a further subsequence, we also have that $u_n$ converges $L^{p}_{loc}$-strong to some $u\in L^p_{loc}(\mu)$, together with the facts $u \in W^{1,p}_{loc}(Y)$ and $|\nabla u|\in L^p(\mu)$. 


Next, by Lemma \ref{lem:conccomp 2}, we infer the existence of countably many points $\{x_j\}_{j \in J}\subset Y$ and positive weights $(\nu_j),(\omega_j)\subset \R^+$, so that $\nu =|u|^{p^*}\mu +\sum_{j\in J}\nu_j\delta_{x_j}$ and $\omega \ge |\nabla u|^p\mu +\sum_{j\in J}\omega_j\delta_{x_j}$, with $A\omega_j \ge \nu_j^{p/p^*}$  and in particular $\sum_j \nu_j^{p/p^*}<\infty$.  Notice that $\lim_n \| \nabla   u_n \|^p_{L^p(\mu_n)} \ge \omega(\Z)$ holds by lower semicontinuity, therefore we can estimate
    \begin{align*}
        1 =  \lim_{n\uparrow\infty} \int |u_n|^{p^*}\, \d \mu_n  &\ge \liminf_{n\uparrow\infty}  \tilde  A_n\| \nabla   u_n \|^p_{L^p(\mu_n)} \ge  A \omega(\Z)\\
         &\ge  A\int |\nabla  u|^p\,\d \mu + \sum_{j\in J} \nu_j^{p/p^*} \overset{\eqref{eq:sob limit Y}}{\ge} \Big(\int |u|^{p^*}\, \d \mu\Big)^{p/p^*} + \sum_{j\in J} \nu_j^{p/p^*} \\
           &\ge \Big( \int |u|^{p^*}\, \d \mu  + \sum_{j\in J} \nu_j \Big)^{p/p^*} = \nu(Y)^{p/p^*} = 1,
    \end{align*}
    having used, in the last inequality, the concavity of the function $t^{p/p^*}$. In particular, all the inequalities must be equalities and, since $t^{p/p^*}$ is strictly concave, we infer that every term in the sum $\int |u|^{p^*}\, \d \mu  + \sum_{j\in J} \nu_j^{p/p^*}$ must vanish except one. By the assumption \eqref{eq:Levyscalings} and $|u|^{p^*}\mm_n \rightharpoonup \nu$ in $C_b(\Z),$ we have $\nu_j\le 1-\eta$ for every $j \in J$. Hence $\nu_j=0$ and $\|u\|_{L^{p^*}(\mu)}=1$.
    % We claim now that $\nu_j\neq 1$ for any $j$; to see this, notice that from \eqref{eq:Levyscalings}, it must be that $y_n \to  y_j (=y) $ (in $\Z$) but, in this case, it is evident that convergence to a Dirac cannot happen as, for every $\eps <\eta, $ denoting the annulus  $O : = B_{2R+1}\setminus B_1(y_n)$, we see that $\int \nchi|u_n|^{2^*}\,\d\mu_n \ge  \int_O |u_n|^{2^*}\,\d\mu_n \ge \eta - \eps >0.$     Finally, we are only left with $1 = \int |u|^{2^*}\,\d \mu$. 
    This means that $u_n$ converges $L^{p^*}$-strong to $u$. Moreover, retracing the equalities in the above we have that $\lim_n \int |\nabla u_n|^p\, \d \mu_n = \int |\nabla u|^p\,\d\mu$. This proves point ii). Finally, equality in the fourth inequality is precisely part iii) of the statement. The proof is now concluded.
\end{proof}

\section{Generalized existence}
In this part, we study generalized existence results for minimizers of the Sobolev inequality. We first handle the general case with nonnegative Ricci lower bounds and then the Alexandrov setting.
%
%
\subsection{Nonnegative Ricci lower bound}
%
\begin{theorem}\label{thm:general RCD}
    Let $(\X_n,\sfd_n,\mm_n)$ be a sequence of ${\sf RCD}(0,N)$-spaces for some $N\in (1,\infty)$ with ${\sf AVR}(\X_n) \in (V,V^{-1})$ for some $V>0$ and let $p \in (1,N)$. Set $p^*=pN/(N-p)$. Then, for every $0\neq u_n\in W^{1,p}_{loc}(\X_n)$ so that
    \[
       {\sf AVR}(\X_n)^{-\frac 1N}S_{N,p} -  \frac{\|u_n\|_{L^{p^*}(\mm_n)}}{\|\nabla u_n\|_{L^p(\mm_n)}}\to 0,\qquad\text{as }n\uparrow\infty,
    \]
    there is a not relabeled subsequence and $z_{n} \in\X_n,\sigma_{n}>0$ so that the following holds:
    \begin{itemize}
        \item[{\rm i)}] there exists a pointed ${\sf RCD}(0,N)$-space $(Y,\rho,\mu,z_0)$ so that, defining $(\X_{\sigma_{n}},\sfd_{\sigma_{n}},\mm_{\sigma_{n}},z_{n}) \coloneqq (\X_{n},\sigma_{n}\sfd_n,\sigma_{n}^N\mm_n,z_n)$, it holds $\X_{\sigma_{n}}  \overset{pmGH}{\to} Y$;
        \item[{\rm ii)}]  there is $0\neq u_\infty \in W^{1,p}_{loc}(Y)$ so that, defining $u_{\sigma_{n}} \coloneqq \frac{\sigma_{n}^{-N/p^*} u_{n}}{\|u_{n}\|_{L^{p^*}(\mm)}}  \in W^{1,p}_{loc}(\X_{\sigma_{n}})$, it holds
        \[
            u_{\sigma_{n}} \to u_\infty \quad \text{in }L^{p^*}\text{-strong},\qquad |\nabla u_{\sigma_{n}}| \to |\nabla u_\infty|\quad \text{in }L^p\text{-strong}.
        \]
        \item[{\rm iii)}] $(Y,\rho,\mu)$ is a metric measure cone with ${\sf AVR}(Y)=\lim_{n\uparrow\infty}{\sf AVR}(\X_n)$ ,  $z_0\in Y$ is a tip and
        \[
           \|u_\infty\|_{L^{p^*}(\mu)} = {\sf AVR}(Y)^{-\frac 1N}S_{N,p} \|\nabla u_\infty\|_{L^p(\mu)}.
        \]
        Moreover $u_\infty$ is a Euclidean bubble centered at $z_0$, i.e.\ there are $a\in\R,b>0$  so that
        \[
        u_\infty =  \frac{a}{(1+b\rho(\cdot,z_0)^{\frac{p}{p-1}})^\frac{N-p}{p}}.
        \]
    \end{itemize}
\end{theorem}
\begin{proof}
   By scaling, we can assume without loss of generality that $\|u_n\|_{L^{p^*}(\mm_n)}=1$ for all $n\in\N$. By approximation, we can further suppose that $u_n \in W^{1,p}(\X_n)$ (see, e.g, \cite[Lemma 3.2]{NobiliViolo24}). We denote $A_n \coloneqq {\sf AVR}(\X_n)^{-\frac 1N}S_{N,p}$ and observe that, by assumptions, $u_n$ satisfies
    \[
    \|u_n\|_{L^{p^*}(\mm_n)} \ge (A_n-1/n)\|\nabla u_n\|_{L^{p}(\mm_n)},\qquad\forall n \in\N.
    \]
    Consider now $\eta \in (0,1)$ given by $\eta= \eta_{N,p}/2$ for $\eta_{N,p}$ as in Theorem \ref{thm:CC extremal}, and take  $y_n \in \X_n$ and $t_n>0$ so that
    \[ 
        1-\eta = \int_{B_{t_n}(y_n)} |u_n|^{2^*}\, \d \mm_n =  \sup_{y \in \X_n} \int_{B_{t_n}(y)} |u_n|^{2^*}\, \d \mm_n ,\qquad \text{for each }n \in \N.
    \]
    Define accordingly $\sigma_n \coloneqq  t_n^{-1}$ and  $(Y_n,\rho_n,\mu_n,y_n) \coloneqq  (\X_n, \sigma_n\sfd_{\sigma_n},\sigma_n^N\mm_n,y_n)$. Clearly $(Y_n,\rho_n,\mu_n)$ is a sequence of ${\sf RCD}(0,N)$-spaces satisfying $\frac{\mu_n( B_R(y))}{\omega_N R^N} =\frac{ \mm_n( B_{ R/\sigma_n}(y))}{\omega_N (R/\sigma_n)^N}$ for all $R>0$ and $n\in\N$. In particular, we deduce 
    \[  
       {\sf AVR}(Y_n)  ={\sf AVR}(\X_n) ,\qquad  A_n \in (V^{\frac 1N}S_{N,p}, V^{-\frac 1N}S_{N,p}),
    \]
    and by scaling
    \[
    1-\eta =  \int_{B_1(y_n)} |u_{\sigma_n}|^{p^*}\, \d \mu_n\qquad \text{and}\qquad  \| u_{\sigma_n}\|_{L^{p^*}(\mu_n)}  \ge (A_n-1/n) \| \nabla u_{\sigma_n}\|_{L^p(\mu_n)}.
    \]
    for  all $n\in\N$. Consider then a not relabeled subsequence so that $A_n\to A$, for some $A>0$ finite so that, in particular, $\exists \lim_{n\uparrow\infty} {\sf AVR}(\X_n)$ along such subsequence. 



    We are in position to invoke Theorem \ref{thm:CC extremal} and get points $y_n \in \X_n$ and scalings $\sigma_n>0$ so that, up to a subsequence, $(Y_n,\rho_n,\mu_n,y_n)$ pmGH-converges to some pointed  ${\sf RCD}(0,N)$ space $(Y,\rho,\mu, z)$ satisfying by stability of Sobolev constants (c.f.\ Lemma \cite[Lemma 4.1]{NobiliViolo21})
    \begin{equation}
    \|u\|_{L^{p^*}(\mu)} \le A \|\nabla u\|_{L^p(\mu)},\qquad \forall u \in W^{1,p}(Y).
    \label{eq:ausixliary}
    \end{equation}
    This shows conclusion i) with taking $z_n=y_n$ and $z_0=z$. 

    Thanks to the sharpness result in \cite[Theorem 4.6]{NobiliViolo21}, we directly deduce ${\sf AVR}(Y)^{-\frac 1N}S_{N,p} \le A$. Again by Theorem \ref{thm:CC extremal}, we know that $u_{\sigma_n}$ convergence $L^{p^*}$-strong to some function $0\neq u_\infty \in W^{1,p}_{loc}(Y)$ with $\|\nabla u_{\sigma_n}\|_{L^p(\mm_{\sigma_n})}\to \|\nabla u_\infty\|_{L^p(\mu)}$ attaining equality in \eqref{eq:ausixliary}. This shows conclusion ii), recalling also the last conclusion of Lemma \ref{lem:pmGHW1ploc}. 

    We finally prove iii) and conclude the proof. We can estimate
    \begin{align*}
         {\sf AVR}(Y)^{-\frac 1N}S_{N,p} \| \nabla u_\infty \|_{L^p(\mu)} &\ge  \|u_\infty \|_{L^{p^*}(\mu)} =\lim_{n\uparrow\infty} \|u_{\sigma_n} \|_{L^{p^*}}(\mu_n) \\
         &\ge  \lim_{n\uparrow\infty} (A_n -1/n)\|\nabla u_{\sigma_n}\|_{L^p(\mu_n)} = A\|\nabla u_\infty\|_{L^p(\mu)},
    \end{align*}
    giving in turn
    \[ 
    {\sf AVR}(Y)^{-\frac 1d}S_{N,p} =A,\qquad \text{hence also}\qquad {\sf AVR}(Y)=\lim_{n\uparrow\infty}{\sf AVR}(\X_n).
    \]
    In particular, $u_\infty$ is a nonzero extremal function for the sharp Sobolev inequality on $Y$. Thanks to the rigidity result \cite[ii) in Theorem 1.6]{NobiliViolo24_PZ} we deduce that $Y$ is a cone and, for some tip  $z_0 \in Y$ and suitable $a \in \R, b>0$, we find $ u_\infty  =  a(1+b\sfd(\cdot,z_0)^{\frac{p}{p-1}})^\frac{p-N}{p}$. Then we can take $z_n \in Y_n$ any sequence such that $z_n\to z_0$ in $\Z$, since i) would be still satisfied replacing $z$ with $z_0$.
\end{proof}
The above applies also when $\X_n \equiv M$ is a fixed Riemannian manifold $(M,g)$ that is not isometric to the Euclidean space (or, more generally, for a fixed ${\sf RCD}(0,N)$-space that is not a cone). In particular, this result can be interpreted as a generalized existence result in the spirit of \cite{Lions84,Lions85} for minimizers of the Sobolev inequality on a fixed space. 
