The next Theorem proves our first main result Theorem \ref{thm:qualitative Sob Manifold}. 
\begin{theorem}\label{thm:qualitative Sob}
For all $\eps>0, V\in(0,1), N>1$ and $p \in (1,N)$, there exists $\delta\coloneqq \delta(\eps,p,N,V)>0$ such that the following holds.
Let  $\Xdm$  be an $\RCD(0,N)$ space with ${\sf AVR}(\X) \in( V,V^{-1})$ and let $0\neq u\in W^{1,p}_{loc}(\X)$ be satisfying
\[
  \frac{\| u\|_{L^{p^*}(\mm)}}{\| \nabla u\|_{L^p(\mm)}} > {\sf AVR}(\X)^{-\frac 1N}S_{N,p}- \delta.
\]
Then, there are $a\in\R,b>0$ and $z_0 \in \X$ so that 
\begin{equation}\label{eq:main stability}
    \frac{\| \nabla(u - u_{a,b,z_0})\|_{L^{p}(\mm)}}{\| \nabla u\|_{L^{p}(\mm)}} \le \eps,
\end{equation}
where $u_{a,b,z_0}\coloneqq a(1+b\sfd(\cdot,z_0)^{\frac{p}{p-1}})^\frac{p-N}{p}$ and $|a|= c_{N,p}\|u\|_{L^{p^*}(\mm)}\avr(\X)^{-1} b^\frac{(p-1)(N-p)}{p^2},$ for some constant $c_{N,p}$ depending only on $N$ and $p$.
\end{theorem}
\begin{proof}
    If not, for any $n\in\N$ there are ${\sf RCD}(0,N)$ spaces $(\X_n,\sfd_n,\mm_n)$ with ${\sf AVR}(\X_n) \in (V,V^{-1})$ and there are $0\neq u_n \in W^{1,p}_{loc}(\X_n)\cap L^{p^*}(\mm_n)$ satisfying
    \begin{equation}
        \| u_n\|_{L^{p^*}(\mm_n)} \ge (A_n-1/n) \| \nabla u_n\|_{L^p(\mm_n)}, \label{eq:AVR sobolev proof}
    \end{equation}
    where $A_n\coloneqq  {\sf AVR}(\X_n)^{-\frac 1N}S_{N,p}$, but, by the contradiction hypothesis, { there is no constant $c_{N,p}$ (depending only on $N$ and $p$)} so that 
    \begin{equation}
        \inf_{a,b,z} \frac{\| \nabla ( u_n  -u_{a,b,z}  )\|_{L^p(\mm_n)}}{\|\nabla u_n\|_{L^p(\mm_n)}} > \eps,\qquad \forall n \in \N,\label{eq:contradiction AVR}
    \end{equation}
    { for all $b>0$ and $|a|= \|u\|_{L^{p^*}(\mm_n)}c_{N,p}^{-1}\avr(\X_n)^{-1} b^\frac{(p-1)(N-p)}{p^2}.$}




    By the generalized existence result in Theorem \ref{thm:general RCD}, we know that there is a not relabeled subsequence, scalings $\sigma_n>0$ and points $z_n \in \X_n$ so that $(\X_{\sigma_n},\sfd_{\sigma_n},\mm_{\sigma_n},z_n)$ pmGH-converges to a pointed metric measure cone $(Y,\rho,\mu,z_0)$, with tip $z_0$, and that $u_{\sigma_n}\coloneqq \sigma_n^{-N/p^*}u_n \in W^{1,p}_{loc}(Y_n)$ converges in $L^{p^*}$-strong to a Euclidean bubble $u_\infty = u_{a,b,z_0} \in W^{1,p}_{loc}(Y)\cap L^{p^*}(\mu)$.   { Up to changing the sign of $u_n$, we can clearly assume that $a>0.$ It  also is easy to see integrating in polar coordinates (c.f.\ \cite[Lemma 4.2]{NobiliViolo21}) that $\|u_{a,b,z_0}\|_{L^{p^*}(\mu)}=c_{N,p}^{-1}\avr(Y) a \cdot b^\frac{(1-p)(N-p)}{p^2},$ for some constant $c_{N,p}$ depending only on $N$ and $p.$ Hence we must have
    \begin{equation}\label{eq:formula ab}
      a =  c_{N,p}\avr(Y)^{-1} b^\frac{(p-1)(N-p)}{p^2}.
    \end{equation}
    } 
    Applying \cite[Lemma 7.2]{NobiliViolo24} twice, we get that $f\circ \rho_n(\cdot,z_n)$ converges $L^{p^*}$-strong to $u_{a,b,z_0}$ and that $ |\nabla(f\circ \rho_n(\cdot,z_n))| $ converges $L^p$-strong to $|\nabla u_{a,b,z_0}|$ where we defined $f(t) = a(1+bt^{\frac{p}{p-1}})^{\frac{p-N}{p}}$.  Recall that $u_{\sigma_n}$ and $|\nabla u_{\sigma_n}|$ also converge respectively in $L^{p^*}$ and $L^p$-strong to $u_{a,b,z_0}$.Therefore, by linearity of convergence (c.f.\  Lemma \ref{prop:linearity W1ploc convergence}, and since $p^*\ge p$ whence $L^p_{loc}$-strong convergence does hold) we get
    \[
        \lim_{n\uparrow\infty} \| \nabla (u_{\sigma_n} - f\circ\sfd_{\sigma_n}(\cdot,z_n))\|_{L^{p}(\mm_{\sigma_n})} =0.
    \]
    By scaling, we thus deduce that the sequence  $v_n \coloneqq   a\sigma_n^{d/p^*} (1+  b\sigma_n^\frac{p}{p-1}\sfd_n(\cdot,z_n)^\frac{p}{p-1})^{\frac{p-N}{p}}$ satisfies
    \[
       \limsup_{n\uparrow\infty} \frac{\| \nabla ( u_n - v_n )\|_{L^p(\mm_n)}}{\|\nabla u_n\|_{L^p(\mm_n)}} =0,
    \] 
    having also used that $\|\nabla u_n\|_{L^p(\mm_n)}\ge S_{N,p}^{-1}\avr(\X_n)^{1/N} \|u_n\|_{L^{p^*}(\X_n)}\ge S_{N,p}^{-1}V^{\frac 1N}.$ {Since $\avr(\X_n)\to \avr(Y)\ge V>0$ by iii) in Theorem \ref{thm:general RCD}, the same is true if we replace $v_n$ with $\tilde v_n\coloneqq \frac{\avr(Y)}{\avr(\X_n)}v_n $.  Since by \eqref{eq:formula ab} we have that $\tilde v_n = u_{a_n,b_n,z_n}$ for $b_n = b\sigma_n^2$, $a_n = c_{N,p}\avr(\X_n)^{-1} b_n^\frac{(p-1)(N-p)}{p^2},$ we find a contradiction with \eqref{eq:contradiction AVR}. The proof is therefore concluded.}
\end{proof}
\begin{remark}\label{rmk:non trivial generalization}
    Theorem \ref{thm:general RCD} and Theorem \ref{thm:qualitative Sob} generalize previous results obtained in \cite{NobiliViolo24} for all $p \in(1,\infty)$. For this generalization, there are two crucial ingredients that, at the time of \cite{NobiliViolo24}, where not available. Indeed, Theorem \ref{thm:general RCD} builds upon a nontrivial adaptations of concentration compactness methods and stability of Sobolev functions along converging ${\sf RCD}$ spaces to general exponent $p$ (c.f.\ Theorem \ref{thm:CC extremal} and Section \ref{sec:Mosco}). Finally, to show iii) in Theorem \ref{thm:general RCD} we relied on a recent characterization of Sobolev minimizers deduced in \cite[Theorem 1.6]{NobiliViolo24_PZ} and working for possibly $p\neq 2$ (differently from \cite[Theorem 5.3]{NobiliViolo24}, see also \cite[Remark 2.9]{Nobili24_overview} for details). This in turn was obtained by carefully revisiting the equality case in the P\'olya-Szeg\H{o} inequality in this setting (c.f.\ \cite[Theorem 1.3]{NobiliViolo24_PZ}). \fr
\end{remark}
