{In the next result we show that, provided the measure of small balls is big enough uniformly, then almost extremal functions must be diffused.  Note that, while on  a Riemannian manifold  with non-negative Ricci curvature and Euclidean volume growth (different from $\rr^n$) \eqref{eq:eps not a cone} is true at every point for some $\rho$, it is not clear if it is true uniformly. We will show in the next section that non-negative sectional curvature is enough. }
\begin{theorem}[Refined stability]\label{thm:refined stability}
    Under the assumptions and notations of Theorem \ref{thm:qualitative Sob} suppose also that \footnote{Inequality \eqref{eq:eps not a cone} is equivalent to  $ \inf_{x\in \X} \frac{\mm(B_\rho(x))}{\omega_N \rho^{N}}\ge \avr(\X)+\delta,$ for some $\rho>0$ and $\delta>0$, by Bishop-Gromov monotonicity.}
    \begin{equation}\label{eq:eps not a cone}
        \inf_{x\in \X} \frac{\mm(B_\rho(x))}{\omega_N \rho^{N}}\ge \avr(\X)+\rho,
    \end{equation}
    holds for some $\rho>0$.
    Then, letting $\delta$ to depend also on $\rho,$ for every $\eps$  the same conclusion of Theorem \ref{thm:qualitative Sob} holds with the additional property that
    \begin{equation}\label{eq:refined stability part 1}
         |u_{a,b,z_0}|\le \|u\|_{L^{p^*}(\mm)}\eps,   \quad \text{(or equivalently $b<\eps$).}
    \end{equation}
\end{theorem}
\begin{proof}
{ The equivalence of the two statements in \eqref{eq:refined stability part 1} (up to decreasing $\delta$) follows immediately from the fact that, by Theorem \ref{thm:qualitative Sob} we can take $|a|= c_{N,p}\|u\|_{L^{p^*}(\mm)}\avr(\X)^{-1} b^\frac{(p-1)(N-p)}{p^2},$ and in particular
$$|u_{a,b,z_0}|\le |u_{a,b,z_0}(z_0)|=a.$$
}
 We now argue by contradiction. Suppose the statement is false. Then there exist  $\eps>0$, $\rho$, a sequence $\delta_n\to 0$,  $\RCD(0,N)$-spaces  $(\X_n,\sfd_n,\mm_n)$  with ${\sf AVR}(\X_n)\ge V$ satisfying \eqref{eq:eps not a cone} and functions $u_n\in W^{1,p}_{loc}(\X_n)$ such that 
  \[
    \frac{\| u_n\|_{L^{p^*}(\mm_n)}}{\| \nabla u_n\|_{L^p(\mm_n)}} - {\sf AVR}(\X_n)^{-\frac 1N}S_{N,p}\to 0.
  \]
  and for every choice of $a,b,z_0$ such that 
  $  \| \nabla (u_n - u_{a,b,z_0})\|_{L^{p}(\mm_n)} \le \eps \| \nabla u\|_{L^{p}(\mm_n)}$ it holds that   $b\ge \eps.$
Arguing as in the proof of Theorem \ref{thm:qualitative Sob} and up to passing to a subsequence, we can find numbers $\sigma_n>0$ and points $z_n\in \X_n$ such that the spaces $(Y_n,\rho_n,\mu_n,z_n)\coloneqq (\X_n,\sigma_n\sfd_n,\sigma_N^{-N}\mm_N,z_n)$ pmGH-converge to a $\RCD(0,N)$ cone $(Y,\rho,\mu,z_0)$, with tip $z_0,$ $\avr(Y)=\lim_n \avr(\X_n)$ and the functions   $v_n \coloneqq   a_n (1+ b_n\sfd_n(\cdot,z_n)^\frac{p}{p-1})^{\frac{p-N}{p}}$
satisfy
\[
       \limsup_{n\uparrow\infty} \frac{\| \nabla ( u_n - v_n )\|_{L^p(\mm_n)}}{\|\nabla u_n\|_{L^p(\mm_n)}} =0,
    \] 
    where $b_n= b\sigma_n^\frac{p}{p-1}$ and $a_n= a\sigma_n^\frac{n-p}{p}$ for some $a>0,$ $b>0$. By assumption we must have $b_n\ge \eps$ and so $\sigma_n\ge c>0$ for some constant $c>0$ independent of $n.$ Hence by Bishop-Gromov monotonicity
    \begin{align*}
         \lim_{n\uparrow\infty} \avr(\X_n)&=\avr(Y)=\frac{\mu(B_{c\rho}(z))}{\omega_N(c\rho)^N}=\lim_{n\uparrow\infty}\frac{\mu_n(B^{Y_n}_{c\rho}(z_n))}{\omega_N(c\rho)^N}\\
         &=\lim_{n\uparrow\infty} \frac{\mm_n(B_{c\rho/\sigma_n}(z_n))}{\omega_N(c\rho/\sigma_n)^N}\ge \lim_{n\uparrow\infty} \frac{\mm_n(B_{\rho}(z_n))}{\omega_N\rho^N}\ge \lim_{n\uparrow\infty}\avr(\X_n)+\rho,
    \end{align*}
    which is a contradiction.
\end{proof}

\begin{remark}
    Condition \eqref{eq:eps not a cone} is sharp in the following sense. If there exists a sequences $x_i \in \X$ and $r_i\to 0^+$ such that 
    \begin{equation}\label{eq:almost conical small balls}
         \frac{\mm(B_{r_i}(x_i))}{\omega_N {r_i}^{N}}\le \avr(\X)+r_i,
    \end{equation}
    then for any $b>0$ the functions $u_i= (1+b\sfd(\cdot,x_i)^{\frac{p}{p-1}})^\frac{p-N}{p}$  are extremizing for the Sobolev inequality in $\X$. Indeed  a suitable subsequence  of $(\X,\sfd,\mm,x_i)$ would pmGH-converge to a limit space $(\X_\infty,\sfd_\infty,\mm_\infty,x_\infty)$. Moreover \eqref{eq:almost conical small balls} implies that $\X_\infty$ must be a cone with  $\avr(\X_\infty)=\avr(\X)$. Then any function $u= (1+b\sfd(\cdot,x_\infty)^{\frac{p}{p-1}})^\frac{p-N}{p}$ is extremizer for the Sobolev inequality in $\X_\infty.$ (c.f.\ \cite[ii) in Theorem 1.7]{NobiliViolo24_PZ}). From this the fact that $u_i$ is extremizing follows from \cite[Lemma 7.2]{NobiliViolo24}. \fr
\end{remark}
