\subsection{Nonnegative sectional lower bound}
In this part we explore refined stability results in Alexandrov spaces. Roughly, the following asserts that on a fixed ${\sf CBB}(0)$ space with Euclidean volume growth and which is not a cone, extremizing sequences for the Sobolev inequality have a diffused asymptotic behavior up to the isometries of the space. As a corollary, we also prove our main result Thereom \ref{thm: stability Sect manifold} on manifolds with nonnegative sectional curvature lower bounds.
\begin{theorem}\label{thm:stability CBB}
    Under the same assumptions and notations of Theorem \ref{thm:qualitative Sob}, suppose also that $(\X,\sfd)$ is an $N$-dimensional ${\sf CBB}(0)$ space with $N\in\N$ and that $(\X,\sfd,\HH^N)$ is not a metric measure cone. 
    % Then, letting $\delta$ to depend also on $\X,$ for every $\eps$ the same conclusion of Theorem \ref{thm:qualitative Sob} holds with the additional property that
    % \begin{equation}
    %     b<\eps.\label{eq:vanishing CBB}
    % \end{equation}
      Write also $\X=\rr^k\times Y$ for some $0\le k<N$ with $Y$ that does not split off any line and fix $y_0 \in Y$.   Then,  the same conclusion of Theorem \ref{thm:qualitative Sob} holds (letting $\delta$ depend also on $y_0$)   with the additional properties that
    \begin{equation}
        z_0\in \rr^k\times\{y_0\} \qquad\text{and}\qquad  b<\eps, \label{eq:up to isometries}
    \end{equation}
    (and in particular $  |u_{a,b,z_0}|\le \|u\|_{L^{p^*}(\mm)}\eps$).
\end{theorem}
\begin{proof}
   We start by showing that \eqref{eq:eps not a cone} holds for some $\rho(\X)>0.$ Suppose the contrary, i.e.\ that there exist a sequence of points $x_i\in \X$ and a sequence of radii $r_i\to 0$ such that
    \begin{equation}
         \frac{\mm(B_{r_i}(x_i))}{\omega_N {r_i}^{N}}\le \avr(\X)+r_i.
    \end{equation}
   We claim that $x_i$ must be a diverging sequence. If this is not the case, up to passing to a subsequence, it converges to some $\bar x\in \X.$  For any $r>0$, Bishop-Gromov monotonicity implies
    \[
     \frac{\mm(B_{r}(\bar x))}{\omega_N {r}^{N}}=\lim_{i\uparrow \infty} \frac{\mm(B_{r}(x_i))}{\omega_N {r}^{N}}\le \liminf_{i\uparrow \infty} \frac{\mm(B_{r_i}(x_i))}{\omega_N {r_i}^{N}}\le\avr(\X).
    \]
    Hence $ \lim_{r\to 0^+}\frac{\mm(B_{r}(\bar x))}{\omega_N {r}^{N}}\le\avr(\X)$, which implies that $\X$ is a cone with tip $\bar x$, which is a contradiction.  Thus $x_i$ is a diverging sequence.
    Up to passing to a subsequence we have that  $(\X,\sfd,\HH^N,x_i)$ pmGH-converges to a limit space $(\X_\infty,\sfd_\infty,\mm_\infty,x_\infty)$.
    By combining \cite[Lemma 4.2]{AntonelliBrueFogagnoloPozzetta22} with Theorem \ref{thm:asymptotic cone CBB}, we must have that $\avr(\X_\infty)\ge \avr(\X)+\delta$ for some $\delta>0.$ Hence  $ \frac{\mm_\infty(B_{1}(x_\infty))}{\omega_N }\ge \avr(\X)+\delta,$ however by pmGH-convergence 
    \[
    \frac{\mm_\infty(B_{1}(x_\infty))}{\omega_N }\le \liminf_{i\uparrow \infty}  \frac{\mm(B_{1}(x_i))}{\omega_N }\le \liminf_{i\uparrow \infty} \frac{\mm(B_{r_i}(x_i))}{\omega_N {r_i}^{N}}\le\avr(\X),
    \]
    which is again a contradiction. We have thus shown that \eqref{eq:eps not a cone} holds.


  We now pass to the proof of the statement  by contradiction. Fix $y_0\in Y.$ Suppose that there exist $\eps>0$, a sequence $\delta_n\to 0$ and functions $u_n\in W^{1,p}_{loc}(\X)$ such that 
  \begin{equation}
        \frac{\| u_n\|_{L^{p^*}(\HH^N)}}{\| \nabla u_n\|_{L^p(\HH^N)}} - {\sf AVR}(\X)^{-\frac 1N}S_{N,p}\to 0,
  \end{equation}
  and for every choice of $a,b,z$ such that 
  $ \| \nabla (u_n - u_{a,b,z})\|_{L^{p}(\HH^N)} \le \eps\| \nabla u\|_{L^{p}(\HH^N)}$,
  either
  \begin{equation}\label{eq:contradiction in CBB}
        b\left(1+ {\rm dist}\big(\rr^k\times \{y_0\},z\big)^\frac{p}{p-1}\right)\ge \eps,
  \end{equation}
  or 
  \begin{equation}\label{eq:contradiction in CBB 2}
      z\notin \rr^k\times \{y_0\}
  \end{equation}
  hold.
  By the same argument in the proof of Theorem \ref{thm:qualitative Sob}  by taking $\X_n=\X$ (which we can repeat because we showed that assumptions \eqref{eq:eps not a cone} is true for some $\rho>0$)  we can find a sequence $\sigma_n\to 0^+$ and points $z_n\in \X$ such that the spaces $(Y_n,\rho_n,\mu_n,z_n)\coloneqq (\X_n,\sigma_n\sfd,\sigma_n^N\HH^N,z_n)$, where $\HH^N$ is the Hausdorff measure with respect to $\sfd,$ pmGH-converge to a $\RCD(0,N)$ cone $(Y,\rho,\mu,z_0)$ with tip $z_0 \in Y$ and $\avr(Y)= \avr(\X)$. Moreover the functions   $v_n \coloneqq   a_n (1+ b_n\sfd(\cdot,z_n)^\frac{p}{p-1})^{\frac{p-N}{p}}$
satisfy
\begin{equation}\label{eq:ananas}
       \limsup_{n\uparrow\infty} \frac{\| \nabla ( u_n - v_n )\|_{L^p(\HH^N)}}{\|\nabla u_n\|_{L^p(\HH^N)}} =0,
\end{equation}
    where $a_n = a \sigma_n^{d/p^*}$ and $b_n= b\sigma_n^\frac{p}{p-1}$ for some $a\in\R,b>0$. Suppose that \eqref{eq:contradiction in CBB} holds for infinitely many $n$ and so for all of them, up to pass to a subsequence. Since $\sigma_n\to 0$ we must have (up to a further subsequence)
    \[
    \sigma_n{\rm dist}\big(\rr^k\times \{y_0\},z_n\big)\ge (\eps/(2b))^\frac{p-1}{p}\eqqcolon\delta>0.
    \]
%   and using the same notations. In particular  $(Y_n,\rho_n,\mu_n,y_n)\coloneqq (X,\sigma_n\sfd_n,\HH^N,y_n)$, where $\HH^N$ is the Hausdorff measure with respect to $\sigma_n\sfd_n,$ is pmGH-converging to some metric cone $(Y,\rho,\mu,z)$ with $\avr(Y)=\avr(\X)$. We can conclude in the same way that $\sigma_n\to 0.$ Fix $y_0 \in \X.$ We need to show that
%     \[
%     b_n\left(1+{\rm dist}\big(\rr^k\times \{y_0\},z_n\big)\right)\le \eps.
%     \]
%     Suppose 
% Since $b_n=\sigma_n b$ for some $b$ and $\sigma_n\to 0$ it is sufficient to show that $\sigma_n\sfd\big(\rr^k\times \{y_0\},z_n\big)\to 0.$ Suppose not, i.e.\
%     \[
%     \sigma_n{\rm dist}\big(\rr^k\times \{y_0\},z_n\big)\ge c>0.
%     \]
Up to isometries we can assume that $z_n=(0,x_n)$ for some $x_n\in Y$ and so $ \sigma_n\sfd(z_n,(0,y_0))\ge \eps$.
In particular, since $\sigma_n\to 0$, we have $r_n\coloneqq \sfd(z_n,(0,y_0))\to +\infty.$ Up to passing to a subsequence   $ (\X,r_n^{-1}\sfd,\HH^N/r_n^N,(0,y_0))$  converge to an asymptotic cone  $(\X_\infty,\sfd_\infty,\mm_\infty,y_\infty)$, where $\HH^N$ is with respect to $\sfd$. Combining \cite[ii) in Lemma 4.2]{AntonelliBrueFogagnoloPozzetta22} with Theorem \ref{thm:asymptotic cone CBB}, we have that  for all $z\in \X_\infty$ with $\sfd_\infty(z,y_\infty)=1$ it holds
\[
\lim_{r\to 0^+} \frac{\mm_\infty(B_r(z))}{r^N\omega_N}\ge  \avr(\X)+\delta
\]
for some $\delta>0$. By scaling, we note that $z_n\to z_\infty$ for some $z_\infty \in \X_\infty$ with $\sfd_\infty(z_\infty,y_\infty)=1$. Additionally by measure convergence
\begin{align*}
    \frac{\mm_\infty(B_r(z_\infty))}{r^N\omega_N}&\le \liminf_{n\uparrow\infty} \frac{\HH^N(B_{r r_n}(z_n))}{(r r_n)^N\omega_N}
=\liminf_{n\uparrow\infty} \frac{\HH^N(B_{r \sigma_nr_n/\sigma_n}(z_n))}{(r r_n\sigma_n/\sigma_n)^N\omega_N}\le \liminf_{n\uparrow\infty} \frac{\HH^N(B_{r \delta/\sigma_n}(z_n))}{(r \delta/\sigma_n)^N\omega_N}\\
&=\liminf_{n\uparrow\infty} \frac{\sigma_n^N\HH^N(B_{r \delta/\sigma_n}(z_n))}{(r \delta)^N\omega_N}=\frac{\mu(B^Y_{r\delta}(z_0))}{(r\eps)^N\omega_N},
\end{align*}
for all $r>0$.  Sending  $r\to 0$ we deduce that $\avr(\X)+\delta\le \avr(\X)$ which is a contradiction. Note that in fact we showed that $ \sigma_n{\rm dist}\big(\rr^k\times \{y_0\},z_n\big)\to 0.$ 

All in all, for $u_n$ we have showed that \eqref{eq:contradiction in CBB 2} must hold with the choice $a_n,b_n,z_n$ for infinitely many $n.$ However, since  $ \sigma_n{\rm dist}\big(\rr^k\times \{y_0\},z_n\big)\to 0$, the spaces $(\X_n,\sigma_n\sfd,\sigma_n^N\HH^N,(0,y_0))$, still pmGH-converge to the same cone $(Y,\rho,\mu,z_0)$ with the same tip $z_0$. Therefore we deduce that the functions  $v_n \coloneqq   a_n (1+ b_n\sfd(\cdot,(0,y_0))^\frac{p}{p-1})^{\frac{p-N}{p}}$  still verify \eqref{eq:ananas} (as we did in the very end of the proof of Theorem \ref{thm:general RCD}). In particular, the choice $a_n,b_n,(0,y_0)$  is then admissible, and does not satisfy neither \eqref{eq:contradiction in CBB} nor \eqref{eq:contradiction in CBB 2}. This gives a contradiction and concludes the proof.
\end{proof}
