     \centering
     \includegraphics[width=\textwidth]{Figures/schematic_mm_method.pdf}
     \caption{Illustration of the mesh morphing method. (a) The reference geometry, in black, as well as points $\boldsymbol X_{\boldsymbol q_\text{ref}}$ which lie on $\Gamma_0$, in green, and those which lie on $\Gamma_a$, in blue. (b) The new geometry, in black, as well as points $\boldsymbol X_{\boldsymbol q_\text{new}}$ which lie on $\Gamma_0$, in green, and those which lie on $\Gamma_a$, in blue. (c) the reference mesh in gray, with vertices $\boldsymbol X_M$, and the displacement applied to each vertex, $\boldsymbol D_M$. (d) The morphed mesh, $\Hat{\boldsymbol X}_M$. }
     \label{fig:schematic_mm_method}
\end{figure}

RBF interpolation is a type of scattered data interpolant which can be applied to data of any dimension, and is constructed in terms of the Euclidean distance between input scattered data \cite{fasshauer_2007}. Given a function $f(\boldsymbol x)$, the RBF interpolant is a linear combination of kernel functions, $\Theta_j(\boldsymbol x) = \Theta \left( \| \boldsymbol x - \boldsymbol x_j \|_2  \right)$, which are centered at scattered data points $\boldsymbol x_j$ and weighted by $w_j$:
\begin{linenomath*}
\begin{equation} 
f(\boldsymbol x) \approx f_{RBF}\left(\boldsymbol x \right) = \sum_{j=1}^{m} w_j \Theta_j (\| \boldsymbol x - \boldsymbol x_j \|_2). 
\label{eq:RBF}
\end{equation}
\end{linenomath*}
In the mesh morphing steps in this study we use the linear kernel, $\Theta_j(\boldsymbol x) = - \| \boldsymbol x - \boldsymbol x_j \|_2$. 
To ensure that the RBF interpolant is unique,
the interpolant is augmented with a complete polynomial basis \cite{fasshauer_2007}.

As described here, it is possible to morph the mesh to be representative of a geometry with a given geometric parameter value, while keeping certain boundaries fixed in their original locations.
However, it is often important that the morphed mesh satisfy certain additional requirements, as suited to the geophysical application. 
For example, the user may require that the mesh volume be preserved, or that certain lines remain straight or planes remain planar after morphing. 
We use Algorithm~\ref{alg:successive_disp} to apply additional morphing steps to ensure that the morphed mesh respects specific constraints. 
To use Algorithm~\ref{alg:successive_disp}, points on boundaries of the previously morphed mesh are considered $\boldsymbol X_{\boldsymbol q_\text{ref}}$, while target points are defined by the user as $\boldsymbol X_{\boldsymbol q_\text{new}}$.
Then an interpolant is constructed using $\boldsymbol X_{\boldsymbol q_\text{ref}}$ and the displacement between $\boldsymbol X_{\boldsymbol q_\text{ref}}$ and $\boldsymbol X_{\boldsymbol q_\text{new}}$. 
The interpolant is evaluated at each mesh vertex to obtain a further morphed mesh that respects the specified constraint. 

\begin{algorithm}
\caption{Building the mesh morphing RBF interpolant.}\label{alg:mmm}
\begin{algorithmic}
\Require $\boldsymbol q_\text{ref}$, $\boldsymbol q_\text{new}$, $\Gamma_a$, $\Gamma_0$, $\Gamma_k$, $\boldsymbol X_M$.
\State Define $N$ points $\boldsymbol X_{\boldsymbol q_\text{ref}} \in \Gamma(\boldsymbol q_\text{ref})$, where $\Gamma = \Gamma_a \cup \Gamma_0 \cup \Gamma_k$. 
\State $\boldsymbol D = \emptyset$. \Comment{$\boldsymbol D$ is the displacement field array.}
\For{$i = 1, \ldots, m$}: \Comment{$m$ is the number of vectors in $\boldsymbol q_\text{new}$}
	\State $\boldsymbol q_i = \boldsymbol q_\text{new}^i$.  \Comment{Select the $i^\text{th}$ column of $\boldsymbol q_\text{new}$.}
	\State Define $N$ points $\boldsymbol X_{\boldsymbol q_\text{new}} \in \Gamma(\boldsymbol q_i)$. 
	\State $\boldsymbol D_i = \text{ComputeDisplacement}\left(  \boldsymbol X_{\boldsymbol q_\text{ref}}, \boldsymbol X_{\boldsymbol q_\text{new}}, \Gamma_a, \Gamma_0, \Gamma_k  \right) $.  
	\State $\boldsymbol D \leftarrow \boldsymbol D \cup \boldsymbol D_i $. \Comment{Augment $\boldsymbol D$ with the displacement corresponding to $\boldsymbol q_i$.}
\EndFor
\State $F_\text{RBF} =  F_\text{RBF} \left( \boldsymbol q_\text{new}, \boldsymbol D \right)$.  \Comment{Define the RBF interpolant as in Equation~\eqref{eq:RBF}.}
\State \Return $F_\text{RBF}$, $\boldsymbol X_{\boldsymbol q_\text{ref}}$.
\end{algorithmic}
\end{algorithm}

\begin{algorithm}
\caption{Morphing the mesh to represent a configuration defined by $\boldsymbol q_j$.}\label{alg:mm_eval}
\begin{algorithmic}
\Require  $\boldsymbol q_j$, $F_\text{RBF}$, $\boldsymbol X_{\boldsymbol q_\text{ref}}$, $\boldsymbol X_M$.
\State  $\boldsymbol D_j = F_\text{RBF} \left( \boldsymbol q_j \right)$. 
\State $G_\text{RBF} =  G_\text{RBF} \left( \boldsymbol X_{\boldsymbol q_\text{ref}}, \boldsymbol D_j \right) $.
\State $\boldsymbol D_M = G_\text{RBF} \left( \boldsymbol X_M \right)$.
\State $\Hat{\boldsymbol X}_M = \boldsymbol X_M + \boldsymbol D_M$.
\State \texttt{valid} $\gets$ CheckValidMesh($\Hat{\boldsymbol X}_M$).  
\If{\texttt{valid} = \texttt{True}}: 
	\State \Return $\Hat{\boldsymbol X}_M$.
\Else: 
	\State Raise error. 
\EndIf
\end{algorithmic}
\end{algorithm}

\begin{algorithm}
\caption{ComputeDisplacement. A function that calculates the displacement $\boldsymbol D$ between $\boldsymbol X_{\boldsymbol q_\text{ref}}$ and $\boldsymbol X_{\boldsymbol q_\text{new}}$ based on whether they lie on $\Gamma_a, \ \Gamma_0$, or $\Gamma_k$. }\label{alg:compute_D}
\begin{algorithmic}
\Require $\boldsymbol X_{\boldsymbol q_\text{ref}}$ , $\boldsymbol X_{\boldsymbol q_\text{new}}$, $\Gamma_a$, $\Gamma_0$, $\Gamma_k$.
\State $\boldsymbol D = \emptyset$
\For{$i = 1, \ldots, N$}:
\State $\boldsymbol x_\text{r} = \boldsymbol X_{\boldsymbol q_\text{ref}, i}$ \Comment{Extract $i^{\text{th}}$ point in $\boldsymbol X_{\boldsymbol q_\text{ref}}$}
\State $\boldsymbol x_\text{t} = \boldsymbol X_{\boldsymbol q_\text{new}, i}$ \Comment{Extract $i^{\text{th}}$ point in $\boldsymbol X_{\boldsymbol q_\text{new}}$}
\State $\boldsymbol d = \boldsymbol x_\text{t} - \boldsymbol x_\text{r}$ \Comment{Compute displacement between $i^{\text{th}}$ points in $\boldsymbol X_{\boldsymbol q_\text{ref}}, \boldsymbol X_{\boldsymbol q_\text{new}}$}.
% \boldsymbol X_{\boldsymbol q_\text{ref}, \boldsymbol X_{\boldsymbol q_\text{new}, i}
\If{$\boldsymbol x_\text{r},  \boldsymbol x_\text{t} \in \Gamma_a$}:
\State $\boldsymbol D \gets \boldsymbol D \cup  \boldsymbol d$

\ElsIf{$\boldsymbol x_\text{r},  \boldsymbol x_\text{t} \in \Gamma_0$}:
\State $\boldsymbol D \gets \boldsymbol D \cup  \boldsymbol 0$

\ElsIf{$\boldsymbol x_\text{r},  \boldsymbol x_\text{t} \in \Gamma_k$}:
\State $\boldsymbol d_\text{uni} = \left[0, 0, 0 \right]$
\State $\boldsymbol d_{\text{uni},k} = \boldsymbol d_k$ \Comment{Replace $k^\text{th}$ element of $\boldsymbol d_\text{uni}$ with $k^\text{th}$ element of $\boldsymbol d$.}
\State $\boldsymbol D \gets \boldsymbol D \cup  \boldsymbol d_\text{uni}$
\Else:
\State Raise error. 
\EndIf

\EndFor
\State \Return $\boldsymbol D$.
\end{algorithmic}
\end{algorithm}

\begin{algorithm}
\caption{Applying an additional morph so that a constraint is respected.}\label{alg:successive_disp}
\begin{algorithmic}
\Require $\boldsymbol X_{\boldsymbol q_\text{ref}}$ , $\boldsymbol X_{\boldsymbol q_\text{new}}$, $\Gamma_a$, $\Gamma_0$, $\Gamma_k$, $\boldsymbol X_M$.
\State $\boldsymbol D \coloneqq  \text{ComputeDisplacement}\left(  \boldsymbol X_{\boldsymbol q_\text{ref}}, \boldsymbol X_{\boldsymbol q_\text{new}}, \Gamma_a, \Gamma_0, \Gamma_k \right) $.
\State $H_\text{RBF} = H_\text{RBF}( \boldsymbol X_{\boldsymbol q_\text{ref}}, \boldsymbol D)$. 
\State $\boldsymbol D_M = H_\text{RBF} \left( \boldsymbol X_M \right)$.
\State $\Hat{\boldsymbol X}_M = \boldsymbol X_M + \boldsymbol D_M$.
\If{\texttt{valid} = \texttt{True}}: 
	\State \Return $\Hat{\boldsymbol X}_M$.
\Else: 
	\State Raise error. 
\EndIf
\end{algorithmic}
\end{algorithm}

\subsection{Evaluating Mesh Quality} \label{sec:mesh_qual_defs}

In this study we focus on unstructured triangular (2D) and tetrahedral (3D) meshes, and we require that meshes are valid and of acceptable quality. 
A valid mesh is defined as a mesh with no ``inverted'' cells; an inverted cell has (i) edges that have crossed each other, resulting in a self-intersecting geometry, and or (ii) has an cell edge with zero length.
For a mesh to be valid, each cell must be such that the coordinate transformation from physical (global) coordinates to ``local'' (cell-based) coordinates must be invertible everywhere in the cell. 
Given a valid mesh, we measure the mesh quality using several metrics. 
The aspect ratio (AR) of a cell is defined as the ratio of the largest edge length to the inner-sphere radius of the cell; it has an ideal value of 1, and the higher the AR value, the more elongated and lower quality the cell. 
The minimum angle (MA) metric is the minimum angle between edges (for triangular cells) or faces (for tetrahedral cells); it has an ideal value of $60^{\circ}$, and lower values indicate lower quality cells. 
Finally, the scaled Jacobian (SJ) metric is the ratio of the Jacobian to the maximum of the products of edge lengths adjacent to each vertex; it has an ideal value of 1, with lower values indicating lower cell quality. 

\section{Dynamic Rupture Simulation Application: Varying Dip of a Planar Normal Fault} \label{sec:dr_examples}

In this section we demonstrate the application of the mesh morphing approach to 3D dynamic rupture simulations performed using SeisSol, a freely available open-source software for simulating dynamic rupture and seismic wave propagation \cite{seissol}. 
SeisSol enables realistic simulation of seismic wave propagation generated by a dynamic rupture earthquake source, which is governed by a frictional constitutive law on geometrically complex faults \cite<e.g.,>{ramos_et_al_2022}. 
SeisSol is based on the Arbitrary high-order accurate DERivative Discontinuous Galerkin method (ADER-DG), has been verified against a range of community benchmarks \cite{kaser_dumbser_2006, pelties_gabriel_ampuero_2014} and is optimized for HPC infrastructure \cite<e.g.,>{heinecke_et_al_2014,uphoff_et_al_2017}. We use polynomial basis functions of degree 3, ensuring $\mathcal{O}4$ accuracy of the seismic wavefield in space and time. 


We present mesh morphing results for the SCEC/USGS TPV 13-3D benchmark exercise \cite{harris_et_al_2018}; we will later extend this example to include reduced-order modeling results in Section~\ref{sec:ROM}.
TPV13 describes spontaneous earthquake rupture on a 2D planar normal fault at 60$^\circ$ dip, with initial stress conditions that lead to supershear rupture, and governed by linear slip-weakening friction \cite{ida_1972,palmer_et_al_1973,andrews_1976}. The model includes off-fault plasticity governed by a non-associative Drucker-Prager visco-plastic rheology \cite{andrews_2005,wollherr_et_al_2018}. 
The TPV13 geometry is shown in Figure~\ref{fig:combined_DR_schematics}(a) and we report the parameters we used in Table~S3. 
We define $\mathcal{S}_A$ to be the union of all outer surfaces of the geometry, while the surface defining the embedded fault plane is $\mathcal{S}_F$, and the nucleation patch is $\mathcal{S}_G$, where $\mathcal{S}_G \subset \mathcal{S}_F$. 
The fault plane has a dip $\theta$, which is our geometric parameter, thus $\boldsymbol q = ( \theta )$. 
Fault planes for selected values of $\theta$ is shown in Figure~\ref{fig:combined_DR_schematics}(b).
Our aim is to morph the entire 3D mesh such that the embedded planar fault has different dip angles. 
We select $\boldsymbol q_\text{ref} = 60^\circ$, and $\boldsymbol Q = [40^\circ, 80^\circ]$. 
Let $\Gamma_a = \{ \mathcal{S}_F \}$, while $\Gamma_0 = \{ \mathcal{S}_A \} $ and $\Gamma_k = \{ \emptyset \}$. 
Since the union of all outer surfaces of the geometry, $\mathcal{S}_A$, is prescribed to have zero displacement, the volume of the domain will be preserved in this example. 

All our SeisSol simulations are performed on unstructured tetrahedral meshes, which employ adaptive coarsening away from the fault. 
We use the open-source software GMSH to generate a reference mesh $M$ with vertices $\boldsymbol X_M$, locally refined to have a mesh size of 100~m in the nucleation patch, 250~m on the fault, and 2.5~km far from the fault \cite{gmsh}. 
Finally, we select 18 $\boldsymbol q_\text{new}$ values, uniformly sampled in $\boldsymbol Q$. 
With these components defined and passed to Algorithm~\ref{alg:mmm}, we call Algorithm~\ref{alg:mm_eval} to obtain morphed meshes with varying fault dips and outer boundaries that have not been displaced. 
Figure~\ref{fig:crinkle_reference} shows the reference mesh (a-b), and a morphed mesh with $\theta = 40^\circ$ (c-d). 

The morphing process can result in the embedded fault becoming non-planar, and even slight non-planarity of the fault (in particular, at the nucleation patch) affects the dynamic rupture. 
We use Algorithm~\ref{alg:successive_disp} to apply an additional constraint after morphing the mesh to ensure that the morphed fault is nearly exactly planar. 
Algorithm~\ref{alg:successive_disp} is called, with $\boldsymbol X_{q_\text{ref}}$ defined as the points in $\Hat{\boldsymbol X}_M$ that lie in $\mathcal{S}_F$. 
A plane is defined that goes through each corner of the fault, and each point on the fault is projected onto that plane, giving the points $\boldsymbol X_{q_\text{new}}$. 
As before, $\Gamma_a = \{ \mathcal{S}_F \}$, while $\Gamma_0 = \{ \mathcal{S}_A \} $ and $\Gamma_k  = \{ \emptyset \}$. 
Applying this correction results in morphed meshes with faults that have points within 1 m of a plane fitted through them. 
It also results in dynamic rupture output that more closely matches output from simulations run on an exactly meshed fault at a given dip. 

Another consequence of the morphing is that the area of the nucleation patch does not exactly match that of an exactly generated mesh, which can affect rupture dynamics \cite<e.g.,>{galis_et_al_2014}.
Each exactly generated mesh will have a nucleation patch with an area of 9 km$^2$, while the morphed meshes can have slightly larger nucleation patches, by up to 0.03 km$^2$.
Given the close match of rupture dynamics with exact meshes (Sec. \ref{sec:DR_mesh_qual_accuracy}), we consider this an acceptable amount of variation, but this effect should be kept in mind for future studies, and handled with additional corrections if required.  

The initial stress is prescribed as a Cartesian stress tensor, hence the initial stress resolved on the fault does change as the dip changes.
As a result, we find that this inhibits rupture at dip angles beyond $3^{\circ}-5^{\circ}$ of the reference dip angle of $60^{\circ}$. 
If all parameters are kept the same as the benchmark description, we find that earthquake rupture only nucleates on faults with $\theta \in [55^\circ, 63^\circ]$. 
To examine dynamic rupture output in a wider $\theta$ interval, we decrease the static friction coefficient inside the nucleation patch from the benchmark value of 0.54 to 0.48. 
This results in earthquake rupture nucleating on faults with $\theta \in [50^\circ, 70^\circ]$, illustrating the trade-offs of fault geometry, prestress, fault strength and nucleation size. 

