\section{Proof of Proposition \ref{main1}}

We start with a lemma from linear algebra. We denote by ${\bf 1}_n$ the $n$-by-$n$ identity matrix.

\begin{Lem}\label{linalg} Let $X\in M_2(\C)$. \begin{enumerate}
\item The matrix $X$ is nilpotent (i.e. $X^n=0$ for some $n\geq 2$) if and only if $X^2=0$, if and only if $\tr(X)=\det(X)=0$.
\item The matrix $X$ is a rank 1 idempotent if and only if $\tr(X)=1$ and $\det(X)=\nolinebreak 0$.
\item If $X$ is nilpotent, then $X^*X+XX^*=\tr(X^*X){\bf 1}_2.$
\end{enumerate}\end{Lem}

\bpr \begin{enumerate}
\item By Cayley-Hamilton, the characteristic polynomial of $X$, namely \linebreak $t^2-\tr(X)t+\det(X)$, vanishes on $X$. To prove the statement, clearly we may assume $X\neq 0$: so the polynomial $t^n$ also vanishes on $X$, which happens if and only if the polynomial $t^2$ vanishes on $X$, if and only if $\tr(X)=\det(X)=0$. 
\item The proof is very similar to the one of 1.
\item This can be proved by direct computation, let us give a more conceptual proof. We may assume $X\neq 0$. Then $X^*X$ is a positive multiple of the projection $P$ on $Im(X)=\ker(X)$, while $XX^*$ is a positive multiple of the projection $Q$ on $Im(X^*)=(\ker(X))^\perp$. Taking traces, we see that those multiples coincide and are equal to $\tr(X^*X)=\tr(XX^*)$. Finally $P+Q={\bf 1}_2$.\epr
\end{enumerate}


To prove Proposition \ref{main1}, we look for Rieffel projections in $M_2(C(Y\times S^1))$ of the form (\ref{Rieffel}), which corresponds to a pair of matrices $X_0,X_1\in M_2(C(Y))$ with $X_0=X_0^*$ and
\begin{equation}\label{Rieffel1}
X_1^2=0;
\end{equation}
\begin{equation}\label{Rieffel2}
X_1=X_0X_1+X_1X_0;
\end{equation}
\begin{equation}\label{Rieffel3}
X_0=X_0^2 + X_1^*X_1+X_1X_1^*=X_0^2+\tr(X_1^*X_1){\bf 1}_2
\end{equation}
(where the last equality follows from lemma \ref{linalg}).
Moreover we want this Rieffel projection to be non-trivial (i.e. $X_1\neq 0$) and of rank 1, so that $\tr(X_0(y))=1$ for every $y\in Y$. Assuming that such a pair $X_0,X_1$ exists, we may write 
$$X_0=\left(\begin{array}{cc}a & b \\ \overline{b} & 1-a\end{array}\right);\;\;\;X_1=\left(\begin{array}{cc}\alpha & \beta \\\gamma & -\alpha\end{array}\right)$$
with $a,b,\alpha,\beta,\gamma\in C(Y)$ and $a$ real-valued. By direct computation, one checks that the condition (\ref{Rieffel1}) translates into 
\begin{equation}\label{nonlincond}
\beta\gamma=-\alpha^2
\end{equation}(see lemma \ref{linalg}); the condition (\ref{Rieffel2}) translates into 
\begin{equation}\label{linearcond}
(2a-1)\alpha+b\gamma+\overline{b}\beta=0;
\end{equation} and the condition (\ref{Rieffel3}) translates into 
\begin{equation}
a=a^2+|b|^2+2|\alpha|^2+|\beta|^2+|\gamma|^2.
\end{equation} This concludes the proof of Proposition \ref{main1}.
\epr

\section{Proof of Theorem \ref{main2}}

We denote by $Proj_1(M_n(\C))$ the space of rank 1 projections in $M_n(\C)$ (it is canonically homeomorphic to the $(n-1)$-dimensional complex projective space $P^{n-1}(\C)$).

\begin{Lem}\label{homotopy} Let $U$ be an open subset in the compact space $Y$, and let $f:Y\rightarrow\R$ be a function which is continuous on $U$, and 0 elsewhere.
\begin{enumerate}
\item The following are equivalent:
\begin{enumerate}
\item The function $\exp(2\pi if)$ is continuous on $Y$;
\item For any function $P:Y\rightarrow Proj_1(M_n(\C))$ which is continuous on $U$ and zero elsewhere, the map $\exp(2\pi i fP)$ is continuous from $Y$ to $U_n(\C)$.
\end{enumerate}
\item If $f,P$ are as above (with $\exp(2\pi if)$ continuous on $Y$), the K-theory class of $\exp(2\pi i fP)$ in $K_1(C(Y))$ only depends on the homotopy class of $P|_U$ as a map $U\rightarrow Proj_1(M_n(\C))$.
\item If moreover $U$ is contractible, then $[\exp(2\pi i fP)]=[\exp(2\pi i f)]$ in $K_1(C(Y))$.
\end{enumerate}
\end{Lem}

\bpr \begin{enumerate}
\item For $(b)\Rightarrow(a)$, assume that $\exp(2\pi i fP)$ is a continuous map on $Y$. So, applying the determinant, $\det(\exp(2\pi i fP)=\exp(\tr(2\pi ifP))$ is a continuous function on $Y$. Using $\tr(P)=1$ on $U$, we see that the equality $\exp(\tr(2\pi ifP))=\exp(2\pi if)$ holds everywhere on $Y$, hence the continuity of $\exp(2\pi if)$.

For $(a)\Rightarrow (b)$, suppose that $\exp(2\pi if)$ is continuous on $Y$. Using the assumption on $P$, the map $\exp(2\pi ifP)$ is certainly continuous on $U$. Let us show that it is also continuous at any $y\in Y\setminus U$. So let $(y_j)_{j\in I}$ be a net in $Y$ converging to $y$. By the Taylor expansion of the exponential:
\begin{equation}\label{Taylor}
\exp(2\pi ifP)=\exp(2\pi if)P + ({\bf 1}_n-P).
\end{equation}
Hence, denoting by $\|\cdot\|$ the operator norm on $M_n(\C)$, we have (using (\ref{Taylor}) for the second equality):
$$\|\exp(2\pi i f(y)P(y))-\exp(2\pi if(y_j)P(y_j))\|=\|{\bf 1}_n-\exp(2\pi if(y_j)P(y_j))\|$$
$$=\|(1-\exp(2\pi if(y_j)))P(y_j)\|\leq |\exp(2\pi if(y))-\exp(2\pi if(y_j))|$$
which goes to 0 for $j\rightarrow\infty$.

\item Let $P_0,P_1:Y\rightarrow Proj_1(M_n(\C))$ be maps, vanishing on $Y\setminus U$, such that $P_0|_U,P_1|_U$ are homotopic. Let $P:U\times [0,1]\rightarrow Proj_1(M_n(\C))$ be a homotopy, i.e. $P(y,0)=P_0(y)$ and $P(y,1)=P_1(y)$ for every $y\in U$. Extend $P$ to $Y\times[0,1]$ by 0 outside of $U\times [0,1]$. View $f$ as a function on $Y\times [0,1]$ by composing with the first projection. Then apply the first part of the lemma to $f$ and $P$, with $Y$ replaced by $Y\times [0,1]$ and $U$ replaced by $U\times [0,1]$. So $\exp(2\pi ifP)$ is continuous on $Y\times[0,1]$, and yields a homotopy between $\exp(2\pi ifP_0)$ and $\exp(2\pi ifP_1)$.

\item If $U$ is contractible, then $P$ is homotopic to $P_0$ which, on $U$, is a constant function to $Proj_1(M_n(\C))$, and is 0 on $Y\setminus U$. By the second part of the lemma together with (\ref{Taylor}), we have:
$$[\exp(2\pi ifP)]=[\exp(2\pi ifP_0)]=[\exp(2\pi if)P_0+(1-P_0)]=[\exp(2\pi if)].$$\epr
\end{enumerate}

{\bf Proof of Theorem \ref{main2}:}
Assume $X_1(y)\neq 0$. Then $\ell_{X_1}(y)$ is a rank 1 projection, and since $[X_0,\ell_{X_1}]=0$ (see Theorem \ref{PV}), $(\ell_{X_1}X_0)(y)$ is a self-adjoint matrix with image contained in the image of $\ell_{X_1}(y)$. So there exists a continuous function $f:supp(X_1)\rightarrow \R$ such that $(\ell_{X_1}X_0)(y)=f(y)\ell_{X_1}(y)$ for every \linebreak $y\in supp(X_1)$. We extend $f$ to $Y$ by setting it equal to 0 outside of $supp(X_1)$. Then, using (\ref{Taylor}):
$$\exp(2\pi iX_0\ell_{X_1})=\exp(2\pi if\ell_{X_1})=\exp(2\pi if)\ell_{X_1}+(1-\ell_{X_1}).$$
By Theorem \ref{PV}, $\exp(2\pi if)\ell_{X_1}+(1-\ell_{X_1})$ belongs to $M_2(C(Y))$; by lemma \ref{homotopy}, this is equivalent to $\exp(2\pi if)\in C(Y)$; finally, again by Theorem \ref{PV}, the image of the corresponding Rieffel projection under $\partial_0$, is the class of that unitary in $K_1(C(Y))$. If $supp(X_1)$ is contractible, by the 3rd part of lemma \ref{homotopy}, this coincides with the class of $\exp(2\pi if)$ in $C(Y)$.
\epr

It might be interesting to have explicit formulae, so write $X_0=\left(\begin{array}{cc}a & b \\ \overline{b} & 1-a\end{array}\right)$ and $X_1=\left(\begin{array}{cc}\alpha & \beta \\\gamma & -\alpha\end{array}\right)$ for some $a, b, \alpha,\beta,\gamma\in C(Y)$ (with $a$ real-valued), and observe that $supp(X_1)=supp(\beta)\cup supp(\gamma)$. 
\begin{itemize}
\item If $\beta(y)\neq 0$, then the vector $(\beta(y),-\alpha(y))$ spans the image of $X_1(y)$, hence 
$$\ell_{X_1}(y)=\frac{1}{|\alpha(y)|^2+|\beta(y)|^2}\left(\begin{array}{cc}|\beta(y)|^2 & -\beta(y)\overline{\alpha(y)} \\ -\overline{\beta(y)}\alpha(y)  & |\alpha(y)|^2\end{array}\right).$$
The (1,1)-coefficient of $(X_0\ell_{X_1})(y)$ is $\frac{-\beta(y)\overline{b(y)\alpha(y)}+ a(y)|\beta(y)|^2}{|\alpha(y)|^2+|\beta(y)|^2}$, hence 
$$f(y)= a(y)-\frac{\alpha(y)b(y)}{\beta(y)}.$$
For a projection of Loring type (see Example \ref{Loring1}), we have $\alpha=\gamma=0$, so for $\beta(y)\neq 0$ we find $f(y)=a(y)$, as in Example \ref{Loring1}.

\item If $\gamma(y)\neq 0$, then the vector $(\alpha(y),\gamma(y))$ spans the image of $X_1(y)$, hence 
$$\ell_{X_1}(y)=\frac{1}{|\alpha(y)|^2+|\gamma(y)|^2}\left(\begin{array}{cc}|\alpha(y)|^2 & \alpha(y)\overline{\gamma(y)} \\\overline{\alpha(y)}\gamma(y)  & |\gamma(y)|^2\end{array}\right).$$
The (2,2)-coefficient of $(X_0\ell_{X_1})(y)$ is $\frac{\alpha(y)\overline{b(y)\gamma(y)}+(1-a(y))|\gamma(y)|^2}{|\alpha(y)|^2+|\gamma(y)|^2}$, hence 
$$f(y)=1-a(y)+\frac{\alpha(y)\overline{b(y)}}{\gamma(y)}.$$
If $y\in supp(\beta)\cap supp(\gamma)$, then the two formulae for $f(y)$ match, as an easy consequence of (\ref{nonlincond}) and (\ref{linearcond}).
\end{itemize}

\section{Another Rieffel projection in $M_2(C(\T^2))$}

Here we exploit the action of the unitary group of $M_2(C(Y))$ on solutions $(X_0,X_1)$ of the system (\ref{Rieffel1}), (\ref{Rieffel2}), (\ref{Rieffel3}): for $U\in U_2(C(Y))$, the pair $(UX_0U^*,UX_1U^*)$ is a solution of the same system. Moreover, the function $f$ associated with the pair is invariant under this action, as follows from $X_0\ell_{X_1}=f\ell_{X_1}$ (see Theorem \ref{main2}).

For $Y=[0,1]$, let us start with the pair 
$$\mathcal{X}_0(\theta)=\left(\begin{array}{cc}\sin^2(\frac{\pi\theta}{2}) & 0 \\0 & \cos^2(\frac{\pi\theta}{2})  \end{array}\right),\;\mathcal{X}_1(\theta)=\left(\begin{array}{cc}0 & \sin(\frac{\pi\theta}{2})  \cos(\frac{\pi\theta}{2})  \\0 & 0\end{array}\right);$$
equations (\ref{Rieffel1}), (\ref{Rieffel2}), (\ref{Rieffel3}) are clearly satisfied, so we have a Rieffel projection - actually of trivial type - in $M_2(C(Y))$; here $\ell_{\mathcal{X}_1}(\theta)=\left(\begin{array}{cc}1 & 0 \\0 & 0\end{array}\right)$ for $0<\theta<1$, while $\ell_{\mathcal{X}_1}(0)=\ell_{\mathcal{X}_1}(1)=0$. Moreover 
\begin{equation}\label{goodf}
f(\theta)=\left\{\begin{array}{ccc}\sin^2(\frac{\pi\theta}{2}) & if & 0\leq\theta<1 \\0 & if & \theta=1 \end{array}\right.
\end{equation}

{\bf Proof of Theorem \ref{magict}:}
Observe that $\mathcal{X}_0(0)=\left(\begin{array}{cc}0 & 0 \\0 & 1\end{array}\right)$ and $\mathcal{X}_0(1)=\left(\begin{array}{cc}1 & 0 \\0 & 0\end{array}\right)$, so that $\mathcal{X}_0$ does not descend to $S^1$ (while $\mathcal{X}_1$ does). To correct this, we consider $U\in U_2(C([0,1]))$ given by a family of rotations:
$$U_\theta=\left(\begin{array}{cc}\sin(\frac{\pi\theta}{2}) & \cos(\frac{\pi\theta}{2}) \\-\cos(\frac{\pi\theta}{2}) & \sin(\frac{\pi\theta}{2})\end{array}\right);$$
$U_\theta$ is the rotation of angle $\frac{\pi}{2}(\theta-1),\;\theta\in [0,1]$.
Define then 
$$X_0(\theta)=U_\theta\mathcal{X}_0(\theta)U_\theta^*;\;X_1(\theta)=U_\theta\mathcal{X}_1(\theta)U_\theta^*,$$
which are now 1-periodic, as $X_0(0)=X_0(1)=\left(\begin{array}{cc}1 & 0 \\0 & 0\end{array}\right).$
Direct computations give:
$$X_0(\theta)=\left(\begin{array}{cc}\sin^4(\frac{\pi\theta}{2}) + \cos^4(\frac{\pi\theta}{2})  & \sin(\frac{\pi\theta}{2}) \cos^3(\frac{\pi\theta}{2}) -\sin^3(\frac{\pi\theta}{2}) \cos(\frac{\pi\theta}{2})  \\
\sin(\frac{\pi\theta}{2}) \cos^3(\frac{\pi\theta}{2}) -\sin^3(\frac{\pi\theta}{2}) \cos(\frac{\pi\theta}{2}) & 2\sin^2(\frac{\pi\theta}{2}) \cos^2(\frac{\pi\theta}{2}) \end{array}\right)$$
$$=\frac{1}{2}\left(\begin{array}{cc}2-\sin^2(\pi\theta) & \sin(\pi\theta) \cos(\pi\theta)  \\\sin(\pi\theta) \cos(\pi\theta)  & \sin^2(\pi\theta) \end{array}\right)$$
$$=\frac{1}{4}\left(\begin{array}{cc}3+\cos(2\pi\theta) & \sin(2\pi\theta)\\\sin(2\pi\theta) & 1-\cos(2\pi\theta) \end{array}\right).$$
Note that $X_0$ is indeed expressed in terms of 1-periodic trigonometric polynomials, i.e. it is in the algebra of 2-by-2 matrices over the complex group ring $\C[\Z]$.
$$X_1(\theta)=\sin(\frac{\pi\theta}{2})\cos(\frac{\pi\theta}{2})\left(\begin{array}{cc}\sin(\frac{\pi\theta}{2})\cos(\frac{\pi\theta}{2}) & \sin^2(\frac{\pi\theta}{2}) \\-\cos^2(\frac{\pi\theta}{2}) & -\sin(\frac{\pi\theta}{2})\cos(\frac{\pi\theta}{2})\end{array}\right)$$
$$=\frac{\sin(\pi\theta)}{4}\left(\begin{array}{cc}\sin(\pi\theta) & 1-\cos(\pi\theta) \\-1-\cos(\pi\theta) & -\sin(\pi\theta)\end{array}\right)$$
$$=\frac{1}{8}\left(\begin{array}{cc}1-\cos(2\pi\theta) & \sqrt{2(1-\cos(2\pi\theta))}-\sin(2\pi\theta) \\-\sqrt{2(1-\cos(2\pi\theta))}-\sin(2\pi\theta) & -1+\cos(2\pi\theta)\end{array}\right).$$
Note that $X_1$ is not in $M_2(\C[\Z])$ (it can't be, as mentioned in the Introduction).%but almost: it is in the smallest sub-algebra of $M_2(C(S^1))$ containing $M_2(\C[\Z])$ and closed under square roots of positive elements.

It remains to prove that $\partial_0[P_I]=[\exp(2\pi i\theta)]$. But here $supp(X_1)=\,]0,1[$ is contractible, so lemma \ref{homotopy} applies, and $\partial_0[P_I]=[\exp(2\pi if)]$, where $f$ is given by (\ref{goodf}). But $\exp(2\pi if(\theta))=\exp(2\pi i\sin^2(\frac{\pi\theta}{2}))$ for every $\theta\in[0,1]$, and since $\exp(2\pi i\sin^2(\frac{\pi\theta}{2}))$ has winding number 1, the result follows. \epr

\section{Applications}

\subsection{Arbitrary crossed products with $\Z$}

Let $A$ be a unital $C^*$-algebra, and let $\alpha$ be any *-automorphism of $A$.

\begin{Cor}\label{crossedproduct} Assume that $\alpha(v)=v$ for some unitary $v\in A$. Then there exists a projection $p\in M_2(A\rtimes_\alpha \Z)$ such that $\partial_0[p]=[v]$ in $K_1(A)$.
\end{Cor}

\bpr Let $u$ be the unitary in $A\rtimes_\alpha \Z$ implementing the action. By assumption, $u$ and $v$ are commuting unitaries, so they define a surjective *-homomorphism $C(\T^2)\rightarrow C^*(u,v)$. Let then $p\in M_2(C^*(u,v))$ be defined either by $P_L(v,u)$ or by $P_I(v,u)$. By Example \ref{Loring2} or by Theorem \ref{magict}, we have $\partial_0[p]=[v]$ in $K_1(C^*(v))$. By naturality of the Pimsner-Voiculescu exact sequence (see Theorem 10.2.1 in \cite{Black}), we also have $\partial_0[p]=[v]$ in $K_1(A)$. \epr

\subsection{Maps of degree 1 from $\T^2$ to $P^1(\C)$}

Recall that $Proj_1(M_2(\C))$ denotes the space of rank 1 projections in $M_2(\C)$: it is canonically homeomorphic to the complex projective line $P^1(\C)$ (itself non-canonically homeomorphic to the 2-sphere $S^2$). A rank 1 projection in $M_2(C(Y))$ can be viewed as a continuous map $Y\rightarrow P^1(\C)$. From Example \ref{Loring2} and Theorem \ref{magict}, we immediately deduce:

\begin{Cor}\label{degree1} The maps $P_L$ and $P_I$ are degree 1 maps from $\T^2$ to $P^1(\C)$.
\epr
\end{Cor}

At this juncture, we observe that the Bass-Heller-Swan \cite{BHS} result already mentioned in the Introduction, implies that any map $\T^2\rightarrow Proj_1(M_2(\C))$ given by trigonometric polynomials, has degree 0. In the same vein, let us quote a result by Loday \cite{Loday}: viewing $\T^2$ as the product of two unit circles in $\R^2\times\R^2$, and $S^2$ as the unit sphere in $\R^3$, any polynomial map $\T^2\rightarrow S^2$ is homotopically trivial.

For more on degree 1 maps from $\T^2$ to $S^2$, see a discussion on Mathematics Stack Exchange \cite{MathStack}.

\subsection{K-theory of the 3-torus}

Let $\T^3$ denote the 3-torus. It is well-known that $K_0(C(\T^3))\simeq\Z^4\simeq K_1(C(\T^3))$. Writing $\T^3$ as the product of $\T^2$ and $S^1$ in various ways, we will exploit Theorem \ref{magict} to give explicit generators of $K_0(C(\T^3))$ and $K_1(C(\T^3))$. A point on $\T^3$ will be written $(\exp(2\pi i\theta),\exp(2\pi i\varphi),\exp(2\pi i\psi))$, with $\theta,\varphi,\psi\in [0,1]$.

\begin{Cor}\label{3torus}\begin{itemize}
\item The group $K_0(C(\T^3))$ is generated by the classes of the projections $1, P_I(\theta,\varphi),P_I(\varphi,\psi),P_I(\psi,\theta)$.
\item The group $K_1(C(\T^3))$ is generated by the classes of $\exp(2\pi i\theta),$ $\exp(2\pi i\varphi),$ $\exp(2\pi i\psi)$ and 
\begin{equation}\label{magicunit}
U_I(\theta,\varphi,\psi):=P_I(\theta,\varphi)\exp(2\pi i\psi)+({\bf 1}_2-P_I(\theta,\varphi))
\end{equation} (the latter being a unitary in $M_2(C(\T^3))$).
\end{itemize}\end{Cor}

\bpr\begin{itemize}
\item For $K_0$: for a compact space $Y$, we denote by $\widetilde{K}_0(C(Y))$ the {\it reduced} K-theory of $C(Y)$, namely $K_0(C(Y))/\Z\cdot[1]$. We define
$$\varepsilon_{\theta,\varphi}:C(\T^3)\rightarrow C(\T^2): f\mapsto [(\theta,\varphi)\mapsto f(\theta,\varphi,0)]$$
(evaluation at $\psi=0$); the maps $\varepsilon_{\varphi,\psi},\varepsilon_{\psi,\theta}$ are defined analogously. We consider then
$$\beta:=(\varepsilon_{\theta,\varphi})_*\oplus(\varepsilon_{\varphi,\psi})_*\oplus(\varepsilon_{\psi,\theta})_*:\widetilde{K}_0(C(\T^3))\rightarrow (\widetilde{K}_0(C(\T^2)))^3.$$
Note that both the source and the range of $\beta$ are isomorphic to $\Z^3$. We claim that $\beta[P_I(\theta,\varphi)]=([P_I(\theta,\varphi)],0,0)$. Indeed, clearly $\varepsilon_{\theta,\varphi}(P_I(\theta,\varphi))=P_I(\theta,\varphi)$, while $\varepsilon_{\varphi,\psi}(P_I(\theta,\varphi))=\left(\begin{array}{cc}1 & 0 \\0 & 0\end{array}\right)=\varepsilon_{\psi,\theta}(P_I(\theta,\varphi))$ by formula (\ref{magic0}); so the two latter vanish in reduced K-theory. Similarly we have $\beta[P_I(\varphi,\psi)]=(0,[P_I(\varphi,\psi)],0)$ and $\beta[P_I(\psi,\theta)]=(0,0,[P_I(\psi,\theta)])$, so that $\beta$ maps the set $\{[P_I(\theta,\varphi)],[P_I(\varphi,\psi)],[P_I(\psi,\theta)]\}\subset \widetilde{K}_0(C(\T^3))$ to the set
$$\{([P_I(\theta,\varphi)],0,0), (0,[P_I(\varphi,\psi)],0), (0,0,[P_I(\psi,\theta)])\}$$
which is a basis of $(\widetilde{K}_0(C(\T^2)))^3$ by Theorem \ref{magict}: this proves the desired result.
\item For $K_1$, we recall that, for $A,B$ unital $C^*$-algebras, there is the product map:
$$K_1(A)\otimes_\Z K_0(B)\rightarrow K_1(A\otimes B):[u]\otimes[p]\mapsto [u\otimes p+1\otimes(1-p)],$$
where $u\in U_m(A),p\in Proj(M_n(B))$ and $u\otimes p+1\otimes(1-p)\in U_{mn}(A\otimes B)$ (see e.g. Proposition 4.8.3 in \cite{HiRo}). By the K\"unneth formula (Theorem 23.1.3 in \cite{Black}), since all the involved K-groups are torsion-free, the product induces an isomorphism
$$K_1(C(T^2))\otimes_\Z K_0(C(S^1))\oplus K_0(C(\T^2))\otimes_\Z K_1(C(S^1))\simeq K_1(C(\T^3)).$$
The first summand contributes the generators $[\exp(2\pi i\theta)],[\exp(2\pi i\varphi)]$; \linebreak the second summand contributes the generators $[\exp(2\pi i\psi)]$ and \linebreak $[P_I(\theta,\varphi)\exp(2\pi i\psi)+({\bf 1}_2-P_I(\theta,\varphi))]$

\end{itemize}\epr

\begin{Rem} Corollary \ref{3torus} also holds with $P_I$ replaced all over by $P_L$. It may be interesting to notice that all generators of $K_i(C(\T^3))$ can be realized within $M_2(C(\T^3))$.
\end{Rem} 

