\section{Useful Mathematical Tools}
\begin{theorem}\citep{klein2005concentration}\label{thm: sup_empirical_process}
    Consider a countable, $\sigma$-uniformly bounded function class $\cG$ such that $\EE[g(X)]=0$ for all $g$. Then for any $\tau>0$, we have with probability at least $1-\delta$,
    \[
    \sup_{g\in\cG}\sqrt{\frac{1}{N}\sum_{i=1}^{N}g(X_i)^2}=||\PP_{N}||_{\cG}\le (1+\tau)\EE[||\PP_{N}||_{\cG}]+\sqrt{\sigma^2(\cG)}\cdot\sqrt{\frac{2\log(1/\delta)}{N}}+(3+\frac{1}{\tau})\frac{\sigma\log(1/\delta)}{N}.
    \]
\end{theorem}

Next, we introduce the peeling argument in \citet{xia2024predictionaidedsurrogatetraining}.
\begin{lemma}\citep{xia2024predictionaidedsurrogatetraining}\label{lemma:peeling}
Given a function class $\cF$, with norm $||\cdot||$ and some empirical process $\cbr{V_n(f):f\in\cF}$, consider a $r$-localized supremum of the form $Z_N(r):=\sup_{f\in\cF,||f||\le r}V_N(f)$. There is a function $Q(r,t)$ increasing in the first argument $r$ and $Q(2r,t)\le 2Q(r,t)$ for all $r\ge s$, where $s$ is some scalar. If we have \[
\PP(Z_N(r)\ge Q(r,t))\le e^{-t},\ \forall r\ge s, 
\]
then, for any random variable $U$ taking values in $[s,b]$, we have
\[
\PP(Z_N(U)\ge 2Q(U,t))\le \ceil{\log_2(\frac{2b}{s})}e^{-t},\ \forall r\ge s,
\]
\end{lemma}
\begin{lemma}[Talagrand Inequality \citep{gine2021mathematical}]\label{lemma:Talagrand_ineq}
    Let $\cF$ be a separable function class with absolute values bounded by $1$, let $X_i,\ i\in\NN$ be independent, identically distributed random variables with common probability law $\PP$ and let $\varepsilon_i$, $i\in\NN$ be a Rademacher sequence from the sequence $\cbr{X_i}$. Then, for all $n\in\NN$ and $x\ge 0$,
    \[
    \PP\cbr{\bignorm{\frac{1}{n}\sum_{i=1}^{n}(f(X_i)-\PP f)}_{\cF}\ge2\bignorm{\frac{1}{n}\sum_{i=1}^{n}f(X_i)}_{\cF}+3\sqrt{\frac{2x}{n}}}\le 2e^{-x}.
    \]
\end{lemma}
\begin{lemma}[Ledoux-Talagrand Lemma]\label{lemma:Ledoux_Talagrand}
    Let $\{\varepsilon_i\}_{i=1}^n$ be a sequence of independent Rademacher random variables (i.e., symmetric Bernoulli random variables), and let $\phi_i : \mathbb{R} \to \mathbb{R}$ be contraction mappings, i.e., $L$-Lipschitz functions such that $\phi_i(0) = 0$. Let $F : [0, \infty) \to \mathbb{R}$ be a nonnegative, nondecreasing convex function. Then for any bounded subset $T \subset \mathbb{R}^n$, we have:
\[
\mathbb{E} \left[ F\left( \frac{1}{2} \sup_{t \in T} \left| \sum_{i=1}^n \varepsilon_i \phi_i(t_i) \right| \right) \right] 
\le 
L\mathbb{E} \left[ F\left( \sup_{t \in T} \left| \sum_{i=1}^n \varepsilon_i t_i \right| \right) \right].
\]
\end{lemma}
\begin{lemma}[McDiarmid's Inequality]\label{lemma:micdiarmid}
    Let \( X_1, X_2, \dots, X_n \) be independent random variables taking values in some sets \( \mathcal{X}_1, \mathcal{X}_2, \dots, \mathcal{X}_n \), respectively.  
Suppose that a function \( f : \mathcal{X}_1 \times \cdots \times \mathcal{X}_n \to \mathbb{R} \) satisfies the bounded difference property:  
\[
\sup_{x_1, \dots, x_n, x_i'} \left| f(x_1, \dots, x_i, \dots, x_n) - f(x_1, \dots, x_i', \dots, x_n) \right| \le c_i, \quad \text{for all } i = 1, \dots, n.
\]
Then, for all \( \varepsilon > 0 \),
\[
\mathbb{P}\left( f(X_1, \dots, X_n) - \mathbb{E}[f(X_1, \dots, X_n)] \ge \varepsilon \right) \le \exp\left( -\frac{2\varepsilon^2}{\sum_{i=1}^n c_i^2} \right),
\]
and similarly,
\[
\mathbb{P}\left( \left| f(X_1, \dots, X_n) - \mathbb{E}[f(X_1, \dots, X_n)] \right| \ge \varepsilon \right) \le 2 \exp\left( -\frac{2\varepsilon^2}{\sum_{i=1}^n c_i^2} \right).
\]
\[
\left| f(X_1, \dots, X_n) - \mathbb{E}[f(X_1, \dots, X_n)] \right| \le \sqrt{\frac{1}{2} \sum_{i=1}^n c_i^2 \cdot \log\left( \frac{2}{\delta} \right)}
\]
\end{lemma}
\begin{lemma}[Hoeffding Inequality for Lipschitz Transformations]\label{lemma:Hoeffding_Lipschitz}
Let $X_1, \dots, X_n$ be independent random variables with $X_i \in [a, b]$ almost surely for all $i \in \{1, \dots, n\}$, and define the empirical mean $\bar{X}_n := \frac{1}{n} \sum_{i=1}^n X_i$. Suppose $f : \mathbb{R} \to \mathbb{R}$ is an $L$-Lipschitz function, i.e.,
\[
|f(x) - f(y)| \le L |x - y|, \quad \forall x,y \in \mathbb{R}.
\]
Then, for any $\varepsilon > 0$,
\[
\mathbb{P}\left( \left| f(\bar{X}_n) - f\left(\mathbb{E}[X_1]\right) \right| \ge \varepsilon \right) 
\le 2 \exp\left( -\frac{2n\varepsilon^2}{L^2(b - a)^2} \right).
\]
Then, for any $\delta \in (0,1)$, with probability at least $1 - \delta$, we have
\[
\left| f(\bar{X}_n) - f\left(\mathbb{E}[X_1]\right) \right| 
\le L(b - a) \sqrt{\frac{\log(2/\delta)}{2n}}.
\]
\end{lemma}
\section{Proofs in \cref{sec:algorithm}}
First, we analyze the estimation error of \cref{thm:erm_oracle_ineq} in this section. First, we have
\begin{align*}
    ||\hat{f}-f^*||_2^2=||\hat{f}-f^*||_2^2-||\hat{f}-f^*||_N^2+||\hat{f}-f^*||_N^2.
\end{align*}
Since the ERM minimizes the empirical risk, we have
\[
\frac{1}{N}\sum_{i=1}^{N}\rbr{f^*(x_i,z_i^*,a_i)+\xi_i-\hat{f}(x_i,\Tilde{z}_i,a_i)}^2\le\frac{1}{N}\sum_{i=1}^{N}\rbr{f^*(x_i,z_i^*,a_i)+\xi_i-f^*(x_i,\Tilde{z}_i,a_i)}^2.
\]
By some algebra,
\begin{align*}
    &\frac{1}{N}\sum_{i=1}^{N}\rbr{f^*(x_i,z_i^*,a_i)+\xi_i-f^*(x_i,\Tilde{z}_i,a_i)-(\hat{f}(x_i,\Tilde{z}_i,a_i)-f^*(x_i,\Tilde{z}_i,a_i))}^2\\
    \le&\frac{1}{N}\sum_{i=1}^{N}\rbr{f^*(x_i,z_i^*,a_i)+\xi_i-f^*(x_i,\Tilde{z}_i,a_i)}^2.
\end{align*}
Therefore,
\begin{align*}
    &\frac{1}{N}\sum_{i=1}^{N}\rbr{f^*(x_i,\Tilde{z}_i,a_i)-\hat{f}(x_i,\Tilde{z}_i,a_i)}^2\\
    \le&\frac{2}{N}\sum_{i=1}^{N}\rbr{f^*(x_i,z_i^*,a_i)+\xi_i-f^*(x_i,\Tilde{z}_i,a_i)}\rbr{\hat{f}(x_i,\Tilde{z}_i,a_i)-f^*(x_i,\Tilde{z}_i,a_i)}\\
    =&\frac{2}{N}\sum_{i=1}^{N}\xi_i\rbr{\hat{f}(x_i,\Tilde{z}_i,a_i)-f^*(x_i,\Tilde{z}_i,a_i)}+\frac{2}{N}\sum_{i=1}^{N}\rbr{f^*(x_i,z_i^*,a_i)-f^*(x_i,\Tilde{z}_i,a_i)}\rbr{\hat{f}(x_i,\Tilde{z}_i,a_i)-f^*(x_i,\Tilde{z}_i,a_i)}.
\end{align*}
For the term $\sum_{i=1}^{N}\rbr{f^*(x_i,z_i^*,a_i)-f^*(x_i,\Tilde{z}_i,a_i)}\rbr{\hat{f}(x_i,\Tilde{z}_i,a_i)-f^*(x_i,\Tilde{z}_i,a_i)}$, we have,
\begin{align*}
&\sum_{i=1}^{N}\rbr{f^*(x_i,z_i^*,a_i)-f^*(x_i,\Tilde{z}_i,a_i)}\rbr{\hat{f}(x_i,\Tilde{z}_i,a_i)-f^*(x_i,\Tilde{z}_i,a_i)}\\
=&\frac{2}{N}\sum_{i=m+1}^{m+n}\rbr{f^*(x_i,z_i^*,a_i)-f^*(x_i,\Tilde{z}_i,a_i)}\rbr{\hat{f}(x_i,\Tilde{z}_i,a_i)-f^*(x_i,\Tilde{z}_i,a_i)}.
\end{align*}
Combining all these together, we have,
\begin{align*}
    ||\hat{f}-f^*||_2^2\le& \frac{2}{N}\sum_{i=1}^{N}\xi_i\rbr{\hat{f}(x_i,\Tilde{z}_i,a_i)-f^*(x_i,\Tilde{z}_i,a_i)}+||\hat{f}-f^*||_2^2-||\hat{f}-f^*||_N^2\\
    +& \frac{2}{N}\sum_{i=m+1}^{m+n}\rbr{f^*(x_i,z_i^*,a_i)-f^*(x_i,\Tilde{z}_i,a_i)}\rbr{\hat{f}(x_i,\Tilde{z}_i,a_i)-f^*(x_i,\Tilde{z}_i,a_i)}
\end{align*}
Now we are ready to analyze the error term by term. As a reminder, recall $\varphi_{b}(x)=\log_2(4b/x)$ as defined in \cref{sec:algorithm}.
\begin{lemma}\label{lemma:bound_K_1}
    Define $K_1=||\hat{f}-f^*||_2^2-||\hat{f}-f^*||_N^2$, then conditioned on $||\hat{f}-f^*||_2\ge r_N$, with probability at least $1-\delta$, 
    \[
    K_1\le 2r_N||\hat{f}-f^*||_2+8\sqrt{\frac{2\log(\varphi_{\lambda}r_N)/\delta)}{N}}||\hat{f}-f^*||_2+\frac{16\log(\varphi_{\lambda}r_N)/\delta)}{N}.
    \]
\end{lemma}
\begin{proof}[Proof of \cref{lemma:bound_K_1}]
We define the function $H_f(x,z,a)=(f(x,z,a)-f^*(x,z,a))^2$ for all $f\in\cF$. Define
\[
Z_N(t):=\sup_{f\in\cH(t)}\cbr{\PP_N(H_f)-\PP(H_f)},
\]
where $\cH(t):=\cbr{H_f:f\in\cF,\ \text{s.t.} ||f-f^*||_2\le t}$. By construction, we have
$$K_1\le Z_N(||\hat{f}-f^*||_2).$$
    We then set $\tau=1$ and apply \cref{thm: sup_empirical_process}. Functions in $\cH(t)$ are uniformly bounded by $2$. to get with probability at least $1-\delta$,
    \[
    Z_N(t)\le 2\EE[Z_N(t)]+\sqrt{\sigma^2(\cH(t))}\sqrt{\frac{2\log(1/\delta)}{N}}+\frac{16\log(1/\delta)}{N}.
    \]
    On one hand, we have
    \[
    \sigma^2(\cH(t))=\sup_{||f-f^*||_2\le t}\PP_{\cD}\rbr{(f(x,z,a)-f^*(x,z,a))^4}\le 4\PP_{\cD}\rbr{(f(x,z,a)-f^*(x,z,a))^2}\le 4t^2.
    \]
    \[
    \EE[Z_N(t)]=\EE\sbr{\sup_{||f^*-f||_2\le t}\abr{||f^*-f||_N^2-||f-f^*||_2^2}}\le 2\EE\sbr{\sup_{||f^*-f||_2\le t}\abr{\frac{1}{N}\sum_{i=1}^{N}\varepsilon_i\rbr{f^*(x_i,\Tilde{z}_i,a_i)-f(x_i,\Tilde{z}_i,a_i)}^2}}.
    \]
    By \cref{lemma:Ledoux_Talagrand}, the function $\phi_i(t)=\phi(t)=t^2$ is $4$-Lipschitz on the interval $[0,2]$, we have
    \begin{align*}\hspace{-0.6cm}
    &2\EE\sbr{\sup_{||f^*-f||_2\le t}\abr{\frac{1}{N}\sum_{i=1}^{N}\varepsilon_i\rbr{f^*(x_i,\Tilde{z}_i,a_i)-f(x_i,\Tilde{z}_i,a_i)}^2}}\\
    \le& 8\EE\sbr{\sup_{||f^*-f||_2\le t}\abr{\frac{1}{N}\sum_{i=1}^{N}\varepsilon_i\rbr{f^*(x_i,\Tilde{z}_i,a_i)-f(x_i,\Tilde{z}_i,a_i)}}}\\
    =&8\cR_N(t,\cF).
    \end{align*}
    By definition, we have $\cR_N(t,\cF)\le\frac{t}{16}r_N$.
    Pluging all these in, we get with probability at least $1-\delta$,
    \[
    Z_N(t)\le r_Nt+4\sqrt{\frac{2\log(1/\delta)}{N}}t+\frac{16\log(1/\delta)}{N}.
    \]
Setting $\delta=e^{-\eta}$ and $\eta=\log(1/\delta)$, this is equivalent to
\[
\PP(Z_N(t)\ge r_Nt+4\sqrt{\frac{2\eta}{N}}t+\frac{8\eta}{N})\le e^{-\eta}.
\]
Define the random variable $U=||\hat{f}-f^*||_2$, and apply the peeling argument in \cref{lemma:peeling}, we shall get
\[
\PP\rbr{Z_N(U)\ge 2(r_NU+4\sqrt{\frac{2\eta}{N}}U+\frac{8\eta}{N})}\le \ceil{\log_2\frac{4}{r_N}}e^{-\eta}.
\]
Therefore, with probability $1-\delta$,
\[
Z_N(||\hat{f}-f^*||_2)\le 2r_N||\hat{f}-f^*||_2+8\sqrt{\frac{2\log(\varphi_2(r_N)/\delta)}{N}}||\hat{f}-f^*||_2+32\frac{\log(\varphi_2(r_N)/\delta)}{N}.
\]
\end{proof}

Now we bound the second term $K_2:=\frac{2}{N}\sum_{i=1}^{N}\xi_i\rbr{\hat{f}(x_i,\Tilde{z}_i,a_i)-f^*(x_i,\Tilde{z}_i,a_i)}$. 
\begin{lemma}\label{lemma:bound K_2}
    Condition on $||\hat{f}-f^*||_2\ge r_N$, we have that with probability at least $1-\delta$,
    \[
    K_2\le \lambda r_N||\hat{f}-f^*||_2+4\lambda\sqrt{\frac{2\log(\varphi_2(r_N)/\delta)}{N}}||\hat{f}-f^*||_2+\frac{32\lambda\log(\varphi_2(r_N)/
    \delta)}{N}.
    \]
\end{lemma}
\begin{proof}[Proof of \cref{lemma:bound K_2}]
    We define the following empirical process
    $$V_N(t):=\sup_{||\hat{f}-f^*||_2\le t}\abr{\frac{1}{N}\sum_{i=1}^{N}\xi_i\rbr{f^*(x_i,\Tilde{z}_i,a_i)-f(x_i,\Tilde{z}_i,a_i)}}.$$
    Define the function class $\cH(t):=\cbr{\xi(f-f^*):f\in\cF, ||f-f^*||_2\le t, |\xi|\le \lambda, \xi\in\QQ}$. By construction,
     \[
     K_2\le 2V_N(||\hat{f}-f^*||_2).
     \]
     Applying \cref{thm: sup_empirical_process} and setting $\tau=1$, we have with probability at least $1-\delta$,
    \[
    V_N(t)\le 2\EE[V_N(t)]+\sqrt{\sigma^2(\cH(t))}\sqrt{\frac{2\log(1/\delta)}{N}}+\frac{8\lambda\log(1/\delta)}{N}.
    \]
    We have
    \[
    \sigma^2(\cH(t))=\sup_{||f-f^*||_2\le t,|\xi|\le \lambda}\text{Var}(\xi(f-f^*))\le \lambda^2t^2.
    \]
    \[
    \EE[V_N(t)]=\EE\sbr{\sup_{||f-f^*||_2\le t}\abr{\frac{1}{N}\sum_{i=1}^{N}\varepsilon_i\xi_i\rbr{f(x_i,\Tilde{z}_i,a_i)-f^*(x_i,\Tilde{z}_i,a_i)}}}.
    \]
    Conditioned on $\xi_t$ and setting $\phi_i(t)=\frac{\xi_i}{\lambda}t$, we apply \cref{lemma:Ledoux_Talagrand} to get
    \begin{align*}\hspace{-0.9cm}
        &\EE\sbr{\sup_{||f-f^*||_2\le t}\abr{\frac{1}{N}\sum_{i=1}^{N}\varepsilon_i\xi_i\rbr{f(x_i,\Tilde{z}_i,a_i)-f^*(x_i,\Tilde{z}_i,a_i)}}}\\
        \le& 2\lambda\EE\sbr{\sup_{||f-f^*||_2\le t}\abr{\frac{1}{N}\sum_{i=1}^{N}\varepsilon_i\rbr{f(x_i,\Tilde{z}_i,a_i)-f^*(x_i,\Tilde{z}_i,a_i)}}}\\
        =&2\lambda\cR_N(t,\cF).
    \end{align*}
    By definition of the critical radius, for $t\ge r_N$, we have $\cR_{N}(t,\cF)\le \frac{r_N}{16}$. Then with probability at least $1-\delta$,
    \[
    V_N(t)\le \frac{1}{4}r_Nt+\lambda\sqrt{\frac{2\log(1/\delta)}{N}}t+\frac{8\lambda\log(1/\delta)}{N}.
    \]
    By the peeling \cref{lemma:peeling}, we define $U=||f^*-\hat{f}||_2$ and plug it in to get
    \[
    V_N(||\hat{f}-f^*||_2)\le \frac{1}{2}\lambda r_N||\hat{f}-f^*||_2+2\lambda\sqrt{\frac{2\log(\varphi_2(r_N)/\delta)}{N}}||\hat{f}-f^*||_2+\frac{16\lambda\log(\varphi_2(r_N)/
    \delta)}{N}.
    \]
\end{proof}
Finally, we bound the third term $K_3:=\frac{2}{N}\sum_{i=m+1}^{m+n}\rbr{f^*(x_i,z_i^*,a_i)-f^*(x_i,\Tilde{z}_i,a_i)}\rbr{\hat{f}(x_i,\Tilde{z}_i,a_i)-f^*(x_i,\Tilde{z}_i,a_i)}$. 

%Recall that in \cref{def:model_elasticity}, we have $\cE_{\PP}^{\cF}(\tilde{g})=\sup_{\substack{f\in\cF,\\a\in\cA}}\EE_{x\sim \PP^*_x, z^*\sim \PP^*\rbr{\cdot|x}}\sbr{(f(x,z^*,a)-f(x,\tilde{g}(x),a))^2}$.
%\begin{definition}
 %   We denote $\cZ$ as the set that $\tilde{z}_i$ lies in and $\cX$ as the space that $x$ belongs to. Then we define the following $\cE_{\PP}^{\cF}(\tilde{g}):=\sup_{\substack{f\in\cF,\\a\in\cA}}\EE_{x\sim \PP^*_x, z^*\sim \PP^*\rbr{\cdot|x}}\sbr{(f(x,z^*,a)-f(x,\tilde{g}(x),a))^2}$.
%\end{definition}
\begin{lemma}\label{lemma:bound_K_3}
    Conditioned on $||f^*-\hat{f}||_2\ge r_N$, with probability at least $1-2\delta$, we have
    \[
    \frac{K_3}{2}\le \rbr{\sqrt{\cE_{\PP}^{\cF}(\tilde{g})}+\frac{4}{\upsilon(f^*,\PP,\tilde{g})^{1/2}}\sqrt{\frac{\log(2/\delta)}{N}}}\rbr{||\hat{f}-f^*||_2+2r_N+8\sqrt{\frac{2\log(\varphi_{\lambda}r_N)/\delta)}{N}}+32\frac{\log(\varphi_{\lambda}r_N)/\delta)}{r_N N}}.
    \]
\end{lemma}
\begin{proof}[Proof of \cref{lemma:bound_K_3}]
    First, by the Cauchy-Schwarz inequality, we have
    \[
    K_3\le \frac{2n}{N}\sqrt{\frac{1}{n}\sum_{i=m+1}^{m+n}\rbr{f^*(x_i,z_i^*,a_i)-f^*(x_i,\Tilde{z}_i,a_i)}^2}\sqrt{\frac{1}{n}\sum_{i=m+1}^{m+n}\rbr{\hat{f}(x_i,\Tilde{z}_i,a_i)-f^*(x_i,\Tilde{z}_i,a_i)}^2}.
    \]
    By some algebra, we have
    \begin{align*}
        &\frac{2n}{N}\sqrt{\frac{1}{n}\sum_{i=m+1}^{m+n}\rbr{f^*(x_i,z_i^*,a_i)-f^*(x_i,\Tilde{z}_i,a_i)}^2}\sqrt{\frac{1}{n}\sum_{i=m+1}^{m+n}\rbr{\hat{f}(x_i,\Tilde{z}_i,a_i)-f^*(x_i,\Tilde{z}_i,a_i)}^2}\\
        \le&2\frac{\sqrt{n}}{\sqrt{N}}\sqrt{\frac{1}{n}\sum_{i=m+1}^{m+n}\rbr{f^*(x_i,z_i^*,a_i)-f^*(x_i,\Tilde{z}_i,a_i)}^2}\sqrt{\frac{1}{N}\sum_{i=1}^{N}\rbr{\hat{f}(x_i,\tilde{z}_i,a_i)-f^*(x_i,\Tilde{z}_i,a_i)}^2}.
    \end{align*}
Define the empirical process $Z_N(t):=\sup_{||f-f^*||_2\le t}\abr{||f-f^*||_N^2-||f-f^*||_2^2}$. We define $H_f(x,z,a)$ as $(f(x,z,a)-f^*(x,z,a))^2$ and $\cH(t):=\cbr{H_f:f\in\cF,||f-f^*||_2\le t}$. We then apply \cref{thm: sup_empirical_process} to get
\[
Z_N(t)\le 2\EE[Z_N(t)]+\sqrt{\sigma^2(\cH(t))}\sqrt{\frac{2\log(1/\delta)}{N}}+\frac{16\log(1/\delta)}{N}.
\]
Similar to \cref{lemma:bound_K_1}, we have
\[
\EE[Z_N(t)]\le 2\EE\sbr{\sup_{||f^*-f||_2\le t}\abr{\frac{1}{N}\sum_{i=1}^{N}\varepsilon_i\rbr{f^*(x_i,\Tilde{z}_i,a_i)-f(x_i,\Tilde{z}_i,a_i)}^2}}\le 8\cR_N(t,\cF)\le \frac{r_Nt}{2},
\]
and
\[
\sigma^2(\cH(t))\le 4t^2.
\]
Applying the peeling argument again, we have that with probability $1-\delta$,
\[
Z_N(||\hat{f}-f^*||_2^2)\le 2r_N||\hat{f}-f^*||_2+8\sqrt{\frac{2\log(\varphi_{\lambda}r_N)/\delta)}{N}}||\hat{f}-f^*||_2+32\frac{\log(\varphi_{\lambda}r_N)/\delta)}{N}.
\]
By construction, $\abr{||\hat{f}-f^*||_N^2-||\hat{f}-f^*||_2^2}\le Z_N(||\hat{f}-f^*||_2^2)$. Moreover, we have
\begin{align*}
    \abr{||\hat{f}-f^*||_2-||\hat{f}-f^*||_N}=\frac{\abr{||\hat{f}-f^*||_2^2-||\hat{f}-f^*||_N^2}}{||\hat{f}-f^*||_2+||\hat{f}-f^*||_N}\le \frac{\abr{||\hat{f}-f^*||_2^2-||\hat{f}-f^*||_N^2}}{||\hat{f}-f^*||_2}.
\end{align*}
Using this bound, we have
\begin{align*}
    \abr{||\hat{f}-f^*||_2-||\hat{f}-f^*||_N}\le 2r_N+8\sqrt{\frac{2\log(\varphi_{\lambda}r_N)/\delta)}{N}}+32\frac{\log(\varphi_{\lambda}r_N)/\delta)}{||\hat{f}-f^*||_2 N}
\end{align*}
Because we condition on that $||\hat{f}-f^*||_2\ge r_N$, then
\[
\frac{\log(\varphi_{\lambda}r_N)/\delta)}{||\hat{f}-f^*||_2 N}\le \frac{\log(\varphi_{\lambda}r_N)/\delta)}{r_N N}.
\]
Therefore, we have with probability $1-\delta$,
\[
||\hat{f}-f^*||_N\le ||\hat{f}-f^*||_2+2r_N+8\sqrt{\frac{2\log(\varphi_{\lambda}r_N)/\delta)}{N}}+32\frac{\log(\varphi_{\lambda}r_N)/\delta)}{r_N N}.
\]
For the term $\sqrt{\frac{1}{n}\sum_{i=m+1}^{m+n}\rbr{f^*(x_i,z_i^*,a_i)-f^*(x_i,\Tilde{z}_i,a_i)}^2}$, notice that
\[
|\sqrt{x}-\sqrt{y}|=\abr{\frac{x-y}{\sqrt{x}+\sqrt{y}}}\le \abr{\frac{x-y}{\sqrt{y}}}\ \text{for}\ x,y>0.
\]
By \cref{lemma:Hoeffding_Lipschitz}, we have that with probability at least $1-\delta$,
\[
\abr{\frac{1}{n}\sum_{i=m+1}^{m+n}\rbr{f^*(x_i,z_i^*,a_i)-f^*(x_i,\Tilde{z}_i,a_i)}^2-\EE[\rbr{f^*(x,z^*,a)-f^*(x,\Tilde{g}(x),a)}^2]}\le 4\sqrt{\frac{\log(2/\delta)}{n}}.
\]
Therefore, we have that with probability at least $1-\delta$,
\begin{align*}
&\sqrt{\frac{1}{n}\sum_{i=m+1}^{m+n}\rbr{f^*(x_i,z_i^*,a_i)-f^*(x_i,\Tilde{z}_i,a_i)}^2}\\
\le& \sqrt{\EE[\rbr{f^*(x,z^*,a)-f^*(x,\Tilde{g}(x),a)}^2]}+\frac{4}{\sqrt{\EE[\rbr{f^*(x,z^*,a)-f^*(x,\Tilde{g}(x),a)}^2]}}\sqrt{\frac{\log(2/\delta)}{n}}\\
\le &\rbr{\sqrt{\cE^{\cF}_{\PP}(\tilde{g})}+\frac{4}{\upsilon(f^*,\PP,\tilde{g})^{1/2}}\sqrt{\frac{\log(2/\delta)}{n}}}.
\end{align*}
Thus, we get that with probability at least $1-\delta$,
\[
\frac{K_3}{2}\le \rbr{\sqrt{\cE^{\cF}_{\PP}(\tilde{g})}+\frac{4}{\upsilon(f^*,\PP,\tilde{g})^{1/2}}\sqrt{\frac{\log(2/\delta)}{N}}}\rbr{||\hat{f}-f^*||_2+2r_N+8\sqrt{\frac{2\log(\varphi_{\lambda}r_N)/\delta)}{N}}+32\frac{\log(\varphi_{\lambda}r_N)/\delta)}{r_N N}}.
\]
So we finish the proof
\end{proof}
