Now we are ready to prove \cref{thm:erm_oracle_ineq}.
\begin{proof}[Proof of \cref{thm:erm_oracle_ineq}]


Define $$A_N=\rbr{\max\cbr{4,\lambda}r_N+\max\cbr{16,4\lambda}\sqrt{\frac{2\log(\varphi_{\lambda}r_N)/\delta)}{N}}+\frac{64\log(\varphi_{\lambda}r_N)/\delta)}{r_NN}}.$$
From \cref{lemma:bound_K_1}, \cref{lemma:bound K_2} and \cref{lemma:bound_K_3}, with probability at least $1-4\delta$, we either have $||\hat{f}-f^*||_2\le r_N$ or
\begin{align*}
||f^*-\hat{f}||_2^2\le& ||\hat{f}-f^*||_2\rbr{2A_N+2\sqrt{\cE_{\PP}^{\cF}(\tilde{g})}+\frac{8}{\sqrt{\upsilon(f^*,\PP,\tilde{g})}}\sqrt{\frac{\log(2/\delta)}{N}}}\\
+&\rbr{\sqrt{\cE_{\PP}^{\cF}(\tilde{g})}+\frac{4}{\upsilon(f^*,\PP,\tilde{g})^{1/2}}\sqrt{\frac{\log(2/\delta)}{N}}}A_N.
\end{align*}
Rearranging the terms, we have
\begin{align*}
&\rbr{||\hat{f}-f^*||_2-\rbr{A_N+\sqrt{\cE_{\PP}^{\cF}(\tilde{g})}+\frac{4}{\upsilon(f^*,\PP,\tilde{g})^{1/2}}\sqrt{\frac{\log(2/\delta)}{N}}}}^2\\
\le& \rbr{\sqrt{\cE_{\PP}^{\cF}(\tilde{g})}+\frac{4}{\upsilon(f^*,\PP,\tilde{g})^{1/2}}\sqrt{\frac{\log(2/\delta)}{N}}}A_N+\rbr{A_N+\sqrt{\cE_{\PP}^{\cF}(\tilde{g})}+\frac{4}{\upsilon(f^*,\PP,\tilde{g})^{1/2}}\sqrt{\frac{\log(2/\delta)}{N}}}^2\\
\le& \frac{5}{4}\rbr{A_N+\sqrt{\cE_{\PP}^{\cF}(\tilde{g})}+\frac{4}{\upsilon(f^*,\PP,\tilde{g})^{1/2}}\sqrt{\frac{\log(2/\delta)}{N}}}^2.
\end{align*}
Therefore, for any $\delta>0$, with probability at least $1-4\delta$,
\begin{align*}
    ||\hat{f}-f^*||_2\le \rbr{1+\frac{\sqrt{5}}{2}}\rbr{A_N+\sqrt{\cE_{\PP}^{\cF}(\tilde{g})}+\frac{4}{\upsilon(f^*,\PP,\tilde{g})^{1/2}}\sqrt{\frac{\log(2/\delta)}{N}}}+r_N.
\end{align*}
Plugging in the definition of $A_N$, we shall finish the proof.
