\end{proof}
Now, we are ready to prove the statistical regret guarantee in \cref{thm:regret}. To do that, we first introduce the following lemma from \citet{simchi2020bypassing} to transform statistical guarantees of regression oracles to regret guarantees of decision-making algorithms.
\begin{lemma}\citep{simchi2020bypassing}\label{lemma:general_guarantee_IGW}
Assume that we are given an offline regression oracle $\mathsf{RegOff}$ and i.i.d. data $\cD=\cbr{(x_i,a_i,r_i)}_{i=1}^{n}$ where $\EE[r_i|x_i,a_i]=f^*(x_i,a_i)$. With probability at least $1-\delta$, it returns
    $\hat{f}:\cX\times\cA\rightarrow \RR$ such that
    $$\EE_{x,a}\sbr{\rbr{\hat{f}(x,a)-f^*(x,a)}^2}\le\mathsf{Est}_{\delta}(n)$$
for some number $\mathsf{Est}_{\delta}(n)$. Then, define epoch schedule $\beta_s=2^s$ and exploration parameter $\gamma_s=\frac{1}{2}\sqrt{\frac{K}{\mathsf{Est}_{\delta/2s^2}(\beta_{s-1}-\beta_{s-2})}}$. For any $t$, let $s(t)$ be the number of epochs that round $t$ lies in. For any $T$ large enough, with probability at least $1-\delta$, the regret of applying the inverse gap weighting policy after $T$ rounds is at most 
$$\cO\rbr{\sqrt{K}\sum_{s=2}^{s(T)}\sqrt{\mathsf{Est}_{\delta/(2s^2)}(\beta_{s-1}-\beta_{s-2})}(\beta_s-\beta_{s-1})}.$$
\end{lemma}
\begin{proof}[Proof of \cref{thm:regret}]
We would like to apply \cref{lemma:general_guarantee_IGW}, so we first specify the number $\sqrt{\mathsf{Est}_{\delta}(n)}$ in our algorithm. By \cref{thm:erm_oracle_ineq}, we have
\[
\sqrt{\mathsf{Est}_{\delta}}(n)=C(\lambda,\upsilon(f^*,\PP,\tilde{g}))\rbr{r_n+\sqrt{\cE^{\cF}_{\PP}(\tilde{g})}+\sqrt{\frac{\log(4\varphi_{\lambda}(r_n)/\delta)}{n}}+\sqrt{\frac{\log(8/\delta)}{n}}+\frac{\log(\varphi_{\lambda}(r_n)/\delta)}{r_nn}}.
\]
Plugging this bound in, we have that
\begin{align*}
    \text{Reg}(T)\lesssim & \sqrt{K}\lbrace\sum_{s=2}^{s(T)}r_{\beta_{s-1}-\beta_{s-2}}(\beta_s-\beta_{s-1})+\sqrt{\log(4s^2\varphi_{\lambda}(r_{\beta_{s-1}-\beta_{s-2}})/\delta)+\log(8s^2/\delta)}\frac{\beta_s-\beta_{s-1}}{\sqrt{\beta_{s-1}-\beta_{s-2}}}\\
    &+\sum_{s=2}^{s(T)}\log(s^2\varphi_{\lambda}(4r_{\beta_{s-1}-\beta_{s-2}})/\delta)\frac{\beta_{s}-\beta_{s-1}}{r_{\beta_{s-1}-\beta_{s-2}}(\beta_{s-1}-\beta_{s-2})}+\sqrt{\cE^{\cF}_{\PP}(\tilde{g})}T\rbrace.
\end{align*}
Recall that we set $\beta_{s}=2^{s}$ in \cref{thm:regret}, then we have that
\begin{align*}
    \text{Reg}(T)\lesssim& \sqrt{K}\Big\lbrace\sum_{s=2}^{s(T)}r_{2^{s-2}}2^{s-1}+\sum_{s=2}^{s(T)}\sqrt{\log(4s^2\varphi_{\lambda}(r_{2^{s-2}})/\delta)+\log(8s^2/\delta)}2^{\frac{s}{2}}\\
    +&\sum_{s=2}^{s(T)}\log(\varphi_{\lambda}(4r_{2^{s-2}})/\delta)\frac{2}{r_{2^{s-2}}}+\sqrt{\cE^{\cF}_{\PP}(\tilde{g})}T\Big\rbrace.
\end{align*}
Thus, we finish the proof.
\end{proof}
\section{Proofs in \cref{sec:model_calibration}}
\begin{lemma}\label{lemma:hat{e}_estimation}
    Denote $s_N$ as the critical radius of the function class $\cT$ with dataset cardinality $N$, then for any $\delta\in(0,1)$, with probability at least $1-\delta$, our calibration procedure $\cref{alg:calibration_procedure}$ outputs $\hat{e}$ that satisfies
    \[
    ||\hat{e}-e^*||_2\le \frac{5}{2}s_{N/2}+10\sqrt{\frac{2\log(\varphi_2(s_{N/2})/\delta)}{N/2}},
    \]
    where $\varphi_2(s_{N/2})=\log_2(\frac{4}{s_{N/2}})$ as pre-specified in \cref{subsec:ERM Oracle Inequality with Imputation}.
\end{lemma}
\begin{proof}[Proof of \cref{lemma:hat{e}_estimation}]
    We first elaborate on the estimation of $\hat{e}$. Note that $$||\hat{e}-e^*||_2^2=||\hat{e}-e^*||_2^2-||\hat{e}-e^*||_{N/2}^2+||\hat{e}-e^*||_{N/2}^2.$$ 
We define the local Rademacher complexity of $\cT$ as $\cR_{N/2}(t,\cT)$ and the critical radius of $\cT$ as $s_{N/2}$.  

For the term $||\hat{e}-e^*||_2^2-||\hat{e}-e^*||_{N/2}^2$, we could apply \cref{thm: sup_empirical_process} by defining $H_{e}(x):=(e(x)-e^*(x))^2-||e-e^*||_2^2$ and $\cH(t):=\cbr{H_e(x):e\in\cT, ||e-e^*||_2\le t}$. We also define $$Z_{N/2}(t):=\sup_{e\in\cH(t)}\cbr{\PP_{N/2}(H_{e})-\PP(H_{e})}.$$ Then with probability at least $1-\delta$, we have
\[
Z_{N/2}(t)\le 2\EE[Z_{N/2}(t)]+\sqrt{\sigma^2(\cH(t))}\sqrt{\frac{2\log(1/\delta)}{N/2}}+2\frac{\log(1/\delta)}{N/2}.
\]
We first have $\sigma^2(\cH(t))\le \PP((e-e^*)^4)\le 4t^2$. For $\EE[Z_{N/2}(t)]$, we have
\[
\EE[Z_{N/2}(t)]=\EE\sbr{\sup_{||e^*-e||_2\le t}\abr{||e^*-e||_{N/2}^2-||e-e^*||_2^2}}\le 2\EE\sbr{\sup_{||e^*-e||_2\le t}\abr{\frac{2}{N}\sum_{i=1}^{N/2}\varepsilon_i\rbr{e^*(x_i)-e(x_i)^2}}}.
    \]
    By \cref{lemma:Ledoux_Talagrand}, the function $\phi_i(t)=\phi(t)=t^2$ is $2$-Lipschitz on the interval $[0,1]$, we have
    \begin{align*}\hspace{-0.6cm}
    2\EE\sbr{\sup_{||e^*-e||_2\le t}\abr{\frac{2}{N}\sum_{i=1}^{N/2}\varepsilon_i\rbr{e^*(x_i)-e(x_i)}^2}}\le 4\EE\sbr{\sup_{||e^*-e||_2\le t}\abr{\frac{2}{N}\sum_{i=1}^{N/2}\varepsilon_i\rbr{e^*(x_i)-e(x_i)}}}=4\cR_{N/2}(t,\cT).
    \end{align*}
    By definition, we have $\cR_{N/2}(t,\cT)\le\frac{t}{16}s_{N/2}$.
    Plugging all these in, we get with probability at least $1-\delta$,
    \[
    Z_{N/2}(t)\le \frac{s_{N/2}}{2}t+4\sqrt{\frac{2\log(1/\delta)}{N/2}}t+\frac{2\log(1/\delta)}{N/2}.
    \]
Apply the peeling argument in \cref{lemma:peeling}, we further have that with probability at least $1-\delta$,
\[
Z_n(||\hat{e}-e^*||_2)\le s_{N/2}||\hat{e}-e^*||_2+8\sqrt{\frac{2\log(\varphi_{2}(s_{N/2})/\delta)}{N/2}}||\hat{e}-e^*||_2+4\frac{\log(\varphi_{2}(s_{N/2})/\delta)}{n}.
\]
For the second term $||\hat{e}-e^*||_{N/2}^2$, conditioned on $||\hat{e}-e^*||_2\ge s_{N/2}$, we first apply the property of the ERM to get
\[
||\hat{e}-e^*||_{N/2}^2\le \frac{4}{N}\sum_{i=1}^{N/2}(b_i-e^*(x_i))(\hat{e}(x_i)-e^*(x_i)).
\]
Conditioned on $||\hat{e}-e^*||\ge s_{N/2}$, we define the empirical process 
\[
W_{N/2}(t):=\sup_{||e-e^*||_2\le t}\abr{\frac{2}{N}\sum_{i=1}^{N/2}(b_i-e^*(x_i))(\hat{e}(x_i)-e^*(x_i))}
\]
Denote $b_i-e^*(x_i)$ as $r_i$ and define the function class $\cH(t):=\cbr{r(e-e^*):e\in\cT,||e-e^*||_2\le t}$. Then we apply \cref{thm: sup_empirical_process} to get that with probability at least $1-\delta$,
\[
W_{N/2}(t)\le 2\EE[W_{N/2}(t)]+\sqrt{\sigma^2(\cH(t))}\sqrt{\frac{2\log(1/\delta)}{N/2}}+2\frac{\log(1/\delta)}{N/2}
\]
Similarly, we have $\sigma^2(\cH(t))\le t^2$ and 
\[
\EE[W_{N/2}(t)]\le 2\cR_{N/2}(t,\cT).
\]
By definition, for $t\ge s_{N/2}$, we have $\cR_{N/2}(t,\cT)\le \frac{s_{N/2}}{16}$. Then with probability at least $1-\delta$,
\[
W_{N/2}(t)\le \frac{s_{N/2}}{4}t+\sqrt{\frac{2\log(1/\delta)}{N/2}}t+\frac{2\log(1/\delta)}{N/2}.
\]
By the peeling argument again, we have with probability at least $1-\delta$,
\[
W_{N/2}(||\hat{e}-e^*||_2)\le \frac{s_{N/2}}{2}||\hat{e}-e^*||_2+2\sqrt{\frac{2\log(\varphi_2(s_{N/2})/\delta)}{n}}||\hat{e}-e^*||_2+\frac{4\log(\varphi_2(s_{N/2})/\delta)}{N/2}.
\]
Now we are ready to prove the bound, by construction, we either have $||e^*-\hat{e}||_2\le s_{N/2}$ or with probability $1-\delta$,
\[
||\hat{e}-e^*||_2^2\le ||\hat{e}-e^*||_2\rbr{\frac{3}{2}s_{N/2}+10\sqrt{\frac{2\log(\varphi_2(s_{N/2})/\delta)}{N/2}}}+6\frac{\log(\varphi_2(s_{N/2})/\delta)}{N/2}.
\]
Thus, with probability at least $1-\delta$,
\[
||\hat{e}-e^*||_2\le \frac{5}{2}s_{N/2}+10\sqrt{\frac{4\log(\varphi_2(s_{N/2})/\delta)}{N}}.
\]
\end{proof}
