In $\cD_{s-1}$, $\tilde{z}_t$ is generated by $\hat{g}_{s-1}$ which is trained by the calibration procedure $\Cal$ on the dataset $\cD_{s-2}$ from epoch $s-2$. Therefore, combining \cref{thm:erm_oracle_ineq} and \cref{thm:calibration_guarantee}, we have that for any $\delta\in(0,1)$, with probability at least $1-3\delta$,
\begin{align*}
    ||\hat{f}_{s}-f^*||_2\le &C(\lambda,\upsilon(f^*,\PP,\tilde{g}))\rbr{r_{2^{s-2}}+\sqrt{\cE^{\cF}_{\PP}(\hat{g}_{s-1})}+\sqrt{\frac{\log(4\varphi_{\lambda}(r_{2^{s-2}})/\delta)}{2^{s-2}}}+\sqrt{\frac{\log(8/\delta)}{2^{s-2}}}+\frac{\log(\varphi_{\lambda}(r_{2^{s-2}})/\delta)}{r_{2^{s-2}}2^{s-2}}}\\
    \lesssim & C(\lambda,\upsilon(f^*,\PP,\tilde{g}))\rbr{r_{2^{s-2}}+\sqrt{\frac{\log(4\varphi_{\lambda}(r_{2^{s-2}})/\delta)}{2^{s-2}}}+\sqrt{\frac{\log(8/\delta)}{2^{s-2}}}+\frac{\log(\varphi_{\lambda}(r_{2^{s-2}})/\delta)}{r_{2^{s-2}}2^{s-2}}}\\
    +&L_{\cZ}||\hat{g}_{s-1}-g^*||_2+L_{\cZ}\EE[\eta^2]^{\frac{1}{2}}\\
    \lesssim & C(\lambda,\upsilon(f^*,\PP,\tilde{g}))\rbr{r_{2^{s-2}}+\sqrt{\frac{\log(4\varphi_{\lambda}(r_{2^{s-2}})/\delta)}{2^{s-2}}}+\sqrt{\frac{\log(8/\delta)}{2^{s-2}}}+\frac{\log(\varphi_{\lambda}(r_{2^{s-2}})/\delta)}{r_{2^{s-2}}2^{s-2}}}\\
    +&L_{\cZ}\sqrt{\frac{1}{\epsilon_0^2}\rbr{\delta_0^{\frac{2d}{d+2}}N^{\frac{-2}{d+2}}+\frac{(1+\tau)^2\log(\varphi_{1+\tau}(q_{\delta_0,N/2})/\delta)}{N}+s_{N/2}^2+\frac{\log(\varphi_2(s_{N/2})/\delta)}{N}}}+L_{\cZ}\omega_0\\
    \lesssim & C(\lambda,\upsilon(f^*,\PP,\tilde{g}))\rbr{r_{2^{s-2}}+\sqrt{\frac{\log(4\varphi_{\lambda}(r_{2^{s-2}})/\delta)}{2^{s-2}}}+\sqrt{\frac{\log(8/\delta)}{2^{s-2}}}+\frac{\log(\varphi_{\lambda}(r_{2^{s-2}})/\delta)}{r_{2^{s-2}}2^{s-2}}}\\
    +&\frac{L_{\cZ}}{\epsilon_0}\rbr{\delta_0^{\frac{d}{d+2}}2^{\frac{-2(s-3)}{d+2}}+\frac{(1+\tau)\sqrt{\log(\varphi_{1+\tau}(q_{\delta_0,2^{s-3}})/\delta)}}{2^{s/2-2}}+s_{2^{s-3}}+\frac{\sqrt{\log(\varphi_2(s_{2^{s-3}})/\delta)}}{2^{s/2-2}}}+L_{\cZ}\omega_0.
\end{align*}
The first inequality is due to \cref{thm:erm_oracle_ineq}, and the second inequality is by the Lipschitz continuity of the reward model class in \cref{ass:calibration}. The third one is by \cref{thm:calibration_guarantee}, and the last one is simply algebra.
Combining this bound, \cref{lemma:general_guarantee_IGW} and \cref{thm:regret}, we have that with probability at least $1-3\delta$,
\begin{align*}
    \text{Reg}(T)\lesssim &\sqrt{K}\rbr{\sum_{s=2}^{s(T)}r_{2^{s-2}}2^{s-1}+\sum_{s=2}^{s(T)}\sqrt{\log(4\varphi_{\lambda}(r_{2^{s-2}})/\delta)+\log(8/\delta)}2^{\frac{s}{2}}+\sum_{s=2}^{s(T)}\log(\varphi_{\lambda}(4r_{2^{s-2}})/\delta)\frac{2}{r_{2^{s-2}}}}\\
    +&\sqrt{K}\sum_{s=2}^{s(T)}\frac{L_{\cZ}}{\epsilon_0}\rbr{\delta_0^{\frac{d}{d+2}}2^{\frac{-2(s-3)}{d+2}}+\frac{(1+\tau)\sqrt{\log(\varphi_{1+\tau}(q_{\delta_0,2^{s-3}})/\delta)}}{2^{s/2-2}}+s_{2^{s-3}}+\frac{\sqrt{\log(\varphi_2(s_{2^{s-3}})/\delta)}}{2^{s/2-2}}}2^{s-1}\\
    &+L_{\cZ}\omega_0 T\\
    \lesssim& \sqrt{K}\rbr{\sum_{s=2}^{s(T)}r_{2^{s-2}}2^{s-1}+\frac{L_{\cZ}}{\epsilon_0}\delta_0^{\frac{d}{d+2}}\sum_{s=2}^{s(T)}2^{\frac{-2(s-3)}{d+2}+s-1}+\frac{L_{\cZ}}{\epsilon_0}\sum_{s=2}^{s(T)}s_{2^{s-3}}2^{s-1}}+L_{\cZ}\omega_0T\\
    +&\sqrt{K}\rbr{\sum_{s=2}^{s(T)}\sqrt{\log(4\varphi_{\lambda}(r_{2^{s-2}})/\delta)+\log(8/\delta)}2^{\frac{s}{2}}+\sum_{s=2}^{s(T)}\log(\varphi_{\lambda}(4r_{2^{s-2}})/\delta)\frac{2}{r_{2^{s-2}}}}\\
    +&\frac{\sqrt{K}L_{\cZ}}{\epsilon_0}\rbr{\sqrt{(1+\tau)^2\log(\varphi_{1+\tau}(q_{\delta_0,2^{s-3}})/\delta)+\log(\varphi_2(s_{2^{s-3}})/\delta)}}2^{s/2}.
\end{align*}
So we finish the proof.
\end{proof}
