        \foreach \j in {1,...,5} {
            \filldraw ({\j*\gap*cos(360/\n*\i)}, {\j*\gap*sin(360/\n*\i)}) circle (0.5pt);
        }
        % Draw the arm line
        \draw[gray, thick, ->] (0,0) -- ({(\m+0.5)*\gap*cos(360/\n*\i)}, {(\m+0.5)*\gap*sin(360/\n*\i)});
