         &=  - \mathscr{Z}_t  \frac{B_t^f}{B_t^r}\sum_{i=1}^d Z_t^i\frac{\mu^i(t,S_t)-r_t^i}{\sigma^{i}(t,S_t)} dt + d \left \langle  \int_0^{\cdot} \frac{1}{B_u^r} dA_u^{R,C}, \mathscr{Z}_{\cdot} \right \rangle_t, \nonumber \\
         &=  - \mathscr{Z}_t \frac{B_t^f}{B_t^r} \sum_{i=1}^d Z_t^i\frac{\mu^i(t,S_t)-r_t^i}{\sigma^{i}(t,S_t)} dt + d \left \langle  \int_0^{\cdot} \frac{1}{B_u^r} dA_u + \int_0^{\cdot} \frac{1}{B_u^r} dC_u -\int_0^{\cdot} \frac{1}{B_u^r}\bar{r}_u^c C_u du   , \mathscr{Z}_{\cdot} \right \rangle_t \nonumber\\
