        &=\int_t^{\tau \wedge T} \mathscr{Z}_u\left(\frac{B_u^f}{B_u^r} \sum_{i=1}^d    Z_u^i dW_u^{f,i}+ \frac{B_u^f}{B_u^r}dH_u^{\mathcal{L}}+ \frac{1}{B_u^r}dA_u^{R,C}+ \left( r_u^f-r_u\right)\frac{{V}_u^p(\varphi, A^{R,C})}{B_u^r}du\right)  \nonumber \\
        & \quad +  \int_t^{\tau \wedge T} \widehat{V}_u^p(\varphi, A^{R,C})\mathscr{Z}_u\left( \sum_{i=1}^d -\frac{\mu^i(u,S_u)-r_u^i}{\sigma^{i}(u,S_u)} dW_u^{f,i}\right) + \int_t^{\tau \wedge T} \frac{1}{B_u^r}d \langle C, \mathscr{Z}\rangle_u. \nonumber 
