    By taking the conditional expectation under $\mathbb{P}$ w.r.t. $\mathcal{G}_t$ for $t < \tau$ we have
    \begin{align}
   \widehat{V}_t^p(\varphi, A^{R,C})&= \frac{1}{\mathscr{Z}_t} \mathbb{E}_{\mathbb{P}}\left[ \left(\frac{C_T}{B_T^r} \textbf{1}_{\lbrace \tau >T \rbrace}- \frac{R_{\tau}}{B_{\tau}^r}\textbf{1}_{\lbrace \tau \leq T \rbrace}\right) \mathscr{Z}_{\tau \wedge T} \Big \vert \mathcal{G}_t\right] \nonumber \\
   & \quad - \frac{1}{\mathscr{Z}_t} {\mathbb{E}_{\mathbb{P}}\left[  \int_t^{\tau \wedge T} \mathscr{Z}_u\left( \frac{B_u^f}{B_u^r}\sum_{i=1}^d    Z_u^i dW_u^{f,i}\right)\Big \vert \mathcal{G}_t\right]} - \frac{1}{\mathscr{Z}_t} {\mathbb{E}_{\mathbb{P}}\left[  \int_t^{\tau \wedge T} \frac{B_u^f}{B_u^r}\mathscr{Z}_udH_u^{\mathcal{L}} \Big \vert \mathcal{G}_t\right]} \nonumber \\
   & \quad -\frac{1}{\mathscr{Z}_t} {\mathbb{E}_{\mathbb{P}}\left[ \int_t^{\tau \wedge T}  \mathscr{Z}_u \left( \frac{1}{B_u^r} dA_u^{R,C}+ \left( r_u^f-r_u\right)\frac{{V}_u^p(\varphi, A^{R,C})}{B_u^r}du \right)\Big \vert \mathcal{G}_t\right]} \nonumber \\
    & \quad -\frac{1}{\mathscr{Z}_t} {\mathbb{E}_{\mathbb{P}}\left[ \int_t^{\tau \wedge T} \widehat{V}_u^p(\varphi, A^{R,C})\mathscr{Z}_u\left( \sum_{i=1}^d -\frac{\mu^i(u,S_u)-r_u^i}{\sigma^{i}(u,S_u)} dW_u^{f,i} \right)\Big \vert \mathcal{G}_t\right]} \nonumber \\
    & \quad -  \frac{1}{\mathscr{Z}_t} {\mathbb{E}_{\mathbb{P}}\left[ \int_t^{\tau \wedge T} \frac{1}{B_u^r} d \langle C, \mathscr{Z}\rangle_u\Big \vert \mathcal{G}_t\right].} \label{eq:ConditionalExpectations}
    \end{align}
  We define the following processes by
  \begin{align}
    \mathscr{M}^{1,i}_t&:= \int_0^{t}  \frac{B_u^f}{B_u^r}\mathscr{Z}_u  Z_u^i dW_u^{f,i}, \quad \quad \mathscr{M}^{2}_t:=\int_0^{t}  \frac{B_u^f}{B_u^r} \mathscr{Z}_u d\mathcal{H}_u^{\mathcal{L}},\quad i=1,...,d, \, t \in [0, T], \nonumber  \\
     \mathscr{M}^{3,i}_t&:=\int_0^{t} -\widehat{V}_u^p(\varphi, A^{R,C})\mathscr{Z}_u\frac{\mu^i(u,S_u)-r_u^i}{\sigma^{i}(u,S_u)} dW_u^{\tau,f,i} , \quad i=1,...,d, \, t \in [0, T], \nonumber
  \end{align}
    and prove that they are martingales.
 To do so, we apply Theorem I.51 in \cite{protter}, i.e. we show that $\mathscr{M}$ for $\mathscr{M}\in \lbrace \mathscr{M}^{1,i},\mathscr{M}^{2}, \mathscr{M}^{3,i}\rbrace$ with $i=1,...,d$ is a local $(\mathbb{G}, \mathbb{P})$-martingale which satisfies
