    \int_{0}^T \left \vert  \frac{B_u^f}{B_u^r} \mathscr{Z}_u  Z_u^i \right \vert^2 du \leq T\sup_{t \in[0,T]} \left \vert Z_t^i \right \vert^2 \sup_{t\in[0,T]} \left \vert \mathscr{Z}_t \right \vert^2 \sup_{t \in [0,T]} \left \vert  \frac{B_t^f}{B_t^r}\right \vert^2  < \infty \quad \mathbb{P}\text{-a.s.}, 
  \end{align*}
  as $Z \in \mathcal{H}^{2,d}(\mathbb{G}, \mathbb{P})$, by \eqref{eq:BoundsInterestRates} and by Doob's maximum inequality it follows from \eqref{eq:SecondMoment}
\begin{align}\label{eq:Doob}
\mathbb{E}_{\mathbb{P}}\left[ \sup_{t \in[0,T]}\vert \mathscr{Z}_t \vert^2\right] \leq \left(\frac{2}{2-1}\right)^2 \mathbb{E}_{\mathbb{P}}\left[ \vert \mathscr{Z}_T \vert^2\right]< \infty.
\end{align} 
Thus, $\mathscr{M}^{1,i}$ is a local $(\mathbb{G}, \mathbb{P})$-martingale.
  Furthermore, it holds
  \begin{align}
