    & \leq K T \mathbb{E}_{\mathbb{P}}\left[  \sup_{t \in [0,T]} \left \vert Z_t^i \right\vert  \sup_{t \in [0,T]} \left \vert \mathscr{Z}_t \right\vert \sup_{t \in [0,T]} \left \vert  \frac{B_t^f}{B_t^r}\right \vert  \right] \nonumber \\
     & \leq K C(K_r) T \mathbb{E}_{\mathbb{P}}\left[  \sup_{t \in [0,T]} \left \vert Z_t^i \right \vert^2 \right]^{\frac{1}{2}} \mathbb{E}_{\mathbb{P}}\left[  \sup_{t \in [0,T]} \left \vert \mathscr{Z}_t \right \vert^2 \right]^{\frac{1}{2}}  \label{eq:Cauchy}  \\
     &< \infty,\label{eq:SecondMomentBound}
  \end{align}
  where we use in \eqref{eq:Burkholder-Davis-Gundy} the Burkholder-Davis-Gundy inequality with a suitable constant $K$. We get \eqref{eq:Cauchy} by the Cauchy-Schwarz inequality. Moreover, \eqref{eq:SecondMomentBound} follows by \eqref{eq:Doob} and $Z \in \mathcal{H}^{2,d}(\mathbb{G}, \mathbb{P})$ .
  Note that 
    \begin{align*}
        \mathscr{M}^{2}_t&=\int_0^{t} \frac{B_u^f}{B_u^r}\mathscr{Z}_u d\mathcal{H}_u^{\mathcal{L}}= \sum_{j \in \lbrace B,C \rbrace} \int_0^t  \frac{B_u^f}{B_u^r}\mathscr{Z}_u U_u^j dM^j_u,
  \end{align*}
  and $[ M^j ]_u= H_u^j=\textbf{1}_{\lbrace \tau^j \leq u\rbrace}$. Thus, we get for $j \in \lbrace{ B, C \rbrace}$
    \begin{align*}
        \int_0^T  \left \vert  \frac{B_u^f}{B_u^r} \mathscr{Z}_u U_u^j\right \vert^2 d [ M^j ]_u&= \int_0^T  \left \vert  \frac{B_u^f}{B_u^r} \mathscr{Z}_u U_u^j\right \vert^2 d\textbf{1}_{\lbrace \tau^j \leq u\rbrace} \nonumber \\
        &= C(K_r)\left(\mathscr{Z}_{\tau^j} U_{\tau^j}^j\right)^2  \textbf{1}_{\lbrace \tau^j \leq T\rbrace} < \infty \quad \mathbb{P}\text{-a.s.}
    \end{align*}
    and 
    \begin{align}
        \mathbb{E}_{\mathbb{P}} \left[\sup_{t \in [0,T]} \left \vert  \int_0^t \frac{B_u^f}{B_u^r}\mathscr{Z}_u U_u^j dM^j_u \right \vert \right] &\leq K \mathbb{E}_{\mathbb{P}} \left[\left \vert  \int_0^T \left( \frac{B_u^f}{B_u^r}\mathscr{Z}_u U_u^j \right)^2 d[ M^j]_u \right \vert^{\frac{1}{2}} \right] \nonumber \\
        &= K \mathbb{E}_{\mathbb{P}} \left[ \frac{B_{\tau^j}^f}{B_{\tau^j}^r}\mathscr{Z}_{\tau^j} U_{\tau^j}^j \textbf{1}_{\lbrace \tau^j \leq T\rbrace} \right] \nonumber \\
        & \leq KC(K_r) \mathbb{E}_{\mathbb{P}} \left[ \mathscr{Z}_{\tau^j}^2  \textbf{1}_{\lbrace \tau^j \leq T\rbrace} \right]^{\frac{1}{2}}\mathbb{E}_{\mathbb{P}} \left[ (U_{\tau^j}^j)^2  \textbf{1}_{\lbrace \tau^j \leq T\rbrace} \right]^{\frac{1}{2}}< \infty, \nonumber
    \end{align}
    by \eqref{eq:Doob} and $U \in \mathcal{H}_{\lambda}^{2,2}(\mathbb{G},\mathbb{P}).$

 It remains to prove that $\mathscr{M}^{3,i}$ is a $(\mathbb{G}, \mathbb{P})$-martingale. For $i=1,...,d$ we have
  \begin{align}
  &\int_0^{\tau \wedge T}\left \vert \widehat{V}_u^p(\varphi, A^{R,C})\mathscr{Z}_u\frac{\mu^i(u,S_u)-r_u^i}{\sigma^{i}(u,S_u)}\right \vert ^2 du \nonumber \\
  &\leq  K_i^2 \sup_{t \in [0,\tau \wedge T]} \vert \mathscr{Z}_t \vert^2    \int_0^{\tau \wedge T}\left \vert \widehat{V}_u^p(\varphi, A^{R,C})\right\vert^2 du \nonumber \\
  &\leq K_i^2 \sup_{t \in [0,T]} \vert \mathscr{Z}_t \vert^2  \left(  2\int_0^{\tau \wedge T}\left \vert \frac{\psi_u^f B^f_u}{B_u^r} \right\vert^2 du + 2\int_0^{\tau \wedge T}\left \vert \frac{C_u}{B_u^r}  \right\vert^2 du \right)\label{eq:DefinitionValueProcess1} \\
   &\leq K_i^2 \sup_{t \in [0,T]} \vert \mathscr{Z}_t \vert^2  \left(  2\int_0^{\tau \wedge T}\left \vert \frac{ B^f_u}{B_u^r} \right \vert^2 \left \vert Y_u + \int_{0}^u \frac{1}{B_s^f} d A^{R,C} _s\right\vert^2 du + 2 T \sup_{t \in[0,T]} \left \vert C_t \right \vert^2 \sup_{t \in[0,T]} \left \vert \frac{1}{B_t^r} \right \vert^2   \right)\label{eq:RepresentationBSDE}  \\
    &\leq K_i^2 C(K_r) \sup_{t \in [0,T]}  \vert \mathscr{Z}_t \vert^2  \left(\sup_{t \in [0,T]}  \left(  4 T \sup_{t \in  [0,\tau \wedge T]}\left \vert Y_t \right \vert^2   + 4 \int_{0}^{\tau \wedge T} \left \vert \int_0^u \frac{1}{B_s^f} d A^{R,C}_s \right\vert^2 du\right) + 2 T \sup_{t \in[0,T]} \left \vert C_t \right \vert^2   \right)\label{eq:BoundedTreasuryAccountUse} \\
    % &= K_i^2 \sup_{t \in [0,T]} \vert \mathscr{Z}_t \vert^2  \left(  4 T \sup_{t \in  [0,T]}\left \vert Y_t \right \vert^2 + 4 \int_{0}^T \left \vert \int_0^u \frac{1}{B_s^f} d A^{R,C}_s \right\vert^2 du + 2 T \sup_{t \in[0,T]} \left \vert C_t \right \vert^2 \right)\nonumber \\
    & < \infty, \label{eq:MartingaleEstimates}
  \end{align}
  where we use in \eqref{eq:DefinitionValueProcess1} that 
  \begin{align}
    \widehat{V}_u^p(\varphi, A^{R,C})= \frac{ {V}_u^p(\varphi, A^{R,C})}{B_u^r} + \frac{C_u}{B_u^r}=\frac{\psi_u^f B_u^f}{B_u^r}+ \frac{C_u}{B_u^r}, \nonumber
  \end{align}
   and \eqref{eq:RepresentationBSDE} follows by Lemma \ref{lemma:DescriptionStrategyBSDE}. Finally, we conclude that \eqref{eq:MartingaleEstimates} holds by \eqref{eq:IntegrabilityCollateral}, \eqref{eq:Doob}, \eqref{eq:AdditionalAssumption1} and $Y \in \mathbb{S}^2(\mathbb{G}, \mathbb{P})$.
  With similar arguments we get for $i=1,...,d$
  \begin{align}
   & \mathbb{E}_{\mathbb{P}}\left[ \sup_{t \in [0, T]}  \left \vert \mathscr{M}_t^{3,i}  \right \vert \right] \nonumber \\
   &= \mathbb{E}_{\mathbb{P}}\left[ \sup_{t \in [0, T]} \left \vert \int_0^{t} \widehat{V}_u^p(\varphi, A^{R,C})\mathscr{Z}_u\frac{\mu^i(u,S_u)-r_u^i}{\sigma^{i}(u,S_u)} dW_u^{f,i}  \right \vert \right] \nonumber \\
   & \leq K K_i^2\mathbb{E}_{\mathbb{P}}\left[  \left \vert \int_0^{{\tau \wedge T}} \left \vert \widehat{V}_u^p(\varphi, A^{R,C})\mathscr{Z}_u \right \vert^2 d u \right \vert^{\frac{1}{2}} \right] \nonumber  \\
    & \leq K K_i^2\mathbb{E}_{\mathbb{P}}\left[ \sup_{t \in [0,T]} \vert \mathscr{Z}_t \vert  \left \vert \int_0^{{\tau \wedge T}} \left \vert \widehat{V}_u^p(\varphi, A^{R,C}) \right \vert^2 d u \right \vert^{\frac{1}{2}} \right]\nonumber \\
   & \leq K K_i^2\mathbb{E}_{\mathbb{P}}\left[ \sup_{t \in [0,T]} \vert \mathscr{Z}_t \vert^2 \right]  ^{\frac{1}{2}} \mathbb{E}_{\mathbb{P}}\left[  \int_0^{{\tau \wedge T}} \left \vert \widehat{V}_u^p(\varphi, A^{R,C}) \right \vert^2 d u  \right]^{\frac{1}{2}} \nonumber \\
   & \leq 4 K K_i^2 T C(K_r) \mathbb{E}_{\mathbb{P}}\left[ \sup_{t \in [0,T]} \vert \mathscr{Z}_t \vert^2 \right]^{\frac{1}{2}} \mathbb{E}_{\mathbb{P}}\left[ \sup_{t \in  [0,{\tau \wedge T}]}\left \vert Y_t  \right \vert^2 + \int_{0}^{{\tau \wedge T}} \left \vert \int_0^u \frac{1}{B_s^f} d A^{R,C}_s \right\vert^2 du +  \sup_{t \in[0,T]} \left \vert C_t \right \vert^2  \right]^{\frac{1}{2}}\nonumber \\
    & \leq 4 K K_i^2 T C(K_r) \mathbb{E}_{\mathbb{P}}\left[ \sup_{t \in [0,T]} \vert \mathscr{Z}_t \vert^2 \right]^{\frac{1}{2}} \Bigg (\mathbb{E}_{\mathbb{P}}\left[   \sup_{t \in  [0,{\tau \wedge T}]}\left \vert Y_t \right \vert^2 \right] + \mathbb{E}_{\mathbb{P}}\left[\int_{0}^{{\tau \wedge T}} \left \vert \int_0^u \frac{1}{B_s^f} d A^{R,C}_s \right\vert^2 du \right]\nonumber \\
    & \quad +\mathbb{E}_{\mathbb{P}}\left[ \sup_{t \in[0,T]} \left \vert C_t \right \vert^2  \right] \Bigg)^{\frac{1}{2}}\nonumber \\
    & \quad < \infty. \nonumber 
  \end{align}
  Thus, \eqref{eq:ConditionalExpectations} simplifies to 
   \begin{align}
  \widehat{V}_t^p(\varphi, A^{R,C})&= \widehat{V}_t^p(\varphi, {A}^{C})\nonumber \\
  &= \frac{1}{\mathscr{Z}_t} \mathbb{E}_{\mathbb{P}}\left[ \left(\frac{C_T}{B_T^r} \textbf{1}_{\lbrace \tau >T \rbrace}- \frac{R_{\tau}}{B_{\tau}^r}\textbf{1}_{\lbrace \tau \leq T \rbrace}\right) \mathscr{Z}_{\tau \wedge T} \Big \vert \mathcal{G}_t\right] -  \frac{1}{\mathscr{Z}_t} {\mathbb{E}_{\mathbb{P}}\left[ \int_t^{\tau \wedge T} \frac{1}{B_u^r} d \langle C, \mathscr{Z}\rangle_u\Big \vert \mathcal{G}_t\right]}\nonumber \\
  & \quad -\frac{1}{\mathscr{Z}_t} {\mathbb{E}_{\mathbb{P}}\left[ \int_t^{\tau \wedge T} \mathscr{Z}_u \left( \frac{1}{B_u^r} dA_u^{C}+ \left( r_u^f-r_u\right)\frac{{V}_u^p(\varphi, A^{C})}{B_u^r}du \right)\Big \vert \mathcal{G}_t\right]}, \label{eq:SplittingA}
   \end{align}
  where we use that on $\lbrace{t < \tau \rbrace}$ it holds $ \widehat{V}_t^p(\varphi, {A}^{C}) =\widehat{V}_t^p(\varphi, A^{R,C})$ as well as $A_t^{R,C}=A_t^C$.\\

  Next, we rewrite the term $\int_{t}^{\tau \wedge T} \mathscr{Z}_u\frac{1}{B_u^r}dA_u^{C}$. To simplify the notation we set 
  \begin{align*} 
\widetilde{A}_t:=  \textbf{1}_{\lbrace t < \tau  \rbrace} A_t +  \textbf{1}_{\lbrace t \geq \tau  \rbrace} A_{\tau-}, \quad \widetilde{C}_t:=\textbf{1}_{\lbrace t < \tau  \rbrace} C_t + \textbf{1}_{\lbrace t \geq \tau  \rbrace}C_{\tau-}, \quad t \in [0, \tau \wedge T],
    \end{align*}
    and thus by \eqref{eq:CashflowDefaultCollateralized} and \eqref{eq:CashflowDefaultCollateralized1} we have 
    \begin{align}\label{eq:CashflowAdjusted}
        {A}_t^C:=\widetilde{A}_t+\widetilde{C}_t-\int_0^t \bar{r}_u^c C_u du.
    \end{align} It holds
    \begin{align}
    \int_{t}^{\tau \wedge T} \frac{\mathscr{Z}_u}{B_u^r}d \widetilde{C}_u&=\frac{\mathscr{Z}_{\tau \wedge T}C_{\tau \wedge T}}{B_{\tau \wedge T}^r}-\frac{\mathscr{Z}_tC_t}{B_t^r}-\int_t^{\tau \wedge T} \mathscr{Z}_uC_u d(B_u^r)^{-1}- \int_t^{\tau \wedge T} \frac{C_u}{B_u^r} d\mathscr{Z}_u- \int_t^{\tau \wedge T} \frac{1}{B_u^r} d \langle C, \mathscr{Z} \rangle_u
    \label{eq:Ito1} \\
    &=\frac{\mathscr{Z}_{\tau \wedge T}C_{\tau \wedge T}}{B_{\tau \wedge T}^r}-\frac{\mathscr{Z}_tC_t}{B_t^r}+ \int_t^{\tau \wedge T} \frac{ \mathscr{Z}_u C_u r_u}{B_u^r} du- \int_t^{\tau \wedge T} \frac{C_u}{B_u^r} d\mathscr{Z}_u - \int_t^{\tau \wedge T} \frac{1}{B_u^r} d \langle C, \mathscr{Z} \rangle_u \label{eq:Ito2}, 
    \end{align} 
where we use in \eqref{eq:Ito1} that by It\^{o}'s formula
\begin{align*}
 d\frac{\mathscr{Z}_t C_t}{B_t^r}= \mathscr{Z}_t C_t d(B_t^r)^{-1}+ (B_t^r)^{-1} d(\mathscr{Z}_tC_t) = \mathscr{Z}_t C_t d(B_t^r)^{-1}+ (B_t^r)^{-1} (\mathscr{Z}_tdC_t+ C_t d\mathscr{Z}_t + {d \langle C,\mathscr{Z}  \rangle_t}). 
\end{align*}
Combining \eqref{eq:SplittingA}, \eqref{eq:CashflowAdjusted} and \eqref{eq:Ito2} yields
\begin{align}
 \widehat{V}_t^p(\varphi, {A}^{R,C})&= \frac{1}{\mathscr{Z}_t} \mathbb{E}_{\mathbb{P}}\left[ \left(\frac{C_T}{B_T^r} \textbf{1}_{\lbrace \tau >T \rbrace}- \frac{R_{\tau}}{B_{\tau}^r}\textbf{1}_{\lbrace \tau \leq T \rbrace}\right) \mathscr{Z}_{\tau \wedge T} \Big \vert \mathcal{G}_t\right] -  \frac{1}{\mathscr{Z}_t} {\mathbb{E}_{\mathbb{P}}\left[ \int_t^{\tau \wedge T} \frac{1}{B_u^r} d \langle C, \mathscr{Z}\rangle_u\Big \vert \mathcal{G}_t\right]}\nonumber \\
  & \quad -\frac{1}{\mathscr{Z}_t} {\mathbb{E}_{\mathbb{P}}\left[ \int_t^{\tau \wedge T} \mathscr{Z}_u \left( \frac{1}{B_u^r} d(\widetilde{A}_u+\widetilde{C}_u- \bar{r}_u^c C_u du)+ \left( r_u^f-r_u\right)\frac{{V}_u^p(\varphi, A^{C})}{B_u^r}du \right)\Big \vert \mathcal{G}_t\right]}, \nonumber \\
 &=\frac{1}{\mathscr{Z}_t} \mathbb{E}_{\mathbb{P}}\left[ \left(\frac{C_T}{B_T^r} \textbf{1}_{\lbrace \tau >T \rbrace}- \frac{R_{\tau}}{B_{\tau}^r}\textbf{1}_{\lbrace \tau \leq T \rbrace}\right) \mathscr{Z}_{\tau \wedge T} - \int_{t}^{\tau \wedge T} \frac{\mathscr{Z}_u}{B_u^r}d\widetilde{A}_u\Big \vert \mathcal{G}_t\right] \nonumber \\
 & \quad -\frac{1}{\mathscr{Z}_t} \mathbb{E}_{\mathbb{P}}\left[ \frac{\mathscr{Z}_{\tau \wedge T}C_{\tau \wedge T}}{B_{\tau \wedge T}^r}-\frac{\mathscr{Z}_tC_t}{B_t^r}+ \int_t^{\tau \wedge T} \frac{ \mathscr{Z}_u C_u r_u}{B_u^r} du- \int_t^{\tau \wedge T} \frac{C_u}{B_u^r} d\mathscr{Z}_u\Big \vert \mathcal{G}_t\right] \nonumber \\
 &\quad  + \frac{1}{\mathscr{Z}_t} \mathbb{E}_{\mathbb{P}}\left[  \int_t^{\tau \wedge T} \frac{ \mathscr{Z}_u \bar{r}_u^c}{B_u^r} du- \int_t^{\tau \wedge T} \mathscr{Z}_u\left( r_u^f-r_u\right)\frac{{V}_u^p(\varphi, A^{C})}{B_u^r}du\Big \vert \mathcal{G}_t\right].\label{eq:IntermediateStepProoof}
\end{align}
By Definition \ref{def:ValueProcessWealth}, \eqref{eq:NoCollateralPosted} and \eqref{eq:IntermediateStepProoof} it follows
\begin{align}
 \widehat{V}_t(\varphi, {A}^{R,C})& 
 = \widehat{V}_t^p(\varphi, A^{R,C}) -\frac{C_t}{B_t^r}\nonumber \\
 &=\frac{1}{ \mathscr{Z}_t}\mathbb{E}_{\mathbb{P}}\left[ -\mathscr{Z}_{\tau \wedge T} \frac{R_{\tau}}{B_{\tau}^r}\textbf{1}_{\lbrace \tau \leq T \rbrace}  - \int_{t}^{\tau \wedge T} \frac{\mathscr{Z}_u}{B_u^r}d\widetilde{A}_u\Big \vert \mathcal{G}_t\right] \nonumber \\
 & \quad - \frac{1}{ \mathscr{Z}_t}\mathbb{E}_{\mathbb{P}}\left[ \mathscr{Z}_{\tau \wedge T} \frac{C_{\tau-}}{B_{\tau}^f} \textbf{1}_{\lbrace  \tau \leq T \rbrace}+ \int_t^{\tau \wedge T} \frac{ \mathscr{Z}_u C_u r_u}{B_u} du- \int_t^{\tau \wedge T} \frac{C_u}{B_u} d\mathscr{Z}_u\Big \vert \mathcal{G}_t\right] \nonumber \\
  & \quad + \frac{1}{\mathscr{Z}_t} \mathbb{E}_{\mathbb{P}}\left[  \int_t^{\tau \wedge T} \frac{ \mathscr{Z}_u \bar{r}_u^c}{B_u^r} du- \int_t^{\tau \wedge T} \mathscr{Z}_u\left( r_u^f-r_u\right)\frac{{V}_u^p(\varphi, A^{C})}{B_u^r}du\Big \vert \mathcal{G}_t\right].  \label{eq:IntermediateStepProof2}
\end{align}
Furthermore, it holds 
\begin{align*}
\mathbb{E}_{\mathbb{P}}\left[  \int_t^{\tau \wedge T} \frac{C_u}{B_u^r} d\mathscr{Z}_u\Big \vert \mathcal{G}_t\right]=\mathbb{E}_{\mathbb{P}}\left[  \int_t^{\tau \wedge T} \frac{C_u}{B_u^r} \mathscr{Z}_u \left( \sum_{i=1}^d -\frac{\mu^i(u,S_u)-r_u^i}{\sigma^{i}(u,S_u)} d W_u^{f,i}\right)  \Big \vert \mathcal{G}_t\right],
\end{align*}
and we now show that 
$$
\mathscr{M}_t^{4,i}:= - \int_0^t \frac{C_u}{B_u^r} \mathscr{Z}_u \frac{\mu^i(u,S_u)-r_u^i}{\sigma^{i}(u,S_u)} dW_u^{\tau,f,i}, \quad i=1...,d, \, t \in [0,T]
$$
is a $(\mathbb{G},\mathbb{P})$-martingale. In particular, we have
\begin{align*}
    \int_0^{\tau \wedge T}  \left \vert \frac{C_u}{B_u^r} \mathscr{Z}_u \frac{\mu^i(u,S_u)-r_u^i}{\sigma^{i}(u,S_u)}\right \vert^2 du &\leq K_i^2 \int_0^T \left \vert \frac{C_u}{B_u^r}  \mathscr{Z}_u \right \vert^2 du \\
    &\leq K_i^2 T \sup_{t \in [0,T]} \vert C_t \vert^2  \sup_{t \in [0,T]} \left \vert  \mathscr{Z}_t \right \vert^2 \sup_{t \in [0,T]} \left \vert  \frac{1}{B_t^r} \right \vert^2 < \infty \quad \mathbb{P} \text{-a.s.}
\end{align*}
and
\begin{align}
\mathbb{E}_{\mathbb{P}}\left[ \sup_{t \in [0,T]} \left \vert \mathscr{M}_t^{4,i} \right \vert \right]&=\mathbb{E}_{\mathbb{P}}\left[ \sup_{t \in [0,T]} \left \vert \int_0^t \frac{C_u}{B_u^r} \mathscr{Z}_u \frac{\mu^i(u,S_u)-r_u^i}{\sigma^{i}(u,S_u)} dW_u^{\tau,f,i} \right \vert \right] \nonumber \\
&\leq K K_i^2 \mathbb{E}_{\mathbb{P}}\left[ \left \vert \int_0^{\tau \wedge T} \frac{1}{\vert B_u^r\vert^2} \vert C_u\vert^2 \vert \mathscr{Z}_u \vert^2  du\right \vert^{\frac{1}{2}} \right] \nonumber \\
&\leq K  K_i^2 T  C(K_r) \mathbb{E}_{\mathbb{P}}\left[ \sup_{t \in [0,T]}\vert C_t \vert   \sup_{t \in [0,T]} \vert \mathscr{Z}_t \vert   \right] \nonumber \\
&\leq K K_i^2  C(K_r) \mathbb{E}_{\mathbb{P}}\left[ \sup_{t \in [0,T]}\vert C_t \vert^2  \right]^{\frac{1}{2}}  \mathbb{E}_{\mathbb{P}} \left[  \sup_{t \in [0,T]} \vert \mathscr{Z}_t \vert^2 \right]^{\frac{1}{2}} \nonumber \\
&< \infty \nonumber 
\end{align}
by using \eqref{eq:IntegrabilityCollateral} and \eqref{eq:Doob} and similar arguments as before. This implies that $\mathbb{E}_{\mathbb{P}}\left[  \int_t^{\tau \wedge T} \frac{C_u}{B_u^r} d\mathscr{Z}_u\Big \vert \mathcal{G}_t\right]=0.$
Thus, by \eqref{eq:IntermediateStepProof2} we get
\begin{align}
\widehat{V}_t(\varphi, {A}^{R,C}) &=\frac{1}{ \mathscr{Z}_t}\mathbb{E}_{\mathbb{P}}\left[ - \frac{\mathscr{Z}_{\tau }}{B_{\tau}^r}( C_{\tau-}+R_{\tau})\textbf{1}_{\lbrace \tau \leq T \rbrace}  - \int_{t}^{\tau \wedge T}\frac{ \mathscr{Z}_u}{B_u^r}d\widetilde{A}_u + \int_{t}^{\tau \wedge T} \mathscr{Z}_u\frac{C_u}{B_u^r}\left(\bar{r}_u^c-{r}_u \right) du\Big \vert \mathcal{G}_t\right] \nonumber \\ 
&\quad -\frac{1}{\mathscr{Z}_t}\mathbb{E}_{\mathbb{P}}\left[\int_t^{\tau \wedge T} \mathscr{Z}_u\left( r_u^f-r_u\right)\frac{{V}_u^p(\varphi, A^{C})}{B_u^r}du\Big \vert \mathcal{G}_t\right] \nonumber \\
 &=\frac{1}{ \mathscr{Z}_t}\mathbb{E}_{\mathbb{P}}\left[ - \frac{\mathscr{Z}_{\tau }}{B_{\tau}^r}( C_{\tau-}+R_{\tau})\textbf{1}_{\lbrace \tau \leq T \rbrace}  - \int_{t}^{\tau \wedge T}\frac{ \mathscr{Z}_u}{B_u^r}d\widetilde{A}_u + \int_{t}^{\tau \wedge T} \mathscr{Z}_u\frac{C_u}{B_u^r}\left(\bar{r}_u^c-{r}_u \right) du\Big \vert \mathcal{G}_t\right] \nonumber \\ 
&\quad -\frac{1}{ \mathscr{Z}_t}\mathbb{E}_{\mathbb{P}}\left[\int_t^{\tau \wedge T} \mathscr{Z}_u\left( r_u^f-r_u\right)\frac{{V}_u(\varphi, A^{C}) + C_u}{B_u^r}du\Big \vert \mathcal{G}_t\right] \nonumber \\
&=\frac{1}{ \mathscr{Z}_t}\mathbb{E}_{\mathbb{P}}\left[ - \frac{\mathscr{Z}_{\tau }}{B_{\tau}^r}( C_{\tau-}+R_{\tau})\textbf{1}_{\lbrace \tau \leq T \rbrace}  - \int_{t}^{\tau \wedge T}\frac{ \mathscr{Z}_u}{B_u^r}d\widetilde{A}_u + \int_{t}^{\tau \wedge T} \mathscr{Z}_u\frac{C_u}{B_u^r}\left(\bar{r}_u^c-{r}_u^f \right) du\Big \vert \mathcal{G}_t\right] \nonumber \\ 
&\quad -\frac{1}{ \mathscr{Z}_t}\mathbb{E}_{\mathbb{P}}\left[\int_t^{\tau \wedge T} \mathscr{Z}_u\left( r_u^f-r_u\right)\frac{{V}_u(\varphi, A^{C})}{B_u^r}du\Big \vert \mathcal{G}_t\right], \label{eq:RepresentationXVA1}
\end{align}
where we use that ${V}_u^p(\varphi, A^{C}) ={V}_u(\varphi, A^{C}) + C_u$.
Next, we study the term $-\frac{1}{ \mathscr{Z}_t}\mathbb{E}_{\mathbb{P}}\left[ \int_{t}^{\tau \wedge T} \frac{ \mathscr{Z}_u}{B_u^r}d\widetilde{A}_u\Big \vert \mathcal{G}_t\right]$. Note that on $\lbrace t < \tau  \rbrace$ it holds
\begin{align*}
 \int_{]t,\tau \wedge T]}  \frac{\mathscr{Z}_u}{B_u^r}d\widetilde{A}_u=\int_{]t, T]}  \frac{\mathscr{Z}_u}{B_u^r}d{A}_u - \textbf{1}_{\lbrace \tau \leq T \rbrace} \int_{[\tau \wedge T,T]}  \frac{\mathscr{Z}_u}{B_u^r}d{A}_u
\end{align*}
and thus
\begin{align}
\frac{B_t^r}{ \mathscr{Z}_t}\mathbb{E}_{\mathbb{P}}\left[-\int_{t}^{\tau \wedge T} \frac{\mathscr{Z}_u}{B_u^r}d\widetilde{A}_u\Big \vert \mathcal{G}_t\right]& = \frac{B_t^r}{ \mathscr{Z}_t} \mathbb{E}_{\mathbb{P}}\left[-\int_{]t, T]} \frac{ \mathscr{Z}_u}{B_u^r}d{A}_u + \textbf{1}_{\lbrace \tau \leq T \rbrace} \int_{[\tau \wedge T,T]}  \mathscr{Z}_u\frac{1}{B_u^r}d{A}_u  \Big \vert \mathcal{G}_t\right] \nonumber \\
&=\mathcal{V}_t + \frac{B_t^r}{ \mathscr{Z}_t}\mathbb{E}_{\mathbb{P}}\left[ \mathbb{E}_{\mathbb{P}} \left[\textbf{1}_{\lbrace \tau \leq T \rbrace}\frac{\mathscr{Z}_{\tau}}{\mathscr{Z}_{\tau}}\frac{{B}_{\tau}^r}{{B}_{\tau}^r} \int_{[\tau \wedge T,T]}  \frac{ \mathscr{Z}_u}{B_u^r}d{A}_u \Big \vert \mathcal{G}_{\tau}\right]\Big \vert \mathcal{G}_t\right] \nonumber \\
&=\mathcal{V}_t + {\frac{B_t^r}{ \mathscr{Z}_t}\mathbb{E}_{\mathbb{P}}\left[ \textbf{1}_{\lbrace \tau \leq T \rbrace}\frac{\mathscr{Z}_{\tau}}{B_{\tau}^r}Q_{\tau} \Big \vert \mathcal{G}_t\right] } \label{eq:DefCleanValue}
\end{align}
where we use Remark \ref{remark:ConditioningGF} with $\mathcal{V}_t$ and $Q_{\tau}$ given in Definition \ref{def:CleanValue}. 
 Combining \eqref{eq:RepresentationXVA1} and \eqref{eq:DefCleanValue} yields
\begin{align}
{V}_t(\varphi, {A}^{R,C}) &= \widehat{V}_t(\varphi, {A}^{R,C}) B_t^r\nonumber \\
&=\mathcal{V}_t+ {\frac{B_t^r}{ \mathscr{Z}_t}\mathbb{E}_{\mathbb{P}}\left[ \textbf{1}_{\lbrace \tau \leq T \rbrace} \textbf{1}_{\lbrace{\tau^C< \tau^B\rbrace}}\frac{\mathscr{Z}_{\tau}}{B_{\tau}^r}(1-R^C) (Q_{\tau}-C_{\tau-})^+\Big \vert \mathcal{G}_t\right] }  \nonumber \\
& \quad - \frac{B_t^r}{ \mathscr{Z}_t}\mathbb{E}_{\mathbb{P}}\left[ \textbf{1}_{\lbrace \tau \leq T \rbrace}\textbf{1}_{\lbrace{\tau^B< \tau^C\rbrace}}\frac{\mathscr{Z}_{\tau}}{B_{\tau}^r} (1-R^B)(Q_{\tau}-C_{\tau-})^-\Big \vert \mathcal{G}_t\right] \nonumber \\
& \quad + \frac{B_t^r}{ \mathscr{Z}_t}\mathbb{E}_{\mathbb{P}}\left[ \int_{t}^{\tau \wedge T} \mathscr{Z}_u\frac{C_u}{B_u^r}\left(\bar{r}_u^c-r_u^f \right) du\Big \vert \mathcal{G}_t\right] \nonumber \\
&\quad - \frac{B_t^r}{ \mathscr{Z}_t}\mathbb{E}_{\mathbb{P}}\left[ \int_{t}^{\tau \wedge T} \mathscr{Z}_u\frac{V_u(\varphi,A^{R,C})}{B_u^r}\left({r}_u^f-r_u \right) du\Big \vert \mathcal{G}_t\right]\nonumber \\
&= \mathcal{V}_t+ \textnormal{CVA}_t-\textnormal{DVA}_t+\textnormal{ColVA}_t -\textnormal{FVA}_t, \nonumber 
\end{align}
and thus
\begin{align}
{V}_t(\varphi, {A}^{R,C})&= \mathcal{V}_t+ \textnormal{CVA}_t-\textnormal{DVA}_t+\textnormal{ColVA}_t \nonumber \\
&  \quad - \frac{B_t^r}{ \mathscr{Z}_t}\mathbb{E}_{\mathbb{P}}\left[ \int_{t}^{\tau \wedge T} \mathscr{Z}_u\frac{\mathcal{V}_u+ \textnormal{CVA}_u-\textnormal{DVA}_u+\textnormal{ColVA}_u-\textnormal{FVA}_u}{B_u^r}\left({r}_u^f-r_u \right) du\Big \vert \mathcal{G}_t\right].  \nonumber 
\end{align}
\end{proof}

The result above provides the decomposition of the price in terms of valuation adjustments. To this extent we prove a consolidated practice in banks' risk management in a mathematical rigorous way also for the case of incomplete markets.

\section{Two-Step valuation of xVAs}
In this section we show that a slight modification of the assumptions underlying our approach based on local risk-minimization provides a foundation to a version of the two-step valuation approach proposed in \cite{pelsser_stadje_2014}, \cite{delong_dhaene_barigou_2019} and \cite{barigou_linders_yang_2022}. This allows us to obtain a formula for CVA (and similarly for other valuation adjustments) which is particularly convenient in applications.

We consider $W^f=(W_t^f)_{t \in [0,T]}$ and $W^\perp=(W_t^\perp)_{t \in [0,T]}$ to be $d$- resp. $d^\prime$-dimensional Brownian motions on $(\Omega, \mathcal{G}, \mathbb{P})$ and $\mathbb{F}^{W^f}=(\mathcal{F}^{W^f}_t)_{t \in [0,T]}$ and $\mathbb{F}^{W^\perp}=(\mathcal{F}^{W^\perp}_t)_{t \in [0,T]}$ their associated natural filtrations. We set $\mathbb{F}:=\mathbb{F}^{W^f}\otimes\mathbb{F}^{W^\perp}$, that is $\mathcal{F}_t:=\mathcal{F}^{W^f}_t\otimes\mathcal{F}^{W^\perp}_t$ for every $t\in[0,T]$. Let the stopping times $\tau^B, \tau^C, \tau$ and the associated filtrations be as introduced in Section  \ref{Sect:preliminaries}. On $(\Omega, \mathcal{G}, \mathbb{P})$ we consider the filtration $\mathbb{G}=(\mathcal{G}_t)_{t\in[0,T]}$ defined by
\begin{align*}
\mathcal{G}_t &:= \mathcal{F}_t \vee \mathcal{H}^B_t \vee \mathcal{H}^C_t\\
&=\mathcal{F}^{W^f}_t\otimes\mathcal{F}^{W^\perp}_t \vee \mathcal{H}^B_t \vee \mathcal{H}^C_t, \quad t \in [0,T],
\end{align*}
and set $\mathcal{G}:=\mathcal{G}_T.$ All filtrations are required to satisfy the usual hypotheses of completeness and right-continuity.

In addition to the assumptions in Section \ref{Sect:preliminaries}, we assume that all coefficients $\mu^i,\sigma^i$, repo rates $r^i$ for $i=1,...,d,$ collateral and funding rates are $\mathbb{F}^{W^f}$-adapted, so that completeness is preserved for the clean market. With respect to the previous sections, we assume that the close-out valuation process $Q$ is $\mathbb{F}^{W^f}$-adapted by setting
\begin{align*}
     Q_t:=  \mathbb{E}_{\mathbb{Q}}\left[\int_{[t,T]}  \frac{B_t^r}{B_u^r}\ d A_u \Big \vert \mathcal{F}^{W^f}_t \right]=\mathbb{E}_{\mathbb{P}}\left[\int_{[t,T]}  {\mathscr{Z}}_u \frac{B_t^r}{B_u^r}\frac{1}{ {\mathscr{Z}}_t} d A_u \Big \vert \mathcal{F}^{W^f}_t \right] \quad t \in [0,T].
\end{align*}
Similarly, we also assume that the collateral process $C$ is $\mathbb{F}^{W^f}$-adapted.

We allow the default intensities to be $\mathbb{F}$-adapted, which introduces an additional dependence on the Brownian motion $W^\perp$. Recalling our previous assumption that intensity rates are bounded, a concrete example that satisfies all the assumptions of the present setting is given by the Jacobi diffusion
\begin{align*}
    d\lambda^j_t=\kappa^j(\theta^j-\lambda^j_t)dt+\sqrt{(\lambda_t-\lambda^j_{max})(\lambda_t-\lambda^j_{min})}\left(\rho^jdW^{f,1}_t+\sqrt{1-(\rho^{j})^2}dW^{\perp,j}\right), \quad t \in [0,T],
\end{align*}
where $\lambda^j_{max},\lambda^j_{min}$ are the upper and lower bound for the intensity respectively, $\kappa^j,\theta^j\in \mathbb{R}_+$, $\rho^j\in(-1,1)$  for $j\in\{B,C\}$. In this setting, let us consider the CVA which can be rewritten as
\begin{align*}
    \textnormal{CVA}_t&=\frac{B_t^r}{ \mathscr{Z}_t}\mathbb{E}_{\mathbb{P}}\left[ \textbf{1}_{\lbrace \tau \leq T \rbrace} \textbf{1}_{\lbrace{\tau^C< \tau^B\rbrace}}\frac{\mathscr{Z}_{\tau}}{B_{\tau}^r}(1-R^C) (Q_{\tau}-C_{\tau-})^+\Big \vert \mathcal{G}_t\right]\\
    &=\textbf{1}_{\lbrace \tau > t \rbrace}\frac{B_t^r}{ \mathscr{Z}_t}\mathbb{E}_{\mathbb{P}}\left[  (1-R^C)\int_t^T\frac{\mathscr{Z}_{u}}{B_{u}^r}e^{-\int_t^u\lambda^C_s+\lambda^B_s ds}\lambda^C_u (Q_{u}-C_{u})^+du\Big \vert \mathcal{F}_t\right], \quad t \in [0,T],
\end{align*}
by using Proposition 5.1.1 in \cite{BieRut2004}. Next, following \cite{pelsser_stadje_2014}, we condition on the full information on the market risk factors up to maturity and consider the two-step valuation
\begin{align*}
    \textnormal{CVA}_t&=\textbf{1}_{\lbrace \tau > t \rbrace}\frac{B_t^r}{ \mathscr{Z}_t}\mathbb{E}_{\mathbb{P}}\left[  (1-R^C)\int_t^T\frac{\mathscr{Z}_{u}}{B_{u}^r}\mathbb{E}_{\mathbb{P}}\left[e^{-\int_t^u\lambda^C_s+\lambda^B_s ds}\lambda^C_u \Big \vert \mathcal{F}^{W^f}_T\otimes\mathcal{F}^{W^\perp}_t\right](Q_{u}-C_{u})^+du\Big \vert \mathcal{F}_t\right],
\end{align*}
where we apply Fubini's theorem. We introduce the notation
\begin{align*}
\Lambda(W^f_u):=\mathbb{E}_{\mathbb{P}}\left[e^{-\int_t^u\lambda^C_s+\lambda^B_s ds}\lambda^C_u \Big \vert \mathcal{F}^{W^f}_T\otimes\mathcal{F}^{W^\perp}_t\right],  \quad u \in [t,T],
\end{align*}
to represent this term that can be computed based on historical information regarding the defaults and then switch to the risk-neutral measure to finally obtain
\begin{align*}
\textnormal{CVA}_t=  \textbf{1}_{\lbrace \tau > t \rbrace}B_t^r\mathbb{E}_{\mathbb{Q}}\left[  (1-R^C)\int_t^T\frac{1}{B_{u}^r}\Lambda(W^f_u)(Q_{u}-C_{u})^+du\Big \vert \mathcal{F}_t\right].  
\end{align*}

This allows the bank to calculate in a first step $\Lambda(W^f_\cdot)$ based on historical information from the internal rating system, as in the outlined setting the bank cannot fall back on the dynamics of the intensity rates under $\mathbb{Q}$. In a second step, the usual approximation of the CVA can be performed either via American Monte Carlo or more advanced deep learning methods. In particular, the local risk-minimization approach of the present paper provides a sound mathematical foundation to this appealing computational strategy. Similar calculations hold also for the remaining valuation adjustments.

%In summary, the two-step procedure consists in a computation that first involves the calculation of $\Lambda(W^f_\cdot)$ based on the historical information from the internal rating system, followed by the usual approximation of CVA that can be performed either via American Monte Carlo or more advanced deep learning methods. The local risk-minimization approach of the present paper provides a sound mathematical foundation to this appealing computational strategy. Similar calculations hold also for the remaining valuation adjustments.


\section{Capital Value Adjustment (KVA)}

In recent years, there has been a debate regarding the need to take into account the funding cost generated by capital requirements on derivative transactions. According to Basel III a bank that is holding a derivative portfolio must set aside capital that can be determined according to different approaches: this could involve a standard model defined by the regulator or an internal model. A first approach that includes the cost of capital in the valuation of derivatives can be found in \cite{gk2014}. Later studies include, among many \cite{Kjaer2017} and \cite{Kjaer2018}, who consider the balance sheet model of \cite{ads2019} or \cite{Castagna2019}. There are other approaches in the literature that see capital requirements as a consequence of market incompleteness, see \cite{Brigo2017}, \cite{alcacre2017}, \cite{Arnsdorf2020}, \cite{css2020} and \cite{crep2022}. 
The capital is provided by the shareholders, who require in return a remuneration for the regulatory capital that they are providing, which is typically termed \textit{hurdle rate}. In line with other value adjustments, the discussion has been about the possibility to charge such costs to the client by means of a suitable value adjustment. In the following, we provide a tentative definition of a capital valuation adjustment that arises from the approach presented in this work. %We assume that any further cost of the strategy beyond $\mathcal{C}_0^{\varphi,A^{R,C}}$ is provided by/provided to the shareholders of the bank. 
We first consider the variation of the cost process of the local risk-minimizing strategy given by
\begin{align*}
    \Delta  \mathcal{C}_t^{\varphi,A^{R,C}}:= \mathcal{C}_t^{\varphi,A^{R,C}}- \mathcal{C}_0^{\varphi,A^{R,C}}.
\end{align*}
This process measures the variation of the cash capital that needs to be put aside or withdrawn. We assume that the capital requirement at a certain point in time $t$ is given by the expected shortfall with confidence level $\alpha$ given by
\begin{align*}
    \mathbb{ES}^\mathbb{P}_\alpha\left[\left.\mathcal{C}_{t+\Delta t}^{\varphi,A^{R,C}}-\mathcal{C}_t^{\varphi,A^{R,C}}\right|\mathcal{G}_t\right]
\end{align*}
 with $\Delta t$ a fixed time horizon, e.g. 1 year. When the shareholders provide such capital, they are remunerated by means of a hurdle rate $h$. When applied to the whole lifetime of the transaction, this gives rise to the following definition

\begin{align*}
    \textnormal{KVA}_t:=B^r_t\mathbb{E}_{\mathbb{Q}}\left[\left.\int_t^{\tau\wedge T}\frac{1}{B^r_u}h_u\mathbb{ES}^\mathbb{P}_\alpha\left[\left.\mathcal{C}_{u+\Delta t}^{\varphi,A^{R,C}}-\mathcal{C}_u^{\varphi,A^{R,C}}\right|\mathcal{G}_u\right]du\right|\mathcal{G}_t\right].
\end{align*}
With this definition the KVA is then charged as a mark-up to the customer on top of the price represented by ${V}_t(\varphi, {A}^{R,C})$. In case the market is complete, then we clearly have that the cost process is a.s. constant, $\mathcal{C}_t^{\varphi,A^{R,C}}-\mathcal{C}_0^{\varphi,A^{R,C}}\equiv 0$ $d\mathbb{P}\otimes dt$-a.s., so that $\textnormal{KVA}_t\equiv 0$ and the client is charged the price ${V}_t(\varphi, {A}^{R,C})$. In summary, the bank charges the amount $V^{full}_t(\varphi, {A}^{R,C})$ given by
\begin{align*}
    V^{full}_t(\varphi, {A}^{R,C}):=V_t(\varphi, {A}^{R,C})+\textnormal{KVA}_t.
\end{align*}
This market practice in the banking sector essentially mimics the traditional insurance valuation, where pricing is performed under the historical measure with the addition of a risk-charge, whose role is taken by the KVA. Clearly, our valuation is performed under a risk neutral setting since we assumed that market risk factors can be hedged. As already claimed in \cite{crep2022} the idea of adding a KVA mimics the valuation approach of Solvency II where the cost of capital is added to the best estimate of the liability.





