\section{Föllmer-Schweizer decomposition} \label{appendix}

We briefly recall the definition of the structure condition for a process $Y$ on a filtered probability space $(\Omega, \mathcal{G}_T,\mathbb{G},\mathbb{P})$, see \cite{schweizer_local_risk-minimization}.
\begin{definition} \label{def:MeanVariance}
Let $Y=(Y_t)_{t \in [0,T]}$ be an $\mathbb{R}^d$-valued continuous $(\mathbb{G}, \mathbb{P})$-semimartingale with decomposition $Y=Y_0+A^Y+M^Y.$ We say that $Y$ satisfies the \emph{structure condition (SC)} if
\begin{enumerate}
    \item $Y \in \mathcal{S}^2_{\textnormal{loc,d}}(\mathbb{G},\mathbb{P}),$ 
    \item $A^Y$ is absolutely continuous w.r.t. to the bracket process $\langle M^Y \rangle=(\langle M^{Y^i}, M^{Y^j} \rangle)_{i,j=1,...,d}$, i.e. there exists an $\mathbb{G}$-predictable process $\lambda=(\lambda_t)_{ t \in[0, T]}$ such that  $A_t^{Y^i}=\sum_{j=0}^d \int_0^t {\lambda}_u^j d\left\langle M^{Y^i},M^{Y^j}\right\rangle_u$, for $i= 1, \ldots, d $ and $t \in[0, T],$
    \item the \emph{mean-variance tradeoff} process $K^Y=(K_t^Y)_{t\in [0,T]}$ 
    \begin{align} \label{eq:MeanVarianceTradoff}
        {K}_t^Y:=\int_0^t {\lambda}_u^{\top} {d}\left\langle M^Y\right\rangle_u {\lambda}_u= \sum_{i,j=1}^d \int_0^t \lambda_u^i \lambda_u^j d \langle M^{Y^i}, M^{Y^i}\rangle_u
    \end{align}
    satisfies $K_T^Y<\infty$ $\mathbb{P}$-a.s.
\end{enumerate}
\end{definition}
%\begin{remark}
%Let $H\in L^2(\mathbb{G}, \mathbb{P})$. Then by Theorem 1.6 in \cite{schweizer_local_risk-minimization} we have that for a process $Y$ as in Definition \ref{def:MeanVariance} satisfying (SC) such that the mean-variance tradeoff process $K^Y$ is continuous, the definitions of a pseudo-locally risk-minimizing $L^2$-strategy and of a locally risk-minimizing $L^2$-strategy are equivalent, see Definition 1.5 in \cite{schweizer_survey}.
%\end{remark}
It is well-known that there exists a link between no arbitrage conditions and the structure condition for continuous semimartingales. Denote by $\mathcal{P}^{\textnormal{loc}}_{\mathbb{G}}(Y)$ the set of all equivalent local $\mathbb{G}$-martingale measures $\mathbb{Q}$ of $Y$ w.r.t. $\mathbb{P}$.
Then the following result holds, see Theorem 3.5 in \cite{schweizer_survey} and Theorem 3.4 in \cite{Monat_Stricker}.
\begin{theorem} \label{theorem:Schweizer}
    Let $Y$ be a continuous process in $ \mathcal{S}^2_{\textnormal{loc,d}}(\mathbb{G},\mathbb{P})$ and $N$ a random variable in $L^2(\mathcal{G}_T,\mathbb{P})$.
    \begin{enumerate}
     \item If $\mathcal{P}^{\textnormal{loc}}_{\mathbb{G}}(Y) \neq \emptyset,$ then $Y$ satisfies (SC).
     \item If $Y$ satisfies (SC) and the mean-variance tradeoff process $K^Y$ is uniformly bounded, then $N$ admits a unique $\mathbb{G}$-F\"ollmer-Schweizer decomposition.
    \end{enumerate}
\end{theorem}
















