\section{Theoretical results}\label{A}

Some useful results: at first, we will explore single name default probability under the model assumptions. We will then move to calculate the portfolio loss distribution. A few necessary tools and additional notational short cuts will be introduced along the way.\newline

\begin{proposition}\label{pr: IA}
	Let $A\subseteq\{1\cdots,n\}$; the probability that at least one name in $A$ spreads an infection is given by the quantity $I_A$ defined as 
	\begin{equation} I_A := \left\{1-\prod_{j\in A} \left[1-p_j(t)\cdot v_j\right]\right\}. \end{equation}
\end{proposition}
\begin{proof}
	[Proof]
	The probability that an infection starts from inside $A$ is given by
	\begin{equation} P\{X_j \cdot V_j=1 \text{ for at least one } j\in A\} = 1- P\{X_j\cdot V_j=0, \forall j \in A\}.\end{equation}
	We can now use the independence assumption on $X$ and $V$ to get
	\begin{equation}
		\begin{array}{lr}
			P\{X_j\cdot V_j=0, \forall j \in A\} & = \\
			\prod_{j \in A} P\{ X_j\cdot V_j =0\} & = \\
			\prod_{j \in A} [1-P\{ X_j\cdot V_j =1\} ] & = \\
			\prod_{j \in A} [1-P\{ X_j=1, V_j =1\} ] & = \\
			\prod_{j \in A} [1-P\{ X_j=1\}\cdot P\{V_j =1\} ] & = \\
			\prod_{j \in A} [1-p_j \cdot v_j ]. & \
		\end{array}
	\end{equation}

\end{proof}
We will now focus on single name properties. Let $\overline{A}$ be the complement of set $A$. The following result gives the formula for the probability of default of single names:

\begin{proposition}\label{pr: I_A}
	Let $X_i,V_i,U_i$, $i=1..n$ be mutually independent Bernoulli variables with   probabilities  $p_i= P\{X_i=1\}, \,\, u_i=P\{U_i=1\} , \,\, v_i=P\{V_i=1\}  $ on a time horizon [0,t]. Let $Z_i$ be defined according to \ref{eq:MainModDesc} and let $\tilde{p}_i := P\{Z_i=1\}$. We have:
	\begin{equation}\label{eq: PD_A} \tilde{p}_i = p_i+[1-p_i]\cdot [1-u_i]\cdot I_{\overline{\{i\}}}\end{equation}
\end{proposition}
\begin{proof}
	We have that
	\begin{equation}
		\begin{array}{cl} 
			P\{Z_i=1\} = & P\{Z_i=1 | X_i=1\} \cdot P\{X_i=1\} + \\
			\quad & P\{Z_i=1| X_i=0\} \cdot P\{X_i=0\}. \\
		\end{array}
	\end{equation}
	It is easy to see that
	\begin{align*}
		\begin{array}{c} 
			P\{Z_i=1| X_i=1\}=1, \\
			P\{X_i=1\}=p_i, \\
			P\{X_i=0\}=1-p_i,
		\end{array} 
	\end{align*}
	so that the only part left to calculate is $P\{Z_i=1| X_i=0\}$; using the expression for $Z_i$ in \eqref{eq:MainModDesc} we have
	\begin{equation}P\{Z_i=1| X_i=0\} = P\left\{(1-U_i) \cdot \left[ 1 - \prod_{i\neq j} (1-X_j \cdot V_j ) \right] = 1\right\}. \end{equation}
	Both variables in the last expression can only take binary values $(0,1)$ so their product can only be $1$ if they both take value $1$. This implies that 
	\begin{equation}\begin{array}{l} 
			P\left\{(1-U_i) \cdot \left[ 1 - \prod_{i\neq j} (1-X_j \cdot V_j) \right] = 1\right\} \\
			= P\left\{(1-U_i)=1, \left[ 1 - \prod_{i\neq j} (1-X_j \cdot V_j) \right] = 1\right\}.
	\end{array} \end{equation}
	We can use the independence assumption between the various building blocks to split the right hand side as 
	\begin{equation}P\left\{(1-U_i)=1\right\} \cdot P\left\{\left[ 1 - \prod_{i\neq j} (1-X_j \cdot V_j) \right] = 1\right\}, \end{equation}
	and hence, thanks to proposition \ref{pr: IA}
	\begin{equation}P\{Z_i=1| X_i=0\} = (1-u_i) \cdot I_{\overline{\{i\}}}\end{equation}
	that concludes the proof.\end{proof}

Intuitively, name $i$ can default in two ways: idiosyncratically (with probability $p_i$) or by contagion if it survives ($1-p_i$), fails to defend itself ($1-u_i$) and an external infection is active ($I_{\overline{i}}$). 


Lets move now to the proof of proposition \ref{portfolio}:

\begin{proposition}\label{portfolioA}
	The following recursive relationship links $[\alpha_j(\cdot,\cdot), \beta_j(\cdot,\cdot)]$ to $[\alpha_{j-1}(\cdot,\cdot),\beta_{j-1}(\cdot,\cdot)]$:
	\begin{equation}\label{alfabetaA}
		\begin{array}{cclr} 
			\ 								&\  & (1-p_j(t)) \cdot u_j \cdot \alpha_{j-1}(h,k,t) 			& + \\
			\alpha_j(h,k,t) & = & (1-p_j) \cdot (1-u_j(t)) \cdot \alpha_{j-1}(h,k-d_j) & + \\ 
			\ 								&\  & p_j(t) \cdot (1-v_j) \cdot \alpha_{j-1}(h-d_j,k),			& \  \\
			\ 								&\  & \ 											& \  \\
			\ 								&\  & (1-p_j(t)) \cdot u_j(t) \cdot \beta_{j-1}(h,k,t) + p_j(t) \cdot \beta_{j-1}(h-d_j,k) & + \\
			\beta_j(h,k,t) 		& = & (1-p_j(t)) \cdot (1-u_j) \cdot \beta_{j-1}(h,k-d_j) & + \\ 
			\ 								&\  & p_j(t) \cdot v_j \cdot \alpha_{j-1}(h-d_j, k), &\ \\
		\end{array}
	\end{equation}
	with the following boundary conditions:
	\begin{equation}\label{boundarycondA}
		\begin{array}{l}
			\alpha_{0,t}(0,0) = 1, \\ \alpha_{0,t}(i,j) = 0 \quad \quad \forall (i,j) \neq (0,0), \\ \beta_{0,t}(i,j) =0 \quad \quad \forall i,j.
		\end{array}
	\end{equation}


	Moreover, the final distribution of the portfolio losses does \textbf{not} depend on the order chosen when adding names in the above algorithm. 
\end{proposition}
\begin{proof}
	In order to obtain a set of equations for $\alpha_j(\cdot,\cdot)$, consider that there are 3 ways of reaching $\alpha_j(h,k)$ starting from $\alpha_{j-1}(h,k)$ and adding a new name:
	\begin{enumerate}
		\item \textbf{Full survival}
		\begin{equation}(1-p_j) \cdot u_j \cdot \alpha_{j-1}(h,k). \end{equation}
		The name survives with probability $(1-p_j)$ and protects itself from future aggressions $(u_j)$. No losses are realized neither potential ones added.
		\item \textbf{Partial survival}
		\begin{equation}(1-p_j) \cdot (1-u_j) \cdot \alpha_{j-1}(h,k-d_j). \end{equation}
		The name survives with probability $(1-p_j)$ but fails to protect itself against future aggressions $(1-u_j)$. Its $d_j$ units of losses are at risk should an infection spread.
		\item \textbf{Non-infectious default}
		\begin{equation}p_j \cdot (1-v_j) \cdot \alpha_{j-1}(h-d_j,k). \end{equation}
		The name defaults directly $(p_j)$ but it is not trying to start an infection $(1-v_j)$.
	\end{enumerate}
	$$\quad$$
	Similarly, there are 4 ways of reaching $\beta_j(h,k)$:
	\begin{enumerate}
		\item \textbf{Full survival}
		\begin{equation} (1-p_j) \cdot u_j \cdot \beta_{j-1}(h,k).\end{equation}
		The name survives $(1-p_j)$ and protects itself against the current and future infections $(u_j)$.
		\item \textbf{Default by contagion}
		\begin{equation} (1-p_j) \cdot (1-u_j) \cdot \beta_{j-1}(h,k-d_j).\end{equation}
		The name survives $(1-p_j)$ but fails to protect itself against the existing infection $(1-u_j)$.
		\item \textbf{Direct default}
		\begin{equation}p_j \cdot \beta_{j-1}(h-d_j,k).\end{equation}
		The name defaults $(p_j)$ and in this case we don't need to consider separately the cases in which it spreads or not the infection as we are already in an infected world.
		\item \textbf{First infection}
		\begin{equation}p_j(t) \cdot v_j \cdot \alpha_{j-1}(h-d_j, k).\end{equation}
		The name defaults $(p_j)$ and spreads the contagion $(v_j)$ in a previously uncontaminated world causing the $k$ units of potential losses to become real ones.
	\end{enumerate}
	Putting together the previous equations, we get system \eqref{alfabetaA}.

	Let's now prove that the order with which we add names is not important for the final result. We report the proof only for $\alpha$ as the case for $\beta$ is similar. Suppose that we want to add two names, $i$ first and then $j$, to a set of $m$ names. In order to shorten the notation, lets indicate with $\bar{p}=1-p$, $\bar{v}=1-v$ and $\bar{u}=1-u$. When we add name $j$, we would apply \eqref{alfabetaA} to a portfolio of $m+1$ names obtaining
	\begin{equation}\label{indproof1}
		\begin{array}{cclr} 
			\ 								&\  & \bar{p}_j \cdot u_j \cdot \alpha_{m+1}(h,k) 			& + \\
			\alpha_{m+2,t}(h,k,t) & = & \bar{p}_j \cdot \bar{u}_j \cdot \alpha_{m+1}(h,k-d_j) & + \\ 
			\ 								&\  & p_j \cdot \bar{v}_j \cdot \alpha_{m+1}(h-d_j,k).			& \  \\
		\end{array}
	\end{equation}
	Each of the three terms $\alpha_{m+1}$ on the right hand side can be explicitly written by applying \eqref{alfabetaA} again:
	\begin{equation}\label{indproof2A}
		\begin{array}{cclr} 
			\ 								&\  & \bar{p}_i \cdot u_i \cdot \alpha_{m}(h,k) 			& + \\
			\alpha_{m+1}(h,k) & = & \bar{p}_i \cdot \bar{u}_i \cdot \alpha_{m}(h,k-d_i) & + \\ 
			\ 								&\  & p_i \cdot \bar{v}_i \cdot \alpha_{m}(h-d_i,k),			& \  \\
		\end{array}
	\end{equation}
	\begin{equation}\label{indproof2B}
		\begin{array}{cclr} 
			\ 								    &\  & \bar{p}_i \cdot u_i \cdot \alpha_{m}(h,k-d_j) 			& + \\
			\alpha_{m+1}(h,k-d_j) & = & \bar{p}_i \cdot \bar{u}_i \cdot \alpha_{m}(h,k-d_j-d_i) & + \\ 
			\ 								    &\  & p_i \cdot \bar{v}_i \cdot \alpha_{m}(h-d_i,k-d_j),			& \  \\
		\end{array}
	\end{equation}
	\begin{equation}\label{indproof2C}
		\begin{array}{cclr} 
			\ 								&\  & \bar{p}_i \cdot u_i \cdot \alpha_{m}(h-d_j,k) 			& + \\
			\alpha_{m+1}(h-d_j,k) & = & \bar{p}_i \cdot \bar{u}_i \cdot \alpha_{m}(h-d_j,k-d_i) & + \\ 
			\ 								&\  & p_i \cdot \bar{v}_i \cdot \alpha_{m}(h-d_j-d_i,k)	.		& \  \\
		\end{array}
	\end{equation}
	Substituting \eqref{indproof2A}, \eqref{indproof2B} and \eqref{indproof2C} into \eqref{indproof1} and rearranging terms, we can write
	\begin{align*}
		%\begin{equation}
		\begin{array}{clr} 
			\alpha_{m+2}(h,k)= & \bar{p}_i \cdot u_i \cdot \bar{p_j} \cdot u_j \cdot \alpha_{m}(h,k) & + \\
			\ 								& \bar{p}_i \cdot \bar{u}_i \cdot \bar{p}_j \cdot \bar{u}_j \cdot \alpha_{m}(h,k-d_i-d_j) & + \\ 
			\ 								& p_i \cdot \bar{v}_i \cdot p_j \cdot \bar{v}_j \cdot \alpha_{m}(h-d_i-d_j,k)			& +\\
			\ 								& \bar{p}_i \cdot u_i \cdot \bar{p}_j \cdot \bar{u}_j \cdot \alpha_{m}(h,k-d_j)& + 	\\
			\
			&\bar{p_j} \cdot u_j \cdot \bar{p}_i \cdot \bar{u}_i \cdot \alpha_{m}(h,k-d_i)& + \\
			\ 								& \bar{p}_i \cdot u_i \cdot p_j \cdot \bar{v_j} \cdot \alpha_{m}(h-d_j,k)& + \\
			\ 
			&\bar{p}_j \cdot u_j \cdot p_i \cdot \bar{v_i} \cdot \alpha_{m}(h-d_i,k)& + \\
			\ 								& \bar{p}_i \cdot \bar{u}_i \cdot p_j \cdot \bar{v_j} \cdot \alpha_{m}(h-d_j,k-d_i)& + \\
			\ 
			&\bar{p}_j \cdot \bar{u}_j \cdot p_i \cdot \bar{v}_i \cdot \alpha_{m}(h-d_i,k-d_j).& \ \\
		\end{array}
	\end{align*}
	%\end{equation}
	Every line in the last equation is symmetric with respect to $i$ and $j$ and then we can invert the order between $i$ and $j$ without changing the final result.\footnote{Technically, this only proves that the order of the last 2 names added is not important. It is quite easy to extend the reasoning to the entire sequence using induction on $m$.}



\end{proof}


\newpage

\begin{proposition}\label{pr:NoLosses_A}
	The probability of observing no losses is given by the following result:
	\begin{equation} \label{eq:NoLosses_A}
		P\{ L_n (t)= 0\} = \prod_{j=1}^{n} (1-p_j(t)).
	\end{equation}

\end{proposition}
\begin{proof}
	The assert can be easily proved by recursion on $n$. Lets start with the case $n=2$. A direct application of equation \eqref{eq:LossFromAlfaBeta} leads to 
	$$ P\{ L_2(t) = 0\} = \alpha_{2,t}(0,0)+\alpha_{2,t}(0,d_1)+\alpha_{2,t}(0,d_2)+\alpha_{2,t}(0,d_1+d_2).$$
	For each of the four terms on the right hand side we can apply recursively equation \ref{alfabetaA} (keeping in mind \ref{boundarycondA}) and obtain
	$$ \alpha_{2,t}(0,0) = (1-p_1(t))\cdot(1-u_1(t)) \cdot (1-p_2(t))\cdot(1-u_2(t)), $$
	$$ \alpha_{2,t}(0,d_1) = (1-p_1(t))\cdot(u_1(t)) \cdot (1-p_2(t))\cdot(1-u_2(t)), $$
	$$ \alpha_{2,t}(0,d_2) = (1-p_1(t))\cdot(1-u_1(t)) \cdot (1-p_2(t))\cdot(u_2(t)), $$
	$$ \alpha_{2,t}(0,d_1+d_2(t)) = (1-p_1(t))\cdot(u_1(t)) \cdot (1-p_2(t))\cdot(u_2(t)). $$
	Summing the four equations above we get
	\begin{align*}
		\begin{array}{c} 
			P\{ L_2(t) = 0\}=(1-p_1(t))\cdot(1-p_2(t)) \times\\
			\quad \quad \times \left[ (1-u_1(t))(1-u_2(t))+u_1(t)(1-u_2(t))+(1-u_1(t))u_2+u_1(t) u_2(t)\right],
		\end{array}
	\end{align*}
	from which the assert as $$(1-u_1(t))(1-u_2(t))+u_1(t)(1-u_2(t))+(1-u_1(t))u_2(t)+u_1(t) u_2(t)=1.$$
	Assume now that \eqref{eq:NoLosses} holds for $n-1$ and lets prove it for $n$. We have
	$$P\{ L_n(t) = 0\} = P\{ L_n(t) = 0 | L_{n-1}(t) = 0\}\cdot P\{ L_{n-1}(t) = 0\}.$$
	The above is true since $P\{ L_n(t) = 0 | L_{n-1}(t) > 0\}=0$. Thanks to the inductive hypothesis we have that $P\{ L_{n-1}(t) = 0\}=\prod_{j=1}^{n-1} (1-p_j(t))$; coming to $P\{ L_n(t) = 0 | L_{n-1}(t) = 0\}$, this represents the probability that a portfolio of $n$ names suffers no losses given the already $n-1$ names experience no defaults. It is then immediate to see that the only way this can be possible is that also the $n$th name does not default idiosyncratically. Exploiting the independence among the various components, we get
	$$P\{ L_n(t) = 0 | L_{n-1}(t) = 0\} = (1-p_n(t)).$$
\end{proof} 


