\section{Semantic Forcing} \label{sec:semantic-forcing}
%%% %%% %%% %%% %%% %%% %%% %%% %%%
As an example of forcing property, we introduce \emph{semantic forcing} and study its properties.
Let us fix an arbitrary signature $\Sigma$ and let $\alpha\coloneqq\card(\Sen(\Sigma))$ be the \emph{power} of $\Sigma$.
Consider an $\S$-sorted set of new constants $C=\{C_s\}_{s\in S}$ such that $\card(C_s)=\alpha$ for all sorts $s\in S$.
These constants, traditionally known as Henkin constants, are used in the construction of models.
%
Throughout this section we assume the following:
\begin{enumerate}[topsep=3pt] 
\item \label{assume1} a partially ordered set $(\K,\preceq)$ with a least element $0_\K$;
\item \label{assume2} a signature functor $\Omega:(\K,\preceq)\to \Sig$ which maps
\begin{enumerate*}[label=(\alph*)]
\item $0_\K$ to $\Sigma$,
\item each element $\kappa\in\K$ to a signature $\Sigma[C_\kappa]$, where $C_\kappa$ is a subset of $C$ with cardinality strictly less than $\alpha$, that is, $C_\kappa\in\P_\alpha(C)$, and
\item each relation $(\kappa\preceq \ell)\in (\K,\preceq)$ to an inclusion of signatures $\Sigma[C_\kappa]\subseteq \Sigma[C_\ell]$; 
\end{enumerate*}
\begin{center}
\begin{tikzcd}[row sep=small]
(\K,\preceq) \ar[dr,bend right=20,"\Omega",swap] \ar[rr,bend left=20pt,"\M", ""{below,name=U}] &  & \Class^{op}\\
& \Sig \ar[ur,bend right=20,"|\Mod|",swap]  \ar[Rightarrow,from = U,"\subseteq"] & 
\end{tikzcd}
\hspace{1cm}
\begin{tikzcd}
\M(\kappa) \ar[d,dotted,"\subseteq"{left}] & \ar[l,"\red_{\Omega(k)}"{above}]\M(\ell) \ar[d,dotted,"\subseteq"]\\
{|\Mod(\Omega(\kappa))|} & {|\Mod(\Omega(\ell))|} \ar[l,"\red_{\Omega(k)}"]
\end{tikzcd}
\end{center}
%
\item \label{assume3} a model functor $\M:(\K,\preceq)\to \Class^{op}$ such that the following hold:
\footnote{$\Class^{op}$ is the opposite category of $\Class$, which means:
\begin{enumerate*}[label=(\alph*)]
\item it has the same objects as $\Class$, that is, classes, but
\item morphisms are reversed, that is, a morphism $f:A\to B$ in $\Class^{op}$ corresponds to a class function $f:B\to A$ in $\Class$.
\end{enumerate*}} 
\begin{enumerate}[topsep=3pt]
\item $\M\subseteq \Omega\comp|\Mod|$ is a natural transformation, that is,
\begin{enumerate*}[label=(\alph*)]
\item \label{assume3-a} $\M(\kappa)\subseteq |\Mod(\Omega(\kappa))|$ for all elements $\kappa\in \K$, and
\item \label{assume3-b} $\M(\ell)\red_{\Omega(\kappa)}\subseteq\M(\kappa)$ for all relations $(\kappa\preceq \ell)\in(\K,\preceq)$;
\end{enumerate*}  
\item Assume an element $\kappa\in \K$, a model $\A\in\M(\kappa)$ and a set of constants $C_1\subseteq_\alpha C\setminus C_\kappa$.
For all expansions $\B$ of $\A$ to $\Sigma[C_\kappa\cup C_1]$, there exists $\ell\succeq\kappa$ such that $C_\ell=C_\kappa\cup C_1$ and $\B\in\M(\ell)$.
\begin{center}
\begin{tikzcd}[row sep=small]
\M(\kappa)\ni\A \ar[r,dotted,no head]& \Sigma[C_\kappa] \ar[r,hook] & \Sigma[C_\kappa\cup C_1]=\Sigma[C_\ell] & \ar[l,dotted,no head]\B\in\M(\ell) \ar[lll,dotted,bend left=10,"\red_{\Sigma[C_\kappa]}"]
\end{tikzcd}
\end{center}
\end{enumerate}
\end{enumerate}
The condition \ref{assume3}\ref{assume3-b} implies that all sets of constants from $\P_\alpha(C)$ appear in some signature from the image of $\Omega$.
%
\begin{example} \label{ex:dls}
Let $\A$ be a model defined over a signature $\Sigma$.
\begin{enumerate}[topsep=3pt]
\item $\K=\{(\Sigma[C'],\A') \mid C'\in\P_\alpha(C) \text{ and }\A'\in |\Mod(\Sigma[C'])| \text{ such that }\A'\red_\Sigma=\A\}$, and

 $(\Sigma[C'],\A')\preceq(\Sigma[C''],\A'')$ iff $C'\subseteq C''$ and $\A''\red_{\Sigma[C']}=\A'$;
\item $\Omega:(\K,\preceq)\to \Sig$ is the forgetful functor mapping each $(\Sigma[C'],\A')$ to $\Sigma[C']$;
\item $\M:(\K,\preceq)\to \Class^{op}$ is the model functor which maps each $(\Sigma[C'],\A')\in \K$ to $\{\A'\}$.
\end{enumerate}
\end{example}
%
Example~\ref{ex:dls} shows that $(\K,\preceq)$ can have a more complex structure than $(\P_\alpha(C),\subseteq)$.
%
\begin{example} \label{ex:ott}
Let $\Phi$ be any set of sentences defined over a signature $\Sigma$.
\begin{enumerate}[topsep=3pt]
\item $\K=\{(\Sigma[C'],\Phi) \mid C'\in\P_\alpha(C)\}$, and
 $(\Sigma[C'],\Phi)\preceq(\Sigma[C''],\Phi)$ iff $C'\subseteq C''$;
\item $\Omega:(\K,\preceq)\to \Sig$ is the forgetful functor mapping each $(\Sigma[C'],\Phi)$ to $\Sigma[C']$;
\item $\M:(\K,\preceq)\to \Class^{op}$ is the functor which maps each $(\Sigma[C'],\Phi)\in \K$ to $|\Mod(\Sigma[C'],\Phi)|$,
the class of $\Sigma[C']$-models which satisfy $\Phi$.
\end{enumerate}
\end{example}
%
\begin{definition}[Semantic Forcing Property] \label{def:semantic-forcing}
The semantic forcing property $\mathbb{P}(\Omega,\M)=(P,\leq,\Delta,f)$ is defined as follows:
\begin{enumerate}[topsep=3pt]
\item A condition $p$ is a pair $(\kappa_p, \Phi_p)$,
where $\kappa_p\in \K$ and $\Phi_p\subseteq_\alpha \Sen(\Omega(\kappa_p))$ such that $\M(\kappa_p) \cap \Phi_p^\bullet\neq\emptyset$, that is, there exists at least one model in $\M(\kappa_p)$ which satisfies $\Phi_p$.
%
\item $p\leq q$ iff $\kappa_p\preceq \kappa_q$ and $\Phi_p\subseteq \Phi_q$, for all conditions $p=(\kappa_p, \Phi_p), q=(\kappa_q, \Phi_q)\in P$.
%
\item $\Delta:(P,\leq)\to \Sig$ is the functor mapping each condition $p=(\kappa_p,\Phi_p)\in P$ to $\Omega(\kappa_p)\in |\Sig|$.
%
\item Let $f(p)= \Sen_0(\Omega(\kappa_p)) \cap (\M(\kappa_p) \cap \Phi_p^\bullet)^\bullet$, 
for all conditions $p\in P$.
In other words,
$f(p)$ is the set of atomic sentences satisfied by all models of $\Phi_p$ from $\M(\kappa_p)$.
\end{enumerate}
\end{definition}
%
From a category theory perspective, several observations are worth noting.
%
\begin{remark} \label{rem:cat}
Definition~\ref{def:semantic-forcing} describe the following mathematical structures:
\begin{itemize}[topsep=3pt]
\item $\Lambda:(P,\leq)\to (\K,\prec)$, defined by $\Lambda(p)=\kappa_p$ for all $p\in P$, is a monotone function such that $\Delta=\Lambda\comp\Omega$.
\item $\Gamma:(P,\leq)\to \Set$, defined by $\Gamma(p)=\Phi_p$ for all $p\in P$, is a functor such that the inclusion $\subseteq ~: \Gamma\Rightarrow (\Lambda\comp\Omega\comp\Sen)$ is a natural transformation, that is:
\begin{enumerate}[topsep=3pt]
\item $\Gamma(p)\subseteq\Sen(\Delta(p))$ for all conditions $p\in P$, and
\item $\Gamma(p)\subseteq \Gamma(q)$ for all relations $(p\leq q)\in(P,\leq)$.
\end{enumerate}
%
\begin{center}
\begin{tikzcd}[column sep=small,row sep=small]
(P,\leq) \ar[rrrr,bend left=20,"\Gamma"{above right=0pt and 3pt}, ""{below right= 0pt and 5pt,name=U}]  \ar[dr,bend right=10,"\Lambda",swap]& & & & \Set\\
& (\K,\preceq) \ar[rr,bend right=5,"\Omega",swap]& \ar[Rightarrow,from = U,"\subseteq"] & \Sig \ar[ur,bend right=10,"\Sen",swap] & 
\end{tikzcd}
\hspace{1cm}
\begin{tikzcd}[row sep=small]
(\K,\preceq) \ar[dr,bend right=20,"\Omega",swap] \ar[rr,bend left=20pt,"\M", ""{below,name=U}] &  & \Class^{op}\\
& \Sig \ar[ur,bend right=20,"|\Mod|",swap]  \ar[Rightarrow,from = U,"\subseteq"] & 
\end{tikzcd}
\end{center}
%
\end{itemize}
\end{remark}
%
Let $p\in P$ be a condition.
\begin{enumerate}[topsep=3pt]
\item We let $\Mod(p)$ denote $\M(\Lambda(p))\cap \Gamma(p)^\bullet$, the class of models in $\M(\Lambda(p))$ satisfying $\Gamma(p)$.
\item We write $p\models \phi$ iff $\phi$ is satisfied by all models in $\Mod(p)$, in symbols, $\Mod(p)\models \phi$. 
\end{enumerate}
%
The perspective of category theory can be disregarded if the reader is not familiar with it.
However, Remark~\ref{rem:cat} lays the groundwork for a generalization to an abstract level, as defined by the notion of institution~\cite{gog-ins}.

We define a notion of distance between conditions, which provides a principled method for regulating the addition of Henkin constants from $C$ to the starting signature $\Sigma$.

\begin{definition}[Distance \& weak forcing]
The distance between two conditions $p$ and $q$, with $p\leq q$, is defined as the number of constants and sentences that must be added to $p$ to obtain $q$, that is, $d(p,q):=\card(\Delta(q)\setminus\Delta(p))+\mathrm{card}(\Gamma(q)\setminus\Gamma(p))$.
%
A condition $p$ weakly forces $\phi$, in symbols, $p\Vdash^w \phi$, 
if for all $q\geq p$ there exists $r\geq q$ such that $d(q,r)< \omega$ and $r\Vdash \phi$.
\end{definition}
%
Using Lemma~\ref{lemma:fp}~(\ref{fp-2}) and the reflexivity of $\leq$, 
it is not difficult to show that $p\Vdash \phi$ implies $p\Vdash^w \phi$.
In the classical setting, weak forcing does not involve any notion of distance:
$p\Vdash^w \phi$ if and only if, 
for all $q\geq p$, there exists $r\geq q$ such that $r\Vdash \phi$; and this, in turn, holds if and only if $p\Vdash \neg\neg\phi$.
The notion of distance is introduced in this paper to extend the applicability of the results to all signatures -- including those of singular cardinality -- by controlling the number of constants introduced during the construction of the generic sets.
%
\begin{theorem} [Semantic Forcing Theorem] \label{th:sfp}
For all conditions $p \in P$ and all sentences $\phi\in\Sen(\Delta(p))$, we have:
\begin{enumerate*}[label=(\alph*)]
\item\label{fst1} $p\models \phi$ ~~~iff~~~
\item\label{fst2} $p\Vdash^{w} \phi$
\end{enumerate*}
\end{theorem}
%
%%% %%% %%% %%% %%% %%% %%% %%% %%%
\section{Downward L\"owenheim-Skolem Theorem}\label{sec:DLS}
Consider a semantic forcing property $\mathbb{P}(\Omega,\M)$ such that the functors $\Omega$ and $\M$ are defined as in Example~\ref{ex:dls}.
We use $\mathbb{P}(\Omega,\M)$ to give a proof of Downward L\"owenheim-Skolem Theorem.
%
The key to proving any result based on forcing is the construction of a generic set for a given condition $p$.
%
\begin{lemma}[Existence]\label{lemma:DLS}
Let  $\mathbb{P}(\Omega,\M)=(P,\leq,\Delta,f)$ be a semantic forcing property such that the functors $\Omega$ and $\M$ are defined as in Example~\ref{ex:dls}.
Any condition $p\in P$ belongs to a generic set $G_p$.
\end{lemma}
%
\begin{proof}
Let $pair:\alpha\times\alpha\to\alpha$ be any bijection such that for all ordinals $i,j,\beta<\alpha$ if $\beta=pair(i,j)$ then $i\leq\beta$.
For any condition $q\in P$, let $\gamma(q):\alpha\to \Sen(\Delta(q))$ be an enumeration of the sentences in $\Sen(\Delta(q))$.

First, we define an increasing chain of conditions $p_0\leq p_1\leq \ldots \leq p_\beta\leq \ldots$
with the following property: for all ordinals $\beta<\alpha$ there exists $n<\omega$ such that $d(p,p_{\beta})\leq n\cdot\mathrm{card}(\beta)$.\footnote{When $\alpha$ is a singular cardinal, the entire set of constants $C$ may be used along a chain $\{p_i\}_{i<\beta}$ with $\beta<\alpha$. 
To avoid this uncontrolled increase in the size, we use the distance measure $d$.}
We proceed by induction on ordinals $\beta<\alpha$.
\begin{description}
\item[($\beta=0$)] Let $p_0\coloneqq p$.
%
\item[($\beta\Rightarrow\beta+1$)]
Let $(i,j)\coloneqq pair^{-1}(\beta)$.
Notice that $i\leq\beta$, which means $p_i$ is already defined. 
Condition $p_{\beta+1}$ is obtained by adding a finite set of constants from $C$ and a finite set of sentences to $p_\beta$, according to a case distinction detailed below:
\begin{description}
\item[($q\Vdash \gamma(p_i,j)$ for some $q\geq p_\beta$)]
Since $q\Vdash \gamma(p_i,j)$, by Theorem~\ref{th:sfp}, $q\models \gamma(p_i,j)$.
It follows that $r\coloneqq (\Lambda(p_{\beta}),\Gamma(p_{\beta})\cup\{\gamma(p_i,j)\})\in P$. 
Since $r \vDash \gamma(p_i,j)$,
by Theorem~\ref{th:sfp}, there exists $p_{\beta+1}\geq r$ such that $p_{\beta+1}\Vdash\gamma(p_i,j)$ and $d(r,p_{\beta+1})<\omega$.
By induction hypothesis, there exists $n<\omega$ such that $d(p,p_{\beta+1})\leq n\cdot\card(\beta+1)$.
\item[($q\not\Vdash \gamma(p_i,j)$ for every $q\geq p_\beta$)] 
Let $p_{\beta+1}\coloneqq p_\beta$.
In this case, $p_{\beta+1}\Vdash \neg\gamma(p_i,j)$.
\end{description}
\item[($\beta<\alpha$ is a limit ordinal)]
At this point, for all $i<\beta$ we have defined $p_i=(\Lambda(p_i),\Gamma(p_i))$, 
where $\Lambda(p_i)=(\Delta(p_i),\A_i)$ and 
$\A_i$ is an expansion of $\A$ to $\Delta(p_i)$.
\begin{itemize}[topsep=3pt]
\item Let $C_{\Lambda(p_\beta)}\coloneqq\bigcup_{i<\beta}C_{\Lambda(p_i)}$ and 
$\Delta(p_\beta)=\Sigma[C_{\Lambda(p_\beta)}]$ and
$\Gamma(p_\beta)\coloneqq\bigcup_{i<\beta}\Gamma(p_i)$.
%
Since $\card(C_{\Lambda(p_i)})\leq\card(\beta)$ for all $i<\beta$,
we get $\card(C_{\Lambda(p_\beta)})\leq\card(\beta)<\alpha$.
Similarly, $\card(\Gamma(p_\beta))\leq\card(\beta)<\alpha$.
\item A model $\A_i\in \M(\Lambda(p_i))$, where $i<\beta$, can be regarded as a pair $(\A,g_i:C_{\Lambda(p_i)}\to \A)$, 
consisting of the model $\A$ and an interpretation of the constants in $C_{\Lambda(p_i)}$ into the elements of $\A$ given by the function $g_i$.
Define $g_\beta\coloneqq \bigcup_{i<\beta}g_i$, let $\A_\beta\coloneqq(\A,g_\beta)$ and $\Lambda(p_\beta)\coloneqq(\Delta(p_\beta),\A_\beta)$.
%
\item Let $p_\beta\coloneqq(\Lambda(p_\beta),\Gamma(p_\beta))$.
By its definition, $\A_\beta\red_{\Delta(p_i)}=\A_i$ for all $i<\beta$.
Since $\A_i\models\Gamma(p_i)$ for all $i<\beta$,
by satisfaction condition, 
$\A_\beta\models\Gamma(p_\beta)$.
Hence, $p_\beta$ is well-defined.
Since for all $i<\beta$ there exists $n_i\in\mathbb{N}$ such that $d(p,p_i)\leq n_i\cdot \card(i)$, 
we get $d(p,p_{\beta})\leq \card(\beta)$.
\end{itemize}
\end{description}
%
Secondly, one can easily show that $G_p\coloneqq\{q\in P\mid q\leq p_\beta \text{ for some } \beta < \alpha \}$ is a generic set.
\end{proof}
%
\begin{theorem}[Downward L\"owenheim-Skolem Theorem] \label{th:DLS}
Let $\A$ be a model over a signature $\Sigma=(S,F,L)$ of power $\alpha$ such that $\card(\A_s)\geq \alpha$ for some sort $s\in S$.
Then there exists an elementary submodel $\B$ of $\A$ such that $\card(\B_s)=\alpha$.
\end{theorem}
