\section{Omitting Types Theorem}\label{sec:OTT}
%%% %%% %%% %%% %%% %%% %%% %%% %%%
Consider a semantic forcing property $\mathbb{P}(\Omega,\M)$ such that $\Omega$ and $\M$ are defined as in Example~\ref{ex:ott}.
We use $\mathbb{P}(\Omega,\M)$ to give a proof of Omitting Types Theorem in $\TA$.
%
\begin{definition}[Types]
A type for a signature $\Sigma$ of power $\alpha$ is a set of sentences $T$ defined over $\Sigma[X]$, where $X$ is a block of variables for $\Sigma$ such that $\alpha^{\card(X)}\leq\alpha$.
A $\Sigma$-model $\A$ \emph{realizes} $T$ if $\B\models T$ for some expansion $\B$ of $\A$ to $\Sigma[X]$.
$\A$ \emph{omits} $T$ if $\A$ does not realize $T$.
\end{definition}
%
For all infinite cardinals $\alpha$ we have $\alpha<\alpha^{\mathrm{cf(\alpha)}}$, where $\mathrm{cf}(\alpha)$ is the cofinality of $\alpha$.
Consequently, the condition $\alpha^{\card(X)}\leq\alpha$ implies that $\card(X)<\mathrm{cf}(\alpha)$. 
The converse also holds under the assumption of GCH.
The inequality $\alpha^{\card(X)}\leq\alpha$ ensures that the number of mappings from $X$ to the set of ground terms -- that is, substitutions $\theta:X\to \emptyset$ -- does not exceed $\alpha$.
Note that if $\alpha$ is the cardinality of real numbers and $X$ is countable then $\alpha^{\card(X)}\leq\alpha$ holds.
%
\begin{definition}[Isolated types] \label{def:isolate}
Let $\Sigma$ be a signature of power $\alpha$.
A set of sentences $\Phi\subseteq\Sen(\Sigma)$ is said to \emph{isolate} a type $T\subseteq\Sen(\Sigma[X])$ iff there exist:
\begin{itemize}[topsep=3pt]
\item an $S$-sorted set of new constants $D$ for $\Sigma$ with $\card(D)<\alpha$,
\item a set $\Gamma \subseteq  \Sen(\Sigma[D])$ with $\card(\Gamma)<\alpha$ and such that $T\cup \Gamma$ is satisfiable over $\Sigma[D]$, and
\item a substitution $\theta:X\to D$,
\end{itemize}
such that  $\Phi\cup\Gamma\models_{\Sigma[D]}\theta(T)$.
We say that $\Phi$ \emph{locally omits} $T$ if $\Phi$ does not isolate $T$.
\end{definition}
%
Our definitions for type, realization, and isolation align with those provided in \cite{GainaBK23},
with one key difference: we do not restrict the block of variables $X$ to be finite.
Definition~\ref{def:isolate} is similar to the definition of locally omitting types for first-order logic without equality from \cite{keisler01}.
If the fragment $\frag$ of $\TA$ is closed under Boolean operators and first-order quantifiers, the above definition coincides with the classical one for isolated types.
\begin{lemma} \label{lemma:otp}
Assume that 
\begin{enumerate*}[label=(\alph*)]
\item $\frag$ is  semantically closed under Boolean operators and first-order quantifiers, and
\item $\frag$ is compact or $\alpha=\omega$.
\end{enumerate*}
Then $\Phi\subseteq \Sen(\Sigma)$ isolates a type $T\subseteq\Sen(\Sigma[X])$ iff there exists a set of sentences $\Gamma\in \P_\alpha(\Sen(\Sigma[X]))$ such that $T\cup\Gamma$ is satisfiable over $\Sigma[X]$ and $\Phi\cup \Gamma\models_{\Sigma[X]} T$.
\end{lemma}
The proof is conceptually identical with the proof of \cite[Lemma 45]{GainaBK23}.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{definition}[Omitting Types Property] \label{def:OTP}
Let $\alpha$ be an infinite cardinal.
The fragment $\frag$ has $\alpha$-Omitting Types Property ($\alpha$-OTP) whenever
\begin{enumerate}[topsep=3pt] 
\item for all signatures $\Sigma$ of power $\alpha$,
\item all satisfiable sets of sentences $\Phi\subseteq \Sen(\Delta)$, and
\item all families of types $\{T_i\subseteq \Sen(\Sigma[X_i]) \mid i<\alpha \}$,
\end{enumerate}
such that $\Phi$ locally omits $T_i$ for all $i<\alpha$,
there exists a $\Sigma$-model of $\Phi$ which omits $T_i$ for all $i<\alpha$.
If $\alpha=\omega$ then we say that $\frag$ has OTP rather than $\frag$ has $\omega$-OTP.
\end{definition}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{theorem}[Omitting Types Theorem] \label{th:OTT}
Let $\Sigma$ be a signature of power $\alpha$.
If $\alpha>\omega$ then we assume that fragment $\frag$ is compact.
Then $\frag$ has $\alpha$-OTP.
\end{theorem}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
Any fragment $\frag$ obtained from $\TA$ by 
\begin{enumerate*}[label=(\alph*)]
\item discarding a subset of sentence or/and action operators, and
\item restricting the category of signatures -- without prohibiting signature extensions with constants --
\end{enumerate*}
has $\omega$-OTP.
Any star-free fragment $\frag$ of $\TA$  is compact and therefore has $\alpha$-OTP for all cardinals cardinal $\alpha\geq \omega$.
In particular, many-sorted first-order logic has $\alpha$-OTP for all cardinals cardinal $\alpha\geq \omega$.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{lemma}\label{lemma:inf}
Assume that $\frag$ is closed under Boolean operators and first-order quantifiers.
Let $\Sigma=(S,F)$ be a signature, where
 $S\coloneqq\{s_n  \mid n>0\}$ and $F\coloneqq \emptyset$.
\begin{itemize}[topsep=3pt]
\item Let $\phi_n\coloneqq \Exists{z_n}\top \Rightarrow \Exists{x_1,\dots,x_n} \bigwedge_{i\neq j} x_i\neq x_j$ be a $\Sigma$-sentence,
where $n>0$,
where $z_n$ is a variable of sort $s_n$, and 
$x_1,\dots,x_n$ are variables of sort $s_1$.
Note that $\phi_n$ states that if there exists an element of sort $s_n$ then there exists at least $n$ elements of sort $s_1$.
%
\item Let $T \coloneqq \{\Exists{x_1,\dots,x_n} \bigwedge_{i\neq j} x_i\neq x_j \land \bigwedge_{i=1}^n  y \neq x_i  \mid n > 0\}$ be a type with one variable $y$ of sort $s_1$, expressing that there are infinitely many elements of sort $s_1$.
\end{itemize}
%
Then $\Phi\coloneqq\{\phi_n \mid n>0\}$ locally omits $T$.
\end{lemma}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
Let $\Sigma$, $\Phi$ and $T$ be as defined in Lemma~\ref{lemma:inf}.
Recall that the set of Henkin constants  is $C=\{C_{s_n}\}_{n<\omega}$, where $\card(C_{s_n})=\omega$ for all $n<\omega$. 
Note that $(\Sigma, \Phi)$ is a satisfiable first-order presentation that does not involve the transitive closure operator $*$, as it contains no relation symbols.
By Lemma~\ref{lemma:inf}, $\Phi$ locally omits $T$. 
By Theorem~\ref{th:OTT}, there exists a model $\A$ for $\Phi$ which omits $T$.
Since every model of $(\Sigma[C], \Phi)$ realizes $T$, the model $\A$ must be constructed over a proper subset of $C$, in contrast to the classical first-order logic approach, where results are developed over the entire $\Sigma[C]$. Consequently, the OTT as presented in \cite{keisler73, Chang:1990, Hodges:1997, gai-ott,GainaBK23} does not apply in this context. 
%%%
\begin{lemma} \label{lemma:unwanted}
Let $\Sigma=(S,F)$ be a signature such that $S\coloneqq \{s\}$ and $F\coloneqq\{c:\to s\mid c\in\mathbb{R}\}$, where $\mathbb{R}$ denotes the set of real numbers.
Let $T\coloneqq \{x_i\neq c \mid c:\to s\in F \text{ and } i<\omega\}$ be a type with a countably infinite number of variables from $X\coloneqq\{x_i\mid i<\omega\}$.
Then $\Phi$ locally omits $T$, where $\Phi$ is any countable and satisfiable set of $\Sigma$-sentences.
\end{lemma}
By Theorem~\ref{th:OTT}, there exists a model $\A$ of $\Phi$ which omits $T$. 
Consequently, the number of elements in $\A$ that are not denotations of real numbers -- considered unwanted elements -- is finite and may therefore be regarded as negligible.
Lemma~\ref{lemma:unwanted} demonstrates that types involving infinitely many variables are not difficult to construct and can naturally arise in applications.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{$\omega$-Completeness} \label{sec:complete}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
Although a transition algebra may satisfy a given set of sentences, it may not be relevant to the intended semantics.
In many cases, formal methods practitioners are interested in the properties of a restricted class of transition algebras, such as:
\begin{enumerate*}[label=(\alph*)]
\item those reachable through a set of constructor operators, 
\item those with a finite number of elements, or
\item those satisfying both conditions.
\end{enumerate*}
Using Omitting Types Theorem we can extend the completeness result in \cite{go-icalp24} to fragments obtained from $\frag$ by restricting the semantics to the aforementioned transition algebras.
Concretely, given a sound and complete proof system for $\frag$, we introduce additional proof rules so that the resulting system remains sound and complete for fragments of $\frag$ obtained by restricting the class of transition algebras to those of interest.

\begin{definition}[Entailment relation] \label{def:entail} 
 An \emph{entailment relation} is a family of binary relations between sets of sentences $\vdash=\{\vdash_\Sigma\}_{\Sigma\in|\Sig^\frag|}$ with the following properties:
%
\begin{longtable}{l l}
$(Monotonicity)\Frac{\Phi_1\subseteq \Phi_2}{\Phi_2 \vdash \Phi_1}$
& $(Transitivity)\Frac{\Phi_1\vdash \Phi_2 \Space \Phi_2\vdash \Phi_3}{\Phi_1\vdash \Phi_3}$\\ \\
%  
$(Union)\Frac{\Phi_1\vdash \varphi_2 \text{ for all }\phi_2\in\Phi_2}{\Phi_1\vdash\Phi_2}$ & 
$(Translation)\Frac{\Phi_1 \vdash_\Sigma \Phi_2}{\chi(\Phi_1) \vdash_{\Sigma'} \chi(\Phi_2)}$ where $\chi:\Sigma\to\Sigma'$ \\
\end{longtable}
An entailment relation $\vdash$ is sound (complete) if $\vdash\subseteq \models$ ($\models \subseteq \vdash$).
\end{definition}
Completeness fails when $\frag$ is closed under $*$ and includes uncountable signatures~\cite[Proposition 15]{go-icalp24}.
Therefore, throughout this section, 
we assume that the fragment $\frag$ 
has only countable signatures if it is closed under $*$. 
 Additionally, we assume that $\frag$ is semantically closed under Boolean operators.

%%% %%% %%%
\subparagraph*{Constructor-based algebras}
Many algebraic structures can be naturally described using a set of constructor operators.
For instance, numbers can be defined using a constant $zero$ and a unary function symbol $succ$,
while lists can be defined using a constant $nil$ and a binary function symbol $cons$.

%%% %%% %%%
\begin{definition} [Constructor-based algebras]
Let $\Sigma=(S,F,L)$ be a signature and 
$F^c\subseteq F$ a subset of constructor operators.
We let $\Sigma^c$ denote the signature of constructors $(S,F^c)$.
The constructors create a partition of the set of sorts $S$.
\begin{enumerate}[topsep=3pt]
\item A sort $s\in S$ that has a constructor -- i.e., there exists a constructor $(\sigma:w\to s)\in F^c$ -- is called \emph{constrained}.
We denote the set of all constrained sorts by $S^c$.
\item A sort that is not constrained is called \emph{loose}.
We denote the set of all loose sorts by $S^l$.
\end{enumerate}
A \emph{constructor-based transition algebra} $\A$ is a transition algebra for which there exist
\begin{enumerate*}[label=(\alph*)]
\item a set of loose variable $Y=\{Y_s\}_{s\in S^l}$ and
\item an expansion $\B$ of $\A$ to $\Sigma[Y]$,
\end{enumerate*}
such that $\B\red_{\Sigma^c[Y]}$ is reachable.
\end{definition}
%
\begin{example}[Lists]\label{ex:list}
Let $\Sigma=(S,F)$ be an algebraic signature such that
\begin{enumerate*}[label=(\alph*)]
\item $S=\{Elt,List\}$ and
\item $F=\{empty:\to List, \_;\_:List~Elt\to List, add:List~List\to List\}$.
\end{enumerate*}
Let $F^c=\{empty:\to List, \_;\_:List~Elt\to List\}$ be a set of constructors.
\begin{itemize}[topsep=3pt]
\item $Elt$ is a loose sort while $List$ is a constrained sort.
\item Let $\A$ be a constructor-based algebra obtained from $T_{\Sigma^c}(\omega)$ by interpreting $add$ as follows: 
\begin{enumerate*}[label=(\alph*)]
\item $add^\A(\ell,empty)=\ell$, and
\item $add^\A(\ell,\ell';n)=add^\A(\ell,\ell');n$ 
\end{enumerate*}
for all lists of natural numbers $\ell,\ell'\in\A_{List}$ and all natural numbers $n\in\A_{Elt}$.
\end{itemize}
\end{example}
%
By refining the syntax with a subset of constructor operators and restricting the semantics to constructor-based transition algebras, we obtain a new logic $\frag^c$ from $\frag$. This restriction in semantics alters the satisfaction relation $\models$ between sets of sentences: $\Phi \models^c \phi$ means that all constructor-based transition algebras of $\Phi$ are models of $\phi$. Consequently, there may exist non-restricted models of $\Phi$ that do not satisfy $\phi$.
In order to obtain an institution, we need to restrict the class of signature morphisms such that the reduct of a constructor-based algebra is again a constructor-based algebra~\cite{gai-cbl,DBLP:journals/tcs/Gaina13,DBLP:journals/tcs/BidoitHK03}.
So, the category of signatures of $\frag^c$ has 
\begin{enumerate}[topsep=3pt]
\item objects of the form $(S,F^c\subseteq F,L)$, where $(S,F,L)$ is a signature in $\frag$, and 
\item signature morphisms of the form $\chi:(S,F^c\subseteq F,L)\to (S',F'^c\subseteq F',L')$, where
\begin{enumerate*}[label=(\alph*)]
\item $\chi:(S,F,L)\to (S',F',L')$ is a signature morphism in $\frag$,
\item constructors are preserved, that is, $\chi(F^c)\subseteq F'^c$, and
\item constructors are reflected, that is, for all $\sigma':w'\to \chi(s)\in F'^c$ there exists $\sigma:w\to s\in F^c$ such that $\chi(\sigma:w\to s)=\sigma':w'\to\chi(s)$.
\end{enumerate*}
\end{enumerate}
%%% %%% %%%
\subparagraph{Finite algebras} 
%%% %%% %%%
Computer science applications often focus on properties that hold in finite structures. Therefore, we refine the fragment $\frag^c$ defined above to include constructor-based transition algebras, where certain distinguished sorts are interpreted as finite sets.
Let $\frag^f$ be a fragment of $\frag^c$ obtained by 
\begin{enumerate*}[label=(\alph*)]
\item refining the syntax with a subset of sorts of finite domains, and
\item by restricting constructor-based models such that the sorts for finite domains are interpreted as finite sets.
\end{enumerate*}
This means that the category of signatures in $\frag^f$ has 
\begin{enumerate}[topsep=3pt]
\item objects of the form $(S^f\subseteq S,F^c\subseteq F,L)$, where $(S,F^c\subseteq F,L)$ is a signature in $\frag^c$, and
\item arrows of the form $\chi:(S^f\subseteq S,F^c\subseteq F,L)\to (S'^f\subseteq S',F'^c\subseteq F',L')$ such that
\begin{enumerate*}[label=(\alph*)]
\item $\chi:(S,F^c\subseteq F,L)\to (S',F'^c\subseteq F',L')$ is a signature morphism in $\frag^c$, and
\item the finite sorts are preserved, that is, $\chi(S^f)\subseteq S'^f$.
\end{enumerate*}
\end{enumerate}

\begin{definition}
Let $\vdash$ be an entailment relation for $\frag$.
The entailment relation $\vdash^f$ for $\frag^f$ is the least entailment relation that includes $\vdash$ and it is closed under the following proof rules: 
%
\begin{enumerate}[topsep=3pt]
\item $(CB)~\Frac{\Phi\vdash^f \Forall{var(t)}\psi(t) \text{ for all }  t\in T_{\Sigma^c}(Y)}{\Phi \vdash^f \Forall{x}\psi(x)}$,
where 
\begin{enumerate*}[label=(\alph*)]
\item $x$ is a variable of constrained sort,
\item $Y$ is a $S^l$-sorted block of variables such that $\card(Y_s)=\omega$ for all loose sorts $s\in S^l$, and
\item $var(t)$ is the set of all variables occuring in $t$.
\end{enumerate*}
\item $(FN)~\Frac{\Phi \cup \{ \Gamma_{\overline{n}} \}\vdash^f \psi \text{ for all } \overline{n}\in\omega^\alpha }{\Phi \vdash^f \psi}$, where
\begin{enumerate}[topsep=3pt]
\item  $\alpha\coloneqq \card(S^f)$ and $\{s_i\}_{i<\alpha}$ is an enumeration of $S^f$,
%
\item $\Gamma_{\overline{n}}$ denotes the set of sentences $\{\gamma_{s_i,\overline{n}(i)}\mid i<\alpha\}$ for all tuples $\overline{n}\in \omega^\alpha$, where 
%
\begin{itemize}[topsep=3pt]
\item $\overline{n}(i)$ is the natural number in position $i$ from $\overline{n}$, for all tuples $\overline{n}\in\omega^\alpha$ and  all $i<\alpha$;
%
\item $\gamma_{s,n}$ denotes the sentence $\Forall{x_1,\dots,x_{n+1}} \lor_{i\neq j} x_i= x_j$,
for all natural numbers $n<\omega$, all sorts $s\in S^f$ and
all variables $x_1,\dots,x_{n+1}$ of sort $s$.
\end{itemize}
\end{enumerate}
Note that $\gamma_{s,n}$ states that the sort $s$ has at most $n$ elements.
If $n=0$ then $\gamma_{0,s}=\Forall{x_1}\vee\emptyset$, which is satisfied only by transition algebras whose carrier set for the sort $s$ is empty. 
\end{enumerate}
\end{definition}
%
$(CB)$ asserts that to prove the property $\psi$ for an arbitrary element $x$, it suffices to establish $\psi$ for all constructor terms $t$ in $T_{(S,F^c)}(Y)$.
$(CB)$ should be disregarded if the base logic $\frag$ is not closed under first-order quantification.
$(FN)$ states that the number of elements of any sort in $S^f$ is finite.
%
It is straightforward to show that $\vdash^f$ is sound for $\frag^f$ provided that $\vdash$ is sound for $\frag$.
Establishing completeness is generally more challenging, but it can be achieved with the help of the OTP.
%%% %%% %%%
\begin{theorem}[Completeness] \label{th:complete}
The entailment relation $\vdash^f$ is complete for $\frag^f$ if $\vdash$ is complete for $\frag$ and $\frag$ has OTP.
\end{theorem}
