\section{Proof of the results presented in Section~\ref{sec:compact}}
\begin{proof}[Proof of Theorem~\ref{th:expansion} (Categoricity)]
For simplicity, we assume that $S$ is a singleton $\{s\}$.
We consider the non-trivial case when  $\alpha\coloneqq\card(\A_s)$ is an infinite cardinal.

First, let $\Sigma^\circ \coloneqq (S,F^\circ,L^\circ)$, where
\begin{itemize}[topsep=3pt]
\item $F^\circ \coloneqq F \cup \{c_i:\to s \mid i< \alpha\} \cup \{ \sigma_\beta : s~s\to s \mid \beta\leq \alpha \text{ is an infinite successor cardinal}\}$ $~\cup~ \{ \delta_\beta: s \to s \mid \beta \leq\alpha \text{ is a limit cardinal}\}$; 
\item $L^\circ \coloneqq L\cup \{ \preceq, \suc \}$.
\end{itemize}
We have defined an inclusion of signatures $\iota^\circ:\Sigma\hookrightarrow\Sigma^\circ$.

Secondly, we define a $\iota^\circ$-expansion $\A^\circ$ of $\A$.
Without loss of generality, we assume that $\A_s=\alpha$.
For each uncountable cardinal $\beta\leq \alpha$, we define:
\begin{description}
\item [($\beta$ is a successor cardinal)]
In this case, we have $\beta=\lambda^+$ for some cardinal $\lambda$.

By GCH, there exists a bijective function $b_\beta:\beta\to 2^\lambda$.

\item [($\beta$ is a limit cardinal)] 
In this case, $\beta$ can be expressed as the supremum of a strictly increasing sequence of smaller cardinals, that is,
$\beta=sup\{\lambda_i \mid i< cf(\beta) \}$, where 
$cf(\beta)$ is the cofinality of $\beta$ and
$\{\lambda_i\}_{i< cf(\beta)}$ is an increasing sequence of cardinals strictly smaller than $\beta$.
Let $f_\beta: cf(\beta)\to \beta$ defined by $f_\beta(i)=\lambda_i$ for all $i<cf(\beta)$.
\end{description}
%
Let $\A^\circ$ be a $\iota^\circ$-expansion of $\A$ defined as follows:
\begin{itemize}[topsep=3pt]
\item $c_i^{\A^\circ}=i$ for all all ordinals $i<\alpha$.
%
\item 
$\sigma_{\lambda^+}^{\A^\circ}(i,j)=
\left\{ \begin{array}{l l}
b_{\lambda^+}(i)(j) & \text{if } i < \lambda^+ \text{ and } j <\lambda \\ 
2 & \text{otherwise}
\end{array}\right.$,
for all infinite cardinals $\lambda$.

Each $i<\lambda^+$ can be regarded as a function in $2^\lambda$ and for all $j<\lambda$, the ordinal $\sigma^{\A^\circ}_{\lambda^+}(i,j)$ is the results of the applying $i$ to $j$.
%
\item $\delta_\beta^{\A^\circ}(i)=
\left\{\begin{array}{l l}
f_\beta(i) & \text{if } i<cf(\beta)\\
2 & \text{otherwise}
\end{array}\right.$,
for all limit cardinals $\beta$.

In this case, $\beta$ is the supremum of $\{\delta_\beta^{\A^\circ}(i)\}_{i<cf(\beta)}$.
%
\item $\preceq^{\A^\circ}\coloneqq \{ (i,j) \mid \text{ for all ordinals } i\leq j <\alpha \}$.
%
\item $\suc^{\A^\circ}\coloneqq \{(i,i+1)\mid \text{for all natural numbers }i<\omega\}$.
\end{itemize}

Thirdly, we show that each model of $(\Sigma^\circ,Th(\A^\circ))$ is isomorphic to $\A^\circ$.
Since $\A^\circ$ is reachable by the constants in $\{c_i\}_{i<\alpha}$, that is, 
$\A\models \Forall{x} \lor\{x=c_i\mid i<\alpha\}$,
it suffices to show that each model of $(\Sigma^\circ,Th(\A^\circ))$ is reachable by the constants in $\{c_i\}_{i<\alpha}$.
Concretely, given a $\Sigma^\circ$-model $\B$, we show that the following property holds: 
\begin{equation}
\{c_i^\B\mid i< \beta \} = \{a\in \B_s \mid a \prec^\B c_\beta\} \text{ for all infinite cardinals }\beta\leq\alpha.
\end{equation}
Obviously, $\{c_i^\B\mid i< \beta \} \subseteq \{a\in \B_s \mid a <^\B c_\beta\}$.
Therefore, we focus on the other inclusion.
We proceed by induction on infinite cardinals $\beta\leq\alpha$.
\begin{description}
\item[($\beta=\omega$)]
Assume that $a\prec^\B c_\omega^\B$, that is, $a\preceq^\B c_\omega^\B$ and $a\neq c_\omega^\B$. 
Notice that $\A^\circ$ satisfies the following sentences:
\begin{enumerate}[label=(S\arabic*)]
\item $\Forall{x} x\prec c_\omega \Rightarrow c_0 \suc^* x$, which says that any element smaller than $c_\omega$ is obtained from $c_0$ by applying successor finitely many times;
%
\item  $c_i \suc c_{i+1}\land c_i \prec c_\omega$ for all $i<\omega$, which says than $c_{i+1}$ is the successor of $c_{i+1}$ and $c_i$ is strictly small than $c_\omega$; and
\item $\Forall{x} x\prec c_\omega \Rightarrow (\Exists{y} x \suc y \land \Forall{z} x \suc z\Rightarrow z=y)$,
which says that any element smaller than $c_\omega$ has a unique successor.
\end{enumerate}
By the first sentence, $c_0^\B (\suc^\B)^*a$, which implies $c_0^\B (\suc^\B)^k a$ for some $k<\omega$.
By the first conjunct of the second sentence, $c_0^\B (\suc^\B)^k c_k^\B$.  
By the second conjunct of the second sentence and the third sentence, $c_k=a$.
%
\item [($\beta=\lambda^+$ for some infinite cardinal $\lambda$)]
Assume that $a\prec^\B c_\beta^\B$.
Notice that $\A^\circ$ satisfies the following sentences:
\begin{enumerate}[label=(S\arabic*)]
\setcounter{enumi}{3}
\item \label{sen:S4}
$\Forall{x,y} x\prec c_\beta \land y\prec c_\lambda \Rightarrow \sigma(x,y)\prec c_2$;
%
\item \label{sen:S5}
$\Forall{x,y} x\prec c_\beta \land y\prec c_\beta \Rightarrow ((\Forall{z} z\prec c_\lambda \Rightarrow \sigma(x,z)=\sigma(y,z))\Rightarrow x=y)$,
which together with the above sentence says that any element smaller than $c_\beta$ can be regarded as a function from $\lambda$ to $2$; and
%
\item \label{sen:S6} $c_i\prec c_\beta$ for all $i < \beta$.
\end{enumerate}
Let $F:\lambda\to 2$ be the function defined by $F(i)=j$ iff $\sigma^\B_\beta(a,c_i^\B)=c_j^\B$ for all $i<\lambda$ and all $j<2$.
By the first two sentences above, $F$ is well-defined.
Let $k\coloneqq b_\beta^{-1}(F)$ and we show that $a=c_k^\B$:
\begin{enumerate}[label=(\alph*)]
\item Let $i<\lambda$ and $j<2$ such that $\sigma^\B_\beta(a,c_i^\B)=c_j^\B$.
We have $\sigma^{\A^\circ}_\beta(c_k^{\A^\circ},c_i^{\A^\circ}) = b_\beta(k)(i) = F(i)= j = c_j^{\A^\circ}$.
Since $\A^\circ\models \sigma_\beta(c_k,c_i)=c_j$, we get $\B\models\sigma_\beta(c_k,c_i)=c_j$.
It follows that $\sigma^\B_\beta(a,c_i^\B) = c_j^\B=\sigma^\B_\beta(c_k^\B,c_i^\B)$.
Hence, $\sigma^\B_\beta(a,c_i^\B)=\sigma^\B_\beta(c_k^\B,c_i^\B)$ for all $i<\lambda$.
%
\item By the induction hypothesis, $\sigma^\B_\beta(a,d)=\sigma^\B_\beta(c_k^\B,d)$ for all $d\prec^\B c_\lambda^\B$.
%
\item By the fifth sentence \ref{sen:S5}, we get $a=c_k^\B$.
\end{enumerate}
%
\item[($\beta\leq \alpha$ is a limit cardinal)]
Let $a\prec^\B c_\beta^\B$.
Notice that $\A^\circ$ satisfies the following sentences:
\begin{enumerate}[label=(S\arabic*)]
\setcounter{enumi}{6}
\item \label{sen:S7} $\Forall{x}x\prec c_\beta \Rightarrow \Exists{y} y \prec c_{cf(\beta)} \land x \prec \delta_\beta(y)$; and
%
\item \label{sen:S8} $\delta_\beta(c_i)=c_{f_\beta(i)}$ for all $i<cf(\beta)$.
\end{enumerate}
By the seventh sentence \ref{sen:S7}, 
there exists $d\prec^\B c_{cf(\beta)}^\B$ such that $a\prec^\B\delta_\beta^\B(d)$.
Since there are no inaccessible cardinals, $cf(\beta)<\beta$. 
By induction hypothesis, $d=c_i^\B$ for some $i<cf(\beta)$.
By the eighth sentence \ref{sen:S8}, $\delta_\beta^\B(c_i^\B)=c_{f_\beta(i)}^\B$.
It follows that $a\prec^\B c_{f_\beta(i)}^\B$, where $f_\beta(i)<\beta$. 
By induction hypothesis, $a=c_k^\B$ for some $k<f_\beta(i)$.
\end{description}
\end{proof}
%%% Corollary USL %%%
\begin{proof}[Proof of Corollary~\ref{cor:usl}]
Let $\Sigma=(S,F,L)$ be a signature such that $S=\{s\}$, $F=\emptyset$ and $L=\{\preceq\}$.
\begin{enumerate}
\item Let  $\beta<\alpha$ be two infinite cardinals.
Let $\A$ be a $\Sigma$-model such that $\A_s=\beta$ and $\preceq^\A=\leq$, the order among ordinals.
By Theorem~\ref{th:expansion}, there exist a sort preserving inclusion of signatures $\iota^\circ:\Sigma\hookrightarrow \Sigma^\circ$ and a $\iota^\circ$-expansion $\A^\circ$ of $\A$ such that all models of $Th(\A^\circ)$ are isomorphic with $\A^\circ$.
There is no model $\B$ of $Th(\A^\circ)$ such that $\card(\B_s)=\alpha$. 
Therefore, $\alpha$-ULS does not hold. 

\item Let $\alpha$ be an infinite cardinal.
Let $\A$ be a $\Sigma$-model such that $\A_s=\alpha$ and $\preceq^\A=\leq$, the order among ordinals.
By Theorem~\ref{th:expansion}, there exist an inclusion of signatures $\iota^\circ:\Sigma\hookrightarrow \Sigma^\circ$ and a $\iota^\circ$-expansion $\A^\circ$ of $\A$ such that all models of $Th(\A^\circ)$ are isomorphic with $\A^\circ$.
Let $\Sigma^\diamond$ be the signature obtained from $\Sigma^\circ$ by adding
\begin{enumerate*}[label=(\alph*)]
\item a new sort $st$,
\item a new set of constant symbols $\{ct_i:\to st\}_{i<\alpha}$, and
\item a function symbol $ft:st\to s$.
\end{enumerate*}
We define the following sets of $\Sigma^\diamond$-sentences:
\begin{enumerate}
\item $\Phi\coloneqq\{\Exists{y}\Forall{x} ft(x) \prec y \}\cup \{\Forall{x,y} ft(x)=ft(y)\Rightarrow x=y\}$, 
which says that $ft$ is bounded and injective;
\item $\Psi_\beta\coloneqq \{ ct_i \neq ct_j \mid i,j < \beta \text{ such that } i\neq j \}$ for all cardinals $\beta<\alpha$,
which implies that $\card(\B_{st})\geq \beta$ for any model $\B$ of $\Psi_\beta$; and
\item $T_\beta\coloneqq Th(\A^\circ) \cup \Phi\cup \Psi_\beta$.
\end{enumerate}
Let $\Psi_\alpha\coloneqq \bigcup_{\beta<\alpha} \Psi_\beta$ and $T_\alpha\coloneqq Th(\A^\circ) \cup \Phi\cup \Psi_\alpha$.
Notice that $\card(\B_{st})\geq \alpha$ for any model $\B$ of $\Psi_\alpha$.
It is not difficult to check that $T_\beta$ is satisfiable for all $\beta<\alpha$,
while $T_\alpha$ is not satisfiable:
\begin{itemize}[topsep=3pt]
\item[] Suppose towards a contradiction that there exists a model $\B$ of $T_\alpha$.
Since $\B\models \Psi_\alpha$, we have $\card(\B_{st})\geq\alpha$.
Since $\B\models Th(\A^\circ)$, $\card(\B_s)=\card(\A^\circ_s)=\alpha$.
Since $\B\models \Phi$, $ft^\B:\B_{st}\to \B_s$ is injective and bounded, which implies $\card(\B_{st}) < \card(\B_s)$.
Since $\card(\B_{st})\geq\alpha$ and $\card(\B_s)=\alpha$, we get $\alpha<\alpha$, which is a contradiction.
\end{itemize}
\end{enumerate}
\end{proof}
