\section{Proofs of the results presented in Section~\ref{sec:semantic-forcing}}
%%% %%% %%% %%% %%% %%% %%% %%% %%%
\begin{lemma} \label{lemma:sfp}
Assume a condition $p\in P$,
an atomic sentence $\varphi\in\Sen_0(\Delta(p))$, 
a sentence $\phi\in\Sen(\Delta(p))$ and 
a set of sentences $\Phi\subseteq \Sen(\Delta(p))$.
\begin{enumerate}
\item \label{lemma:sfp-1} $p\models\varphi$ iff $f(p)\models \varphi$ iff $\varphi\in f(p)$.

\item \label{lemma:sfp-2} $p\models\phi$ implies $q\models \phi$, for all relations $(p\leq q)\in (P,\leq)$.

\item \label{lemma:sfp-3} $p\models \Phi$ iff
for all $q\geq p$ there exists $r\geq q$ such that $r\models\Phi$.
\end{enumerate}
\end{lemma}
%
\begin{proof}
We only prove the backwards implication of the third statement.
Suppose towards a contradiction that $p\not\models\Phi$.
Then $\A\models\neg\phi$ for some $\phi\in \Phi$ and some $\A\in\Mod(p)$.
Let $q\coloneqq (\Lambda(p),\Gamma(p)\cup\{\neg\phi\})$.
Notice that $q\geq p$ and for all $r\geq q$, we have $r\models \neg\phi$. 
It follows that for all $r\geq q$, we have $r\not\models\Phi$, which is a contradiction.
\end{proof}
%
First statement of  Lemma~\ref{lemma:sfp} show that a condition $p$ satisfies an atomic sentence $\varphi$ if and only if $\varphi$ is a semantic consequence of the atomic sentences of $p$.
The second statement establises that the ordering relation among conditions preserves the satisfaction of sentences.
The third statement asserts that a condition $p$ satisfies a set of sentences $\Phi$ if and only if $\Phi$ is satisfied by all conditions in all trees of conditions  rooted at $p$.
%
\begin{lemma} \label{lemma:up}
For any condition $p \in P$, the following hold:
\begin{enumerate}
%		
\item  \label{lemma:up1} 
If $p\models (\act_1\comp\act_2)(t_1,t_2)$ then $q\models \act_1(t_1,c)$ and $q\models \act_2(c,t_2)$ 
for  some constant $c\in C$ and some condition $q \geq p$ such that $d(p,q)<\omega$.
%
\item  \label{lemma:up2} 
If $p\models (\act_1\cup\act_2)(t_1,t_2)$ then $q\models \act_1 (t_1,t_2)$ or $q\models \act_2(t_1,t_2)$
for some condition $q \geq p$ such that $d(p,q)<\omega$.
%
\item  \label{lemma:up3} 
If $p\models \act^*(t_1,t_2)$ then $q\models \act^n(t_1,t_2)$ 
for some natural number $n<\omega$ and some condition $q \geq p$ such that $d(p,q)<\omega$.
%
\item  \label{lemma:up4} 
If $p\models \vee\Phi$ then $q\models \phi$ 
for some sentence $\phi\in\Phi$ and some condition $q \geq p$ such that $d(p,q)<\omega$.
%
\item  \label{lemma:up5} 
If $p\models \Exists{X}\phi$ then $q\models\chi(\phi)$ 
for some bijective signature morphism $\chi:\Delta(p)[X]\to \Delta(q)$ which preserves $\Delta(p)$ and some condition $q \geq p$ such that $d(p,q)<\omega$.
\end{enumerate}
\end{lemma}
%
\begin{proof}
Let $p\in P$ be a condition.
\begin{enumerate}
\item Assume $p \models (\act_1\comp\act_2)(t_1,t_2)$.
Since $\Mod(p)\neq\emptyset$, there exists $\A\in \Mod(p)$.
It follows that $\A\models (\act_1\comp\act_2)(t_1,t_2)$. 
We have $(t_1^\A,d)\in \act_1^\A$ and $(d,t_2^\A)\in \act_2^\A$ for some $d\in \A_s$,
where $s$ is the sort of $t_1$ and $t_2$.
Let $c\in C\setminus C_{\Lambda(p)}$ be a constant of sort $s$.
Let $\B$ be an expansion of $\A$ to $\Delta(p)[c]$ which interprets $c$ as $d$. 
By our assumptions, there exists $\ell\succeq\Lambda(p)$ such that $C_\ell=C_{\Lambda(p)}\cup\{c\}$ and $\B\in \M(\ell)$.
Let $q\coloneqq (\ell,\Gamma(p)\cup\{\act_1(t_1,c),\act_2(c,t_2)\})$ and notice that $d(p,q)<\omega$.
By satisfaction condition, $\B\models \Gamma(p)$.
By definition, $(t_1^\B,d)\in \act_1^\B$ and $(d,t_2^\B)\in \act_2^\B$.
It follows that $\B\models \{\act_1(t_1,c),\act_2(c,t_2)\}$.
Therefore, $\B\in \Mod(q)$, which means that $q$ is well-defined.
%
\item Let $\A\in\Mod(p)$.
Since $p\models (\act_1\cup\act_2)(t_1,t_2)$, 
we have $\A\models (\act_1\cup\act_2)(t_1,t_2)$.
By semantics, $\A\models \act_i(t_1,t_2)$ for some $i\in \{1,2\}$.
Let $q\coloneqq (\Lambda(p),\Gamma(p)\cup\{\act_i(t_1,t_2)\})$ and notice that $d(p,q)<\omega$.
We have $\A\in\Mod(q)$, which means $q\in P$.
%
\item Let $\A\in\Mod(p)$.
Since $p\models \act^*(t_1,t_2)$, 
we have $\A\models \act^*(t_1,t_2)$.
By semantics, $\A\models \act^n(t_1,t_2)$ for some $n<\omega$.
Let $q\coloneqq (\Lambda(p),\Gamma(p)\cup\{\act^n(t_1,t_2)\})$ and notice that $d(p,q)<\omega$.
We have $\A\in\Mod(q)$, which means $q\in P$.
%
\item This case is similar to the second one.
%
\item 
Let $\A\in\Mod(p)$.
Since $p\models\Exists{X}\phi$, we have $\A\models \Exists{X}\phi$. 
Let $\B$ be an expansion of $\A$ to $\Delta(p)[X]$ such that $\B\models\phi$.
Since $X$ is finite, there exists a sort preserving injection $\vartheta:X\to C\setminus C_{\Lambda(p)}$.
Let $C_1=\vartheta(X)$ and let $\vartheta':X\to C_1$ be the co-restriction of $\vartheta:X\to C\setminus C_{\Lambda(p)}$ to $C_1$. 
There exists a bijection $\chi:\Delta(p)[X]\to \Delta(p)[C_1]$ which extends $\vartheta':X\to C_1$ and preserves $\Delta(p)$.
Let $\D\coloneqq\Mod(\chi)^{-1}(\B)$. 
Since $\B\models\phi$, by satisfaction condition, 
$\D\models \chi(\phi)$.
Since $\D\red_{\Delta(p)}=\A$ and $\A\models \Gamma(p)$, 
by satisfaction condition,
$\D\models\Gamma(p)$.
%
\begin{center}
\begin{tikzcd}
\B \ar[r,dotted,no head] & \Delta(p)[X] \ar[rr,"\chi"] & & \Delta(p)[C_1]=\Omega(\ell) & \ar[l,dotted,no head] \D \\
& \A \ar[r,dotted,no head] & \ar[ul,hook] \Delta(p) \ar[ur,hook] &
\end{tikzcd}
\end{center}
%
By our assumptions there exists $\ell>\Lambda(p)$ such that 
\begin{enumerate*}[label=(\alph*)]
\item $\Omega(\ell)=\Delta(p)[C_1]$, and
\item $\D\in\M(\ell)$. 
\end{enumerate*}
Let $q\coloneqq(\ell,\Gamma(p)\cup\{\chi(\phi)\})$ and notice that $d(p,q)<\omega$.
Since $\D\models\Gamma(p)$ and $\D\models \chi(\phi)$, 
we have $\D\in \Mod(q)$, which means that $q$ is well-defined.
\end{enumerate}
\end{proof}
%
Lemma~\ref{lemma:up} lays the foundation for proving the following important theorem, which establishes the completeness of the forcing relation with respect to the satisfaction relation.
%%% Semantic Forcing Theorem %%%
\begin{proof}[Proof of Theorem~\ref{th:sfp} (Semantic Forcing Theorem)]
We proceed by induction on the structure of $\phi$.
\begin{description}
\item[$\varphi\in\Sen_0(\Delta(p))$]

To show $\ref{fst1}\Rightarrow\ref{fst2}$, we assume $p\models\varphi$.
\begin{proofsteps}{17em}
let $q\geq p$ be arbitrarily fixed & \\
%
$\varphi\in f(p)$ & by Lemma~\ref{lemma:sfp}(\ref{lemma:sfp-1}), since $p\models\varphi$ and $\varphi\in\Sen_0(\Delta(p))$\\
$p\Vdash \varphi$ & by the definition of $\Vdash$\\
$q\Vdash \varphi$ & since $p\leq q$\\
$p\Vdash^{w}\varphi$ & since $d(q,q)=0$ and $q\Vdash\varphi$
\end{proofsteps}


To show $\ref{fst2}\Rightarrow\ref{fst1}$, we assume $p\Vdash^w\varphi$. Suppose a contradiction that $p\not\models\varphi$.
\begin{proofsteps}{21em}
$\A\models \neg\varphi$ for some $\A\in\Mod(p)$ & since $p\not\models\varphi$ \\
$\A\in \M(\Lambda(p))\cap (\Gamma(p)\cup\{\neg\varphi\})^\bullet$ & since $\A\in\Mod(p)$ and $\A\models \neg\varphi$ \\
$q\coloneqq (\Lambda(p),\Gamma(p)\cup\{\neg\varphi\})$ belongs to $P$  & since $\A\in\Mod(q)$ \\
$r\not \models \varphi$ for all $r\geq q$ & since $\neg\varphi\in \Gamma(q)$\\
$\varphi \not\in f(r)$ for all $r\geq q$ & by Lemma~\ref{lemma:sfp}(\ref{lemma:sfp-1}) \\
$r\not \Vdash \varphi$ for all $r\geq q$ &  by the definition of $\Vdash$\\
$p\not\Vdash^w\varphi$ & since $q\geq p$ and $r\not\Vdash\varphi$ for all $r\geq q$\\
contradiction & since $p\not\Vdash^w\varphi$ and $p\Vdash^w\varphi$
\end{proofsteps}
%
\item[$(\act_1\comp\act_2)(t_1,t_2)$] 
To show $\ref{fst1}\Rightarrow\ref{fst2}$, we assume that $p\models (\act_1\comp\act_2)(t_1,t_2)$.
\begin{proofsteps}{20em}
let $q\geq p$ be arbitrarily fixed & \\
%
$q\models (\act_1\comp\act_2)(t_1,t_2)$ & by Lemma~\ref{lemma:sfp}(\ref{lemma:sfp-2})\\
%
$r\models \act_1(t_1,c)$ and $r\models \act_2(c,t_2)$ for some $c\in C$ and some 
$r \geq q$ such that $d(q,r)<\omega$ & 
by  Lemma~\ref{lemma:up}(\ref{lemma:up1})\\
%
$r\Vdash^w \act_1(t_1,c)$ and $r\Vdash^w \act_2(c,t_2)$ & 
by induction hypothesis \\
%
$u\Vdash \act_1(t_1,c)$ and $u\Vdash \act_2(c,t_2)$ for some $u\geq r$ such that $d(r,u)<\omega$ & 
by the definition of $\Vdash^w$ \\
% 
$u\Vdash(\act_1\comp\act_2)(t_1,t_2) $ and $ d(q,u)<\omega$ & by the definition $\Vdash$ and $d$ \\
%
$p\Vdash^w(\act_1\comp\act_2)(t_1,t_2)$ & 
since for each $q\geq p$ there exists $u\geq q$ s.t. $d(q,u)<\omega$ and $u\Vdash (\act_1\comp\act_2)(t_1,t_2)$
\end{proofsteps}
%

To show $\ref{fst2}\Rightarrow\ref{fst1}$, we assume that $p\Vdash^w (\act_1\comp\act_2)(t_1,t_2)$.
\begin{proofsteps}{20em}
let $q\geq p$ be an arbitrary condition & \\
%
there exists $r\geq q$ such that $r\Vdash(\act_1\comp\act_2)(t_1,t_2)$ & 
since $p\Vdash^w (\act_1\comp\act_2)(t_1,t_2)$\\
% 
$r\Vdash \act_1(t_1,t)$ and $r\Vdash\act_2(t,t_2)$ \newline
for some $t\in T_{\Delta(r)}$ &
by the definition of $\Vdash$\\
%
$p\Vdash^w\act_1(t_1,t)$ and $p\Vdash^w\act_2(t,t_2)$ &
since for all $q\geq p$ there exist $r\geq q$ and $t\in T_{\Delta(r)}$ s.t. $r\Vdash \act_1(t_1,t)$ \& $r\Vdash\act_2(t,t_2)$\\
%
$p\models \act_1(t_1,t)$ and $p\models\act_2(t,t_2)$ & 
by induction hypothesis\\
%
$p\models (\act_1\comp\act_2)(t_1,t_2)$ & 
by semantics
\end{proofsteps}
%
\item[$(\act_1\cup\act_2)(t_1,t_2)$]
To show $\ref{fst1}\Rightarrow\ref{fst2}$, we assume that $p\models (\act_1\cup\act_2)(t_1,t_2)$.
\begin{proofsteps}{20em}
let $q\geq p$ be arbitrarily fixed & \\
%
$q\models (\act_1\cup\act_2)(t_1,t_2)$ & by Lemma~\ref{lemma:sfp}(\ref{lemma:sfp-2})\\
%
$r\models \act_1(t_1,t_2)$ or $r\models \act_2(t_1,t_2)$ for some
$r > q$ such that $d(q,r)<\omega$  & 
by  Lemma~\ref{lemma:up}(\ref{lemma:up2})\\
%
$r\Vdash^w \act_1(t_1,t_2)$ or $r\Vdash^w \act_2(t_1,t_2)$ & 
by induction hypothesis\\
%
$u\Vdash \act_1(t_1,t_2)$ or $u\Vdash \act_2(t_1,t_2)$ for some $u\geq r$ such that $ d(r,u)<\omega$ & 
by the definition of $\Vdash^w$, since $r\geq r$\\
% 
$u\Vdash(\act_1\cup\act_2)(t_1,t_2)$ and $d(q,u)<\omega$ & by the definition $\Vdash$ and $d$ \\
%
$p\Vdash^w(\act_1\cup\act_2)(t_1,t_2)$ & 
since for each $q\geq p$ there exists $u\geq q$ s.t. $d(q,u)<\omega$ and $u\Vdash (\act_1\cup\act_2)(t_1,t_2)$
\end{proofsteps}
%
To show $\ref{fst2}\Rightarrow\ref{fst1}$, 
we assume that $p\Vdash^w (\act_1\cup\act_2)(t_1,t_2)$.
\begin{proofsteps}{17em}
let $q\geq p$ be an arbitrary condition & \\
%
$r\Vdash(\act_1\cup\act_2)(t_1,t_2)$ for some $r\geq q$ & 
since $p\Vdash^w (\act_1\cup\act_2)(t_1,t_2)$\\
% 
$r\Vdash \act_1(t_1,t_2)$ or $r\Vdash\act_2(t_1,t_2)$ &
by the definition of $\Vdash$\\
%
$p\Vdash^w \act_1(t_1,t_2)$ or $p\Vdash^w\act_2(t_1,t_2)$ &
since for all $q\geq p$ there exists $r\geq q$ such that $r\Vdash \act_1(t_1,t_2)$ or $r\Vdash\act_2(t_1,t_2)$\\
%
$p\models \act_1(t_1,t_1)$ or $p\models\act_2(t_1,t_2)$ & 
by induction hypothesis\\
%
$p\models (\act_1\cup\act_2)(t_1,t_2)$ & 
by semantics
\end{proofsteps}
%
\item[$\act^*(t_1,t_2)$] 
To show $\ref{fst1}\Rightarrow\ref{fst2}$, we assume that $p\models \act^*(t_1,t_2)$.
\begin{proofsteps}{22em}
let $q\geq p$ be arbitrarily fixed & \\
%
$q\models\act^*(t_1,t_2)$ & by Lemma~\ref{lemma:sfp}(\ref{lemma:sfp-2})\\
%
$r\models \act^n(t_1,t_2)$ for some $n<\omega$ and some $r\geq q$ such that $d(q,r)<\omega$  & 
by  Lemma~\ref{lemma:up}(\ref{lemma:up3})\\
%
$r\Vdash^w \act^n(t_1,t_2)$ & 
by induction hypothesis \\
%
$u\Vdash \act^n(t_1,t_2)$ for some $u\geq r$ s.t. $d(r,u)<\omega$ & 
by the definition of $\Vdash^w$\\
% 
$u\Vdash\act^*(t_1,t_2)$ and $d(q,u)<\omega$ & by the definition $\Vdash$ and $d$ \\
%
$p\Vdash^w\act^*(t_1,t_2)$ & 
as for each $q\geq p$ there exists $u\geq q$ s.t. $d(q,u)<\omega$ and $u\Vdash \act^*(t_1,t_2)$
\end{proofsteps}
%
To show $\ref{fst2}\Rightarrow\ref{fst1}$, we assume that $p\Vdash^w \act^*(t_1,t_2)$.
\begin{proofsteps}{15em}
let $q\geq p$ be an arbitrary condition & \\
%
$r\Vdash\act^*(t_1,t_2)$ for some $r\geq q$ & 
since $p\Vdash^w \act^*(t_1,t_2)$\\
% 
$r\Vdash \act^n(t_1,t_2)$ for some $n<\omega$ &
since $r\Vdash \act^*(t_1,t_2)$\\
%
$p\Vdash^w \act^n(t_1,t_2)$ & 
since for all $q\geq p$ there exists $r\geq q$ s.t. $r\Vdash \act^n(t_1,t_2)$\\
%
$p\models \act^n(t_1,t_2)$ & 
by induction hypothesis\\
%
$p\models \act^*(t_1,t_2)$ & 
by semantics
\end{proofsteps}
%
\item [$\neg\phi$]
For $\ref{fst1}\Rightarrow\ref{fst2}$, 
assume that $p\models\neg\phi$.
For each $q\geq p$,
we show that $q\Vdash\neg\phi$.
\begin{itemize}[topsep=3pt]
\item[] 
Let $q\geq p$.
Suppose towards a contradiction that $q\not\Vdash\neg\phi$.
By the definition of forcing relation, there exists $r\geq q$ such that $r\Vdash\phi$.
It follows that $r\Vdash^w \phi$. 
By induction hypothesis, $r\vDash \phi$.
Since $p\models\neg\phi$ and $r\geq q\geq p$, 
we get $r\vDash \neg \phi$, which is a contradiction.
\end{itemize}
Hence, $p\Vdash^w\neg \phi$.

To show $\ref{fst2}\Rightarrow\ref{fst1}$, assume that $p\Vdash^w\neg\phi$.
Suppose towards a contradiction that $p\not\models\neg\phi$.
\begin{proofsteps}{18em}
there exists $\A\in\Mod(p)$ such that $\A\models\phi$ &
since $p\not\models\neg\phi$\\
%
let $q=(\Lambda(p),\Gamma(p) \cup \{\phi\}) $ &
$q$ is well-defined, since $\A\in\Mod(q)$\\
%
$q\models\phi$ &  since $q\models \Gamma(p)\cup\{\phi\}$\\
%
$q\Vdash^w\phi$ & by induction hypothesis\\
%
$r\Vdash\phi$ for some $r\geq q$ & 
since $q\geq q$ and $q\Vdash^w\phi$ \\
%
$u\Vdash\neg\phi$ for some $u\geq r$ & 
since $p\Vdash^w\neg\phi$ and $r\geq p$\\
%
$u\Vdash\phi$ & since $r\Vdash\phi$ and $u\geq r$\\
%
contradiction & since $u\Vdash\neg\phi$ and $u\Vdash\phi$
\end{proofsteps}
%
\item[$\lor\Phi$]
To show $\ref{fst1}\Rightarrow\ref{fst2}$, we assume that $p\models\lor\Phi$.
\begin{proofsteps}{20em}
let $q\geq p$ be an arbitrary condition & \\
%
$q\models \lor \Phi$ & by Lemma~\ref{lemma:sfp}(\ref{lemma:sfp-2})\\
%
$r\models \phi$ for some $\phi\in\Phi$ and some $r\geq q$ such that $d(q,r)<\omega$ & 
by  Lemma~\ref{lemma:up}(\ref{lemma:up4})\\
%
$r\Vdash^w\phi$ & by induction hypothesis\\
%
$u\Vdash \phi$ for some $u\geq r$ such that $d(r,u)<\omega$ & 
by the definition of $\Vdash^w$\\
%
$u\Vdash\lor\Phi$ and $d(q,u)<\omega$ & by the definition of $\Vdash$ and $d$ \\
%
$p\Vdash^w\lor\Phi$ & 
since for all $q\geq p$ there exists $u\geq q$ such that $d(q,u)<\omega$ and $u\Vdash\lor\Phi$
\end{proofsteps}
%
To show $\ref{fst2}\Rightarrow\ref{fst1}$, we assume $p\Vdash^w\lor \Phi$.
\begin{proofsteps}{17em}
let $q\geq p$ be an arbitrary condition & \\
%
$r\Vdash\lor\Phi$ for some $r\geq q$ & 
since $p\Vdash^w\lor \Phi$ \\
%
$r\Vdash\phi$ for some $\phi\in\Phi$ & 
by the definition of $\Vdash$ \\
%
$p\Vdash^w\phi$ & since for all $q\geq p$ there exists $r\geq q$ s.t. $r\Vdash\phi$\\
%
$p\models\phi$ & by induction hypothesis \\
%
$p\models\lor\Phi$ & by semantics 
\end{proofsteps}
%
\item[$\Exists{X}\phi$]
To show $\ref{fst1}\Rightarrow\ref{fst2}$, we assume that $p\models\Exists{X}\phi$.
\begin{proofsteps}{22em}
let $q\geq p$ be an arbitrary condition & \\
%
$q\models \Exists{X}\phi$ & by Lemma~\ref{lemma:sfp}(\ref{lemma:sfp-2})\\
%
$r\models \chi(\phi)$ 
for some bijection $\chi:\Delta(q)[X]\to\Delta(r)$ and 
some $r\geq q$ such that $d(q,r)<\omega$ & 
by  Lemma~\ref{lemma:up}(\ref{lemma:up5})\\
%
$r\Vdash^w \chi(\phi)$ & by induction hypothesis\\
%
$u\Vdash\chi(\phi)$ for some $u\geq r$ such that $d(r,u)<\omega$ & 
by the definition of $\Vdash^w$\\
%
$u\Vdash\Exists{X}\phi$ and $d(q,u)<\omega$ & by the definition of $\Vdash$ and $d$ \\
%
$p\Vdash^w\Exists{X}\phi$ & since for all $q\geq p$ there exists $u\geq q$ such that $d(q,u)<\omega$ and $u\Vdash\Exists{X}\phi$
\end{proofsteps}

To show $\ref{fst2}\Rightarrow\ref{fst1}$, we assume that $p\Vdash^w \Exists{X}\phi$.
\begin{proofsteps}{20em}
let $q\geq p$ be an arbitrary condition & \\
%
there exists $r\geq q$ such that $r\Vdash\Exists{X}\phi$ & 
since $p\Vdash^w \Exists{X}\phi$\\
% 
$r\Vdash \theta(\phi)$ 
for some $\theta:X\to \emptyset$ &
by the definition of $\Vdash$\\
%
$p\Vdash^w\theta(\phi)$ &
since for all $q\geq p$ there exist $r\geq q$ such that $r\Vdash \theta(\phi)$\\
%
$p\models \theta(\phi)$ & 
by induction hypothesis\\
%
$p\models \Exists{X}\phi$ & 
by semantics
\end{proofsteps}
%
\end{description}
\end{proof}
