\section{Proofs of the results presented in Section~\ref{sec:DLS}}
%
\begin{proof}[Proof of Theorem~\ref{th:DLS} (Downward L\"owenheim-Skolem Theorem)]
Let  $\mathbb{P}(\Omega,\M)$ be a semantic forcing property such that the functors $\Omega$ and $\M$ are defined as in Example~\ref{ex:dls}.
Let $p=((\Sigma,\A),\emptyset)$ be the least condition of $\mathbb{P}(\Omega,\M)$.
By Lemma~\ref{lemma:DLS}, $p$ belongs to a generic set $G$.
Let $\mu:\Delta\Rightarrow \Delta_G$ be a co-limit of $\Delta:(G,\leq)\to \Sig$ such that $\mu_q:\Delta(q)\hookrightarrow\Delta_G$ is an inclusion for all conditions $q\in G$.
By Theorem~\ref{th:gm}, there exists a reachable generic $\Delta_G$-model $\A_G$ for $G$.
For each $p=(\Lambda(p),\Gamma(p))\in G$, we let $\A_p$ denote the unique model from $\M(\Lambda(p))$.
Note that $\A_p$ can be regarded as a pair $(\A,g_p:C_{\Lambda(p)}\to \A)$, 
consisting of the model $\A$ and an interpretation of the constants in $C_{\Lambda(p)}$ into the elements of $\A$ given by the function $g_p$.
For all $(p\leq q)\in (G,\leq)$, we have $\A_q\red_{\Delta(p)}=\A_p$, which means $g_q|_{C_{\Lambda(p)}}=g_p$.
It follows that  $g \coloneqq \bigcup_{p\in G}g_p$ and $\B\coloneqq (\A,g)$ are well-defined.
We show that $\A_G$ is an elementary submodel of $\B$.
Since $\A_G$ is reachable, it suffices to show that $\A_G\models\phi$ implies $\B\models\phi$, for all sentences $\phi\in\Sen(\Delta_G)$.
\begin{proofsteps}{15em}
assume that $\A_G\models\phi$ & where $\phi\in\Sen(\Delta_G)$\\
$q\Vdash \phi$ for some $q\in G$ & $\A_G$ is a generic model for $G$\\
$q\Vdash^w\phi$ & since $q\Vdash \phi$\\
$q\models \phi$ & Theorem~\ref{th:sfp}\\
$\A_q\models \phi$ & since $\Mod(q)=\{\A_q\}$ \\
$\B\models\phi$ & by satisfaction condition, since $\B\red_{\Delta(q)}=\A_q$ and $\A_q\models \phi$ 
\end{proofsteps}
\end{proof}
