\section{Proof of the results presented in Section~\ref{sec:OTT}}
%%% %%% %%% %%% %%% %%% %%% %%% %%%
\begin{proof}[Proof of Theorem~\ref{th:OTT} (Omitting Types Theorem)]
Let  $\mathbb{P}(\Omega,\M)=(P,\leq,\Delta,f)$ be a semantic forcing property such that the functors $\Omega$ and $\M$ are defined as in Example~\ref{ex:ott}.
%
Let $\Phi$ be a satisfiable set of $\Sigma$-sentences.
%
Let $\{T_i\subseteq \Sen(\Sigma[X_i])\}_{i<\alpha}$ be a family of types for $\Sigma$ such that $\Phi$ locally omits $T_i$ for all $i<\alpha$. 
%
We show that there exists a model $\A$ of $\Phi$ which omits  $T_i$ for all $i<\alpha$.
%
The key point of the proof is to construct a generic set for the least condition $p\coloneqq((\Sigma,\Phi),\emptyset)$ of the semantic forcing property $\mathbb{P}(\Omega,\M)$.
\begin{itemize}[topsep=3pt]
\item Let $triple:\alpha\times\alpha\times\alpha\to\alpha$ be any bijection such that $\beta=triple(i,j,k)$ implies $i \leq \beta$ for all ordinals $i,j,k,\beta<\alpha$.
%
\item For each condition $q\in P$, let $\gamma(q):\alpha\to \Sen(\Delta(q))$ be an enumeration of the sentences in $\Sen(\Delta(q))$.
%
\item For each set $D\in\P_\alpha(C)$ and any block of variables $X$ such that $\alpha^{\card(X)}\leq \alpha$,
let $\Theta(X,D)$ denote the set of substitutions from $X$ to $D$.
Furthermore, if $\Theta(X,D)\neq\emptyset$ then we let $\theta(X,D):\alpha\to \Theta(X,D)$ be an enumeration of the substitutions in $\Theta(X,D)$.
\footnote{Since $\alpha^{\card(X_i)}\leq\alpha$ for all $i\in\alpha$, we have $\card(\Theta(X_i,C_{\Lambda(q)}))\leq\alpha$ for all $i<\alpha$ and all $q\in P$.}

\end{itemize}
%
First, we define an increasing chain of conditions $p_0\leq p_1\leq \ldots \leq p_\beta\leq \ldots$ with the following property:
for all ordinals $\beta<\alpha$ there exists $n<\omega$ such that $d(p,p_\beta)\leq n\cdot\mathrm{card}(\beta)$. 
We proceed by induction on ordinals $\beta<\alpha$.
\begin{description}
\item[($\beta=0$)] Let $p_0\coloneqq p$.
%
\item[($\beta\Rightarrow\beta+1$)]
Let $(i,j,k)\coloneqq triple^{-1}(\beta)$.
By our assumptions $i\leq\beta$. 
Therefore, the condition $p_i$ is already defined.
%
\begin{center}
\begin{tikzcd}
T_j  \ar[r,dotted,no head]& \Sen(\Sigma[X_j]) \ar[rr,"{\theta(X_j,C_{\Lambda(p_i)},k)}"] & & 
\Sen(\Delta(p_i)) \ar[r,hook]&  
\Sen(\Delta(p_\beta)) & \ar[l,dotted,no head] \Gamma(p_\beta)\\
& & \ar[ul,hook] \Sen(\Sigma) \ar[ur,hook] & \Phi  \ar[l,dotted,no head]
\end{tikzcd}
\end{center}
%
\begin{description}
\item[($\Theta(X_j,C_{\Lambda(p_i)})\neq\emptyset$)]
Since $\Phi$ locally omits $T_j$, 
$\Phi\cup \Gamma(p_\beta)\not\models_{\Delta(p_\beta)}\theta(X_j,C_{\Lambda(p_\beta)},k)(T_j)$.

It follows that $\Phi\cup\Gamma(p_\beta)\cup\{\neg\psi\} \not\models_{\Delta(p_\beta)}\bot$  for some $\psi\in\theta(X_j,C_{\Lambda(p_i)},k)(T_j)$.\

Let $q\coloneqq (\Lambda(p_\beta),\Gamma(p_\beta)\cup\{\neg\psi\})$.

Since $\Mod(q)=\Phi^\bullet\cap\Gamma(p_i)^\bullet\cap \{\neg \psi\}^\bullet\neq \emptyset$, we have $q\in P$.
\item[($\Theta(X_j,C_{\Lambda(p_i)})=\emptyset$)] 
Let $q\coloneqq p_\beta$.
\end{description}
We define $p_{\beta+1}$ as follows:
% 
\begin{description}
\item [($r\not\Vdash \gamma(p_i,j)$ for every $r\geq q$)] 
Let $p_{\beta+1}\coloneqq q$. 
In this case, $p_{\beta+1}\Vdash \neg\gamma(p_i,j)$.
\item[($r\Vdash\gamma(p_i,j)$ for some $r\geq q$)] 
Since $r\Vdash^w\gamma(p_i,j)$, by Theorem \ref{th:sfp}, $r\models \gamma(p_i,j)$.
%
It follows that $\Phi^\bullet\cap \Gamma(r)^\bullet \models_{\Delta(r)} \gamma(p_i,j)$ and
$\Phi^\bullet\cap \Gamma(r)^\bullet \cap \{\gamma(p_i,j)\}^\bullet\neq \emptyset$.
%
Since $\Gamma(q)\subseteq \Gamma(r)$, we have $\Phi^\bullet\cap \Gamma(q)^\bullet \cap \{\gamma(p_i,j)\}^\bullet\neq \emptyset$.
%
Therefore, $u\coloneqq (\Lambda(q),\Gamma(q)\cup \{\gamma(p_i,j)\})$ is well-defined. 
%
Since $u\models\gamma(p_i,j)$, by Theorem~\ref{th:sfp}, we obtain $u\Vdash^w \gamma(p_i,j)$.
%
There exists $p_{\beta+1}\geq u$ such that $d(u,p_{\beta+1})<\omega$ and $p_{\beta+1}\Vdash \gamma(p_i,j)$.
%
Since $d(p_\beta,u)<\omega$ and $d(u,p_{\beta+1})<\omega$, we get $d(p_\beta,p_{\beta+1})<\omega$.
%
By induction hypothesis, $d(p,p_\beta)<n_\beta \cdot \card(\beta)$ for some $n_\beta\in\omega$, which implies $d(p,p_{\beta+1})<n_{\beta+1} \cdot \card(\beta+1)$ for some $n_{\beta+1}\in \omega$.
\end{description}
%
\item[($\beta<\alpha$ is a limit ordinal)]
Since $(\Delta(p_i),\Gamma(p_i)\cup \Phi)$ is satisfiable for all $i<\beta$,
by compactness, 
$(\bigcup_{i<\beta} \Delta(p_i), (\bigcup_{i<\beta} \Gamma(p_i)) \cup \Phi)$ is satisfiable as well.
Since $\card(C_{\Lambda(p_i)})\leq\card(\beta)$ for all $i<\beta$,
we get $\card(C_{\Lambda(p_\beta)})\leq\card(\beta)<\alpha$.
Similarly, $\card(\Gamma(p_\beta))\leq\card(\beta)<\alpha$.

Hence, $p_\beta\coloneqq\bigcup_{i<\beta}p_i\in P$ is well-defined.
\end{description}
%
Secondly, we define a generic set $G\coloneqq\{ q\in P\mid q\leq p_\beta \text{ for some }\beta<\alpha\}$.
Let $C_G\coloneqq \bigcup_{\beta<\alpha}C_{\Lambda(p_\beta)}$ and
$\Delta_G\coloneqq\Sigma[C_G]$.
We show that $G$ is a generic set:
\begin{proofsteps}{17em}
let $\phi\in \Sen(\Delta_G)$ & \\
%
$\phi\in \Sen(\Delta(p_i))$ for some $i<\alpha$ &
since $\Delta_G=\Sigma[C_G]$ and $C_G = \bigcup_{\beta<\alpha}C_{\Lambda(p_\beta)}$ \\
%
$\phi=\gamma(p_i,j)$ for some $j<\alpha$ & 
since $\gamma(p_i)$ is an enumeration of $\Sen(\Delta(p_i))$\\
%
let $\beta\coloneqq triple(i,j,k)$ for some $k<\alpha$ & \\
%
$p_{\beta+1}\Vdash \gamma(p_i,j)$ or $p_{\beta+1}\Vdash \neg \gamma(p_i,j)$ & 
by the construction of  $p_0\leq p_1\leq\ldots$\\
%
$G\Vdash \phi$ or $G\Vdash \neg\phi$ &
since $\phi=\gamma(p_i,j)$ and $p_{\beta+1}\in G$
\end{proofsteps}
%
By Theorem~\ref{th:gm}, there exists a reachable generic $\Delta_G$-model $\A_G$ for $G$.
We show $\A_G\red_\Sigma\models\Phi$:
%
\begin{proofsteps}{17em}
$p_0\Vdash^w \phi$ for all $\phi\in \Phi$ & by Theorem~\ref{th:sfp}, since $p_0\models\phi$ for all $\phi\in \Phi$\\
%
$G\Vdash\phi$ for all $\phi\in\Phi$ & since $G$ is generic and $p_0\Vdash^w \phi$ for all $\phi\in \Phi$\\
%
$\A_G\models \phi$ for all $\phi\in\Phi$ & since $\A_G$ is a generic model for $G$\\
%
$\A_G\red_\Sigma\models\Phi$ & by satisfaction condition, since $\A_G\models\Phi$
\end{proofsteps}
%
Let $j<\alpha$ be any ordinal.
We show that $\A_G\red_\Sigma$ omits $T_j$.
%
\begin{proofsteps}{21em}
let $\B$ be an expansion of $\A_G\red_\Sigma$ to $\Sigma[X_j]$ & \\
%
$\A_G\red_\vartheta=\B$ for some subst. $\vartheta:X_j\to C_G$ &
since $\A_G$ is reachable over $\Delta_G$\\
%
$\vartheta(X_j)\subseteq C_{\Lambda(p_i)}$ for some $i<\alpha$ &
since $\card(X_j)< cf(\alpha)$\\
%
let \rlap{$\vartheta': X_j \to C_{\Lambda(p_i)}$ be the co-restriction of $\vartheta:X_j\to C_G$ to $C_{\Lambda(p_i)}$} & \\
%
$\vartheta'=\theta(X_j,C_{\Lambda(p_i)},k)$ for some $k<\alpha$ &
since $\theta(X_j,C_{\Lambda(p_i)})$ is an enumeration of all substitutions from $X_j$ to $C_{\Lambda(p_i)}$\\
%
let $\beta=triple(i,j,k)$ & \\
%
$\neg\psi\in \Gamma(p_{\beta+1})$ for some $\psi\in\theta(X_j,C_{\Lambda(p_i)},k)(T_j)$ & 
by the construction of $p_0\leq p_1\leq\ldots$\\
%
$p_{\beta+1}\models \neg\psi$ & by semantics\\
%
$p_{\beta+1}\Vdash^w\neg\psi$ & by Theorem~\ref{th:sfp}\\
%
$G\Vdash \neg\psi$ & since $G$ is generic and $p_{\beta+1}\in G$\\
%
$\A_G\models \neg\psi$ & since $\A_G$ is generic for $G$\\
%
$\A_G\not\models\theta(X_j,C_{\Lambda(p_i)},k)(T_j)$ & since $\psi\in \theta(X_j,C_{\Lambda(p_i)},k)(T_j)$\\
%
$\A_G\not\models\vartheta(T_j)$ & since $\vartheta(T_j)=\theta(X_j,C_{\Lambda(p_i)},k)(T_j)$\\
%
$\B\not\models T_j$ & by satisfaction condition for substitutions\\
%
$\A_G\red_\Sigma$ omits $T_j$ & since $\B$ is an arbitrary expansion of $\A_G\red_\Sigma$ to $\Sigma[X_j]$ for which we proved that $\B\not\models T_j$
\end{proofsteps}
\end{proof}
%%% %%% %%% %%% %%% %%% %%% %%% %%%
\begin{proof}[Proof of Lemma~\ref{lemma:inf}]
Suppose towards a contradiction that $\Phi\cup \Gamma\models_{\Sigma[y]} T$ for some finite set $\Gamma\subseteq\Sen(\Sigma[y])$ such that $\Phi\cup \Gamma$ is satisfiable over $\Sigma[y]$.
For each $n>0$, let 
\begin{enumerate}
\item $\Sigma_n\coloneqq (\{s_i\mid 0 < i\leq n \},\emptyset,\emptyset)$ be a signature, which is included in $\Sigma$, and
\item  $\Phi_n\coloneqq \{\phi_i\mid 0< i\leq n \}$  a set of $\Sigma_n$-sentences, which is included in $\Phi$.
\end{enumerate}
Since $\Gamma$ is finite, $\Gamma\subseteq \Sigma_k[y]$ for some $k > 0$.
We show that $\Phi_k\cup \Gamma\models_{\Sigma_k[y]} T$:
\begin{proofsteps}{20em}
let $\A$ be a model of $(\Sigma_k[y],\Phi_k\cup \Gamma)$ & \\
let $\B$ be the expansion of $\A$ to $\Sigma[y]$ \rlap{ which interprets $s_n$ as $\emptyset$ for all $n > k$} & \\
$\B\models \Phi_k\cup\Gamma$ & by satisfaction condition, since $\A\models \Phi_k\cup\Gamma$\\
$\B\models\phi_n$ for all $n>k$ & since $\B_{s_n}=\emptyset$ for all $n>k$\\
$\B\models \Phi$ & since $\B\models \Phi_k$ and $\B\models\phi_n$ for all $n>k$\\
$\B\models T$ & since $\Phi\cup \Gamma\models_{\Sigma[y]} T$
\end{proofsteps}
%
\noindent Since $\Phi_k\cup \Gamma$ is finite and $\Phi_k\cup \Gamma\models_{\Sigma_k[y]} T$, 
it follows that infinity can be modeled by a finite set of sentences, which is a contradiction with compactness.
Hence, $\Phi$ locally omits $T$.
\end{proof}
%
Let $\Sigma$, $\Phi$ and $T$ be as defined in Lemma~\ref{lemma:inf}.
Recall that $C=\{C_{s_n}\}_{n<\omega}$ is the set of all constants, and $\card(C_{s_n})=\omega$ for all natural numbers $n$. 
Notice that $(\Sigma,\Phi)$ is satisfiable and by Lemma~\ref{lemma:inf}, $\Phi$ locally omits $T$. 
By Theorem~\ref{th:OTT}, there exists a model $\A$ for $\Phi$ which omits $T$.
Since any model of $(\Sigma[C],\Phi)$ realizes $T$, the model $\A$ is constructed from a proper subset of $C$  in contrast to classical first-order logic, where results are developed over the entire $\Sigma[C]$.
