\section{Proofs of the results presented in Section~\ref{sec:complete}}

\begin{lemma}\label{lemma:list}
Let $\Sigma$ be the signature defined in Example~\ref{ex:list}.
Let $\Phi$ be a set of $\Sigma$-sentences which defines $add:List~List\to List$ by induction on the second argument:
\begin{enumerate*}[label=(\alph*)]
\item $\Forall{x}add(x,empty)=x$ and
\item $\Forall{x,y,e} add(x,y;e)=add(x,y);e$
\end{enumerate*} 
where $x$ and $y$ are variables of sort $List$ while $e$ is a variable of sort $Elt$.
\begin{enumerate}
\item $\Phi\models^c\Forall{x,y,z}add(add(x,y),z)=add(x,add(y,z))$ and
\item $\Phi\not\models\Forall{x,y,z}add(add(x,y),z)=add(x,add(y,z))$, 
\end{enumerate}
where $x$, $y$ and $z$ are variables of sort $List$.
\end{lemma}
%
\begin{proof}[Proof of Lemma~\ref{lemma:list}]
First, 
notice that the following proof rule is sound in $\frag^c$.
\begin{longtable}{l l l}
$(CB)~\Frac{\Phi\vdash^c \Forall{var(t)}\psi(t) \text{ for all }  t\in T_{\Sigma^c}(Y)}{\Phi \vdash^c \Forall{x}\psi(x)}$\\
\end{longtable}
%
\noindent where 
\begin{enumerate*}[label=(\alph*)]
\item $x$ is a variable of constrained sort,
\item $Y$ is a $S^l$-sorted block of variables such that $\card(Y_s)=\omega$ for all loose sorts $s\in S^l$, and
\item $var(t)$ is the set of all variables occuring in $t$.
\end{enumerate*}
$(CB)$ asserts that to prove the property $\psi$ for an arbitrary element $x$, it suffices to establish $\psi$ for all constructor terms $t$ in $T_{\Sigma^c}(Y)$.


Then prove that $\Phi\models^c\Forall{x,y,z}add(add(x,y),z)=add(x,add(y,z))$, where $x$, $y$ and $z$ are variables of sort $List$.
Let $Y$ be a countably infinite block of variables of sort $Elt$.
We show that 
$\Phi\models_{\Sigma[\overline{x},\overline{y},\overline{z}]} add(add(\overline{x},\overline{y}),\overline{z})=add(\overline{x},add(\overline{y},\overline{z}))$,
where 
$\overline{x}$, $\overline{y}$ and $\overline{z}$ are lists of variables from $Y$, that is,
\begin{enumerate*}[label=(\alph*)]
\item $\overline{x}=empty;x_1;\dots;x_n$, where $x_i\in Y$ for all $i\in\{1,\dots,n\}$,
\item $\overline{y}=empty;y_1;\dots;y_m$, where $y_i\in Y$ for all $i\in\{1,\dots,m\}$ and
\item $\overline{z}=empty;z_1;\dots;z_k$, where $z_i\in Y$ for all $i\in\{1,\dots,k\}$.
\end{enumerate*}
We proceed by induction on the structure of $\overline{z}$:
\begin{enumerate}[label=(\alph*)]
\item Since $\Phi\models_{\Sigma[\overline{x},\overline{y}]} add(add(\overline{x},\overline{y}),empty)=add(\overline{x},\overline{y})$ and 

$\Phi\models_{\Sigma[\overline{x},\overline{y}]} add(\overline{x},add(\overline{y},empty))=add(\overline{x},\overline{y})$, we get

$\Phi\models_{\Sigma[\overline{x},\overline{y}]}  add(add(\overline{x},\overline{y}),empty)=add(\overline{x},add(\overline{y},empty))$.

\item Since $\Phi\models_{\Sigma[\overline{x},\overline{y},\overline{z},e]} add(add(\overline{x},\overline{y}),\overline{z};e)=add(add(\overline{x},\overline{y}),\overline{z});e$ 
by induction hypothesis, 
$\Phi\models_{\Sigma[\overline{x},\overline{y},\overline{z},e]} add(add(\overline{x},\overline{y}),\overline{z};e)=add(\overline{x},add(\overline{y},\overline{z}));e$.

Since $\Phi\models_{\Sigma[\overline{x},\overline{y},\overline{z},e]} add(\overline{x},add(\overline{y},\overline{z};e))=add(\overline{x},add(\overline{y},\overline{z}));e$,
it follows that 

$\Phi\models_{\Sigma[\overline{x},\overline{y},\overline{z},e]} add(add(\overline{x},\overline{y}),\overline{z};e)=add(\overline{x},add(\overline{y},\overline{z};e))$.  
\end{enumerate}
%
Since $\Phi\models_{\Sigma[\overline{x},\overline{y},\overline{z}]} add(add(\overline{x},\overline{y}),\overline{z})=add(\overline{x},add(\overline{y},\overline{z}))$,
by semantics, we have 
$\Phi\models_{\Sigma}\Forall{\overline{x},\overline{y},\overline{z}} add(add(\overline{x},\overline{y}),\overline{z})=add(\overline{x},add(\overline{y},\overline{z}))$ 
for all lists $\overline{x}$, $\overline{y}$ and $\overline{z}$ with elements from $Y$.
By soundness of $(CB)$, we obtain $\Phi\models^c\Forall{x,y,z}add(add(x,y),z)=add(x,add(y,z))$, where $x$, $y$ and $z$ are variables of sort $List$.

For the second statement, we construct a $\Sigma$-model $\B$ such that $\B\models\Phi$ and $\B\not\models\Forall{x,y,z}add(add(x,y),z)=add(x,add(y,z))$.
Let $\Sigma'$ be the signature obtained from $\Sigma^c$ by adding a new constant $nil:\to List$.
The $\Sigma$-model $\B$ is obtained from $T_{\Sigma'}(\omega)\red_{\Sigma^c}$\footnote{This means that $\B_{Elt}=\omega$ and $\B_{List}$ consists of lists of one of the forms $empty$, $(empty;m_1;\dots;m_k)$, $nil$  or $(nil;n_1;\dots;n_l)$, 
where $n_i$ and $m_j$ are natural numbers.} 
by interpreting $add$ as follows:
\begin{enumerate}[label=(\alph*)]
\item $add^\B(\ell,empty)=\ell$,
\item $add^\B(\ell,\ell';n)=add^\A(\ell,\ell');n$,
\item $add^\B(empty,nil)=empty;0$ and
\item $add^\B(\ell;n,nil)=\ell;n$,
\end{enumerate}
where  $\ell,\ell'\in \B_{List}$ and $n\in \B_{Elt}$.
By definition, $\B\models\Phi$.
However, for all $n<\omega$ we have
$add^\B(add^\B(empty;n,empty),nil)= empty;n$ which is different from the list $add^\B(empty;n,add^\B(empty,nil)) = empty;n;0$.
\end{proof}
