\begin{proof}[Proof of Theorem~\ref{th:complete} (Completeness)]
Consider a set of sentences $\Phi$ defined over a signature $(S^f\subseteq S,F^c\subseteq F,L)$.
Let $Y$ be a $S^l$-sorted block of variables such that $\card(Y_s)=\omega$ for all sorts $s\in S^l$. 
Let $\alpha\coloneqq\card(S^f)$ and $\{s_i\}_{i<\alpha}$ is an enumeration of $S^f$.
We say that $\Phi$ is semantically closed under $(CB)$ whenever $\Phi\models_\Sigma \Forall{var(t)} \psi(t)$ for all constructor terms $t\in T_{(S,F^c)}(Y)$ implies $\Phi\models_\Sigma\Forall{x}\psi(x)$.
Similarly, we say that $\Phi$ is semantically closed under $(FN)$ whenever $\Phi\cup\Gamma_{\overline{n}}\models\psi$ for all $\overline{n}\in \omega^\alpha$ implies $\Phi\models\psi$.


First, we assume that $\Phi$ is semantically closed under $(CB)$ and $(FN)$ and satisfiable in $\frag$.
Then we prove that $\Phi$ is satisfiable in $\frag^f$ in three steps:
\begin{enumerate}
\item  $\Phi$ omits  type $T^c\coloneqq\{\Forall{var(t)} x\neq t \mid t\in T_{\Sigma^c}(Y)\}\subseteq \Sen(\Sigma[x])$.
\begin{proofsteps}{17.5em}
let $\gamma$ be a $\Sigma[x]$-sentence such that \rlap{$\Phi\cup\{\gamma(x)\}$ is satisfiable over $\Sigma[x]$} & \\ 
$\Phi\not\models\Forall{x}\neg\gamma(x)$ & since $\Phi\cup\{\gamma(x)\}$ is satisfiable over $\Sigma[x]$\\
$\Phi\not\models \Forall{var(t)}\neg \gamma(t)$ for some $t\in T_{\Sigma^c}(Y)$ & since $\Phi$ is semantically closed under $(CB)$\\
$\Phi\cup\{\gamma(t)\}\not\models_{\Sigma[var(t)]}\bot$  & by semantics\\
$\Phi\cup\{\gamma(x)\}\cup\{\Exists{var(t)} t=x \}\not\models_{\Sigma[x]}\bot$ & as $\A\models\Phi\cup\{\gamma(t)\}$ for some $\A\in|\Mod(\Sigma[var(t)])$\\
$\Phi$ locally omits $T$ & by Lemma~\ref{lemma:otp}
\end{proofsteps}

\item $\Phi$ omits type $T_s^f\coloneqq\{\Exists{x_1,\dots,x_n} \land_{i\neq j} x_i\neq x_j \mid x_1,\dots, x_n \text{ are variables of sort }s\}$, for all sorts $s\in S^f$.
\begin{proofsteps}{17em}
let $\gamma$ be a $\Sigma$-sentence such that \rlap{$\Phi\cup\{\gamma\}$ is satisfiable over $\Sigma$} & \\ 
$\Phi\cup \{\gamma\}\not\models\bot$ & since $\Phi\cup\{\gamma\}$ is satisfiable over $\Sigma$\\
$\Phi\cup \{\gamma\}\cup \Gamma_{\overline{n}}  \not\models \bot$ for some $\overline{n}\in\omega^\alpha$ & since $\Phi$ is semantically closed under $(FN)$\\
$\A\models \Phi\cup \{\gamma\}\cup \Gamma_{\overline{n}}$ for some $\Sigma$-model $\A$  & by semantics\\
$\A\not\models T_s^f$ for all $s\in S^f$ & since $\A\models \Gamma_{\overline{n}}$\\
$\Phi$ locally omits $T_s^f$ for all $s\in S^f$ & by Lemma~\ref{lemma:otp}, since $\A\models \Phi\cup \{\gamma\}$ and $\A\not\models T_s^f$ for all $s\in S^f$
\end{proofsteps}

\item By Theorem~\ref{th:OTT}, there exists a model $\A$ which satisfies $\Phi$ and omits $T^c$ and  $T_s^f$ for all $s\in S^f$.
By the definition of the types $T^c$ and $T_s^f$, the model $\A$ is a constructor-based algebra which interprets each sort $s\in S^f$ as a finite set.
\end{enumerate}

Secondly, we assume that $\Phi\not \vdash^f \bot$ and then we prove that $\Phi\not\models^f\bot$.
We define the following set of sentences $\Psi\coloneqq \{\psi\in\Sen(S^f\subseteq S,F^c\subseteq F,L)\mid \Phi\vdash^f \psi\}$.
We show that $\Phi\not\vdash^f\bot$ iff $\Psi\not\vdash \bot$:
\begin{description}
\item [$\Rightarrow$]
For the forward implication, suppose towards a contradiction that $\Psi$ is not consistent in
$\frag$, that is, $\Psi\vdash\bot$.
Since $\vdash\subseteq \vdash^f$, we get $\Psi\vdash^f\bot$.
By $(Union)$, $\Phi\vdash^f \Psi$.
By $(Transitivity)$, $\Phi\vdash^f\bot$, 
which is a contradiction with the consistency of $\Phi$ in $\frag^f$.

\item [$\Leftarrow$]
For the backward implication, suppose towards a contradiction that $\Phi\vdash^f\bot$.
By the definition of $\Psi$, $\bot\in \Psi$.
By $(Monotonicity)$, $\Psi\vdash \bot$, which is a contradiction with the consistency of $\Psi$ in $\frag$. 
\end{description}
Assume that $\Phi$ is consistent in $\frag^f$. 
By the above property, $\Psi$ is consistent in $\frag$.
By completeness of $\frag$, $\Psi$ is satisfiable in $\frag$.
By completeness and soundness of $\frag$, $\Psi$ is semantically closed under $(CB)$ and $(FN)$.
By the first part of the proof, $\Psi$ is satisfiable in $\frag^f$.
Since $\Phi\subseteq \Psi$, $\Phi$ is satisfiable in $\frag^f$. 
\end{proof}
