  It remains then to show that $\FF$ belongs to $\CUBE(F)$.
  As already seen, \ref{Condition_C2} is obvious from the construction.
  Since our definition of $\FF$ uses rational approximations and dense sets we need to prove \ref{Condition_C1} explicitly, while Stein can take it for granted.

\begin{prop}\label{Prop_FisCovering}
    The family of cubes $\FF$ covers the  complement of $F$, that is
    $$ \bigcup_{Q \in \FF} Q = \RR^n \setminus F. $$
\end{prop}
\begin{proof}

    If we prove that each point in $\RR^n \setminus F$ is contained in a cube in the family $\FF_0$, we are done.
    In fact, by definition of $\FF$, $\bigcup \FF = \bigcup \FF_0$, and by definition of $\FF_0$, no cube in $\FF_0$ intersects $F$.

    For each $k \in \ZZ$, recalling that $\sqrt{n} \, 2^{-k}$ is the diameter of the cubes in $\mathcal{M}_k$, we define the sets
    \begin{align*}
        C_k &= \{ x \notin F \mid 2 \sqrt{n} \, 2^{-k} \le d(x,F) < 2 \sqrt{n} \, 2^{-k} + 2^{-k-1} \}, \\
        D_k &= \{ x \notin F \mid 2 \sqrt{n} \, 2^{-k} + 2^{-k-1} \le d(x,F) \le 4 \sqrt{n} \, 2^{-k} - 2^{-k-1} \}, \\
        E_k &= \{ x \notin F \mid 4 \sqrt{n} \, 2^{-k} - 2^{-k-1} < d(x,F) < 4 \sqrt{n} \, 2^{-k} \}.
    \end{align*}
    Obviously, we have $\bigcup_{k \in \ZZ} \left( C_k \cup D_k \cup E_k \right) = \RR^n \setminus F$.
    %and also each $x \notin F$ is contained in exactly one of $C_k, D_k$ and $E_k$ for a single $k \in \ZZ$; in other words, $\bigcup_{k \in \ZZ} \{ C_k, D_k, E_k\}$ forms a partition of $\RR^n \setminus F$.

    Given $x \notin F$ there exists $k$ such that $x \in C_k \cup D_k \cup E_k$. Let $Q \in \mathcal{M}_k$ be a cube that contains $x$.

    If $x \in D_k$ let $r \in R(Q,\max(k+1,0))$ with $d(x,r) < 2^{-k-1}$. We then have
    \begin{align*}
        d(r,F)[b_k] \ge d(x,F) - d(x,r) - \eta_k > (2 \diam(Q) + 2^{-k-1}) - 2^{-k-1} - \eta_k, \\
        d(r,F)[b_k] \le d(x,F) + d(x,r) + \eta_k < (4 \diam(Q) - 2^{-k-1}) + 2^{-k-1} + \eta_k,
    \end{align*}
    so that $Q \in \FF_0$.\smallskip

    If $x \in C_k$ we consider two cases:
    \begin{itemize}
        \item[1)] There exists $r \in R(Q,\max(k+1,0))$ such that $d(r,F)[b_k] > 2 \diam(Q) - \eta_k$.
        \item[2)] Each $r \in R(Q,\max(k+1,0))$ satisfies $d(r,F)[b_k] \le 2 \diam(Q) - \eta_k$.
    \end{itemize}

    In the first case $Q$ is in $\FF_0$, in fact
    \begin{align*}
        d(r,F)[b_k] &< d(x,F) + d(x,r) + \eta_k  \\
        &< (2 \diam(Q) + 2^{-k-1}) + \diam(Q) + \eta_k < 4 \diam(Q) + \eta_k,
    \end{align*}
    since $2^{-k-1} < \sqrt{n} \, 2^{-k} = \diam(Q)$.

    In the second case, $Q$ is not in $\FF_0$, so we have to look for a smaller cube $Q'$. Let $Q'$ be a cube with $x \in Q'$, $Q' \in \mathcal{M}_{k+1}$ (and thus $2 \diam(Q') = \diam(Q)$), and $Q' \subseteq Q$.
    By Remark \ref{Remark_R(Q,i)} we have $R(Q,\max(k+1,0)) \cap R(Q',\max(k+2,0)) \ne \emptyset$.
    So, there exists $r \in R(Q', \max(k+2,0))$ such that
    \begin{align*}
        d(r,F)[b_{k+1}] &< d(r,F)[b_k] + \eta_{k}+\eta_{k+1} \le (2 \diam(Q) - \eta_k) + \eta_{k}+\eta_{k+1} \\
        &< 4 \diam(Q') + \eta_{k+1}.
    \end{align*}

    For the other inequality, by $x \in Q' \cap C_k$, it holds $d(r,F) \ge d(x,F) - d(x,r) \ge 2 \diam(Q) - \diam(Q') = 3 \diam(Q')$, so
    \begin{align*}
        d(r,F)[b_{k+1}] \ge 3 \diam(Q') - \eta_{k+1} > 2 \diam(Q') - \eta_{k+1}.
    \end{align*}	
    Therefore $Q' \in \FF_0$.\smallskip

    If $x \in E_k$ the situation is symmetric and the two cases are:
    \begin{itemize}
        \item[1)] There exists $r \in R(Q,\max(k+1,0))$ such that $d(r,F)[b_k] < 4 \diam(Q) + \eta_k$.
        \item[2)] Each point $r \in R(Q,\max(k+1,0))$ satisfies $d(r,F)[b_k] \ge 4 \diam(Q) + \eta_k$.
    \end{itemize}

    In the first case $Q \in \FF_0$, in fact
    \begin{align*}
        d(r,F)[b_k] &> d(x,F) - d(x,r) - \eta_k  \\
            &> (4 \diam(Q) - 2^{-k-1}) - \diam(Q) - \eta_k > 2 \diam(Q) - \eta_k.
    \end{align*}

    For the second case, let $Q'$ in $\mathcal{M}_{k-1}$, with $x \in Q'$ and $Q' \supseteq Q$. Then $\diam(Q') = 2 \diam(Q)$, and by Remark \ref{Remark_R(Q,i)} $R(Q,\max(k+1,0)) \cap R(Q',\max(k,0)) \ne \emptyset$.
    So there exists $r \in R(Q', \max(k,0))$ with
      \begin{align*}d(r,F)[b_{k-1}] &> d(r,F)[b_k] - \eta_k-\eta_{k-1} \ge (4 \diam(Q) + \eta_k) -\eta_k- \eta_{k-1}  \\
    &= 2 \diam(Q')- \eta_{k-1}.
    \end{align*}

    For the other inequality, by $x \in Q' \cap E_k$, it holds $d(r,F) \le d(x,F) + d(x,r) < 4 \diam(Q) + \diam(Q') = 3 \diam(Q')$, so
    \begin{align*}
        d(r,F)[b_{k-1}] < 3 \diam(Q') + \eta_{k-1} < 4 \diam(Q') + \eta_{k-1}.
    \end{align*}	
Thus $Q' \in \FF_0$ also in this case.
\end{proof}

The intuitive idea behind the definitions of $\FF$ and $\FF_0$ (for any given $F$) is that we tile the complement of $F$ by using cubes whose edge lengths get smaller as they get closer to $F$.
We can express this fact more precisely by finding a precise quantitative relation binding $d(Q,F)$ to $\diam(Q)$ that yields condition \ref{Condition_C3} with $c_1 = \frac12$ and $c_2=5$.

\begin{prop}\label{Prop_DistanceDiamRelation2}
    For all $Q \in \FF$ it holds
    $$\frac{1}{2} \diam(Q) < d(Q,F) < 5 \diam(Q).$$
\end{prop}
\begin{proof}
    Let $k$ be such that $Q \in \mathcal{M}_k$.
    Consider now a witness $x \in Q$ of Proposition \ref{Prop_DistanceDiamRelation}, and $x' \in Q$ and $y \in F$ such that $d(Q,F) = d(x',y)$ ($x'$ and $y$ exist because $Q$ and $F$ are closed).
    We deduce that
    \begin{align*}
        d(Q,F) &= d(x',y) \ge d(x,y) - d(x,x') >  2\diam(Q) - 2\eta_k - \diam(Q)  \\
               &= \diam(Q) - 2\eta_k.
    \end{align*}
    Using $b_k > k+2$ (see (\ref{Align_bk})), we have $2\eta_k = 2^{-b_k + 1} < 2^{-k-1} \le \sqrt{n} \, 2^{-k-1}  = \frac{1}{2} \diam(Q)$, and thus $\frac{1}{2} \diam(Q) < d(Q,F)$.

    For the other inequality, let again $x \in Q$ be a witness to Proposition \ref{Prop_DistanceDiamRelation}, so that $d(x,F) < 4 \diam(Q) + 2\eta_k$.
    Using again $2\eta_k < \frac{1}{2} \diam(Q)$ we than have
    $$ d(Q,F) \le d(x, F) <  4 \diam(Q) + 2\eta_k < 5 \diam(Q).\qedhere$$
\end{proof}

We have thus completed the proof of:

\begin{teo}\label{Theorem_CUBEcomp}
The multi-valued function $\CUBE$ is computable.
\end{teo}

We now fix $\FF \in \CUBE (F)$.
We first obtain some further properties of $\FF$ and then define a derived family of enlarged cubes $\FF^*$.
To ease comparison with \cite{stein:1970} we adopt the following terminology.

\begin{defin}
    We say that two cubes \emph{touch} if their boundaries intersect.
\end{defin}

Since the cubes in $\FF$ have disjoint interiors by \ref{Condition_C2}, two cubes in $\FF$ intersect if and only if they touch.

\begin{prop} \label{Prop_DiamTouch}
    Let $Q_1 \in \mathcal{M}_h \cap \FF$ and $Q_2 \in \mathcal{M}_k \cap \FF$.
    If $Q_1, Q_2$ touch, then $|h-k| \le 3$, which is equivalent to
    \begin{align}\label{Align_DiamTouch8}
        \frac{1}{8} \diam(Q_1) \le \diam(Q_2) \le 8 \diam(Q_1).
    \end{align}
\end{prop}
\begin{proof}
    We show that if two cubes $Q_1,Q_2 \in \FF$ touch, then
    \begin{align}\label{Align_DiamTouch12}
        \frac{1}{12} \diam(Q_1) < \diam(Q_2) < 12 \diam(Q_1).
    \end{align}
    In fact, (\ref{Align_DiamTouch8}) follows immediately from (\ref{Align_DiamTouch12}) since the ratio of the diameters of two cubes in $\FF$ is always a power of $2$.

    Clearly it suffices to prove the second inequality in (\ref{Align_DiamTouch12}).
    By Proposition \ref{Prop_DistanceDiamRelation2} $\diam(Q_2) < 2 \, d(Q_2, F)$ and hence it is enough to prove $d(Q_2, F) < 6 \diam(Q_1)$.
    We achieve this goal by using the inequality $d(Q_1,F) < 5 \diam(Q_1)$ that holds by Proposition \ref{Prop_DistanceDiamRelation2}.
    In fact $d(Q_2,F) \leq d(x,F)$ for every $x \in Q_2$, in particular for every $x \in Q_1 \cap Q_2$.
    Fix then such an $x$, which exists by hypothesis, and let $x' \in Q_1$ and $y \in F$ be such that $d(x',y) = d(Q_1,F)$. Since $d(x,x') \leq \diam(Q_1)$ we have
    $$ d(Q_2,F) \leq d(x,y) \leq d(x,x') + d(x',y) < \diam(Q_1) + 5 \diam(Q_1) = 6 \diam(Q_1).\qedhere$$
\end{proof}

