Fix a rational number $\varepsilon < \frac{1}{5}$.
Given $Q \in \FF$ let $c_Q$ be the center of $Q$ and define the \emph{enlarged cube} $Q^*$ as the image of $Q$ under the map $x \mapsto x^* := (1 + \varepsilon)(x - c_Q) + c_Q$.
Notice that $Q^*$ is $Q$ dilated by $(1 + \varepsilon)$.

%%		Given any cube $Q \in \FF$, let $Q^*$ be the expanded cube  $(1 + \varepsilon) (Q - c_Q) + c_Q$ for a \emph{fixed} $\varepsilon < 2^{-10}$, where $c_Q$ is the center of the cube $Q$.
%		%The choice to take $\varepsilon < 2^{-10}$ should be clear later.
We call the family of enlarged cubes $\FF^*$, i.e.
\begin{align} \label{Align_F*}
    \FF^* := \left\{ Q^* \mid Q \in \FF \right\}.
\end{align}

It is easy to see the following fact.

\begin{prop}\label{Prop_RelationQQ*}
    Each point $x \in Q$ is mapped to a point $x^* \in Q^*$ such that $d(x,x^*) \leq \frac{\varepsilon}{2} \diam(Q)$.
    Moreover $\diam(Q^*) = (1 + \varepsilon)\diam(Q)$, and for any $y \in \RR^n$ we have $d(y, Q^*) \ge d(y, Q) - \frac{\varepsilon}{2} \diam(Q)$.
\end{prop}

\begin{prop}\label{Prop_NonOverlapping}
    Every cube $Q^* \in \FF^*$ (exactly as the original cube $Q$) does not intersect $F$, and in fact $d(Q^*, F) \ge \frac{1}{2}( 1 - \varepsilon )\diam(Q)$.
\end{prop}
\begin{proof}
    Let $x\in Q$ and $y \in F$ be such that $d(x^*,y) = d(Q^*,F)$.
    Using Propositions \ref{Prop_DistanceDiamRelation2} and \ref{Prop_RelationQQ*}, we deduce that
    $$\frac{1}{2} \diam(Q) < d(Q,F) \leq d(x,y) \leq d(x^*,y) + d(x,x^*) \leq  d(Q^*,F) + \frac{\varepsilon}{2} \diam(Q).$$
    Therefore $0 < \frac{1}{2}( 1 - \varepsilon ) \diam(Q) \leq d(Q^*,F)$.
\end{proof}

\begin{defin} \label{Def_Fx}
    For each $x \notin F$ let
    \begin{align*}
        \FF_x = \{ Q \in \FF \mid x \in Q^* \}.
    \end{align*}
\end{defin}

Since the condition $x \in Q^*$ is not decidable we cannot compute $\FF_x$.
The following Proposition overcomes this obstacle by replacing, in contrast with the classical proof, $\FF_x$ with a suitable superset.

\begin{prop}\label{Prop_Gx}
    For each $x \notin F$, we can uniformly compute a finite set $\mathcal{G}_x \supseteq \FF_x$.
    Moreover, the cardinality of $\mathcal{G}_x$ has a bound independent of $x$, indeed $|\mathcal{G}_x| \le N_n := \lceil 197 \, \sqrt{n} \rceil^n$.
\end{prop}
\begin{proof}
    Let $x \notin F$ and $\delta := d(x,F)$.
    If $Q \in \FF_x$ we have $d(Q^*, F) \le \delta \le d(Q^*, F) + \diam(Q^*)$.
    Using that for every $Q \in \FF$, $d(Q^*,F) < d(Q,F)$, and Propositions \ref{Prop_RelationQQ*} and \ref{Prop_DistanceDiamRelation2} we have
    \begin{align*}
        \delta \le d(Q^*, F) + \diam(Q^*) < d(Q, F) + (1 + \varepsilon) \diam(Q) < (6 + \varepsilon) \diam(Q).
    \end{align*}
    On the other side, using Proposition \ref{Prop_NonOverlapping}, we have
    \begin{align*}
        \delta \ge d(Q^*, F) \ge \frac{1 - \varepsilon}{2} \diam(Q).
    \end{align*}
    Combining these two results (and using $\varepsilon < \frac13$), we obtain
    \begin{align*}
        \frac{\delta}{7} < \frac{\delta}{6 + \varepsilon} < \diam(Q) \le \frac{2 \, \delta}{ 1 - \varepsilon} < 3 \, \delta.
    \end{align*}

    Now, since obviously $d(x, c_Q) \le \frac{1}{2} \diam(Q^*)$,
    %, where $c_Q$ is the center of $Q$.
    using again Proposition \ref{Prop_RelationQQ*} (and $\varepsilon < \frac15$) we have
    \begin{align*}
        d(x,c_Q) \le \frac{1 + \varepsilon}{2} \diam(Q) \leq \frac{(1 + \varepsilon) \, \delta}{ 1 - \varepsilon} < \frac{3 \, \delta }{2}.
    \end{align*}

    We now are ready to define the computable set $\mathcal{G}_x$.
    First, we start computing $\delta$ using the total information of $F$ (see Corollary \ref{Cor_DistanceIsComputable}) until we find some $i$ such that $\delta[i] \ge 2^{-i + 1}$, so that we are sure that $\delta \ge 2^{-i}$.
    This always happens because $F$ is closed and therefore $\delta > 0$.
    Then, recalling that $\FF$ is uniformly computable from $F$, we define $\mathcal{G}_x$ to be the set of all cubes $Q \in \FF$ such that
    \begin{enumerate}
        \item $\frac{1}{14} \delta[i] < \diam(Q) < 6 \, \delta[i]$,
        \item $d(x,c_Q)[i] < \frac{3}{2} \, \delta[i] + 2^{-i + 2}$.
    \end{enumerate}

    By Remark \ref{Remark_RepresentationCubes}, since we have an upper bound and a lower bound on the edge length of the cubes in $\mathcal{G}_x$, and also a bound on the distance between the center of the cubes and $x$, we have that $\mathcal{G}_x$ is computable and can be listed in finite time.

    We still need to show that $\FF_x \subseteq \mathcal{G}_x$.
    Let $Q \in \FF_x$, then
    \begin{gather*}
        \frac{\delta[i]}{14} < \frac{\delta + 2^{-i}}{14} \le \frac{\delta}{7} < \diam(Q) < 3 \, \delta < 3 \,( \delta[i] + 2^{-i} ) \le 6 \, \delta[i], \\
        d(x, c_Q)[i] < d(x,c_Q) + 2^{-i} < \frac{3}{2}\, \delta + 2^{-i} < \frac{3}{2} \delta[i] + 2^{-i+2},
    \end{gather*}
    and $Q$ belongs to $\mathcal{G}_x$.

    Now, for the cardinality of $\mathcal{G}_x$, note first that the distance of any point in $\bigcup \mathcal{G}_x$ from $x$ is less than $\max_{Q \in \mathcal{G}_x} d(x, c_Q) + \max_{Q \in \mathcal{G}_x} \frac{1}{2} \diam(Q) < \frac{3}{2} \, \delta[i] + 5 \cdot 2^{-i} + 3 \, \delta[i]$.
    If we consider the cube $R$ centered in $x$ whose edges have length $14 \, \delta[i]$, then obviously $R \supseteq \bigcup \mathcal{G}_x$.
    To cover $R$ with the smallest cubes that can belong to $\mathcal{G}_x$ (Figure \ref{Figure_Gx}), we need
    \begin{align*}
        \left\lceil \frac{14 \,\delta[i]}{ \frac{1}{14 \, \sqrt{n}} \, \delta[i] } + 1 \right\rceil ^n = \lceil 196 \, \sqrt{n} + 1 \, \rceil ^n \le \lceil 197 \, \sqrt{n} \rceil^n
    \end{align*}
    of them. Therefore we have an upper bound for $|\mathcal{G}_x|$, that is $|\mathcal{G}_x| \le \lceil 197 \, \sqrt{n} \rceil^n$.
\end{proof}

