\begin{prop}\label{Prop_FydFinito}
    Given $x \notin F$, let $\delta = d(x,F)/2$. Then, the set %$\FF_{x,\delta}
    $\widetilde{\FF}_x := \{ Q \in \FF \mid d(x, Q^*) < \delta \}$ is finite.
\end{prop}
\begin{proof}
    First, observe that if $Q \in \widetilde{\FF}_x$, then $d(Q^*, F) < 3  \delta$.
    Moreover, we have $d(Q^*, F) + \diam(Q^*) > \delta$.
    In fact, let $x^* \in Q^*$ and $z \in Q^* \cap B(x, \delta)$, then
    \begin{align*}
        d(x^*,F) &\ge d(x,F) - d(x^*,x) \ge d(x,F) - d(x^*,z) - d(z,x) >\\
            &> 2 \delta - \diam(Q^*) - \delta = \delta - \diam(Q^*),
    \end{align*}
    hence $d(x^*, F) + \diam(Q^*) > \delta$ for every $x^* \in Q^*$, and so $d(Q^*, F) + \diam(Q^*) > \delta$.

    By Proposition \ref{Prop_NonOverlapping},
    we have
    \begin{align*}
        \frac{1 - \varepsilon}{2} \diam(Q) \le d(Q^*, F) < 3  \delta,
    \end{align*}
    and since $d(Q^*,F) < d(Q,F)$, using Propositions \ref{Prop_DistanceDiamRelation2} and \ref{Prop_RelationQQ*} we obtain
    \begin{align*}
        {\delta} < d(Q^*, F) + \diam(Q^*) < d(Q, F) + (1 + \varepsilon) \diam(Q) < (6 + \varepsilon)\diam(Q).
    \end{align*}
    Therefore we have upper and lower bounds for the diameter of the cubes $Q$ that belong to $\widetilde{\FF}_x$, i.e.\
    \begin{align*}
        \frac{\delta }{ 6 + \varepsilon} < \diam(Q) < \frac{6  \delta }{ 1 - \varepsilon}.
    \end{align*}

    Now, using Proposition \ref{Prop_RelationQQ*} we have
    \begin{align*}
        \delta > d(x, Q^*) \ge d(x, Q) - \frac{\varepsilon}{2} \diam(Q) > d(x, Q) - \frac{3  \delta  \varepsilon}{ 1 - \varepsilon },
    \end{align*}
    and using this inequality we obtain
    \begin{align*}
        \widetilde{\FF}_x \subseteq  \left\{ Q \in \FF \mid d(x, Q) < \frac{1 + 2\varepsilon}{1-\varepsilon}\delta \right\} := \mathcal{U}.
    \end{align*}

    Let now $k$ be the largest integer such that if $Q \in \mathcal{M}_k$ then $\diam(Q) > \delta / (6 + \varepsilon)$, that is, $k$ is the largest integer such that $\sqrt{n} \, 2^{-k} > \delta / (6 + \varepsilon)$. Using the fact that the cubes in $\mathcal{M}_k$ intersect only along the boundaries, have edges of length $2^{-k}$, and are the smallest possible among those that can belong to $\mathcal{U}$, we have $|\mathcal{U}| \le L^n$, where
    $$ L = \left \lceil \left( 2 \frac{1 + 2\varepsilon}{1 - \varepsilon}\delta + 2\frac{6 \delta}{1-\varepsilon} \right) 2^k + 1 \right \rceil = \left\lceil 2^{k} \frac{13 + 2\varepsilon}{1 - \varepsilon} \delta + 1\right\rceil.$$
    In fact, $L$ represents the maximum number of cubes along each edge of the grid formed by cubes in $\mathcal{M}_k$ whose union covers $\bigcup \, \mathcal{U}$ (see Figure \ref{Figure_FydFinito}).
\end{proof}

