\section{Partition of unity}\label{Section_PartitionUnit}

In this section, using the families of cubes $\FF$ and $\FF^*$ (defined respectively in (\ref{Align_FF}) and (\ref{Align_F*})), we define a collection of $C^{\infty}$ computable functions which constitutes a partition of unity on $\RR^n \setminus F$.
Moreover all partial derivatives of these functions are computable.

Let $Q_0 \subseteq \RR^n$ be the cube with center $(0,...,0)$ and edges parallel to the axes of length $1$.
We need to define a computable function $\varphi_0 \in C^\infty(\RR^n)$ such that $0 \leq \varphi_0(x) \leq 1$, $\varphi_0(x) = 1$ if $x \in Q_0$ and $\varphi_0(x) = 0$ for $x \notin Q_0^*$, and such that we can uniformly compute all partial derivatives of $\varphi_0$.

We postpone the actual definition of $\varphi_0$ and first we show how we use it.
First, we adapt $\varphi_0$ to any cube $Q \in \FF$ by defining $\varphi_Q \in C^\infty(\RR^n)$ as
\begin{align} \label{Align_varphi}
    \varphi_Q(x) := \varphi_0\left(\frac{x-c_Q}{l_Q}\right),
\end{align}
where $c_Q$ is the center of $Q$ and $l_Q$ the length of its edges. Notice that $0 \leq \varphi_Q(x) \leq 1$, $\varphi_Q(x) = 1$ if $x \in Q$ and $\varphi_Q(x) = 0$ for $x \notin Q^*$.

We then define the partial function $\varphi^*_Q \in C(\RR^n \setminus F)$ as
\begin{align}\label{Align_varphistar}
    \varphi^*_Q(x):=\frac{\varphi_Q(x)}{\Phi(x)}
\end{align}
for every $x \notin F$, where $\Phi(x) := \sum_{Q \in \FF} \varphi_{Q}(x)$.

\begin{remark} \label{Cor_SumVarphi}
For every $Q \in \FF$ let $d_Q \in \RR$.
Then
    \begin{align*}
        \sum_{ Q \in \FF} d_Q \varphi_Q(x) = \sum_{ Q \in \FF_x} d_Q \varphi_Q(x) = \sum_{ Q \in \mathcal{G}_x} d_Q \varphi_Q(x),
    \end{align*}
where $\FF _x$ and $\mathcal{G}_x$ are as in Definition \ref{Def_Fx} and Proposition \ref{Prop_Gx}.
The same applies to $\varphi^*_Q$ instead of $\varphi_Q$.
In fact if $Q \not\in \FF_x $ then $\varphi_Q(x) = 0$ and consequently also $\varphi_Q^*(x) = 0$.
\end{remark}

\begin{prop} \label{Prop_varphiCinfinito}
    For all $Q \in \FF$, $\varphi_Q$ and $\varphi_Q^*$ are $C^{\infty}$ and computable. Moreover, for all $Q \in \FF$ we can uniformly compute the partial derivatives of $\varphi_Q^*$.
\end{prop}
\begin{proof}
Computability and smoothness of $\varphi_Q$ follow from the same properties of $\varphi_0$.
By Remark \ref{Cor_SumVarphi} $\Phi(x) = \sum_{Q \in \mathcal{G}_x} \varphi_{Q}(x) $, and $\mathcal{G}_x$ is finite and computable by Proposition \ref{Prop_Gx}.
Moreover $\Phi(x) >0$ by Proposition \ref{Prop_FisCovering}.
Therefore $\varphi_Q^*$ is a quotient of computable $C^{\infty}$ functions with nonzero denominator and so is computable and $C^{\infty}$.

For the second part, let $Q \in \FF$ and let $1 \le i \le n$.
By the definition of $\varphi_Q^*$ (\ref{Align_varphistar}), we have
    \begin{align*}
         \partial_i \, \varphi_Q^*(x) = \frac{ \partial_i \, \varphi_Q(x) \, \Phi(x) - \varphi_Q(x) \, \partial_i \, \Phi(x) }{ \Phi^2(x) },
    \end{align*}
and $\partial_i \, \Phi(x) = \sum_{Q \in \mathcal{G}_x} \partial _i \, \varphi_Q (x)$. By the definition of $\varphi_Q$ (\ref{Align_varphi}) we have
    %$$\frac{ \partial  }{\partial x_i} \varphi_Q(x) = \frac{1}{l_Q} \, \frac{ \partial \, \varphi_0 }{\partial x_i} \left(\frac{x - c_Q}{l_Q} \right).$$
    $$ \partial_i  \, \varphi_Q(x) = \frac{1}{l_Q} \, \partial_i \, \varphi_0 \left(\frac{x - c_Q}{l_Q} \right).$$
Then, since we can compute the partial derivatives of $\varphi_0$, %by Proposition \ref{Prop_varphi0Derivatives}
we can also compute the partial derivatives of $\varphi_Q^*$.
For higher order derivatives, we proceed in the same way.
\end{proof}


By definition we have:

\begin{prop}\label{Prop_varphi*Partition}
The functions $\varphi^*_Q$ constitute a partition of unity on $\RR^n \setminus F$, that is
$$\sum_{Q \in \FF} \varphi^*_Q(x) = 1 \text{ for every } x \notin F.$$
\end{prop}

We now illustrate how to construct $\varphi_0$.
Since $\varphi_0$ depends on the dimension of the space, sometimes we refer to this function as $\varphi_0^n$, where $n > 0$ is the dimension of the space.
Let $\lambda : \RR \to \RR$ be the function
\[
    \lambda(x) := \begin{cases}
        e^{-\frac{1}{x}} & \text{ if } x > 0\\
        0 & \text{ if } x \le 0.\\
    \end{cases}
\]	
Let $\mu$ be the function defined by 		
\[
    \mu(x) := \frac{\lambda(x)}{\lambda(x) + \lambda(1-x)}.
\]

Now, using $\varepsilon$ defined in the previous section, we define $\nu$ by
\[
    \nu(x) := \mu\left( \frac{2x - \left( -1-\varepsilon \right) }{ \varepsilon } \right) \mu\left( \frac{ \left( 1 + \varepsilon \right) - 2x }{ \varepsilon } \right).
\]
This is a function that is $0$ outside $[-\frac{1}{2}-\frac{\varepsilon}{2},\frac{1}{2} + \frac{\varepsilon}{2}]$ and $1$ inside $[-\frac{1}{2},\frac{1}{2}]$.
To obtain $\varphi_0^n$ we set
$$ \varphi_0^n(x_1, ..., x_n) := \nu(x_1) \cdot ... \cdot \nu(x_n).$$


\begin{prop} \label{Prop_varphi0}
    The functions $\lambda$, $\mu$ and $\nu$ are $C^\infty$ and so is $\varphi_0^n$ for every $n>0$.
\end{prop}
\begin{proof}
    By \cite[Proposition 2.2]{nestruev:2020}, $\lambda$ is $C^\infty$, and since $\mu$ has a strictly positive denominator everywhere on the real line, $\mu$ is also $C^{\infty}$.
    Since $\nu$ is obtained by composition and product of $C^{\infty}$ functions, it is also $C^{\infty}$, and the same holds for $\varphi_0^n$ for all $n > 0$.
\end{proof}

\begin{lemma}\label{Lemma_Derivativesh}
    For every $k$, we can compute rational numbers $H_k$ and $B_k$ such that for every $x \in \RR$,
    \begin{align}\label{Align_Derivativesh}
\left| \lambda^{(k)}(x) \right| \le H_k, \quad \left| \mu^{(k)}(x) \right| \le B_k, \quad \text{and} \quad \left| \nu^{(k)}(x) \right| \le B_{k} \, \left( \frac{2}{\varepsilon}\right)^{k}.
    \end{align}
\end{lemma}
\begin{proof}
It is easy to check that for $x>0$ we have
    \begin{align*}
        \lambda^{({k})}(x) = \frac{\lambda(x)}{x^{2k}} P_k(x),
    \end{align*}
where $P_0(x) = 1$ and $P_{k+1}(x) = (1-2k x) P_k(x) + x^2 P'_k(x)$, so that $P_k$ is a polynomial with integer coefficients that can be explicitly computed.
It is an exercise to see that $\lambda(x)/x^{2k}$ for $x>0$ has maximum value $(2k)^{2k} e^{-2k}< (2k)^{2k}$.
Moreover when $x \in (0,1)$ $|P_k(x)| \leq A_k$ where $A_k$ is the sum of the absolute values of its coefficients.
Therefore we can set $H_k := (2k)^{2k} A_k$.

Now, for the derivatives of $\mu$, we have
\begin{align*}
        \mu^{(k)}(x) = \frac{Q_k \left( \left\{ \lambda(x), \lambda(1-x), \dots, \lambda^{(k)}(x), \lambda^{(k)}(1-x) \right\} \right) }{(\lambda(x) + \lambda(1-x))^{k+1}}
\end{align*}
 where $Q_k$ is a polynomial in $\left\{ \lambda(x), \lambda(1-x), \dots, \lambda^{(k)}(x), \lambda^{(k)}(1-x) \right\}$ with integer coefficients that can be computed.
    %Let $l_k$ be the number of terms of $Q_k$, and for every $j < l_k$, $q_j \in \ZZ$ be the coefficient of the $j$-th term.
    %Both $l_k$ and $(q_j)_{j < l_k}$ can be effectively computed using symbolic calculation for derivatives.
Furthermore, we can compute an upper bound  for the absolute value of each term of the polynomial using the bound for the derivatives of $\lambda$.
Therefore, we can compute a bound $T_k$ for the numerator by taking the sum of the upper bounds for each term.
For the denominator, we have that for every $x \in (0,1)$, since $\lambda$ is increasing we have $\lambda(x) + \lambda(1-x) \ge \lambda(1/2) = e^{-2} \geq 1/8$ and therefore
$(\lambda(x) + \lambda(1-x))^{k+1} \ge (1/8)^{k+1}$.
Summing up, if we set $B_k := 8^{k+1} T_k$ then $|\mu^{(k)}(x)| \le B_k$.

If we let $a = 1/2 + \varepsilon/2$ we have
% \[
%     \nu^{(k)}(x) = \frac{1}{\varepsilon ^k} \sum_{i \le k} (-1)^i \binom{k}{i} \mu^{(k-i)} \left(\frac{x+a}{\varepsilon} \right) \mu^{(i)} \left(\frac{-x+a}{\varepsilon} \right).
% \]
\[
    \nu^{(k)}(x) = \left(\frac{2}{\varepsilon} \right) ^k \sum_{i \le k} (-1)^i \binom{k}{i} \mu^{(k-i)} \left(\frac{2(x+a)}{\varepsilon} \right) \mu^{(i)} \left(\frac{2(-x+a)}{\varepsilon} \right).
\]
Notice that, since the derivatives of $\mu$ vanish outside $(0,1)$ and $\frac{2}{\varepsilon}(x+a) \in (0,1)$ if and only if $-\frac12 - \frac{\varepsilon}{2} < x <-\frac12$ while $\frac2\varepsilon(-x+a) \in (0,1)$ if and only if $\frac12 < x < \frac12 + \frac{\varepsilon}{2}$, only the terms
\[
    t_1:=\mu^{(k)} \left(\frac{2(x+a)}{\varepsilon} \right) \mu \left(\frac{2(-x+a)}{\varepsilon} \right) \quad \text{and} \quad t_2:=\mu \left(\frac{2(x+a)}{\varepsilon} \right) \mu^{(k)} \left(\frac{2(-x+a)}{\varepsilon} \right)
\]
do not vanish.
For every $x$, $\mu^{(k)} \left(\frac{2(x+a)}\varepsilon \right) \neq 0$ only when $\mu \left(\frac{2(-x+a)}\varepsilon \right)=1$, and analogously for the other term.
Moreover, the terms $t_1$ and $t_2$ cannot be non-zero simultaneously.
Therefore, the bound for $\nu^{(k)}$ holds as well.
\end{proof}

\begin{prop}\label{Prop_fghDerivatives}
The functions $\lambda$, $\mu$ and $\nu$ are computably $C^\infty$, i.e.\ given $k$ we can uniformly find $\delta^{\to}$-names for $\lambda^{(k)}$, $\mu^{(k)}$ and $\nu^{(k)}$.
\end{prop}
\begin{proof}
We first show that given $k$ and $x$ we can compute $\lambda^{(k)}(x)$ uniformly in $k$.
The main point here is that $e^{-1/x}$ and its derivatives are not defined in $0$, so we have to be careful when we do not know whether $x\le 0$ or $x>0$.

To show that $\lambda^{(k)}$ is computable
%Notice that we cannot apply Lemma \ref{Lemma_JoinFunctionComputable} because $e^{-1/x}$ is not defined on $0$.
%Therefore, we have to show that given $x \in \RR$, we can compute a good approximation of $f(x)$ until we realize, possibly, that $x \le 0$ or $x > 0$; in these cases, the output is $0$ or $e^{-1/x}$ respectively.
%In other words, we show that $f$ is $\delta^{\to}$-computable by defining a machine that given a $\rho$-name for $x$, compute a $\rho$-name for $f(x)$ (i.e.\ a $(\rho,\rho)$-realization of $f$).
we define a machine that operates in stages: at each stage $i$, it outputs an approximation of $\lambda^{(k)}(x)$ within an error of $2^{-i}$.
First let $j$ be least such that $2^{-j+1}<2^{-i}/H_{k+1}$.
If $x[j] \ge 2^{-i}/H_{k+1} -2^{-j}$ (and so $x \ge 2^{-i}/H_{k+1} -2^{-j+1}>0$), we proceed calculating an approximation of $\lambda^{(k)}(x)$ using the explicit formula for the $k$-th derivative of $e^{-1/x}$, while if $x[j] < 2^{-i}/H_{k+1} -2^{-j}$ (and so $x < 2^{-i}/H_{k+1}$), we print $0$ on the output tape.
Notice in fact that in the latter case, by the Mean Value Theorem, $|\lambda^{(k)}(x)| \le H_{k+1} x \le 2^{-i}$.
%: this is obvious if $x \le 0$.
%If instead $x>0$ we have $|f^{(k)}(x) - |x[i]|| = f^{(k)}(x) - |x[i]| < x - |x[i]| < 2^{-i}$ when $e^{-1/x} > |x[i]|$ (here we use $0< e^{-1/x} < x$ for every $x > 0$), while $|f(x) - |x[i]|| < |x[i]| < 2^{-i}$ when $e^{-1/x} \le |x[i]|$.

%The proofs for $\mu$ and $\nu$ are similar using $B_{k+1}$ in place of $H_{k+1}$.

The derivatives of  $\mu$ and $\nu$ can be computed from those of $\lambda$ using the familiar calculus rules.
\end{proof}

\begin{prop}\label{Prop_varphi0Derivatives}
    For every $n$ the function $\varphi_0^n$ is computably $C^\infty$.
