\section{Proof of Proposition \ref{Prop_Derivativesvarphi}}\label{Appendix_A}

In order to prove Proposition \ref{Prop_Derivativesvarphi} we need a general fact about the derivatives of a quotient.

\begin{prop}\label{Prop_DerivativesQuotient}
%Let $f,g : \RR^n \to \RR$ be smooth functions. Then, for every $\bar{k}$,
%\begin{align}\label{Align_DerivativesQuotients}
%    \frac{\partial^{\bar{k}} }{\partial x^{\bar{k}}} \frac{f}{g} = \frac{Q_{\bar{k}} \left( \left\{ \frac{\partial^{\bar{l}} \, f }{\partial x^{\bar{l}}}, \frac{\partial^{\bar{l}} \, g }{\partial x^{\bar{l}}} \mid \bar{l} \le \bar{k} \right\} \right) }{g^{|\bar{k}|+1}},
%\end{align}
%where $Q_{\bar{k}}$ is a polynomial with $l_{\bar{k}}$ terms, integer coefficients $(q_j)_{j < l_{\bar{k}}}$, and each term has $\mathrm{deg}^*$ equal to $|\bar{k}|$.
%The sequence of coefficients $(q_j)_{j < l_{\bar{k}}}$ can be effectively computed from $\bar{k}$.
%
Let $u,v : \RR^n \to \RR$ be $C^m(\RR)$ functions and, for every $\bar{k}$ with $|\bar{k}| \le m$, let $\bar{l}_0, \dots, \bar{l}_{t_{\bar{k}}-1}$ list in lexicographical order all $\bar{l} \le \bar{k}$. Then the derivative ${\partial_{\bar{k}} } \frac{u}{v}$ can be expressed as
\begin{align}\label{Align_DerivativesQuotients}
\frac{\sum_{j < t_{\bar{k}}} W_j}{v^{|\bar{k}|+1}},
\end{align}
where each $W_j$ is of the form
\begin{align*}
    W_j = r_j \, ( \partial_{\bar{l}_j} u )%^{n_{j,\bar{l}}}
    \prod_{\bar{l} \le \bar{k}}  ( {\partial_{\bar{l}} \, v} )^{m_{j,\bar{l}}},
\end{align*}
with $r_j \in \ZZ$, $m_{j,\bar{l}} \in \NN$ and $|\bar{l}_j| + \sum_{\bar{l} \le \bar{k}} m_{j,\bar{l}} \, |\bar{l}| = |\bar{k}|$.

Moreover $t_{\bar{k}}$ and the sequences $(r_j)_{j < t_{\bar{k}}}$, and $(m_{j,\bar{l}})_{j < t_{\bar{k}}, \bar{l} \leq \bar{k}}$ can be effectively computed from $\bar{k}$.
\end{prop}
\begin{proof}
By induction on $|\bar{k}|$.
The case $|\bar{k}| = 0$ is obvious. 	

For the inductive step, suppose that (\ref{Align_DerivativesQuotients}) holds for $\bar{k}$.
We show that it holds also for $\bar{k} + e_i$ for every $i$ with $1 \le i \le n$. We have
\begin{align*}
     \partial_i \, \partial_{\bar{k}} \, \frac{u}{v} &= \sum_{j < t_{\bar{k}}} {\partial_i } \frac{W_j}{v^{|\bar{k}|+1}} =
      \sum_{j < t_{\bar{k}}} \frac{ {\partial_i }  W_j v^{|\bar{k}|+1} - W_j \, {\partial_i } (v^{|\bar{k}|+1}) }{v^{2(|\bar{k}|+1)}}  \\
      &= \sum_{j < t_{\bar{k}}} \frac{ {\partial_i }  W_j \, v^{|\bar{k}|+1} - (|\bar{k}|+1) W_j v^{|\bar{k}|} {\partial_i  v} }{v^{2(|\bar{k}|+1)}} = \sum_{j < t_{\bar{k}}} \frac{ {\partial_i }  W_j \, v - (|\bar{k}|+1) W_j \, \partial_i v }{v^{|\bar{k}|+2}}.
\end{align*}
Since
\begin{align*}
    {\partial_i } \, W_j & = r_j \, {\partial_i } \, \Big[ ( {\partial_{\bar{l}_j} u} ) \prod_{\bar{l} \le \bar{k}}  ( {\partial_{\bar{l}} v} )^{m_{j,\bar{l}}} \Big] = r_j \, ( {\partial_{\bar{l}_j + e_i}  u} ) \prod_{\bar{l} \le \bar{k}}  ( {\partial_{\bar{l}} \, v} )^{m_{j,\bar{l}}} \, + \\
     & \quad + r_j \, {\partial_{\bar{l}_j} u}  \sum_{\bar{h} \le \bar{k}} m_{j,\bar{h}} \, {\partial_{\bar{h} + e_i} v} \, ( {\partial_{\bar{h} } v} )^{m_{j,\bar{h}} - 1 }  \prod_{\bar{l} \le \bar{k}, \bar{l} \ne \bar{h} }  ( {\partial_{\bar{l}} v} )^{m_{j,\bar{l}} }
\end{align*}
all terms in the numerator are of the prescribed form.
\end{proof}

\begin{proof}[Proof of Proposition \ref{Prop_Derivativesvarphi}]
  Using (\ref{Align_varphi}), the definition of $\varphi_0$, Lemma \ref{Lemma_Derivativesh} and Notation \ref{Def_nInteger},
    we have
    \begin{align*}
        \left| \partial_{\bar{k}} \, \varphi_Q(x) \right| &=
        \frac{1}{l_Q^{|\bar{k}|}} \left| \partial_{\bar{k}}\, \varphi_0 \left( \frac{x - c_Q}{l_Q} \right) \right| \\
        &= \frac{1}{l_Q^{|\bar{k}|}} \left| \frac{\partial^{k_1}}{\partial x_1^{k_1}} \, \nu \left( \frac{x_1 - (c_Q)_1}{l_Q} \right) \dots \frac{\partial^{k_n}}{\partial x_n^{k_n}} \, \nu \left( \frac{x_n - (c_Q)_n}{l_Q} \right) \right| \\
        &\le \frac{1}{l_Q^{|\bar{k}|}} B_{k_1} \left(\frac{2}{\varepsilon}\right)^{k_1}  \dots  B_{k_n}\left( \frac{2}{\varepsilon} \right) ^{k_n} = B_{\bar{k}} \left(\frac{2}{ \varepsilon \, l_Q} \right) ^{|\bar{k}| }.
    \end{align*}

    For the second inequality the interesting case is when $x \in Q^*$. First, observe that using (\ref{Align_varphistar}) and Proposition \ref{Prop_DerivativesQuotient}, we have
    \begin{align*}
        \partial_{\bar{k}} \, \varphi^*_Q(x) = \frac{\sum_{j < t_{\bar{k}}} W_j}{\Phi(x)^{|\bar{k}| + 1}}.
    \end{align*}
Since each $W_j$ depends on the partial derivatives of $\Phi$ we need estimates on the absolute values of the latter. By the proof of Proposition \ref{Prop_Gx} we have that for every $Q' \in \FF_x$, $ \frac{1}{7}\, d(x,F) < \diam(Q') < 3\, d(x,F)$.
    Therefore, for every $Q' \in \FF_x$ we have
    \begin{align*}
        \diam(Q') > \frac{\diam(Q)}{ 21 }.
    \end{align*}
    Using that $\diam(Q) = \sqrt{n} \,l_Q$ and Proposition \ref{Prop_Gx} %and (\ref{Align_NormVarphilQ})
    we obtain for every $\bar{l} \leq \bar{k}$
    \begin{align}\label{Align_DerivativesPhi}
        \left| \partial_{\bar{l}} \, \Phi(x) \right| \le N_n \, B_{{\bar{l}}} \left( \frac{2}{ \varepsilon} \right)^{|\bar{l}|} \left( \frac{ 21 \, \sqrt{n} } { \diam(Q) }\right)^{|\bar{l}|}.
    \end{align}

    Now, consider a term $W_j$; by Proposition \ref{Prop_DerivativesQuotient}, we have
    \begin{align*}
        |W_j| &= |r_j| \, | {\partial_{ \bar{l}_j} }\, \varphi_Q(x) | \prod_{\bar{l} \le \bar{k}}  \left| {\partial_{\bar{l}} } \, \Phi(x) \right|^{m_{j,\bar{l}}} \le  K_j \, \left( \frac{2}{\varepsilon \diam(Q)} \right) ^{|\bar{k}|}
    \end{align*}
    where $K_j$ can be computed from $|r_j|$, $n$, $\left\{ B_{\bar{l}} \mid \bar{l} \le \bar{k} \right\}$ and $N_n$.

    Using again (\ref{Align_DefBbark}) and $\Phi(x) \ge 1$ (by Proposition \ref{Prop_FisCovering}) we obtain
    \begin{align*}
        \left| {\partial_{\bar{k}}} \, \varphi^*_Q(x) \right| \le \sum_{j < t_{\bar{k}}} { K_j \, \left( \frac2{\varepsilon \diam(Q)} \right)^{|\bar{k}|} }.
        % \left| Q_{\bar{k}}\left( \left\{ \frac{\partial^{\bar{l}}}{\partial x^{\bar{l}}} \varphi_Q(x), \frac{\partial^{\bar{l}}}{\partial x^{\bar{l}}} \Phi(x) \mid \bar{l} \le \bar{k} \right\} \right) \right| \le \\
    \end{align*}
    Setting $B'_{\bar{k}} := \sum_{j < t_{\bar{k}}} K_j$ we have the thesis.
\end{proof}


