			\includegraphics{Integral-PGM.png}     	
		}
		\caption{\small
			The schematic illustration of the integral pretty-good test in \eqref{eq:integral-PGM} in terms of a randomized Holevo--Helstrom test \eqref{eq:HH} with the uniform priors $(u,1-u)$, where $u$ is drawn uniformly at random.}
