	\end{figure}

	\smallskip
	\noindent\fbox{\begin{minipage}{1\textwidth}
			The interpretation given in Theorem~\ref{theo:extremal} also provides an intuitive explanation of why both conventional and integral pretty-good measurements are pretty good (c.f.~Proposition~\ref{prop:PGMs}).
			Indeed, the Holevo--Helstrom measurement can achieve the optimal error exponent even with the wrong priors as the wrong priors only add up to a constant; 
			the integration of the constants incurred in the integral PGM results in at most a constant multiplicative cost to the optimal error.
	\end{minipage}}
	\smallskip

	With this observation, we obtain the following tilting inequality in Proposition~\ref{prop:key}, which acts as the main technical tool in our later analysis.

	\begin{prop}[Tilting inequality] \label{prop:key}
		For all finite-dimensional positive semi-definite operators $A$ and $B$, the following holds:
		\begin{align}
			\Tr\left[ A \frac{B^{\alpha}}{A^{\alpha} + B^{\alpha}} \right]
			&\leq c_{\alpha} \cdot \Tr\left[ A^{\alpha} B^{1-\alpha} \right]
			\quad\forall\, \alpha \in [\nicefrac{1}{2},1],
		\end{align}
		where
		\begin{align} \label{eq:c_alpha}
			c_\alpha^{(1)} \coloneq \frac{1-\alpha}{\alpha}\frac{\pi}{\sin\left(\frac{1-\alpha}{\alpha}\pi\right)}, 
			\quad
			c_\alpha^{(2)}\coloneq \left( 2\alpha\right)^{-\frac{1}{\alpha}}
			\left(1-\frac{1}{2\alpha}\right)^{2-\frac{1}{\alpha}}
			\frac{\alpha}{1-\alpha}, 
			\quad
			c_{\alpha}\coloneq \min \left\{c_\alpha^{(1)}, c_\alpha^{(2)} \right\}<1.102.
		\end{align}


	\end{prop}

