		\section{Classical-Quantum Channel Coding} \label{sec:CQ}

		In this section, we first establish a one-shot bound for classical-quantum channel coding (Theorem~\ref{theo:CQ}), which resolves Burnashev--Holevo's conjecture \cite{BH98}.
		In Sections~\ref{sec:large_deviation}, \ref{sec:moderate_deviation}, and \ref{sec:small_deviation}, we demonstrate the corresponding asymptotic results in the large deviation, moderate deviation, and small deviation regimes, respectively, and compare with the existing results.

		\begin{defn}[Classical-quantum channel coding] \label{defn:CQ}
			Let $\mathscr{N}_{\X \to \B}: x\mapsto \rho_{\B}^x \in \mathcal{S}(\B)$ be a classical-quantum channel, where each channel output $\rho_{\B}^x$ is a density operator (i.e.~a positive semi-definite operator with unit trace).
			\begin{enumerate}[1.]
				\item Alice has classical registers $\mathsf{M}$ and $\X$, and Bob has a quantum register $\B$.

				%		\item A resource of uniform distribution on $[1:K]$ as a private randomness at Alice.

				\item An encoder at Alice, $m \mapsto x(m)$, maps each (equiprobable) message in $\mathsf{M}$ to a codeword in $\X$.

				\item 
				Alice's codeword in $\X$ undergoes the classical-quantum channel $\mathcal{N}_{\X\to \B}$ and ends up with an output state on Bob's quantum register $\B$.

				\item Bob applies a decoding measurement described by a positive operator-valued measure (POVM) $\left\{ {\Lambda}_{\B}^{m} \right\}_{m\in\mathsf{M}}$ on his  quantum register $\B$ to obtain an estimated message $\hat{m} \in \mathsf{M}$.
			\end{enumerate}
			We consider the conventional random coding strategy as follows.
			For each message $m\in \mathsf{M}$, a codeword $x({m})$ is drawn pairwise independently according to the common input distribution $p_{\mathsf{X}}$.
			Then, the minimum \emph{random coding error probability} for sending $|\mathsf{M}|$ messages through channel $\mathscr{N}_{\mathsf{X}\to\B}$ with input distribution $p_{\mathsf{X}}$ is defined as\footnote{
				We only write $p$ in the subscript of $\varepsilon(\X:\B)_{p}$ in \eqref{eq:error_CQ} because the channel $\mathscr{N}_{\X\to\B} : x\mapsto \rho_{\B}^x$ is usually fixed in classical-quantum channel coding.
				Hence, the random coding error $\varepsilon(\X:\B)_{p}$ only depends on the input distribution $p_{\X}$.}
			\begin{align} \label{eq:error_CQ}
				\varepsilon(\X:\B)_{p}
				&\coloneq
				\inf_{ \big\{ {\Lambda}_{\B}^{m} \big\}_{m\in\mathsf{M}} } \frac{1}{|\mathsf{M}|}  \sum_{m\in \mathsf{M}}	\mathds{E}_{x(m)\sim p_{\mathsf{X}}}
				\Tr\left[ \rho_{\B}^{x(m)} \left(\I_{\B} -  {\Lambda}_{\B}^{m} \right) \right],
			\end{align}
			where the joint input-output state is denoted by 
			\begin{align} \label{eq:CQ-state}
				\rho_{\mathsf{XB}} \coloneq \sum_{x\in\mathsf{X}} p_{\mathsf{X}}(x)|x\rangle \langle x|_{\mathsf{X}} \otimes \rho_{\mathsf{B}}^x.
			\end{align}
		\end{defn}


		Given a realization of the random codebook $\left\{ x(1), x(2), \ldots, x(|\mathsf{M}|) \right\}$, we adopt the integral $\alpha$-PGM:\footnote{Note that $\sum_{m\in\mathsf{M}} \mathring{\Pi}_{\mathsf{B}}^{x(m)}$ is equal to the projection onto the support of $\sum_{{m}\in \mathsf{M} } \big( \rho_{\mathsf{B}}^{x({m})} \big)^{\alpha}$, which could be less than $\I_{\B}$.}
		\begin{align}
			\begin{split} \label{eq:main}
				\mathring{\Pi}_{\mathsf{B}}^{x(m)} 
				\coloneq \frac{\left( \rho_{\mathsf{B}}^{x({m})} \right)^{\alpha}}{\sum_{\bar{m}\in \mathsf{M} } \left( \rho_{\mathsf{B}}^{x(\bar{m})} \right)^{\alpha} }, \quad \forall \, m \in \mathsf{M}, \; \alpha \in [\sfrac{1}{2},1]
			\end{split}
		\end{align}
		according to the associated channel output states $\left\{ \rho_{\B}^{x(m)} \right\}_{m\in \mathsf{M}}$.

		\begin{theo} \label{theo:CQ} %~\\
			For any classical-quantum channel $\mathscr{N}_{\mathsf{X} \to \B}: x \mapsto \rho_{\B}^x$, the minimum random coding error probability \eqref{eq:error_CQ} for sending $|\mathsf{M}|$ messages with an input distribution $p_{\mathsf{X}}$  is upper bounded by
			\begin{align} \notag
				\varepsilon(\X:\B)_{p}
				&\leq c_{\alpha}
				(|\mathsf{M}|-1)^{\frac{1-\alpha}{\alpha}}
				\Tr \left[
				\left( \sum_{x\in\mathsf{X}} p_{\mathsf{X}}(x) \left(\rho_{\mathsf{B}}^x\right)^{\alpha}  \right)^{\nicefrac{1}{\alpha}}
				\right]
				\\
				\notag
				&= c_{\alpha} \cdot
				2^{
					-\frac{1-\alpha}{\alpha} \left[ I_{\alpha} (\mathsf{X} \,:\, \B)_{\rho} - \log_2 (|\mathsf{M}|-1) \right]
				}, \quad \forall\, \alpha \in [\nicefrac{1}{2},1].
			\end{align}
			Here, the joint state $\rho_{\mathsf{X}\B}$ is defined in \eqref{eq:CQ-state}
			and $I_{\alpha} (\mathsf{X}:\B)_{\rho} \coloneq \inf_{\sigma_{\B} \in \mathcal{S}(\B) } D_{\alpha}(\rho_{\mathsf{X}\B}\Vert \rho_{\mathsf{X}} \otimes \sigma_{\B}) $ is the order-$\alpha$ Petz--R\'enyi information.
		\end{theo}

		The quantum Sibson identity \cite[Lemma II.6]{KW09}, \cite[(3.10)]{HT14}, \cite{CGH19} showed that the minimizer in $I_{\alpha} (\mathsf{X}:\B)_{\rho}$ is attained by
		\[
		\sigma_{\B}^{\star} = \frac{
			\left( \sum_{x\in\mathsf{X}} p_{\mathsf{X}}(x) \left(\rho_{\mathsf{B}}^x\right)^{\alpha}  \right)^{\nicefrac{1}{\alpha}}
		}{
			\Tr \left[
			\left( \sum_{x\in\mathsf{X}} p_{\mathsf{X}}(x) \left(\rho_{\mathsf{B}}^x\right)^{\alpha}  \right)^{\nicefrac{1}{\alpha}}
			\right]
		},
		\]
		and, hence, the order-$\alpha$ Petz--R\'enyi information with respect to the state $\rho_{\mathsf{X}\B}$
		admits a closed-form expression:
		\[
		I_{\alpha} (\X:\B)_{\rho} 
		= D_{\alpha}\left(\rho_{\X\B}\Vert \rho_{\X} \otimes \sigma_{\B}^{\star}\right)
		=
		\frac{\alpha}{\alpha-1} \log_2 \Tr \left[
		\left( \sum_{x\in\mathsf{X}} p_{\mathsf{X}}(x) \left(\rho_{\mathsf{B}}^x\right)^{\alpha}  \right)^{\nicefrac{1}{\alpha}}
		\right].
		\]

		The proof of Theorem~\ref{theo:CQ} is given below, which only uses the tilting inequality in Proposition~\ref{prop:key}.
		\begin{proof}
			By symmetry of random coding, we only calculate the error probability of sending $m=1$ without loss of generality: For all $\alpha \in [\nicefrac{1}{2},1]$,
			\begin{align}\notag
				\varepsilon(\X:\B)_{p} 
				&= \mathds{E}_{ x(m)\sim p_{\mathsf{X}} }
				\Tr\left[ \rho_{\mathsf{B}}^{x({1})}  \cdot \frac{
					\sum_{\bar{m}\neq 1} \left(\rho_{\mathsf{B}}^{x({\bar{m}})}\right)^{\alpha}
				}{    \left(\rho_{\mathsf{B}}^{x({1})}\right)^{\alpha}
					+ \sum_{\bar{m}\neq 1} \left(\rho_{\mathsf{B}}^{x({\bar{m}})}\right)^{\alpha}
				} \right]
				\\ \notag
				&\leq \mathds{E}_{ x(m)\sim p_{\mathsf{X}} } c_{\alpha} \Tr\left[ \left( \rho_{\mathsf{B}}^{x({1})} \right)^{\alpha} \left( \sum_{\bar{m}\neq 1} \left( \rho_{\mathsf{B}}^{x(\bar{m})} \right)^{\alpha} \right)^{\frac{1-\alpha}{\alpha}} \right],
			\end{align}
			where the inequality follows from Proposition~\ref{prop:key} with $A \leftarrow \rho_{\mathsf{B}}^{x({1})} $ and $B \leftarrow  \left[ \sum_{\bar{m}\neq 1} \left( \rho_{\mathsf{B}}^{x(\bar{m})} \right)^{\alpha} \right]^{\nicefrac{1}{\alpha}} $.

			Now we take expectation over the random codes $x(m) \sim p_{\mathsf{X}}$ to obtain
			\begin{align*}
				&\mathds{E}_{x(1)} \mathds{E}_{x(\bar{m})\mid x({1})}
				\Tr\left[ \left( \rho_{\mathsf{B}}^{x({1})} \right)^{\alpha} \left( \sum_{\bar{m}\neq 1} \left( \rho_{\mathsf{B}}^{x(\bar{m})} \right)^{\alpha} \right)^{\frac{1-\alpha}{\alpha}} \right]
				\\
				&\overset{\text{(a)}}{\leq} 
				\mathds{E}_{x(1)}
				\Tr\left[ \left( \rho_{\mathsf{B}}^{x({1})} \right)^{\alpha} \left( \mathds{E}_{x(\bar{m})\mid x({1})}\sum_{\bar{m}\neq 1} \left( \rho_{\mathsf{B}}^{x(\bar{m})} \right)^{\alpha} \right)^{\frac{1-\alpha}{\alpha}} \right]
				\\
				&\overset{\text{(b)}}{=} (|\mathsf{M}|-1)^{\frac{1-\alpha}{\alpha}} \cdot
				\mathds{E}_{x\sim p_{\mathsf{X}}} \Tr\left[ \left( \rho_{\mathsf{B}}^x \right)^{\alpha } \left( \mathds{E}_{\bar{x}} \left( \rho_{\mathsf{B}}^{\bar{x}} \right)^{\alpha} \right)^{\frac{1-\alpha}{\alpha}}
				\right]
				\\
				&= (|\mathsf{M}|-1)^{\frac{1-\alpha}{\alpha}} \cdot \Tr\left[ \left( \sum_{x\in \mathsf{X}} p_{\mathsf{X}}(x) \left( \rho_{\mathsf{B}}^x \right)^{\alpha}
				\right)^{\frac{1}{\alpha}}\right],
			\end{align*}
			where inequality (a) is because the power function $0\leq x\mapsto x^{\frac{1-\alpha}{\alpha}}$ is operator concave for $\frac{1-\alpha}{\alpha} \in [0,1]$;
			equality (b) follows from the pairwise independence of the random codebook.
		\end{proof}


		\subsection{Large Deviation Regime and Comparisons} \label{sec:large_deviation}

		When the underlying channel is product, say $\mathscr{N}_{\X_1 \to \B_1} \otimes \mathscr{M}_{\X_2 \to \B_2}$, the right-hand side of \eqref{eq:main} is multiplicative (see e.g., \cite[Lemma 7]{HT14}) for \emph{any} $\alpha \in [\nicefrac{1}{2},1]$ and \emph{any} product input distributions, say $p_{\X_1} \otimes q_{\X_2}$.

		If the channel is i.i.d.~, i.e., $\mathscr{N}_{\X\to \B}^{\otimes n}$, 
		one may choose an arbitrary i.i.d.~input distribution $p_{\X}^{\otimes n}$ which is called the \emph{i.i.d.~random codebook}.
		By optimizing the order $\alpha \in [\nicefrac{1}{2},1]$, Theorem~\ref{theo:CQ} implies
		\begin{align} \label{eq:CQ-exponent-iid}
			-\log_2  \varepsilon\left(\X^n : \B^n\right)_{ p^{\otimes n} }
			\geq
			n \cdot \sup_{\alpha \in [\nicefrac{1}{2},1]} \frac{1-\alpha}{\alpha} \left[ I_{{\alpha}}\left( \X:\B \right)_{\rho} - R \right]
			- \log_2 (1.102), \quad \forall\, n \in \mathds{N}.
		\end{align}
		If one further chooses the optimal input distributions, the above bound leads to the achievable error exponent:\footnote{The maximal order-$\alpha$ Petz--\Renyi information is called the order-$\alpha$ \Renyi radius \cite[\S 4]{MO14}.}
		\begin{align} \label{eq:CQ-exponent}
			\liminf_{n\to \infty} - \frac{1}{n} \log_2 \inf_{p_{\X}} \varepsilon\left(\X^n : \B^n\right)_{ p^{\otimes n} }
			\geq
			\sup_{p_{\X}} \sup_{\alpha \in [\nicefrac{1}{2},1]} \frac{1-\alpha}{\alpha} \left[ I_{{\alpha}}\left( \X:\B \right)_{\rho} - R \right].
		\end{align}
		Here, the asymptotic \emph{transmission rate} is
		\begin{align} \label{eq:rate}
			R := \lim_{n\to \infty} \frac{1}{n} \log_2 |\mathsf{M}|,
		\end{align}
		which is a \emph{fixed} constant away from the channel capacity $\sup_{p_{\X}} I_{1}\left( \X:\B \right)_{\rho}$, which is conventionally called the \emph{large deviation regime} as the rate deviates from the fundamental limit $\sup_{p_{\X}} I_{1}\left( \X:\B \right)_{\rho}$ by a constant amount (in dependent of the blocklength $n$).
		(In some contexts, it is also called the small error regime as the error vanishes exponentially fast.)



		The above error exponent is positive if and only if $R < \sup_{p_{\X}} I_{1}\left( \X:\B \right)_{\rho} $.
		It coincides with the results independently obtained by Renes  \cite{Ren25}, and Li--Yang \cite{LY25}, and also matches Dalai's sphere-packing exponent for classical-quantum channels \cite[Theorem 5]{Dal13} (see also \cite[Theorem 8]{CHT19} for the non-asymptotic refined sphere-packing bound) for $R$ higher than the so-called \emph{critical rate} $\left. \frac{\d}{\d s} I_{\frac{1}{1+s}}\left( \X:\B \right)_{\rho} \right|_{s=1}$.
		The advantages of our result in Theorem~\ref{theo:CQ} is that 
		(i) we do not have the polynomial prefactor $(n+1)^{|\mathcal{H}_{\B}|}$, which could be high in short blocklengths $n$,
		and 
		(ii) our error bound accommodates any input distribution $p_{\X}$ available at the encoder, which is of practical importance for implementations.



		\medskip
		It is worth mentioning that the first exponential decay error rate for mixed classical-quantum channels was proved by Hayashi \cite{Hay07}:
		\begin{align} \label{eq:Hay07}
			\varepsilon(\X:\B)_{p}
			&\leq 4
			(|\mathsf{M}|-1)^{\frac{1-\alpha}{\alpha}}
			\sum_{x\in\mathsf{X}} p_{\mathsf{X}}(x)  \Tr \left[
			\left( \rho_{\mathsf{B}}^x\right)^{2-\frac{1}{\alpha}} \rho_{\B}^{\frac{1-\alpha}{\alpha}}
			\right], \quad \forall\, \alpha \in [\nicefrac{1}{2},1].
		\end{align}
		Later, the constant $4$ was improved to $1$ by one of the present authors \cite[Proposition 1]{Cheng_simple}.
		For $n$-fold product channels, Hayashi's bound leads to the following achievable error exponent (using any i.i.d.~codebook $p_{\X}^{\otimes n}$):
		\begin{align} \label{eq:Hayashi-exponent}
			\sup_{\alpha \in [\nicefrac{1}{2},1]} \frac{1-\alpha}{\alpha} \left[ D_{2-\frac{1}{\alpha}}\left( \rho_{\X\B} \Vert \rho_{\X} \otimes \rho_{\B} \right) - R \right].
		\end{align}

		In the following Proposition~\ref{prop:comparison_Hayashi}, we directly show that the established error exponent in \eqref{eq:CQ-exponent} for any fixed $p_X$ is greater than \eqref{eq:Hayashi-exponent} unless for pure-state channels.
		The proof immediately follows from the duality relations for the conditional \Renyi entropies \cite[Corollary 4]{TBH14}, \cite[Corollary 5.3]{Tom16}, and \cite[Lemma 4]{HT14}.
		We gave the credits to Tomamichel, Berta, and Hayashi.

		\begin{prop} \label{prop:comparison_Hayashi}
			For any quantum state $\rho_{\A\B} \in \mathcal{S}(\A\otimes \B)$, and $\tau_{\A} \geq 0$ such that $\textnormal{\texttt{supp}}(\rho_{\A}) \subseteq \textnormal{\texttt{supp}}(\tau_{\A})$,
			\begin{align}
				D_{2-\frac{1}{\alpha} } \left( \rho_{\A\B} \Vert \tau_{\A} \otimes \rho_{\B} \right)
				\leq \inf_{\sigma_{\B} \in \mathcal{S}(\B)} D_{\alpha } \left( \rho_{\A\B} \Vert \tau_{\A} \otimes \sigma_{\B} \right),
				\quad \forall\,\alpha \geq \nicefrac{1}{2}.
			\end{align}

			In particular, for any quantum ensemble, $\{ p_{\X}(x), \rho_{\B}^x \}_{x\in\X}$,
			\begin{align}
				\Tr \left[
				\left( \sum_{x\in\mathsf{X}} p_{\mathsf{X}}(x) \left(\rho_{\mathsf{B}}^x\right)^{\alpha}  \right)^{\nicefrac{1}{\alpha}}
				\right]
				\leq 
				\sum_{x\in\mathsf{X}} p_{\mathsf{X}}(x)  \Tr \left[
				\left( \rho_{\mathsf{B}}^x\right)^{2-\frac{1}{\alpha}} \rho_{\B}^{\frac{1-\alpha}{\alpha}}
				\right],
				\quad \forall\,\alpha \geq \nicefrac{1}{2}.
			\end{align}
		\end{prop}
		\begin{proof}
			For any purification $\rho_{\A\B\C}$ of $\rho_{\A\B}$, we invoke \cite[Lemma 4]{HT14} as follows: for any $\alpha \geq \nicefrac{1}{2}$,
			\begin{align*}
				D_{2-\frac{1}{\alpha} } \left( \rho_{\A\B} \Vert \tau_{\A} \otimes \rho_{\B} \right)
				&\overset{}{=}
				- D_{2-\frac{1}{\alpha} } \left( \rho_{\A\C} \Vert \tau_{\A}^{-1} \otimes \rho_{\C} \right) && \text{(by \cite[(3.14)]{HT14})}
				\\
				&\leq - \widetilde{D}_{2-\frac{1}{\alpha} } \left( \rho_{\A\C} \Vert \tau_{\A}^{-1} \otimes \rho_{\C} \right)
				\\
				&\overset{}{=}
				\inf_{\sigma_{\B} \in \mathcal{S}(\B)} D_{\alpha } \left( \rho_{\A\B} \Vert \tau_{\A} \otimes \sigma_{\B} \right),
				&& \text{(by \cite[(3.13)]{HT14})}
			\end{align*}
			where $\widetilde{D}_{2-\nicefrac{1}{\alpha} }$ is the \emph{sandwiched \Renyi divergence}
			\cite{MDS+13, WWY14} (whose exact definition is not important here), which is always less than the Petz--\Renyi divergence  ${D}_{2-\nicefrac{1}{\alpha} }$ by the Araki--Lieb--Thirring inequality {\cite{Ara90, LT76}}.
		\end{proof}


		\subsection{Moderate Deviation Regime} \label{sec:moderate_deviation}

		In channel coding, one endeavors to operate at a higher rate $R$ (c.f.~\eqref{eq:rate}) as possible.
		Hence, one can let the transmission rate to approach channel capacity as the blocklength $n$ increases and study the asymptotic minimum error.
		As $R_n$ approaches channel capacity at a speed slower than $\mathcal{O}(\nicefrac{1}{\sqrt{n}})$, the error probability does not decay exponentially but still vanishes \cite{PV10, AW14b, CH17, CTT2017}.
		Such a situation is called the \emph{moderate deviation regime} as the rate deviates from the fundamental limit by a moderate amount, and also called the medium error regime.

		In \cite[Theorem 4]{CH17}, the moderate deviation analysis was done by using Hayashi's bound \eqref{eq:Hay07}.
		In the following, we show that Theorem~\ref{theo:CQ} also directly leads to vanishing errors in the moderate deviation regime.
		This is can be considered as the quantum analogy of \cite[Theorem 2.1]{AW14b}.

		Let $(a_n)_{n\in\mathds{N}}$ be any real sequence such that 
		\begin{align}
			\lim_{n\to \infty} a_n = 0, \quad
			\lim_{n\to \infty} \sqrt{n} \cdot a_n = \infty.
		\end{align}
		Suppose that the channel $\mathscr{N}_{\X\to \B} $ satisfies
		\begin{align}
			\Upsilon := \sup_{s\in[0,1]} \sup_{p_{\X}} \left| \frac{\d^3}{\d s^3} s I_{\frac{1}{1+s}} (\X:\B)_{\rho} \right| < \infty.
		\end{align}
		Denote the channel capacity as $C_{\mathscr{N}} := \sup_{p_{\X}} I_1(\X:\B)_{\rho}$, and define the \emph{channel dispersion} as:
		\begin{align}
			V_{\mathscr{N}}
			&:= \sup_{p_{\X} : I_1(\X:\B)_{\rho} = C_{\mathscr{N}} } \mathds{E}_{x \sim p_{\X}} V\left( \rho_{\B}^x \Vert \rho_{\B} \right), \label{eq:V}
			\\
			V(\rho\Vert\sigma)
			&:= \Tr\left[ \rho \left( \log_2 \rho - \log_2 \sigma \right)^2 \right] - D_1(\rho\Vert\sigma)^2.
		\end{align}
		By choosing $\alpha_n = \frac{a_n}{V_{\mathscr{N}}}$ in \eqref{eq:CQ-exponent} along with the Taylor's series expansion of $D_{\alpha}$ around $1$ (see e.g., \cite[Proposition 2]{CH17}, we have 
		\begin{align}
			\sup_{\alpha \in [\nicefrac{1}{2},1]} \frac{1-\alpha}{\alpha} \left[ I_{{\alpha}}\left( \X:\B \right)_{\rho} - (C_{\mathscr{N}} - a_n) \right]
			&\geq \frac{a_n^2}{2 V_{\mathscr{N}}} -  \frac{a_n^3}{ 6 V_{\mathscr{N}}^3} \Upsilon,
		\end{align}
		where $\tilde{\rho}_{\X\B} = \sum_{x\in\X} \tilde{p}_{\X}(x) |x\rangle \langle x|\otimes \rho_{\B}^x$ and $\tilde{p}_{\X}$ is any dispersion-achieving input distribution (i.e., $\tilde{p}$ achieves \eqref{eq:V}).
		Then, Theorem~\ref{theo:CQ} implies
		\begin{align}
			- \frac{1}{n a_n^2} \log_2 \varepsilon (\X^n : \B^n)_{\tilde{p}^{\otimes n}} 
			\geq  \frac{1}{2 V_{\mathscr{N}}} \left( 1 - \Upsilon \frac{a_n}{V_{\mathscr{N}}^2}\right)
			- \frac{\log_2 c_{\alpha_n}}{ n a_n^2 }
			\to \frac{1}{2 V_{\mathscr{N}}}
		\end{align}
		as $n\to \infty$
		(by noting that $c_{\alpha_n} \to 1$).
		Moreover, the sub-exponential vanishing rate $\frac{1}{2 V_{\mathscr{N}}}$ is tight \cite[Theorem 5]{CH17}.

		\subsection{Small Deviation Regime} \label{sec:small_deviation}
		For the large error regime, also known as the non-vanishing error regime, one asks for the largest achievable transmission rate $R$ with a prescribed error tolerance, i.e., the minimum error probability is no larger than a fixed constant, say $\epsilon \in (0,1)$ \cite[Proposition 2]{Cheng_simple}.
		In the i.i.d.~asymptotics, the largest achievable rate converges to the channel capacity at a speed of $\mathcal{O}(\nicefrac{1}{\sqrt{n}})$
		\cite{TH13, Li14, TT15, DPR16, OMW19, PW20, Cheng_simple}.
		Hence, it is also called the \emph{small deviation regime}, as the rate deviates from the fundamental limit by a small amount $\mathcal{O}(\nicefrac{1}{\sqrt{n}})$.

		Given that the optimal $\alpha $ converges to $1$ eventually, it is natural to choose the $1$-PGM in decoding.
		As shown in \cite{Cheng_simple}, the key ingredient giving the tightest one-shot characterization for $R$ is the following trace inequality when using the conventional $1$-PGM:
		\begin{align}
			\Tr\left[A (A+B)^{-\nicefrac{1}{2}} B (A+B)^{-\nicefrac{1}{2}} \right] \leq \Tr\left[ A \wedge B \right], \quad \forall\, A,B\geq 0,
		\end{align}
		where the noncommutative minimum $A\wedge B$ is given in \eqref{eq:noncommutative_minimum}.
		Later, Beigi and Tomamichel proved that the integral $1$-PGM also satisfies the similar inequality \cite[Lemma 4]{BT24}, i.e.,
		\begin{align} \label{eq:BT24_trace}
			\Tr\left[A \frac{B}{A+B} \right] \leq \Tr\left[ A \wedge B \right],  \quad \forall\, A,B\geq 0
		\end{align}
		by adapting the analysis in \cite[Lemma 1]{Cheng_simple}.
		Hence, the decoder in \eqref{eq:main} for $\alpha = 1$ could also achieve the state-of-the-art performance in the small deviation regime.

		In the following, we show that \eqref{eq:BT24_trace} is a natural consequence of the operator layer cake theorem.
		Using Theorem~\ref{theo:Dlog_formula} for $\frac{B}{A+B}$, we have
		\begin{align}
			\Tr\left[A \frac{B}{A+B} \right]
			&= \int_{0}^1 \Tr\left[ A \proj{ A < \frac{1-u}{u} B } \right] \d u
			\leq \int_{0}^1 \Tr\left[ A \proj{ A < \frac{1}{u} B } \right] \d u
			= \Tr\left[ A \wedge B \right].
		\end{align}
		Here, the inequality is because the map $\gamma \mapsto \Tr\left[ A \proj{A < \gamma B } \right]$ is monotone increasing for $A,B\geq 0$ \cite{LHC25_layer_cake}\footnote{The monotonicity of the map $\gamma \mapsto \Tr\left[ A \proj{A < \gamma B } \right]$ is equivalent to the convexity of the Hockey-Stick divergence in $\gamma$, i.e., 
			$\gamma \mapsto E_{\gamma}(A\Vert B) := \Tr\left[(A-\gamma B)_+\right]$, which is also equivalent to the monotonicity of the
			\emph{information-spectrum divergence} $D_\textnormal{S}^{\epsilon}(\rho \,\|\, \sigma ):= \sup\left\{ \gamma \in \mathds{R} : \Tr\left[ \rho \left\{ \rho\leq \mathrm{e}^\gamma \sigma \right\} \leq \eps \right]  \right\} $ \cite{VH94, Han03, HN03, NH07, TH13} in the error parameter $\epsilon$.
			Note that the known smooth entropic quantities such as the \emph{$\epsilon$-hypothesis-testing divergence}
			$D_\textnormal{H}^\epsilon(\rho \,\|\, \sigma) := \sup_{0\leq T\leq \I } \left\{ -\log \Tr[\sigma T] : \Tr[\rho T] \geq 1 - \varepsilon \right\}$
			\cite{TH13, WR13, Li14} and others, see e.g.,~\cite{RLD25}, all satisfy this property. Namely, the distinguishability increases once the error tolerance is relaxed.}, which may be viewed as a relaxation.
		The last equality is from the integral representation in Proposition~\ref{prop:min} below.

		\begin{prop}[Integral representation for the tracial noncommutative minimum] \label{prop:min}
			Let $A$ and $B$ be Hermitian.
			Then,
			\begin{align}
				\Tr\left[ A \wedge B \right]
				&= \int_0^1 \Tr\left[ A \proj{ u A < B } \right] \d u,
			\end{align}
			where $A\wedge B := \frac12\left[ A+B- |A-B| \right]$.
		\end{prop}
		\begin{proof}
			Note that $A\wedge B = B - (B-A)_+$.
			We have
			\begin{align*}
				\Tr\left[ A \wedge B \right]
				&= \Tr[B-(B-A)_+]
				=-\Tr[(B-uA)_+]\big\vert_{u=0}^{u=1}
				\\
				&=\int_{0}^1 \left(-\frac{\d}{\d u}\Tr\left[ (B-u A)_+ \right]\right) \d u
				\\
				&=\int_{0}^1 \Tr\left[ A \left\{ B-u A > 0 \right\} \right] \d u,
				% =\int_{0}^1 \Tr\left[ \rho \left\{ \sigma \geq t\rho \right\} \right] \d t
			\end{align*}
			where we use the Lebesgue integral and note that $u\mapsto \Tr[(B-u A)_+]$ is continuous and piecewise differentiable (see e.g., \cite{LHC25_layer_cake}).
		\end{proof}

		\section{Constrained Classical-Quantum Channel Coding} \label{sec:CC}

		The goal of this section is still on classical-quantum channel coding but now with a constrained set of codewords $\Z \subset \X$.
		In the $n$-shot setting, we will show later in Section~\ref{sec:cc_codes} that constant composition codes are optimal in the sense that the established error exponent matches the sphere-packing exponent for \emph{each} composition.\footnote{Since the constant composition codes are of finite blocklength in nature. The error exponent here also refers to the finite blocklength one, namely, the leading term of $-\log \varepsilon$ by ignoring other sub-linear terms. We will discuss this issue in Remark~\ref{remark:CC} later.}

		We follow the notation given in Section~\ref{sec:CQ} and fix a classical-quantum state $\rho_{\mathsf{XB}} \coloneq \sum_{x\in\mathsf{X}} p_{\mathsf{X}}(x)|x\rangle \langle x|_{\mathsf{X}} \otimes \rho_{\mathsf{B}}^x$ for any input distribution $p_{\X}$.
		Since now the codewords are constrained to the set $\Z$, we instead employ the following conditional probability distribution in random coding:
		\begin{align} \label{eq:p_breve}
			\breve{p}_{\X}(x)
			&\coloneq \frac{\{x \in \Z \}\cdot  p_{\X}(x) }{ p_{\X}(\Z) }
		\end{align}
		(here $\{x \in \Z \}$ is understood as the indicator function of the event $x \in \Z$).
		We use the notation $\breve{p}_{\X}$ to highlight that it is induced from the original distribution $p_{\X}$.
		Additionally, we still write $\X$ in the subscript of $\breve{p}_{\X}$ instead of $\Z$ for notational convenience because we can always embed the system $\Z$ in the larger $\X$.

		Our goal is to bound the random coding error probability $\varepsilon({\X}:\B)_{\breve{p}}$ as in \eqref{eq:error_CQ}, and characterize it in terms of the original joint state $\rho_{\X\B}$.
		% Then, the minimum {random coding error probability} for sending $M$ equiprobable messages through channel $\mathcal{N}_{\mathsf{X}\to\B}$ using input distribution $p_{\breve{\mathsf{X}}}$ on the constrained set $\breve{\X}$ is 
		% 	\begin{align} \label{eq:error_CC}
			%     \breve{\varepsilon}(\mathsf{X}:\B)_{\rho}
			%     &\coloneq
			% 	\frac{1}{M} \sum_{m\in \mathsf{M}}	\mathds{E}_{x(m)\sim p_{\breve{\mathsf{X}}}}
			%     \inf_{ \left\{ {\Pi}_{\B}^{x(m)} \right\}_{m\in\mathsf{M}} } \Tr\left[ \rho_{\B}^{x(m)} \left(\mathds{1}_{\B} -  {\Pi}_{\B}^{x(m)} \right) \right].
			% 	\end{align}

		To characterize $\varepsilon(\X,\B)_{\breve{\rho}}$, we introduce the \emph{order-$\alpha$ Petz--Augustin information} with respect to the state $\rho_{\mathsf{XB}} = \sum_{x\in\mathsf{X}} p_{\mathsf{X}}(x)|x\rangle \langle x|_{\mathsf{X}} \otimes \rho_{\mathsf{B}}^x$ as
		\begin{align} \label{eq:Augustin}
			\breve{I}_{\alpha}(\X:\B)_{\rho}
			\coloneq \inf_{\sigma_{\B} \in \mathcal{S}(\B)} \sum_{x\in\X} p_{\X}(x) D_{\alpha}\left( \rho_{\B}^x \Vert \sigma_{\B} \right).
		\end{align}
		It is known that when $|\mathsf{X}|<\infty$, the minimizer in $\breve{I}_{\alpha}(\X:\B)_{\rho}$ is always attained by a unique state, named the \emph{Augustin mean}, and  we denote it by $\breve{\sigma}_{\B}^{\star}(\alpha,p_{\X})$.
		(We will drop the dependence $(\alpha,p_{\X})$ for simplicity when there is no possibility of confusion.) 
		Moreover, it satisfies a fixed-point property (see \cite[Proposition 2-(b)]{CHT19}, \cite[Theorem IV.14]{MO18} for the finite-dimensional case and \cite[(32)]{CB24} for the infinite-dimensional case):
		\begin{align} \label{eq:fixed-point}
			\breve{\sigma}_{\B}^{\star}(\alpha,p_{\X})
			=  \left( \sum_{x\in\X} p_{\X}(x) \mathrm{e}^{ (1-\alpha) D_{\alpha}\left(\rho_{\B}^x \Vert \breve{\sigma}_{\B}^{\star}(\alpha, p_{\X})\right)  } \left(\rho_{\B}^x\right)^{\alpha}  
			\right)^{\nicefrac{1}{\alpha}}, \quad \alpha \in (0,1)
			% \breve{\sigma}_{\B}^{\star}
			% =  \left( \sum_{x\in\X} p_{\X}(x) \frac{ \left(\rho_{\B}^x\right)^{\alpha} }{
				% \Tr\left[ \left(\rho_{\B}^x\right)^{\alpha} \left( \breve{\sigma}_{\B}^{\star} \right)^{1-\alpha} \right]
				% }
			% \right)^{\nicefrac{1}{\alpha}}.
		\end{align}
		which further implies that the Augustin mean has the tensorization property, i.e., $\sigma_{\B^n}^{\star} = (\sigma_{\B}^{\star})^{\otimes n}$, for $n$-fold product $p_{\X}^{\otimes n}$ and $\mathscr{N}_{\X\to\B}^{\otimes n}$.

		\begin{theo}[One-shot bound for constrained classical-quantum channel coding] \label{theo:CC-one-shot} %~\\
			For any classical-quantum channel $\mathscr{N}_{\mathsf{X} \to \B}: x\mapsto \rho_{\B}^x$ and distribution $p_{\X}$, the minimum random coding error probability  for sending $|\mathsf{M}|$ messages with an induced input distribution $\breve{p}_{\X}$ on the constrained set $\Z \subset \X$, i.e., \eqref{eq:p_breve}, is upper bounded by
			\begin{align} \notag
				{\varepsilon}(\X:\B)_{\breve{p}}
				&\leq \frac{c_{\alpha}}{ p_{\X}(\Z)^{\nicefrac{1}{\alpha}} } \cdot
				2^{
					-\frac{1-\alpha}{\alpha} \left[  \inf_{x \in \Z } D_{\alpha}\left(\rho_{\B}^{x}\Vert \breve{\sigma}_{\B}^{\star}(\alpha,p_{\X}) \right)  - \log_2(|\mathsf{M}|-1) \right]
				}, \quad \forall\, \alpha \in [\nicefrac{1}{2},1].
			\end{align}
			Here, $\breve{\sigma}_{\B}(\alpha,p_{\X})$ is the minimizer in \eqref{eq:Augustin}.%, and $\breve{\rho}_{\X\B}$ is the joint input-output state in \eqref{eq:CQ-state_constrained}.
		\end{theo}
		% \begin{remark}
			% The analysis of Theorem~\ref{theo:CC-one-shot} is greatly inspired by Nakibo\u{g}lu's variant of Gallager's inner bound for classical channels \cite[Lemma 5]{Nak20}.
			% Our contribution here is to show that, via the tilting inequality (Proposition~\ref{prop:key}) and the analysis established in Section~\ref{sec:CQ}, his idea extends to classical-quantum channels with aconstrained set as well.
			% \end{remark}

		\begin{proof}
			For simplicity, we write $\sigma_{\B}^{\star}(\alpha,p_{\X}) = \sigma_{\B}^{\star}$ subsequently.
			We directly apply Theorem~\ref{theo:CQ} to obtain
			\begin{align*}
				\varepsilon(\X:\B)_{\breve{p}}
				&\leq c_{\alpha}
				(|\mathsf{M}|-1)^{\frac{1-\alpha}{\alpha}}
				\Tr \left[
				\left( \sum_{x\in \Z} \breve{p}_{\X}(x) \left(\rho_{\mathsf{B}}^x\right)^{\alpha}  \right)^{\nicefrac{1}{\alpha}}
				\right]
				\\
				&\overset{\text{(a)}}{\leq}
				c_{\alpha}
				(|\mathsf{M}|-1)^{\frac{1-\alpha}{\alpha}}
				\Tr \left[
				\left( \sum_{x\in\X} \frac{\{x \in \Z \}\cdot  p_{\X}(x) }{ p_{\X}(\Z) } 2^{ (1-\alpha) D_{\alpha}\left(\rho_{\B}^x \Vert \breve{\sigma}_{\B}^{\star}\right)} \left(\rho_{\mathsf{B}}^x\right)^{\alpha}  \right)^{\nicefrac{1}{\alpha}}
				\right] 
				\cdot \sup_{x\in\Z} 2^{ \frac{\alpha-1}{\alpha} D_{\alpha}\left(\rho_{\B}^x \Vert \breve{\sigma}_{\B}^{\star}\right)}
				\\
				&\overset{}{\leq}
				c_{\alpha}
				(|\mathsf{M}|-1)^{\frac{1-\alpha}{\alpha}}
				\Tr \left[
				\left( \sum_{x\in\X} \frac{ p_{\X}(x) }{ p_{\X}(\Z) } 2^{ (1-\alpha) D_{\alpha}\left(\rho_{\B}^x \Vert \breve{\sigma}_{\B}^{\star}\right)} \left(\rho_{\mathsf{B}}^x\right)^{\alpha}  \right)^{\nicefrac{1}{\alpha}}
				\right] 
				\cdot \sup_{x\in\Z} 2^{ \frac{\alpha-1}{\alpha} D_{\alpha}\left(\rho_{\B}^x \Vert \breve{\sigma}_{\B}^{\star}\right)}
				\\
				&\overset{\text{(b)}}{=}
				\frac{c_{\alpha}}{ p_{\X}(\Z)^{\nicefrac{1}{\alpha}}  }
				(|\mathsf{M}|-1)^{\frac{1-\alpha}{\alpha}} \Tr\left[ \breve{\sigma}_{\B}^{\star}\right]\cdot \sup\nolimits_{x\in\Z} 2^{ \frac{\alpha-1}{\alpha} D_{\alpha}\left(\rho_{\B}^x \Vert \breve{\sigma}_{\B}^{\star}\right)}
				\\
				&=
				\frac{c_{\alpha}}{ p_{\X}(\Z)^{\nicefrac{1}{\alpha}}  }
				(|\mathsf{M}|-1)^{\frac{1-\alpha}{\alpha}} \sup\nolimits_{x\in\Z} 2^{ \frac{\alpha-1}{\alpha} D_{\alpha}\left(\rho_{\B}^x \Vert \breve{\sigma}_{\B}^{\star}\right)},
			\end{align*}
			where we changed the priors $\breve{p}_{\X}$ in (a), and 
			we invoked the fixed-point property \eqref{eq:fixed-point} in (b).
		\end{proof}

		\subsection{Constant Composition Codes} \label{sec:cc_codes}
		Theorem~\ref{theo:CC-one-shot} is useful in bounding the error exponent for \emph{constant composition codes}.
		Fix an integer $n\in\mathds{N}$ such that the input distribution $p_{\X}$ is an \emph{$n$-type} (whose probability value is an integer multiple of $\frac{1}{n}$).
		Now, the constrained set is the typical set, namely, the set of sequences $x^n \in \X^n$ having the same empirical distribution or composition of $p_{\X}$, i.e.,~
		\begin{align*}
			\Z^n &\leftarrow  \mathcal{T}_{p_{\X}}^n
			\coloneq \left\{ x^n \in \X^n : p_{\X}(x) = \frac{ \sum_{i=1}^n \{ x_i = x \}}{n}, \quad \forall\, x\in\X \right\},
		\end{align*}
		and hence
		\begin{align} \label{eq:CC}
			\breve{p}_{\X^n}(x^n) = \frac{ 1 }{\left| \mathcal{T}_{p_{\X}}^n \right|} \left\{ x^n \in  \mathcal{T}_{p_{\X}}^n  \right\} , \quad \forall\, x^n \in \X^n.
		\end{align}


		Notice that the $n$-length joint input-output state 
		\[
		\breve{\rho}_{\X^n \B^n} = \sum_{x^n \in \X^n} \breve{p}_{\X^n}(x^n) |x^n\rangle\langle x^n |_{\X^n} \otimes \rho_{\B_1}^{x_1} \otimes \cdots \otimes \rho_{\B_n}^{x_n}
		\]
		is no longer a product state.

		\begin{theo}[Random coding bound for constant composition codes] \label{theo:CC}
			Let $\mathscr{N}_{\X\to\B} \colon x\mapsto \rho_{\B}^x$ be a classical-quantum channel.
			For any integer $n\in\mathds{N}$ such that $p_{\X}$ is an $n$-type and any rate $R\coloneq \frac{1}{n}\log_2 |\mathsf{M}|$, we have for constant composition codes \eqref{eq:CC}:
			\begin{align} \label{eq:CC_bound1}
				\log_2 \varepsilon(\X^n:\B^n)_{\breve{p}} \leq - n \frac{1-\alpha}{\alpha} \left[ \breve{I}_{\alpha}(\X:\B)_{\rho} - R \right] + \frac{|\X|}{\alpha}\log_2 (n+1) + \log_2 c_{\alpha}, \quad \forall\, \alpha \in [\sfrac12, 1].
			\end{align}
			Here, the order-$\alpha$ Petz--Augustin information $\breve{I}_{\alpha}(\X:\B)_{\rho}$ is defined in \eqref{eq:Augustin} with respect to state $\rho_{\mathsf{XB}} = \sum_{x\in\mathsf{X}} p_{\mathsf{X}}(x)|x\rangle \langle x|_{\mathsf{X}} \otimes \rho_{\mathsf{B}}^x$.

			Moreover, for $R \geq \left.\frac{\d}{\d s} s \breve{I}_{\frac{1}{1+s}}(\X\colon\B)_{\rho}\right|_{s=1}$,
			\begin{align} \label{eq:CC_bound2}
				-\log_2 \varepsilon(\X^n:\B^n)_{\breve{p}}
				= n \cdot \sup_{\alpha \in [\nicefrac{1}{2}, 1] }\frac{1-\alpha}{\alpha} \left[ \breve{I}_{\alpha}(\X:\B)_{\rho} - R \right]
				+ \mathcal{O}(\log_2 n)
			\end{align}
			(where the exact factors in $\mathcal{O}(\log_2 n)$ can be found in \eqref{eq:CC_bound1} and the converse bound \cite{CHT19}).
		\end{theo}
		\begin{remark} \label{remark:CC}
			Theorem~\ref{theo:CC} estimates the optimal performance of a finite blocklength constant composition code, which by design is an $n$-type in \eqref{eq:CC}.
			Note that the leading first-order term in \eqref{eq:CC_bound2} is optimal (for higher rates) for \emph{any} $n$-type, and hence both the leading term and the state $\rho_{\X\B}$ still depend on the blocklength $n$.
			From the operational point of view, such a characterization for a constant composition code is already useful.

			When comparing the optimal performance of constant composition codes with other codes, e.g.,~the i.i.d.~codebook in Section~\ref{sec:large_deviation} (see Remark~\ref{remark:Augustin_vs_Renyi} below), one may choose an $n$-type $p_{\X}^{(n)}$ to approximate an arbitrary input distribution $p_{\X}$ with a cost in total variation distance $\frac12\big\| p_{\X}^{(n)} - p_{\X} \big\|_1 \leq \nicefrac{|\X|}{n} =: \delta_n$ \cite{CK11}.
			The continuity of the Augustin information further yields the cost (\cite[Proposition 5-(c)]{CGH19}):
			\begin{align}
				H_{\text{b}}(\delta_n) + \delta_n \cdot \sup\nolimits_{p_{\X}} \breve{I}_{1}(\X:\B)_{\rho}.
			\end{align}
			where $H_{\text{b}}(q) = - q \log_2 q - (1-q) \log_2 (1-q) \leq \big(4q (1-q)\big)^{ \nicefrac{1}{\log 4}}$ is the binary entropy function.
			Overall, the additional cost (for allowing $p_{\X}$ to be a general distribution) to the right-hand side of \eqref{eq:CC_bound1} is 
			\begin{align}
				\frac{1-\alpha}{\alpha} |\X| \left[
				4^{ \nicefrac{1}{\log 4}} \cdot n^{ 1 -  \nicefrac{1}{\log 4}} + \sup\nolimits_{p_{\X}} \breve{I}_{1}(\X:\B)_{\rho}
				\right].
			\end{align}
		\end{remark}

		\begin{remark} \label{remark:CK}
			In the commuting case, Theorem~\ref{theo:CC} recovers (the non-asymptotic version of) Csisz{\'a}r--K{\"o}rner's random coding bound \cite[Theorem 10.2]{CK11}.
			Note that our result in terms of the parametric R\'enyi divergence, $\sup_{\alpha\in[\nicefrac{1}{2},1]} \frac{1-\alpha}{\alpha} \left[ \breve{I}_{\alpha}(\X:\B)_{\rho} - R \right]$, is commonly called the \emph{dual domain} expression \cite{Bla74}, while Csisz{\'a}r--K{\"o}rner's result is expressed in the \emph{primal domain} (which matches the Haroutunian's form of the sphere-packing bound \cite{Har68}):
			\begin{align} \label{eq:CK}
				\inf_{ \mathscr{M}_{\X\to\B}\colon x\mapsto \sigma_{\B}^x  } \left\{
				\mathds{E}_{x\sim p_{\X}} D_1( \sigma_{\B}^x \Vert \rho_{\B}^x ) + 
				\left( \breve{I}_1(\X:\B)_{\sigma} - R
				\right)_+
				\right\}.
			\end{align}
			However, in the noncommuting case, the dual-domain expression of \eqref{eq:CK} corresponds to the Augustin information defined via the \emph{log-Euclidean} \Renyi divergence \cite{MO14, Dal16, CHT19}, instead of the Petz--\Renyi divergence.
			This means that the random coding error exponent of the form \eqref{eq:CK} is generally not achievable because of the sphere-packing bound established in \cite{DW14, CHT19}.
			In light of this, our result in Theorem~\ref{theo:CC} is the only true expression to the best of our knowledge; we do not know if there is a primal domain expression as in the classical case.
		\end{remark}

		\begin{remark}\label{remark:Augustin_vs_Renyi}
			The Augustin information is greater than the \Renyi information for all orders, i.e., $\breve{I}_{\alpha}(\X:\B)_{\rho} \geq I_{\alpha}(\X:\B)_{\rho}$ (for all $p_{\X}$ but the optimal ones) by Jensen's inequality \cite{nakiboglu_augustin_2018, MO14, MO18, CGH19}, resulting in a faster exponential decay rate, but they are all equal to the \Renyi radius after optimizing over $p_{\X}$ \cite[\S IV]{MO14}.
			This phenomenon for classical-quantum channels again confirms Gallager's observation \cite{Gal94}: 
			Constant composition codes act as a better ensemble than the ensemble with independently chosen letters.
		\end{remark}

		\begin{proof}
			First, the probability of the typical sequences under the i.i.d.~$p_{\X}^{\otimes n} $ is lower bounded by (\cite[\S 2]{CK11}):\footnote{The probability $p_{\X}^{\otimes n}(\mathcal{T}_{p_{\X}}^n)$ can be explicitly calculated by Stirling’s formula; see e.g.,~\cite[p.~26]{CK11}.
				Hence, the polynomial prefactor in Theorem~\ref{theo:CC} can be tightened slightly.}
			\[
			p_{\X}^{\otimes n}(\mathcal{T}_{p_{\X}}^n) \geq  (n+1)^{- |\X|}.
			\]
			Then, we apply the one-shot bound in Theorem~\ref{theo:CC-one-shot}, the tensorization property of the Augustin mean, and the additivity of the Petz--R\'enyi divergence to conclude the proof, namely,
			\begin{equation*}
				% \begin{aligned}[b]
					\inf_{x^n \in T_{p_{\X}}^n } \frac{1}{n} D_{\alpha}\left( \rho_{\B^n}^{x^n} \Vert \sigma_{\B^n}^{\star} \right)
					= \inf_{x^n \in T_{p_{\X}}^n } \frac{1}{n} D_{\alpha}\left( \rho_{\B^n}^{x^n} \Vert (\sigma_{\B}^{\star})^{\otimes n} \right)
					% = \frac1n \breve{I}_{\alpha}(\X^n:\B^n)_{\rho^{\otimes n}}
					= \breve{I}_{\alpha}(\X:\B)_{\rho}.
					% \end{aligned}\qedhere
			\end{equation*}

			The converse (i.e., the so-called sphere-packing bound) was derived in \cite[Theorem 8]{CHT19}:
			\begin{align}
				- \log_2 \varepsilon(\X^n:\B^n)_{\breve{p}} \leq n \cdot  \sup_{\alpha \in (0,1]} \frac{1-\alpha}{\alpha} \left[ \breve{I}_{\alpha}(\X:\B)_{\rho} - R \right] + \mathcal{O}(\log_2 n)
			\end{align}
			(see also for the asymptotic result in \cite{DW14}).
		\end{proof}

