		\section{Classical Data Compression with Quantum Side Information} \label{sec:CQSW}

		In this section, we first show a generic one-shot achievability bound for classical data compression with quantum side information.
		In Section~\ref{sec:iid_fixed-length}, we consider the $n$-shot setting where the sources are generated in a i.i.d.~fashion, and the compressed indices are of fixed length.
		In Section~\ref{sec:type_fixed-length}, we consider sources generated from a constant type class uniformly at random.
		In Section~\ref{sec:iid_variable-length}, we go back to $n$-shot i.i.d.~sources but now with variable-length coding.

		\begin{defn}[Classical data compression with quantum side information]
			Let $\rho_{\X\B} = \sum_{x\in\X} p_{\X} (x) |x\rangle \langle x|_{\X} \otimes \rho_{\B}^x \in \mathcal{S}(\X\B)$ be a classical-quantum state.
			% Without loss of generality, we assume that the prior distribution of the source, $p_{\X}$, has full support.
			\begin{enumerate}[1.]
				\item Alice has classical registers $\X$ and $\mathsf{M}$, and Bob has a quantum register $\B$.

				\item An encoder $\mathcal{E}\colon x\mapsto m(x)$
				at Alice compress the source in $\X$ to an index in $\mathsf{M}$.

				\item According to the compressed index $m$, Bob applies a decoding measurement described by a family of POVMs indexed by $m\in\mathsf{M}$, i.e.,~$\{ {\Lambda}_{\B}^{x,m} \}_{x\in\mathsf{X}}$ on register $\B$, to recover the source $x\in\X$.
			\end{enumerate}
			Again, we adopt the conventional random coding to compress each source letter $x\in\X$ to an uniform index $m\in\mathsf{M}$.
			Then, the minimum random coding error probability for $\rho_{\X\B}$ with index size $|\mathsf{M}|$ is 
			\begin{align} \label{eq:error_CQSW}
				\varepsilon(\X\mid\B)_{\rho}
				\coloneq
				\inf_{ \big\{ \Lambda_{\B}^{x,m} \big\} } \sum_{ x\in\X }	p_{\X}(x)  \mathds{E}_{m(x)\sim \frac{1}{|\mathsf{M}|} }
				\Tr\left[ \rho_{\B}^{x} \left(\I_{\B} -  {\Lambda}_{\B}^{x, m} \right) \right].
			\end{align}
		\end{defn}


		Given a realization of the random codebook, we adopt the integral $\alpha$-PGM for each family $m\in\mathsf{M}$:
		\begin{align} \notag
			\mathring{\Pi}_{\mathsf{B}}^{x,m} 
			\coloneq \frac{ \left(p_{\X}(x) \rho_{\B}^x\right)^{\alpha} }{ \sum_{\bar{x}: \mathcal{E}(\bar{x}) = m } \left( p_{\X}(\bar{x}) \rho_{\B}^{\bar{x}}\right)^{\alpha} }, \quad \forall x\in \X: \mathcal{E}(x)=m, \; \alpha \in [\sfrac{1}{2},1].
		\end{align}

		\begin{theo} \label{theo:CQSW}
			For any classical-quantum state $\rho_{\X\B}$, the minimum random coding error probability \eqref{eq:error_CQSW} for compressing the source into $|\mathsf{M}|$ indices is upper bounded by
			\begin{align*}
				\varepsilon(\X\mid\B)_{\rho}
				&\leq c_{\alpha} |\mathsf{M}|^{\frac{\alpha-1}{\alpha}} \Tr\left[ \left( \sum_{x\in\X} \left[ p_{\X}(x) \rho_{\B}^x \right]^{\alpha} \right)^{\nicefrac{1}{\alpha}} \right]
				\\
				&= c_{\alpha} \cdot 2^{ - \frac{1-\alpha}{\alpha} \left[ \log_2 \left|\mathsf{M}\right| - H_{\alpha}(\X\mid\B)_{\rho} \right]  },
				\quad \forall\, \alpha \in [\nicefrac{1}{2},1].
			\end{align*}
			Here, $H_{\alpha} (\mathsf{X}\mid\B)_{\rho} \coloneq -\inf_{\sigma_{\B} \in \mathcal{S}(\B) } D_{\alpha}(\rho_{\mathsf{X}\B}\Vert \I_{\mathsf{X}} \otimes \sigma_{\B}) $ is the order-$\alpha$ conditional Petz--R\'enyi entropy.
		\end{theo}



		The quantum Sibson identity 
		\cite[Lemma 3 in Supplementary Material]{SW12}, \cite[(3.10)]{HT14}, \cite{CGH19} showed that the minimizer in $H_{\alpha} (\mathsf{X}\mid\B)_{\rho}$ attained by
		\begin{align} \label{eq:Renyi_mean_CQSW}
			\sigma_{\B}^{\star} = \frac{
				\left( \sum_{x\in\mathsf{X}} \left[p_{\mathsf{X}}(x) \rho_{\mathsf{B}}^x\right]^{\alpha}  \right)^{\nicefrac{1}{\alpha}}
			}{
				\Tr \left[
				\left( \sum_{x\in\mathsf{X}} \left[p_{\mathsf{X}}(x) \rho_{\mathsf{B}}^x\right]^{\alpha}  \right)^{\nicefrac{1}{\alpha}}
				\right], \quad \alpha > 0,
			},
		\end{align}
		and, hence, the order-$\alpha$ conditional Petz--R\'enyi entropy with respect to the state $\rho_{\mathsf{X}\B}$
		admits a closed-form expression:
		\[
		H_{\alpha} (\X \mid \B)_{\rho} 
		= -D_{\alpha}\left(\rho_{\X\B}\Vert \I_{\X} \otimes \sigma_{\B}^{\star}\right)
		=
		\frac{\alpha}{1-\alpha} \log_2 \Tr \left[
		\left( \sum_{x\in\mathsf{X}} \left[p_{\mathsf{X}}(x) 
		\rho_{\mathsf{B}}^x\right]^{\alpha}  \right)^{\nicefrac{1}{\alpha}}
		\right].
		\]

		\begin{proof}
			We apply Proposition~\ref{prop:key} with $A\leftarrow p_{\X}(x) \rho_{\B}^x$ and $B \leftarrow  \left[ \sum_{\bar{x}\neq x, \, \mathcal{E}(\bar{x})= m } \left(p_{\X}(\bar{x}) \rho_{\B}^{\bar{x}}\right)^{\alpha} \right]^{\nicefrac{1}{\alpha}}$ to obtain, for every $x\in\X$,
			\begin{align*}
				&\mathds{E}_{m \sim \frac{1}{|\mathsf{M}|} } \Tr\left[ p_{\X}(x) \rho_{\B}^x \frac{ \sum_{\bar{x}\neq x, \, \mathcal{E}(\bar{x})= m } \left(p_{\X}(\bar{x}) \rho_{\B}^{\bar{x}}\right)^{\alpha} }{ 
					\left( p_{\X}(x) \rho_{\B}^x \right)^{\alpha} + \sum_{\bar{x}\neq x, \, \mathcal{E}(\bar{x})= m } \left(p_{\X}(\bar{x}) \rho_{\B}^{\bar{x}}\right)^{\alpha} } \right]
				\\
				&\leq
				c_{\alpha}  \mathds{E}_{m \sim \frac{1}{|\mathsf{M}|} } \Tr\left[ \left( p_{\X}(x) \rho_{\B}^x\right)^{\alpha} \left( \sum_{\bar{x}\neq x, \, \mathcal{E}(\bar{x})= m } \left(p_{\X}(\bar{x}) \rho_{\B}^{\bar{x}}\right)^{\alpha} 
				\right)^{\frac{1-\alpha}{\alpha}} \right]
				\\
				&\overset{\text{(a)}}{\leq}
				c_{\alpha}   \Tr\left[ \left( p_{\X}(x) \rho_{\B}^x\right)^{\alpha} \left( \mathds{E}_{m \sim \frac{1}{|\mathsf{M}|} } \sum_{\bar{x}\neq x, \, \mathcal{E}(\bar{x})= m } \left(p_{\X}(\bar{x}) \rho_{\B}^{\bar{x}}\right)^{\alpha} 
				\right)^{\frac{1-\alpha}{\alpha}} \right]
				\\
				&= c_{\alpha}   \Tr\left[ \left( p_{\X}(x) \rho_{\B}^x\right)^{\alpha} \left( \sum_{\bar{x}\neq x} \frac{1}{|\mathsf{M}|} \left(p_{\X}(\bar{x}) \rho_{\B}^{\bar{x}}\right)^{\alpha} 
				\right)^{\frac{1-\alpha}{\alpha}} \right]
				\\
				&\overset{\text{(b)}}{\leq} c_{\alpha} |\mathsf{M}|^{\frac{\alpha-1}{\alpha}}  \Tr\left[ \left( p_{\X}(x) \rho_{\B}^x\right)^{\alpha} \left( \sum_{\bar{x} \in \mathsf{X} } \left(p_{\X}(\bar{x}) \rho_{\B}^{\bar{x}}\right)^{\alpha} 
				\right)^{\frac{1-\alpha}{\alpha}} \right],
			\end{align*}
			where inequality (a) is because the power function $0\leq x\mapsto x^{\frac{1-\alpha}{\alpha}}$ is operator concave for $\frac{1-\alpha}{\alpha} \in [0,1]$;
			inequality (b) is because the power function $0\leq x\mapsto x^{\frac{1-\alpha}{\alpha}}$ is operator monotone for $\frac{1-\alpha}{\alpha} \in [0,1]$.

			Summarizing the above inequality over all $x\in\X$ concludes the proof.
		\end{proof}

		\subsection{I.I.D.~Sources With Fixed-Length Coding} \label{sec:iid_fixed-length}

		In the i.i.d.~scenario, each $n$-length source $x^n = x_1 x_2 \ldots x_n \in \X^n$ is distributed according to a common i.i.d.~distribution $p_{\X}^{\otimes n}$, and each source is associated with quantum side information $\rho_{\B^n}^{x_n} \coloneq \rho_{\B_1}^{x_1} \otimes \rho_{\B_2}^{x_2} \otimes \cdots \otimes \rho_{B_n}^{x_n}$.
		In fixed-length coding, each source $x^n$ is compressed to a shorter sequence of fixed length, i.e., $|\mathsf{M}| = \ceil{ 2^{nR} }$, where $R$ is called the \emph{compression rate}.

		The resulting joint classical-quantum state for the i.i.d.~source is $\rho_{\X\B}^{\otimes n}$.
		By applying the one-shot bound in Theorem~\ref{theo:CQSW}, we have the following characterization of the optimal error exponent.

		\begin{theo} \label{theo:CQSW_iid}
			The optimal error exponent for compressing the i.i.d.~source $\rho_{\X\B}^{\otimes n}$ of fixed length with compression rate $R$ is given by
			\begin{align*}
				\lim_{n\to \infty} - \frac{1}{n} \log_2 \varepsilon(\X^n\mid\B^n)_{\rho^{\otimes n}}
				=
				\sup_{\alpha \in [\nicefrac{1}{2},1]} \frac{1-\alpha}{\alpha} \left[ R - H_{\alpha}(\X\mid\B)_{\rho} \right] 
			\end{align*}
			for $R \leq \left.\frac{\d}{\d s} - s {D}_{\frac{1}{1+s}}(\rho_{\X\B}\Vert\I_{\X}\otimes \rho_{\B})\right|_{s=1}$.
		\end{theo}
		\begin{remark}
			Renes also obtained the characterization of the optimal error exponent \cite{Ren23}, while the achievability bound is with a dimension-dependent prefactor (which is of order $(n+1)^{\text{dim } (\mathcal{H}_{\B})}$ in the i.i.d.~scenario).
		\end{remark}

		\begin{proof}
			The converse bound has been derived in \cite[Theorem 2]{CHDH-2018}:
			\begin{align*}
				- \log \varepsilon(\X^n\mid\B^n)_{\rho^{\otimes n}}
				\leq  n \cdot \sup_{\alpha \in [0,1]} \frac{1-\alpha}{\alpha} \left[ R - H_{\alpha}(\X\mid\B)_{\rho} \right] +  \mathcal{O}(\log_2 n).
			\end{align*}
			The lower bound follows from Theorem~\ref{theo:CQSW} and the additivity:
			$H_{\alpha}(\X^n \mid\B^n )_{\rho^{\otimes n}} = n H_{\alpha}(\X\mid\B)_{\rho}$ as the minimizer in \eqref{eq:Renyi_mean_CQSW} is multiplicative.
		\end{proof}

		\subsection{Constant-Type Sources With Fixed-Length Coding} \label{sec:type_fixed-length}

		Fix an integer $n\in\mathds{N}$ and let a probability distribution $Q$ on $\X$ be an $n$-type.
		Now each source $x^n \in \X^n$ is distributed uniformly over the type class $\mathcal{T}_Q^n$, i.e.,
		\begin{align} \label{eq:CC-source}
			p_{\mathcal{T}_Q^n}(x^n) = \frac{ 1  }{\left| \mathcal{T}_{Q}^n \right|} \left\{ x^n \in  \mathcal{T}_{Q}^n  \right\}, \quad \forall\, x^n \in \X^n.
		\end{align}
		The resulting classical-quantum state
		\begin{align} \label{eq:const-type}
			\breve{\rho}_{\X^n \B^n}^{(Q)}
			= \sum_{x^n \in \X} p_{\mathcal{T}_Q^n}(x^n) |x^n\rangle \langle |_{\X^n} \otimes \rho_{\B^n}^{x^n}
		\end{align}
		is no longer a product state as in Section~\ref{sec:cc_codes}.

		\begin{theo} \label{theo:CQSW_cc}
			The optimal error exponent for compressing the source $\breve{\rho}_{\X^n \B^n}^{(Q)}$ in \eqref{eq:const-type} of an $n$-type $Q$  with compression rate $R$ is given by
			\begin{align*}
				\lim_{n\to \infty} - \frac{1}{n} \log_2 \varepsilon(\X^n\mid\B^n)_{\breve{\rho}^{(Q)}}
				=
				\sup_{\alpha \in [\nicefrac{1}{2},1]} \frac{1-\alpha}{\alpha} \left[ R - H(\X)_Q + \breve{I}_{\alpha}(\X:\B)_{\rho^{(Q)}} \right]
			\end{align*}
			for $R \leq H(\X)_Q - \left.\frac{\d}{\d s} s \breve{I}_{\frac{1}{1+s}}(\X:\B)_{\rho^{(Q)}}\right|_{s=1}$.
			Here, the order-$\alpha$ Petz--Augustin information $\breve{I}_{\alpha}(\X:\B)_{\rho^{(Q)}}$ is defined in \eqref{eq:Augustin} with respect to the state $\rho_{\X\B}^{(Q)} := \sum_{x\in\X} Q(x) |x\rangle \langle x |_{\X} \otimes \rho_{\B}^x$,
			and $H(\X)_Q := - \sum_{x\in\X} Q(x) \log_2 Q(x)$ is the Shannon entropy.
		\end{theo}

		\begin{remark}
			The order-$\alpha$ Petz--Augustin information $\breve{I}_{\alpha}$ generally does not have a closed-form expression for $\alpha \neq 1$.
			However, Ref.~\cite{CB24} showed that it is still analytical in the order $\alpha$.
		\end{remark}

		\begin{proof}
			The converse has been derived in 
			\cite[Theorem 5]{CHDH2-2018}:
			\begin{align}
				- \log \varepsilon(\X^n\mid\B^n)_{\breve{\rho}^{(Q)}}
				\leq n \cdot \sup_{\alpha \in [0,1]} \frac{1-\alpha}{\alpha} \left[ R - H(\X)_Q + \breve{I}_{\alpha}(\X:\B)_{\rho^{(Q)}} \right].
			\end{align}
			However, the achievability bound therein is not asymptotically tight.
			Nonetheless, \cite[Theorem 2]{CHDH2-2018} showed that the minimum error of the constant-type source compression with quantum side information of rate $R$ is at most twice of the minimum error of communication over the classical-quantum channel $x\mapsto \rho_{\B}^x$ via codes of the same composition with rate $ H(\X)_Q - R + \frac{1}{n} \log_2( 2n \log_2(|\X|+1) )$.
			By invoking Theorem~\ref{theo:CC} and taking $n\to \infty$, we conclude the proof.
		\end{proof}

		\subsection{I.I.D.~Sources With Variable-Length Coding} \label{sec:iid_variable-length}

		Now let us go back to the i.i.d.~source scenario, i.e., $\rho_{\X\B}^{\otimes n}$ for
		\begin{align} \label{eq:state_variable}
			\rho_{\X\B} = \sum_{x\in\X} p_{\X} |x\rangle\langle x|_{\X} \otimes \rho_{\B}^x.
		\end{align}
		In variable-length coding, each source is compressed to a binary sequence in $\{0,1\}^*$ with probably a different length via an encoder $\mathscr{E}: \X^n \to \{0,1\}^*$.
		We then define the \emph{average rate} of the code as the expectation
		\begin{align}
			\bar{R} := \frac{1}{n} \mathds{E}_{x^n \sim p_{\X}^{\otimes n} } \left[ \mathtt{length}\left( \mathscr{E}(x^n) \right) \right].
		\end{align}

		\begin{theo} \label{theo:CQSW_variable}
			The optimal error exponent for compressing the i.i.d.~source $\rho_{\X\B}^{\otimes n}$ via variable-length coding with average rate $\bar{R}$ is given by
			\begin{align*}
				\lim_{n\to \infty} - \frac{1}{n} \log_2 \varepsilon(\X^n\mid\B^n)_{\rho^{\otimes n}}
				=
				\sup_{\alpha \in [\nicefrac{1}{2},1]} \frac{1-\alpha}{\alpha} \left[ \bar{R} - H(\X)_{p} + \breve{I}_{\alpha}(\X:\B)_{\rho} \right]
			\end{align*}
			for $H(\X\mid\B)_{\rho} < \bar{R} \leq H(\X)_p - \left.\frac{\d}{\d s} s \breve{I}_{\frac{1}{1+s}}(\X:\B)_{\rho}\right|_{s=1}$.
			Here, the order-$\alpha$ Petz--Augustin information $\breve{I}_{\alpha}(\X:\B)_{\rho}$ is defined in \eqref{eq:Augustin} with respect to the state in \eqref{eq:state_variable},
			and $H(\X)_p := - \sum_{x\in\X} p_{\X}(x) \log_2 p_{\X}(x)$ is the Shannon entropy.
		\end{theo}

		\begin{proof}
			Ref.~\cite[Theorem 13]{CHDH2-2018} showed that the optimal error exponent of variable-length coding with average rate $\bar{R} > H(\X\mid\B)_{\rho}$ is equal to that of classical-quantum channel coding with constant composition $p_{\X}$ and rate $H(\X)_p - R$.
			Our contribution here is to fill the achievability gap in \cite[Proposition 5.1]{CHDH2-2018} by invoking Theorem~\ref{theo:CC}.
		\end{proof}

