		\section{Unassisted Classical Communication over Quantum Channels} \label{sec:unassisted}

		\begin{defn}[Unassisted classical communication over quantum channels]
			Let $\mathscr{N}_{\A\to \B}\colon \mathcal{S}(\A) \to \mathcal{S}(\B)$ be a quantum channel.
			\begin{enumerate}[1.]
				\item Alice has a classical register $\mathsf{M}$ and a quantum register $\A$, and Bob has a quantum register $\B$.

				\item For any (equiprobable) message $m\in\mathsf{M}$ Alice wants to send, she encodes it into an input state on her quantum register $\A$.

				\item 
				Alice's quantum state on the register $\A$ undergoes the quantum channel $\mathcal{N}_{\A\to \B}$ and ends up with an output state on Bob's quantum register $\B$.

				\item Bob applies a decoding measurement $\{ {\Pi}_{\\B}^m\}_{m\in\mathsf{M}}$ on his quantum register $\B$ to obtain an estimated message $\hat{m} \in \mathsf{M}$.
			\end{enumerate}
			As in Section~\ref{sec:CQ}, we employ the conventional random coding strategy but now with a quantum ensemble $\{ p_{\X}(x), \rho_{\A}^x \}_{x \in \X} $, where the classical register $\X$ could be an arbitrary alphabet and the ensemble can be represented by a classical-quantum state \begin{align} \label{eq:CQ-state_unassisted}
				\rho_{\X\A} = \sum_{x\in\X} p_{\X}(x)|x\rangle \langle x|_{\X} \otimes \rho_{\A}^x.
			\end{align}
			Specifically, each message $m\in \mathsf{M}$ is encoded to a quantum codeword $\rho_{\A}^{x(m)}$ pairwise-independently with probability $p_{\mathsf{X}}(x(m))$.
			Then, the minimum \emph{random coding error probability} for sending $M$  messages through channel $\mathscr{N}_{\mathsf{A}\to\B}$ with the quantum ensemble $\rho_{\X\A}$ is
			\begin{align} \label{eq:error_unassisted}
				\varepsilon(\mathsf{X}:\B)_{\mathscr{N}(\rho)}
				&\coloneq
				\inf_{ \big\{ {\Lambda}_{\B}^{m} \big\}_{m\in\mathsf{M}} } \frac{1}{|\mathsf{M}|}  \sum_{m\in \mathsf{M}}	\mathds{E}_{x(m)\sim p_{\mathsf{X}}}
				\Tr\left[ \mathscr{N}_{\A\to \B}\left(\rho_{\A}^{x(m)}\right) \left(\I_{\B} -  {\Lambda}_{\B}^{m} \right) \right].
			\end{align}
		\end{defn}

		Evidently, our analysis for classical-quantum channel coding in Section~\ref{sec:CQ} applies to classical communication over any quantum channel $\mathscr{N}_{\A\to \B}$ by the substitution $\rho_{\B}^{x(m)} \leftarrow \mathscr{N}_{\A\to \B}\left( \rho_{\A}^{x(m)} \right)$. Hence, the integral $\alpha$-PGM is constructed according to the channel images:
		\begin{align} \notag
			\Pi_{\mathsf{B}}^{x(m)} 
			\coloneq \frac{\left[ \mathscr{N}_{\A\to \B}\left( \rho_{\A}^{x(m)} \right) \right]^{\alpha}}{\sum_{\bar{m}\in \mathsf{M} } \left[ \mathscr{N}_{\A\to \B}\left( \rho_{\A}^{x(\bar{m})} \right)\right]^{\alpha} }, \quad \forall \, m \in \mathsf{M}, \; \alpha \in [\sfrac{1}{2},1].
		\end{align}
		Then, we immediately obtain the following result.
		\begin{theo} \label{theo:CQ_unassisted} %~\\
			For any quantum channel $\mathscr{N}_{\mathsf{A} \to \B}$, the minimum random coding error probability \eqref{eq:error_unassisted} for sending $|\mathsf{M}|$ messages with a quantum ensemble $\rho_{\X\A} = \sum_{x\in\X} p_{\X}(x)|x\rangle\langle x|_{\X} \otimes \rho_{\A}^x$ is upper bounded by
			\begin{align} \notag
				\varepsilon(\X:\B)_{\mathscr{N}(\rho)}
				&\leq c_{\alpha}
				(|\mathsf{M}|-1)^{\frac{1-\alpha}{\alpha}}
				\Tr \left[
				\left( \sum_{x\in\mathsf{X}} p_{\mathsf{X}}(x) \left[ \mathscr{N}_{\A\to\B}\left(\rho_{\mathsf{A}}^x\right)\right]^{\alpha}  \right)^{\nicefrac{1}{\alpha}}
				\right]
				\\
				\notag
				&= c_{\alpha} \cdot
				2^{
					-\frac{1-\alpha}{\alpha} \left[ I_{\alpha} (\mathsf{X} \,:\, \B)_{\mathscr{N}(\rho)} - \log_2 (|\mathsf{M}|-1)  \right]
				}, \quad \forall\, \alpha \in [\nicefrac{1}{2},1].
			\end{align}
		\end{theo}

		We may define the \emph{order-$\alpha$ Holevo quantity} by optimizing the encoding quantum ensemble $\rho_{\X\A}$:
		\begin{align} \label{eq:Holevo_quantity}
			\chi_{\alpha}(\mathscr{N}_{\A\to\B})
			\coloneq \sup_{ \rho_{\X\A} \in \mathcal{S}(\X\A) } I_{\alpha} (\mathsf{X} \,:\, \B)_{\mathscr{N}(\rho)}.
		\end{align}
		For any channel whose Holevo quantity is additive, i.e., $\chi_{\alpha}\left(\mathscr{N}_{\A\to\B}^{\otimes n}\right) = n \chi_{\alpha}(\mathscr{N}_{\A\to\B})$,
		our result in Theorem~\ref{theo:CQ_unassisted} applies to exponential decays for \emph{any}  blocklength $n\in\mathds{N}$.
		Even if the Holevo quantity is not additive, one may choose an entangled channel input in the ensemble so as to achieve the \emph{regularized} Holevo quantity:\footnote{As in the order-$1$ scenario, it is not hard to see that $\chi_{\alpha}$ superadditive. Hence, the limit as $n\to \infty$ is equal to taking supremum over $n \in \mathds{N}$.}
		\[
		\chi_{\alpha}^{(\infty)}(\mathscr{N}_{\A\to\B})
		\coloneq \lim_{n\to \infty} \frac{1}{n}
		\chi_{\alpha}\left(\mathscr{N}_{\A\to\B}^{\otimes n}\right).
		\]
		For purely theoretical analysis, our result shows that the following fundamental limit in principle is achievable: For any rate $R \coloneq \lim_{n\to \infty} \frac{1}{n} \log |\mathsf{M}|$,
		\[
		\sup_{\alpha \in [\sfrac12,1]} \frac{1-\alpha}{\alpha} \left[ \chi_{\alpha}^{(\infty)}(\mathscr{N}_{\A\to\B}) - R \right].
		\]
		This error exponent is positive if and only if the communication rate is below the order-$1$ regularized Holevo quantity $R < \chi_{1}^{(\infty)}(\mathscr{N}_{\A\to \B})$, which is known as the (asymptotic) classical capacity of the quantum channel $\mathscr{N}_{\A\to \B}$.
		Unfortunately, computationally finding the $\chi_{\alpha}^{(\infty)}$-achieving-input-ensembles and practically implementing such an asymptotic encoding strategy are highly challenging.
		Nevertheless, our one-shot result established in Theorem~\ref{theo:CQ_unassisted} applies to any input ensemble $\rho_{\X^n \A^n}$ for any $n\in\mathds{N}$ (some of which may hopefully be  easier to implement in practice).
		Moreover, for product channels (not necessary stationary) and using non-entangled input states,  Theorem~\ref{theo:CQ_unassisted} demonstrates exponential decays for any blocklength.


