		\section{Entanglement-Assisted Classical Communication} \label{sec:EA}

		\begin{defn}[Entanglement-assisted classical communication over quantum channels] ~\\
			Let $\mathscr{N}_{\A\to \B}\colon\mathcal{S}(\A) \to \mathcal{S}(\B)$ be a quantum channel.
			\begin{enumerate}[1.]
				\item Alice has a classical register $\mathsf{M}$ with cardinality $M\coloneq |\mathsf{M}|$ and quantum registers $\A$ and $\A'$, and Bob has quantum registers $\B$ and $\B'$.

				\item An arbitrary state $\theta_{\B'\A'}$ is shared between Bob and Alice as a resource in assisting communication.

				\item For any (equiprobable) message $m\in\mathsf{M}$ Alice wants to send, she applies an encoding quantum operation $\mathcal{E}_{\A'\to \A}^m$ on $\theta_{\B'\A'}$.

				\item 
				Alice's quantum state on the register $\A$ undergoes the quantum channel $\mathcal{N}_{\A\to \B}$ and ends up with an output state on Bob's quantum register $\B$.

				\item Bob applies a decoding measurement $\{ {\Lambda}_{\B'\B}^m\}_{m\in\mathsf{M}}$ on registers $\B'$ and $\B$ to obtain an estimated message $\hat{m} \in \mathsf{M}$.
			\end{enumerate}
			We adopt the encoder of the \emph{position-based coding} \cite{AJW19a} as follows.
			Alice and Bob pre-share an $M$-fold product state $\theta_{\B'\A'} := \theta_{\R\A}^{\otimes M} = \theta_{\R_1\A_1}\otimes \cdots \otimes \theta_{\R_M\A_M}$, where $\R$ may be viewed as $\A$'s reference system.
			For sending each $m\in\mathsf{M}$, 
			Alice sends her system $\A_m$, i.e., $\mathcal{E}_{\A^M\to \A}^m = \Tr_{\A^{\mathsf{M}\backslash \{m\}}}$, by tracing out systems $\A_{\bar{m}}$ for all $\bar{m}\neq  m$. 	
			The minimum error probability for sending $M$ messages through channel $\mathscr{N}_{\A\to \B}$ with assistance of state $\theta_{\R\A}$ is defined as
			\begin{align} \label{eq:error_EA}
				\varepsilon(\R:\B)_{\mathcal{N}(\theta)}
				\coloneq
				\inf_{ \left\{ {\Lambda}_{\B'\B}^m\right\}_{m\in\mathsf{M}} }
				\frac{1}{M} \sum_{m\in \mathsf{M}}	\Tr\left[  \mathscr{N}_{\A\to\B} \circ \mathcal{E}_{\A'\to \A}^m\left(\theta_{\B'\A'}\right)
				\left( \I_{\B'\B}-  {\Lambda}_{\B'\B}^m \right)
				\right].
			\end{align}
		\end{defn}

		Bob applies the integral $\alpha$-PGM with respect to the channel output states:
		\begin{align} 
			\notag
			\mathring{\Pi}_{\R_1 \ldots \R_M \B}^m 
			&\coloneq \frac{ \left(\rho_{\R_1 \ldots \R_M  \B}^m\right)^{\alpha} }{ \sum_{\bar{m}\in\mathsf{M}} \left(\rho_{\R_1 \ldots \R_M \B}^{\bar{m}}\right)^{\alpha} }, \quad \forall \, m\in\mathsf{M},
			\; \alpha \in [\nicefrac{1}{2},1],
			\\
			\notag
			%\label{eq:rho_m}
			\rho_{\R_1 \ldots \R_M \B}^m 
			&\coloneq \theta_{\R}^{\otimes (m-1)} \otimes \mathcal{N}_{\A\to\B}(\theta_{\R_m\A_m}) \otimes \theta_{\R}^{\otimes (M-m)}, \quad \forall\, m\in\mathsf{M}.
		\end{align}

		\begin{theo} \label{theo:EA} %~\\
			For any quantum channel $\mathscr{N}_{\A \to \B}$, the minimum error \eqref{eq:error_EA} for sending $M$ messages with assisting state $\theta_{\R\A}$   is upper bounded by
			\begin{align} \notag
				\varepsilon(\R:\B)_{\rho}
				&\leq c_{\alpha}
				(M-1)^{\frac{1-\alpha}{\alpha}}
				\Tr_{\mathsf{B}} \left[
				\left( \Tr_{\mathsf{R}} \left[ \rho_{\mathsf{RB}}^{\alpha} \theta_{\mathsf{R}}^{1-\alpha} \right]
				\right)^{\nicefrac{1}{\alpha}}
				\right]
				\\
				\notag
				&= c_{\alpha} \cdot
				2^{
					-\frac{1-\alpha}{\alpha} \left[ I_{\alpha} (\R \,:\, \B)_{\mathcal{N}(\theta)} - \log_2 (M-1) \right]
				}, \quad \forall\, \alpha \in [\nicefrac{1}{2},1].
			\end{align}
			Here, $\rho_{\mathsf{RB}} \coloneq \mathcal{N}_{\A \to \B}\left(\theta_{\R\A}\right)$ with $\rho_{\R} = \theta_{\R}$
			and $I_{\alpha} (\R:\B)_{\rho} \coloneq \inf_{\sigma_{\B} \in \mathcal{S}(\B) } D_{\alpha}(\rho_{\R\B}\Vert \rho_{\R} \otimes \sigma_{\B}) $ is the order-$\alpha$ Petz--R\'enyi information.
		\end{theo}

		The quantum Sibson identity \cite[(3.10)]{HT14}, \cite{CGH19} showed that the minimizer in $I_{\alpha} (\R:\B)_{\rho}$ is attained by
		\[
		\sigma_{\B}^{\star} = \frac{
			\left( \Tr_{\mathsf{R}} \left[ \rho_{\mathsf{RB}}^{\alpha} \rho_{\mathsf{R}}^{1-\alpha} 
			\right]\right)^{\nicefrac{1}{\alpha}}
		}{
			\Tr_{\mathsf{B}} \left[
			\left( \Tr_{\mathsf{R}} \left[ \rho_{\mathsf{RB}}^{\alpha} \rho_{\mathsf{R}}^{1-\alpha} \right]
			\right)^{\nicefrac{1}{\alpha}}
			\right]
		},
		\]
		and, hence, the order-$\alpha$ Petz--\Renyi information admits a closed-form expression:
		\[
		I_{\alpha} (\R:\B)_{\rho} 
		= D_{\alpha}\left(\rho_{\R\B}\Vert \rho_{\R} \otimes \sigma_{\B}^{\star}\right)
		=
		\frac{\alpha}{\alpha-1} \log_2 \Tr_{\mathsf{B}} \left[
		\left( \Tr_{\mathsf{R}} \left[ \rho_{\mathsf{RB}}^{\alpha} \rho_{\mathsf{R}}^{1-\alpha} \right]
		\right)^{\nicefrac{1}{\alpha}}
		\right].
		\]


		\begin{proof}
			By symmetry of the position-based encoding, we calculate the error probability for sending $m=1$ without loss of generality:
			\begin{align*}
				\varepsilon(\R:\B)_{\rho}
				&= \Tr\left[ \rho_{\R_1 \ldots \R_M \B}^1 \frac{ \sum_{\bar{m}\neq 1} \left(\rho_{\R_1 \ldots \R_M \B}^{\bar{m}}\right)^{\alpha} }{ 
					\left(\rho_{\R_1 \ldots \R_M \B}^{1}\right)^{\alpha}
					+ \sum_{\bar{m}\neq 1} \left(\rho_{\R_1 \ldots \R_M \B}^{\bar{m}}\right)^{\alpha}}
				\right]
				\\
				&\leq c_{\alpha} \cdot \Tr\left[ 
				\rho_{\mathsf{R}_1 \mathsf{B}}^{\alpha} \otimes \theta_{\mathsf{R}_2}^{\alpha} \otimes \theta_{\mathsf{R}_3}^{\alpha} \otimes \cdots \otimes \theta_{\mathsf{R}_M}^{\alpha}
				\cdot
				\left( 
				\sum_{\bar{m}= 2}^M \rho_{\mathsf{R}_{\bar{m}} \mathsf{B}}^{\alpha} \bigotimes\limits_{ m'\neq \bar{m} } \theta_{\mathsf{R_{m'}}}^{\alpha}
				\right)^{\frac{1-\alpha}{\alpha}}
				\right].
			\end{align*}
			Here, we again employ Proposition~\ref{prop:key} with
			\begin{align*}
				A &\leftarrow \rho_{\R_1 \ldots \R_M \B}^1 = \rho_{\mathsf{R}_1 \mathsf{B} }\otimes \theta_{\mathsf{R}_2} \otimes \theta_{\mathsf{R}_3} \otimes \cdots \otimes \theta_{\mathsf{R}_M},
				\\
				B^{\alpha} &\leftarrow \sum_{\bar{m}\neq 1} \left(\rho_{\R_1 \ldots \R_M \B}^{\bar{m}}\right)^{\alpha}
				= 
				\sum_{\bar{m}= 2}^M \rho_{\mathsf{R}_{\bar{m}} \mathsf{B}}^{\alpha} \bigotimes\limits_{ m'\neq \bar{m} } \theta_{\mathsf{R_{m'}}}^{\alpha}.
			\end{align*}

			To evaluate the trace term, we apply an operator Jensen inequality, detailed in Lemma~\ref{lemm:operator_Jensen} below with 
			${\mathsf{A}} \leftarrow \mathsf{R}_1 \mathsf{B}$ and
			$\mathsf{B} \leftarrow \mathsf{R}_2 \mathsf{R}_3 \ldots \mathsf{R}_M$,
			\begin{align*}
				Y_{\mathsf{AB}} 
				&\leftarrow \sum_{\bar{m}= 2}^M \rho_{\mathsf{R}_{\bar{m}} \mathsf{B}}^{\alpha} \bigotimes\limits_{ m'\neq \bar{m} } \theta_{\mathsf{R_{m'}}}^{\alpha},
				% &\leftarrow
				% \theta_{\mathsf{R}_1}^{\alpha}\otimes \rho_{\mathsf{R}_{2} \mathsf{B}}^{\alpha} \otimes \theta_{\mathsf{R}_3}^{\alpha} \otimes \theta_{\mathsf{R}_M}^{\alpha}
				% \\
				% &\quad + \theta_{\mathsf{R}_1}^{\alpha}\otimes \otimes \theta_{\mathsf{R}_2}^{\alpha} \otimes \rho_{\mathsf{R}_{3} \mathsf{B}}^{\alpha} \otimes \theta_{\mathsf{R}_4}^{\alpha} \otimes \theta_{\mathsf{R}_M}^{\alpha}
				% \\
				% &\quad + \cdots +
				% \theta_{\mathsf{R}_1}^{\alpha} \otimes \theta_{\mathsf{R}_2}^{\alpha} \otimes \cdot \otimes \theta_{\mathsf{R}_{M-1}}^{\alpha} \otimes \rho_{\mathsf{R}_{M} \mathsf{B}}^{\alpha}
				\\
				\tau_{\mathsf{B}}
				&\leftarrow \theta_{\mathsf{R}_2} \otimes \theta_{\mathsf{R}_3} \otimes\cdots \otimes \theta_{\mathsf{R}_M},
			\end{align*} 
			to obtain
			\begin{equation*}
				\begin{aligned}[b]
					&\Tr\left[ 
					\rho_{\mathsf{R}_1 \mathsf{B}}^{\alpha} \otimes \theta_{\mathsf{R}_2}^{\alpha} \otimes \theta_{\mathsf{R}_3}^{\alpha} \otimes \cdots \otimes \theta_{\mathsf{R}_M}^{\alpha}
					\cdot
					\left( 
					\sum_{\bar{m}= 2}^M \rho_{\mathsf{R}_{\bar{m}} \mathsf{B}}^{\alpha} \bigotimes\limits_{ m'\neq \bar{m} } \theta_{\mathsf{R_{m'}}}^{\alpha}
					\right)^{\frac{1-\alpha}{\alpha}}
					\right]
					\\
					&=
					\Tr_{\mathsf{R}_1 \mathsf{B}} \left[
					\rho_{\mathsf{R}_1 \mathsf{B}}^{\alpha} \cdot
					\Tr_{\mathsf{R}_2 \ldots \mathsf{R}_M}\left[
					\theta_{\mathsf{R}_2}^{\alpha} \otimes \cdots \otimes \theta_{\mathsf{R}_M}^{\alpha} \cdot
					\left( 
					\sum_{\bar{m}= 2}^M \rho_{\mathsf{R}_{\bar{m}} \mathsf{B}}^{\alpha} \bigotimes\limits_{ m'\neq \bar{m} } \theta_{\mathsf{R_{m'}}}^{\alpha}
					\right)^{\frac{1-\alpha}{\alpha}}
					\right]
					\right]
					\\
					&\leq
					\Tr_{\mathsf{R}_1 \mathsf{B}} \left[
					\rho_{\mathsf{R}_1 \mathsf{B}}^{\alpha} \cdot
					\left( \sum_{\bar{m}= 2}^M \theta_{\mathsf{R}_1}^{\alpha}\otimes \Tr_{ \mathsf{R}_{\bar{m}} } \left[ \rho_{\mathsf{R}_{\bar{m}} \mathsf{B}}^{\alpha} \theta_{\mathsf{R}_{\bar{m}}}^{1-\alpha} \right] \right)^{\frac{1-\alpha}{\alpha}}
					\right]
					\\
					&=
					(M-1)^{\frac{1-\alpha}{\alpha}} \cdot 
					\Tr_{\mathsf{R}_1 \mathsf{B}} \left[ \rho_{\mathsf{R}_1 \mathsf{B}}^{\alpha} \theta_{\mathsf{R}_1}^{1-\alpha} \cdot
					\left( \Tr_{\mathsf{R}_{\bar{m}}}\left[ \rho_{\mathsf{R}_{\bar{m}} \mathsf{B}}^{\alpha} \theta_{\mathsf{R}_{\bar{m}}}^{1-\alpha} \right]
					\right)^{\frac{1-\alpha}{\alpha}}
					\right]
					\\
					&=
					(M-1)^{\frac{1-\alpha}{\alpha}} \cdot 
					\Tr_{\mathsf{B}} \left[
					\left( \Tr_{\mathsf{R}} \left[ \rho_{\mathsf{RB}}^{\alpha} \theta_{\mathsf{R}}^{1-\alpha} \right]
					\right)^{\frac{1}{\alpha}}
					\right].
				\end{aligned}\qedhere
			\end{equation*}
		\end{proof}


		\begin{lemm} \label{lemm:operator_Jensen}
			For any positive semi-definite operator $Y_{\mathsf{AB}}  \geq 0$ on a Hilbert space $\mathcal{H}_{\mathsf{A}} \otimes 
			\mathcal{H}_{\mathsf{B}}$
			and
			any normalized state $\tau_{\mathsf{B}} $ on $\mathcal{H}_{\mathsf{B}}$,
			% and $\alpha \in [\sfrac{1}{2},1]$, 
			we have
			\begin{align*}
				\Tr_{\mathsf{B}} \left[ \tau_{\mathsf{B}}^{\alpha}\cdot 
				Y_{\mathsf{AB}}^{\frac{1-\alpha}{\alpha}}  
				\right]
				\leq 
				\left( \Tr_{\mathsf{B}} \left[ Y_{\mathsf{AB}} \cdot \tau_{\mathsf{B}}^{1-\alpha}\right] \right)^{\frac{1-\alpha}{\alpha}}, \quad \forall\, \alpha \in [\nicefrac{1}{2},1].
			\end{align*}
		\end{lemm}
		\begin{proof}
			Denote the spectral decomposition of $\tau_{\mathsf{B}}$ by
			$\tau_{\mathsf{B}} = \sum_i \lambda_i |i\rangle_{\mathsf{B}}\langle i|_{\mathsf{B}}$, where $\lambda_i\geq 0$ for each $i$, $\sum_i \lambda_i = 1$, and $\{|i\rangle_{\mathsf{B}}\}_i$ is an orthonormal basis of $\mathcal{H}_{\mathsf{B}}$.
			We calculate\footnote{By convention, the power in $\lambda_i^{-\alpha}$ is understood as taken on the support of (the constant function) $\lambda_i$. If $\lambda_i=0$ for some $i$, then the term $\lambda_i^{-\alpha}$ is void.}
			\begin{align*}\Tr_{\mathsf{B}} \left[ \tau_{\mathsf{B}}^{\alpha}\cdot 
				Y_{\mathsf{AB}}^{\frac{1-\alpha}{\alpha}}  
				\right]
				&=
				\sum_i \lambda_i^{\alpha} \cdot \mathbf{1}_{\mathsf{A}}\otimes \Big\langle i \Big|_{\mathsf{B}} Y_{\mathsf{AB}}^{\frac{1-\alpha}{\alpha}} \mathbf{1}_{\mathsf{A}}\otimes\Big|i\Big\rangle_{\mathsf{B}}
				\\
				&=
				\sum_i \lambda_i \cdot \mathbf{1}_{\mathsf{A}}\otimes \Big\langle i \Big|_{\mathsf{B}} \left( Y_{\mathsf{AB}} \cdot \lambda_i^{-\alpha} \right)^{\frac{1-\alpha}{\alpha}} \mathbf{1}_{\mathsf{A}}\otimes \Big|i\Big\rangle_{\mathsf{B}}
				\\
				&\leq 
				\left( 
				\sum_i \lambda_i \cdot \mathbf{1}_{\mathsf{A}}\otimes \Big\langle i \Big|_{\mathsf{B}} Y_{\mathsf{AB}} \cdot \lambda_i^{-\alpha} \mathbf{1}_{\mathsf{A}}\otimes \Big|i\Big\rangle_{\mathsf{B}}
				\right)^{\frac{1-\alpha}{\alpha}}
				\\
				&=
				\left( \Tr_{\mathsf{B}} \left[ Y_{\mathsf{AB}} \cdot \tau_{\mathsf{B}}^{1-\alpha}\right] \right)^{\frac{1-\alpha}{\alpha}}.
			\end{align*}
			Here, the inequality follows from the operator concavity of $0\leq x\mapsto x^{\frac{1-\alpha}{\alpha}}$ for $\frac{1-\alpha}{\alpha} \in [0,1]$ and the
			operator Jensen inequality \cite{HP03}, which states that:
			For any operator concave function $f$,
			any sequence $(X_1, X_2, \ldots)$
			of bounded self-adjoint operators on a Hilbert space $\mathcal{H}$ supported on the domain of $f$,
			and any sequence
			$(C_1, C_2, \ldots)$ of bounded operators from $\mathcal{K}$ to $\mathcal{H}$ satisfying $\sum_i C_i^{\dagger} \mathbf{1}_{\mathcal{H}} C_i = \mathbf{1}_{\mathcal{K}}$, 
			\begin{align*}
				\sum_i C_i^{\dagger} f(X_i) C_i
				\leq
				f\left( \sum_i C_i^{\dagger}  X_i C_i\right).
			\end{align*}
			In viewing 
			$\mathcal{K} \leftarrow \mathcal{H}_\mathsf{A}$,
			$\mathcal{H} \leftarrow \mathcal{H}_{\mathsf{A}}\otimes \mathcal{H}_{\mathsf{B}}$,
			$C_i \leftarrow \mathbf{1}_{\mathsf{A}} \otimes \sqrt{\lambda_i} |i\rangle_{\mathsf{B}}$ with 
			$\sum_i C_i^{\dagger} \cdot \mathbf{1}_{\mathsf{A}} \otimes \mathbf{1}_{\mathsf{B}} \cdot
			C_i = \sum_i \mathbf{1}_{\mathsf{A}} \otimes \lambda_i = \mathbf{1}_{\mathsf{A}}$, 
			and $X_i \leftarrow Y_{\mathsf{AB}} \cdot \lambda_i^{-\alpha}$,
			the proof is completed.
		\end{proof}

		\section{Conclusions} \label{sec:conclusions}

		We resolved the Burnashev--Holevo conjecture for classical-quantum channels with a prefactor $c< 1.102$ and show that Burnashev and Holevo's expectation holds even beyond to include arbitrary fully quantum channel for communicating classical information with or without entanglement-assistance.
		The same reasoning naturally extends to constant composition codes and classical data compression  with quantum side information via fixed-length coding or variable-length coding.

		The general proof recipe inherits Shannon and Gallager's random coding principle---employing random coding and a kind of union bound (via PGMs) to reduce the channel output ensemble to a proper binary quantum hypothesis testing problem.
		Our key contribution is to show that the integral $\alpha$-PGM decomposes to a family of the Holevo--Helstrom measurements with a uniform prior.
		The advantage of it is that usual techniques developed in binary hypothesis testing naturally apply here, so as to obtain the optimal tilting in large deviation analysis.

