		\section{Properties of The Operator Logarithm} \label{sec:log}

		In this section, we study the properties of the logarithm.
		We denote the \emph{principal logarithm} as follows:
		\begin{align} \label{eq:defn:Log}
			\Log (z) := \log (|z|) + \Arg(z) 
			= r + \mathrm{i} \theta, \quad \forall z = r \mathrm{e}^{\mathrm{i}\theta} \in \mathds{C}\backslash\mathds{R}_{\leq 0},
		\end{align}
		where $r>0$, $-\pi < \theta < \pi$, and $0<u\mapsto \log(u) $ is the real logarithm (with base  $\mathrm{e}$).

		For an operator $A$ whose spectrum does not cross the branch cut $\mathds{R}_{\leq 0}$, the principal logarithm is holomorphic in the spectrum.
		Then, the operator extension is defined via the functional calculus (see e.g.~\cite[\S 3]{HP14}, \cite[\S 11]{Hig08}, \cite[(5.47), p.~44]{Kat95}):
		\begin{align}
			\Log(A) := \frac{1}{2\pi \mathrm{i}}\ointctrclockwise_{C_A} \Log(z)\left( z \I - A \right)^{-1}\, \d z,
		\end{align}
		where $C_A$ is a simple closed (counterclockwise) contour containing the spectrum of $A$ without crossing the the branch cut.
		If, furthermore, $A>0$ is positive definite, then it reduces to the usual operator logarithm, i.e.,~$\Log (A) = \log (A)$.

		%For any positive definite operator $A$ and self-adjoint operator $B$,
		%we define the \emph{G{\^{a}}teaux differential} of logarithm at $A$ along the direction $B$ as
		%\begin{align} \label{eq:defn:Dlog}
		%	\mathrm{D}\log[A](B)
		%	&:= \lim_{t\to 0} \frac{\log(A+tB) - \log(A)}{t}.
		%\end{align}
		We denote the G{\^{a}}teaux differential (i.e.,~the directional derivative) of the principal logarithm at $A$ along the direction $B$ as
		\begin{align} \label{eq:defn:DLog}
			\mathrm{D}\Log[A](B)
			&:= \lim_{t\to 0} \frac{\Log(A+tB) - \Log(A)}{t}.
		\end{align}
		When $A>0$ is positive definite, we adopt the notation $\mathrm{D}\Log[A](B) = \mathrm{D}\log[A](B)$.

		\begin{fact}
			Let $A$ be an operator with $\spec(A) \subset \mathds{C}\backslash \mathds{R}_{\leq 0}$.
			The G{\^{a}}teaux differential of the principal logarithm in \eqref{eq:defn:DLog} satisfies the following properties.
			\begin{enumerate}[(i)]
				\item \label{item:DLog_identity}
				It holds that $\mathrm{D} \Log[A](A) = \I$.

				%		\item \label{item:Dlog_reciprocal}
				%		For any scalar $t>0$, we have $\mathrm{D}\log[tA](B) = \frac{ \mathrm{D}\log[A](B)}{t}$.

				\item \label{item:DLog_reciprocal}
				For any complex number $z\in\mathds{C}$ such that $\Log(zA)=\Log(z)\I+\Log(A)$, we have
				\[\mathrm{D}\Log[zA](B) = z^{-1}\mathrm{D}\Log[A](B).\]


				\item \label{item:Dlog_linear}
				The principal logarithm is \emph{continuously Fr\'echet differentiable} on  $A$ with $\spec(A) \in \mathds{C}\backslash \mathds{R}_{\leq0}$
				and, hence the \emph{Fr\'echet derivative}, $B \mapsto \mathrm{D}\Log[A](B)$, is a linear map.

				\item \label{item:Dlog_integral}
				(Lieb's formula) The G{\^{a}}teaux differential admits the following integral representations:
				\begin{align}
					\label{eq:log-formula1}
					\mathrm{D}\Log[A](B)
					&= \int_{0}^{\infty} \frac{1}{A+t\I} B \frac{1}{A+t\I} \,\mathrm{d}t
					\\
					\label{eq:log-formula2}    
					&= \int_{0}^{1} \frac{1}{(1-t)A+t\I} B \frac{1}{(1-t)A+t\I} \,\mathrm{d}t.
				\end{align}

				\item \label{item:DLog_positivity}
				For $A>0$, the \emph{Fr\'echet derivative}, $B \mapsto \mathrm{D}\log[A](B)$, is a (completely) positive map.
				Namely, $\mathrm{D}\log[A](B) \geq 0 $ for any $B\geq 0$.

				\item \label{item:Dlog_division}
				If $A>0$, we have
				\begin{align}
					\mathrm{D}\log[A](B)
					&=            A^{-1/2}\mathrm{D}\log\left[A^{-1}\right]\left(A^{-1/2} B A^{-1/2} \right)A^{-1/2}.
				\end{align}

				\item \label{item:Beigi-Tomamichel}
				(Beigi--Tomamichel's inequality)
				For $A+B>0$ and $B\geq 0$,
				\begin{align}
					\mathrm{D}\log[A+B](B) 
					\leq \mathrm{D} \log [A] (B).
				\end{align}

				\item \label{item:Dlog_norm}
				Suppose $A>0$ and $B\geq 0$, then 
				\[
				\|\mathrm{D}\log[A](B)\|_\infty\leq \|A^{-1/2}BA^{-1/2}\|_\infty.
				\]

			\end{enumerate}
		\end{fact}
		\begin{proof}
			Items~\ref{item:DLog_identity} and \ref{item:DLog_reciprocal} follow from definition.
			Item~\ref{item:Dlog_linear} is from \cite{Ped00}.

			Item~\ref{item:Dlog_integral}:
			The formula \eqref{eq:log-formula1} was first pointed out by Lieb \cite{Lie73}
			by using the integral formula
			$\Log(A) 
			= \int_0^{\infty} (1+t)^{-1}(A-\I)(A+t\I)^{-1}\d t
			=
			\int_0^{\infty} \left[ (1+t)^{-1}\I - (A+t\I)^{-1}\right]\d t$
			(see also \cite[(3.11)]{HP14}).
			The second formula follows from change of variable $t\leftarrow \frac{1-t}{t}$, or by the integral representation:
			$\Log (A) =    \int_0^1  (A-\I)\left[ t A + (1-t) \I\right]^{-1} \d t $
			\cite{Wou65}, 
			\cite[(3.12)]{HP14}
			\cite[\S 11]{Hig08}.
			% \cite{DMP96}

			Item~\ref{item:DLog_positivity} follows from the formula given in Item~\ref{item:Dlog_integral}.

			Item~\ref{item:Dlog_division} can be shown as follows:
			Shorthand $D := A^{-\frac12} B A^{-\frac12}$. Then, by Item~\ref{item:Dlog_integral}, we have 
			\begin{DispWithArrows}[displaystyle]
				% \begin{align*}
					{\rm D} \log[A^{-1}](D)
					&=\int_0^\infty \frac{1}{u\I+A^{-1}}\,D\,\frac{1}{u\I+A^{-1}}\,\d u
					\notag
					\\
					&=\int_0^\infty A^{\frac{1}{2}}\frac{1}{Au+\I}A^{\frac{1}{2}}D A^{\frac{1}{2}}\frac{1}{Au+\I}A^{\frac{1}{2}}\,\d u
					\notag
					\\
					&=A^{\frac{1}{2}}\int_0^\infty \frac{1}{Au+\I}\,B\,\frac{1}{Au+\I}\,\d u\,A^{\frac{1}{2}} 
					\Arrow{\textnormal{by substitution} $v=u^{-1}$}
					\notag
					\\
					&= A^{\frac{1}{2}}\int_0^\infty \frac{1}{A+v\I}\,B\,\frac{1}{A+v\I}\,\d v\,A^{\frac{1}{2}}
					\notag
					\\
					&=A^{\frac{1}{2}} \cdot{\rm D}\log[A](B)\cdot A^{\frac{1}{2}}.
					% \end{align*}
			\end{DispWithArrows}
			% where (a) is due to the substitution $v=u^{-1}$.

			Item~\ref{item:Beigi-Tomamichel} was firstly shown by Beigi and Tomamichel \cite[Lemma 3]{BT24}.
			Here, we provide an alternative proof.
			Using Theorem~\ref{theo:Dlog_formula}:
			\begin{DispWithArrows}[displaystyle]
				\mathrm{D}\log[A+B](B) 
				&= \int_0^1 \left\{ u A < (1-u) B \right\} \, \d u
				\Arrow{$v = \frac{u}{1-u}$}
				\notag
				\\
				&=\int_0^{\infty} \left\{ v A <  B \right\} \frac{1}{(1+v)^2} \, \d v
				\notag
				\\
				&\leq
				\int_0^{\infty} \left\{ v A <  B \right\} \, \d v
				\notag
				\\
				&= \mathrm{D}\log[A](B).
				\notag
			\end{DispWithArrows}

			Item~\ref{item:Dlog_norm} can be shown by using Theorem~\ref{theo:Dlog_formula}. Let $r=\|A^{-1/2}BA^{-1/2}\|$, then
			\begin{align}
				\|\mathrm{D}\log[A](B)\|_\infty=\left\|\int_{0}^{r} \{ uA < B \} \d u\right\|\leq\int_{0}^{r} \left\|\{ uA < B \}\right\| \d u=r.
			\end{align}

		\end{proof}


