		\section{Operator Layer Cake Theorem} \label{sec:layer-cake}
		% \begin{align*}
			%     &\ointctrclockwisectrclockwise \Log(uA-B) \,\d t
			%     \\
			%     &\varointctrclockwise \Log(uA-B) \,\d t
			%     \\
			%     &\ointctrclockwise \Log(uA-B) \,\d t
			% \end{align*}


		This section is devoted to establishing a layer cake representation for the operator logarithm function introduced in Section~\ref{sec:log}.

		We begin with a definition and a lemma that appear repeatedly in both proofs of the theorem.

		\begin{defn}
			Let $X$ be an operator on a finite-dimensional Hilbert space. We define the real part (Hermitian part) and the imaginary part (skew-Hermitian part) of $X$ by \[\mathrm{Re}(X):=\frac{X+X^\dagger}{2}, \quad\mathrm{Im}(X):=\frac{X-X^\dagger}{2\mathrm{i}}.\]
		\end{defn}

		\begin{lemm}

			If $\mathrm{Re}(X)>0$ (resp.~$<0$), then all the eigenvalues of $X$ have positive (resp. negative) real part; similarly, if $\mathrm{Im}(X)>0$ (resp.~$<0$), then all the eigenvalues of $X$ have positive (resp. negative) imaginary part.
		\end{lemm}

		\begin{proof}
			We only prove the case when $\mathrm{Re}(X)>0$.
			Let $\lambda$ be an eigenvalue of $X$ and let $\ket{v}$ be a corresponding non-zero eigenvector, i.e.,
			\[ X\ket{v} = \lambda \ket{v} .\]
			Then
			\[
			\mathrm{Re}(\lambda)=\frac{\lambda+\bar{\lambda}}{2}
			=\frac{\bra{v}X\ket{v}+\overline{\bra{v}X\ket{v}}}{2}=\bra{v} \mathrm{Re}(X) \ket{v}>0.
			\]
			The remaining cases follows from similar proofs.
		\end{proof}


		\begin{theo}[Operator layer cake representation] \label{theo:Dlog_formula}
			For any positive definite operator $A$ and any self-adjoint operator $B$ on a finite-dimensional Hilbert space,
			the following representation holds:
			\begin{align} \label{eq:Dlog_formula}
				\mathrm{D} \log[A](B) = \int_{0}^{\infty} \{ uA < B \} \d u\,-\,\int_{-\infty}^{0} \{ uA > B \} \d u,
			\end{align}
			where $ \mathrm{D} \log[A](B) $ is the directional derivative of the operator logarithm (see Section~\ref{sec:log}),
			and $ \{ uA < B \} \equiv \{ B - uA > 0 \} $ denotes the projection onto the positive part of $B-uA$.
		\end{theo}


		\begin{remark}
			Let $\Delta = A^{-\frac{1}{2}}BA^{-\frac{1}{2}}$.
			Notice that $\{u\in \mathbb{R} \mid B-uA \; \text{singular}\}=\{u\in \mathbb{R} \mid \Delta -u\I \; \text{singular}\}=\spec\left(\Delta\right)$ as $B-uA=A^{\frac{1}{2}}(\Delta-u\I)A^{\frac{1}{2}}$ and $A$ has full support.
			Since $\Delta$ has discrete spectrum (due to the finite-dimensional assumption), the set $\{u\in \mathbb{R} \mid B-uA \; \text{singular}\}$ has measure zero.
			Hence, one can replace $\{ uA < B \}$ or $\{ uA > B \}$ in \eqref{eq:Dlog_formula} by $\{ uA \leq B \}$ or $\{ uA \geq B \}$, respectively.
		\end{remark}

		In the following, we provide two proofs of Theorem~\ref{theo:Dlog_formula}.
		The first proof is in Section~\ref{sec:first-proof}, while the second on is in Section~\ref{sec:second-proof}.

		\subsection{The First Proof} \label{sec:first-proof}

		\begin{proof}
			In the following argument, $\I$ denotes the identity operator.
			Define $\Delta=A^{-\frac{1}{2}}BA^{-\frac{1}{2}}$ and let $r, R\in\mathbb{R}$ satisfy $r\I>\Delta>-r\I$ and $R\I>B>-R\I$.
			Additionally, let $C_{R}^+$ (resp.~$C_{R}^-$) denote the boundary of the counterclockwise
			semidisc with center $z = 0$ and radius $R$ that lies entirely in the right (resp.~left) half-plane, let $C_{R,\text{arc}}^+$ (resp.~$C_{R,\text{arc}}^-$) denote the  counterclockwise
			semicircular arc with center $z = 0$ and radius $R$ that lies entirely in the right (resp.~left) half-plane, and let $C_{R}^\circ$ denote the full circle centered at $z=0$ with radius $R$.

			Note that if $u>r$, then $\{B-uA\geq 0\}$ is the zero operator. Because $rI>\Delta$ implies $rA>B$, and thus $B-uA<B-rA<0$. 
			Then, for the first and second integration regions in \eqref{eq:Dlog_formula}, we only need to integrate over $[0,r]$ and $[-r, 0]$, respectively.

			To tackle $\{ B - uA > 0 \}$, let $C(u)$ be any simple closed (counterclockwise) contour that encloses all and only the positive spectra of $B-uA$.
			% exactly enclosing all of the non-negative spectra of $B-uA$ and not passing through them.
			%	We can diagonalize $B-uA$ and apply the residue theorem to the diagonal as usual, and gain ([2] Problem 5.9)
			We apply the residue theorem to $B-uA$ (see e.g.,~\cite[Problem 5.9, p.~40]{Kat95}) to obtain
			\begin{align}
				\left\{ B - uA > 0 \right\} = \frac{1}{2\pi \mathrm{i}}\ointctrclockwise_{C(u)} \frac{1}{z\I-(B-uA)}\, \d z.
			\end{align}


			Suppose that \( u \notin \spec(\Delta) \). Then \( B - uA \) is non-singular.  
			For \( u \in \mathds{R}_{\geq 0} \setminus \spec(\Delta) \), since \( R\I > B \geq B - uA \), one can verify that the contour \( C_R^+ \) satisfies all the requirements for \( C(u) \), where \( u \in \mathds{R}_{\geq 0} \setminus \spec(\Delta) \). Therefore, we may use \( C_R^+ \) in place of \( C(u) \) for all such values of \( u \), and write:
			\begin{align}\label{eq:residue-theorem}
				\left\{ B - uA > 0 \right\} = \frac{1}{2\pi \mathrm{i}}\ointctrclockwise_{C_R^+} \frac{1}{z\I-(B-uA)}\, \d z.
			\end{align}

			Although the above integral is well-defined in the Riemann sense, for the purposes of the following calculations, we shall interpret it in the sense of Lebesgue. Specifically, by writing
			\[
			\ointctrclockwise_{C_R^+} f(z)\, \mathrm{d}z,
			\]
			we mean the Lebesgue integral
			\[
			\int_{R}^{-R} f(\mathrm{i}x)\, \mathrm{i}\, \mathrm{d}x + \int_{-\pi/2}^{\pi/2} f\left( R e^{\mathrm{i} \theta} \right) R e^{\mathrm{i} \theta} \, \mathrm{d}\theta,
			\]
			where the contour \( C_R^+ \) is parameterized by  
			\[
			C_R^+ = \{ \mathrm{i}x \mid R \geq x \geq -R \} \cup \{ R e^{\mathrm{i} \theta} \mid -\pi/2 \leq \theta \leq \pi/2 \}.
			\]

			Moreover, not only the integral over $C_R^+$, but all contour integrals appearing below are to be interpreted in the Lebesgue sense, with the following parameterizations:
			\begin{align*}
				C_{R,\text{arc}}^+ &=  \{ R e^{\mathrm{i} \theta} \mid -\pi/2 \leq \theta \leq \pi/2 \},\\
				C_R^- &= \{ \mathrm{i}x \mid -R \leq x \leq R \} \cup \{ R e^{\mathrm{i} \theta} \mid \pi/2 \leq \theta \leq 3\pi/2 \},\\
				C_{R,\text{arc}}^- &= \{ R e^{\mathrm{i} \theta} \mid \pi/2 \leq \theta \leq 3\pi/2 \},\\
				C_R^\circ &= \{ R e^{\mathrm{i} \theta} \mid 0 \leq \theta \leq 2\pi \}.
			\end{align*}

			Return to the calculation. Since the set $\spec(\Delta)$ has measure zero, we may integrate both sides of $\eqref{eq:residue-theorem}$ over $[0,r]$ in the sense of Lebesgue to obtain:
			\begin{align}
				\int_0^r\left\{ B - uA > 0 \right\} \d u 
				&= \frac{1}{2\pi \mathrm{i}} \int_0^r\ointctrclockwise_{C_R^+} \frac{1}{z \I-(B-uA)} \d z \, \d u
				\\
				&\overset{\text{(a)}}{=} \frac{1}{2\pi \mathrm{i}} \ointctrclockwise_{C_R^+} \int_0^r \frac{1}{z \I-(B-uA)} \d u \, \d z
				\\
				&= \frac{1}{2\pi \mathrm{i}} A^{\frac{-1}{2}}\ointctrclockwise_{C_R^+}\int_0^r \frac{1}{u \I+zA^{-1}-\Delta}\, \d u\, \d z\,A^{\frac{-1}{2}} 
				\\
				&\overset{\text{(b)}}{=} \frac{1}{2\pi \mathrm{i}} A^{\frac{-1}{2}}\ointctrclockwise_{C_R^+} \Log(r\I+zA^{-1}-\Delta)-\Log(zA^{-1}-\Delta)\,\d z\,A^{\frac{-1}{2}}  
				\\\label{eq:integral_positive}
				&\overset{\text{(c)}}{=} -\frac{1}{2\pi \mathrm{i}} A^{\frac{-1}{2}}\ointctrclockwise_{C_R^+}\Log(zA^{-1}-\Delta)\,\d z\,A^{\frac{-1}{2}}.
			\end{align}
			where (a) is by the Fubini--Tonelli theorem and the absolute integrability given in Lemma~\ref{lemm:boundness_Fubini} below.
			In (b) we are able to do such an integral via the fundamental theorem of calculus
			since $zA^{-1}-\Delta$ never touches the branch cut $R_{\leq 0}$ along $z\in C_R^+$ except possibly for $z=0$.\footnote{
				Note that as long as $z\not\in \{0,R\}$, the spectrum of $z A^{-1}-\Delta$ will never be real. This is because  $\mathrm{Im}(z A^{-1}-\Delta)\gtrless 0$ implies $\mathrm{Im}(\spec(z A^{-1}-\Delta))\gtrless 0$. For $z=R$, $zA^{-1}-\Delta$ is positive.
				For $z\in C_R^+\setminus\{0\}$ as the real number $u$ moves from $0$ to $r$, the spectrum of $ u \mathds{1} + z A^{-1}-\Delta$ only shifts towards right in the complex plane, and hence never touches the branch cut.
			}
			For (c), by hypothesis $r \I > \Delta$, $\Log(r\I+zA^{-1}-\Delta)$ is holomorphic in $\mathrm{Re}(z)>-\varepsilon_+$, where $\varepsilon_+=\left\Vert(A^{\frac{1}{2}}(r\I-\Delta)A^{\frac{1}{2}})^{-1}\right\Vert^{-1}>0$.\footnote{
				The spectrum of $r\I+zA^{-1}-\Delta$ will never have negative real parts as long as $\mathrm{Re}(z)>-\left\Vert(A^{\frac{1}{2}}(r\I-\Delta)A^{\frac{1}{2}})^{-1}\right\Vert^{-1}$ by checking that $\mathrm{Re}(r\I+zA^{-1}-\Delta)> 0$.
			}
			Since $C_R^+\subseteq \{z\in \mathds{C} \mid \mathrm{Re}(z)>-\varepsilon_+\}$, by Cauchy's integral theorem,    
			\[
			\ointctrclockwise_{C_R^+}\Log(r\I+zA^{-1}-\Delta)\, \d z =0.
			\]
			We now lay some groundworks for the upcoming calculations.
			Consider the derivative of $z\Log(zA^{-1}-\Delta)$:
			\[
			\frac{\d}{\d z}(z\cdot \Log(zA^{-1}-\Delta))
			=\Log(zA^{-1}-\Delta)+z\cdot \mathrm{D}\Log[zA^{-1}-\Delta](A^{-1}).
			\]
			Note that the spectrum of $zA^{-1}-\Delta$ never touches the negative real axis along $C_{R,\text{arc}}^+$, so the derivative always exists along it.

			We integrate both sides along $C_{R,\text{arc}}^+$. For the left hand side,
			\begin{align*}
				\int_{C_{R,\text{arc}}^+}\frac{\d}{\d z}(z\cdot \Log(zA^{-1}-\Delta))\,\d z
				=\mathrm{i}R\cdot\Log(\mathrm{i}R A^{-1}-\Delta)+\mathrm{i}R\cdot\Log(-\mathrm{i}R A^{-1}-\Delta).
			\end{align*}
			For the derivative term on the right hand side,
			\begin{align}
				\int_{C_{R,\text{arc}}^+}z\cdot{\rm D}\Log[zA^{-1}-\Delta](A^{-1})\,\d z	
				&\overset{\text{(a)}}{=}\int_{C_{R,\text{arc}}^+}{\rm D}\Log[zA^{-1}-\Delta](zA^{-1})\,\d z
				\\
				&\overset{\text{(b)}}{=}\int_{C_{R,\text{arc}}^+}({\rm D}\Log[zA^{-1}-\Delta](\Delta)+\I)\,\d z
				\\
				&=\int_{C_{R,\text{arc}}^+}{\rm D}\Log[zA^{-1}-\Delta](\Delta)\,\d z+2\mathrm{i}R\I
				\\
				\label{eq:integral_positive_final}
				&\overset{\text{(c)}}{=}\int_{C_{R,\text{arc}}^+}z^{-1}\cdot{\rm D}\Log[A^{-1}-z^{-1}\Delta](\Delta)\,\d z+2\mathrm{i}R\I,
			\end{align}
			where 
			(a) and (b) follows from the linearity of the Fr\'echet derivative (Fact~\ref{item:Dlog_linear}), and (c) follows from Fact~\ref{item:DLog_reciprocal}, where one can check that $\mathrm{Re}(A^{-1}-z^{-1}\Delta)>0$ and $\Log(zA^{-1}-\Delta)=\Log(z)\I+\Log(A^{-1}-z^{-1}\Delta)$ for $z\in C_{R,\text{arc}}^+$.

			%Need to check Arg(z^{-1})+Arg(A^{-1}-z^{-1}\Delta)=Arg(zA^{-1}-\Delta)?

			%%%%%%%%%%%%%%%%%
			Hence\footnote{For $\mathrm{Im}(X)<0$, we have $\Log(X)=\Log(-X)-\pi\mathrm{i}\I$.},
			\begin{align}
				&\int_{C_{R,\text{arc}}^+}\Log(zA^{-1}-\Delta)\,\d z \notag\\
				&=\mathrm{i}R\cdot\Log(\mathrm{i}R A^{-1}-\Delta)+\mathrm{i}R\cdot\Log(-\mathrm{i}R A^{-1}-\Delta)-\int_{C_{R,\text{arc}}^+}z^{-1}\cdot{\rm D}\Log[A^{-1}-z^{-1}\Delta](\Delta)\,\d z-2\mathrm{i}R\I \notag\\
				&=\mathrm{i}R\left(\Log(\mathrm{i}R A^{-1}-\Delta)+\Log(\mathrm{i}R A^{-1}+\Delta)-\pi\mathrm{i}\I -2\I\right)-\int_{C_{R,\text{arc}}^+}z^{-1}\cdot{\rm D}\Log[A^{-1}-z^{-1}\Delta](\Delta)\,\d z.
			\end{align}

			Now, we go back to the negative part of the integral. 
			The things are similar for the negative part.
			Firstly,
			\[
			\left\{ B - uA < 0 \right\} = \frac{1}{2\pi \mathrm{i}}\ointctrclockwise_{C_R^-} \frac{1}{z\I-(B-uA)}\,\d z
			\]
			for $u\in \mathbb{R}_{\leq 0}\backslash\spec(\Delta)$.
			By following the same reasoning as above, we have
			\begin{align}
				\int_{-r}^0\{ B - uA < 0 \}\d u 
				&= \frac{1}{2\pi \mathrm{i}}\int_{-r}^0 \ointctrclockwise_{C_R^-}\frac{1}{z\I-(B-uA)}\,\d z\,\d u 
				\\
				&=\frac{1}{2\pi \mathrm{i}}\ointctrclockwise_{C_R^-}\int_{-r}^0 \frac{1}{z\I-(B-uA)}\,\ d u\,\d z 
				\\
				&=\frac{1}{2\pi \mathrm{i}} A^{\frac{-1}{2}}\ointctrclockwise_{C_R^-}\int_{-r}^0 \frac{1}{u\I+zA^{-1}-\Delta}\,\d u\,\d z\,A^{\frac{-1}{2}} 
				\\
				&=\frac{1}{2\pi \mathrm{i}} A^{\frac{-1}{2}}\ointctrclockwise_{C_R^-}\int_{-r}^0 \frac{-1}{-u\I-(zA^{-1}-\Delta)}\,\d u\,\d z\,A^{\frac{-1}{2}} 
				\\
				&\overset{\text{(a)}}{=} \frac{1}{2\pi \mathrm{i}} A^{\frac{-1}{2}}\ointctrclockwise_{C_R^-}\Log(-zA^{-1}+\Delta)-\Log(r\I-zA^{-1}+\Delta)\,\d z\,A^{\frac{-1}{2}}  
				\\
				&=\frac{1}{2\pi \mathrm{i}} A^{\frac{-1}{2}}\left(\ointctrclockwise_{C_R^-}\Log(-zA^{-1}+\Delta)\,\d z-\ointctrclockwise_{C_R^-}\Log(r\I-zA^{-1}+\Delta)\right)\,A^{\frac{-1}{2}}
				\\\label{eq:integral_negative}
				&\overset{\text{(b)}}{=}\frac{1}{2\pi \mathrm{i}} A^{\frac{-1}{2}}\ointctrclockwise_{C_R^-}\Log(-zA^{-1}+\Delta)\,\d z\,A^{\frac{-1}{2}},
			\end{align}
			where (a) is again from the fundamental theorem of calculus.
			For (b), according to hypothesis $r \I > -\Delta$, $\Log(r\I-zA^{-1}+\Delta)$ is holomorphic in $\mathrm{Re}(z)<\varepsilon_-$, where $\varepsilon_-=\left\Vert(A^{\frac{1}{2}}(r\I+\Delta)A^{\frac{1}{2}})^{-1}\right\Vert^{-1}>0$. Since $C_R^-\subseteq \{z\in \mathds{C} \mid \mathrm{Re}(z)<\varepsilon_-\}$, (b) holds by Cauchy integral theorem.

			Similar to the positive part, we consider the derivative of $z\Log(-zA^{-1}+\Delta)$:
			\begin{align*}
				\frac{\d}{\d z}(z\cdot \Log(-zA^{-1}+\Delta))
				&=\Log(-zA^{-1}+\Delta)+z\cdot{\rm D}\Log[-zA^{-1}+\Delta](-A^{-1}).
			\end{align*}
			Again, since each of the eigenvalue of $-zA^{-1}+\Delta$ never touches the negative real axis along $C_{R,\text{arc}}^-$, so the derivative always exists along it.

			Again, we integrate both sides along $C_{R,\text{arc}}^-$. For the left hand side,
			\begin{align} \label{eq:integral_negative_final}
				\int_{C_{R,\text{arc}}^-}\frac{\d}{\d z}(z\cdot \Log(-zA^{-1}+\Delta))\,\d z
				= -\mathrm{i}R\cdot\Log(\mathrm{i}R A^{-1}+\Delta)-\mathrm{i}R\cdot\Log(-\mathrm{i}R A^{-1}+\Delta).
			\end{align}

			For the derivative term on the right hand side,
			\begin{align*}
				\int_{C_{R,\text{arc}}^-}z\cdot{\rm D}\Log[-zA^{-1}+\Delta](-A^{-1})\,dz
				&=-\int_{C_{R,\text{arc}}^-}{\rm D}\Log[-zA^{-1}+\Delta](zA^{-1})\,\d z
				\\
				&=-\int_{C_{R,\text{arc}}^-}({\rm D}\Log[-zA^{-1}+\Delta](\Delta)-I)\,\d z
				\\
				&=-\int_{C_{R,\text{arc}}^-}{\rm D}\Log[-zA^{-1}+\Delta](\Delta)\,\d z -2\mathrm{i}R\I
				\\
				&\overset{\text{(a)}}{=}\int_{C_{R,\text{arc}}^-}z^{-1}\cdot{\rm D}\Log[A^{-1}-z^{-1}\Delta](\Delta)\, \d z-2\mathrm{i}R\I,
			\end{align*}
			where (a) follows again from Fact~\ref{item:DLog_reciprocal}, with $\mathrm{Re}(A^{-1}-z^{-1}\Delta)>0$ and $\Log(-zA^{-1}+\Delta)=\Log(-z)\I+\Log(A^{-1}-z^{-1}\Delta)$ for $z\in C_{R,\text{arc}}^-$.

			Hence, 
			\begin{align}
				&\int_{C_{R,\text{arc}}^-}\Log(-zA^{-1}+\Delta)\,\d z \notag \\
				&=-\mathrm{i}R\cdot\Log(\mathrm{i}R A^{-1}+\Delta)-\mathrm{i}R\cdot\Log(-\mathrm{i}R A^{-1}+\Delta)-\int_{C_{R,\text{arc}}^-}z^{-1}\cdot{\rm D}\Log[A^{-1}-z^{-1}\Delta](\Delta)\, \d z+2\mathrm{i}R\I\notag \\
				&=\mathrm{i}R\left(-\Log(\mathrm{i}R A^{-1}+\Delta)-\Log(\mathrm{i}R A^{-1}-\Delta)+\pi\mathrm{i}\I+2\I\right)-\int_{C_{R,\text{arc}}^-}z^{-1}\cdot{\rm D}\Log[A^{-1}-z^{-1}\Delta](\Delta)\, \d z.
			\end{align}


			Combining the above \eqref{eq:integral_positive}, \eqref{eq:integral_positive_final}, \eqref{eq:integral_negative}, and \eqref{eq:integral_negative_final} of both the positive and negative parts, we now obtain
			\begin{align}
				&\quad\;\int_0^\infty\{ B - uA > 0 \}\,\d u-\int_{-\infty}^0\{ B - uA < 0 \}\, \d u
				\\
				&=\int_0^r\{ B - uA > 0 \}\,\d u-\int_{-r}^0\{ B - uA < 0 \}\, \d u
				\\
				&=\frac{1}{2\pi \mathrm{i}} A^{\frac{-1}{2}}\left(-\ointctrclockwise_{C_R^+}\Log(zA^{-1}-\Delta)\,\d z-\ointctrclockwise_{C_R^-}\Log(-zA^{-1}+\Delta)\,\d z\right)\,A^{\frac{-1}{2}}
				\\
				&=\frac{-1}{2\pi \mathrm{i}} A^{\frac{-1}{2}}\left(\int_{C_{R,\text{arc}}^+}\Log(zA^{-1}-\Delta)\,\d z+\int_{C_{R,\text{arc}}^-}\Log(-zA^{-1}+\Delta)\,\d z\right.
				\\
				&\left.\quad\;+\int_R^{-R} \Log(x\mathrm{i}A^{-1}-\Delta)\,\mathrm{i}\d x+\int_{-R}^R \Log(-x\mathrm{i}A^{-1}+\Delta)\,\mathrm{i}\d x\right)\,A^{\frac{-1}{2}}
				\\
				&=\frac{-1}{2\pi \mathrm{i}} A^{\frac{-1}{2}}\left(
				-\int_{C_{R,\text{arc}}^+}z^{-1}\cdot{\rm D}\Log[A^{-1}-z^{-1}\Delta](\Delta)\,\d z
				-\int_{C_{R,\text{arc}}^-}z^{-1}\cdot{\rm D}\Log[A^{-1}-z^{-1}\Delta](\Delta)\, \d z\right.\\
				&\quad\;\left.
				+\int_R^{-R} \Log(x\mathrm{i}A^{-1}-\Delta)\,\mathrm{i}\d x 
				+\int_{-R}^R\Log(x\mathrm{i}A^{-1}-\Delta)\,\mathrm{i}\d x
				+\int_0^R (-\pi\mathrm{i}\I)\,\mathrm{i}\d x
				+\int_{-R}^0 (\pi\mathrm{i}\I)\,\mathrm{i}\d x\right)\,A^{\frac{-1}{2}}\\
				&=\frac{1}{2\pi \mathrm{i}} A^{\frac{-1}{2}}\ointctrclockwise_{C_R^\circ}z^{-1}\cdot{\rm D}\Log[A^{-1}-z^{-1}\Delta](\Delta)\,\d z\,A^{\frac{-1}{2}}\label{eq:combining1}
			\end{align}

			However,
			\begin{align*}
				&\quad\;\ointctrclockwise_{C_R^\circ}z^{-1}\cdot{\rm D} \Log\left[A^{-1}-z^{-1}\Delta\right](\Delta)\,\d z
				\\
				&=\int_{0}^{2\pi}(R \mathrm{e}^{\mathrm{i}\theta})^{-1}\cdot{\rm D} \Log\left[A^{-1}-(R \mathrm{e}^{\mathrm{i}\theta})^{-1}\Delta\right](\Delta)\cdot R \mathrm{e}^{\mathrm{i}\theta}\cdot \mathrm{i} \d\theta\\
				&=\int_{0}^{2\pi}{\rm D} \Log\left[A^{-1}-(R \mathrm{e}^{\mathrm{i}\theta})^{-1}\Delta\right](\Delta)\cdot \mathrm{i} \d\theta.
			\end{align*}

			Since $R$ is an arbitrary real number satisfying $R\I>B>-R\I$, and the integral is independent of $R$, we can take $R \rightarrow \infty$ and recall that 
			the Fr\'echet derivative $\mathrm{D}\Log[\,\cdot\,]$ is continuous (Fact~\ref{item:Dlog_linear})
			to arrive at
			\begin{align} \label{eq:combining2}
				\int_{0}^{2\pi}{\rm D} \Log[A^{-1}](\Delta)\cdot \mathrm{i} \d\theta
				=2\pi \mathrm{i}\cdot {\rm D} \Log[A^{-1}](\Delta)
				=2\pi \mathrm{i}\cdot {\rm D} \log[A^{-1}](\Delta).
				%		&\quad\;\int_{0}^{2\pi}{\rm D} \Log[A^{-1}](\Delta)\cdot \mathrm{i} \d\theta
				%		\\
				%		&=2\pi \mathrm{i}\cdot {\rm D} \Log[A^{-1}](\Delta)
				%		\\
				%		\label{eq:combining2}
				%		&=2\pi \mathrm{i}\cdot {\rm D} \log[A^{-1}](\Delta).
			\end{align}

			Combining \eqref{eq:combining1}, \eqref{eq:combining2}, and invoking 
			${\rm D} \log[A^{-1}](\Delta) = A^{\frac{1}{2}} \cdot{\rm D}\log[A](B)\cdot A^{\frac{1}{2}}$ (Fact~\ref{item:Dlog_division}), we complete the proof.
			%		
			%	by the integral representation of the Fr\'echet derivative of logarithm ([1] Example 3.22),
			%	\begin{align*}
				%		{\rm D} log[A^{-1}](\Delta)=&\int_0^\infty \frac{1}{uI+A^{-1}}\,\Delta\,\frac{1}{uI+A^{-1}}\,du\\
				%		=&\int_0^\infty A^{\frac{1}{2}}\frac{1}{Au+I}A^{\frac{1}{2}}\Delta A^{\frac{1}{2}}\frac{1}{Au+I}A^{\frac{1}{2}}\,du\\
				%		=&A^{\frac{1}{2}}\int_0^\infty \frac{1}{Au+I}\,B\,\frac{1}{Au+I}\,du\,A^{\frac{1}{2}}\\
				%		= &A^{\frac{1}{2}}\int_0^\infty \frac{1}{A+vI}\,B\,\frac{1}{A+vI}\,dv\,A^{\frac{1}{2}}\\
				%		=&A^{\frac{1}{2}} \cdot{\rm D}log[A](B)\cdot A^{\frac{1}{2}},
				%	\end{align*}
			%	where the fourth equality is due to the substitution $v=u^{-1}$.
			%	
			%	To sum up, we have proved that
			%	\begin{align*}
				%		&\int_0^\infty\{ B - uA \geq 0 \}du-\int_{-\infty}^0\{ B - uA \leq 0 \}du\\
				%		=&\frac{1}{2\pi i} A^{\frac{-1}{2}}\ointctrclockwise_{C_R^\circ}{\rm D}Log[zA^{-1}-\Delta](\Delta)\,dz\,A^{\frac{-1}{2}}\\
				%		=&A^{\frac{-1}{2}}\cdot {\rm D} Log[A^{-1}](\Delta)\cdot A^{\frac{-1}{2}}\\
				%		=&{\rm D} Log[A](B)
