		\end{proof}


		\begin{lemm} \label{lemm:boundness_Fubini}
			Following the notation used 
			in Section~\ref{sec:first-proof}, %\hyperlink{proof:first_Dlog_formula}{first proof}
			% of Theorem~\ref{theo:Dlog_formula},
			we have
			\begin{align}
				\int_0^r\ointctrclockwise_{C_R^+} \left\| \frac{1}{z \I-(B-uA)}\right\| |\d z|\,\d u < \infty.
			\end{align}
		\end{lemm}
		\begin{proof}
			We break $C_R^+$ into two parts: the straight line $C_{R,\,\text{straight}}^+ :=\{\mathrm{i}x \mid R\geq x \geq -R\}$ and the arc $C_{R,\,\text{arc}}^+ :=\{R\mathrm{e}^{\mathrm{i}\theta}\,| -\pi/2\leq\theta\leq\pi/2\}$.
			Notice that the integrand is the reciprocal of the minimum distance between $z$ and the spectrum of $B-uA$. 
			For $z\in C_{R,\,\text{arc}}^+$, suppose $\beta$ is in the spectrum of $B-uA$ and $\beta\geq 0$, then
			\[
			|z-\beta|\geq |z| - |\beta| =|z|-\beta\geq R-\Vert B\Vert>0.
			\]
			On the other hand, if $\beta< 0$, then it is clear that $|z-\beta|>R\geq R-\Vert B\Vert$. As a result, the integrand will be bounded by $(R-\Vert B\Vert)^{-1}$. Thus 
			\[
			\int_0^r\int_{C_{R,\,\text{arc}}^+} \left \Vert\frac{1}{z\I-(B-uA)}\right\Vert |\d z|\,\d u\leq r\cdot\pi R\cdot \frac{1}{R-\Vert B\Vert}< \infty.
			\]

			For the straight line part, we rewrite the integral:
			\[
			\int_0^r\int_{C_{R,\,\text{straight}}^+}  \left\Vert\frac{1}{z\I-(B-uA)}\right\Vert |\d z|\,\d u =\int_0^r\int_{-R}^R \left \Vert\frac{1}{\mathrm{i}x\I-(B-uA)}\right\Vert \d x\, \d u.
			\]
			Fix $x$ and $u$. The integrand is the reciprocal of the minimum modulus among the eigenvalues of $\mathrm{i}x \I-(B-uA)$. Let $\{\beta_j\}$ be the set of eigenvalues of $B-uA$, then $\{\mathrm{i}x-\beta_j\}$ will be the set of eigenvalues of $\mathrm{i}x\I-(B-uA)$. Thus 
			\begin{align*}
				\left\Vert\frac{1}{\mathrm{i}x\I-(B-uA)}\right\Vert
				&=\frac{1}{\min_{j}|\mathrm{i}x-\beta_j|}\\
				&=\frac{1}{\sqrt{x^2+(\min_{j}\beta_j)^2}}\\
				&=\frac{1}{\sqrt{x^2+\left\Vert(B-uA)^{-1}\right\Vert^{-2}}}
			\end{align*}
			as
			$$
			\min_{j}\beta_j=\left\Vert(B-uA)^{-1}\right\Vert^{-1}.
			$$

			However, 
			\begin{align*}
				\left\Vert(B-uA)^{-1}\right\Vert
				&=\left\Vert A^{-\frac{1}{2}}(\Delta-u\I)^{-1}A^{-\frac{1}{2}}\right\Vert
				\leq\left\Vert A^{-1}\right\Vert\left\Vert (\Delta-u\I)^{-1}\right\Vert.
			\end{align*}

			Hence
			\begin{align*}
				\left \Vert\frac{1}{\mathrm{i}x\I-(B-uA)}\right\Vert
				&=\frac{1}{\sqrt{x^2+\left\Vert(B-uA)^{-1}\right\Vert^{-2}}}\\
				&\leq\frac{1}{\sqrt{x^2+\left\Vert A^{-1}\right\Vert^{-2}\left\Vert (\Delta-u\I)^{-1}\right\Vert^{-2}}}\\
				&=\frac{1}{\sqrt{x^2+\left\Vert A^{-1}\right\Vert^{-2}\left(\min_{1\leq j\leq n}\left\vert\delta_j-u\right\vert\right)^2}}\\
				&=\max_{1\leq j\leq n}\frac{1}{\sqrt{x^2+\left\Vert A^{-1}\right\Vert^{-2}\left(\delta_j-u\right)^2}},
			\end{align*}
			where $\{\delta_j\}_{j=1}^n$ are the eigenvalues of $\Delta = A^{-\frac12} B A^{-\frac12}$.

			For the integral
			\[
			\int_0^r\int_{-R}^R \left \Vert\frac{1}{\mathrm{i}x \I-(B-uA)}\right\Vert \d x\,\d u
			\]
			to be finite, we only need each of
			\[
			\int_0^r\int_{-R}^R \frac{1}{\sqrt{x^2+\left\Vert A^{-1}\right\Vert^{-2}\left(\delta_j-u\right)^2}} \d x\,\d u
			\]
			to be finite, which can be shown by elementary calculus.
		\end{proof}


