		\subsection{The Second Proof} \label{sec:second-proof}
		% \begin{proof}[\hypertarget{proof:second_Dlog_formula}{Second Proof}]
			Define $\Delta=A^{-\frac{1}{2}}BA^{-\frac{1}{2}}$ and let $r\in\mathbb{R}$ satisfy $r\I>2\Delta>-r\I$. 
			Then
			\begin{align*}
				&\int_0^\infty\{ B - uA > 0 \}\,\d u-\int_{-\infty}^0\{ B - uA < 0 \}\,\d u
				=\int_0^r\{ B - uA > 0 \}\,\d u-\int_{-r}^0\{ B - uA < 0 \}\,\d u
			\end{align*}
			as described in the %\hyperlink{proof:first_Dlog_formula}{first proof} of 
			first proof.


			Notice that, by the definition of the principal logarithm given in \eqref{eq:defn:Log},
			\[
			\sign(x)=\frac{1}{\pi \mathrm{i}}(\Log(\mathrm{i}x)-\Log(-\mathrm{i}x)),
			\quad \forall\, x\in \mathbb{R}\backslash\{0\}.
			\]


			Hence,
			\begin{align*}
				\{x > 0\}&=\frac{1}{2}(1+\sign(x))=\frac{1}{2\pi \mathrm{i}}(\Log(\mathrm{i}x)-\Log(-\mathrm{i}x)+\pi \mathrm{i});
				\\
				\{x< 0\}&=\frac{1}{2}(1-\sign(x))=\frac{1}{2\pi \mathrm{i}}(-\Log(\mathrm{i}x)+\Log(-\mathrm{i}x)+\pi \mathrm{i}),
			\end{align*}
			for $x\in \mathbb{R}\backslash\{0\}$.

			In the following, we introduce a smooth function defined on the whole real axis to approximate the sign function as an intermediate step.
			Fix $\frac{r}{4\|A^{-1}\|}>\varepsilon>0$. We have, for $x\in\mathbb{R}$,
			\begin{align*}
				\Log(x\mathrm{i}+\varepsilon)
				&=\frac{1}{2}\log(x^2+\varepsilon^2)+\mathrm{i}\arctan\left(\frac{x}{\varepsilon}\right);
				\\
				\Log(-x\mathrm{i}+\varepsilon)
				&=\frac{1}{2}\log(x^2+\varepsilon^2)-\mathrm{i}\arctan\left(\frac{x}{\varepsilon}\right),
			\end{align*}
			and, then
			\[
			\frac{2}{\pi}\arctan\left(\frac{x}{\varepsilon}\right)=\frac{1}{\pi \mathrm{i}} \left(\Log(x\mathrm{i}+\varepsilon)-\Log(-x\mathrm{i}+\varepsilon)\right).
			\]
			Then, this approaches the sign function as $\varepsilon\rightarrow 0$.

			By this, we know that
			\[
			f_\varepsilon^+(x):=\frac{1}{2}\left[1+\frac{2}{\pi}\arctan\left(\frac{x}{\varepsilon}\right)\right]=\frac{1}{2\pi \mathrm{i}}(\Log(x\mathrm{i}+\varepsilon)-\Log(-x\mathrm{i}+\varepsilon)+\pi \mathrm{i})
			\] approaches $\{x > 0\}$, and
			\[
			f_\varepsilon^-(x):=\frac{1}{2}\left[1-\frac{2}{\pi}\arctan\left(\frac{x}{\varepsilon}\right)\right]
			=\frac{1}{2\pi \mathrm{i}}(-\Log(x\mathrm{i}+\varepsilon)+\Log(-x\mathrm{i}+\varepsilon)+\pi \mathrm{i})
			\] 
			approaches $\{x< 0\}$ as $\varepsilon\rightarrow0$.
			This allows us to calculate
			\begin{align}
				\notag
				&\int_0^r f_\varepsilon^+(B-uA) \,\d u-\int_{-r}^0 f_\varepsilon^-(B-uA)\,\d u\\
				&=\int_0^r \frac{1}{2\pi i}\left[ \Log\left((B-uA)\mathrm{i}+\varepsilon\I\right)-\Log\left(-(B-uA)\mathrm{i}+\varepsilon\I\right)+\pi \mathrm{i} \right] \d u
				\\
				\notag
				&\quad -\int_{-r}^0\frac{1}{2\pi i}\left[ -\Log((B-uA)\mathrm{i}+\varepsilon\I)+\Log(-(B-uA)\mathrm{i}+\varepsilon\I)+\pi \mathrm{i} \right] \d u
				\\
				\label{eq:second_proof_line}
				&=\frac{1}{2\pi \mathrm{i}}\left[\int_{-r}^r \Log((B-uA)\mathrm{i}+\varepsilon\I) \,\d u-\int_{-r}^r \Log(-(B-uA)\mathrm{i}+\varepsilon\I)\, \d u\right].
			\end{align}

			Observe that if $\mathrm{Im}\{z\}>-\varepsilon/(2\norm{A}{})$, then
			\begin{align} \label{eq:second_epsilon_away}
				\frac{1}{2}\left[(B-zA) \mathrm{i}+\varepsilon\I+\left((B-zA) \mathrm{i}+\varepsilon\I\right)^\dagger \right]
				=\frac{-z\mathrm{i}+\overline{z}\mathrm{i}}{2}A+\varepsilon\I=\mathrm{Im}\{z\}A+\varepsilon\I
				>\varepsilon\left(\I-\frac{A}{2\norm{A}{}}\right)>0.
			\end{align}
			This shows that $\mathrm{Re}\{(B-zA) \mathrm{i}+\varepsilon\I\}>0$.

			For the negative part, if $\mathrm{Im}\{z\}<\varepsilon/(2\norm{A}{})$, then
			\begin{align*}
				\frac{1}{2}\left[-(B-zA) \mathrm{i}+\varepsilon\I+\left(-(B-zA) \mathrm{i}+\varepsilon\I\right)^\dagger \right]=\frac{z\mathrm{i}-\overline{z}\mathrm{i}}{2}A+\varepsilon\I=-\mathrm{Im}\{z\}A+\varepsilon\I
				>\varepsilon\left(\I-\frac{A}{2\norm{A}{}}\right)>0.
			\end{align*}
			Hence $\mathrm{Re}\{-(B-zA) \mathrm{i}+\varepsilon\I\}>0$.

			As a result, $z\mapsto \Log((B-zA)\mathrm{i}+\varepsilon\I)$ is holomorphic in the open set $\{z\in \mathbb{C}\mid\mathrm{Im}\{z\}>-\varepsilon/(2\norm{A}{})\}$, and $z \mapsto \Log(-(B-zA)\mathrm{i}+\varepsilon\I)$ is holomorphic in the open set $\{z\in \mathbb{C}\mid\mathrm{Im}\{z\}<\varepsilon/(2\norm{A}{})\}$.

			Denoting the upper arc
			$C_{r,\text{arc}}^+=\{r\mathrm{e}^{\mathrm{i}\theta} \mid 0\leq \theta\leq\pi\}$ (counterclockwise) and the lower arc
			$C_{r,\text{arc}}^-=\{r\mathrm{e}^{\mathrm{i}\theta} \mid -\pi\leq \theta\leq 0\}$ (counterclockwise),
			by Cauchy's integral theorem,
			\begin{align*}
				\int_{-r}^r \Log((B-uA)\mathrm{i} +\varepsilon\I)\, \d u
				&=
				-\int_{C_{r,\text{arc}}^+} \Log((B-zA)\mathrm{i}+\varepsilon\I) \,\d z,
				\\
				-\int_{-r}^r \Log(-(B-uA)\mathrm{i}+\varepsilon\I) \,\d u
				&=
				-\int_{C_{r,\text{arc}}^-} \Log(-(B-zA)\mathrm{i}+\varepsilon\I) \, \d z,
			\end{align*}
			as the closed paths $[-r,r]\cup C_{r,\text{arc}}^+$ and $[-r,r]\cup C_{r,\text{arc}}^-$ are in the open sets $\{z\in \mathbb{C}\mid\mathrm{Im}\{z\}>-\varepsilon/(2\norm{A}{})\}$ and $\{z\in \mathbb{C}\mid\mathrm{Im}\{z\}<\varepsilon/(2\norm{A}{})\}$, respectively.

			We have, by \eqref{eq:second_proof_line},
			\begin{align} 
				\begin{split}\label{eq:second_proof_epsilon}
					&\int_0^r f_\varepsilon^+(B - uA)\,\d u-\int_{-r}^0 f_\varepsilon^-( B - uA)\, \d u.
					\\
					&=\frac{-1}{2\pi \mathrm{i}}\left[\int_{C_{r,\text{arc}}^+} \Log((B-zA)\mathrm{i}+\varepsilon \I )\,\d z+\int_{C_{r,\text{arc}}^-} \Log(-(B-zA)\mathrm{i}+\varepsilon \I )\,\d z\right].
				\end{split}
			\end{align}

			Now, we intend to let $\varepsilon\to 0$. 
			First, for the left-hand side of \eqref{eq:second_proof_epsilon}, 
			the convergences (in weak operator topology)
			% we claim that
			\begin{align*}
				\int_0^r f_\varepsilon^+(B - uA)\,\d u \to 
				&\int_0^r \{B - uA> 0\}\,\d u
				\\
				\int_{-r}^0 f_\varepsilon^-( B - uA)\, \d u \to 
				&\int_{-r}^0 \{B - uA< 0\}\,\d u
			\end{align*}
			as $\varepsilon\to 0$ are evident by the bounded convergence theorem, because
			% , where in finite-dimensional space, we only need the convergence to be weak, in the sense that $\forall$ vector $\ket{v}$,
			% \begin{align}
				%      \bra{v}\,\int_0^r f_\varepsilon^+(B - uA)\,\d u\,\ket{v} \to 
				%      &\bra{v}\,\int_0^r \{B - uA> 0\}\,\d u\,\ket{v}\\
				%      \bra{v}\,\int_{-r}^0 f_\varepsilon^-( B - uA)\, \d u \,\ket{v}\to 
				%      &\bra{v}
				%      \,\int_{-r}^0 \{B - uA< 0\}\,\d u\,\ket{v},
				% \end{align}or
			% \begin{align}
				% \begin{split}\label{eq:varepsilon_to_0}
					%      \int_0^r \bra{v}f_\varepsilon^+(B - uA)\ket{v}\,\d u \to 
					%      &\int_0^r \bra{v}\{B - uA> 0\}\ket{v}\,\d u\\
					%      \int_{-r}^0\bra{v} f_\varepsilon^-( B - uA)\ket{v}\, \d u \to 
					%      &\int_{-r}^0\bra{v} \{B - uA< 0\}\ket{v}\,\d u.
					%      \end{split}
				% \end{align}
			% as $\varepsilon\to 0$.
			for any unit vector $|\psi\rangle$ in the Hilbert space, both $\bra{\psi}f_\varepsilon^+(B - uA)\ket{\psi}$ and $\bra{\psi}f_\varepsilon^-(B - uA)\ket{\psi}$ are merely a real-valued function whose absolute value is bounded by the constant function $1$, which is integrable on both $(0, r]$ and $[-r,0)$.
			% By applying the Lebesgue dominated convergence theorem, the convergence in \eqref{eq:varepsilon_to_0} is established.

			% Note that since we are in a finite-dimensional space, this indeed implies $f_\varepsilon^+(B - uA)\to \{B-uA>0\}$ and $f_\varepsilon^-(B - uA)\to \{B-uA<0\}$ in the operator norm.


			Second, the convergences on the right-hand side of \eqref{eq:second_proof_epsilon} are deferred to Lemma~\ref{lemm:uniform_convergence} later.
			In conclusion, we obtain
			\begin{align}
				\begin{split} \label{eq:second-no-epsilon}
					&\int_0^r\{ B - uA > 0 \}\,\d u-\int_{-r}^0\{ B - uA < 0 \}\,\d u\\
					&=\frac{-1}{2\pi \mathrm{i}}\left[\int_{C_{r,\text{arc}}^+} \Log((B-zA)\mathrm{i})\,\d z+\int_{C_{r,\text{arc}}^-} \Log(-(B-zA)\mathrm{i}) \,\d z\right].
				\end{split}
			\end{align}


			By applying integration by parts,
			\begin{align}
				\notag
				&-\int_{C_{r,\text{arc}}^+} \Log((B-zA)\mathrm{i})\,\d z
				\\
				\notag
				&=-z\cdot\Log((B-zA)\mathrm{i})\Big\vert_{z=r}^{z=-r}+\int_{C_{r,\text{arc}}^+}z\cdot {\rm D}\Log[(B-zA)\mathrm{i}](-A\mathrm{i})\,\d z
				\\
				\label{eq:second-no-epsilon-1}
				&=r\cdot \Log((B+rA)\mathrm{i})+r\cdot \Log((B-rA)\mathrm{i})
				+\int_{C_{r,\text{arc}}^+}z\cdot {\rm D}\Log[(B-zA)\mathrm{i}](-A\mathrm{i})\,\d z,
			\end{align}
			and for the other part:
			\begin{align}
				\notag
				&-\int_{C_{r,\text{arc}}^-} \Log(-(B-zA)\mathrm{i})\,\d z
				\\
				\notag
				&=-z\cdot\Log(-(B-zA)\mathrm{i})\Big\vert_{z=-r}^{z=r}+\int_{C_{r,\text{arc}}^-}z\cdot {\rm D}\Log[-(B-zA)\mathrm{i}](A\mathrm{i})\,\d z
				\\
				\label{eq:second-no-epsilon-2}
				&= -r\cdot \Log(-(B+rA)\mathrm{i})-r\cdot\Log(-(B-rA)\mathrm{i})
				+\int_{C_{r,\text{arc}}^-}z\cdot {\rm D}\Log[-(B-zA)\mathrm{i}](A\mathrm{i})\,\d z.
			\end{align}

			Combining the above results \eqref{eq:second-no-epsilon}, \eqref{eq:second-no-epsilon-1}, and \eqref{eq:second-no-epsilon-2}, we get:
			\begin{align*}
				&\int_0^r \{B-uA\geq 0\} \, \d u-\int_{-r}^0 \{B-uA\leq 0\} \, \d u
				\\
				&=\frac{1}{2\pi \mathrm{i}} \left[ r\cdot \Log((B+rA)\mathrm{i})+r\cdot \Log((B-rA)\mathrm{i})
				+\int_{C_{r,\text{arc}}^+}z\cdot {\rm D}\Log[(B-zA)\mathrm{i}](-A\mathrm{i})\,\d z \right.
				\\
				&\quad\quad\quad\quad \left.- r\cdot \Log(-(B+rA)\mathrm{i})-r\cdot\Log(-(B-rA)\mathrm{i})
				+\int_{C_{r,\text{arc}}^-}z\cdot {\rm D}\Log[-(B-zA)\mathrm{i}](A\mathrm{i})\,\d z \right].
			\end{align*}
			Since $B+rA>0$ and $B-rA<0$ by design, we can simplify
			\begin{align*}
				&r\cdot \Log((B+rA)\mathrm{i})+r\cdot \Log((B-rA)\mathrm{i})
				-r\cdot \Log(-(B+rA)\mathrm{i})-r\cdot\Log(-(B-rA)\mathrm{i})
				\\
				&=r\cdot\left[\log(B+rA)+\frac{\pi}{2}\mathrm{i}\I+\log(-(B-rA))-\frac{\pi}{2}\mathrm{i}\I\right]-r\cdot \left[\log(B+rA)-\frac{\pi}{2}\mathrm{i}\I+\log(-(B-rA))+\frac{\pi}{2}\mathrm{i}\I\right]
				\\
				&=0.
			\end{align*}
			For the integral term, we recall Fact~\ref{item:DLog_identity}, \ref{item:DLog_reciprocal}, and \ref{item:Dlog_linear} to obtain
			\begin{DispWithArrows}[displaystyle]
				&\int_{C_{r,\text{arc}}^+}z\cdot {\rm D}\Log[(B-zA)\mathrm{i}](-A\mathrm{i})\,\d z
				+\int_{C_{r,\text{arc}}^-}z\cdot {\rm D}\Log[-(B-zA)\mathrm{i}](A\mathrm{i})\,\d z
				\Arrow{by linearity\\(Fact~\ref{item:Dlog_linear})}
				\notag
				\\
				&=\int_{C_{r,\text{arc}}^+} {\rm D}\Log[(B-zA)\mathrm{i}](-zA\mathrm{i})\,\d z
				+\int_{C_{r,\text{arc}}^-} {\rm D}\Log[-(B-zA)\mathrm{i}](zA\mathrm{i})\,\d z
				\Arrow{Fact~\ref{item:Dlog_linear} \& \ref{item:DLog_identity}}
				\notag
				\\
				&=\int_{C_{r,\text{arc}}^+} \!\!\!\left\{ {\rm D}\Log[(B-zA)\mathrm{i}](-B\mathrm{i})+\I \right\} \d z
				+\int_{C_{r,\text{arc}}^-} \!\!\!\!\! \left\{ {\rm D}\Log[-(B-zA)\mathrm{i}](B\mathrm{i})+\I\right\}\d z
				\notag
				\\
				&=\int_{C_{r,\text{arc}}^+} {\rm D}\Log[(B-zA)\mathrm{i}](-B\mathrm{i})\,\d z + 2r \!\I
				+\int_{C_{r,\text{arc}}^-} {\rm D}\Log[-(B-zA)\mathrm{i}](B\mathrm{i})\,\d z - 2r \!\I
				\Arrow{Fact~\ref{item:DLog_reciprocal}}
				\notag
				\\
				&=\int_{C_{r,\text{arc}}^+} \frac{1}{-z\mathrm{i}}{\rm D}\Log[A-z^{-1}B](-B\mathrm{i})\,\d z
				+\int_{C_{r,\text{arc}}^-} \frac{1}{z\mathrm{i}}{\rm D}\Log[A-z^{-1}B](B\mathrm{i})\,\d z
				\notag
				\\
				&=\int_{C_{r,\text{arc}}^+} z^{-1}{\rm D}\Log[A-z^{-1}B](B)\,\d z
				+\int_{C_{r,\text{arc}}^-} z^{-1}{\rm D}\Log[A-z^{-1}B](B)\,\d z
				\notag
				\\
				&=\int_{C_{r,\text{arc}}^\circ} z^{-1}{\rm D}\Log[A-z^{-1}B](B)\,\d z
				\notag
				\\
				&=\int_0^{2\pi} {(r\mathrm{e}^{\mathrm{i}\theta})}^{-1} {\rm D}\Log\left[A- {(r\mathrm{e}^{\mathrm{i}\theta})}^{-1} B\right](B)\cdot r\mathrm{e}^{\mathrm{i}\theta}\, \mathrm{i} \, \d\theta
				\notag
				\\
				&=\int_0^{2\pi} {\rm D}\Log\left[A-{(r\mathrm{e}^{\mathrm{i}\theta})}^{-1} B\right](B) \cdot \mathrm{i}\, \d\theta
				\notag
				\\
				&=\int_0^{2\pi} {\rm D}\Log\left[A^\frac{1}{2}\left(\I-{(r\mathrm{e}^{\mathrm{i}\theta})}^{-1}\Delta\right)A^\frac{1}{2}\right](B) \cdot \mathrm{i}\,\d\theta.
				\notag
			\end{DispWithArrows}

			Since $r$ is an arbitrary real number satisfying $r\I>2\Delta>-r\I$, and the integral is independent of $r$, we can take $r \rightarrow \infty$ and recall that the Fr\'echet derivative $\mathrm{D}\Log[\,\cdot\,]$ is continuous (Fact~\ref{item:Dlog_linear})
			to arrive at
			\begin{align*}
				\int_0^\infty \{B-uA> 0\} \, \d u-\int_{-\infty}^0 \{B-uA< 0\} \, \d u
				&=\frac{1}{2\pi \mathrm{i}}\int_0^{2\pi} {\rm D}\Log[A](B) \cdot\mathrm{i}\,\d\theta
				={\rm D}\Log[A](B)
				={\rm D}\log[A](B)
			\end{align*}    
			as desired.
			% \end{proof}
		\qed 
		\\

		\begin{lemm} \label{lemm:uniform_convergence}
			Following the notation used 
			in Section~\ref{sec:second-proof},
			% in the \hyperlink{proof:second_Dlog_formula}{second proof}
			% of Theorem~\ref{theo:Dlog_formula},
			we have, as $\varepsilon \to 0$,
			\begin{align*}
				\int_{C_{r,\textnormal{arc}}^+} \Log((B-zA)\mathrm{i}+\varepsilon \I )\,\d z&\to \int_{C_{r,\textnormal{arc}}^+} \Log((B-zA)\mathrm{i})\,\d z; \\
				\int_{C_{r,\textnormal{arc}}^-} \Log(-(B-zA)\mathrm{i}+\varepsilon \I )\,\d z&\to \int_{C_{r,\textnormal{arc}}^-} \Log(-(B-zA)\mathrm{i})\,\d z.
			\end{align*}
		\end{lemm}

		\begin{proof}
			It suffices to show that
			\begin{align*}
				\int_{C_{r,\text{arc}}^+} \big\Vert\Log((B-zA)\mathrm{i}+\varepsilon \I )-\Log((B-zA)\mathrm{i})\big\Vert\,|\d z|
				&\to0;
				\\
				\int_{C_{r,\text{arc}}^-} \big\Vert\Log(-(B-zA)\mathrm{i}+\varepsilon \I )-\Log(-(B-zA)\mathrm{i})\big\Vert\,|\d z|
				&\to0.
			\end{align*}

			By the above argument shown in \eqref{eq:second_epsilon_away}, 
			we have $\mathrm{Re}\{(B-zA)\mathrm{i}\}> 0$ for $\mathrm{Im}\{z\}>0$. 
			Also, for $z=\pm r$, $B-zA\lessgtr0$, thus $(B-zA)\mathrm{i}$ has no eigenvalues on the real axis.
			As a result, $(B-zA)\mathrm{i}$ will never have any eigenvalue on the negative real axis as long as $z\in C_{r,\text{arc}}^+$.
			Hence, we can write
			\begin{align*}
				\Log((B-zA)\mathrm{i}+\varepsilon \I )-\Log((B-zA)\mathrm{i})=\int_0^\varepsilon \frac{1}{(B-zA)\mathrm{i}+\beta \I}\,\d \beta,
				\quad \forall\, z\in C_{r,\text{arc}}^+.
			\end{align*}
			We intend to bound
			\begin{align}
				\label{eq:uniform_convergence_1}
				\left\Vert\frac{1}{(B-zA)\mathrm{i}+\beta \I}\right\Vert
				\leq\left\Vert A^{-1}\right\Vert \left\Vert\frac{1}{z\I+\beta\mathrm{i}A^{-1}-D}\right\Vert
				=\left\Vert A^{-1}\right\Vert\cdot \frac{1}{r}
				\left\Vert\frac{1}{ \I+z^{-1}\left(\beta\mathrm{i}A^{-1}-D\right)}\right\Vert.
			\end{align}
			Since
			\begin{align*}
				\left\Vert z^{-1}\left(\beta\mathrm{i}A^{-1}-D\right)\right\Vert
				\leq\frac{1}{r}\left(\left\Vert \beta A^{-1}\right\Vert+\left\Vert D\right\Vert \right)
				\leq \frac{1}{r}\left(\varepsilon\left\Vert A^{-1}\right\Vert+\left\Vert D\right\Vert\right)
				<\frac{1}{r}\left(\frac{r}{4}+\frac{r}{2}\right)=\frac{3}{4}<1,
			\end{align*}
			we have
			\begin{align}
				\label{eq:uniform_convergence_2}
				\left\Vert\frac{1}{ \I+z^{-1}\left(\beta\mathrm{i}A^{-1}-D\right)}\right\Vert
				\leq \frac{1}{1-\left\Vert z^{-1}\left(\beta\mathrm{i}A^{-1}-D\right)\right\Vert}\leq 4.
			\end{align}

			By combining \eqref{eq:uniform_convergence_1} and \eqref{eq:uniform_convergence_2}, we gain
			\begin{align*}
				&\int_{C_{r,\text{arc}}^+} \big\Vert\Log((B-zA)\mathrm{i}+\varepsilon \I )-\Log((B-zA)\mathrm{i})\big\Vert\,|\d z|\\
				&=
				\int_{C_{r,\text{arc}}^+}\left\Vert\int_0^\varepsilon \frac{1}{(B-zA)\mathrm{i}+\beta \I}\,\d \beta\right\Vert\,|\d z|\\
				&\leq \int_{C_{r,\text{arc}}^+}\int_0^\varepsilon\left\Vert \frac{1}{(B-zA)\mathrm{i}+\beta \I}\right\Vert\,\d \beta\,|\d z|\\
				&\leq 
				\int_{C_{r,\text{arc}}^+}\int_0^\varepsilon\left\Vert A^{-1}\right\Vert\cdot \frac{1}{r}
				\left\Vert\frac{1}{ \I+z^{-1}\left(\beta\mathrm{i}A^{-1}-D\right)}\right\Vert\,\d \beta\,|\d z|\\
				&\leq 
				\int_{C_{r,\text{arc}}^+}\int_0^\varepsilon\left\Vert A^{-1}\right\Vert
				\cdot\frac{4}{r}\,\d \beta\,|\d z|\\
				&=4\pi \varepsilon\left\Vert A^{-1}\right\Vert\to 0
			\end{align*} as $\varepsilon\to 0$.

			For the negative part, $-(B-zA)\mathrm{i}$ will never have any eigenvalue on the negative real axis  as long as $z\in C_{r,\text{arc}}^-$, so we can make the same argument:
			\begin{align*}
				&\int_{C_{r,\text{arc}}^-} \big\Vert\Log(-(B-zA)\mathrm{i}+\varepsilon \I )-\Log(-(B-zA)\mathrm{i})\big\Vert\,|\d z|\\
				&=
				\int_{C_{r,\text{arc}}^-}\left\Vert\int_0^\varepsilon \frac{1}{-(B-zA)\mathrm{i}+\beta \I}\,\d \beta\right\Vert\,|\d z|\\
				&\leq \int_{C_{r,\text{arc}}^-}\int_0^\varepsilon\left\Vert \frac{1}{-(B-zA)\mathrm{i}+\beta \I}\right\Vert\,\d \beta\,|\d z|\\
				&\leq 
				\int_{C_{r,\text{arc}}^-}\int_0^\varepsilon\left\Vert A^{-1}\right\Vert\cdot \frac{1}{r}
				\left\Vert\frac{1}{\I-z^{-1}(\beta\mathrm{i}A^{-1}+D)}\right\Vert\,\d \beta\,|\d z|\\
				&\leq 
				\int_{C_{r,\text{arc}}^-}\int_0^\varepsilon\left\Vert A^{-1}\right\Vert
				\cdot\frac{4}{r}\,\d \beta\,|\d z|\\
				&=4\pi \varepsilon\left\Vert A^{-1}\right\Vert\to 0
			\end{align*} 
			as $\varepsilon\to 0$.
			This completes the proof.
		\end{proof}

