		\section{Operator Change of Variables} \label{sec:change-of-variable}



		\begin{theo} \label{theo:change-of-variable}
			Let $A$ be a positive definite operator and $B$ a positive semi-definite operator on a finite-dimensional Hilbert space. Define $r := \| A^{-1/2}B A^{-1/2} \|_{\infty}$.
			Then, for any Lebesgue-integrable function $h$ on $[0,r]$,
			\begin{align} \label{eq:change-of-variable}
				\int_0^r \{ B > \gamma A \} h(\gamma) \, \d \gamma
				&= \int_0^\infty \frac{1}{A+t\I}  B \frac{1}{\sqrt{A+t\I}} h\left( \frac{1}{\sqrt{A+t\I}} B \frac{1}{\sqrt{A+t\I}} \right) \frac{1}{\sqrt{A+t\I}} \d t.
			\end{align}
		\end{theo}

		\begin{remark}
			When $A$ and $B$ commute, \eqref{eq:change-of-variable} reduces to the usual change of variables in calculus.
			Hence, Theorem~\ref{theo:change-of-variable} can be viewed as a kind of change of variables argument for operators.
			To see this, let $a = \langle i|A |i\rangle$ and $b = \langle i|B|i\rangle$ for any common eigenbasis $\{|i\rangle\}_i$.
			Then, the $i$-th diagonal entry on the left-hand side is $\int_0^{b/a} h(\gamma) \, \d \gamma$.
			By setting $\gamma = \frac{b}{a + t} \in [0, b/a]$ and $\d \gamma = -\frac{b}{(a+t)^2} \d t$, the $i$-th diagonal entry on the right-hand side is equal to that of the left-hand side.
		\end{remark}


		\begin{proof}
			In the context of this proof and the following lemma, we redefine the notation $\frac{B}{A + t\I}$ to stand for the symmetric quotient $(A + t\I)^{-\nicefrac{1}{2}} B (A + t\I)^{-\nicefrac{1}{2}}$ for notational convenience, overriding its previous meaning. Then the formula we desired can be compactly written as \[
			\int_0^r \{ B > \gamma A \} h(\gamma) \, \d \gamma
			= \int_0^\infty  \frac{1}{\sqrt{A+t\I}}\frac{B}{A + t\I} h\left( \frac{B}{A + t\I} \right) \frac{1}{\sqrt{A+t\I}} \d t.
			\]

			We first establish \eqref{eq:change-of-variable} for all polynomial functions.
			We then extend the result to continuous and Lebesgue-integrable functions by applying the Weierstrass approximation theorem and the Lebesgue convergence theorems.


			Apply the operator layer cake theorem (Theorem~\ref{theo:Dlog_formula}), we have for all $\beta \geq 0$,
			\begin{DispWithArrows}[displaystyle]
				\mathrm{D} \log[ A + \beta B ] (B)
				&= \int_0^\infty \{B > (A + \beta B) u\} \d u
				\notag
				\\
				&= \int_0^\infty \{(1-u\beta) B > u A\} \d u
				\notag
				\\
				&= \int_0^{\frac{1}{\beta}} \{(1-u\beta) B > u A\} \d u
				\notag
				\\
				&= \int_0^{\frac{1}{\beta}} \{ B > \frac{u}{1-u\beta} A\} \d u
				\Arrow{\textnormal{ by substitution} $\gamma = \frac{u}{1-u\beta}$ 
					\\  \textnormal{ and} $\d u = \frac{1}{(1+\beta \gamma)^2} \d \gamma$
				}
				\notag
				\\
				&= \int_0^{\infty} \{ B > \gamma A\}  \frac{1}{(1+\beta \gamma)^2}\d \gamma
				\notag
				\\
				&= \int_0^{r} \{ B > \gamma A\} \frac{1}{(1+\beta \gamma)^2} \d \gamma.
				\label{eq:change-of-variable1}
			\end{DispWithArrows}


			On the other hand, by Lieb's integral formula (Fact~\ref{item:Dlog_integral}),
			\begin{align}
				\mathrm{D} \log [ A + \beta B](B)
				&= \int_0^\infty \frac{1}{A + \beta B + t \I } B \frac{1}{A + \beta B + t \I } \d t
				\notag
				\\
				&= \int_0^\infty \frac{1}{\sqrt{A + t\I}}  \frac{1}{ \I + \beta \frac{B}{A +t\I}  } \frac{B}{A + t\I}  \frac{1}{ \I + \beta  \frac{B}{A +t\I}} \frac{1}{\sqrt{A + t\I}} \d t
				\notag
				\\
				&=
				\int_0^\infty \frac{1}{\sqrt{A + t\I}} \frac{B}{A+t\I} \frac{1}{ \left(1 + \beta \frac{B}{A+t\I}\right)^2 } \frac{1}{\sqrt{A + t\I}}\d t
				\label{eq:change-of-variable2}
			\end{align}

			%where (a) follows from the inverse formula $(XYX)^{-1} =X^{-1} Y^{-1} X^{-1}$ with $X \leftarrow  \sqrt{A+t\I}$ and $Y \leftarrow \I + \beta \frac{B}{A +t\I}$,
			%and (b) is because $\frac{1}{\I + \beta \frac{B}{A+t\I} }$ and $\frac{B}{A+t\I}$ commute.

			Hence, from \eqref{eq:change-of-variable1} and \eqref{eq:change-of-variable2}, we have for all $\beta \geq 0$,
			\begin{align}
				\int_0^r \{ B > \gamma A \} \frac{1}{(1+\beta \gamma)^2} \d \gamma
				&= \int_0^\infty \frac{1}{\sqrt{A + t\I}} \frac{B}{A+t\I} \frac{1}{ \left(1 + \beta \frac{B}{A+t\I}\right)^2 } \frac{1}{\sqrt{A + t\I}} \d t
				\label{change-of-variable:m=2}
				\\
				\left(-\frac{1}{2} \frac{\d}{\d \beta} \right) \eqref{change-of-variable:m=2} : \int_0^r \{ B > \gamma A \} \frac{\gamma}{(1+\beta \gamma)^3} \d \gamma
				&= \int_0^\infty \frac{1}{\sqrt{A + t\I}} \frac{B}{A+t\I} \frac{\frac{B}{A+t\I}}{ \left(1 + \beta \frac{B}{A+t\I}\right)^3 } \frac{1}{\sqrt{A + t\I}} \d t
				\label{change-of-variable:m=3}
				\\
				\left(-\frac{1}{3} \frac{\d}{\d \beta} \right) \eqref{change-of-variable:m=3} : \int_0^r \{ B > \gamma A \} \frac{\gamma^2}{(1+\beta \gamma)^4} \d \gamma
				&= \int_0^\infty \frac{1}{\sqrt{A + t\I}} \frac{B}{A+t\I} \frac{\left(\frac{B}{A+t\I}\right)^2}{ \left(1 + \beta \frac{B}{A+t\I}\right)^4 } \frac{1}{\sqrt{A + t\I}} \d t
				\label{change-of-variable:m=4}
				\\
				&\vdots
				\notag
				\\
				\int_0^r \{ B > \gamma A \} \frac{\gamma^m}{(1+\beta \gamma)^{m+2} } \d \gamma
				&= \int_0^\infty \frac{1}{\sqrt{A + t\I}} \frac{B}{A+t\I} \frac{\left(\frac{B}{A+t\I}\right)^m}{ \left(1 + \beta \frac{B}{A+t\I}\right)^{m+2} } \frac{1}{\sqrt{A + t\I}} \d t, 
				\notag
			\end{align}
			for all $m\in\mathds{Z}_{\geq 0}$.\footnote{
				Here, we require the interchangeability of the integrals with differentiation on both sides, as well as with the limit $\beta \searrow 0$. The left-hand side of the first one is justified by the fact that $\bra{\psi}\{ B > \gamma A \}\ket{\psi} \frac{\gamma^m}{(1+\beta \gamma)^{m+2}}$ is a finite sum of functions continuous in both $\beta$ and $\gamma$ for any $\ket{\psi}$. The right-hand side follows from the uniform convergence of
				\[
				\int_0^n \bra{\psi} \frac{1}{\sqrt{A + t\I}} \frac{B}{A + t\I} \frac{\left( \frac{B}{A + t\I} \right)^m}{\left( 1 + \beta \frac{B}{A + t\I} \right)^{m+2}} \frac{1}{\sqrt{A + t\I}} \ket{\psi} \, dt
				\]
				in $\beta$ as $n \to \infty$, for any vector $\ket{\psi}$, together with \cite[Theorem 3.7.1]{tao_analysis_II}. %\textit{Analysis II}, Theorem 3.7.1 in Terence Tao (4th ed.). 
				The second follows from the monotone convergence theorem.
			}

			Let $\beta = 0$, then we have
			\begin{align}
				\int_0^r \{ B > \gamma A \} \gamma^m \d \gamma
				% &= \int_0^\infty \!\! \frac{1}{A + t \I} B \frac{1}{A+t\I} \left(B \frac{1}{A+t\I}\right)^m  \d t \\
				&= \int_0^\infty \!\! \frac{1}{\sqrt{A + t \I}} \frac{B}{A+t\I} \left(\frac{B}{A+t\I}\right)^m \frac{1}{\sqrt{A + t \I}} \d t, \quad m \in \mathds{Z}_{\geq 0}.
				\notag
			\end{align}
			Hence, for all polynomial $f\in \mathcal{A}=\text{span}_{\mathds{R}}\{1,\gamma,\gamma^2,\dots\}$,
			\begin{align}
				\int_0^r \{ B > \gamma A \} f(\gamma) \, \d \gamma
				&= \int_0^\infty \frac{1}{\sqrt{A+t\I}} \frac{B}{A+t\I} f\left( \frac{B}{A+t\I} \right)\frac{1}{\sqrt{A+t\I}} \d t.
			\end{align}

			By the Weierstrass approximation theorem,
			\begin{align}
				\forall g\in \mathcal{C}[0,r], \forall \epsilon >0,
				\exists\, f \in \mathcal{B} \text{ such that }
				\left|f(x)-g(x)\right| < \epsilon \, \quad \forall x \in [0,r].
			\end{align}
			We then estimate the following  approximations:
			\begin{align}
				\left\| \int_0^r \{ B > \gamma A\} \left[g(\gamma)- f(\gamma)\right] \, \d \gamma \right\|_{\infty}
				&\leq  \int_0^r \left\| \{ B > \gamma A\} \right\|_{\infty} \left|g(\gamma)- f(\gamma)\right| \, \d \gamma 
				\notag
				\\
				&< \int_0^r 1 \cdot \epsilon \, \d \gamma
				\notag 
				\\
				&= r \epsilon,
				\label{eq:change-of-variable3}
			\end{align}
			and since $-\epsilon\gamma\leq \gamma [g(\gamma)-f(\gamma)]\leq\epsilon\gamma$ for $\gamma\in[0,r]$,
			\begin{align}
				&\quad\, \left\|\int_0^\infty \frac{1}{\sqrt{A+t\I}} \frac{B}{A+t\I} \left[ g\left(\frac{B}{A+t\I} \right) - f\left( \frac{B}{A+t\I} \right) \right]\frac{1}{\sqrt{A+t\I}} \d t \right\|_{\infty} 
				\notag
				\\
				&\leq \left\|\int_0^\infty \frac{1}{\sqrt{A+t\I}}\cdot \epsilon\frac{B}{A+t\I}\cdot \frac{1}{\sqrt{A+t\I}}  \d t \right\|_{\infty}
				\notag
				\\
				&= \epsilon \left\|\int_0^\infty \frac{1}{A+t\I}B\frac{1}{A+t\I}  \d t \right\|_{\infty}
				\notag
				\\
				&= \epsilon \left\|{\rm D} \log[A](B) \right\|_{\infty}
				\notag
				\\
				&\leq r\epsilon ,
				\label{eq:change-of-variable4}
			\end{align}
			under the observation that $\spec\left(\frac{1}{\sqrt{A + t\I}}B\frac{1}{\sqrt{A + t\I}}\right)
			\subseteq [0, r]$.


			Putting \eqref{eq:change-of-variable3} and \eqref{eq:change-of-variable4} together,
			\begin{align}
				&\quad\,\left\| \int_0^r \{ B > \gamma A\} g(\gamma) \, \d \gamma - \int_0^\infty \frac{1}{\sqrt{A+t\I}} \frac{B}{A+t\I} g\left(\frac{B}{A+t\I} \right)\frac{1}{\sqrt{A+t\I}} \d t \right\|_{\infty}
				\notag
				\\
				&= \left\| \int_0^r \{ B > \gamma A\} \left[(g(\gamma)- f(\gamma)\right] \, \d \gamma - \int_0^\infty \frac{1}{\sqrt{A+t\I}} \frac{B}{A+t\I} \left[ g\left(\frac{B}{A+t\I} \right) - f\left( \frac{B}{A+t\I} \right) \right]\frac{1}{\sqrt{A+t\I}} \d t \right\|_{\infty}
				\notag
				\\
				&\leq \left\| \int_0^r \{ B > \gamma A\} \left[(g(\gamma)- f(\gamma)\right] \, \d \gamma \right\|_{\infty}
				+ \left\|\int_0^\infty \frac{1}{\sqrt{A+t\I}} \frac{B}{A+t\I} \left[ g\left(\frac{B}{A+t\I} \right) - f\left( \frac{B}{A+t\I} \right) \right]\frac{1}{\sqrt{A+t\I}} \d t \right\|_{\infty}
				\notag
				\\
				&\leq 2r\epsilon.
			\end{align}

			Since $\epsilon>0$ is arbitrary, we obtain, for all $g \in \mathcal{C}[0,r]$,
			\begin{align}
				\int_0^r \{ B > \gamma A \} g(\gamma) \, \d \gamma
				&= \int_0^\infty \frac{1}{\sqrt{A+t\I}} \frac{B}{A+t\I} g\left(\frac{B}{A+t\I} \right)\frac{1}{\sqrt{A+t\I}} \d t.
			\end{align}

			Next, we extend the result to bounded nonnegative measurable functions.

			Let $h$ be a nonnegative measurable function on $[0,r]$ bounded by a positive constant $L$.
			We fix an arbitrary unit vector $\ket{\psi}$, then it suffices to prove that
			\[
			\int_0^r \bra{\psi}\{ B > \gamma A \} \ket{\psi}h(\gamma) \, \d \gamma
			= \int_0^\infty \bra{\psi}\frac{1}{\sqrt{A+t\I}} \frac{B}{A+t\I} h\left(\frac{B}{A+t\I} \right)\frac{1}{\sqrt{A+t\I}}\ket{\psi} \d t,
			\]
			since the integrands on the both sides are self-adjoint.

			An implication of Lusin's theorem is that there exists continuous functions $h_n$ on $[0,r]$ such that $h_n\to h$ almost everywhere.

			Suppose $h_n(\gamma)\to h(\gamma)$ on $[0,r]\setminus S$, $m(S)=0$, where $m(\cdot)$ denotes the Lebesgue measure of a Lebesgue-measurable set.

			Set $\widetilde{h_n}(\gamma)=\max\{0,\min\{h_n(\gamma),L\}\}$, then we still have $\widetilde{h_n}\to h$ on $[0,r]\setminus S$, but now $\widetilde{h_n}$ is nonegative and bounded above by $L$.

			For the left hand side, since \[
			0\leq\bra{\psi}\{ B > \gamma A \} \ket{\psi}\leq 1
			\]
			for all $\gamma\in[0,r]$, we have \[
			0\leq\bra{\psi}\{ B > \gamma A \} \ket{\psi}\widetilde{h_n}(\gamma)\leq L
			\] for all $\gamma\in[0,r]$.

			By the bounded convergence theorem, 
			\[
			\int_0^r \bra{\psi}\{ B > \gamma A \} \ket{\psi}\widetilde{h_n}(\gamma) \, \d \gamma \to
			\int_0^r \bra{\psi}\{ B > \gamma A \} \ket{\psi}h(\gamma) \, \d \gamma.
			\]

			For the right hand side, we also intend to apply the dominated convergence theorem, so we must check that \[
			\bra{\psi}\frac{1}{\sqrt{A+t\I}} \frac{B}{A+t\I} \widetilde{h_n}\left( \frac{B}{A+t\I} \right)\frac{1}{\sqrt{A+t\I}}\ket{\psi}\to \bra{\psi}\frac{1}{\sqrt{A+t\I}} \frac{B}{A+t\I} h\left( \frac{B}{A+t\I} \right)\frac{1}{\sqrt{A+t\I}}\ket{\psi}
			\]
			almost everywhere for $t\in [0,\infty)$.
			Hence, we claim that \[
			\frac{B}{A+t\I} \widetilde{h_n}\left( \frac{B}{A+t\I} \right)\to \frac{B}{A+t\I} h\left( \frac{B}{A+t\I} \right)
			\] almost everywhere in any matrix norm, which implies the convergence above. The proof of the claim is later deferred to Lemma~\ref{lemm:change-of-variable_lemma}.

			Now, since 
			\begin{align}
				&\left\vert\bra{\psi}\frac{1}{\sqrt{A+t\I}} \frac{B}{A+t\I} \widetilde{h_n}\left( \frac{B}{A+t\I} \right)\frac{1}{\sqrt{A+t\I}}\ket{\psi}\right\vert\\
				&=\bra{\psi}\frac{1}{\sqrt{A+t\I}} \frac{B}{A+t\I} \widetilde{h_n}\left( \frac{B}{A+t\I} \right)\frac{1}{\sqrt{A+t\I}}\ket{\psi}\\
				&\leq \bra{\psi}\frac{1}{\sqrt{A+t\I}} \cdot L\frac{B}{A+t\I}\cdot\frac{1}{\sqrt{A+t\I}}\ket{\psi}
			\end{align}
			and
			\[
			\int_0^\infty \bra{\psi}\frac{1}{\sqrt{A+t\I}} \cdot L\frac{B}{A+t\I}\cdot\frac{1}{\sqrt{A+t\I}}\ket{\psi}\d t=L\bra{\psi}{\rm D} \log[A](B)\ket{\psi}\leq rL<\infty,
			\]
			by the dominated convergence theorem, 
			\begin{align*}
				&\int_0^\infty\bra{\psi}\frac{1}{\sqrt{A+t\I}} \frac{B}{A+t\I} \widetilde{h_n}\left( \frac{B}{A+t\I} \right)\frac{1}{\sqrt{A+t\I}}\ket{\psi} \d t\\
				&\to\int_0^\infty\bra{\psi}\frac{1}{\sqrt{A+t\I}} \frac{B}{A+t\I} h\left( \frac{B}{A+t\I} \right)\frac{1}{\sqrt{A+t\I}}\ket{\psi} \d t.
			\end{align*}


			Hence 
			\begin{align}
				\int_0^r \bra{\psi}\{ B > \gamma A \} \ket{\psi}h(\gamma) \, \d \gamma   &=\lim_{n\to\infty}\int_0^r\bra{\psi}\{ B > \gamma A \} \ket{\psi}\widetilde{h_n}(\gamma) \, \d \gamma\\
				&=\lim_{n\to\infty} \int_0^\infty \bra{\psi}\frac{1}{A+t\I} B \frac{1}{A+t\I} \widetilde{h_n}\left( B \frac{1}{A+t\I} \right)\ket{\psi} \d t\\
				&= \int_0^\infty \bra{\psi}\frac{1}{A+t\I} B \frac{1}{A+t\I} h\left( B \frac{1}{A+t\I} \right)\ket{\psi} \d t.
			\end{align}

			For the next step, suppose that the nonnegative function $ h $  is integrable on $[0, r]$.  
			For any positive number $M > 0$ , define the truncated function by
			$h_M(\gamma) := \min\{h(\gamma), M\}$.
			Then $ h_M $ is bounded, nonnegative, and measurable. Thus, we have \[
			\int_0^r \bra{\psi}\{ B > \gamma A \} \ket{\psi}h_M(\gamma) \, \d \gamma=\int_0^\infty \bra{\psi}\frac{1}{\sqrt{A+t\I}} \frac{B}{A+t\I} h_M\left( \frac{B}{A+t\I} \right) \frac{1}{\sqrt{A+t\I}}\ket{\psi}\d t.
			\]
			On the other hand, since $h_M\nearrow h$, we know that
			\[
			\bra{\psi}\frac{1}{\sqrt{A+t\I}} \frac{B}{A+t\I} h_M\left( \frac{B}{A+t\I} \right) \frac{1}{\sqrt{A+t\I}}\ket{\psi} 
			\nearrow
			\bra{\psi}\frac{1}{\sqrt{A+t\I}} \frac{B}{A+t\I} h\left( \frac{B}{A+t\I} \right) \frac{1}{\sqrt{A+t\I}}\ket{\psi}.
			\]

			As a result,
			\begin{align}
				\int_0^r \bra{\psi}\{ B > \gamma A \} \ket{\psi}h(\gamma) \, \d \gamma   &=\lim_{M\to\infty}\int_0^r\bra{\psi}\{ B > \gamma A \}\ket{\psi} h_M(\gamma) \, \d \gamma\\
				&=\lim_{M\to\infty} \int_0^\infty \bra{\psi}\frac{1}{\sqrt{A+t\I}} \frac{B}{A+t\I} h_M\left( \frac{B}{A+t\I} \right) \frac{1}{\sqrt{A+t\I}}\ket{\psi} \d t\\
				&= \int_0^\infty \bra{\psi}\frac{1}{\sqrt{A+t\I}} \frac{B}{A+t\I} h\left( \frac{B}{A+t\I} \right) \frac{1}{\sqrt{A+t\I}}\ket{\psi} \d t,
			\end{align}
			by the monotone convergence theorem, for all $\ket{\psi}$.

			Furthermore, the fact that 
			\[
			\int_0^r \bra{\psi}\{ B > \gamma A \} \ket{\psi}h(\gamma) \, \d \gamma 
			\]
			is bounded by $\int_0^r h(\gamma) \, \d \gamma<\infty$ for all $\ket{\psi}$ implies that 
			\[
			\int_0^\infty \frac{1}{\sqrt{A+t\I}} \frac{B}{A+t\I} h\left( \frac{B}{A+t\I} \right) \frac{1}{\sqrt{A+t\I}} \d t
			\]
			is a self-adjoint matrix with its operator norm at most $\int_0^r h(\gamma) \, \d \gamma$, hence with finite entries.

			Finally, for any Lebesgue integrable function $h$ on $[0,r]$, we set $h_+(\gamma)=\max\{h(\gamma),0\}$ and $h_-(\gamma)=\max\{-h(\gamma),0\}$, then $h_+$ and $h_-$ are nonnegative and integrable. Applying the above result, we obtain 
			\begin{align}
				&\int_0^r \{ B > \gamma A \} h(\gamma) \, \d \gamma  \\ 
				&=\int_0^r \{ B > \gamma A \} h_+(\gamma) \, \d \gamma 
				-\int_0^r \{ B > \gamma A \} h_-(\gamma) \, \d \gamma \\
				&=\int_0^\infty \frac{1}{\sqrt{A+t\I}} \frac{B}{A+t\I} h_+\left( \frac{B}{A+t\I} \right) \frac{1}{\sqrt{A+t\I}} \d t-\int_0^\infty \frac{1}{\sqrt{A+t\I}} \frac{B}{A+t\I} h_-\left( \frac{B}{A+t\I} \right) \frac{1}{\sqrt{A+t\I}} \d t\\
				&= \int_0^\infty \frac{1}{\sqrt{A+t\I}} \frac{B}{A+t\I} h\left( \frac{B}{A+t\I} \right) \frac{1}{\sqrt{A+t\I}} \d t.
			\end{align}

		\end{proof}


		%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

		\begin{lemm} \label{lemm:change-of-variable_lemma}
			Given $\widetilde{h_n}(\gamma)\to h(\gamma)$ on $[0,r]\setminus S$, $m(S)=0$, we have
			\[
			\frac{B}{A+t\I} \widetilde{h_n}\left(  \frac{B}{A+t\I} \right)\to \frac{B}{A+t\I} h\left( \frac{B}{A+t\I} \right)
			\] almost everywhere in any matrix norm.
		\end{lemm}

		\begin{proof}
			By the given condition, we have $\gamma \widetilde{h_n}(\gamma)\to\gamma h(\gamma)$ except for $\gamma\in S\setminus\{0\}$.
			Hence, for $t\geq 0$ such that $\spec(\frac{B}{A+t\I})\cap (S\setminus\{0\})=\emptyset$, we already have
			\[
			\frac{B}{A+t\I} \widetilde{h_n}\left( \frac{B}{A+t\I} \right)\to \frac{B}{A+t\I} h\left( \frac{B}{A+t\I} \right).
			\]

			It remains to show that $E=\{t\geq 0|\spec(\frac{B}{A+t\I})\cap (S\setminus\{0\})\neq\emptyset\}$ has zero measure.

			Suppose that the space has dimension $n$. Since $\frac{B}{A+t\I}=\frac{1}{\sqrt{A+t\I}}B\frac{1}{\sqrt{A+t\I}}$ is analytic in $t\in (-\Vert A^{-1}\Vert^{-1},\infty)$, there exists analytic functions $\{\lambda_i(t)\}_{i=1}^n$ and analytic vector-valued functions $\{\ket{v_i(t)}\}_{i=1}^n$, such that $\frac{1}{\sqrt{A+t\I}}B\frac{1}{\sqrt{A+t\I}}\ket{v_i (t)}=\lambda_i \ket{v_i (t)}$ and $\braket{v_i(t)|v_j(t)}=\delta_{ij}$ \cite[Theorem 1.10]{Kat95}. For the purpose of this proof, we restrict the domain of these functions to $[0,\infty)$.

			By differentiating both sides of $\frac{1}{\sqrt{A+t\I}}B\frac{1}{\sqrt{A+t\I}}\ket{v_i (t)}=\lambda_i \ket{v_i (t)}$, we have
			\begin{align}
				&\frac{-1}{2}\left(\frac{1}{A+t\I}\frac{1}{\sqrt{A+t\I}}B\frac{1}{\sqrt{A+t\I}}+\frac{1}{\sqrt{A+t\I}}B\frac{1}{\sqrt{A+t\I}}\frac{1}{A+t\I}\right)\ket{v_i (t)}+\frac{1}{\sqrt{A+t\I}}B\frac{1}{\sqrt{A+t\I}}\frac{\d}{\d t}\ket{v_i (t)}\\
				&=\left(\frac{\d}{\d t} \lambda_i(t)\right)\ket{v_i (t)}+\lambda_i(t)\frac{\d}{\d t}\ket{v_i (t)}.
			\end{align}

			Apply $\bra{v_i(t)}$ on both sides, then we obtain \[
			-\lambda_i(t)\bra{v_i(t)}\frac{1}{A+t\I}\ket{v_i(t)}+\lambda_i(t)\bra{v_i(t)}\frac{\d}{\d t}\ket{v_i(t)}=\frac{\d}{\d t} \lambda_i(t)+\lambda_i(t)\bra{v_i(t)}\frac{\d}{\d t}\ket{v_i(t)},
			\]
			or \[
			\frac{\d}{\d t} \lambda_i(t)=-\lambda_i(t)\bra{v_i(t)}\frac{1}{A+t\I}\ket{v_i(t)}.
			\]

			The solution to the ordinary differential equation is $\lambda_i(t) = \lambda_i(0) \exp\left(-\int_0^t \bra{v_i(s)}(A+s\I)^{-1}\ket{v_i(s)} \d s\right)$. 

			We analyze the behavior of $\lambda_i(t)$ based on its initial value.

			\textbf{Case 1: $\boldsymbol{\lambda_i(0) = 0}$.}
			Then $\lambda_i(t) \equiv 0$ for all $t \ge 0$. In this case, the range of $\lambda_i(t)$ is just $\{0\}$, so its preimage of the set $S \setminus \{0\}$ is empty. An empty set has measure zero.

			\textbf{Case 2: $\boldsymbol{\lambda_i(0) > 0}$.}
			Then $\lambda_i(t)$ is strictly positive for all $t \ge 0$, and tends to $0$ as $t\to \infty$, as it is bounded by $\|(A+t\I)^{-1/2}B(A+t\I)^{-1/2}\|$.
			Consequently, the derivative
			\[ \frac{\d\lambda_i}{\d t} = -\lambda_i(t) \underbrace{\bra{v_i(t)} \frac{1}{A+t\I} \ket{v_i(t)}}_{>0} < 0. \]
			This shows that $\lambda_i(t)$ is a strictly decreasing bijection from $[0, \infty)$ onto $(0, \lambda_i(0)]$, and its derivative is never zero.
			By the inverse function theorem, its inverse exists and is continuously differentiable on the interval $(0, \lambda_i(0)]$.

			Note that the preimage $\lambda_i^{-1}(S \setminus \{0\})$ is precisely the image of the set $S \cap (0, \lambda_i(0)]$ under the inverse function. According to \cite[Lemma 7.25]{Rudin}, the inverse function sends the null set $S\cap (0,\lambda_i(0)]$ to another null set. We can therefore conclude that the preimage of $S\setminus\{0\}$ under $\lambda_i$, i.e., the image of $(S\setminus\{0\})\cap (0,\lambda_i(0)]$ under its inverse, has zero measure:
			\[ m(\lambda_i^{-1}(S \setminus \{0\})) = 0. \]


			Finally, observe that the set $E$ is the union of the preimages for each eigenvalue:
			\[ E = \bigcup_{i=1}^n \lambda_i^{-1}(S \setminus \{0\}). \]
			Since $E$ is a finite union of sets of measure zero, it is also a set of measure zero, i.e., $m(E)=0$. This completes the proof.
		\end{proof}

		\begin{defn}
			Let $X=P\Lambda P^{-1}$ be a finite-dimensional complex diagonalizable operator, where $\Lambda=\mathrm{diag}(\lambda_1,\dots,\lambda_n)$. For a complex-valued function $f:\mathds{C}\to\mathds{C}$, define $f(X)$ by $Pf(\Lambda) P^{-1}$, where $f(\Lambda):=\mathrm{diag}(f(\lambda_1),\dots,f(\lambda_n))$.
		\end{defn}

		One can verify that the above definition is well-defined. Under this definition, Theorem~\ref{theo:change-of-variable} can be simplified to the following proposition.

		\begin{prop}
			Let $A$ be a positive definite operator and $B$ a positive semi-definite operator on a finite-dimensional Hilbert space. Define $r := \| A^{-1/2}B A^{-1/2} \|_{\infty}$.
			Then, for any Lebesgue-integrable function $h$ on $[0,r]$,
			\begin{align} 
				\int_0^r \{ B > \gamma A \} h(\gamma) \, \d \gamma
				&= \int_0^\infty \frac{1}{A+t\I}  B \frac{1}{A+t\I} h\left(B\frac{1}{A+t\I} \right) \d t\\
				&= \int_0^\infty   h\left(\frac{1}{A+t\I} B \right)\frac{1}{A+t\I}  B\frac{1}{A+t\I} \d t.
			\end{align}
		\end{prop}


		\begin{proof}
			For all $t>0$, the operators \( B(A + t\I)^{-1} \) and \( (A + t\I)^{-1}B \) are diagonalizable and have the same spectrum as \( (A + t\I)^{-1/2} B (A + t\I)^{-1/2} \), since they are all similar. This implies that $h\left( B \frac{1}{A+t\I} \right)$ is well defined and
			\[
			\frac{1}{A+t\I} h\left(B\frac{1}{A+t\I}\right)
			= \frac{1}{\sqrt{A+t\I}} h\left(\frac{1}{\sqrt{A+t\I}} B \frac{1}{\sqrt{A+t\I}}\right)\frac{1}{\sqrt{A+t\I}}
			= h\left(\frac{1}{A+t\I} B\right)\frac{1}{A+t\I}.
			\]
			To see this, we interpolate $h$ on the spectrum by a polynomial function $g$, so that $h(X) = g(X)$ for $X = B(A + t\I)^{-1}$, $(A + t\I)^{-1/2} B (A + t\I)^{-1/2}$, and $(A + t\I)^{-1} B$. The desired equality then follows by direct calculation.
		\end{proof}

