\begin{ex}\label{ex: tangential slope example}
    Our next example shows that our main theorem fails if we assume that the curve $\gamma\colon[0,+\infty)\to\H$ satisfies
    \[
    \lim_{t\to+\infty}\mathrm{arg}(\gamma(t))=\pm\frac{\pi}{2}.
    \]
    For this, we let $\gamma$ be such that $\gamma(t)=1+it$, for all $t\geq0$. It is easy to see that $\arg(\gamma(t))$ converges to $\tfrac{\pi}{2}$. Now consider the hyperbolic map $f\colon\H\to\H$, with $f(z)=2z$, we used in Example \ref{ex: hyperbolic map}. Then, simple computations show that the projection of $f^n(1)=2^n$ onto $\gamma$ is the point $1$, for all $n\in\N$, and thus the sequence $\pi_\gamma(f^n(z))$ is constant.\\
    For the case where $\arg(\gamma(t))$ tends to $-\tfrac{\pi}{2}$ one can use the curve $\gamma(t)=1-it$.
\end{ex}

\begin{ex}\label{ex:corollary counterexample}
    Finally, we describe how the example constructed in \cite{BK} can be used to show that Corollary \ref{cor: main cor} may fail completely for parabolic functions. 

    In \cite[Section 4]{BK}, the authors construct a simply connected domain $\Omega\subsetneq\C$, with the following properties:
    \begin{enumerate}
        \item $z+t\in\Omega$, for all $t\geq0$ and any $z\in \Omega$;
        \item $\R\subset\Omega$;
        \item the family of holomorphic functions $\phi_t\colon \Omega\to\Omega$, with $\phi_t(z)=z+t$ is a parabolic semigroup in $\Omega$. 
    \end{enumerate}
    Let us remark that even though the definition of a semigroup presented in Example \ref{ex: hyperbolic semigroup} was stated only for the right half-plane, the definition can easily be extended to any simply connected domain via a Riemann map. Similarly, all the notation introduced for self-maps of $\H$ (or $\D$) can be easily transferred to $\Omega$. With this in mind, we will construct our example in $\Omega$. 

    A key point in their construction is that there exist real sequences $\{x_n\},\{y_n\}\subset \R$, tending to $+\infty$ such that $x_n<y_n<x_{n+1}$, for any $n\in\N$, and 
    \begin{equation}\label{eq:ex Bets-Kar 1}
         d_\Omega(0,x_n)>d_\Omega(0,y_n).
    \end{equation}
    In fact, $x_n$ and $y_n$ can be chosen to be positive integers (it is evident from \cite[Lemma 4.1]{BK} that one may chose $x_n=3^n-2^n$ and $y_n=3^n+2^n$).

    Now consider the function $\phi_1\colon\Omega\to\Omega$ from the semigroup $(\phi_t)$; that is, $\phi_1(z)=z+1$.  Since the semigroup $(\phi_t)$ is parabolic, every function $\phi_t$, for $t>0$, is also parabolic as a self-map of $\Omega$ (see the angular derivative condition \eqref{eq:angular der for semigroups} in Example \ref{ex: hyperbolic semigroup}). Note that $\phi_1^{x_n}(0)=x_n$ and $\phi_1^{y_n}(0)=y_n$. Thus, \eqref{eq:ex Bets-Kar 1} can be rewritten as
    \[
    d_\Omega(0,\phi_1^{x_n}(0))>d_\Omega(0,\phi_1^{y_n}(0)),
    \]
    meaning that the sequence $\{d_\Omega(0,\phi_1^n(0))\}$ is not eventually increasing. 
\end{ex}

\section{Projections of sequences onto curves}\label{sect:projections}%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

This section contains the bulk of our technical results about projections of arbitrary sequences onto curves. As usual, our proofs will be carried out in the right half-plane. 

Our first lemma requires some set-up. Let us denote by $\Delta_\H(z,r)$ the \emph{pseudo-hyperbolic disc} of $\H$, centred at $z\in\H$ and of radius $r\in(0,1)$; i.e.
\begin{equation}\label{eq: pseudo-hyp discs}
    \Delta_\H(z,r)=\{w\in\H\colon \rho_{\H}(w,z)<r\}.
\end{equation}

Using formula \eqref{eq: useful pseudo-hyp formula}, we can rewrite \eqref{eq: pseudo-hyp discs} as 
\begin{equation}\label{eq: pseudo-hyp discs v2}
    \Delta_\H(z,r)=\left\{w\in\H\colon \lvert \overline{w}+z\rvert^2<4\frac{\mathrm{Re}\ z}{1-r^2}\ \mathrm{Re}\ w\right\}
\end{equation}

The following lemma is a classical result \cite[Proposition 2.1.3]{Abate} quantifying the idea that horodiscs are limits of pseudo-hyperbolic discs, restated for the case of the right half-plane. We include a short proof for the sake of completeness.

\begin{lm}[\cite{Abate}]\label{lm: disc convergence lemma}
    Let $\{p_n\}\subset \H$ be a sequence of points converging to infinity and $\{r_n\}\subset(0,1)$ a sequence converging to 1. If
    \[
    \lim_{n\to+\infty}\frac{\mathrm{Re}\ p_n}{(1-r_n^2)\lvert 1+p_n\rvert^2}=\lambda\in (0,+\infty), 
    \]
    then 
    \[
    \left\{z\in\C\colon \mathrm{Re} \ z >\frac{1}{4\lambda} \right\}\subseteq \liminf_{n\to+\infty} \Delta_\H(p_n,r_n).
    \]
\end{lm}

\begin{proof}
    Arguing towards a contradiction, we assume that there exists a point $z_0\in\H$, with $\mathrm{Re}\ z_0>\tfrac{1}{4\lambda}$, and a sequence of integers $\{n_k\}$, so that $z_0\notin \Delta_\H(p_{n_k},r_{n_k})$, for all $k\in\N$. By \eqref{eq: pseudo-hyp discs v2}, this means that
    \begin{equation}\label{eq: disc convergence eq}
        4\ \mathrm{Re}\ z_0\frac{\mathrm{Re}\ p_{n_k}}{1-r_{n_k}^2}\leq \lvert \overline{z_0} +p_{n_k}\rvert^2 \leq \left(1+\frac{\lvert\overline{z_0} +1\rvert}{\lvert 1+p_{n_k}\rvert}\right)^2\ \lvert 1+p_{n_k}\rvert^2.
    \end{equation}
    Since $z_0$ is fixed and $p_n$ tends to infinity, we have that 
    \[
    \lim_{k\to+\infty}\frac{\lvert\overline{z_0} +1\rvert}{\lvert 1+p_{n_k}\rvert} =0.
    \]
    So, taking limits $k\to+\infty$ in \eqref{eq: disc convergence eq} yields 
    \[
    4\lambda \ \mathrm{Re}\ z_0\leq 1,
    \]
    which leads to a contradiction.
\end{proof}


We can now start our analysis by proving that in the setting of Theorem \ref{thm: main monotonicity result} (the half-plane version of Theorem \ref{thm: main result}), the projections tend to the point at infinity.

\begin{lm}\label{lm:convergence of projections to zeta}
    Let $\gamma\colon[0,+\infty) \to\H$ be a curve landing at infinity, with 
    \[
    \lim_{t\to+\infty}\mathrm{arg}(\gamma(t))=\theta, \quad  \text{for some}\ \theta\in(-\tfrac{\pi}{2}, \tfrac{\pi}{2}).
    \]
    If $\{z_n\}\subset\H$ is a sequence converging to infinity and $\pi_\gamma(z_n)$ is a projection of $z_n$ onto $\gamma$, for $n\in\N$, then
    \[
    \lim_{n\to+\infty}\pi_\gamma(z_n)=\infty.
    \]
\end{lm}

\begin{proof}
    For simplicity, we write $\pi_n\vcentcolon=\pi_\gamma(z_n)$. Since $\pi_n\in\gamma([0,+\infty))$, for all $n\in\N$, and $\gamma(t)$ converges to $\infty$, as $t\to+\infty$, it suffices to show that $\{\pi_n\}$ does not accumulate in $\H$. Assume, towards a contradiction, that the sequence $\{\pi_n\}$ is relatively bounded in $\H$. By passing to a subsequence if necessary, we can then assume that $\{\pi_n\}$ converges to some $z_0\in\H$, as $n\to+\infty$.\\
    Since $\pi_n$ is the projection of $z_n$ onto $\gamma$, the hyperbolic discs $D_\H(z_n,d_\H(z_n,\pi_n))$ do not intersect $\gamma([0,+\infty))$, for any $n\in\N$. Note that the formulas for the hyperbolic and pseudo-hyperbolic metrics, \eqref{eq:hyperbolic distance in H} and \eqref{eq: pseudo-hyperbolic metric} respectively, imply that $D_\H(z_n,d_\H(z_n,\pi_n))=\Delta_\H(z_n,\rho_\H(z_n,\pi_n))$, where $\Delta_\H$ are the pseudo-hyperbolic discs defined in \eqref{eq: pseudo-hyp discs}. Because $\{z_n\}$ converges to infinity, as $n\to+\infty$, we have that 
    \[
    \lim_{n\to+\infty}\rho_\H(z_n,\pi_n)=1.
    \]
    Our goal is to apply the Disc Convergence Lemma, Lemma \ref{lm: disc convergence lemma}, to the pseudo-hyperbolic discs $\Delta_\H(z_n,\rho(z_n,\pi_n))$. To do so, observe that the formula \eqref{eq: useful pseudo-hyp formula} implies that
    \begin{equation}\label{eq: convergence to zeta eq1}
        \frac{\mathrm{Re}\ z_n}{(1-\rho_\H(z_n,\pi_n)^2)\lvert 1+z_n\rvert^2}=\frac{\lvert \overline{z_n}+\pi_n\rvert^2}{4\mathrm{Re}\ \pi_n \lvert 1+z_n\rvert^2}.
    \end{equation}
    Because $\pi_n$ is bounded, we have that 
    \[
    \lim_{n\to+\infty}\frac{\lvert \overline{z_n}+\pi_n\rvert^2}{\lvert 1+z_n\rvert^2}=1.
    \]
    So, taking limits in \eqref{eq: convergence to zeta eq1} yields
    \[
    \lim_{n\to+\infty}\frac{\mathrm{Re}\ z_n}{(1-\rho_\H(z_n,\pi_n)^2)\lvert 1+z_n\rvert^2} = \frac{1}{4\ \mathrm{Re}\ z_0}>0.
    \]
    Thus, Lemma \ref{lm: disc convergence lemma} is indeed applicable to the sequence of discs $\Delta_\H(z_n,\rho_\H(z_n,\pi_n))$ and implies that 
    \begin{equation}\label{eq: convergence to zeta eq2}
        \{z\in\C\colon \mathrm{Re}\ z> \mathrm{Re}\ z_0\}\subseteq \liminf_{n\to+\infty} \Delta_\H(z_n,\rho_\H(z_n,\pi_n)).
    \end{equation}
    Recall that by assumption, $\mathrm{arg}(\gamma(t))$ converges to $\theta\in(-\tfrac{\pi}{2}, \tfrac{\pi}{2})$ and $\gamma(t)$ converges to $\infty$. This means that the set $\gamma([0,+\infty))$ intersects all half-planes $\{z\in\C\colon \mathrm{Re}\ z>x\}$, for $x>0$. Therefore, by \eqref{eq: convergence to zeta eq2} we get that 
    \[
    \gamma([0,+\infty))\cap\liminf_{n\to+\infty} \Delta_\H(z_n,\rho_\H(z_n,\pi_n))\neq\emptyset,
    \]
    meaning that there exist $t_0\geq0$ and $n_0\in\N$ so that $\gamma(t_0)\in\Delta_\H(z_n,\rho_\H(z_n,\pi_n))$, for all $n\geq n_0$, contradicting the fact that $\pi_n$ are projections of $z_n$.
\end{proof}

\medskip

Note that by Example \ref{ex: tangential slope example}, the conclusion of Lemma \ref{lm:convergence of projections to zeta} fails if we assume that $\mathrm{arg}(\gamma(t))$ converges to $\pm\tfrac{\pi}{2}$. However, using the same proof, one could reduce the assumption of Lemma \ref{lm:convergence of projections to zeta} to: ``the slope of $\gamma$ contains an angle $\theta\in(-\tfrac{\pi}{2}, \tfrac{\pi}{2})$", recalling that the slope of $\gamma$ is the cluster set of $\arg(\gamma(t))$.

\medskip


Before moving on, we state the following handy fact, whose proof is a simple exercise in calculus.

\begin{lm}\label{lm:cosh fact}
    If $\{x_n\},\{y_n\}\subset \R$ are real sequences with $\lim\limits_{n\to+\infty}(x_n-y_n)=0$, then 
    \[
    \lim_{n\to+\infty} \frac{\cosh x_n}{\cosh y_n}=1.
    \]
\end{lm}

The next theorem is the main result of this section and shows that projections of a sequence onto different curves landing with the same angle are asymptotically close.

\begin{theorem}\label{lm:orthogonal lemma 2}
	Let $\gamma_j:[0,+\infty)\to\H$, $j=1,2$, be two curves landing at $\infty$, with 
    \[
    \lim_{t\to+\infty}\mathrm{arg}(\gamma_j(t))=\theta,
    \]
    for some $\theta\in(-\tfrac{\pi}{2},\tfrac{\pi}{2})$ and $j=1,2$. Let $\{z_n\}\subset\H$ be a sequence converging to $\infty$. If $\pi_{\gamma_j}(z_n)$ is a projection of $z_n$ on $\gamma_j$, for $j=1,2$ and $n\in\N$, then
    \[
    \lim_{n\to+\infty}d_\H(\pi_{\gamma_1}(z_n),\pi_{\gamma_2}(z_n))=0.
    \]
\end{theorem}
\begin{proof}
	In order to simplify notation, we write $\pi_n^j\vcentcolon=\pi_{\gamma_j}(z_n)$ for $j=1,2$ and all $n\in\N$. Note that Lemma \ref{lm:convergence of projections to zeta} is applicable and yields that both sequences $\{\pi_n^1\},\{\pi_n^2\}$ converge to $\infty$, as $n\to+\infty$.\\
    Consider the straight half-line $\gamma\colon[1,+\infty)\to\H$, with $\gamma(t)=te^{i\theta}$. Recall from Lemma \ref{lm: sectors in H} that for all $R>0$, we have that
    \[
    S_R\vcentcolon= \{z\in\H\colon d_\H(z,\gamma)<R\}= D_\H(e^{i\theta},R)\cup\{re^{i\phi}\colon r>1, \ \phi\in(\phi_1,\phi_2)\},
    \]
    for some $\phi_1\in(-\tfrac{\pi}{2},\theta)$ and $\phi_2\in(\theta,\tfrac{\pi}{2})$ satisfying $d_\H(e^{i\theta},e^{i\phi_1})=d_\H(e^{i\theta},e^{i\phi_2})=R$. So, since $\gamma_1$ lands at $\infty$ with $\lim_{t\to+\infty}\arg(\gamma_1(t))=\theta$, we get that for every $R>0$, there exists a $t_0\geq0$, so that $\gamma_1([t_0,+\infty))\subset S_R$. So, for any sequence $\{\zeta_n\}\subset \gamma_1([0,+\infty))$, converging to $\infty$, we have that
    \begin{equation}\label{eq:orthogonal speed lemma 2, eq1}
        \lim_{n\to+\infty}d_\H(\zeta_n,\gamma)=0.
    \end{equation}
    Observe that due to Lemma \ref{lm: properties of metric in H} (1), the unique projections of $z_n$ and $\pi_n^1$ onto $\gamma$ are $\lvert z_n\rvert e^{i\theta}$ and $\lvert \pi_n^1\rvert e^{i\theta}$, respectively, for sufficiently large $n\in\N$ (see Figure \ref{fig:projection}). Since $\{\pi_n^1\}\subset\gamma_1([0,+\infty))$ and $\pi^1_n\xrightarrow{n\to+\infty}\infty$, \eqref{eq:orthogonal speed lemma 2, eq1} yields
    \begin{equation}\label{eq:orthogonal speed lemma 2, eq2}
    \lim_{n\to+\infty}d_\H(\pi^1_n, \lvert \pi^1_n \rvert e^{i\theta})=0.
    \end{equation}
