\emailAdd{fb.nieri@gmail.com}



\abstract{We investigate trace formulas in $\vep$-deformed W-algebras, highlighting a novel connection to the modular double of $\q$-deformed W-algebras. In particular, we show that torus correlators in the additive (Yangian) setting reproduce sphere correlators in the trigonometric setup, possibly with the inclusion of a non-perturbative completion. From a dual perspective, this mechanism implements a gauge theoretic 2d$\to$3d uplift, where a circle direction in the world-sheet transmutes to a compact space-time direction in a non-trivial manner. We further discuss a unified picture of deformed W-algebras driven by trace formulas, suggesting a deeper algebraic layer related to the massive and massless form-factor approach to integrable QFT and 2d CFT.}

%\mathsubclass{81T20, 81T40, 81T60, 81R10, 81R50, 17B68.}

\keywords{Deformed W-algebras, Yangian and quantum toroidal algebras, bosonization and trace formulas, supersymmetric gauge theory, integrable form-factors.}

