\section{Introduction}

Positivity concepts such as plurisubharmonicity and Griffiths/Nakano positivity are fundamental in several complex variables and complex geometry. These notions have yielded significant results including H\"ormander's $L^2$ existence theorem for the $\overline{\partial}$-equation \cite{Hor65} and the Ohsawa-Takegoshi $L^2$ extension theorem \cite{OT87}.

Recently, Deng, Ning, Wang, Zhang, and Zhou \cite{DNW21, DNWZ22, DWZZ24} developed a converse $L^2$ theory, establishing new characterizations of plurisubharmonicity and Griffiths/Nakano positivity through $L^2$ conditions related to the $\overline{\partial}$-operator.

\begin{definition}[\cite{DNW21}]
Let   $\varphi$ be  an upper semi-continuous function on  a domain $D\subset \CC^n$.  We say that $\varphi$ is \emph{$L^2$-optimal}
   if for any Stein coordinates $U\subset D$, for any smooth strictly plurisubharmonic function $\phi$ and
   any K\"{a}hler metric $\omega$ on $U$,
   the equation $\dbar u=f$ can be solved on $U$ for any $\dbar$-closed  $(n,1)$-form
   $f \in L^2_{(n,1)}(U; \loc)$
   with the estimate:
   \begin{equation}\label{eq:a1}
   \int_U|u|^2_{\omega} e^{-\varphi-\phi} dV_\omega
   \leq
   \int_U \inner{B_{\omega,\phi}^{-1}f,f}_{\omega} e^{-\varphi-\phi} dV_{\omega},
  \end{equation}
   provided that the right-hand side is finite, where $B_{\omega,\phi}:=[i\ddbar \phi, \Lambda_{\omega}]$.
\end{definition}


\begin{remark}
It is worthwhile mentioning that the integrals on both sides of \eqref{eq:a1} are independent of the choice of the K\"ahler metric $\omega$ since $u$ is an $(n,0)$-form and $f$ is an $(n,1)$-form.
\end{remark}

 It follows from H\"ormander's $L^2$ existence theorem
 that any plurisubharmonic function $\varphi$ is $L^2$-optimal. The converse was established by Deng-Ning-Wang \cite[Theorem 1.2]{DNW21}, who showed that $L^2$-optimality implies plurisubharmonicity for $C^2$-smooth functions.

 A natural question arises whether this regularity condition can be relaxed. It is well-known that plurisubharmonic functions are strongly upper semi-continuous: for any $x\in D$ and subset $S\subset D$ of measure zero,
\[
\limsup_{\substack{z\in D\setminus S \\ z\to x}} \varphi(z) = \varphi(x).
\]
This suggests the following conjecture:

\begin{conj}[{\cite[Remark 1.9]{DNW21}}]\label{conj DNW}
   Let $\varphi$ be a (strongly) upper semi-continuous function. If $\varphi$ is $L^2$-optimal, then $\varphi$ is plurisubharmonic.
\end{conj}

Notice that  any plurisubharmonic function satisfies ``the optimal $L^2$-extension property" \cite{Blocki13, GZext} and conversely,  any upper semi-continuous function with the optimal $L^2$-extension property is plurisubharmonic \cite{DNW21}. Consequently,   we can establish Conjecture  \ref{conj DNW} by verifying this property for $L^2$-optimal functions.

%Recently, \cite{Liu25} resolved Conjecture \ref{conj DNW} for continuous functions via an optimal $L^2$ extension theorem, while the techniques employed there seem inadequate for the (strongly) upper semi-continuous case.

 In this paper, we adapt the approach of   \cite[Theorem 1.3]{LXYZ21} with a key modification -- replacing the generalized Siu's lemma \cite{ZZsiulem} by a Lebesgue-type differentiation theorem -- to establish an Ohsawa-Takegoshi-type $L^2$ extension theorem for upper semi-continuous $L^2$-optimal functions.

\begin{theorem}\label{Thm:OT ext}
   Let $\varphi$ be an upper semi-continuous function on   a  Stein domain $U\times D\subset \CC^{n-k}_{w'}\times\CC^k_{w''}$.
	 Assume that $D$ is bounded, $\varphi$ is $L^2$ optimal and $\supp\calO/\calI(\varphi)\subset H\times D$ for some hypersurface $H\subset U$.  Then for almost all $z''\in D$, for any $f\in \calO(U\times\{z''\})$ with
$\int_{U\times\{z''\}}|f|^2e^{-\varphi}d\lambda_{n-k}(w')<+\infty,$
 there is an $F\in \calO(U\times D)$ such that $F|_{U\times\{z''\}}=f$ and
\begin{equation*}
\int_{U\times D}  \frac{|F|^2e^{-\varphi}}{ |w''-z''|^{2k}(\log |w''-z''|^2)^2} d\lambda_{n}(w)\leq C \int_{U\times\{z''\}}|f|^2e^{-\varphi} d\lambda_{n-k}(w'),
\end{equation*}
where $C$ is a uniform constant only depending on $k$ and $\sup_{w''\in D}|w''|^2$.
\end{theorem}
\begin{remark}
\begin{enumerate}
  \item  Here $\calI(\varphi)$ is the multiplier ideal sheaf of $\calO$ defined by
\begin{equation*}
\calI(\varphi)_x := \{u\in \calO_x; |u|^2e^{-\varphi} \textup{ is integrable in some neighborhood of } x\}.
\end{equation*}
\item  If $k=n$,  $U$ and the condition that $\supp\calO/\calI(\varphi)\subset H\times D$  will disappear,  and $ \int_{U\times\{z''\}}|f|^2e^{-\varphi} d\lambda_{n-k}(w')$ will be replaced by $|f(z'')|^2e^{-\varphi(z'')}$.
  \item  Although the uniform constant $C$ obtained here are not sharp enough to   settle Conjecture \ref{conj DNW}, this approach provides a potential pathway towards the complete solution via refined coefficient estimates.
\end{enumerate}
\end{remark}

As our primary application, we provide a characterization of plurisubharmonic functions via the ``multiple coarse
 $L^2$-estimate property" (Definition \ref{def DNW}), which relaxes the continuity assumption in \cite[Theorem 1.5]{DNW21} to strong upper semi-continuity.

\begin{theorem}\label{thm DNW mod}
   A measurable function $\varphi:D\subset\CC^n\to [-\infty,+\infty)$ is plurisubharmonic if and only if
   $\varphi$ is strongly upper semi-continuous and satisfies the multiple coarse $L^2$-estimate property.
\end{theorem}
\begin{remark}
  If   $\varphi$ is  upper semi-continuous and satisfies the multiple coarse $L^2$-estimate property, then $\varphi$  agrees almost everywhere with a plurisubharmonic function.
\end{remark}

An important analytic invariant measuring the singularity of plurisubharmonic functions is the Lelong number $\nu(\varphi,x)$ at $x$, defined as
\begin{equation*}
\nu(\varphi,x):=\sup\{c\ge0; \varphi(z)\le c\log|z-x|+O(1) \textup{ near } x\},
\end{equation*}
which remains valid for (strongly) upper semi-continuous functions. For plurisubharmonic functions, the  celebrated Skoda  integrability theorem \cite{Skoda72} states that $\calI(\varphi)_x=\calO_x$ when $\nu(\varphi,x)<2$.

Multiplier ideal sheaves, serving as a bridge between complex analysis and algebraic geometry, possess fundamental properties including coherence, torsion-freeness, and integral closure. A significant  breakthrough in their study was Guan-Zhou's resolution \cite{GZsoc} of Demailly's strong openness conjecture \cite{Demailly-note2000, DK2001} through their innovative combination of the Ohsawa-Takegoshi extension theorem with inductive techniques.

In addition, as applications of Theorem \ref{Thm:OT ext}, we show that (strongly) upper semi-continuous $L^2$-optimal functions satisfy both  Skoda's integrability theorem and the strong openness property. We expect these results to provide useful tools for the eventual resolution of Conjecture \ref{conj DNW}.
\begin{theorem}[Skoda's integrability theorem]\label{thm Skoda}
  Let $\varphi$ be a strongly upper semi-continuous  $L^2$-optimal function on a domain $D\subset\CC^n$. Assume that $\calI(\varphi)\not\equiv 0$. If $\nu(\varphi,x)<2$ for some $x\in D$, then $\calI(\varphi)_x=\calO_x$.
\end{theorem}

\begin{theorem}\label{thm SOC}
  Let $\varphi$ be an upper semi-continuous  function on a domain $D\subset\CC^n$. Let $\{\varphi_j\}_{j\ge1}$ be upper semi-continuous  and $L^2$-optimal functions  increasingly converging to $\varphi$ on $D$. Assume that $\calI(\varphi_1)\not\equiv 0$. Then $\calI(\varphi)=\bigcup_j\calI(\varphi_j)$.
\end{theorem}

\begin{remark}
  Indeed, following the argument in \cite[Proposition 2.18]{LXYZ21}, we observe that  $\varphi$ itself must be $L^2$-optimal.
\end{remark}

Let $\varphi$ be an upper semi-continuous function on a domain $D\subset\mathbb{C}^n$ with $P(\varphi)\not\equiv-\infty$, where $P(\varphi)$ denotes its plurisubharmonic envelope:
\begin{equation*}
P(\varphi) := \sup\{\psi\in \text{Psh}(D) : \psi\leq\varphi\}.
\end{equation*}
When $\varphi$ is $L^2$-optimal, Lemma \ref{lem h^} implies that $\varphi+\varepsilon P(\varphi)$ remains $L^2$-optimal for any $\varepsilon>0$. Consequently, Theorem \ref{thm SOC} establishes that

\begin{corollary}[Strong openness property]
   Let $\varphi$ be an upper semi-continuous  and $L^2$-optimal function  on  a domain $D\subset\CC^n$. Assume that  $P(\varphi)\not\equiv-\infty$, then $$\calI(\varphi) =\bigcup_{\eps>0}\calI((1+\eps)\varphi).$$
\end{corollary}




The remaining parts of this article are organized as follows. Section \ref{Sec:Lebesgue} presents a Lebesgue-type differentiation theorem; Section \ref{Sec:Lemmas} presents some properties of $L^2$-optimal functions; Section \ref{Sec:Ext} presents a proof of  Theorem \ref{Thm:OT ext};  Section \ref{Sec:Appl} presents a characterization of plurisubharmonic functions, Skoda's integrability theorem and the strong openness property for (strongly) upper semi-continuous $L^2$-optimal functions.


