\section{Preliminaries} \label{Sec:Pre}

In this paper, $d\lambda_n$ denotes the Lebesgue measure of $\mathbb{C}^n$. For any $z\in\CC^n$ and $r>0$, we denote $\mathbb{B}^n_z(r):=\{w\in\mathbb{C}^n;|w-z|<r\}$ and $\DD^n_z(r):=\{w\in\CC^n;|w_k-z_k|<r, \text{ for }1\le k\le n\}$.

\subsection{Lebesgue-type differentiation theorem}\label{Sec:Lebesgue}


\begin{lemma}[Vitali covering lemma, {\cite[Theorem 1.2]{Hein01}}]\label{lem covering}
  Every family $\mathcal{F}$ of balls of uniformly bounded diameter in $\CC^n$ contains a disjointed subfamily $\mathcal{G}$, which means that no two balls in $\mathcal{G}$ meet, such that
  $$\bigcup_{B\in\mathcal{F}}B\subset\bigcup_{B\in\mathcal{G}} 5B.$$
\end{lemma}
%\begin{remark}[Polydisk version]\label{rmk:polydisk-covering}The Besicovitch covering lemma remains valid when balls $\BB^n(r)$ are replaced by polydisks $\DD^n(r)$ with the same expansion constant 5.\end{remark}

\begin{theorem}[Lebesgue differentiation theorem]
  Let $f\in L^1(\CC^n;\loc)$, then for almost all $z\in\CC^n$, $$\lim_{\eps\to 0}\frac{1}{\lambda_n(\BB^n_z(\eps))}\int_{\BB^n_z(\eps)}
  |f(w)-f(z)|d\lambda_n(w)=0.$$
\end{theorem}

Let $f\in L^1(\CC^n)$. It follows from  Fubini's theorem that the function $$F(z''):=\int_{\CC^{n-k}}f(z',z'')d\lambda_{n-k}(z')$$ is locally integrable on $\CC^k$. Then by the Lebesgue differentiation theorem, we have

\begin{proposition}\label{prop weak Lebesgue hyperplane}
  Let $f\in L^1(\CC^n)$, then for almost all $z''\in\CC^k$, $$\lim_{\eps\to 0} \int_{\BB^k_{z''}(\eps)}\hspace{-3.05em}-\quad\quad
  \left|\int_{\CC^{n-k}}f(w',w'')-f(w',z'')d\lambda_{n-k}(w')\right|
  d\lambda_k(w'')=0.$$
\end{proposition}

\begin{remark}
  The above result, while informative, is insufficient for our main theorems. By refining the approach used in proving the Lebesgue differentiation theorem, we establish a more powerful version (Proposition \ref{prop Lebesgue hyperplane}) adequate for our needs.
\end{remark}


\begin{definition}
  Let $f\in L^1(\CC^n)$. Define the maximal function $$Mf(z''):=\sup_{\eps> 0} \int_{\BB^k_{z''}(\eps)}\hspace{-3.05em}-\quad\quad
  \int_{\CC^{n-k}}|f(w',w'')|d\lambda_{n-k}(w')
  d\lambda_k(w'')$$
\end{definition}

\begin{proposition}
   Let $f\in L^1(\CC^n)$, then the maximal function $Mf$ is lower semi-continuous on $\CC^k$.
\end{proposition}
\begin{proof}
It follows from Fubini's theorem that $Mf$ is finite almost everywhere.
  For any $t\in(0,+\infty)$, it suffices to show that $E_t:=\{z''\in \CC^k; Mf(z'')>t\}$ is open. Fix $z''_0\in E_t$, then there is $\eps>0$ such that $$ \int_{\BB^k_{z''_0}(\eps)}\hspace{-3.05em}-\quad\quad\int_{
  \CC^{n-k}}
   |f(w',w'')|d\lambda_{n-k}(w')d\lambda_k(w'')>t.$$
   Take $\eps'>\eps$ with $$ \frac{1}{\lambda_k(\BB^k_{z''_0}(\eps'))}\int_{\BB^k_{z''_0}(\eps)}\int_{
  \CC^{n-k}}
   |f(w',w'')|d\lambda_{n-k}(w')d\lambda_k(w'')>t,$$ then for any $z''\in \CC$ with $|z''-z''_0|<\eps'-\eps$, we have $\BB^k_{z''_0}(\eps)\subset\BB^k_{z''}(\eps')$ and \begin{align*}
     t <&\frac{1}{\lambda_k(\BB^k_{z''_0}(\eps'))}\int_{\BB^k_{z''_0}(\eps)}\int_{
  \CC^{n-k}}
   |f(w',w'')|d\lambda_{n-k}(w')d\lambda_k(w'')\\
      \le&  \int_{\BB^k_{z''}(\eps')}\hspace{-3.3em}-\quad\quad\ \int_{
  \CC^{n-k}}
   |f(w',w'')|d\lambda_{n-k}(w')d\lambda_k(w'')\le Mf(z'').
   \end{align*}
   Hence $\BB^k_{z''_0}(\eps'-\eps)\subset E_t$ and we complete the proof.
   \end{proof}

\begin{theorem}[Hardy-Littlewood theorem]
  Let $f\in L^1(\CC^n)$, then for any $t\in(0,+\infty)$, $$\lambda_k(\{z''\in\CC^k; Mf(z'')>t\})\le 5^{2k}t^{-1}\|f\|_{L^1}.$$
\end{theorem}
\begin{proof}
  Fix $t>0$ and denote $E_t:=\{z''\in\CC^k; Mf(z'')>t\}$.  It suffices to show that  any compact subset $K$ of $E_t$ satisfies $$\lambda_k(K)\le 5^{2k}t^{-1}\|f\|_{L^1}.$$

  For $z''\in K$, there is open disk $\BB_{z''}(\eps_{z''})$ such that  $$ \int_{\BB^{k}_{z''}(\eps_{z''})}\hspace{-3.9em}-\quad\quad\quad\int_{
  \CC^{n-k}}
   |f(w',w'')|d\lambda_{n-k}(w')d\lambda_k(w'')>t.$$
   Since $K$ is compact, then there are finite open balls $\{\BB_{z''_j}(\eps_{z''_j}); 1\le j\le N\}$ covering $K$. It follows from Lemma \ref{lem covering} that there are mutually disjoint open balls $\BB_{z''_{j_\ell}}(\eps_{z''_{j_\ell}}), 1\le \ell\le M (M\le N)$   such that $\{\BB_{z''_{j_\ell}}(5\eps_{z''_{j_\ell}}); 1\le \ell\le M\}$ covering $K$. Hence we have
   \begin{align*}
     \lambda_k(K) \le& 5^{2k}\sum_{\ell=1}^{M}\lambda_k(\BB_{z''_{j_\ell}}(\eps_{z''_{j_\ell}})) \\
      \le & 5^{2k}t^{-1} \sum_{j=1}^{M}\int_{\BB_{z''_{j_\ell}}(\eps_{z''_{j_\ell}})}\int_{
  \CC^{n-k}}
   |f(w',w'')|d\lambda_{n-k}(w')d\lambda_k(w'')\\
   \le& 5^{2k}t^{-1} \|f\|_{L^1}.
   \end{align*}
\end{proof}


\begin{proposition}\label{prop f*}
 Let $f\in L^1(\CC^n)$ and  define $$f^*(z''):=\limsup_{\eps\to 0} \int_{\BB^k_{z''}(\eps)}\hspace{-3.05em}-\quad\quad
  \int_{\CC^{n-k}}|f(w',w'')-f(w',z'')|d\lambda_{n-k}(w')
  d\lambda_k(w'').$$ Then we have
  \begin{enumerate}
    \item[(i)] If $f\in C^0_c(\CC^n)$, then $f^*=0$.
    \item[(ii)] If $g\in L^1(\CC^n)$ with $g^*=0$, then $f^*=(f-g)^*$.
    \item[(iii)] $\lambda_k(\{z''\in\CC^k;f^*(z'')>t\})\le 2(5^{2k}+1)t^{-1}\|f\|_{L^1}.$
  \end{enumerate}
\end{proposition}
  \begin{proof}
  \begin{enumerate}
    \item[(i)] Since $f\in C^0_c(\CC^n)$, then $\supp(f)\subset \BB^{n-k}_0(R)\times \BB^{k}_0(R)$ for some $R>0$.  In addition,  for any $\delta>0$, there is $r>0$ such that $$|f(w',w'')-f(w',z'')|<\delta$$ as long as $|w''-z''|<r$.  Hence for $\eps<r$, we have \begin{align*}
                                                 \int_{\BB^k_{z''}(\eps)}\hspace{-3.05em}-\quad\quad
  \int_{\CC^{n-k}}|f(w',w'')-f(w',z'')|d\lambda_{n-k}(w')
  d\lambda_k(w'')
                                              \le &  \lambda_{n-k}(\BB^{n-k}_0(R))\delta.
                                            \end{align*}  As a result, $f^*=0$.
    \item[(ii)] By the  triangle inequality, we have  \begin{align*}
               (f-g)^* \le& f^*+g^*= f^* = (f-g+g)^*\le (f-g)^*+g^*=(f-g)^*.
             \end{align*}
    \item[(iii)] Since \begin{align*}
                         f^*(z'') \le & \sup_{\eps> 0} \int_{\BB^k_{z''}(\eps)}\hspace{-3.05em}-\quad\quad
  \int_{\CC^{n-k}}|f(w',w'')-f(w',z'')|d\lambda_{n-k}(w')
  d\lambda_k(w'') \\
                         \le & Mf(z'')+ \int_{\CC^{n-k}}|f(w',z'')|d\lambda_{n-k}(w').
                       \end{align*}
                       Note that  $F(z''):=\int_{\CC^{n-k}}|f(w',z'')|d\lambda_{n-k}(w')$ is integrable on $\CC^k$, then by
                       Chebyshev's inequality, we have $$\lambda_k(\{z''\in\CC^k;F(z'')>t\})\le t^{-1}\|F\|_{L^1}=t^{-1}\|f\|_{L^1}.$$
      Therefore, \begin{align*}
               & \lambda_k(\{z''\in\CC^k;f^*(z'')>t\})\\ \le    & \lambda_k(\{z''\in\CC^k;Mf^*(z'')>\frac{t}{2}\})+\lambda_k(\{z''\in\CC^k;F(z'')>\frac{t}{2}\})\\
                   \le & 2(5^{2k}+1)t^{-1}\|f\|_{L^1}.
                 \end{align*}
  \end{enumerate}

  \end{proof}

Now we can strength the Proposition \ref{prop weak Lebesgue hyperplane} as follows.


\begin{proposition}[Lebesgue-type differentiation theorem]\label{prop Lebesgue hyperplane}
  Let $f\in L^1(\CC^n)$, then for almost all $z''\in\CC^k$, $$\int_{\CC^{n-k}}| f(w',z'')|d\lambda_{n-k}(w')<+\infty$$ and $$\lim_{\eps\to 0} \int_{\BB^k_{z''}(\eps)}\hspace{-3.05em}-\quad\quad
  \int_{\CC^{n-k}}|f(w',w'')-f(w',z'')|d\lambda_{n-k}(w')
  d\lambda_k(w'')=0.$$
\end{proposition}

\begin{remark}
  Let $U\subset \CC^{n-k}$, $D\subset\CC^k$ and $f\in L^1(U\times D)$. Consider
  \begin{equation*}
   \tilde{f}(z):=\left\{\begin{aligned}
    &f(z), &z\in U\times D;\\
    &0,    &z\notin U\times D.
  \end{aligned}\right.
    \end{equation*}
Then $\tilde{f}\in L^1(\CC^n)$ and Proposition \ref{prop Lebesgue hyperplane} implies that for almost all $z''\in D$, $$\lim_{\eps\to 0} \int_{\BB^k_{z''}(\eps)}\hspace{-3.05em}-\quad\quad
  \int_{U}|f(w',w'')-f(w',z'')|d\lambda_{n-k}(w')
  d\lambda_k(w'')=0.$$
  %\item From the proof and Remark \ref{rmk:polydisk-covering},we conclude that the theorem remains valid when Euclidean balls $\BB^k_{z''}(\eps)$ are replaced by polydisks $\DD^k_{z''}(\eps)$.

\end{remark}



\begin{proof}
It suffices to show that $f^*=0$ almost everywhere.
 Since $f\in L^1(\CC^n)$, for any $\delta>0$, we can find a function $g_\delta\in C^0_c(\CC^n)$ such that $\|f-g_\delta\|_{L^1}\le\delta.$ Then it follows from Proposition \ref{prop f*} that
 \begin{align*}
   \lambda_k(\{z''\in\CC^k;f^*(z'')>t\})= &\lambda_k(\{z''\in\CC^k;(f-g_\delta)^*(z'')>t\})  \\
   \le & 2(5^{2k}+1)t^{-1}\|f-g_\delta\|_{L^1} \\
    \le &  2(5^{2k}+1)t^{-1}\delta.
 \end{align*}
 Since $\delta$ is arbitrary, we get $\lambda_k(\{z''\in\CC^k;f^*(z'')>t\})=0$ for any $t>0$. We complete the proof.

\end{proof}

\subsection{Some properties of $L^2$-optimal functions}\label{Sec:Lemmas}

In this section, we will recall and prove some basic properties of $L^2$-optimal functions.

\begin{lemma}[\cite{Nadel, LZ24}]\label{lem coherent}
Let $D$ be a domain in $\CC^n$ and $\varphi$ be an upper semi-continuous function on $D$.
  Assume that $(D,\varphi)$ is $L^2$-optimal, then $\calI(\varphi)$   is coherent. In particular, the support set of the quotient sheaf $\mathcal{O}/\mathcal{I}(\varphi)$ is an analytic subset of $D$.
\end{lemma}

\begin{remark}\label{rmk coherent}
  If moreover that $\calI(\varphi)\not\equiv 0$, then $\supp( \mathcal{O}/\mathcal{I}(\varphi))$ is a proper analytic subset of $D$. which means that $e^{-\varphi}$ is locally integrable outside a proper analytic subset. In particular, $\varphi>-\infty$ almost everywhere.
\end{remark}

\begin{lemma}[{\cite[Proposition 2.14]{LXYZ21}}]\label{lem h^}
    Let $\varphi, \varphi_j$ be upper semi-continuous functions on a holomorphic vector bundle $E$.
    Assume that $\{\varphi_j\}$ are $L^2$-optimal and decreasingly converge to $\varphi$.
    Then $\varphi$ is also $L^2$-optimal.
    Especially, $\varphi+\phi$ is $L^2$-optimal for any plurisubharmonic function $\phi$.
\end{lemma}


It is well-known that any complex analytic subset is $L^2$-negligible in the sense of the following lemma.

\begin{lemma}[{\cite[Chapter VIII-(7.3)]{D12a}}]\label{lem L2negligible}
  Let $D$ be an open subset of $\CC^n$ and $Z$  a complex analytic subset of $D$.
Assume that $u$ is  a $(p, q-1)$-form with $L^2_\loc$
coefficients and $f$ a $(p, q)$-form with $L^1_\loc$ coefficients
such that $\dbar u=f$ on $D\setminus Z$ (in the sense of distribution theory). Then $\dbar u=f$ on $D$.
\end{lemma}

\begin{lemma}[{\cite[(5.8) Proposition]{D12b}}]\label{lem dem mod}
  Let $\pi:X'\to X$ be a proper holomorphic modification between two complex manifolds of dimension $n$. Let $\varphi$ be an upper semi-continuous function on $X$. Then $\pi_*(K_{X'}\otimes\calI(\pi^*\varphi))=K_X\otimes\calI(\varphi)$.
\end{lemma}

\begin{lemma}\label{lem soc mod}
   Let $\pi:X'\to X$ be a proper holomorphic modification between two complex manifolds of dimension $n$. Let $\varphi$ be an upper semi-continuous function on $X$. If  $\calI(\pi^*\varphi)$ has strong openness property, then $\calI(\varphi)$  has strong openness property.
\end{lemma}
   \begin{proof}
  As $X'$ and $X$ are both complex manifolds, we need only prove that the strong openness property holding for $K_{X'}\otimes \mathcal{I}(\pi^*\varphi)$ guarantees the strong openness property for $K_X\otimes\mathcal{I}(\varphi)$.

    Fix $x\in X$ and $f\in K_X\otimes\calI(\varphi)_x$, there is a neighbourhood $  U$ of $x$ such that $\int_{U}i^{n^2} f \wedge \overline{f} e^{-\varphi}<+\infty$. By Lemma \ref{lem dem mod}, $\pi^*f\in H^0(\pi^{-1}(U),K_{X'}\otimes \calI(\pi^*\varphi))$ and
    the change of variable formula yields
$$\int_{U}i^{n^2} f \wedge \overline{f} e^{-\varphi}=\int_{\pi^{-1}(U)}i^{n^2} \pi^*f \wedge \overline{\pi^*f} e^{-\pi^*\varphi}.$$
 Since $\pi^{-1}(x)\subset \subset\pi^{-1}(U)$ is compact and $\calI(\pi^*\varphi)$ has strong openness property, there is $p>1$ and a subset $V\subset  U$ containing $\pi^{-1}(x)$ such that $$\int_{V}i^{n^2} \pi^*f \wedge \overline{\pi^*f} e^{-p\pi^*\varphi}<+\infty.$$ Since $\pi(V)$ is an open set containing $x$, then the change of variable formula yields $\int_{\pi(V)}i^{n^2} f \wedge \overline{f} e^{-p\varphi}<+\infty$. We complete the proof.
   \end{proof}

Noticing that any analytic set in a Stein manifold is globally defined and any
   Stein manifold is still Stein after removing a hypersurface, then we can show that the $L^2$-optimal property is preserved under  proper holomorphic modifications.

\begin{lemma}\label{lem modification}
  Let $\pi:X'\to X$ be a proper holomorphic modification between two complex manifolds. Let $\varphi$ be an upper semi-continuous function on   $X$. Then $\varphi$ is $L^2$-optimal if and only if $\pi^*\varphi$ is $L^2$-optimal.
\end{lemma}

\begin{proof}
Let $n = \dim X = \dim X'$ and let $S \subset X$ be an analytic set such that $\pi : X' \setminus S' \to X \setminus S$ is a biholomorphism, where $S'=\pi^{-1}(S')$.

Assume that $\pi^*\varphi$ is $L^2$-optimal.
  Let $U\subset X$ be a Stein coordinate, $\phi$  a smooth strictly plurisubharmonic function,
   $\omega$  a K\"{a}hler metric  on $U$ and
   $f$  a $\dbar$-closed  $(n,1)$-form satisfying with \begin{equation*}
   \int_U \inner{B_{\omega,\phi}^{-1}f,f}_{\omega} e^{-\varphi-\phi} dV_{\omega}<+\infty.
  \end{equation*}
  Notice that the  integral is independent of the choice of $\omega$ and
  there is a nonzero holomorphic function $G\in \calO(U)$ such that $U\cap S\subset G^{-1}(0)$. Then $U\setminus G^{-1}(0)$ is also  Stein.
  Since $\varphi$ is locally bounded from above, we may even consider forms $f$ which are a priori defined only on $U \setminus G^{-1}(0) $, because $f$ will be in $L^2_{\text{loc}}(U)$ and therefore will automatically extend through $G^{-1}(0)$ by Lemma \ref{lem L2negligible}. The change of variable formula yields
  \begin{align*}
   \int_{\pi^{-1}(U)} \inner{B_{\pi^*\omega,\pi ^*\phi}^{-1}\pi^*f,\pi^*f}_{\pi^*\omega} e^{-\pi^*\varphi-\pi^*\phi} dV_{\pi^*\omega}=&\int_U \inner{B_{\omega,\phi}^{-1}f,f}_{\omega} e^{-\varphi-\phi} dV_{\omega}.
  \end{align*}

    Notice that $\pi$ is  a biholomorphism   on $\pi^{-1}(U\setminus G^{-1}(0))$,
   and $\pi^*\varphi$ is $L^2$-optimal, then the equation $\dbar u=\pi ^*f$ can be solved on $\pi^{-1}(U\setminus G^{-1}(0))$
   with the estimate:
   \begin{align*}
   & \int_{\pi^{-1}(U\setminus G^{-1}(0))}|u|^2_{\pi ^*\omega} e^{-\pi ^*\varphi-\pi^*\phi} dV_{\pi^*\omega}
     \\\leq &\int_{\pi^{-1}(U)} \inner{B_{\pi^*\omega,\pi ^*\phi}^{-1}\pi^*f,\pi^*f}_{\pi^*\omega} e^{-\pi ^*\varphi-\pi^*\phi} dV_{\pi^*\omega}.
  \end{align*}
  Hence $\dbar((\pi^{-1})^* u)=f$ on  $U\setminus G^{-1}(0)$ with \begin{equation*}
   \int_{U\setminus G^{-1}(0)}|(\pi^{-1})^* u|^2_{\omega} e^{-\varphi-\phi} dV_{\omega}
   \leq
     \int_U \inner{B_{\omega,\phi}^{-1}f,f}_{\omega} e^{-\varphi-\phi} dV_{\omega}.
  \end{equation*}
  Notice that $\varphi$ is   bound from above locally, the  Lemma \ref{lem L2negligible} implies that $\dbar(\pi^{-1})^* u=f$ on  $U$.
This means that $\varphi$   is $L^2$-optimal.

  Similarly, we can also derive the $L^2$-optimality of $\pi^*\varphi$ from the $L^2$-optimality of $\varphi$.  We complete the proof.
\end{proof}

\begin{lemma}[Siu-type lemma]\label{lem weak siu lemma}
  Let $\varphi$ be an upper semi-continuous function on  a bounded domain $U\times D\subset \CC^{n-k}_{w'}\times\CC^k_{w''}$. Assume that $\calI(\varphi)=\calO$. Then almost every $z''\in D$ satisfies that  for any  relatively compact subset $V\Subset U$  and any nonnegative function $P\in C^0(\overline{V}\times D)$, we have $$ \int_{V}P(w',z'')e^{-\varphi(w',z'')}d\lambda_{n-k}(w')<+\infty$$ and $$\lim_{\eps\to 0} \int_{\BB_{z''}(\eps)}\hspace{-3.05em}-\quad\quad
  \int_{V}P(w',w'') |e^{-\varphi(w',w'')}- e^{-\varphi(w',z'')}|d\lambda_{n-k}(w')
  d\lambda_n(w'')=0.$$
\end{lemma}
\begin{proof}
Let $\{U_\ell\}$ be a compact exhaustion of $U$, which means $U_\ell\Subset U_{\ell+1}$ for each $\ell$ and $\bigcup_{\ell=1}^{+\infty}U_\ell=U$.  Then for any  relatively compact subset $V\Subset U$, $V\subset U_\ell$ for some $\ell$.
    Since  $\calI(\varphi)=\calO$, we know that the function $\int_{U_\ell}e^{-\varphi(w',w'')}d\lambda_{n-k}(w')$ is locally integrable on $D\subset\CC^k$. Then by Proposition \ref{prop Lebesgue hyperplane}, there is a measurable subset $A_{\ell}$ of full measure such that  $$\lim_{\eps\to 0}\int_{\BB_{z''}(\eps)}\hspace{-3.05em}-\quad\quad
  \int_{U_\ell}| e^{-\varphi(w',w'')}- e^{-\varphi(w',z'')}|d\lambda_{n-k}(w')
  d\lambda_n(w'')=0$$ for any $z''\in A_{\ell}$. Therefore,  for any $z''\in\bigcap_{\ell}A_{\ell}$, we obtain that $$\lim_{\eps\to 0} \int_{\BB_{z''}(\eps)}\hspace{-3.05em}-\quad\quad
  \int_{V} |e^{-\varphi(w',w'')}- e^{-\varphi(w',z'')}|d\lambda_{n-k}(w')
  d\lambda_n(w'')=0$$ for any $V\Subset U$.
  Notice that $P$ is uniformly continuous on $V\times \BB^k_{z''}(\eps)$, then for any $z''\in\bigcap_{\ell}A_{\ell}$, we obtain
  $$\lim_{\eps\to 0} \int_{\BB_{z''}(\eps)}\hspace{-3.05em}-\quad\quad
  \int_{V}P(w',w'') |e^{-\varphi(w',w'')}- e^{-\varphi(w',z'')}|d\lambda_{n-k}(w')
  d\lambda_n(w'')=0.$$

\end{proof}


\begin{lemma}[{\cite[Proposition 3.3]{LXYZ21}}] \label{pro nak res nak}
Let $\varphi$ be an upper semi-continuous function on a Stein domain $U\times D\subset \CC_{w'}^{n-k}\times\CC_{w''}^k$. Assume that $\varphi$ is $L^2$ optimal and $\supp\calO/\calI(\varphi)\subset H\times D$ for some hypersurface $H\subset U$.  Then for almost all $z''\in D$,  $\varphi|_{U\times\{z''\}}$ is  $L^2$-optimal.
\end{lemma}
\begin{proof}
Since $U\setminus H$ is also Stein, there is  a Stein exhaustion $U_\ell$ of $U\setminus H$ and we have
$\calI(\varphi)=\calO$ on $\overline{U_\ell}\times D$. It follows from Lemma \ref{lem weak siu lemma} that there is a subset $A$ of $D$ such that $\lambda_k(A)=\lambda(D)$ and  any $z''\in A$ satisfies that  for any $U_\ell$ and any nonnegative function $P\in   C^0(\overline{U_\ell}\times D)$, we have
$$ \int_{U_\ell}P(w',z'')e^{-\varphi(w',z'')}d\lambda_{n-k}(w')<+\infty$$ and
\begin{equation}\label{for pro nak res nak aaa}
                                                 \lim_{\eps\to 0} \int_{\BB_{z''}(\eps)}\hspace{-3.05em}-\quad\quad
  \int_{U_\ell}P(w',w'') |e^{-\varphi(w',w'')}- e^{-\varphi(w',z'')}|d\lambda_{n-k}(w')
  d\lambda_k(w'')=0.
                                                   \end{equation}

 For any $z''\in A$, let $V\subset U$ be a Stein open subset,  $\omega$  a K\"{a}hler metric, $\phi$ a smooth strictly plurisubharmonic function on $V\times\{z''\}$ and $f(w')=\sum_{j=1}^{n-k}f^{(j)}(w')d\bar w'_j$ a $\dbar$-closed  $(n-k,1)$-form   such that
   \begin{equation*}
   \int_{V\times\{z''\}} \inner{B_{\omega,\phi}^{-1}f,f}_{\omega} e^{-\varphi-\phi} dV_{\omega}<+\infty.
  \end{equation*}
  Let $V_\ell$ be  a Stein exhaustion of $V\setminus H$. After passing to a subsequence, we may assume that $V_\ell\subset U_ell$ for each $\ell$. Let $f_\ell$ be the smooth approximation sequence of $f$ obtained by convolution on $V_{\ell+1}$, then we have $\dbar f_\ell=0$ and $f_\ell$ are smooth on $\overline{V_\ell}\times\{z''\}$ with
 \begin{equation}\label{for pro nak res nak bbb}
\lim_{\ell\to+\infty}\int_{V_\ell\times\{z''\}} \inner{B_{\omega,\phi}^{-1}f_\ell,f_\ell}_{\omega} e^{-\varphi-\phi} dV_{\omega}=\int_{V\times\{z''\}} \inner{B_{\omega,\phi}^{-1}f,f}_{\omega} e^{-\varphi-\phi} dV_{\omega}.
 \end{equation}

  Write $w=(w',w'')=(w_1,\cdots,w_{n-k},w_{n-k+1},\cdots,w_n)$ and take a K\"{a}hler metric $\widetilde\omega=\omega+\sum_{j=n-k+1}^n\frac{i}{2}dw_j\wedge d\bar w_j$    on $V_{\ell,\eps}:=V_\ell\times\BB^k_{z''}(\eps)$. Notice that $\phi_\eps(w',w''):=\phi(w')+\eps|w''-z''|^2$ is a smooth strictly plurisubharmonic function on $V_{\ell,\eps}$ and $$\widetilde{f_\ell}(w',w'')=\sum_{j=1}^{n-k}f_\ell^{(j)}(w')\wedge dw''\wedge d\bar w_j$$ is a $\dbar$-closed  $(n,1)$-form on $V_{\ell,\eps}$, where $dw''=dw_{n-k+1}\wedge\cdots\wedge dw_n$.

Since $\phi_\eps(w',z'')=\phi(w')$ and  $\langle B^{-1}_{\widetilde\omega,\phi_\eps} \widetilde {f_\ell} ,\widetilde {f_\ell}  \rangle_{\widetilde\omega} =\langle B^{-1}_{\omega,\phi}   f_\ell ,  f_\ell  \rangle_{ \omega}, $
then by \eqref{for pro nak res nak aaa},  we obtain \begin{align}\label{for pro nak res nak ddd}
  &\lim_{\eps \to 0} \frac{1}{\lambda_k(\BB^k_{z''}(\eps))}\int_{V_{\ell, \eps}}  \langle B^{-1}_{\widetilde\omega,\phi_\eps} \widetilde {f_\ell} ,\widetilde {f_\ell}  \rangle_{\widetilde\omega}e^{-\varphi-\phi_\eps}dV_{\widetilde\omega}\nonumber\\=&\int_{V_\ell\times\{z''\}}\langle B^{-1}_{\omega,\phi}   f_\ell,  f_\ell \rangle_{ \omega}e^{-\varphi-\phi}dV_{\omega}.
 \end{align}

Since $\varphi$ is $L^2$-optimal,
 there is a $v_{\ell,\eps}\in L^2_{n,0}(V_{\ell, \eps},E;\loc)$ such that $\dbar v_{\ell,\eps}=\widetilde f$ and
     \begin{align*}
    \int_{V_{\ell, \eps}} |v_{\ell,\eps}|^2_{\omega} e^{-\varphi-\phi_\eps} dV_{\widetilde\omega}
    \le \int_{V_{\ell, \eps}} \langle B^{-1}_{\omega,\phi_\eps}\widetilde {f_\ell},\widetilde {f_\ell} \rangle_{\widetilde\omega} e^{-\varphi-\phi_\eps} dV_{\widetilde\omega}.
 \end{align*}
 Moreover, by the weak regularity of $\dbar$ on $(n,0)$-forms, we can take $v_{\ell,\eps}$ to be smooth.
Using Fubini's theorem, we know that for any $\eps>0$, there exists a $\xi_\eps\in \BB^k_{z''}(\eps)\cap A$ such that \begin{equation*}
            \int_{V_\eps\cap\{w''=\xi_\eps\} }|v_{\ell,\eps}(w',\xi_\eps)|^2_{\widetilde\omega,h}e^{-\varphi-\phi_\eps}dV_{\widetilde\omega}\le
\frac{1}{\lambda_k(\BB^k_{z''}(\eps))}\int_{V_{\ell, \eps}} |v_{\ell,\eps}|^2_{\widetilde\omega,h} e^{-\varphi-\phi_\eps} dV_{\widetilde\omega}.
          \end{equation*}
Let $u_{\ell, \eps}(w')=v_{\eps}(w',\xi_\eps)/dw''$, then we have $\dbar u_{\ell, \eps}=f_\ell$ on $U$ and \begin{align}\label{for pro nak res nak ccc}
&\int_{V_\ell\times\{z''\} }|u_{\ell,\eps}|^2_{\omega}e^{-\varphi(w',\xi_\eps)-\phi_\eps(w',\xi_\eps)}dV_{\omega}\nonumber\\ \le&
\frac{1}{\lambda_k(\BB^k_{z''}(\eps))}\int_{V_{\ell, \eps}} \langle B^{-1}_{\widetilde\omega,\phi_\eps}\widetilde {f_\ell},\widetilde {f_\ell} \rangle_{\widetilde\omega} e^{-\varphi-\phi_\eps} dV_{\widetilde\omega}. 
\end{align}

Since $\varphi$ is upper semi-continuous,
we  can choose a sequence $\eps_k\to 0$ such that $u_{\ell,\eps_k}$  compactly converges to a limit $u_\ell$. Then   $\dbar u=f$ and for any $K\subset V_\ell$, by Fatou's lemma together with   \eqref{for pro nak res nak ddd} and \eqref{for pro nak res nak ccc} , we have
\begin{align}\label{eq gap}
  &\int_{K\times\{z''\} } |u_\ell|^2_{\omega}e^{-\varphi-\phi}dV_\omega   \nonumber\\\le &\int_{K\times\{z''\} } \lim_{\eps_k\to0}  |u_{\ell,\eps_k}|_\omega^2\cdot\liminf_{\eps_k\to0}e^{-\varphi(w',\xi_{\eps_k})-\phi_{\eps_k}(w',\xi_{\eps_k})}dV_\omega
  \nonumber\\\le &\int_{K\times\{z''\} } \liminf_{\eps_k\to0}  |u_{\ell,\eps_k}|_\omega^2 e^{-\varphi(w',\xi_{\eps_k})-\phi_{\eps_k}(w',\xi_{\eps_k})}dV_\omega  \\\le & \liminf_{\eps_k\to0} \int_{K\times\{z''\} } |u_{\ell,\eps_k}|_\omega^2 e^{-\varphi(w',\xi_{\eps_k})-\phi_{\eps_k}(w',\xi_{\eps_k})}dV_\omega    \nonumber\\  \le&   \liminf_{\eps_k\to0} \frac{1}{\lambda_k(\BB^k_{z''}(\eps_k))}\int_{V_{\ell, \eps_k}} \langle B^{-1}_{\widetilde\omega,\phi_{\eps_k}}\widetilde {f_\ell},\widetilde {f_\ell} \rangle_{\widetilde\omega} e^{-\varphi-\phi_{\eps_k}} dV_{\widetilde\omega}\nonumber\\
  \le & \int_{V_\ell\times \{z''\} }\langle B^{-1}_{\omega,\phi}   f_\ell,  f_\ell \rangle_{ \omega}e^{-\varphi-\phi}dV_{\omega},\nonumber
\end{align}
where  the second inequality is due to the fact that $$\liminf_ka_k\liminf_kb_k\le\liminf_ka_kb_k$$ for nonnegative sequence $\{a_k\},\{b_k\}$.
Since  $K\Subset V_\ell$ is arbitrary, we obtain
$$\int_{V_\ell\times\{z''\} } |u_\ell|^2_{\omega}e^{-\varphi-\phi}dV_\omega \le  \int_{V_\ell\times \{z''\} }\langle B^{-1}_{\omega,\phi}   f_\ell,  f_\ell \rangle_{ \omega,h}e^{-\varphi-\phi}dV_{\omega}.$$
Then  we can choose a sequence $\ell_k\to 0$ such that $u_{\ell_k}$  weakly converges to a limit $u$ on $V\times\{z''\}$. Then $\dbar u=f$. In addition, by Mazur's theorem, there is a sequence $\{g_j\}$ such that $g_j$ strongly converges to $u$ where each $g_{j}$ is a convex combination of
	$\{u_{\ell_k} \}_{k\ge j}$. Write $g_{j}=\sum_{m=1}^{N}a_mu_{\ell_{k_m}}$ for $a_m>0$ with $\sum_{m=1}^{N}a_m=1$, then by the Cauchy-Schwarz inequality, we have
\begin{align*}
  &\int_{V_\ell\times\{z''\} }|g_j|^2_{\omega}e^{-\varphi-\phi}dV_\omega \\
 = &\int_{V_\ell\times\{z''\} }|\sum_{m=1}^{N}a_mu_{\ell_{k_m}}|^2_{\omega}e^{-\varphi-\phi}dV_\omega\\
 \le &\int_{V_\ell\times\{z''\} }\left(\sum_{m=1}^{N}a_m\right)
 \left(\sum_{m=1}^{N}(a_m|u_{\ell_{k_m}}|^2_{\omega})\right)e^{-\varphi-\phi}dV_\omega\\
 \le& \sum_{m=1}^{N}a_m\int_{V_\ell\times \{z''\} }\langle B^{-1}_{\omega,\phi}   f_{\ell_{k_m}},  f_{\ell_{k_m}} \rangle_{ \omega,h}e^{-\varphi-\phi}dV_{\omega}
\end{align*}

Then by Fatou's lemma and (\ref{for pro nak res nak bbb}), we have
$$\int_{V\times\{z''\}}|u|^2_{\omega}e^{-\varphi-\phi}dV_\omega\le\int_{V\times \{z''\} }\langle B^{-1}_{\omega,\phi}   f ,  f  \rangle_{\omega}e^{-\varphi-\phi}dV_{\omega}.$$


\end{proof}

\begin{remark}
  In this section, all properties hold satisfactorily for ``upper semi-continuous" $L^2$-optimal Hermitian metrics on holomorphic vector bundles. However, the validity of the following modified inequality replacing \eqref{eq gap} remains unclear:
\begin{equation}\label{eq modified gap}
\lim_{\eps_k\to 0}\liminf_{\xi\to z''} |u_{\ell,\eps_k}|_{\omega,h(z',\xi)}^2
\leq \lim_{\eps_k\to 0}|u_{\ell,\eps_k}|_{\omega,h(z',\xi_{\eps_k})}^2.
\end{equation}
\end{remark}

\section{$L^2$ extension theorem}\label{Sec:Ext}


   Note that if we use Lemma \ref{lem weak siu lemma} instead of the generalized Siu's lemma (\cite[Lemma 2.22]{LXYZ21}) in the proof  of \cite[Theorem 3.1]{LXYZ21}, then we can obtain the following $L^2$-extension theorem for upper semi-continuous $L^2$-optimal functions.
\begin{theorem}[=Theorem \ref{Thm:OT ext}]
   Let $\varphi$ be an upper semi-continuous function on  a  Stein domain $U\times D\subset \CC^{n-k}_{w'}\times\CC^k_{w''}$.
	 Assume that $D$ is bounded, $\varphi$ is $L^2$ optimal and $\supp\calO/\calI(\varphi)\subset H\times D$ for some hypersurface $H\subset U$.  Then for almost every $z''\in D$, for any $f\in \calO(U\times\{z''\})$ with
$\int_{U\times\{z''\}}|f|^2e^{-\varphi}d\lambda_{n-k}(w')<+\infty,$
 there is an $F\in \calO(U\times D)$ such that $F|_{U\times\{z''\}}=f$ and
\begin{equation*}
\int_{U\times D}  \frac{|F|^2e^{-\varphi}}{ |w''-z''|^{2k}(\log |w''-z''|^2)^2} d\lambda_{n}(w)\leq C \int_{U\times\{z''\}}|f|^2e^{-\varphi} d\lambda_{n-k}(w'),
\end{equation*}
where $C$ is a uniform constant only depending on $k$ and $\sup_{w''\in D}|w''|^2$.

  If $k=n$,  $U$ and the condition that $\supp\calO/\calI(\varphi)\subset H\times D$  will disappear,  and $ \int_{U\times\{z''\}}|f|^2e^{-\varphi} d\lambda_{n-k}(w')$ will be replaced by $|f(z'')|^2e^{-\varphi(z'')}$.
\end{theorem}

\begin{proof}
\vskip0.3cm
\noindent {\bf Step One: Reduce to the case that $\calI(\varphi)=\calO$.}
\vskip0.5cm
    Notice that $U\setminus H$ is Stein and $\calI(\varphi)=\calO$ on $(U\setminus H)\times D$. If  we have proven that for almost every $z''\in D$, there is a holomorphic function $F$ on $(U\setminus H)\times D$ such that $F=f$ on $(U\setminus H)\times\{z''\}$ and
\begin{equation*}
\int_{(U\setminus H)\times D}  \frac{|F|^2e^{-\varphi}}{ |w''-z''|^{2k}(\log |w''-z''|^2)^2} d\lambda_{n}(w)\leq C \int_{(U\setminus H)\times\{z''\}}|f|^2e^{-\varphi} d\lambda_{n-k}(w').
\end{equation*}
Since $\varphi$ is bounded from above locally, then by Lemma \ref{lem L2negligible}, the holomorphic function $F$ can extend holomorphically across $H\times D$ with the same estimate.

 If $k=n$, we may assume that $\calI(\varphi)\not\equiv0$. Then it follows from Lemma \ref{lem coherent} that $\supp\calO/\calI(\varphi)$ is a proper analytic subset of $D$. Since $D$ is Stein, there is a hypersurface $H\subset D$ such that  $\calI(\varphi)=\calO$ on $D\setminus H$ and $D\setminus H$ is also Stein.
 In summary, we may assume that $\calI(\varphi)=\calO$.


\vskip0.3cm
\noindent {\bf Step Two:   Construction an $L^2$ extension of openness type via  minimal  solutions \cite{chenboyong}.}
\vskip0.5cm

     Since $\calI(\varphi)=\calO$, Lemma \ref{lem weak siu lemma} implies the existence of a full-measure subset $A \subset D$ such that for every $z'' \in A$, the following holds: given any relatively compact subset $V \Subset U$ and any nonnegative continuous function $P \in C^0(\overline{V} \times D)$, we have  $$ \int_{V}P(w',z'')e^{-\varphi(w',z'')}d\lambda_{n-k}(w')<+\infty$$ and
     \begin{equation}\label{for basic}
     \lim_{\eps\to 0} \int_{\BB_{z''}(\eps)}\hspace{-3.05em}-\quad\quad
  \int_{V}P(w',w'') |e^{-\varphi(w',w'')}- e^{-\varphi(w',z'')}|d\lambda_{n-k}(w')
  d\lambda_n(w'')=0
  \end{equation}.
  Now fix $z''\in A$ and $f\in \calO(U\times\{z''\})$ with
$\int_{U\times\{z''\}}|f|^2e^{-\varphi}d\lambda_{n-k}(w')<+\infty$.
  Since $U\times D$ is Stein, by  Cartan's extension theorem, there is a holomorphic function $\hat{f}$ on $U\times D$ such that $\hat{f}|_{U\times\{z''\}}=f$. Take  Stein exhaustions $\{U_j\}$ and $\{D_j\}$ of $U$ and $D$ respectively.

  Let $C_D:=2e^2\sup_{w''\in D}|w''|^2$ and $r(w)=C_D^{-1}|w''-z''|^2$. Define $\phi=\log r$, $\phi_\varepsilon=\log (r+\varepsilon^2)$ and $\phi_{\delta,\varepsilon}(z)=\log (r+\delta^2+\varepsilon^2)=\log (e^{\phi_\delta}+\varepsilon^2)$ on $U\times D$.	
  Then $r\le e^{-2}$ and $\phi,\phi_\eps<-1$ for $\eps$ small enough.
	Take $\tau(t)=kt$ and $\chi(t)=-\log(-t+\log (-t))$ when $t<-1$, then
	$$\chi'=\frac{1-t^{-1}}{-t+\log(-t)}>0~~,~~ \chi''=\frac{(1-t^{-1})^2}{(-t+\log(-t))^2}+\frac{t^{-2}}{-t+\log(-t)}>0.$$	
    Let $0\le\rho:=\rho_{\varepsilon}\le1 $ be a smooth function on $\mathbb{R}$ such that $\rho=1$ on $(-\infty, a_\varepsilon)$, $\rho=0$ on $(b_\varepsilon,+\infty)$ and $|\rho'|\le \frac{1+c_\varepsilon}{b_\varepsilon-a_\varepsilon}$ on $(a_\varepsilon,b_\varepsilon)$, where $b_\varepsilon>a_\varepsilon>0$, $c_\varepsilon>0$ are to be determined later and $\lim_\varepsilon b_\varepsilon=\lim_\varepsilon c_\varepsilon=0$.

    Write $w=(w',w'')=(w_1,\cdots,w_{n-k},w_{n-k+1},\cdots,w_n)$. Let $\omega=\sum_{j=1}^{n}\frac{i}{2}dw_j\wedge d\bar{w}_j$. Then $dV_\omega:=\frac{\omega^n}{n!}=d\lambda_n(w)$.
	 Notice that $v:=\hat{f}dw\wedge \overline{\partial}\rho(r)$ is a $\dbar$-closed (n,1)-form on $U\times D$ and for $\varepsilon>0$ small enough, we have
	\begin{align*}
	\int_{U_j\times D_j} |v|^2_{\omega} e^{-\varphi-\tau(\phi)}dV_\omega
	= \int_{\{a_\varepsilon\le r \le b_\varepsilon\}} |\hat{f}|^2|\rho'|^2|dw\wedge \dbar r|_\omega^2 e^{-\varphi-\tau(\log r)}dV_{\omega}<+\infty,
	\end{align*}
	where $\eps$ small enough.

Since $\tau(\phi)$ is plurisubharmonic, it follows from Lemma \ref{lem h^} that $\varphi_\tau=\varphi+\tau(\phi)$ is also $L^2$-optimal.
	Then there exists a solution $\hat{u}$ of $\overline{\partial}\hat u=v$ such that
	\begin{align*}
	 \int_{U_j\times D_j} |\hat{u}|_\omega^2e^{-\varphi_\tau-\Psi}dV_{\omega}\le
	 \int_{U_j\times D_j} \langle B_{\omega,\Psi}^{-1}v,v\rangle_{\omega}e^{-\varphi_\tau-\Psi}dV_{\omega}<+\infty,
	 \end{align*}
	where $\Psi$ is a positive, bounded, smooth and strictly plurisubharmonic exhaustion function on $U\times D$. Take $u:=u_{\varepsilon,j}$ be the solution of $\overline{\partial}u=v$ with minimal norm in $L^2_{(n,0)}({U_j\times D_j},e^{-\varphi_\tau})$, that is, $u \perp  \Ker \overline{\partial}$ in $L^2_{(n,0)}({U_j\times D_j},e^{-\varphi_\tau})$.
	Since $\chi(\phi_{\varepsilon})$ is a smooth plurisubharmonic function on $U\times D$ and hence bounded on $U_j\times D_j$, we have $ue^{\chi(\phi_{\varepsilon})}\perp\Ker \overline{\partial}$ in $L^2_{(n,0)}({U_j\times D_j},  e^{-\varphi_\tau-\chi(\phi_{\varepsilon})})$, which means that $ue^{\chi(\phi_{\varepsilon})}$ is the minimal solution of $\dbar s=\dbar(ue^{\chi(\phi_{\varepsilon})})$ in $L^2_{(n,0)}({U_j\times D_j},  e^{-\varphi_\tau-\chi(\phi_{\varepsilon})})$.

Let  $\psi_{\delta}=\tau(\phi_\delta)+\chi(\phi_{\delta,\varepsilon})+\delta\Psi$, then $\lim_{\delta\to0}\psi_\delta=\varphi_\tau+\chi(\phi_{\varepsilon}).$
	Since $\log r$ is plurisubharmonic, we have $i  r\ddbar r \ge i \partial r\wedge \dbar r$. Therefore,
\begin{align*}
	i\ddbar \psi_\delta
	\ge 	\left(  \frac{\chi''}{(r+\varepsilon^2+\delta^2)^2}+
	\frac{(\delta^2+\eps^2)\chi'}{r(r+\delta^2+\varepsilon^2)^2}\right) \cdot i\partial r\wedge \dbar r,
		\end{align*}
	where $\chi'=\chi'(\phi_{\delta,\eps}), \chi''=\chi''(\phi_{\delta,\eps})$.

    Then for fixed $\eps>0$, by the dominated convergence theorem,  we have
	\begin{align*}
	& \limsup_{\delta\to0}\int_{U_j\times D_j} \langle B_{\omega,\psi_\delta}^{-1}\overline{\partial}(ue^{\chi(\phi_\varepsilon) }), \overline{\partial}(ue^{\chi(\phi_\varepsilon) })\rangle_\omega e^{-\psi_{\delta}(z)-\varphi}dV_{\omega}\\
	=&\limsup_{\delta\to 0}\int_{{U_j\times D_j}}|\dbar r|^2_{i \ddbar \psi_{\delta}} |\rho' \hat{f}+(r+\varepsilon^2)^{-1}\chi'  u|^2_{\omega}e^{2\chi(\phi_\varepsilon)-\psi_{\delta}-\varphi}dV_{\omega}\\
	\le& \int_{ U_j\times D_j}
	\frac{r|(r+\varepsilon^2)\rho'(r) \hat{f}+\chi'(\phi_\varepsilon) u|^2_{h}~e^{\chi(\phi_\varepsilon)-\tau(\phi)}}
	{r{\chi''(\phi_\varepsilon)}+\chi'(\phi_\varepsilon)\varepsilon^2}dV_{\omega}=:I,
 \end{align*}
 where the last integration $I$ is finite. Since $\psi_\delta$ is smooth strictly plurisubharmonic function decreasingly converging to $\chi(\phi_\varepsilon)+\tau(\phi)$,
then by a standard approximating procedure,  $\overline{\partial}s=\overline{\partial}(ue^{\chi(\phi_\varepsilon)})$ have a solution    with the estimate
\begin{align*}
	\int_{U_j\times D_j} |s|^2_{\omega}e^{-\varphi-\chi(\phi_\varepsilon)-\tau(\phi)}dV_{\omega}
	\le I.
	\end{align*}
	Noticing that $ue^{\chi(\phi_\varepsilon)}$ is the minimal solution of the equation $\dbar s=\dbar(ue^{\chi(\phi_{\varepsilon})})$ in $L^2_{(n,0)}({U_j\times D_j},  e^{-\varphi_\tau-\chi(\phi_{\varepsilon})})$, we have
	\begin{align*}
	\int_{U_j\times D_j} |ue^{\chi(\phi_\varepsilon)}|^2_{\omega}e^{-\varphi-\chi(\phi_\varepsilon)-\tau(\phi)}dV_{\omega}
	\le I.
	\end{align*}
Since
	\begin{align*}
	|(r+\varepsilon^2)\rho'(r) \hat{f}dw+\chi'(\phi_\varepsilon) u|^2_{\omega}
	\le 2(r+\varepsilon^2)^2|\rho'|^2|\hat{f}|^2+(1+\mathbb{I}_{\supp\rho'(r)})
|\chi'(\phi_\varepsilon)|^2|u|^2_\omega,
	\end{align*}
    	we obtain that
	\begin{align}\label{formula right}
&	\int_{U_j\times D_j} \Big(1- \frac{r(1+\mathbb{I}_{\supp\rho'(r)})|\chi'(\phi_\varepsilon)|^2}
	{r{\chi''(\phi_\varepsilon)}+\chi'(\phi_\varepsilon)\varepsilon^2}\Big)
	|u|^2_\omega e^{\chi(\phi_\varepsilon)-\tau(\phi)-\varphi}dV_{\omega}\\\nonumber
	\le&
	\int_{U_j\times D_j } \frac{2r(r+\varepsilon^2)^2\rho'(r)^2}
	{\chi'(\phi_\varepsilon)\varepsilon^2}|\hat{f}|^2  e^{\chi(\phi_\varepsilon)-\tau(\phi)-\varphi}dV_{\omega}.
	\end{align}

	Let us denote the left-hand side and right-hand side of equation  \eqref{formula right} by $I_1, I_2$ respectively.
	Next we need to control $I_1$ and $I_2$ as $\eps$ goes to $0$.

\vskip0.3cm
\noindent {\bf Step Three: Apply a Lebesgue-type differentiation theorem to control $I_2$.}
\vskip0.5cm	

	Recall that $ \tau(t)=kt,\chi(t)=-\log(-t+\log (-t))$,
	 and
	$\chi'=\frac{1-t^{-1}}{-t+\log(-t)},$
	then ${e^\chi}/\chi'=1/(1-t^{-1})\le 1/2$.
	Since $|\rho'|\le \frac{1+c_\varepsilon
	}{b_\varepsilon-a_\varepsilon}$, we get
\begin{align*}
    I_2
	\le \int_{(U_j\times D_j)\cap\{a_\varepsilon\le r\le b_\varepsilon\}  }
	\frac{2r(r+\varepsilon^2)^2
	}{\varepsilon^2(b_\varepsilon-a_\varepsilon)^2r^{k}  }|\hat{f}|^2 e^{-\varphi}dV_{\omega}.
		\end{align*}

    Take $a_\varepsilon=a\varepsilon^2, b_\varepsilon=b\varepsilon^2$ where $b>a>0$, then it follows immediately that when $a_\eps\le r\le b_\eps$,
	$$
	\frac{2r(r+\varepsilon^2)^2
	}{\varepsilon^2(b_\varepsilon-a_\varepsilon)^2  }
	\le C_1	,
	$$
	since $\phi_\eps=\log(r+\eps^2)\le -1$.

	Thus
\begin{align}\label{111}
	I_2
	\le C_1\int_{(U_j\times D_j)\cap\{a_\varepsilon\le r\le b_\varepsilon\}  }
	\frac{|\hat{f}|^2
	}{r^{k}  }d\lambda_n.
\end{align}

		By \eqref{for basic}, we  obtain that
	\begin{align*}
	\lim_{\varepsilon\to0} \frac{1}{\varepsilon^{2k}}\int_{(U_j\times D_j)\cap\{r\le b\varepsilon^2\}} |\hat{f}|_\omega^2e^{-\varphi}dV_{\omega}
	= \frac{(C_Db\pi)^{k}}{k!}\int_{U_j\times \{z''\}}|f|^2e^{-\varphi(w',z'')}d\lambda_{n-k}.
	\end{align*}
	Together with \eqref{111}, we have
\begin{align}\label{a1}
	\limsup_{\eps\to0}
	I_2	\le C_2\int_{U\times\{z''\}}|f|^2e^{-\varphi(w',z'')}d\lambda_{n-k},
\end{align}
	where  $C_2=\frac{C_1(C_Db\pi)^{k}}{k!a^k}$.

\vskip0.3cm
\noindent {\bf Step Four: Direct computation for estimating $I_1$.}
\vskip0.5cm	
    When $\mathbb{I}_{\supp\rho'(r)}=0$, we have {\small	
	\begin{align*}
	\Big(1-(1+\mathbb{I}_{\supp\rho'(r)}) \frac{r|\chi'(\phi_\eps)|^2}
	{r{\chi''(\phi_\eps)}+\chi'(\phi_\eps)\eps^2}\Big)
	e^{\chi(\phi_\eps)}
	&\ge\Big(1- \frac{|\chi'(\phi_\eps)|^2}
	{{\chi''(\phi_\eps)}}\Big)
	e^{\chi(\phi_\eps)}
	\ge C_3 (-\phi_\eps)^{-2}
	\end{align*}}
	for some positive constant $C_3$ independent of $\eps$ since $-\phi_\eps=-\log(r+\eps^2)\ge 1$.

    When $\mathbb{I}_{\supp\rho'(r)}=1$, we have $a\eps^2\le r \le b\eps^2$. Since $$-\log({(b+1)\eps^2})\le -\phi_\eps\le -\log({(a+1)\eps^2})$$ for $\eps$ small enough, we get that
    $
    \chi'(\phi_\eps)=\frac{1-\phi_\eps^{-1}}{-\phi_\eps+\log(-\phi_\eps)} \thicksim\frac{1}{-\phi_\eps}$ and $e^{\chi(\phi_\eps)}=\frac{1}{-\phi_\eps+\log(-\phi_\eps)}\thicksim\frac{1}{-\phi_\eps}$.
    Therefore,
    \begin{align*}
	\Big(1- \frac{2r|\chi'(\phi_\eps)|^2}
	{r{\chi''(\phi_\eps)}+\chi'(\phi_\eps)\eps^2}\Big)
	e^{\chi(\phi_\eps)}
	\ge & \Big(1- \frac{2r|\chi'(\phi_\eps)|^2}
	{\chi'(\phi_\eps)\eps^2}\Big)
	e^{\chi(\phi_\eps)}
	\ge  C_4(- \phi_\eps)^{-2}
	\end{align*}
	for some positive constant $C_4$ independent of $\eps$.

    Thus for $\varepsilon>0$ small enough, the LHS of \eqref{formula right}
	\begin{align}
	I_1
	\ge
	C_5\int_{U_j\times D_j}
	\frac{|u|^2_\omega e^{-\varphi}}{r^k (\log({r+\eps^2}))^2}dV_{\omega}.
	\end{align}

	Combining this with \eqref{formula right} and \eqref{a1}, we obtain for $\varepsilon>0$ small enough
	\begin{align}\label{form C_6}
	\int_{U_j\times D_j}
	\frac{|u|^2_\omega e^{-\varphi}}{r^k (\log({r+\eps^2}))^2}dV_{\omega}
	\le
	C_6
	\int_{U\times\{z''\}} |f|^2e^{-\varphi} d\lambda_{n-k}.
	\end{align}
\vskip0.3cm
\noindent {\bf Step Five: Construct a holomorphic extension with the demanded estimate. }
\vskip0.5cm	

    Since $\dbar u=\hat{f}dw\wedge  \dbar \rho(r)=0$ in $\{r< a_\varepsilon\}\cap U_j\times D_j$,  $u$ is holomorphic near $ U_j\times \{z''\}$.
	 Since $r^{-k}$ is not integrable near $U\times\{z''\}$, combining  \eqref{form C_6}, we get that $u|_{ U_j\times \{z''\}}=0$.
	Let $F_{\varepsilon,j}=\hat{f}\rho(r)-\frac{u}{dw}$ on $U_j\times D_j$, then $\dbar F_{\varepsilon,j}=0$ and $F_{\varepsilon,j}=f$ on $  U_j\times \{z''\}$. We obtain
    that
\begin{align*}
	&\int_{U_j\times D_j}
	|F_{\varepsilon,j}|^2e^{-\varphi} d\lambda_n\\
	\le&
	2\int_{U_j\times D_j}
	|\hat{f}\rho(r)|^2e^{-\varphi}dV_{\omega}
	+2C_7\int_{U_j\times D_j}
	\frac{|u|^2_\omega e^{-\varphi}}{r^k (\log({r+\eps^2}))^2}dV_{\omega},
\end{align*}	
	where $C_7=\sup_{0\le r<e^{-1}} r^k(\log r)^2$.

	Hence $\{F_{\varepsilon,j}\}_\eps$ is  bounded on $L^2(U_j\times D_j)$ for each fixed $j$ by (\ref{form C_6}).
	Using Montel's theorem we can choose a subsequence $F_{\varepsilon_k,j}$ compactly converging to a holomorphic function $F_j$ on $U_j\times D_j$.
In addition, we have
\begin{align}\label{ineq restricted}
	&\int_{(U_j\times D_j)\cap\{r\ge a_\eps\}}
	\frac{|F_{\varepsilon,j}|^2e^{-\varphi}}{r^k (\log{r})^2}dV_{\omega}\nonumber	\\
    \le& 2\int_{(U_j\times D_j)\cap\{r\ge a_\eps\}}
    \frac{|\hat{f}\rho(r)|^2e^{-\varphi}}{r^k (\log{r})^2}dV_{\omega}+2\int_{U_j\times D_j}
	\frac{|u|^2_\omega e^{-\varphi}}{r^k (\log{r})^2}dV_{\omega}\nonumber\\  \le&
    2\int_{(U_j\times D_j)\cap\{r\ge a_\eps\}}
    \frac{|\hat{f}\rho(r)|^2e^{-\varphi}}{r^k (\log({r+\eps^2}))^2}dV_{\omega}
    + C_8\int_{U\times\{z''\}} |f|^2e^{-\varphi} d\lambda_{n-k}.
\end{align}

By \eqref{for basic}, we have
\begin{align*}
 &\lim_{\eps\to0}\int_{U_j\times D_j\cap\{r\ge a_\eps\}}
	\frac{|\hat{f}\rho(r)|^2e^{-\varphi}}{r^k (\log({r+\eps^2}))^2}dV_{\omega}\\
 \le & \limsup_{\eps\to0}
	\frac{1}{(\log({b\eps^2+\eps^2}))^2}\int_{(U_j\times D_j)\cap\{ a_\eps\le r\le b_\eps\}}
	\frac{|\hat{f}|^2e^{-\varphi}}{r^k}dV_{\omega}\\
\le & \limsup_{\eps\to0}
	\frac{1}{(\log({b\eps^2+\eps^2}))^2}\cdot \frac{C_D^{k}}{a^k\eps^k}\int_{(U_j\times D_j)\cap\{ r\le b_\eps\}}
	|\hat{f}|^2e^{-\varphi}dV_{\omega}=0.
\end{align*}

Let $\eps$ goes to $0$ in \eqref{ineq restricted}, then by Fatou's lemma, we obtain that

\begin{align*}
	\int_{U_j\times D_j}
	\frac{|F_{j}|^2e^{-\varphi}}{r^k (\log{r})^2}dV_{\omega}	
	\le
	C_8\int_{U\times\{z''\}} |f|^2e^{-\varphi} d\lambda_{n-k}.
\end{align*}

	By a standard limitation argument via Montel's theorem again,  there is a subsequence of$\{F_j\}$ compactly converging to an $F\in \calO(U\times D)$ such that $F|_{U\times\{z''\}}=f$ and
\begin{align*}
	\int_{U\times D}
	\frac{|F|^2e^{-\varphi}}{r^k (\log{r})^2}dV_{\omega}	
	\le
	C_8\int_{U\times\{z''\}} |f|^2e^{-\varphi} d\lambda_{n-k}.
\end{align*}

 Noticing that $dV_{\omega}=d\lambda_n$ and $r=C_D^{-1}|w''-z''|^2$, we complete the proof.



\end{proof}



\section{Applications}\label{Sec:Appl}

\subsection{A characterization of plurisubharmonic functions}

Recall some notations and results in \cite{DNW21}.  A \textit{holomorphic cylinder} in $\mathbb{C}^n$ is a domain of the form $P_{A,r,s}:=A(\mathbb{D}_r\times\mathbb{B}_s^{n-1})$, where $A\in \textbf{U}(n)$ is unitary and $r,s>0$.
It is well-known that plurisubharmonic functions satisfy the mean value inequality on holomorphic cylinders. Conversely, this property characterizes all plurisubharmonic  functions.

\begin{lemma}[{\cite[Lemma 3.1]{DNW21}}] \label{Lemma:CharPsh}
Let $\varphi$ be an upper semi-continuous function on a domain $D\subset\mathbb{C}^n$, then $\varphi$ is plurisubharmonic  if and only if
\begin{equation*}
	\varphi(z) \le \frac{1}{\lambda_n(P)} \int_{z+P}\varphi d\lambda_n
\end{equation*}
 for any $z\in D$ and any holomorphic cylinder $z+P\Subset D$.
\end{lemma}

Notice that any plurisubharmonic function is strongly upper semi-continuous. Moreover, a strongly upper semi-continuous function is plurisubharmonic if and only if it agrees almost everywhere with a plurisubharmonic function. This leads to the following variant of Lemma \ref{Lemma:CharPsh}:

\begin{lemma}\label{lem susc charpsh}
  Let $\varphi$ be  a strongly upper semi-continuous function on a domain $D\subset\CC^n$. Assume that for almost every $z\in D$ and any holomorphic cylinder $z+P\Subset D$,
  \begin{equation}\label{for mean ineq}
	\varphi(z) \le \frac{1}{\lambda_n(P)} \int_{z+P}\varphi d\lambda_n.
\end{equation}
\end{lemma}
\begin{proof}
  Since $\varphi$ is bounded from above, together with \eqref{for mean ineq}, we know that $\varphi\in L^{1}(D;\loc)$.  For any $z\in D$ and any holomorphic cylinder $z+P\subset D$, we can choose $z_j\in D$ such that  $z_j+P\Subset D$, $\lim_{j\to +\infty}\varphi(z_j)=\varphi(z)$ and \begin{equation*}
	\varphi(z_j) \le \frac{1}{\lambda_n(P)} \int_{z_j+P}\varphi d\lambda_n.
\end{equation*}
Then by the absolute continuity property of the Lebesgue integral, we conclude that \begin{align*}
       \varphi(z)=  \lim_{j\to +\infty}\varphi(z_j)
       \le \lim_{j\to +\infty}\frac{1}{\lambda_n(P)} \int_{z_j+P}\varphi d\lambda_n
       \le  \frac{1}{\lambda_n(P)} \int_{z+P}\varphi d\lambda_n.
     \end{align*}
Hence $\varphi$ is plurisubharmonic by Lemma \ref{Lemma:CharPsh}.
\end{proof}

\begin{remark}
 Indeed, if we assume that $\varphi$ is only upper semi-continuous, then by employing convolution techniques, one can verify that the regularized functions $\varphi_\varepsilon$ satisfy the mean-value inequality \eqref{for mean ineq} for almost every $z\in D_\eps:=\{z\in D;{\rm dist}(z,\partial D)\}$. By continuity of $\varphi_\varepsilon$, this inequality in fact holds for every $z \in D_\varepsilon$. It follows from Lemma \ref{Lemma:CharPsh} that $\varphi_\eps$ is plurisubharmonic, which means that $i\ddbar \varphi_\eps\ge 0$ in the sense of currents. Since $\varphi_\eps$ converges to $\varphi$ in $L^1(D;\loc)$, then we know that  $i\ddbar \varphi\ge 0$ as a current. Therefore, $\varphi$ agrees almost everywhere with a plurisubharmonic function.
\end{remark}

\begin{definition}[\cite{DNW21}]\label{def DNW}
  Let   $\varphi$ be  an upper semi-continuous function on  a domain $D\subset \CC^n$.
  \begin{enumerate}
    \item We say that $\varphi$  satisfies the \textit{multiple coarse $L^2$-estimate property} if for any Stein coordinates $U\subset D$, for any smooth strictly plurisubharmonic function $\phi$ and
   any K\"{a}hler metric $\omega$ on $U$,
   the equation $\dbar u=f$ can be solved on $U$ for any $\dbar$-closed  $(n,1)$-form
   $f \in L^2_{(n,1)}(U; \loc)$
   with the estimate:
   \begin{equation*}
   \int_U|u|^2_{\omega} e^{-\varphi-\phi} dV_\omega
   \leq
   C_m\int_U \inner{B_{\omega,\phi}^{-1}f,f}_{\omega} e^{-m\varphi-\phi} dV_{\omega},
  \end{equation*}
   provided that the right-hand side is finite, where  $C_m$'s are constants such that $\lim_{m\to+\infty}\frac{\log C_m}{m}=0$.
   \item We say that $\varphi$  satisfies the \textit{multiple coarse $L^2$-extension property} if for any $z\in D$ with $\varphi(z)>-\infty$, and any holomorphic cylinder $z+P\Subset D$, there is a holomorphic function $f\in\calO(z+P)$ such that $f(z)=1$    with the estimate:
   \begin{equation*}
  \int_{z+P}|f|^2e^{-m\varphi} d\lambda_n
   \leq
   C_m e^{-m\varphi(z)},
  \end{equation*}
    where   $C_m$'s are constants such that $\lim_{m\to+\infty}\frac{\log C_m}{m}=0$.
  \end{enumerate}
\end{definition}
Deng-Ning-Wang  gave the following characterizations of plurisubharmonic functions via the above $L^2$ conditions.
\begin{theorem}[\cite{DNW21}]\label{thm DNW}
 Let   $\varphi$ be  an upper semi-continuous function on  a domain $D\subset \CC^n$,
  \begin{enumerate}
    \item If $\varphi$ satisfies the multiple coarse $L^2$-extension property, then $\varphi$ is plurisubharmonic.
    \item If $\varphi$ is continuous and satisfies the multiple coarse $L^2$-estimate property, then $\varphi$ satisfies the multiple coarse $L^2$-extension property and hence is plurisubharmonic.
  \end{enumerate}
\end{theorem}

   As an application of the single-point case in Theorem \ref{Thm:OT ext}, we can relax the continuity requirement in Theorem \ref{thm DNW}-(2) to strong upper semi-continuity - the minimal regularity condition necessary for plurisubharmonicity.

\begin{theorem}[=Theorem \ref{thm DNW mod}]
   A measurable function $\varphi:D\subset\CC^n\to [-\infty,+\infty)$ is plurisubharmonic if and only if
   $\varphi$ is strongly upper semi-continuous and satisfies the multiple coarse $L^2$-estimate property.
\end{theorem}
\begin{proof}
  It suffices to prove the ``if" part. Since  $\varphi$   satisfies the multiple coarse $L^2$-estimate property, by Theorem \ref{Thm:OT ext}, there is a full-measure subset $A$ of $D$ such that for any $z\in A$,  and any holomorphic cylinder $z+P\subset D$, there is a holomorphic function $f\in\calO(z+P)$ such that $f(z)=1$    with the estimate:
   \begin{equation*}
    \int_{z+P}|f|^2e^{-m\varphi} d\lambda_n
   \leq
   C e^{-m\varphi(z)},
  \end{equation*}
    where   $C$ is a constant only depending on $n$ and ${\rm diam} P$.
  Then we have $$\varphi(z)\le \frac{\log C}{m}-\frac{\lambda_n(P)}{m}-\frac{1}{m}\log\left(\frac{1}{\lambda_n(P)}\int_{z+P}|f|^2e^{-m\varphi} d\lambda_n\right).$$
    Use Jensen's inequality and let $m\to +\infty$, then we get
    \begin{align*}\varphi(z)&\le \lim_{m\to+\infty}-\frac{1}{m}\cdot\frac{1}{\lambda_n(P)}\int_{z+P}\log(|f|^2e^{-m\varphi}) d\lambda_n\\
    &\le \frac{1}{\lambda_n(P)}\int_{z+P}\varphi d\lambda_n+\lim_{m\to+\infty}-\frac{1}{m}\cdot\frac{1}{\lambda_n(P)}\int_{z+P}\log|f|^2 d\lambda_n\\
    &\le \frac{1}{\lambda_n(P)}\int_{z+P}\varphi d\lambda_n+\lim_{m\to+\infty}-\frac{\log|f(z)|^2 }{m}\\
    &\le \frac{1}{\lambda_n(P)}\int_{z+P}\varphi d\lambda_n
    \end{align*}
    where the third inequality follows from the plurisubharmonicity of $\log|f|^2$.

    Since $\varphi$ is strongly upper semi-continuous, by Lemma \ref{lem susc charpsh}, we obtain that $\varphi$ is plurisubharmonic.
\end{proof}


\subsection{Skoda's integrability theroem}
As another application of single-point case in Theorem \ref{Thm:OT ext},  following the language of \cite[Theorem 9.17, Corollary 9.18]{Boucksom L2note}, we can obtain Skoda's integrability theorem for strongly upper semi-continuous  $L^2$-optimal functions.

\begin{theorem}[=Theorem \ref{thm Skoda}]
  Let $\varphi$ be a strongly upper semi-continuous  $L^2$-optimal function on a domain $D\subset\CC^n$. Assume that $\calI(\varphi)\not\equiv 0$. If $\nu(\varphi,x)<2$ for some $x\in D$, then $\calI(\varphi)_x=\calO_x$.
\end{theorem}

\begin{proof}
Let $U\Subset D$ be a Stein neighbourhood of $x$.
since $\varphi$ is $L^2$-optimal and $\calI(\varphi)\not\equiv 0$, we know that the Bergman space $\calH^2(U, \varphi)\neq0$.  Let $(\sigma_j)$ be a complete orthonormal basis of $\calH^2(U,\varphi)$. Consider the linear continuous functional ${\rm{ev}}_z(f):f\mapsto f(z)$ on $\calH^2(U,\varphi)$. By the Riesz representation theorem, we have $$\sup_{\|f\|=1}|f(z)|^2=\sum _{j=1}^{+\infty} |\sigma_j(z)|^2.$$ Since $\varphi$ is locally bounded from above, the $L^2$ topology is actually stronger than the topology of uniform convergence on compact subsets of $U$. It follows that the series $\sum|\sigma_j|^2$ converges uniformly on compact subsets of $U$ and that its sum is real analytic. Moreover,  we know that there is a neighbourhood $ V\subset U$ of $x$ and $j_0,C_0>0$ such that
$\sum_{j=1}^{+\infty} |\sigma_j(z)|^2\le C_0\sum_{j=1}^{j_0} |\sigma_j(z)|^2$ on $V$. Then we have $$\nu(\log\sum_{j=1}^{+\infty} |\sigma_j(z)|^2, x)=\nu(\log\sum_{j=1}^{j_0} |\sigma_j(z)|^2,x)=\min_{1\le j\le j_0}\{2{\rm{ord}}_x \sigma_j\}.$$
 In particular, the  Lelong number of $\log\sum_{j=1}^{+\infty} |\sigma_j(z)|^2$ at $x$ is an even integer.

  In addition, by Theorem \ref{Thm:OT ext}, for almost every $z\in U$, there is a holomorphic function $F\in H^0(U,\varphi)$ such that $$\int_U|f|^2e^{-\varphi}d\lambda_n\le C|f(z)|^2e^{-\varphi(z)}.$$
  Since  $\calI(\varphi)\not\equiv 0$, it follows from Remark \ref{rmk coherent} that $\varphi>-\infty$ almost everywhere. Hence for almost every $z\in U$, we can take $f(z)=C^{-\frac{1}{2}}e^{\frac{1}{2}\varphi(z)}$, then $\|f\|\le1$. Since  $\varphi$ is strongly upper semi-continuous, we have
  $$\log\sup_{\|f\|=1}|f(z)|^2\ge \varphi -\log C.$$
  Hence $$\nu(\log(\sum_{j=1}^{+\infty} |\sigma_j(z)|^2), x)=\nu(\log\sup_{\|f\|=1}|f(z)|^2,z)\le\nu(\varphi,z).$$

  Now $\nu(\varphi,x)<2$, then $\min_{1\le j\le j_0}\{2{\rm{ord}}_x \sigma_j\}=0$, which means that there is a $\sigma_j\in H^0(U,\varphi)$ with $\sigma_j(x)\neq0$ for some $1\le j\le j_0$. Therefore, $\calI(\varphi)_x=\calO_x$.
\end{proof}



\subsection{Strong openness property}

In this section, we prove the strong openness property of  multiplier ideal sheaves by modifying  Guan-Zhou's proof \cite{GZsoc} of Demailly's strong openness conjecture and follows Lempert's language \cite{Lempert17}.

\begin{theorem}[=Theorem \ref{thm SOC}]
  Let $\varphi$ be an upper semi-continuous and $L^2$-optimal function on a domain $D\subset\CC^n$. Let $\{\varphi_j\}_{j\ge1}$ be upper semi-continuous  and $L^2$-optimal functions  increasingly converging to $\varphi$ on $D$. Assume that $\calI(\varphi_1)\not\equiv 0$. Then $\calI(\varphi)=\bigcup_j\calI(\varphi_j)$.
\end{theorem}
\begin{proof}

Let $H\subset \CC^n$ be a complex hyperplane, $W\subset H\cap D$  relatively open and $f$ a measurable function on $W$. Define \begin{align*}
\|f\|^2=\inf_j \int_W |f|^2e^{-\varphi_j}d\lambda_{n-1}\in [0,+\infty]
\end{align*}
 Then we have
\begin{lemma}[{\cite[Lemma 2.1]{Lempert17}}]\label{lem lempert}
The germ $f_0\in \calO_0$ belongs to $\bigcup_j \calI(\varphi_j)_0$ if and only if for any $\DD^{n}_{0}(r)$ with $r$ small enough and hyperplanes $H_k:=\{z\in\CC^n; z_k=0\}$ for $1\le k\le n$, there is a subset $S\subset \DD_0^1(r)$ of full measure such that
	\begin{align*}
	\underset{ S\ni\xi\to0}{\liminf}~~ |\xi| \cdot\|f|_{V\cap H_{k,\xi}}\|=0,
	\end{align*}
	where $H_{k,\xi}:=\{z\in\CC^n; z_k =\xi\}$.	
\end{lemma}	
\begin{remark}
  Here we present two minor modifications to Lempert's original formulation. First, we allow for the presence of a zero-measure set $S$, since  such sets do not affect integration when we use Fubini's theorem. Second, it suffices to consider only the $n$ hyperplanes $H_k(1\le k\le n)$, as Lempert's proof requires only that for any analytic disc through the $0$, there exists at least one hyperplane not containing it.
\end{remark}

Since strong openness property is local, it is sufficient to show that  $\calI(\varphi)_0=\bigcup_{j=1}^{+\infty}\calE(h_j)_0$.
We  prove the theorem by induction on $n=\dim D$.
It  is obvious for  the case $n=0$.
Assume the statement is right for $n-1$, then consider the $n$-dimensional case.

By Lemma \ref{lem soc mod} and Lemma \ref{lem modification} , shrinking $D$ if necessary, we may assume that $D=\DD^{n}_{0}(r_0)$ and $\supp(\calO/\calI(e^{-\varphi_1}))$ is contained in $\{z_1\cdot\cdots\cdot z_n=0\}$.
To apply the induction hypothesis we have to verify whether the restrictions $\varphi_j|_{D\cap H_{k,\xi}}$ for each $1\le k\le n$, any $j\in\ZZ_+$ and almost every $\xi\in\CC$ is upper semi-continuous and $L^2$-optimal. Owing to Lemma \ref{pro nak res nak}, it is true.

If $f\in \calI(\varphi)_0$,  then for any $\DD^{n}_{0}(r)$ with $r$ small enough,  $\int_{\DD^{n}_{0}(r) } |f|^2e^{-\varphi}d\lambda_{n}<+\infty$.
Then Fubini's theorem guarantees that there is  $S\subset\DD^1_0(r)$ of full measure such that
$$\int_{\DD^{n}_{0}(r)\cap H_{k,\xi}} |f|^2e^{-\varphi}d\lambda_{n-1}<+\infty\quad
 \text{ for }~ \xi\in S,$$
and 
\begin{equation}\label{ccc}
\liminf_{S\ni \xi\to 0} |\xi|^2 \int_{\DD^{n}_{0}(r)\cap H_{k,\xi}} |f|^2e^{-\varphi}d\lambda_{n-1}=0.
\end{equation}
The induction hypothesis implies that for each $\xi\in S$ there is a $j_\xi$ such that $\int_{\DD^{n}_{0}(r)\cap H_{k,\xi}} |f|^2e^{-\varphi_{j_\xi}}d\lambda_{n-1}<+\infty$,
and by the monotone convergence theorem we have
$$\| f|_{\DD^{n}_{0}(r)\cap H_{k,\xi}}\|^2=\int_{\DD^{n}_{0}(r)\cap H_{k,\xi}} |f|^2e^{-\varphi}d\lambda_{n-1}.$$
 It follows from  \eqref{ccc}  that
 \begin{equation}
\liminf_{S\ni \xi\to 0} |\xi|\cdot\| f|_{\DD^{n}_{0}(r)\cap H_{k,\xi}}\|=0.
\end{equation}
 Then by Lemma \ref{lem lempert}, $f_0\in \bigcup_j\calI(\varphi_j)_0$ indeed.
\end{proof}




